-- Sources: data/i18n/itIT. Lore text adapted from warcraft.wiki.gg (CC BY-SA 4.0); the core add-on's src fields name the articles.
local P = LoreForeverPacks.Begin("LoreForever_Lang_itIT")
P.entries["quest:1802"] = {n="Tomo della Cabala",s="Da Forgiardente, la tua ricerca del Tome of the Cabal conduce a un manoscritto perduto e a una nave affondata. Le sue pagine sparse custodiscono i riti per vincolare un mastino demoniaco.",h="Da Forgiardente, la tua ricerca del Tome of the Cabal conduce a un manoscritto perduto e a una nave affondata.",kw={"miniera di venazzurra","mastino demoniaco","forgiardente","krom braccioforte","tomo ammuffito","covo di zoccolo spezzato","strahad farsan","manoscritto cencioso","tome of the cabal"},ang={["class:Warlock"]="Per te, come stregone, recuperare le metà strappate del grimorio rappresenta un rito di passaggio. Le sue pagine custodiscono i riti di evocazione necessari per richiamare un mastino demoniaco dal Nether e renderlo schiavo.",["faction:Alliance"]="Come adepto dell'Alleanza, puoi contare sui contatti di Forgiardente, come Krom Braccioforte, per rintracciare rare reliquie demoniache attraverso i continenti senza destare aperti sospetti nella chiesa o nella corona."},sec={{t="Un Grimorio Diviso",b="Del Tome of the Cabal fu scritta una sola copia. La violenza lo fece a pezzi e ne deturpò le pagine, disperdendone i resti in angoli remoti del mondo. Un manoscritto cencioso attraversò il mare fino a Kalimdor, dove se ne impadronirono i clan dei centauri. L'altra metà salpò da Lordaeron verso Khaz Modan, ma la nave affondò prima di raggiungere il porto."},{t="Oltre il Mare e il Canyon",b="Due pericoli custodiscono le pagine mancanti. Quelle perdute in mare furono trascinate a riva sulla costa di Colletorto, a ovest di Riva del Sud. I murloc della costa vicino alla Miniera di Venazzurra si impadronirono delle reliquie impregnate d'acqua e dei rottami. La metà asciutta riposa in un antico forziere nelle profondità delle caverne dei centauri del Covo di Zoccolo Spezzato, a Millepicchi. Una volta riuniti i frammenti, Krom Braccioforte potrà esaminare il testo perduto prima che torni a Strahad Farsan."}},faq={{q="Che cos'è il Tome of the Cabal?",a="Il Tome of the Cabal è un raro grimorio demoniaco e ne esiste una sola copia. Il suo sapere arcano custodisce gli incantesimi e i riti di vincolo necessari agli stregoni per evocare e soggiogare un mastino demoniaco dalla Distorsione Fatua.",al={"storia del tome of the cabal","cos'è questo libro","tome cabal"}},{q="Chi è Krom Braccioforte e perché vuole il tomo?",a="Krom Braccioforte è un nano di Forgiardente che studia testi rari e dimenticati. Indica agli stregoni dell'Alleanza dove sono finiti i frammenti del tomo, chiedendo soltanto di poterli studiare una volta recuperati.",al={"chi è krom braccioforte","perché krom vuole il libro","krom braccioforte forgiardente"}},{q="Dove sono finiti i due pezzi del libro?",a="Il Tomo Ammuffito fu trascinato sulla costa di Colletorto, a ovest di Riva del Sud vicino alla Miniera di Venazzurra, dove i murloc costieri lo raccolsero. Il Manoscritto Cencioso si trova in un forziere malridotto nelle profondità di una caverna dei centauri al Covo di Zoccolo Spezzato, a Millepicchi, su Kalimdor.",al={"dove sono i pezzi del tomo","posizioni dei libri","posizione manoscritto cencioso"}},{q="Perché il tomo è stato strappato?",a="Del Tome of the Cabal fu trascritta una sola copia. Nel suo oscuro passato, qualcuno lo deturpò deliberatamente, strappò un'ampia sezione dalla rilegatura e la portò a Kalimdor. Il resto andò perduto in mare durante un viaggio verso Porto di Menethil.",al={"perché il libro è stato strappato","chi ha vandalizzato il tomo"}},{q="Chi è Strahad Farsan e cosa c'entra con questa missione?",a="Strahad Farsan è uno stregone esperto che vive vicino a Porto Paranco, nelle Savane. Incarica gli aspiranti evocatori di recuperare il tomo e apprendere sotto la sua guida i riti per evocare e vincolare un mastino demoniaco.",al={"chi è strahad","strahad farsan","collegamento con strahad"}},{q="Perché il Tomo Ammuffito è coperto di melma marina?",a="Il Tomo Ammuffito era a bordo di una nave diretta dalla costa di Lordaeron a Porto di Menethil, ma la nave non arrivò mai. Il relitto andò alla deriva vicino alla costa di Colletorto, dove i murloc costieri presso la Miniera di Venazzurra raccolsero le pagine umide e ammuffite.",al={"perché il tomo ammuffito è bagnato","tomo colletorto murloc"}}},fx={["7c4e226c"]={q="Che cos'è il Tomo Ammuffito?",a="Il Tomo Ammuffito è ciò che resta, impregnato d'acqua, della parte principale del Tome of the Cabal. Andò perduto in mare al largo delle Alture di Colletorto, quando affondò una nave diretta a Porto di Menethil. Recuperarlo permette di ritrovare il nucleo degli insegnamenti sinistri del grimorio.",al={"tomo ammuffito","che cos'è il tomo ammuffito","perché trovare il tomo ammuffito"}},aa350fa4={q="Che cos'è il Manoscritto Cencioso?",a="Il Manoscritto Cencioso è la sezione strappata dal Tome of the Cabal originale prima che il libro andasse perduto. Trasportato molto lontano attraverso il mare, finì nelle mani dei centauri Galak di Millepicchi e contiene i riti mancanti necessari a ricomporre il testo completo.",al={"manoscritto cencioso","che cos'è il manoscritto cencioso","manoscritto dei centauri"}}},fp="17,155,18.334.0,21.405.0,30.210.0,51.185.0,44.251.0,47.236.0,66.207.0,43.231.0"}
P.entries["quest:1803"] = {n="Tomo della Cabala",s="A Sepulcra, gli stregoni dell'Orda cercano le metà disperse del Tome of the Cabal per Jorah Annison. Un tempo custodito a Lordaeron, il grimorio fu fatto a pezzi, e i suoi resti giacciono lungo le acque ostili dei Regni Orientali e nel cuore delle terre dei centauri di Kalimdor.",h="A Sepulcra, gli stregoni dell'Orda cercano le metà disperse del Tome of the Cabal per Jorah Annison.",kw={"galak","jorah annison","lordaeron","tomo ammuffito","riva del sud","covo di zoccolo spezzato","manoscritto cencioso","millepicchi","tome of the cabal","missione stregone"},ang={["class:Warlock"]="Come stregone, recuperi il Tome of the Cabal come rito di passaggio per un praticante di livello intermedio. I suoi perduti segreti arcani di Lordaeron possono ampliare il tuo repertorio di evocazioni.",["faction:Horde"]="Come membro dell'Orda, segui le tracce del manoscritto tra i canyon di Millepicchi. Le forze dell'Orda al Presidio di Ventolibero sono in guerra costante contro i centauri nativi.",["race:Undead"]="Come non morto, recuperi un tomo custodito a Lordaeron prima della caduta del regno. Il suo ritorno ti restituisce un retaggio occulto delle tue precedenti vite umane."},sec={{t="Un'eredità divisa",b="Il Tome of the Cabal era un tempo custodito nella biblioteca di Lordaeron. Qualcuno deturpò il sinistro grimorio, strappò quasi metà delle sue pagine e lo divise in due. Il testo rilegato superstite fu inviato alle sale naniche di Forgiardente. Ma l'imbarcazione che lo trasportava naufragò lungo la costa rocciosa a ovest di Riva del Sud, e ora le pagine marciscono nei bassifondi, sotto i murloc in cerca di cibo."},{t="Sparsi tra i continenti",b="L'altra metà viaggiò da Lordaeron fino al sud di Kalimdor. Nelle profondità del Covo di Zoccolo Spezzato, a Millepicchi, i centauri Galak custodiscono il manoscritto senza alcuna cura. Setacci l'umido litorale di Colletorto in cerca del Tomo Ammuffito, poi ti addentri nei canyon polverosi e selvaggi dei centauri per recuperare il Manoscritto Cencioso. Quando entrambi i resti giungono a Jorah Annison, il leggendario testo oscuro torna integro e leggibile."}},faq={{q="Che cos'è il Tome of the Cabal?",a="Il Tome of the Cabal è un grimorio arcano di rituali demoniaci un tempo custodito nella capitale di Lordaeron. Qualcuno lo deturpò e lo divise in due prima che andasse perduto tra due continenti.",al={"storia del tome of the cabal","cos'è questo libro","tome of the cabal"}},{q="Perché una parte del libro si trova vicino a Riva del Sud?",a="Dopo che il tomo fu vandalizzato, la parte rilegata superstite era destinata agli studiosi di Forgiardente. L'imbarcazione naufragò sulla costa a ovest di Riva del Sud, lasciando il libro abbandonato tra i murloc del luogo.",al={"perché riva del sud","origine tomo ammuffito","costa a ovest di riva del sud"}},{q="Come sono finite le pagine in mano ai centauri a Millepicchi?",a="Circa metà delle pagine furono strappate dal tomo originale a Lordaeron e portate via di nascosto. Tra commerci, saccheggi o mani di viandanti, il Manoscritto Cencioso finì nelle profondità del Covo di Zoccolo Spezzato, dove i centauri Galak lo custodiscono in un forziere.",al={"perché i centauri lo hanno","pagine di millepicchi","libro al covo di zoccolo spezzato"}},{q="Chi è Jorah Annison?",a="Jorah Annison è uno stregone dei Reietti nel Magic Quarter di Sepulcra. Guida gli stregoni dell'Orda in ascesa mentre recuperano conoscenze dimenticate e proibite e approfondiscono il loro dominio sulle forze demoniache.",al={"storia jorah annison","chi è jorah"}},{q="Chi ha vandalizzato il tomo, in origine?",a="Chi abbia vandalizzato il tomo resta ignoto. Jorah Annison deplora i danni e si chiede chi possa compiere un simile atto contro un testo dal potere occulto così grande.",al={"chi ha strappato il libro","chi ha rubato le pagine","vandalo del tomo"}},{q="Cosa fa Jorah con il libro una volta che riporti entrambe le parti?",a="Quando gli porti sia il Tomo Ammuffito sia il Manoscritto Cencioso, Jorah Annison li riunisce in un unico volume e ne legge le pagine. Ti prepara alle fasi successive dei tuoi riti demoniaci.",al={"cosa succede dopo la consegna","tomo restaurato"}}},fx={a3cceb5d={q="Perché Jorah Annison vuole il Tome of the Cabal?",a="Jorah Annison è uno studioso stregone Reietto, dedito a riportare alla luce le conoscenze demoniache perdute un tempo custodite a Lordaeron. Recuperare il Tome of the Cabal frammentato gli permette di studiarne direttamente i segreti occulti e di guidare gli stregoni promettenti nell'apprendimento di evocazioni pericolose e avanzate.",al={"perché jorah vuole questo","motivo di jorah annison","perché raccogliere il tome of the cabal"}},["968099ef"]={q="Che cos'è il Tomo Ammuffito?",a="Il Tomo Ammuffito contiene i resti recuperati del testo originale, destinato a essere trasferito a Forgiardente. Perduto in un naufragio lungo la costa vicino a Riva del Sud e saccheggiato dai murloc, custodisce una metà essenziale dei rituali della Cabala.",al={"che cos'è il tomo ammuffito","storia del tomo ammuffito","a cosa serve il tomo ammuffito"}},["2b99c3ce"]={q="Che cos'è il Manoscritto Cencioso?",a="Il Manoscritto Cencioso è la metà mancante del Tome of the Cabal, strappata quando il libro fu vandalizzato a Lordaeron. Passando per mani sconosciute, le pagine rubate attraversarono il mare fino a Kalimdor e finirono infine chiuse in un forziere tra i centauri Galak di Millepicchi.",al={"che cos'è il manoscritto cencioso","storia del manoscritto cencioso","a cosa serve il manoscritto cencioso"}}},fp="17,258,16.353.0,27.374.1,30.177.0,44.194.0,62.240.0,21.187.0,43.151.0,64.187.0"}
P.entries["quest:1804"] = {n="Tomo della Cabala",s="Nelle Savane, Strahad Farsan attende il tomo e le verghe necessari per vincolare un mastino villoso. Lo stregone glieli porta perché il suo circolo possa preparare il rito.",h="Nelle Savane, Strahad Farsan attende il tomo e le verghe necessari per vincolare un mastino villoso.",kw={"savane","fauce del drago","mastino villoso","krom braccioforte","porto paranco","verghe di canalizzazione","strahad farsan","tome of the cabal","paludi grigie"},ang={["class:Warlock"]="Come stregone, soggiogare un mastino villoso segna il tuo passaggio dai patti con diavoletti e abissali al dominio su demoni predatori creati per divorare la magia arcana.",["faction:Alliance"]="Come evocatore dell'Alleanza, viaggi tra Forgiardente, gli acquitrini nebbiosi delle Paludi Grigie e Porto Paranco, il porto neutrale dei goblin a Kalimdor.",["race:Dwarf"]="Come nano, conosci il valore di un'attenta conservazione. Nel Salone degli Esploratori di Forgiardente, Krom Braccioforte ricompone reliquie in rovina."},sec={{t="Una consegna riluttante",b="Krom Braccioforte rilega i resti laceri del Tome of the Cabal nel Salone degli Esploratori di Forgiardente. Lo studioso nano si separa a malincuore dalla rara opera, dopo essersi assicurato la promessa di una copia. Consegna inoltre allo stregone una nuova missiva di Strahad Farsan. Il tomo contiene riti per aprire un varco nell'Abisso, ma la sola pergamena non basta a celebrarli."},{t="Reliquie rubate ai Fauce del Drago",b="Gli accoliti di Strahad hanno bisogno di strumenti per concentrare le energie usate per vincolare un mastino villoso. Krom manda lo stregone nelle Paludi Grigie, dove gli incantatori Fauce del Drago portano con sé verghe di canalizzazione. Gli orchi ostili custodiscono le verghe. Sottratte agli orchi, le verghe forniscono al circolo di Strahad un tramite per controllare la fenditura e stabilizzare le energie evocate."},{t="Ritorno alle Savane",b="Alla torre di Strahad sopra Porto Paranco, il tomo restaurato e le verghe di canalizzazione completano i difficili preparativi. Il testo è tradotto e gli strumenti sono pronti. Strahad prepara il pericoloso rito di vincolo, in cui la volontà dell'evocatore si confronta con un segugio della Legione Infuocata."}},faq={{q="Perché Strahad ha bisogno delle verghe di canalizzazione?",a="Gli accoliti di Strahad usano le verghe per concentrare e stabilizzare le energie necessarie a evocare e vincolare un mastino villoso. Questo aiuta a impedire che il portale collassi o sfugga al controllo.",al={"perché verghe di canalizzazione","scopo verghe di canalizzazione","a cosa servono le verghe"}},{q="Dove si trovano le verghe di canalizzazione?",a="Gli incantatori degli orchi Fauce del Drago nelle Paludi Grigie portano con sé le verghe di canalizzazione, soprattutto presso gli acquitrini e le rovine che occupano.",al={"dove trovare verghe di canalizzazione","chi lascia cadere le verghe di canalizzazione","posizione verghe di canalizzazione"}},{q="Perché Krom Braccioforte è stato coinvolto in un rituale da stregone?",a="Krom Braccioforte è un maestro ricercatore di Forgiardente, esperto nel tradurre, preservare e ricostruire antichi manoscritti danneggiati. Il suo interesse per le antichità rare lo ha spinto a restaurare le pagine corrotte del Tome of the Cabal.",al={"perché krom","perché un nano di forgiardente aiuta uno stregone","krom braccioforte stregone"}},{q="Cosa succede dopo aver dato il tomo e le verghe a Strahad?",a="Dopo che gli hai consegnato il tomo e le verghe, Strahad dà inizio al rito di vincolo in cima alla sua torre. Affronti il mastino villoso evocato e cerchi di soggiogarlo.",al={"cosa succede dopo","missione successiva a tome of the cabal 3","cosa fa strahad"}},{q="Chi è Strahad Farsan?",a="Strahad Farsan è un potente stregone che dimora in una torre solitaria sulle scogliere sopra Porto Paranco, nelle Savane. Gli esperti di queste arti di Kalimdor e dei Regni Orientali riconoscono la sua maestria nella demonologia.",al={"lore strahad farsan","chi è strahad","tizio sopra porto paranco"}},{q="Il Tome of the Cabal viene usato anche dall'Orda?",a="Gli stregoni dell'Orda seguono i propri riti del Tome of the Cabal, con indizi che conducono a diversi contatti a Kalimdor e a Sepulcra anziché a Krom Braccioforte a Forgiardente.",al={"tome of the cabal orda","gli orchi fanno questa missione"}}},fx={["7a279078"]={q="Perché devi dare la caccia al clan Fauce del Drago nelle Paludi Grigie?",a="I resti del clan Fauce del Drago, trincerati nelle Paludi Grigie, brandiscono ancora la potente magia oscura ereditata dal loro antico dominio. Krom sa che i loro incantatori possiedono le speciali verghe d'incanalamento necessarie ad ancorare il cerchio d'evocazione di Strahad. Per reclamare questi catalizzatori, devi strapparli direttamente agli ostili incantatori orchi.",al={"perché gli orchi fauce del drago","stregoni fauce del drago nelle paludi grigie","chi ha le verghe d'incanalamento"}}},fp="17,143,19.338.0,30.322.0,19.270.1,41.163.0,39.125.0,51.223.0,55.138.1,22.203.0,51.163.0"}
P.entries["quest:1805"] = {n="Tomo della Cabala",s="Il lavoro di Strahad Farsan sul Tome of the Cabal si spinge ora in territorio ostile. Dopo aver aiutato Jorah Annison a restaurare il tomo, devi procurarti tre Aste di Canalizzazione e portarle a Strahad a Porto Paranco.",h="Il lavoro di Strahad Farsan sul Tome of the Cabal si spinge ora in territorio ostile.",kw={"accampamento zannarabbiosa","fauce del drago","mastino villoso","jorah annison","porto paranco","verga della canalizzazione","strahad farsan","tome of the cabal","paludi grigie"},ang={["class:Warlock"]="Come stregone, affronti una prova di determinazione. Procurarti pericolosi reagenti rituali in terre ostili richiede la conoscenza e il sangue freddo necessari per vincolare al tuo servizio un mastino villoso predatore.",["faction:Horde"]="Come membro dell'Orda, affronti i rinnegati Fauce del Drago nelle Paludi Grigie, acerrimi nemici dell'Orda di Thrall. Sottrarre loro le aste di canalizzazione favorisce gli interessi dell'Orda.",["race:Orc"]="Come orco, abbattere i Fauce del Drago rinnegati nelle Paludi Grigie richiama il cammino oscuro e impenitente che l'Orda ha lottato per lasciarsi alle spalle.",["race:Undead"]="Come non morto, puoi osservare il lavoro di Jorah Annison a Sepulcra. Gli stregoni dei Reietti studiano testi arcani proibiti per ottenere una concreta supremazia."},sec={{t="I segreti del Tomo Ricostruito",b="A Sepulcra, Jorah Annison studia i frammenti recuperati del Tome of the Cabal. Lo studioso dei Reietti ne ricompone i passaggi arcani e accoglie con favore il raro sapere che custodiscono. Poi Jorah ti trasmette un messaggio urgente di Strahad Farsan. La sola conoscenza non basta a vincolare un mastino villoso; a uno stregone servono strumenti precisi per concentrare il potere demoniaco in un cerchio di vincolo."},{t="Avventurarsi nelle Paludi Grigie",b="A Strahad servono tre Aste di Canalizzazione portate dagli orchi rinnegati del clan Fauce del Drago. Dimorano tra le rovine dell'Accampamento Zannarabbiosa nelle Paludi Grigie, lontano dalle terre dell'Orda. Devi entrare in territorio conteso e affrontare i superstiti del clan, che odiano l'Orda moderna tanto quanto massacrano gli esploratori dell'Alleanza."},{t="Ritorna a Porto Paranco",b="Con le aste e il Tomo Ricostruito al sicuro, riattraversi il mare e torni alla torre di Strahad Farsan sopra Porto Paranco. Strahad ti accoglie con cupa soddisfazione. I componenti del rituale sono riuniti, e ti attende una pericolosa prova di volontà contro una bestia della Distorsione Fatua."}},faq={{q="Qual è lo scopo di questa missione?",a="Porti il Tome of the Cabal restaurato e tre Aste di Canalizzazione a Strahad Farsan sopra Porto Paranco, nella terza tappa della serie di missioni degli stregoni dell'Orda per evocare un mastino villoso.",al={"perché fare questa missione","scopo della missione","a cosa serve tome of the cabal"}},{q="Chi è Jorah Annison?",a="Jorah Annison è uno stregone e studioso dei Reietti nel Magic Quarter di Sepulcra. Jorah studia testi esoterici e oscuri, aiutando gli altri praticanti a ricomporre grimori danneggiati come il Tome of the Cabal.",al={"chi è jorah","lore di jorah annison"}},{q="Perché servono le Aste di Canalizzazione?",a="Le aste danno a uno stregone un controllo preciso quando evoca e soggioga un mastino villoso. Concentrano il potere del rituale e ne modellano il cerchio di evocazione, aiutando lo stregone a sottomettere il demone anziché esserne divorato.",al={"perché le aste di canalizzazione","scopo delle aste"}},{q="Dove si trovano gli orchi Fauce del Drago per questa missione?",a="Il clan Fauce del Drago controlla l'Accampamento Zannarabbiosa nelle Paludi Grigie, al di là del mare, a Khaz Modan. I suoi guardiani delle ossa portano le aste di canalizzazione.",al={"dove trovare i fauce del drago","posizione fauce del drago paludi grigie","accampamento zannarabbiosa"}},{q="Chi è Strahad Farsan?",a="Strahad Farsan è uno stregone umano alleato degli incantatori oscuri dell'Orda. Opera da una torre solitaria sulle alture sopra Porto Paranco, il porto dei goblin nelle Savane.",al={"chi è strahad","strahad farsan porto paranco"}},{q="Cosa succede dopo aver completato questa missione?",a="La tua consegna conduce a 'The Binding'. Strahad ti ordina quindi di tracciare un cerchio di evocazione e affrontare un mastino villoso evocato in un combattimento magico per dominarlo.",al={"what comes next","missione successiva al tomo"}}},fx={["9475dbd0"]={q="Perché Jorah Annison ti sta aiutando?",a="Jorah Annison è un cartografo Reietto nel Quartiere Magico della Città Sotterranea, assetato di testi arcani ed esoterici dopo aver esaurito da tempo la scarsa scelta di testi geografici a sua disposizione. In cambio della possibilità di studiare il Tome of the Cabal ricostruito, ti trasmette le istruzioni di Strahad Farsan e ti rivela dove procurarti le rare verghe d'incanalamento necessarie al tuo addestramento.",al={"perché jorah aiuta","motivo di jorah annison","che cosa vuole jorah"}},cff1ec65={q="Perché gli orchi Fauce del Drago hanno le verghe d'incanalamento?",a="Il rinnegato clan Fauce del Drago mantiene roccaforti nelle Paludi Grigie, dove dimorano incantatori oscuri e custodi delle ossa che praticano magie sinistre, separati dall'Orda moderna. Usano potenti verghe d'incanalamento per concentrare e vincolare le energie magiche grezze, rendendo i loro accampamenti il luogo ideale per recuperare i catalizzatori arcani necessari a Strahad per i rituali d'evocazione.",al={"orchi fauce del drago nelle paludi grigie","chi ha le verghe d'incanalamento","perché gli orchi fauce del drago"}}},fp="17,208,33.368.0,25.304.0,17.280.1,34.167.0,21.220.0,34.198.0,52.137.0,22.164.0,41.162.1"}
P.entries["quest:1806"] = {n="The Test of Righteousness",s="Alla fucina di Jordan Stilwell, fuori Forgiardente, porti i materiali per il martello da guerra di un paladino. Raccolti nei Regni Orientali e a Kalimdor, contribuiscono a trasformare un apprendista in un campione riconosciuto della Luce.",h="Alla fucina di Jordan Stilwell, fuori Forgiardente, porti i materiali per il martello da guerra di un...",kw={"bosch verigan","dun morogh","forgia","martello","forgiardente","jordan stilwell","paladino","test of righteousness","verigan"},ang={["class:Paladin"]="Come paladino, i tuoi pericolosi viaggi in terre lontane ti fanno guadagnare il Pugno di Verigan, un'arma consacrata alla difesa della rettitudine.",["profession:Blacksmithing"]="Come fabbro, puoi vedere come il lavoro magistrale di Jordan Stilwell conferisca uno scopo sacro all'acciaio grezzo e ai materiali recuperati.",["race:Dwarf"]="Come nano, porti un martello forgiato per preservare il ricordo di Bosch Verigan, uno stimato paladino nano che incarnava la tenacia di Khaz Modan."},sec={{t="Il tributo di un fabbro",b="Jordan Stilwell lavora alla sua fucina fuori dai cancelli di Forgiardente. Invidia i paladini che vagano per il mondo, ma è orgoglioso di servire la loro causa. Gli porti materiali rari raccolti in cripte oscure, rovine sommerse e miniere pericolose. Con questi, il mastro fabbro mantiene la promessa e forgia un'arma degna di un vero difensore."},{t="L'eredità di Bosch Verigan",b="Jordan Stilwell chiama il martello da guerra appena terminato Pugno di Verigan, in onore di Bosch Verigan, uno stimato paladino nano e suo caro amico. A nome suo e di sua moglie, depone l'arma sacra nelle mani di un giovane campione. Grazie a essa, il ricordo e il valore del suo amico caduto perdurano contro l'oscurità che minaccia Azeroth."}},faq={{q="Cosa succede durante questa fase della missione?",a="Jordan Stilwell lavora all'incudine i componenti che hai raccolto, battendo il metallo rovente nella sua fucina. Quando il lavoro è concluso, ti presenta l'arma finita.",al={"conclusione test of righteousness","jordan forgia l'arma","filmato di verigan"}},{q="Chi è Bosch Verigan?",a="Bosch Verigan era uno stimato paladino nano e un caro amico di Jordan Stilwell. Jordan ha dato il suo nome al martello a due mani appena forgiato, onorando la sua devozione alla Sacra Luce.",al={"chi è verigan","ispirazione per il pugno di verigan","bosch verigan"}},{q="Dove avviene questa forgiatura?",a="Jordan Stilwell forgia il martello appena fuori dai grandi cancelli di Forgiardente, sulle vette innevate di Dun Morogh. La sua fucina e la sua incudine si trovano lì.",al={"posizione di jordan stilwell","dove si trova la forgia","incudine di dun morogh"}},{q="Perché Jordan aveva bisogno di materiali rari da tutto il mondo?",a="A Jordan Stilwell servivano materiali rari provenienti da luoghi pericolosi in tutto il mondo per forgiare un'arma dall'equilibrio eccezionale e dalla risonanza sacra. I minerali, il legno e le gemme servivano a creare un martello capace di resistere all'ira sacra di un paladino.",al={"perché raccogliere materiali","componenti missione test of righteousness"}},{q="Jordan Stilwell combatte mai in battaglia?",a="Jordan Stilwell è un fabbro, non un guerriero errante. Invidia chi vaga per il mondo, ma trova orgoglio e uno scopo nel forgiare armi per i difensori della Luce.",al={"jordan è un guerriero","combattente jordan stilwell"}},{q="Cosa significa ricevere questo martello per un paladino?",a="Ricevere il martello segna la fine delle lunghe prove di un paladino. Dimostra che chi lo impugna possiede il coraggio, la perseveranza e la sacra convinzione necessari a difendere la Luce negli angoli più pericolosi di Azeroth.",al={"significato del pugno di verigan","rito di passaggio paladino"}}},fx={["49955bc3"]={q="Perché Jordan Stilwell vuole forgiare questo martello?",a="Jordan Stilwell ammette di provare una fitta d'invidia nel vedere le audaci imprese dei campioni in tutta Azeroth, dato che lui è un fabbro e non un avventuriero. Forgiando il Pugno di Verigan con i rari componenti che hai raccolto, può aiutare direttamente un difensore della Luce e contribuire a mantenere il regno al sicuro a modo suo, con un ruolo essenziale.",al={"motivo di jordan stilwell","perché forgiare l'arma","perché jordan forgia il martello"}}},fp="25,221,17.330.0,27.317.0,43.161.0,21.181.0,35.137.0,59.239.0,50.168.0,54.191.0"}
P.entries["quest:181"] = {n="Look To The Stars",s="A Borgoscuro, Viktori Prism'antras cerca l'ultimo pezzo per il suo telescopio. La struttura è pronta, ma nessun vetro locale è abbastanza grande per la lente richiesta dai suoi progetti.",h="A Borgoscuro, Viktori Prism'antras cerca l'ultimo pezzo per il suo telescopio.",kw={"cog","borgoscuro","look to the stars","monocolo","telescopio","viktori prism'antras","tumulo degli ogre vul'gol","zzarc'vul"},ang={["faction:Alliance"]="Come viaggiatore dell'Alleanza, puoi vedere Borgoscuro resistere agli orrori e alle bestie che la circondano. La dedizione di Viktori allo studio delle stelle offre un piccolo segno della perseveranza dei civili.",["profession:Engineering"]="Come ingegnere, puoi apprezzare l'audacia di usare un enorme monocolo da ogre per soddisfare i requisiti di una lente astronomica.",["race:Gnome"]="Come gnomo, sai che l'ingegno può trasformare un ritrovamento improbabile in un componente utile. I progetti del telescopio di Viktori richiedono una lente ricavata dal monocolo di un ogre."},sec={{t="Il Pezzo Finale",b="Viktori Prism'antras sta costruendo un telescopio a Borgoscuro seguendo i progetti di Cog Glitzspinner, un ingegnere gnomo. Ha raccolto tubi di ottone e robusti supporti dalle scorte locali. Ma il progetto richiede una lente di messa a fuoco insolitamente grande. Le lenti d'ingrandimento e i componenti ottici dei mercanti di Roccavento sono troppo piccoli, così Viktori cerca il pezzo necessario tra materiali fuori dall'ordinario."},{t="L'Oculare dell'Ogre",b="Al Tumulo degli Ogre Vul'Gol, ogre ostili affollano le colline meridionali. Uno di loro, Zzarc'Vul, indossa un monocolo di vetro abbastanza grande per il telescopio di Viktori. Sottrarlo a Zzarc'Vul darebbe a Viktori la lente richiesta dai progetti di Cog. Potrebbe così completare il telescopio e scrutare i cieli sopra le cupe chiome degli alberi di Boscovespro."}},faq={{q="Chi è Viktori Prism'antras?",a="Viktori Prism'antras è un astronomo e studioso che vive in una capanna sulla collina a Borgoscuro. Sebbene l'oscurità avvolga Boscovespro, continua a dedicarsi al completamento del suo telescopio e allo studio delle stelle.",al={"chi è viktori","viktori prism'antras"}},{q="Dove posso trovare Zzarc'Vul?",a="Zzarc'Vul si trova al Tumulo degli Ogre Vul'Gol, nella parte meridionale di Boscovespro. Si aggira per l'accampamento e la rete di caverne, nel territorio degli ogre sorvegliato da numerose guardie.",al={"posizione zzarc'vul","dov'è l'ogre","posizione monocolo ogre"}},{q="Perché un ogre possiede un monocolo?",a="Zzarc'Vul indossa un monocolo enorme. È l'unica lente della regione abbastanza grande da soddisfare i progetti del telescopio di Cog.",al={"perché monocolo ogre","lore monocolo dell'ogre"}},{q="Cosa succede una volta completato il dispositivo?",a="Il monocolo permette a Viktori di montare l'ultima lente del telescopio. Una volta completato il dispositivo, potrà tornare a studiare le stelle sopra la tetra foresta.",al={"telescopio finito","conclusione missione"}},{q="Chi ha progettato il telescopio?",a="Cog, un ingegnere gnomo, ha progettato il telescopio. I suoi progetti richiedono componenti specializzati, una struttura metallica e una lente molto più grande di quelle dei comuni occhiali nanici o gnomici.",al={"progetti cog","chi ha costruito il telescopio"}},{q="Il Tumulo degli Ogre Vul'Gol è sicuro da affrontare da soli?",a="No. Gli ogre ostili gremiscono il Tumulo degli Ogre Vul'Gol, pattugliando in gruppi e sorvegliando gli stretti sentieri. Addentrarsi alla ricerca di Zzarc'Vul è pericoloso per un viaggiatore solitario.",al={"difficoltà tumulo vul'gol","tumulo degli ogre sicuro"}}},fx={ac1c4dd0={q="Perché Viktori Prism'Antras vuole che venga fatto?",a="Viktori è uno studioso eccentrico, dedito a costruire uno speciale dispositivo per osservare le stelle partendo dai progetti di Cog. Ha dedicato molto impegno alla raccolta di pezzi delicati, ma al suo progetto manca ancora una lente abbastanza grande da scrutare i cieli. Una volta assemblato il telescopio, potrà finalmente riprendere le sue ricerche astronomiche nell'oscurità di Borgoscuro.",al={"perché viktori ha bisogno del monocolo","obiettivo di viktori prism'antras","motivo di look to the stars"}},f331a2d2={q="A cosa serve il Monocolo dell'Ogre?",a="I progetti del dispositivo astronomico di Viktori richiedono una lente ottica insolitamente grande. Invece di molarne una da zero nell'isolamento ombroso di Boscovespro, Viktori ha capito che l'enorme monocolo indossato dall'orco Zzarc'Vul ha esattamente le dimensioni e il vetro focale necessari per completare l'apparecchio.",al={"scopo del monocolo dell'ogre","perché il monocolo dell'ogre","a cosa serve il monocolo"}},bbeac028={q="Chi è Zzarc'Vul?",a="Zzarc'Vul è un orco di spicco che vive tra i suoi simili al Tumulo degli Ogre Vul'Gol, sulle colline meridionali di Boscovespro. A differenza dei suoi brutali compagni, porta un enorme monocolo che ha attirato l'attenzione di Viktori Prism'Antras: è l'ultimo ostacolo tra lo studioso e il telescopio completato.",al={"chi è zzarc'vul","chi è l'ogre","bersaglio zzarc'vul"}}},fp="17,161,15.381.0,19.316.1,28.197.0,27.130.0,35.114.0,42.145.0,27.166.0,42.159.0"}
P.entries["quest:1818"] = {n="Speak with Dillinger",s="Alla Taverna dell'Impiccato di Brill, Austil de Mon invia combattenti in una pericolosa missione per Lady Sylvanas. L'ordine manda le reclute abili dal Guardiamorte Dillinger all'estremità occidentale del villaggio.",h="Alla Taverna dell'Impiccato di Brill, Austil de Mon invia combattenti in una pericolosa missione per Lady...",kw={"austil de mon","brill","guardiamorte dillinger","speak with dillinger","radure di tirisfal","ulag the cleaver","sepulcra"},ang={["class:Warrior"]="I comandanti dei Guardiamorte apprezzano la tenacia in battaglia, perciò la chiamata di Dillinger mette alla prova la tua abilità in combattimento in prima linea.",["faction:Horde"]="Rispondere alle richieste di difesa di Sepulcra rafforza la solidarietà tra gli alleati dell'Orda di Kalimdor e i Reietti appena entrati nelle sue file.",["race:Undead"]="Come Reietto appena liberato, rispondere alla chiamata di Dillinger è fondamentale per dimostrare la tua dedizione alla Signora Oscura e alla difesa di Tirisfal."},sec={{t="Una chiamata al fronte",b="Alla Taverna dell'Impiccato di Brill, l'istruttore dei guerrieri Austil de Mon cerca combattenti disposti a servire la Signora Oscura. Quando i Guardiamorte hanno bisogno di braccia capaci, invia sul campo reclute inesperte. Il Guardiamorte Dillinger sorveglia i confini occidentali di Brill e ha richiesto qualcuno esperto nel combattimento per un incarico urgente."},{t="Mettere alla prova i fedeli",b="I Reietti devono dimostrare costantemente la propria superiorità militare sulla prima linea delle Radure di Tirisfal. Vicino al cimitero di Brill, Dillinger gestisce le incursioni locali. Presentarti a lui mette alla prova la tua abilità in combattimento e la tua lealtà alla neonata nazione dei Reietti."}},faq={{q="Chi mi invia in questa missione?",a="Austil de Mon, l'istruttore dei guerrieri alla Taverna dell'Impiccato di Brill, individua potenziali soldati e li invia ad aiutare il Guardiamorte Dillinger.",al={"datore di missione","austil de mon","chi inizia speak with dillinger"}},{q="Dove si può trovare il Guardiamorte Dillinger?",a="Il Guardiamorte Dillinger è di stanza ai confini occidentali di Brill, nelle Radure di Tirisfal, vicino all'ingresso del cimitero.",al={"posizione di dillinger","dove si trova dillinger","trovare dillinger"}},{q="Qual è lo scopo di presentarsi a Dillinger?",a="Dillinger ha bisogno di un campione abile per una missione di combattimento in cui difendere Brill e dimostrare fedeltà alla causa dei Reietti.",al={"perché parlare con dillinger","scopo di dillinger"}},{q="Quale incarico ha preparato Dillinger?",a="Quando ti presenti al Guardiamorte Dillinger, ti affida il compito di dare la caccia a Ulag la Mannaia, una pericolosa minaccia.",al={"cosa vuole dillinger","prossima missione di dillinger"}},{q="Anche le altre razze dell'Orda ricevono questo ordine?",a="Qualsiasi guerriero dell'Orda che goda della fiducia dei funzionari di Sepulcra può accettare l'incarico, pensato soprattutto per valutare l'abilità in combattimento delle reclute mentre difendono le Radure di Tirisfal.",al={"è solo per non morti","gli orchi possono farlo"}},{q="Perché un istruttore di guerrieri mi invia da Dillinger?",a="Austil de Mon addestra guerrieri alla Taverna dell'Impiccato di Brill. Invia gli avventurieri che hanno appena acquisito le capacità necessarie ai comandanti dei Guardiamorte che hanno urgente bisogno di combattenti.",al={"perché iniziare a sepulcra","ruolo di austil de mon"}}},fx={["277a5d32"]={q="Perché Austil de Mon ti manda da Dillinger?",a="Austil de Mon fa da intermediario e indirizza i Reietti emergenti in cerca di prestigio verso incarichi in cui i loro talenti marziali possano servire il regno. Mandando combattenti capaci dalla Taverna dell'Impiccato di Brill sul campo, sotto il comando del Guardiamorte Dillinger, si assicura che gli insediamenti in prima linea ricevano rinforzi e mette alla prova il tuo valore e la tua devozione alla causa di Lady Sylvanas.",al={"motivo di austil de mon","perché mandare da dillinger","ragione di austil de mon"}}},fp="20,190,22.325.0,20.240.0,29.140.0,40.106.0,46.126.0,45.116.1,40.169.0,48.148.0"}
P.entries["quest:1819"] = {n="Ulag the Cleaver",s="Sotto un mausoleo a nord di Brill, Ulag la Mannaia attende di mettere alla prova i giovani Reietti. Il Guardiamorte Dillinger ti manda a liberare il prigioniero e ad affrontarlo in combattimento.",h="Sotto un mausoleo a nord di Brill, Ulag la Mannaia attende di mettere alla prova i giovani Reietti.",kw={"brill","guardiamorte dillinger","dillinger","mausoleo","flagello","pietra del teschio","ulag","ulag the cleaver"},ang={["class:Warrior"]="Come guerriero dei Reietti, affronti una delle tue prime prove di coraggio contro un potente campione del Flagello ancora sotto il controllo del Re dei Lich.",["race:Undead"]="Come non morto, vedi nel destino di Ulag l'orrore del controllo del Flagello: alcuni Reietti si sono liberati, mentre altri rimangono schiavi del Re dei Lich."},sec={{t="Un servitore del Flagello incatenato",b="Dopo che il Flagello travolse Lordaeron, i Reietti catturarono un insolito guerriero non morto che si faceva chiamare Ulag la Mannaia. La sua mente rimase lucida, ma il Re dei Lich teneva ancora il suo spirito sotto un giogo psichico. Sotto un mausoleo a nord di Brill, i Reietti lo imprigionarono con un sigillo magico. Speravano di scoprire come il Flagello incatenasse una mente e di spezzare il suo controllo su Ulag."},{t="La Prova del Carnefice",b="I Reietti non riuscirono a liberare Ulag dal dominio del Re dei Lich. Ora il Guardiamorte Dillinger usa il prigioniero come prova di combattimento per i guerrieri Reietti in ascesa. Disturba la pietra del teschio fuori dalla cripta e le protezioni si infrangeranno, liberando Ulag dalla sua prigione. Un guerriero deve affrontarlo con un'ascia. La morte lo libererà finalmente."}},faq={{q="Chi è Ulag la Mannaia?",a="Ulag la Mannaia era un guerriero non morto catturato dai Reietti durante l'invasione delle Radure di Tirisfal da parte del Flagello. Conservò la propria mente e identità, ma rimase sotto il dominio del Re dei Lich.",al={"lore di ulag","chi è ulag","ulag la mannaia identità"}},{q="Perché Ulag era imprigionato sotto il mausoleo?",a="I Reietti sigillarono Ulag sotto il mausoleo per studiare il controllo del Re dei Lich sulla sua mente. Speravano di recidere il legame psichico, ma fallirono.",al={"perché ulag è rinchiuso","prigioniero mausoleo tirisfal"}},{q="Perché i Guardiamorte vogliono che Ulag venga ucciso ora?",a="I Reietti non riuscirono a spezzare il controllo del Re dei Lich su Ulag e decisero che la morte fosse l'unica misericordia rimasta. Il Guardiamorte Dillinger trasformò l'esecuzione in una prova di coraggio e disciplina per gli aspiranti guerrieri.",al={"perché uccidere ulag","motivo per uccidere ulag"}},{q="Come viene evocato Ulag?",a="Ulag è tenuto prigioniero sotto un mausoleo poco a nord di Brill. Tocca la pietra del teschio vicino alla tomba per spezzare il sigillo magico e Ulag si alzerà per attaccarti.",al={"come evocare ulag","dove si trova ulag","pietra del teschio di ulag"}},{q="Chi assegna la missione per uccidere Ulag?",a="Il Guardiamorte Dillinger sorveglia la strada che esce da Brill verso ovest, nelle Radure di Tirisfal. Manda i guerrieri Reietti in cerca di ulteriore addestramento ad affrontare Ulag.",al={"datore missione ulag","chi mi manda da ulag"}},{q="Cosa succede dopo che Ulag viene sconfitto?",a="Dopo che hai confermato la morte di Ulag, il Guardiamorte Dillinger riconosce il tuo coraggio e ti manda da Coleman Farthing a Brill per continuare l'addestramento.",al={"dopo ulag","seguito missione ulag"}}},fx={["6de55395"]={q="Perché il Guardiamorte Dillinger ti fa affrontare Ulag invece di occuparsene lui stesso?",a="Il Guardiamorte Dillinger sta mettendo alla prova il tuo valore. Ulag non era un semplice servitore del Flagello, e affrontarlo da solo dimostra se possiedi l'abilità, il coraggio e la determinazione richiesti a un vero guerriero al servizio di Lady Sylvanas. Dillinger protegge Brill e supervisiona il tuo addestramento; mandarti nella cripta è la tua prova di combattimento per dimostrare di meritare un'istruzione avanzata.",al={"perché io da dillinger","perché non uccidere ulag da solo","perché mandare il giocatore contro ulag"}}},fp="16,162,22.371.0,23.315.0,24.188.0,44.142.0,44.196.0,21.142.0,33.146.0,36.146.0"}
P.entries["quest:182"] = {n="The Troll Cave",s="Nel sud della Valle Crestafredda, Grelin Barbabianca ti manda contro i giovani Geloscudo che si insediano in una caverna. Il loro accampamento in espansione minaccia le vicine fattorie naniche.",h="Nel sud della Valle Crestafredda, Grelin Barbabianca ti manda contro i giovani Geloscudo che si insediano in...",kw={"valle crestafredda","dun morogh","geloscudo","grelin barbabianca","trogg","troll","cucciolo"},ang={["class:Hunter"]="Come cacciatore, puoi usare le rupi attorno alla caverna meridionale come un duro terreno di prova, stanando prede ostili dalle alture montane.",["race:Dwarf"]="Come nano Bronzebeard, affronti una minaccia alla frontiera e un'antica faida montana quando impugni le armi contro le bande da guerra dei Geloscudo.",["race:Gnome"]="Come gnomo rifugiatosi a Dun Morogh dopo la caduta di Gnomeregan, puoi offrire ingegno e armi per aiutare i nani che ti ospitano ad affrontare le minacce circostanti."},sec={{t="Occhi nel Freddo",b="Grelin sorveglia la valle gelata da un dirupo mentre i soldati di Forgiardente combattono i trogg nelle distese innevate. Lui e suo fratello Senir sono giunti su ordine delle autorità montane per scoprire se i troll del ghiaccio nativi minacciassero il cuore del territorio. Ora Grelin veglia da solo, seguendo i loro movimenti lungo gli accessi meridionali."},{t="Un Attacco Preventivo",b="Grelin ha scoperto che il clan locale dei Geloscudo si sta insediando in una profonda caverna lungo il crinale meridionale della Valle Crestafredda. Ritiene che una mobilitazione completa sia uno spreco di forze naniche, quindi ingaggia capaci volontari locali per eliminare i giovani aggressivi. Sfoltire i giovani combattenti potrebbe destabilizzare l'accampamento prima che i Geloscudo lancino incursioni coordinate contro le vicine fattorie naniche."}},faq={{q="Perché Forgiardente non invia soldati regolari ad affrontare questi troll?",a="Il Senato e l'esercito di Forgiardente sono allo stremo a causa dell'improvvisa e devastante invasione dei trogg in tutta Dun Morogh. Esploratori come Grelin Barbabianca ingaggiano avventurieri indipendenti per affrontare minacce minori, comprese le bande da guerra dei troll.",al={"perché niente esercito nanico","dove sono le guardie","perché ingaggiare avventurieri"}},{q="Chi sono i troll Geloscudo?",a="I Geloscudo sono una tribù autoctona di troll del ghiaccio proveniente dalle gelide rupi di Dun Morogh. Da tempo si scontrano con i nani Bronzebeard e i montanari per i territori di caccia, le terre e gli antichi valichi montani.",al={"clan geloscudo","troll di dun morogh","chi sono i geloscudo"}},{q="Dove si trova la caverna dei troll?",a="La caverna si trova lungo il crinale montuoso meridionale della Valle Crestafredda, a sud dell'accampamento di osservazione di Grelin Barbabianca.",al={"posizione caverna dei troll","dove si trova la caverna","dove sono i cuccioli"}},{q="Chi è Grelin Barbabianca?",a="Grelin Barbabianca è un esploratore di Forgiardente di stanza nella Valle Crestafredda. Suo fratello Senir perlustra altre zone di Dun Morogh, mentre Grelin sorveglia i gruppi di troll ostili e riferisce ai capi nanici.",al={"grelin","datore di missione","barbabianca"}},{q="Perché Grelin prende di mira specificamente i cuccioli Geloscudo?",a="Grelin prende di mira i giovani Geloscudo perché il loro insediamento nel sud della Valle Crestafredda è in espansione e conta giovani guerrieri tra i suoi membri. Uccidere quei giovani combattenti potrebbe impedire alla banda di diventare abbastanza forte da minacciare le linee di rifornimento naniche.",al={"perché i cuccioli","perché prendere di mira i giovani troll"}},{q="Cosa succede dopo aver decimato la caverna?",a="Dopo che hai ripulito la caverna, i troll si vendicano di notte. Assaltano l'accampamento di Grelin e rubano il suo diario personale di ricognizione, che devi recuperare nelle profondità delle loro tane.",al={"cosa succede dopo","seguito caverna dei troll"}}},fx={["9e422164"]={q="Perché Grelin Barbabianca vuole che si affrontino i troll?",a="Grelin e suo fratello Senir sono stati mandati in giro per Dun Morogh per valutare se i troll Gelidoartiglio nativi rappresentino una seria minaccia per il regno. Con il Senato di Forgiardente già sopraffatto dalle rivolte dei trogg altrove, Grelin spera di stroncare sul nascere questa congregazione prima che degeneri in una crisi tale da richiedere l'intervento delle truppe regolari.",al={"perché uccidere i troll","motivo di grelin barbabianca","perché ripulire la caverna dei troll"}}},fp="14,158,16.322.0,19.361.0,70.225.0,29.210.0,32.115.0,25.201.0,53.251.0,36.171.1"}
P.entries["quest:1820"] = {n="Speak with Coleman",s="A Brill, il Guardiamorte Dillinger manda combattenti esperti ad aiutare Coleman Farthing. Il loro incontro nella taverna apre la strada a una faccenda privata legata alle vecchie terre degli Agamand.",h="A Brill, il Guardiamorte Dillinger manda combattenti esperti ad aiutare Coleman Farthing.",kw={"agamand","brill","coleman farthing","guardiamorte dillinger","reietti","gallow's end tavern","orda","radure di tirisfal"},ang={["faction:Horde"]="Come viaggiatore dell'Orda che contribuisce a rendere sicura Lordaeron, incontrando gli abitanti di Brill trovi un punto di partenza per incarichi nelle Radure di Tirisfal.",["race:Undead"]="Molti Reietti nutrono rancori personali accanto alla loro lealtà verso la Dark Lady. Le richieste di Coleman Farthing mostrano come le perdite personali e la difesa di Tirisfal siano legate."},sec={{t="Una parola dalla guardia",b="Hai contribuito a contenere gravi minacce nei pressi di Brill, tra cui Ulag la Mannaia. Per questo il Guardiamorte Dillinger si fida della tua forza. Sorveglia le strade che conducono in paese e sceglie chi può svolgere incarichi che vanno oltre i consueti pattugliamenti. Vedendo che sei all'altezza, ti indirizza verso chi ha bisogno di un aiuto specializzato."},{t="Una vendetta privata",b="Non tutti gli scontri nelle Radure di Tirisfal iniziano con ordini da Sepulcra. I non morti sopravvissuti di Lordaeron nutrono ancora rancori legati alle terre, alle famiglie e alle fortune che si sono lasciati alle spalle. Coleman Farthing attende nella Gallow's End Tavern un combattente disposto a colpire le minacce nei pressi di antichi insediamenti come i Mulini degli Agamand."}},faq={{q="Dove posso trovare Coleman Farthing?",a="Coleman Farthing attende nella Gallow's End Tavern, sul lato orientale di Brill, nelle Radure di Tirisfal.",al={"posizione coleman farthing","dove si trova coleman farthing","trovare farthing brill"}},{q="Chi ti manda a parlare con Coleman?",a="Il Guardiamorte Dillinger sorveglia la strada che conduce a Brill. Ti manda da Coleman dopo che hai dimostrato la tua abilità in combattimento.",al={"chi dà speak with coleman","missione dillinger"}},{q="Che tipo di lavoro ha Coleman Farthing?",a="Coleman Farthing cerca un combattente capace per vendicarsi dei nemici dei Reietti. Sono in gioco questioni legate alle vecchie proprietà degli Agamand.",al={"cosa vuole coleman","compito coleman farthing"}},{q="Quali prerequisiti sono necessari prima di ricevere questo compito?",a="Il Guardiamorte Dillinger ti indirizza da Coleman dopo che hai sconfitto Ulag la Mannaia e dimostrato ai Reietti la tua lealtà e abilità in combattimento.",al={"prerequisiti speak with coleman","requisito ulag"}},{q="Questa missione garantisce ricompense sostanziali direttamente?",a="Parlare con Farthing nella taverna ti permette di conoscere le sue richieste personali. L'incontro, di per sé, non frutta equipaggiamento o denaro di rilievo.",al={"ricompense speak with coleman","vale la pena farlo"}},{q="Che cos'è la Gallow's End Tavern?",a="La Gallow's End Tavern è la locanda principale di Brill, dove i non morti del posto si riuniscono e riposano. È anche un luogo d'incontro informale per accordi privati.",al={"locanda brill","gallows end tavern"}}},fx={["75bd5c35"]={q="Perché il Guardiamorte Dillinger vuole che parli con Coleman?",a="Il Guardiamorte Dillinger riconosce che hai dimostrato forza e lealtà alla Signora Oscura affrontando le minacce a Brill. Coleman Farthing ha dei conti personali da regolare e ha bisogno di un combattente capace per vendicarsi dei nemici dei Reietti. Mandandoti da lui, Dillinger si assicura che dei campioni capaci aiutino i loro concittadini e contribuiscano alla sicurezza generale del regno.",al={"perché mandare da coleman","motivo di dillinger per parlare con coleman","perché vedere coleman farthing"}},["5d6ae549"]={q="Perché il Guardiamorte Dillinger manda me invece di occuparsi personalmente della richiesta di Coleman?",a="Dillinger è un Guardiamorte di stanza a protezione del perimetro di Brill dalle minacce immediate, come il Flagello. Non può abbandonare il suo posto per risolvere le vendette personali o le questioni private degli abitanti del luogo. Hai dimostrato abilità in combattimento e indipendenza, quindi sei l'agente ideale per aiutare direttamente Coleman Farthing.",al={"perché io da coleman","perché non dillinger","perché dillinger ti manda"}}},fp="18,175,21.290.0,18.327.0,34.97.0,33.109.0,45.140.0,57.133.0,53.136.0,32.143.0"}
P.entries["quest:1821"] = {n="Agamand Heirlooms",s="Ai Mulini degli Agamand, Coleman Farthing ti manda a recuperare dei cimeli nella cripta di famiglia. Incolpa gli Agamand della propria morte e cerca le loro armi ancestrali.",h="Ai Mulini degli Agamand, Coleman Farthing ti manda a recuperare dei cimeli nella cripta di famiglia.",kw={"cripta degli agamand","agamand heirlooms","mulini degli agamand","coleman farthing","arma cimelio","flagello","radure di tirisfal"},ang={["class:Rogue"]="Come ladro, sai come superare di soppiatto i ghoul in agguato e sottrarre armi antiche da camere sepolcrali sorvegliate.",["faction:Horde"]="Come membro dell'Orda, contribuisci a indebolire la presa del Flagello sulle Radure di Tirisfal settentrionali e a rendere il regno più sicuro per i viaggiatori.",["race:Undead"]="Come non morto, sai come i rancori della vita mortale possano persistere dopo la morte tra i Reietti."},sec={{t="L'amaro rancore di un servitore",b="Prima che la Terza Guerra devastasse Lordaeron, Coleman Farthing serviva la ricca famiglia Agamand nei suoi mulini nelle Radure di Tirisfal. Farthing incolpa i suoi antichi signori della propria morte. Ora risorto come non morto tra i Reietti, prova un maligno compiacimento per la rovina degli Agamand. I membri della famiglia un tempo orgogliosa sono diventati servitori senza mente, schiavi del Re dei Lich."},{t="Profanazione della cripta",b="Farthing ti manda nella Cripta degli Agamand, sotto le rupi settentrionali dei mulini. Morti irrequieti e superstiti del Flagello vagano per le sue sale di pietra. Vuole che tu prenda quattro reliquie: la spada, l'ascia, il pugnale e la mazza della famiglia Agamand. La loro perdita priverebbe la stirpe dell'onore che le resta."}},faq={{q="Chi era Coleman Farthing in vita?",a="Prima dell'invasione di Lordaeron da parte del Flagello, Coleman Farthing serviva la ricca famiglia Agamand ai Mulini degli Agamand. Morì durante la catastrofe e ne incolpa i suoi antichi padroni, portando quel rancore con sé nella non morte.",al={"chi è coleman farthing","storia di coleman","passato di farthing"}},{q="Perché Coleman Farthing vuole gli cimeli?",a="Farthing cerca vendetta contro i suoi antichi padroni. Vuole la loro spada, ascia, pugnale e mazza ancestrali per privare la famiglia caduta in rovina dei suoi ultimi resti di onore e memoria.",al={"perché rubare gli cimeli","movente di coleman","perché prendere le armi"}},{q="Cosa è successo alla famiglia Agamand?",a="La famiglia Agamand perì quando il Flagello travolse le Radure di Tirisfal. I suoi membri furono rianimati come schiavi non morti senza mente, vincolati al Re dei Lich, e vagano tra i loro mulini in rovina e la cripta.",al={"destino degli agamand","gli agamand sono vivi","cosa sono ora gli agamand"}},{q="Dove si trova la Cripta degli Agamand?",a="La Cripta degli Agamand si trova all'estremità settentrionale dei Mulini degli Agamand, tra le pareti rocciose che sovrastano le fattorie contaminate delle Radure di Tirisfal settentrionali.",al={"posizione della cripta","dove si trova la cripta","mappa della cripta agamand"}},{q="Quali armi sono custodite all'interno della cripta?",a="La cripta custodisce quattro armi ancestrali: la Spada della Famiglia Agamand, l'Ascia della Famiglia Agamand, il Pugnale della Famiglia Agamand e la Mazza della Famiglia Agamand.",al={"quali cimeli","quattro cimeli","armi agamand"}},{q="Perché i Reietti attaccano gli Agamand se entrambi sono non morti?",a="I Reietti hanno libero arbitrio e combattono per la propria sopravvivenza. Gli Agamand non morti restano schiavi senza mente del Flagello, al servizio del Re dei Lich che i Reietti disprezzano.",al={"non morti contro non morti","perché combattere gli agamand","conflitto reietti flagello"}}},fx={c3afbf3e={q="Cosa farà Coleman Farthing con i cimeli degli Agamand?",a="Per Coleman Farthing, le quattro armi — la spada, l'ascia, il pugnale e la mazza della famiglia Agamand — rappresentano gli ultimi resti dell'orgoglio e della discendenza dei suoi ex padroni. Profanandone la tomba e sottraendole, cancella le ultime vestigia di onore e memoria rimaste nelle terre maledette degli Agamand e dichiara che la famiglia non esiste più.",al={"uso dei cimeli degli agamand","a cosa servono i cimeli","scopo delle armi della famiglia agamand"}},c1f9d064={q="Chi protegge la cripta della famiglia Agamand?",a="La cripta e i mulini circostanti sono infestati da servitori senza senno del Flagello, tra cui i resti rianimati della stessa famiglia Agamand. Vincolati alla volontà del Re dei Lich, anziché dotati di libero arbitrio come i Reietti, questi non morti si annidano nelle tombe oscure dei loro antenati e difendono con ferocia le reliquie di famiglia dagli intrusi.",al={"nemici della cripta degli agamand","chi protegge i cimeli","mostri della cripta della famiglia agamand"}}},fp="17,153,25.355.0,21.292.0,33.208.0,45.158.0,36.182.0,42.149.0,39.145.0,63.162.0"}
P.entries["quest:1824"] = {n="Trial at the Field of Giants",s="A Camp Taurajo, Ruga Totem Rabbioso manda gli aspiranti guerrieri a sud ad affrontare un nemico sconosciuto. Hanno mezz'ora per uccidere i silithid nel Field of Giants e tornare con diverse antenne ancora guizzanti.",h="A Camp Taurajo, Ruga Totem Rabbioso manda gli aspiranti guerrieri a sud ad affrontare un nemico sconosciuto.",kw={"savane","camp taurajo","field of giants","ruga totem rabbioso","silithid","antenna ronzante","prova guerriero"},ang={["class:Warrior"]="Come guerriero, affronti questo rito di passaggio intorno al ventesimo livello. Mette alla prova la rapidità con cui riesci a sopraffare sciami di nemici e a reggere la pressione di un rigido limite di tempo.",["faction:Horde"]="Come membro dell'Orda, affronti la crescente presenza dei silithid nelle Savane Meridionali. Queste prove servono anche a raccogliere informazioni su una minaccia che avanza lentamente.",["race:Tauren"]="Come difensore tauren, contribuisci a proteggere i territori di caccia intorno a Camp Taurajo affrontando la profanazione del Field of Giants e il suo alveare innaturale e invasivo."},sec={{t="Una prova di velocità e acciaio",b="Ruga Totem Rabbioso mette alla prova i guerrieri in formazione a Camp Taurajo contro un nemico sconosciuto. Gli istruttori dei guerrieri dell'Orda esigono più dell'abilità in battaglia: gli aspiranti devono uccidere le creature e riportare antenne fresche entro mezz'ora. La corsa attraverso le Savane Meridionali mette alla prova la loro velocità e determinazione. Le antenne devono ancora guizzare quando arrivano a Taurajo."},{t="Intrusi indesiderati",b="Gli alveari silithid sorgono nel Field of Giants sotto enormi gabbie toraciche fossilizzate. Questi strani insetti striscianti sono arrivati di recente nelle Savane, turbando i cacciatori e gli sciamani tauren che vegliano sulle distese erbose. Ruga dice che la loro presenza è di cattivo auspicio per Kalimdor. La prova mette alla prova l'istinto in battaglia di un giovane guerriero e raccoglie informazioni su una minaccia crescente per queste terre."}},faq={{q="Perché c'è un limite di tempo per le antenne?",a="Ruga Totem Rabbioso esige che le antenne guizzino ancora quando i guerrieri le portano a Camp Taurajo. Questo concede loro solo trenta minuti per la caccia e il ritorno. La loro freschezza dimostra che l'aspirante ha ucciso un silithid in uno scontro diretto, anziché raccoglierle da uno già morto.",al={"perché a tempo","timer antenne guizzanti","quanto tempo ho"}},{q="Quali creature vivono nel Field of Giants?",a="Bizzarri e aggressivi silithid scavatori vivono nel Field of Giants. Hanno scavato enormi tumuli e alveari sotto antichi fossili, alterando l'ecologia locale e allarmando l'Orda.",al={"che insetti sono","mostri field of giants","cosa sono i silithid"}},{q="Chi è Ruga Totem Rabbioso?",a="Ruga Totem Rabbioso è un istruttore di guerrieri tauren a Camp Taurajo, nelle Savane Meridionali. Supervisiona le prove dei guerrieri dell'Orda che cercano di avanzare di rango, mettendo alla prova la loro abilità, resistenza e velocità.",al={"ruga","chi dà la missione","storia di ruga totem rabbioso"}},{q="Dov'è situato il Field of Giants?",a="Il Field of Giants si trova subito a sud di Camp Taurajo, accanto alla strada prima del passo meridionale verso Millepicchi. Gabbie toraciche gigantesche e tumuli silithid contraddistinguono la zona.",al={"dove si trova field of giants","posizione field of giants","dove trovo gli insetti"}},{q="Dove porta questa catena di addestramento?",a="Quando un guerriero riporta in tempo le antenne guizzanti, Ruga lo manda da Thun'grim Firegaze, un anziano fabbro orco che vive in cima a una collina a est di Crocevia. Thun'grim forgerà armature per i guerrieri che hanno dimostrato il proprio valore.",al={"prossima missione","cosa succede dopo","continuazione catena guerriero"}},{q="Perché i tauren sono preoccupati per gli insetti?",a="Ruga dice che i silithid sono nuovi arrivati innaturali nelle Savane e che il loro arrivo è di cattivo auspicio per queste terre. Sospetta che la loro aggressiva attività di scavo ed espansione indichi un pericolo maggiore sotto le sabbie.",al={"perché ai tauren importa","araldo insettoide","minaccia silithid"}}},fx={["5312a899"]={q="Perché Ruga Totem Rabbioso vuole che venga fatto?",a="Ruga Totem Rabbioso mette alla prova il tuo valore marziale nell'ambito dell'addestramento da guerriero, tenendo al contempo d'occhio una minaccia emergente. Di recente, strane creature insettoidi sono comparse al Field of Giants, inquietando i tauren del luogo. Mandandoti a eliminarle in fretta e a riportare trofei freschi prima che smettano di contorcersi, Ruga mette alla prova la tua abilità in combattimento, la velocità e la resistenza sul campo.",al={"motivo di ruga totem rabbioso","perché la prova al field of giants","perché ruga ti manda"}},["2d3c0cc0"]={q="Perché Ruga Totem Rabbioso ha bisogno di te invece delle guardie dell'accampamento?",a="Questa missione è un rito di passaggio personale pensato appositamente per un aspirante guerriero sotto la guida di Ruga. Le guardie dell'accampamento sono impegnate a difendere Camp Taurajo e a sorvegliare le frontiere vicine; sopravvivere da solo a dure prove contro predatori pericolosi è invece il modo per dimostrare di essere pronto a seguire il più ampio cammino del guerriero.",al={"perché io nella prova dei giganti","perché ruga manda un avventuriero"}}},fp="28,195,25.345.0,19.367.0,42.255.0,43.184.0,22.200.0,37.185.0,41.211.0,47.197.0"}
P.entries["quest:1825"] = {n="Speak with Thun'grim",s="Dopo la Trial at the Field of Giants, Thun'grim Firegaze chiama i guerrieri al suo accampamento nelle Savane. Il fabbro orco offre armature su misura a chi ha dimostrato il proprio valore e li manda a raccogliere materiali per la Brutal Armor.",h="Dopo la Trial at the Field of Giants, Thun'grim Firegaze chiama i guerrieri al suo accampamento nelle Savane.",kw={"savane","brutal armor","crocevia","firegaze","ragetotem","ruga","thun'grim","guerriero"},ang={["class:Warrior"]="Come guerriero, sei passato da combattente alle prime armi a campione riconosciuto e ti sei guadagnato un'armatura forgiata su misura.",["faction:Horde"]="Come membro dell'Orda, puoi contare sui suoi armaioli per equipaggiare i suoi difensori più agguerriti in riconoscimento delle loro imprese alla frontiera.",["profession:Blacksmithing"]="Come fabbro, riconosci in Thun'grim Firegaze la tradizionale convinzione orchesca che un'armatura di maestria debba essere guadagnata attraverso prove marziali, non comprata con il denaro."},sec={{t="Il Richiamo del Fabbro",b="La notizia della prova dei guerrieri giunge a Thun'grim Firegaze dopo che hanno dimostrato resistenza e abilità in combattimento a Ruga Totem Rabbioso. Il suo accampamento sorge su un crinale a est di Crocevia. Thun'grim vuole forgiare per loro un'eccezionale armatura di maglia da battaglia."},{t="Lo Standard di un Maestro",b="Thun'grim Firegaze riserva la sua forgia ai guerrieri che soddisfano i suoi elevati requisiti. Si aspetta che l'acciaio sia all'altezza dello spirito di chi lo indossa. Raggiungere il suo accampamento significa che un guerriero ha superato l'addestramento di base della milizia e può affrontare l'ardua raccolta di materiali rari in tutta Kalimdor."}},faq={{q="Chi è Thun'grim Firegaze?",a="Thun'grim Firegaze è un rinomato fabbro orco accampato su un crinale roccioso a est di Crocevia, nelle Savane. Realizza armature su misura per i guerrieri dell'Orda che dimostrano il proprio valore affrontando prove pericolose.",al={"chi è thungrim","storia di thungrim","thungrim firegaze"}},{q="Perché Ruga Totem Rabbioso mi manda da lui?",a="Ruga Totem Rabbioso ti manda da Thun'grim perché sei sopravvissuto ai silitidi nelle Savane Meridionali e hai superato le prove di base. Il fabbro offre armature specializzate in riconoscimento del tuo servizio all'Orda.",al={"perché parlare con thungrim","ruga che mi manda"}},{q="Dove posso trovare l'accampamento di Thun'grim?",a="L'accampamento di Thun'grim si trova sulle alte scarpate a est di Crocevia, nelle Savane.",al={"dov'è thungrim","posizione di thungrim","trovare thungrim firegaze"}},{q="Cosa succede dopo aver parlato con Thun'grim?",a="Parlare con Thun'grim dà inizio al lavoro per realizzare la Brutal Armor. Viaggi attraverso terre lontane per raccogliere materiali, tra cui lingotti di ferro fumante e barre di ferro, per una corazza di maglia su misura.",al={"missione successiva dopo thungrim","cosa vuole thungrim"}},{q="Questa missione è disponibile per tutte le classi?",a="No. Solo i guerrieri dell'Orda possono intraprendere questo lavoro per l'armatura.",al={"possono farlo i non guerrieri","è solo per guerrieri"}},{q="Quale prova era richiesta prima di questo incontro?",a="Prima di incontrare Thun'grim, viaggi nelle Savane Meridionali e completi la Trial at the Field of Giants. Raccogliere antenne frementi di silitide dimostra la tua resistenza in combattimento.",al={"missione prerequisito","cosa ho fatto prima di questo"}}},fx={["2df90612"]={q="Perché Ruga Totem Rabbioso manda te invece di andarci lui?",a="Ruga Totem Rabbioso supervisiona l'addestramento e le prove dei guerrieri emergenti dell'Orda dal suo posto a Camp Taurajo. Thun'grim Firegaze ti ha cercato appositamente, avendo sentito parlare del tuo valore e delle prove che hai superato nelle Barrens. Ruga si limita a trasmetterti la convocazione, così potrai ricevere un'armatura forgiata su misura per te.",al={"perché ruga mi manda","perché io da ruga totem rabbioso","perché ruga ha bisogno di me"}}},fp="20,226,21.244.0,19.287.0,26.204.0,39.207.0,34.77.0,43.186.0,39.54.0,44.173.0"}
P.entries["quest:183"] = {n="The Boar Hunter",s="Nella Valle Crestafredda, Talin Occhioforte chiede alle giovani reclute di sfoltire i cinghiali di rupe che minacciano i sentieri. Così i cacciatori esperti potranno seguire le tracce in pace.",h="Nella Valle Crestafredda, Talin Occhioforte chiede alle giovani reclute di sfoltire i cinghiali di rupe che...",kw={"forgiamara","the boar hunter","valle crestafredda","cinghiale di rupe","dun morogh","caccia","talin occhioforte"},ang={["class:Hunter"]="Come cacciatore, puoi seguire il semplice approccio di Talin Occhioforte: mira con precisione, rispetta le bestie e libera il sottobosco quando la selvaggina diventa ostile.",["race:Dwarf"]="La vita in montagna richiede di condividere la terra con una fauna feroce. Per un giovane nano, sfoltire i cinghiali di rupe aggressivi attorno a Forgiamara è un rito di passaggio al di fuori della forgia.",["race:Gnome"]="Per uno gnomo rifugiato appena arrivato da Gnomeregan, affrontare i feroci cinghiali di Dun Morogh è un duro primo assaggio della vita nelle aspre terre dei nani."},sec={{t="Una valle affollata",b="La Valle Crestafredda offre ai giovani montanari e agli studiosi di Forgiardente un luogo tranquillo e protetto in cui addestrarsi. Durante il rigido inverno, i piccoli cinghiali di rupe si sono moltiplicati in tutta la valle. Ora i loro attacchi minacciano chiunque percorra i sentieri innevati."},{t="Prendersi cura delle nevi",b="La caccia offre ai nani carne, pelli e pratica sul campo. Quando la selvaggina diventa numerosa e attacca a vista, l'abbattimento ripristina l'equilibrio. Sfoltendo i cinghiali di rupe sui pendii della valle, i giovani avventurieri dimostrano di essere pronti al combattimento. I cacciatori locali hanno più spazio per seguire le tracce senza essere sopraffatti."}},faq={{q="Chi è Talin Occhioforte?",a="Talin Occhioforte è un cacciatore nano di stanza nella Valle Crestafredda, vicino a Forgiamara. Segue le tracce della selvaggina nella neve e insegna agli avventurieri alle prime armi ad affrontare le bestie ostili.",al={"talin occhioforte","chi assegna la missione the boar hunter","png cacciatore di cinghiali"}},{q="Perché i cinghiali di rupe sono un problema così grande?",a="I piccoli cinghiali di rupe sono diventati insolitamente numerosi nella Valle Crestafredda e attaccano senza essere provocati. Il loro numero rende pericolosi gli spostamenti e la caccia per gli abitanti del posto.",al={"perché uccidere i cinghiali","problema cinghiali crestafredda","perché i cinghiali sono pericolosi"}},{q="Dove si possono trovare i cinghiali di rupe?",a="I piccoli cinghiali di rupe vagano nelle pianure aperte e innevate e nelle zone poco boscose attorno a Forgiamara, in tutta la Valle Crestafredda.",al={"dove sono i cinghiali","posizione cinghiale di rupe","mappa piccolo cinghiale di rupe"}},{q="Questa missione è collegata a una minaccia più grande nella valle?",a="No. I trogg tormentano gli avamposti dei nani, ma i cinghiali di rupe sono un problema legato alla fauna locale. Ridurne il numero rende i sentieri più sicuri e permette a Talin di cacciare in pace.",al={"esiste una missione successiva","catena missioni cacciatore di cinghiali","storia dietro i cinghiali"}},{q="Cosa rende i cinghiali di rupe adatti a Dun Morogh?",a="I cinghiali di rupe sono suini robusti dalla pelle spessa, capaci di sopportare le temperature gelide di Dun Morogh. L'aggressività e le zanne affilate li aiutano a cercare cibo nel terreno ghiacciato e a difendersi dai predatori delle montagne.",al={"lore cinghiale di rupe","cinghiali dei nani","fauna di dun morogh"}},{q="Perché Talin Occhioforte non uccide i cinghiali da solo?",a="Talin dice che i cinghiali aggressivi hanno reso le sue battute di caccia spiacevolmente pericolose. Chiede ai nuovi arrivati volenterosi che passano da Forgiamara di ridurne il numero, così da poter tornare a seguire le tracce come al solito.",al={"perché talin ha bisogno di aiuto","talin pigro","perché talin non può cacciarli"}}},fx={aa61ef91={q="Perché Talin Occhioforte vuole che si decimino i cinghiali delle rocce minori?",a="Per Talin Occhioforte, cacciare cinghiali è un ottimo passatempo, ma l'enorme numero di cinghiali delle rocce minori che infestano la Valle Crestafredda ha rovinato il suo svago. La loro natura aggressiva e la rapida proliferazione hanno trasformato la sua routine quotidiana in un'attività pericolosa anziché piacevole. Riducendone il numero di una dozzina, renderai la valle un po' più sicura e lui potrà godersi la caccia senza essere continuamente assalito.",al={"perché uccidere i cinghiali","motivo di talin occhioforte","perché talin vuole i cinghiali morti"}},cf0c4f7e={q="Cosa sono i cinghiali delle rocce minori e perché si trovano nella Valle Crestafredda?",a="I cinghiali delle rocce minori sono i robusti suini nativi di Dun Morogh, dotati per natura di una pelle spessa e di un carattere feroce, qualità che li aiutano a sopravvivere al gelido terreno montuoso. La Valle Crestafredda offre abbondante cibo lungo i contrafforti innevati, ma di recente la loro popolazione è cresciuta così tanto che vagano ovunque e caricano con aggressività chiunque si avvicini.",al={"cosa sono i cinghiali delle rocce","perché ci sono cinghiali qui","storia dei cinghiali delle rocce minori"}}},fp="15,143,16.234.0,17.295.0,21.165.0,38.164.0,34.116.0,57.168.0,43.204.0,49.186.0"}
P.entries["quest:1838"] = {n="Brutal Armor",s="Nelle Savane settentrionali, un guerriero affronta la prova di Thun'grim Firegaze. Il fabbro quasi cieco invia guerrieri esperti dell'Orda in terre lontane alla ricerca di ingredienti rari e agenti di fusione. Portagli ciò che richiede la sua pergamena e potrà iniziare a forgiare un set completo di brutale equipaggiamento da battaglia.",h="Nelle Savane settentrionali, un guerriero affronta la prova di Thun'grim Firegaze.",kw={"savane","brutal armor","brutal hauberk","flogisto","azurite polverosa","lingotto di ferro fumoso","thun'grim firegaze","missione guerriero"},ang={["class:Warrior"]="Come guerriero dell'Orda, dimostri il tuo valore e la tua resistenza in più continenti per ottenere un'armatura da battaglia forgiata su misura.",["faction:Horde"]="Come membro dell'Orda, vedi fabbri Orchi, Tauren, Troll e Reietti riunire le rispettive tradizioni artigiane in un unico set da battaglia.",["profession:Blacksmithing"]="Come fabbro, puoi vedere come la pergamena di Thun'grim combina ferro fumante, Azurite Polverosa e flogisto per perfezionare la fusione del ferro comune."},sec={{t="La chiamata del maestro",b="Nelle Savane settentrionali, Thun'grim Firegaze attende notizie di guerra. La vista del veterano fabbro orco si sta indebolendo, eppure nessuna mano alla forgia è più abile della sua. Gli giungono voci di un guerriero la cui forza e il cui valore superano quelli dei comuni soldati. Così Thun'grim si propone di forgiare un'armatura di maglia adatta alle battaglie più feroci di Kalimdor e dei Regni Orientali."},{t="Una ricerca transcontinentale",b="L'armatura di Thun'grim richiede più del comune minerale. Alla luce del fuoco, i suoi occhi indeboliti lo guidano mentre redige una pergamena dettagliata per il pettorale principale. Richiede ferro raffinato, lingotti di ferro fumante trasportati da coboldi scavatori, Azurite Polverosa lavorata da minatori oltre il mare e una volatile Fiala di Flogisto. Solo un guerriero pronto ad affrontare prove in terre lontane può raccogliere tutti i materiali necessari."},{t="Il primo colpo del Martellino",b="I rari materiali di Thun'grim danno inizio a un'impresa ben più grande. Quando arrivano, accende la fornace e forgia la Brutal Hauberk. Eppure il vecchio fabbro capisce di non poter completare da solo un insieme di armamenti tanto ambizioso. Il set completo richiede abili artigiani delle altre razze dell'Orda: un forgiatore di elmi Tauren, un fabbricante di guanti Troll e un fabbro di schinieri dei Reietti, sparsi per i continenti."}},faq={{q="Chi è Thun'grim Firegaze?",a="Thun'grim Firegaze è un veterano fabbro orco che vive su una collina affacciata sulle Savane settentrionali. La sua vista si sta indebolendo, ma il suo istinto all'incudine resta acuto. Crea potenti armature di maglia da battaglia su misura per i guerrieri dell'Orda rinomati per il loro valore.",al={"chi è thungrim","storia di thun'grim firegaze","retroscena di thungrim"}},{q="Cos'è la Brutal Armor?",a="La Brutal Armor è un'armatura di maglia forgiata per la battaglia e destinata ai guerrieri esperti dell'Orda. I fabbri dell'Orda uniscono le loro abilità per creare il set, i cui pezzi richiedono viaggi pericolosi per trovare rari reagenti alchemici, minerali purificati e tecniche antiche.",al={"cos'è la brutal armor","storia del set brutal armor","serie missioni armatura guerriero"}},{q="Perché Thun'grim ha bisogno di ingredienti così insoliti?",a="A Thun'grim servono ingredienti insoliti perché il ferro comune è troppo fragile per resistere ai colpi pesanti che un campione affronta in prima linea. Usa Azurite Polverosa, lingotti di ferro fumante e flogisto volatile come fondenti e agenti di tempra, conferendo al metallo maggiore resistenza e robustezza.",al={"perché l'azurite polverosa","perché il flogisto","a cosa servono i reagenti"}},{q="Thun'grim forgia l'intero set da solo?",a="No. Thun'grim forgia l'usbergo principale, mentre altri fabbri dell'Orda realizzano l'elmo, i guanti e i gambali abbinati. Tra loro ci sono Orm Zoccolo Granitico, Ula'elek e Velora Nitely.",al={"thungrim crea tutto lui","chi crea i pezzi della brutal armor"}},{q="Dove conduce questa serie di missioni?",a="La prova porta alla forgiatura della Brutal Hauberk. Poi si apre la strada per consultare i fabbri di Picco del Tuono, del Villaggio di Sen'jin e di Sepulcra per il resto della brutale armatura di maglia da battaglia.",al={"cosa succede dopo la brutal armor","seguito brutal armor"}},{q="Perché un guerriero deve viaggiare così lontano per questi materiali?",a="Il viaggio mette alla prova la tenacia in battaglia e l'ingegno di un guerriero. Per dimostrarsi degno di un'armatura forgiata da maestri, un guerriero deve attraversare territori nemici, entrare in miniere pericolose e raccogliere componenti fuori dalla comune portata.",al={"perché viaggiare nei regni orientali","perché così tanti materiali"}}},fx={["31952f55"]={q="Perché Thun'grim Firegaze vuole creare quest'armatura?",a="Thun'grim ha sentito parlare della tua crescente fama in tutta l'Orda e desidera forgiare un'armatura degna della tua forza. Per il fabbro anziano, quasi cieco, forgiare un'armatura leggendaria per accompagnare un guerriero emergente nel suo viaggio è un onore e una testimonianza della sua maestria.",al={"perché thun'grim mi aiuta","motivo di thun'grim firegaze","perché creare brutal armor"}},["8131a754"]={q="Perché Thun'grim ha bisogno che raccolga i materiali?",a="Thun'grim è un orco anziano che ha quasi perso la vista; ha faticato per diverse notti soltanto per scrivere le tue istruzioni. Raccogliere reagenti pericolosi da miniere lontane e da bestie selvagge va ben oltre le sue capacità fisiche: serve un guerriero esperto che affronti il viaggio.",al={"perché devo raccogliere i materiali","perché io per brutal armor","perché thun'grim ha bisogno del mio aiuto"}}},fp="12,277,18.352.0,26.396.0,30.377.1,26.247.0,21.225.0,49.278.0,44.174.1,38.183.1,61.213.0"}
P.entries["quest:1839"] = {n="Ula'elek and the Brutal Gauntlets",s="Nel Villaggio di Sen'jin, Ula'elek ti aspetta per forgiare i Brutal Gauntlets. Thun'grim Firegaze ti manda dalle Savane alla costa meridionale di Durotar.",h="Nel Villaggio di Sen'jin, Ula'elek ti aspetta per forgiare i Brutal Gauntlets.",kw={"brutal gauntlets","puntascura","durotar","villaggio di sen'jin","le savane","thun'grim firegaze","ula'elek","guerriero"},ang={["class:Warrior"]="Come guerriero dell'Orda, assemblare il set Brutal Armor segna il tuo cammino verso il ruolo di campione temprato dalle battaglie in prima linea.",["faction:Horde"]="Come membro dell'Orda, vedi i fabbri orchi nelle Savane e i fabbri troll a Durotar lavorare insieme. La loro arte tiene unita la giovane coalizione di Thrall.",["race:Troll"]="Come troll, vedi come l'arte di fabbro Puntascura di Ula'elek e la sua sintonia con gli spiriti sostengono lo sforzo bellico dell'Orda."},sec={{t="Un viaggio verso la costa",b="Thun'grim Firegaze ti manda a est dopo che hai dimostrato il tuo valore nelle Savane e iniziato ad assemblare il set Brutal Armor. L'esperto fabbro orco si affida ad abili artigiani nelle terre dell'Orda per forgiarne i pezzi. Per i guanti di maglia pesante, ti manda sulla costa rocciosa meridionale di Durotar."},{t="Gli occhi dei Loa",b="Nel Villaggio di Sen'jin, l'armaiolo troll Ula'elek lavora tra i suoi simili Puntascura. Thun'grim gli ha raccontato le tue gesta, e Ula'elek dice che gli spiriti hanno osservato i tuoi trionfi in battaglia. Per un guerriero che cerca un posto tra l'élite dell'Orda, l'abilità artigianale e il riconoscimento spirituale vanno di pari passo."}},faq={{q="Chi assegna la missione Ula'elek and the Brutal Gauntlets?",a="Thun'grim Firegaze, un armaiolo orco sulle cime delle montagne nelle Savane, ti manda a procurarti i guanti.",al={"datore di missione","chi avvia ula'elek and the brutal gauntlets","missione thun'grim firegaze"}},{q="Dove posso trovare Ula'elek?",a="Ula'elek lavora nel Villaggio di Sen'jin, sulla costa meridionale di Durotar.",al={"posizione ula'elek","dov'è ula'elek","ulaelek senjin"}},{q="Cos'è il set Brutal Armor?",a="Brutal Armor è un set di maglia su misura per guerrieri esperti dell'Orda intorno alla loro trentesima stagione. Fabbri alleati in tutta Kalimdor ne realizzano i pezzi.",al={"brutal armor","cosa sono i brutal gauntlets","armatura di classe guerriero 30"}},{q="Cosa succede dopo aver raggiunto Ula'elek?",a="Dopo averti accolto e aver riconosciuto le tue gesta in battaglia, Ula'elek ti chiede di raccogliere materiali esotici per i Brutal Gauntlets, cominciando dai Satyr Hooves.",al={"missione successiva","dopo aver parlato con ula'elek","missione satyr hooves"}},{q="Perché Thun'grim ti manda da un armaiolo troll?",a="Thun'grim suddivide la forgiatura del set Brutal Armor tra i migliori fabbri specializzati dell'Orda. L'artigiano Puntascura Ula'elek realizza i guanti.",al={"perché ula'elek","perché andare al villaggio di sen'jin","fabbro troll brutal armor"}},{q="I giocatori dell'Alleanza hanno una missione equivalente?",a="I guerrieri dell'Alleanza affrontano una prova marziale simile per realizzare un'armatura specifica per la loro classe. La serie di missioni Brutal Armor e il lavoro di Ula'elek appartengono all'Orda.",al={"brutal gauntlets alleanza","equivalente per l'alleanza"}}},fx={a664db53={q="Perché Thun'grim Firegaze ha bisogno che tu vada al Villaggio di Sen'jin?",a="Thun'grim Firegaze guida la tua crescita come guerriero emergente dell'Orda. Mentre supervisiona il tuo addestramento, l'antica arte di forgiare Brutal Armor richiede le capacità specialistiche di altri artigiani nelle terre dell'Orda. Ula'elek, al Villaggio di Sen'jin, è un abile armaiolo dei Lanciascura, in sintonia con gli spiriti e adatto a forgiare i guanti. Thun'grim ti manda di persona non solo per commissionare il pezzo, ma anche per dimostrare la tua dedizione e conquistare direttamente la fiducia dell'armaiolo.",al={"perché io da ula'elek","perché thun'grim non può forgiare i guanti","perché mandare il guerriero a durotar"}}},fp="33,148,22.282.0,19.294.0,54.98.0,26.62.0,29.140.0,37.157.0,50.147.0,53.141.0"}
P.entries["quest:184"] = {n="Atto dei Ciglioarcuato",s="Il Contadino Ciglioarcuato e Verna sono stati cacciati dalla loro fattoria, mentre i Banditi Defias portano la loro concessione terriera attraverso la Foresta di Elwynn. Restituiscila al Contadino Ciglioarcuato vicino al confine delle Marche Occidentali, e la coppia manterrà il diritto alla proprietà sottratta.",h="Il Contadino Ciglioarcuato e Verna sono stati cacciati dalla loro fattoria, mentre i Banditi Defias portano...",kw={"defias","elwynn","ciglioarcuato","theodore ciglioarcuato","verna ciglioarcuato","marche occidentali","atto marche occidentali"},ang={["class:Paladin"]="Come paladino, restituire un atto di proprietà rubato a dei profughi onora i tuoi sacri voti di difendere gli indifesi e portare giustizia nelle terre di confine senza legge.",["faction:Alliance"]="La difficile situazione dei Ciglioarcuato mostra che la corona di Roccavento non è riuscita a proteggere i cittadini che pagano le tasse oltre le mura fortificate della capitale."},sec={{t="Un Indizio su carta rubata",b="Un atto di proprietà firmato da Theodore e Verna Ciglioarcuato viene ritrovato tra i Banditi Defias a Elwynn. Sul retro, una nota sgrammaticata dice che i banditi hanno cacciato l'anziano contadino dalla sua proprietà. Hanno portato l'atto oltre il fiume, a Elwynn, per copiarlo e falsificare rivendicazioni su altre terre occupate. La nota colloca i Ciglioarcuato bloccati appena oltre il confine, lungo la strada, dopo che il loro carro si è rotto."},{t="La difficile situazione dei contadini delle Marche Occidentali",b="I Defias hanno cacciato decine di famiglie delle Marche Occidentali dalle loro terre ancestrali. Usano la forza e false rivendicazioni per impadronirsi di altre fattorie per la Fratellanza, mentre Theodore e Verna abbandonano la propria per mettersi al sicuro. Il loro legittimo atto di proprietà ne tutela i diritti, qualora l'ordine dovesse tornare nella provincia."}},faq={{q="Dove trovo questo atto?",a="I banditi della Fratellanza dei Defias portano con sé l'atto nella Foresta di Elwynn meridionale e occidentale, anche vicino al Molo di Jerod e negli accampamenti locali.",al={"ottenimento atto","come ottenere l'atto dei ciglioarcuato","dove si trova l'atto"}},{q="Dov'è il Contadino Ciglioarcuato?",a="Il Contadino Ciglioarcuato e sua moglie Verna sono bloccati accanto al loro carro rotto sulla strada principale, appena dentro le Marche Occidentali, poco dopo il ponte che attraversi dirigendoti a ovest dalla Foresta di Elwynn.",al={"posizione ciglioarcuato","dove consegnare l'atto dei ciglioarcuato","dove si trova il contadino"}},{q="Perché i Defias volevano l'atto?",a="Una nota sul retro dice che i banditi intendono copiare il legittimo atto di proprietà di Ciglioarcuato e falsificare rivendicazioni su altre proprietà. I documenti falsi rafforzerebbero il loro controllo sulle fattorie sottratte.",al={"perché i banditi hanno rubato l'atto","perché i defias vogliono gli atti"}},{q="I Ciglioarcuato torneranno alla loro fattoria?",a="La coppia sta fuggendo dalla regione a causa dell'illegalità e degli attacchi dei banditi. Conservare l'atto permette loro di reclamare legalmente la propria terra, se mai le Marche Occidentali verranno pacificate.",al={"i ciglioarcuato torneranno a casa","cosa succede alla fattoria dei ciglioarcuato"}},{q="Perché Roccavento non protegge queste fattorie?",a="La protezione di Roccavento si è indebolita tra l'improvvisa scomparsa di re Varian Wrynn e le tensioni politiche interne. Con le risorse della corona concentrate sulla capitale, i territori periferici come le Marche Occidentali sono lasciati ad affrontare la crescente forza della Fratellanza dei Defias.",al={"perché non ci sono guardie nelle marche occidentali","perché roccavento ignora le marche occidentali"}},{q="Qual è il collegamento tra Elwynn e le Marche Occidentali in questa missione?",a="La rete dei Defias si estende dalla Foresta di Elwynn fin oltre il fiume, nelle Marche Occidentali. La sua presenza laggiù mostra quanto si sia addentrata nei territori centrali del regno.",al={"perché l'atto era a elwynn","collegamento tra zone"}}},fx={["9b306b68"]={q="Perché dovrei restituire l'Atto dei Ciglioarcuato?",a="L'atto in sé è solo un pezzo di carta inanimato, ma il messaggio scarabocchiato sul retro rivela che dei furfanti dei Defias hanno intimidito Theodore e Verna Ciglioarcuato, costringendoli a cedere le loro terre. I ladri volevano usarlo come modello per contraffare rivendicazioni su altre proprietà. Riportandolo ai Ciglioarcuato in fuga, darai a un'onesta famiglia di contadini l'unica prova di proprietà che le è rimasta e la speranza di poter un giorno rivendicare la propria eredità rubata, se la pace tornerà mai nelle Marche Occidentali.",al={"perché restituire l'atto","motivo dell'atto delle marche occidentali","scopo dell'atto dei ciglioarcuato"}}},fp="15,233,22.376.0,32.287.0,26.131.0,25.172.0,52.174.0,42.161.0,43.239.0,65.165.0"}
P.entries["quest:1840"] = {n="Orm Stonehoof and the Brutal Helm",s="A Picco del Tuono, Orm Zoccolo Granitico può forgiare il Brutal Helm. Thun'grim Firegaze gli manda i guerrieri per questo lavoro.",h="A Picco del Tuono, Orm Zoccolo Granitico può forgiare il Brutal Helm.",kw={"missione armatura","brutal helm","orm zoccolo granitico","thun'grim firegaze","picco del tuono","guerriero"},ang={["class:Warrior"]="Come guerriero, vieni mandato da uno dei migliori maestri fabbri dell'Orda per ottenere una pesante protezione per la testa.",["faction:Horde"]="Come membro dell'Orda, vedi i maestri d'armi orcheschi delle Savane collaborare con gli artigiani tauren sulle alture di Picco del Tuono."},sec={{t="Una raccomandazione di ferro",b="I guerrieri che dimostrano il proprio valore e raccolgono pezzi della Brutal Armor nelle Savane vengono mandati a Picco del Tuono. Thun'grim Firegaze è un abile fabbro d'armature, ma il lavoro ha superato le sue capacità. Perciò indirizza i guerrieri da Orm Zoccolo Granitico, la cui abilità è nota in tutta Kalimdor. Orm sa creare elmi robusti usando rari trofei ricavati da bestie feroci."},{t="L'artigiano vicino alla pozza",b="Orm Zoccolo Granitico vive e lavora sulle alte rupi di Mulgore, vicino allo stagno sotto il grande totem centrale di Picco del Tuono. Quando un guerriero arriva su raccomandazione di Thun'grim Firegaze, Orm mette da parte il suo lavoro abituale. Gli parla dei componenti difficili da procurare, necessari per forgiare un elmo degno delle prime linee dell'Orda."}},faq={{q="Chi è Orm Zoccolo Granitico?",a="Orm Zoccolo Granitico è un abile fabbro d'armature tauren che vive a Picco del Tuono. Thun'grim Firegaze gli manda i guerrieri per la sua abilità nel forgiare elmi da battaglia.",al={"orm zoccolo granitico","chi è orm"}},{q="Dove si trova Orm Zoccolo Granitico?",a="Orm Zoccolo Granitico lavora vicino allo stagno sotto il grande totem centrale di Picco del Tuono.",al={"dove si trova orm","posizione orm zoccolo granitico","trova orm"}},{q="Perché Thun'grim Firegaze ti manda a Picco del Tuono?",a="Thun'grim Firegaze sa creare la corazza e altri pezzi del completo Brutal, ma Orm Zoccolo Granitico ha l'abilità necessaria per forgiare il Brutal Helm.",al={"perché picco del tuono","perché vedere orm"}},{q="Cos'è il Brutal Helm?",a="Il Brutal Helm è un copricapo forgiato per i guerrieri dell'Orda ormai divenuti veterani. Richiede materiali pericolosi provenienti da bestie di tutta Kalimdor.",al={"missione brutal helm","cos'è brutal helm"}},{q="Cosa chiede Orm dopo?",a="Orm Zoccolo Granitico ti chiede di raccogliere trofei di bestie per l'elmo, a cominciare da un Chimaeric Horn di una chimera selvatica.",al={"prossima missione","dopo orm zoccolo granitico","missione chimaeric horn"}},{q="Qualsiasi classe può intraprendere questa missione?",a="No. Questa serie di missioni è destinata ai guerrieri con un addestramento marziale avanzato che hanno completato il lavoro iniziale di Thun'grim sulle armature.",al={"è solo per guerrieri","chi può fare questa missione"}}},fx={["528c5ae8"]={q="Perché Thun'grim Firegaze vuole che tu vada da Orm Zoccolo Granitico?",a="Thun'grim Firegaze ti ha aiutato a guidare il tuo addestramento da guerriero, ma per forgiare un Brutal Helm serve un artigiano esperto, la cui abilità superi quella di un comune fabbro. Riconoscendo l'incomparabile maestria di Orm Zoccolo Granitico nella lavorazione del metallo e delle ossa, Thun'grim ti manda dal mastro artigiano tauren a Picco del Tuono, così potrai guadagnarti un pezzo d'armatura degno della tua forza crescente e del tuo servizio all'Orda.",al={"motivo di thun'grim firegaze","perché mandarmi da orm zoccolo granitico","motivo di thun'grim per il brutal helm"}}},fp="33,113,24.351.0,23.298.0,21.152.0,33.78.0,54.136.0,24.149.0,27.115.1,30.115.0"}
P.entries["quest:1841"] = {n="Velora Nitely and the Brutal Legguards",s="Oltre il Grande Mare, Thun'grim Firegaze manda i guerrieri dell'Orda a cercare Velora Nitely e i Gambali Foderati Brutali. A Sepulcra, la fabbra dei Reietti forgia l'armatura grazie all'arte che ha conservato dalla sua vita mortale. Il suo lavoro contribuisce a completare un'armatura resistente per i guerrieri dell'Orda.",h="Oltre il Grande Mare, Thun'grim Firegaze manda i guerrieri dell'Orda a cercare Velora Nitely e i Gambali...",kw={"brutal armor","gambali foderati brutali","lordaeron","thun'grim firegaze","trade quarter","sepulcra","velora nitely","missione guerriero"},ang={["class:Warrior"]="Come guerriero, raggiungi una tappa importante nelle prove dell'armatura dell'Orda intorno al livello trenta, viaggiando oltre Kalimdor per ottenere un'armatura specifica per la tua classe.",["faction:Horde"]="Come membro dell'Orda, partecipi a un lavoro che unisce orchi, troll e tauren di Kalimdor agli artigiani Reietti dei Regni Orientali.",["race:Undead"]="Come Reietto, puoi vedere Velora Nitely portare avanti le raffinate abilità e l'eredità artistica della caduta Lordaeron."},sec={{t="Un viaggio attraverso il mare",b="Thun'grim Firegaze ti manda a est, oltre il Grande Mare, a cercare una fabbra per i Gambali Foderati Brutali. Hai dimostrato il tuo valore al fabbro veterano durante la sua veglia nelle Savane, e ora lui ti indirizza verso la leggendaria Brutal Armor. Thun'grim non può realizzare l'intera armatura da solo, quindi si affida ad abili alleati in tutta l'Orda. I gambali richiedono un'artigiana il cui lavoro era venerato prima della caduta dell'umanità settentrionale, nel regno sotterraneo dei Reietti."},{t="L'arte di Velora Nitely",b="Velora Nitely lavora nel Trade Quarter di Sepulcra, dove la sua antica arte è ancora al servizio dell'Orda. Prima che lo Scourging del nord ponesse fine alla sua vita mortale, era una delle più illustri fabbre d'armature del Regno di Lordaeron. La sua terra natale fu corrotta e lei divenne una dei Reietti. La morte non le tolse la sua maestria nella lavorazione del metallo. Ora mette la sua abilità umana al servizio dei guerrieri dell'Orda, con un umorismo asciutto e macabro sulla propria condizione di non morta."}},faq={{q="Chi è Velora Nitely?",a="Velora Nitely era un tempo celebrata come una delle migliori fabbre d'armature del regno di Lordaeron. Dopo la Third War, risorse come una dei Reietti e si stabilì nel Trade Quarter di Sepulcra, dove ancora esercita il suo mestiere per l'Orda.",al={"storia di velora nitely","chi è velora","fabbra reietta velora"}},{q="Perché Thun'grim mi manda a Sepulcra?",a="Thun'grim Firegaze ti manda a Sepulcra perché il completo della Brutal Armor richiede abili artigiani di tutta l'Orda. Conosce la reputazione di Velora come fabbra d'armature e ti manda a Lordaeron per commissionarle i gambali.",al={"perché andare a sepulcra","missione thun'grim sepulcra","guerriero dalle savane a sepulcra"}},{q="Dove posso trovare Velora Nitely a Sepulcra?",a="Velora Nitely lavora nel Trade Quarter di Sepulcra, alle forge, tra fabbri e altri maestri artigiani al servizio di Dama Sylvanas Ventolesto.",al={"posizione di velora nitely","dov'è velora nitely","trovare velora nitely"}},{q="Cosa succede dopo aver parlato con Velora Nitely?",a="Velora ti chiede di raccogliere tibie dagli orchi Fauce del Drago nelle Paludi Grigie per i tuoi Gambali Foderati Brutali.",al={"prossima missione dopo velora","missione stinchi fauce del drago","cosa vuole velora"}},{q="Velora ha qualche dialogo sul suo essere non morta?",a="Sì. Velora scherza con umorismo asciutto, chiedendosi se sia lei a fare l'armatura per te o il contrario. Dice di aver perso il senso dell'umorismo più o meno quando ha perso l'olfatto e ha smesso di respirare.",al={"battute di velora","dialogo fabbro non morto","umorismo di velora"}},{q="La Brutal Armor è solo per i guerrieri?",a="Sì. Le prove della Brutal Armor, compresa la ricerca di Velora Nitely per i gambali, sono destinate ai guerrieri dell'Orda che avanzano tra i ranghi più esperti.",al={"altre classi possono ottenere la brutal armor","missione solo guerriero brutal armor"}}},fx={["7eb107f7"]={q="Perché Thun'grim Firegaze vuole che tu lo faccia?",a="Thun'grim Firegaze ti sta aiutando a forgiare il tuo completo Brutal Armor, un rito che segna i progressi marziali dei guerrieri promettenti dell'Orda. Thun'grim può creare da sé diversi componenti, ma la lavorazione specializzata richiesta per i Gambali Foderati Brutali supera le tecniche della sua forgia, perciò ti manda da Velora Nitely, rinomata come una delle migliori fabbrai di armature di Lordaeron.",al={"motivo di thun'grim firegaze","perché fabbricare i gambali foderati brutali","perché mandarmi da velora nitely"}}},fp="38,276,24.449.0,29.426.0,21.257.0,40.228.0,48.145.0,43.98.1,49.198.0,34.141.0"}
P.entries["quest:1842"] = {n="Satyr Hooves",s="Al Villaggio di Sen'jin, Ula'elek manda i guerrieri a nord, a Valtetra, in cerca di Satyr Hooves. Ha bisogno del loro strano potere per forgiare guanti brutali.",h="Al Villaggio di Sen'jin, Ula'elek manda i guerrieri a nord, a Valtetra, in cerca di Satyr Hooves.",kw={"valtetra","brutal gauntlets","durotar","zoccoli","satiro","villaggio di sen'jin","ula'elek","non fesso"},ang={["class:Warrior"]="Come guerriero, affronti astuti demoni esperti nelle imboscate nel tuo rito di avanzamento. La prova mette alla prova la tua resistenza in battaglia e ti fa guadagnare un'armatura personalizzata.",["faction:Horde"]="Come guerriero dell'Orda, lasci le aride pianure di Durotar e ti addentri nel conteso territorio degli Elfi della Notte a Valtetra.",["race:Troll"]="Come troll, puoi riconoscere l'arte dei Puntascura nei metodi di Ula'elek. Estrae essenza grezza dai nemici magici abbattuti, anziché affidarsi soltanto alle tecniche di forgiatura convenzionali."},sec={{t="Imbrigliare l'Essenza Corrotta",b="Ula'elek ti manda negli antichi boschi di Valtetra a raccogliere ciò che gli serve per il suo lavoro. La corruzione demoniaca permea ancora le congreghe di satiri di quei luoghi. Per un'armatura capace di rivaleggiare con le forze più feroci di Kalimdor, gli occorrono più che ferro e cuoio."},{t="Il Gonfiore della Magia di Valtetra",b="Nel nord-est di Valtetra, i satiri si nutrono della purezza che ancora permane nella foresta e la trasformano in un potere immondo. A quelli che ne assorbono di più crescono zoccoli gonfi, privi della consueta fenditura. Ula'elek intende estrarre quella magia concentrata e intesserla nei suoi guanti."}},faq={{q="Perché Ula'elek ha bisogno degli zoccoli di satiro?",a="A Ula'elek servono gli zoccoli per potenziare i guanti brutali che sta realizzando. Intende estrarre la magia della foresta che i satiri hanno prosciugato e corrotto.",al={"perché zoccoli di satiro","scopo zoccoli","a cosa servono gli zoccoli"}},{q="Dove si trovano i satiri?",a="I satiri dimorano nel nord-est di Valtetra, tra antiche rovine corrotte. Lì prosciugano la magia che ancora permane nel folto della foresta.",al={"dove sono i satiri","posizione satiri","dove trovare zoccoli di satiro"}},{q="Cosa rende speciale uno zoccolo non fesso?",a="Uno zoccolo privo di fenditura contraddistingue un satiro che si è rimpinzato della magia pura di Valtetra. Il potere rubato gli gonfia i piedi.",al={"storia zoccoli non fessi","perché non fessi","zoccoli gonfi"}},{q="Chi è Ula'elek?",a="Ula'elek è un abile artigiano di armature, un troll Puntascura del Villaggio di Sen'jin, nel sud di Durotar. Aiuta i guerrieri a creare l'equipaggiamento delle loro prove.",al={"chi è ulaelek","datore di missione","troll a senjin"}},{q="Che armatura sta forgiando Ula'elek?",a="Ula'elek sta preparando un paio di Brutal Gauntlets. Questa pesante protezione per le mani è infusa di magia rubata ed è destinata ai guerrieri emergenti dell'Orda.",al={"cosa sono i brutal gauntlets","missione guanti","armatura ricompensa"}},{q="I satiri di questi luoghi servono la Legione Infuocata?",a="Sì. I satiri sono antichi Elfi della Notte trasformati da patti demoniaci. Le congreghe che ancora dimorano nei boschi di Kalimdor continuano a usare la corruzione vile al servizio di potenze demoniache.",al={"lealtà satiri","i satiri servono la legione"}}},fx={["749a1d7b"]={q="Perché i satiri si trovano nel nord-est di Valtetra?",a="I satiri infestano il nord-est di Valtetra per saziarsi della purezza dell'antica foresta. Attingendo ai suoi incantesimi latenti e corrompendoli, potenziano i loro riti malvagi e deformano i propri corpi. Quelli che si nutrono più avidamente della magia naturale di Valtetra sviluppano zoccoli grotteschi, gonfi e privi di fessure, diventando ricettacoli viventi di forza arcana concentrata.",al={"perché i satiri a valtetra","storia degli zoccoli dei satiri","chi cacciare per gli zoccoli"}}},fp="12,136,28.233.0,30.265.0,36.148.0,27.122.0,36.127.0,16.130.0,31.126.0,44.167.0"}
P.entries["quest:1843"] = {n="Guanti Lunghi Brutali",s="A Durotar, Ula'elek ha completato i Brutal Gauntlets per un guerriero veterano dell'Orda. Nella lavorazione ha impiegato materiali rari provenienti da terre lontane, per onorare sia l'artefice sia chi li indossa.",h="A Durotar, Ula'elek ha completato i Brutal Gauntlets per un guerriero veterano dell'Orda.",kw={"forgiatura di armature","brutal gauntlets","durotar","orda","satyr hooves","ula'elek","armatura da guerriero"},ang={["class:Warrior"]="Come guerriero, indossi guanti realizzati per intensi combattimenti in mischia. Segnano un passo verso un ruolo di comando improntato alla disciplina marziale.",["faction:Horde"]="Come membro dell'Orda, porti in battaglia la tradizione e l'orgoglio marziale dei tuoi artigiani. Il loro lavoro racchiude un significato spirituale e onore."},sec={{t="Il capolavoro di un artigiano",b="A Durotar, Ula'elek infonde il retaggio della sua stirpe e la sua abilità nell'armatura destinata a un guerriero veterano della prima linea. Modella guanti brutali con trofei induriti sottratti a nemici pericolosi. L'armatura finita può resistere a colpi feroci e potenziare gli attacchi di chi la indossa."},{t="Onore ancestrale",b="Tra gli orchi e i troll, armi e armature di pregevole fattura portano in battaglia il prestigio della forgia e lo spirito dell'artefice. Quando Ula'elek presenta i guanti finiti, affida a un guerriero l'eredità dei propri antenati. Si aspetta che il campione che li indossa onori quella maestria con coraggio, disciplina marziale e forza."}},faq={{q="Chi è Ula'elek?",a="Ula'elek è un artigiano di Durotar che realizza armature su misura per i guerrieri dell'Orda. Richiede materiali esotici affinché il suo lavoro onori il suo mestiere e le tradizioni ancestrali.",al={"ulaelek","chi dà brutal gauntlets","consegnatario della missione"}},{q="Perché erano necessari i Satyr Hooves per questi guanti?",a="I Satyr Hooves sono rigonfi e non fessi, e custodiscono un potere sottratto alla magia di Valtetra. Ula'elek estrae quel potere e lo infonde nei guanti, conferendo loro una grande forza magica.",al={"perché i satyr hooves","parti dei satiri","materiali usati"}},{q="Cosa significa per Ula'elek indossare i guanti?",a="Per Ula'elek, i guanti sono la massima espressione della sua arte. Donarli a un guerriero degno onora il suo mestiere e i suoi antenati, e lega il suo lavoro alle vittorie dell'Orda in battaglia.",al={"onorare gli antenati","onore di ula'elek"}},{q="Dove si svolge questo compito?",a="La forgiatura si conclude a Durotar, l'arida patria degli orchi e dei troll Puntascura. Qui Ula'elek esamina i materiali recuperati e presenta l'armatura finita.",al={"posizione","dove si consegna brutal gauntlets"}},{q="Questa prova è destinata a tutti gli avventurieri?",a="La prova è destinata ai guerrieri di prima linea che hanno dimostrato resistenza e dedizione alle arti marziali. Segna il loro passaggio a ruoli di combattimento più esperti all'interno dell'Orda.",al={"è solo per guerrieri","requisito di classe"}},{q="Cosa succede dopo aver ricevuto i guanti?",a="Ricevere i guanti completa questa prova di artigianato. Il guerriero è equipaggiato per affrontare minacce maggiori sui campi di battaglia di Azeroth, devastati dalla guerra.",al={"prossima missione","seguito di brutal gauntlets"}}},fp="16,172,25.252.0,15.308.0,16.160.0,49.172.0,52.179.0,32.161.0,43.165.0,41.142.0"}
P.entries["quest:1844"] = {n="Chimaeric Horn",s="Nella Valle Bruciata, una matriarca chimera sofferente mette alla prova la forza e la pietà di un guerriero dell'Orda. Orm Zoccolo Granitico ha bisogno del suo corno per il Brutal Helm, e la caccia dimostrerà la determinazione del guerriero.",h="Nella Valle Bruciata, una matriarca chimera sofferente mette alla prova la forza e la pietà di un guerriero...",kw={"brutal helm","valle bruciata","matriarca chimera","chimaeric horn","corno galvanizzato","orm zoccolo granitico","vette di petrartiglio","picco del tuono","missione guerriero"},ang={["class:Warrior"]="Come guerriero, dimostri la tua abilità dando la caccia a una bestia alfa solitaria in un luogo brutale. Questo ti fa guadagnare il diritto di indossare il Brutal Helm.",["faction:Horde"]="Come membro dell'Orda, viaggi dal Rifugio Roccia del Sole alle terre selvagge contese delle Vette di Petrartiglio. Lì forgi le armi necessarie per la difesa di Kalimdor.",["race:Tauren"]="Come tauren, cogli la riverenza nelle parole di Orm Zoccolo Granitico. Anche in battaglia, porre fine alle sofferenze di una bestia tormentata onora Earth Mother."},sec={{t="Una Prova di Determinazione",b="Orm Zoccolo Granitico forgerà il Brutal Helm per i guerrieri dell'Orda, ma la tradizione richiede una prova prima che inizi. Metallo e monete non bastano. Un guerriero deve dimostrare la propria abilità marziale e affrontare le cicatrici lasciate da un conflitto devastante."},{t="Le Cicatrici della Valle Bruciata",b="La Valle Bruciata si trova nella parte sud-occidentale delle Vette di Petrartiglio, sepolta dalla cenere. Un tempo rigogliosa e verde, la valle è stata ridotta dalle fiamme a una landa desolata e fumante. Le bestie vagano ancora tra i suoi crateri coperti di fuliggine, stravolte dal dolore e dalla furia. Possenti chimere nidificano tra alberi morti e sfiati di vapore rovente."},{t="Pietà in Combattimento",b="Per il fabbro tauren, il corno della matriarca chimera è necessario per l'elmo e dimostra la forza di un guerriero. Ma la caccia pone anche fine al suo tormento. Abbattendo la matriarca, il guerriero concede pietà a uno spirito selvaggio reso folle dalla distruzione della sua dimora."}},faq={{q="Chi è Orm Zoccolo Granitico?",a="Orm Zoccolo Granitico è un abile fabbro tauren di Picco del Tuono che aiuta i guerrieri veterani dell'Orda a forgiare le loro armature di classe, incluso il Brutal Helm.",al={"storia di orm zoccolo granitico","chi è orm zoccolo granitico","fabbro orm picco del tuono"}},{q="Perché Orm vuole il Corno Galvanizzato?",a="Orm vuole il Corno Galvanizzato perché è un componente resistente del Brutal Helm. Procurarselo dimostra anche che il guerriero ha avuto il coraggio di rintracciare e sconfiggere un pericoloso predatore alfa su un terreno insidioso.",al={"uso del corno galvanizzato","perché ottenere il corno galvanizzato","corno brutal helm"}},{q="Cosa sono le chimere nelle Vette di Petrartiglio?",a="Le chimere sono grandi bestie alate a due teste originarie di Kalimdor. Il fuoco e la distruzione nella Valle Bruciata hanno fatto impazzire le chimere sopravvissute, rendendole violente.",al={"chimere delle vette di petrartiglio","storia delle chimere","cosa sono le chimere"}},{q="Come si inserisce questa missione nell'addestramento del guerriero?",a="Intorno alla loro trentesima stagione, i guerrieri dell'Orda si rivolgono a specialisti come Orm Zoccolo Granitico per affrontare prove pericolose. Superandole, si guadagnano il diritto di indossare il pesante completo irto di spuntoni Brutal Armor, creato per i campioni del campo di battaglia.",al={"serie di missioni brutal helm guerriero","missione guerriero livello trenta picco del tuono","serie missioni brutal armor"}},{q="Perché Orm definisce la caccia come un atto di pietà?",a="La cultura tauren onora l'armonia con la terra e le sue creature. Gli abitanti della Valle Bruciata soffrono per la devastazione della loro terra, quindi uccidere la matriarca è visto come la fine del suo dolore incessante, non come un massacro insensato.",al={"perché pietà per la matriarca","liberala dalla sua miseria"}}},fx={["3a1b9e89"]={q="A cosa serve il Corno Galvanizzato?",a="Il Corno Galvanizzato ha un duplice scopo per Orm Zoccolo Granitico. Sul piano materiale, fornisce il formidabile corno indurito necessario per forgiare il tuo Brutal Helm. Sul piano rituale, dimostra che hai osato avventurarti nelle distese cineree della Valle Bruciata, affrontato una matriarca delle chimere impazzita e dimostrato sia la tua forza marziale sia la misericordia di concederle la liberazione.",al={"uso del corno galvanizzato","perché mi serve il corno galvanizzato","corno galvanizzato per il brutal helm"}},["241e9666"]={q="Chi ti mandano a cacciare nella Valle Bruciata?",a="Ti mandano a cacciare una matriarca delle chimere che dimora tra le rovine della Valle Bruciata. Un tempo rigogliosa valle d'altopiano, fu devastata dal fuoco, facendo impazzire di dolore e disperazione le bestie sopravvissute. La matriarca è uno di questi maestosi predatori, condannata a soffrire senza tregua tra le ceneri contaminate, finché non le concederai una fine onorevole.",al={"matriarca delle chimere da cacciare","chi uccidere nella valle bruciata","bersaglio per il chimaeric horn"}},c3120874={q="Perché Orm manda te invece di andarci di persona?",a="Orm Zoccolo Granitico sta mettendo alla prova il tuo animo, non ti sta affidando una commissione di routine. Il Brutal Helm è un'armatura tradizionale e potente, riservata ai guerrieri che hanno dimostrato determinazione, valore marziale e capacità di concedere misericordia con onore. Cacciando la bestia di persona nelle ostili distese della Valle Bruciata, dimostrerai a Orm di essere degno di indossare un'opera della sua maestria.",al={"perché orm manda me","perché orm non può cacciare la matriarca","perché orm ha bisogno di un avventuriero"}}},fp="14,196,17.218.0,29.281.0,15.257.0,21.146.0,38.193.0,33.157.0,46.227.0,47.231.0"}
P.entries["quest:1845"] = {n="Elmo Brutale",s="A Picco del Tuono, Orm Zoccolo Granitico conclude la prova del guerriero con il Brutal Helm. Dopo aver raccolto rari trofei di bestie in tutta Kalimdor, un aspirante guerriero riceve un elmo cornuto come riconoscimento della sua forza.",h="A Picco del Tuono, Orm Zoccolo Granitico conclude la prova del guerriero con il Brutal Helm.",kw={"brutal helm","chimaeric horn","madre terra","altura dei cacciatori","orm zoccolo granitico","picco del tuono","guerriero"},ang={["class:Warrior"]="Come guerriero dell'Orda, superi un rito fondamentale e indossi un'armatura pesante forgiata con materiali ricavati da bestie feroci e benedetta da istruttori veterani.",["faction:Horde"]="Sotto lo stendardo dell'Orda, dimostri la resistenza fisica e l'abilità nella caccia richieste dai tuoi capi.",["race:Tauren"]="A Picco del Tuono, il tuo elmo riflette la tradizione tauren di trasformare i trofei di caccia in equipaggiamento protettivo da guerra sotto la grazia della Madre Terra."},sec={{t="Il rito di un guerriero",b="Orm Zoccolo Granitico è un severo fabbro di Picco del Tuono che guida i guerrieri dell'Orda attraverso duri riti di passaggio. Le prove mettono alla prova la loro abilità in battaglia. Gli iniziati cacciano creature pericolose in terre insidiose e ne ricavano rari trofei. Solo chi soddisfa gli elevati requisiti di Orm può presentarsi al suo cospetto per completare la propria armatura."},{t="Il dono della Madre Terra",b="Il guerriero dimostra la propria determinazione nelle terre selvagge portando a Orm Zoccolo Granitico un raro corno di chimera. In cambio, Orm gli consegna il Brutal Helm, un pesante elmo di maglia forgiato per onorare la bestia e rafforzare chi lo indossa in prima linea. Mentre consegna l'elmo, Orm invoca la benedizione della Madre Terra. Guarda alle grandi imprese che il guerriero è destinato a compiere in tutta Azeroth."}},faq={{q="Chi offre il Brutal Helm?",a="Orm Zoccolo Granitico, un fabbro tauren di Picco del Tuono, consegna il Brutal Helm ai guerrieri dell'Orda che completano le sue prove.",al={"chi dà brutal helm","png brutal helm","missione orm zoccolo granitico"}},{q="Quale compito deve essere completato prima di ricevere l'elmo?",a="Prima di ricevere l'elmo, completi la prova chiamata Chimaeric Horn. Cacci bestie feroci nelle terre selvagge e porti il loro corno a Orm Zoccolo Granitico, a Picco del Tuono.",al={"prerequisiti per brutal helm","missione chimaeric horn"}},{q="Dove si trova Orm Zoccolo Granitico?",a="Orm Zoccolo Granitico si trova vicino allo specchio d'acqua accanto al grande totem centrale di Picco del Tuono, la città sulle alte mese.",al={"posizione orm zoccolo granitico","dove si trova orm zoccolo granitico"}},{q="Perché Orm Zoccolo Granitico invoca la Madre Terra?",a="In quanto tauren, Orm onora la Madre Terra come creatrice del mondo e sua custode spirituale. La sua benedizione sull'elmo appena completato di un guerriero riflette la convinzione dei tauren che la forza in battaglia debba essere bilanciata dalla devozione spirituale.",al={"perché menzionare la madre terra","lore madre terra"}},{q="Questa prova è aperta a qualsiasi avventuriero?",a="No. La prova e le ricompense Brutal Armor sono riservate ai guerrieri dell'Orda che dimostrano il proprio valore attraverso prove specifiche per la loro classe.",al={"chiunque può ottenere brutal helm","classe brutal helm"}},{q="Qual è il significato del set Brutal Armor?",a="I pezzi di Brutal Armor segnano il cammino di un guerriero da soldato inesperto a campione d'élite dell'Orda. Sono realizzati con materiali ricavati dai predatori più feroci di Kalimdor.",al={"lore brutal armor","perché si chiama brutal helm"}}},fx={["3a1185bd"]={q="Perché Orm Zoccolo Granitico ti ricompensa con il Brutal Helm?",a="Orm Zoccolo Granitico ti conferisce l'elmo non per un bisogno disperato o una crisi improvvisa, ma per riconoscere cerimonialmente la tua crescita marziale. Raccogliendo materiali rari da ogni parte di Kalimdor e dimostrando la tua forza nelle prove dei guerrieri, hai dimostrato di essere pronto a raccogliere l'eredità dei campioni esperti. Orm rende onore alla tua perseveranza e invoca la benedizione della Madre Terra, affinché la tua armatura ti protegga nelle battaglie ancora più grandi che ti attendono.",al={"perché orm ti dà l'elmo","motivo del brutal helm di orm zoccolo granitico","perché il brutal helm"}}},fp="11,227,16.312.0,27.358.0,27.116.0,53.168.0,31.98.0,46.223.0,37.120.0,49.179.0"}
P.entries["quest:1846"] = {n="Dragonmaw Shinbones",s="Velora Nitely invia i guerrieri dell'Orda da Sepulcra nelle Paludi Grigie meridionali per recuperare Dragonmaw Shinbones. Le spesse ossa rinforzeranno i Gambali Foderati Brutali contro i colpi che un guerriero esperto deve affrontare.",h="Velora Nitely invia i guerrieri dell'Orda da Sepulcra nelle Paludi Grigie meridionali per recuperare...",kw={"accampamento zannarabbiosa","gambali foderati brutali","fauce del drago","tibie","viadotto di thandol","sepulcra","velora nitely","paludi grigie"},ang={["class:Warrior"]="Come guerriero, metti alla prova la tua forza sul campo e raccogli materiali macabri per fabbricare armature più resistenti.",["faction:Horde"]="Come membro dell'Orda, indebolisci una pericolosa fazione superstite dell'Old Horde a Khaz Modan e rafforzi la coalizione di Thrall.",["race:Orc"]="Come orco fedele a Orgrimmar, affronti i Fauce del Drago impenitenti e il prezzo di sangue della redenzione del tuo popolo dal suo passato vile.",["race:Undead"]="Come non morto, vedi Velora Nitely fare un uso pratico dei resti umanoidi, poiché i Reietti sfruttano ogni risorsa, per quanto macabra."},sec={{t="Un'armatura raccapricciante",b="Velora Nitely, un'armaiola dei Reietti a Sepulcra, ha bisogno di un robusto rinforzo per i Gambali Foderati Brutali. Invia i guerrieri dell'Orda nelle Paludi Grigie a raccogliere ossa spesse dagli orchi Fauce del Drago. La loro struttura scheletrica compatta può sopportare i pesanti colpi che i guerrieri esperti devono affrontare."},{t="Testare il midollo",b="Velora ha bisogno di ossa che resistano. Ognuna deve superare una prova a mani nude; quelle che si spezzano sono troppo fragili per la forgia. Così i guerrieri perlustrano gli accampamenti dei rinnegati lungo i dirupi delle Paludi Grigie, spezzando gli esemplari deboli finché non rimangono otto tibie robuste."}},faq={{q="Perché Velora Nitely ha bisogno proprio delle tibie degli orchi?",a="Velora ha bisogno di ossa spesse e compatte per rinforzare i Gambali Foderati Brutali. Ritiene che la robusta struttura scheletrica degli orchi Fauce del Drago sia più adatta allo scopo della selvaggina comune o dei resti recuperati.",al={"perché tibie di orco","perché ossa fauce del drago","armatura d'osso velora"}},{q="Perché i guerrieri dell'Orda possono dare liberamente la caccia agli orchi Fauce del Drago?",a="I superstiti dei Fauce del Drago nelle Paludi Grigie sono rinnegati ostili ancora legati all'oscura eredità della Second War. Non devono alcuna lealtà all'Orda di Thrall, quindi i guerrieri dell'Orda possono cacciarli come nemici.",al={"i fauce del drago fanno parte dell'orda","perché combattere i fauce del drago","rapporti tra fauce del drago e orda"}},{q="Dove si trovano i Fauce del Drago per questo compito?",a="I Fauce del Drago si trovano nelle Paludi Grigie, a sud degli Altopiani d'Arathi, oltre il Viadotto di Thandol. I guerrieri li cacciano presso le scarpate montuose dell'Accampamento Zannarabbiosa, a sud-ovest della strada principale settentrionale.",al={"posizione fauce del drago","dove trovare le tibie dei fauce del drago","posizione accampamento zannarabbiosa"}},{q="Perché così tante ossa si rompono durante la missione?",a="Velora ha bisogno delle ossa più compatte per la struttura dell'armatura. I guerrieri le mettono alla prova a mani nude e scartano quelle che si spezzano sotto la pressione, poiché le ossa fragili non possono proteggere le gambe di un guerriero in battaglia.",al={"tibie rotte","perché le tibie si spezzano","test dell'osso robusto"}},{q="Chi è Velora Nitely?",a="Velora Nitely è un'armaiola dei Reietti a Sepulcra. Burbera e dotata di un umorismo asciutto e macabro, ricorre a battute sinistre mentre aiuta i guerrieri dell'Orda a fabbricare equipaggiamento specializzato per veterani temprati dalla battaglia.",al={"storia di velora nitely","chi è velora","armaiola di sepulcra"}},{q="Quale pezzo di armatura viene forgiato da queste ossa?",a="Le ossa formano la struttura dei Gambali Foderati Brutali, resistenti gambali di maglia realizzati per i guerrieri dell'Orda di livello intermedio.",al={"ricompensa tibie","a cosa servono le tibie","creazione gambali foderati brutali"}}},fx={["0579d748"]={q="Perché Velora Nitely vuole che tu lo faccia?",a="A Velora Nitely servono le tibie degli orchi Dragonmaw delle Paludi per fabbricare i tuoi Gambali Foderati Brutali. Le loro ossa robuste forniscono il materiale per l'armatura che ha accettato di realizzare.",al={"motivo di velora nitely","perché velora vuole le tibie","perché velora nitely"}}},fp="19,193,19.254.0,18.232.0,55.172.0,56.195.0,44.198.0,51.185.0,21.178.0,44.95.0"}
P.entries["quest:1848"] = {n="Usbergo Brutale",s="Nelle Savane, i guerrieri dell'Orda affrontano una prova prima che Thun'grim Firegaze forgi le loro armature di maglia. Raccolgono materiali rari e affrontano nemici pericolosi in terre lontane, poi portano il loro bottino al fabbro solitario. Lui lo forgia in un'armatura fatta per la battaglia.",h="Nelle Savane, i guerrieri dell'Orda affrontano una prova prima che Thun'grim Firegaze forgi le loro armature...",kw={"brutal armor","brutal hauberk","crocevia","forgiatura orchesca","le savane","thun'grim firegaze","maglia da guerriero"},ang={["class:Warrior"]="Come giovane guerriero dell'Orda, ottieni il Brutal Hauberk passando da recluta inesperta a combattente temprato, equipaggiato con un'armatura di maglia su misura.",["faction:Horde"]="Come membro dell'Orda, puoi vedere le sue virtù di autonomia in battaglia e forza riflesse in un usbergo fatto con trofei conquistati nelle terre selvagge di Kalimdor.",["profession:Blacksmithing"]="Come fabbro, puoi imparare dall'arte orchesca tradizionale di Thun'grim, in cui lo spirito guerriero e la tenacia vengono forgiati nell'acciaio."},sec={{t="Il capolavoro di un fabbro",b="Nelle Savane settentrionali, Thun'grim Firegaze, un orco, forgia armature solo per i guerrieri che soddisfano le sue richieste. Il fabbro solitario li manda in lungo e in largo a raccogliere parti di bestie coriacee, Metallo Raro e reagenti alchemici prima di azionare i mantici. L'usbergo finito protegge chi lo indossa e testimonia la resistenza e la determinazione dimostrate. I combattenti veterani di tutta l'Orda riconoscono quella prova conquistata a caro prezzo."},{t="Forgiato nelle avversità",b="Thun'grim rende le sue richieste estenuanti di proposito. Le armi e le armature dell'Orda devono portare il sudore e il sangue di chi le indossa fin dal momento della loro creazione. Quando consegni il Brutal Hauberk finito, il fabbro non ti offre alcuna lode. Si aspetta che tu metta alla prova l'armatura in combattimenti brutali e torni con storie di sangue e onore."}},faq={{q="Cos'è il Brutal Hauberk?",a="Il Brutal Hauberk è una robusta protezione per il torso realizzata da Thun'grim Firegaze, un fabbro orco. I guerrieri dell'Orda lo ottengono dimostrando la propria abilità in combattimento e raccogliendo materiali rari in diverse terre pericolose.",al={"cos'è brutal hauberk","missione brutal hauberk","chi crea brutal hauberk"}},{q="Chi è Thun'grim Firegaze?",a="Thun'grim Firegaze è un fabbro veterano e solitario che vive su uno sperone montuoso nelle Savane settentrionali, poco a est della strada tra Crocevia e Orgrimmar. Mette alla prova i guerrieri alle prime armi e forgia per loro armature speciali quando dimostrano il proprio valore.",al={"chi è thun'grim","thun'grim firegaze","dove si trova thun'grim"}},{q="Perché Thun'grim richiede così tanto sforzo prima di forgiare l'armatura?",a="La tradizione guerriera dell'Orda tiene in gran conto le avversità quanto l'abilità marziale. Thun'grim crede che una buona armatura di maglia spetti a chi ha versato il proprio sangue e faticato per raccogliere i rari componenti necessari a forgiarla.",al={"perché raccogliere così tanti materiali","requisiti brutal armor","prove di thun'grim"}},{q="Dove porta questa serie di missioni?",a="Dopo che Thun'grim ti ha consegnato l'usbergo finito, il suo lavoro per te è completo. Puoi indossare l'armatura in battaglia in tutta Kalimdor e nei Regni Orientali.",al={"cosa viene dopo brutal hauberk","missione successiva a brutal hauberk","c'è un seguito"}},{q="La missione del Brutal Hauberk è disponibile per l'Alleanza?",a="No. Il Brutal Hauberk è una prova dell'Orda. I guerrieri dell'Alleanza affrontano un rito marziale distinto con i fabbri di Forgiardente e dei territori nanici circostanti per forgiare la propria armatura distintiva.",al={"l'alleanza può ottenere brutal hauberk","equivalente per l'alleanza","è solo per l'orda"}},{q="Dove si trova Thun'grim nelle Savane?",a="Thun'grim vive su un alto crinale nelle Savane settentrionali, poco a sud dei Colli Spinosi e a est di Crocevia.",al={"posizione di thun'grim","dove si trova thungrim nelle savane","come trovare thun'grim"}}},fx={a5674fab={q="Perché Thun'grim Firegaze ti forgia questo usbergo?",a="Thun'grim Firegaze non forgia la sua armatura brutale per chiunque. In qualità di mastro armaiolo onorato, mette alla prova i promettenti guerrieri dell'Orda e pretende prove di resistenza, forza e pura tenacia prima di battere il martello. Raccogliendo i materiali necessari e affrontando i pericoli per suo conto, hai dimostrato di essere degno di portare in battaglia la sua opera più pregiata.",al={"perché proprio io per il brutal hauberk","perché thun'grim fabbrica l'armatura","perché dare il brutal hauberk"}}},fp="14,256,21.404.0,18.329.0,27.207.0,26.253.0,68.202.0,38.162.0,54.195.0,44.109.0"}
P.entries["quest:185"] = {n="Tiger Mastery",s="Alla Spedizione di Nesingwary, Ajeck Rouack insegna ai cacciatori a seguire le tracce dei grandi felini. Comincia con le giovani tigri vicino al campo settentrionale, mettendo alla prova le capacità di caccia e di inseguimento dei nuovi arrivati.",h="Alla Spedizione di Nesingwary, Ajeck Rouack insegna ai cacciatori a seguire le tracce dei grandi felini.",kw={"ajeck rouack","caccia","nesingwary","valle di rovotorto","tiger mastery","giovane tigre di rovotorto"},sec={{t="Prime lezioni nella giungla",b="Ajeck Rouack ha imparato a cacciare le tigri da suo padre quando era bambina. Ora insegna la sua arte ai viaggiatori che raggiungono la Spedizione di Nesingwary dopo Benvenuti nella giungla. Le giovani tigri sono le prime prede. Seguirne le tracce e cacciarle ti prepara a inseguire prede più grandi."},{t="Caccia ai predatore",b="Le giovani tigri di Rovotorto si aggirano nella giungla vicino al campo della spedizione. Ajeck Rouack ti chiede di cacciarne dieci. Vuole una prova della tua abilità prima di offrirti ulteriore addestramento."}},faq={{q="Chi si offre di addestrarti nella caccia alle tigri?",a="Ajeck Rouack si offre di addestrarti nella caccia alle tigri presso la Spedizione di Nesingwary, nella parte settentrionale della Valle di Rovotorto.",al={"chi dà tiger mastery","missione ajeck rouack","chi dà missione tigri"}},{q="Perché Ajeck Rouack punta prima alle tigri giovani?",a="Ajeck Rouack comincia con le giovani tigri perché le considera più facili da rintracciare e cacciare. Mettono alla prova la tua capacità di seguire le tracce prima che tu insegua prede più pericolose.",al={"perché tigri giovani","perché iniziare facilmente tiger mastery"}},{q="Dove si trovano le tigri giovani?",a="Le giovani tigri di Rovotorto si aggirano nella giungla vicino al campo della Spedizione di Nesingwary.",al={"dove sono giovani tigri di rovotorto","posizione tigre giovane"}},{q="Cosa viene prima di questa caccia?",a="Arrivi al campo safari dopo Benvenuti nella giungla, che ti fa conoscere il campo.",al={"prerequisito tiger mastery","missione precedente tiger mastery"}}},fp="13,177,27.272.0,20.170.0,41.108.0,48.162.0,33.78.0,28.92.0"}
P.entries["quest:1858"] = {n="The Shattered Hand",s="A Orgrimmar, Therzok mette alla prova i furfanti che cercano un posto negli Shattered Hand. Vuole che la Valigetta di Tazan recuperata venga aperta con una chiave sottratta a un complice ignaro.",h="A Orgrimmar, Therzok mette alla prova i furfanti che cercano un posto negli Shattered Hand.",kw={"spelonca delle ombre","gamon","orgrimmar","borseggiare","furfante","the shattered hand","tazan","therzok"},ang={["class:Rogue"]="Come furfante, impari a pedinare un bersaglio ignaro in un luogo affollato, sottrarre una chiave senza farti notare e ottenere informazioni vitali.",["faction:Horde"]="Sotto l'onore marziale della nuova Orda di Thrall, la ricognizione segreta resta necessaria. Gli Shattered Hand se ne occupano in silenzio dalle profondità di Orgrimmar."},sec={{t="Una prova di sottigliezza",b="Hai la Valigetta di Tazan chiusa a chiave, ma senza la chiave è inutile. Therzok si aspetta che un furfante apra la serratura con abilità, senza ricorrere alla forza bruta. Perciò ti manda da Gamon, un ubriacone tauren che frequenta la locanda di Orgrimmar. Gamon si distrae facilmente e un tempo ha aiutato Tazan. Questo lo rende un bersaglio adatto per un furto silenzioso."},{t="Benvenuto nelle ombre",b="Sottrai la chiave a Gamon senza mettere in allarme la locanda. Poi apri la valigetta e porta il registro di Tazan a Therzok nella Spelonca delle Ombre. Un lavoro pulito soddisfa gli standard degli Shattered Hand. Therzok ti riconosce formalmente come uno dei loro agenti."}},faq={{q="Chi è Gamon e perché ha la chiave?",a="Gamon un tempo ha aiutato Tazan, l'agente su cui Therzok sta indagando. Mentre portava con sé la valigetta, Tazan ne lasciò la chiave a Gamon, un ignaro ubriacone che passa le giornate bevendo nella locanda centrale di Orgrimmar.",al={"perché gamon","chi ha la chiave","chiave di gamon"}},{q="Cosa c'è nella Valigetta di Tazan?",a="Il registro di Tazan si trova nella valigetta chiusa a chiave. Contiene informazioni che interessano a Therzok e agli Shattered Hand. Recuperarlo mette alla prova la tua capacità di ottenere informazioni vitali di nascosto.",al={"registro di tazan","contenuto valigetta","cosa c'è nella valigetta"}},{q="Cosa sono i The Shattered Hand a Orgrimmar?",a="Gli Shattered Hand nacquero come un famigerato clan orchesco di Draenor, noto per l'automutilazione e la spietatezza. A Orgrimmar, sono la gilda di assassini, spie e furfanti dell'Orda e operano dalla Spelonca delle Ombre, nel sottosuolo.",al={"cosa sono i the shattered hand","furfanti the shattered hand","furfanti di orgrimmar"}},{q="Dove opera Therzok?",a="Therzok opera dalla Spelonca delle Ombre, una rete di caverne buie sotto le creste rocciose di Orgrimmar. Vi si radunano stregoni e furfanti e vi si praticano le arti dell'ombra, lontano dalla luce del giorno.",al={"dov'è therzok","posizione di therzok","spelonca delle ombre istruttore dei furfanti"}},{q="Perché Therzok non apre semplicemente la valigetta?",a="La valigetta ha una serratura complessa e Therzok sta mettendo alla prova la disciplina di un furfante. Gli Shattered Hand prediligono i furti precisi e la destrezza alla distruzione rumorosa.",al={"perché borseggiare","perché serve la chiave"}},{q="Cosa succede dopo questa missione?",a="Consegnare il registro di Tazan completa la tua iniziazione. Therzok ti riconosce come membro degli Shattered Hand e ti fornisce strumenti per le operazioni segrete.",al={"ricompensa the shattered hand","fine della catena"}}},fx={["74a53139"]={q="Perché Therzok vuole che venga aperta la valigetta di Tazan?",a="Therzok e The Shattered Hand agiscono nell'ombra di Orgrimmar, occupandosi di segreti e sicurezza clandestina per l'Orda. Tazan era in possesso di informazioni fondamentali per le loro operazioni, ma il delicato contenuto era chiuso in una valigetta complicata. Therzok vuole ottenere le informazioni senza danneggiarle e usa il recupero come prova pratica per capire se possiedi l'astuzia, la furtività e l'abilità necessarie per essere ammesso ufficialmente nella gilda.",al={"motivo di therzok","perché aprire la valigetta","cosa vuole therzok"}},a30dee79={q="Che cos'è il diario di Tazan?",a="Il diario di Tazan contiene i resoconti scritti e gli affari clandestini di Tazan, un agente che ha attirato l'attenzione di The Shattered Hand. Chiuso nella sua valigetta, il diario custodisce le informazioni fondamentali che servono a Therzok. Consegnarlo intatto dimostra non solo che sai borseggiare e scassinare serrature complicate, ma permette anche di recapitare informazioni preziose direttamente ai maestri delle spie di Orgrimmar.",al={"diario di tazan","cosa contiene il diario","storia del diario di tazan"}},["1b7f194d"]={q="Perché Therzok non manda le guardie di Orgrimmar a prendere Gamon?",a="The Shattered Hand prospera grazie alla discrezione e alla segretezza, ben lontano dai metodi aperti e onorevoli delle guardie cittadine. Coinvolgere i fanti di Orgrimmar per arrestare un avventore ubriaco come Gamon provocherebbe un'indesiderata scenata pubblica e metterebbe in allerta eventuali complici di Tazan. Affidare il furto a un aspirante ladro mantiene l'operazione segreta e al tempo stesso valuta in silenzio la tua destrezza.",al={"perché proprio io","perché mandare un ladro","perché non le guardie cittadine"}}},fp="18,163,18.320.0,22.248.0,42.210.0,31.187.0,40.227.0,27.162.0,48.152.0,30.149.1"}
P.entries["quest:1859"] = {n="Therzok",s="A Orgrimmar, Therzok attende un promettente ladro inviato da Durotar. Kaplak ha notato la tua abilità nella violenza e nella furtività e ti manda alla Spelonca delle Ombre per incontrare un agente della Shattered Hand.",h="A Orgrimmar, Therzok attende un promettente ladro inviato da Durotar.",kw={"assassino","spelonca delle ombre","durotar","kaplak","orgrimmar","ladro","shattered hand","therzok"},ang={["class:Rogue"]="Come ladro, questa convocazione ti introduce nella Shattered Hand. Il tuo lavoro solitario a Durotar si collega ora alla rete di spionaggio organizzata dell'Orda.",["faction:Horde"]="Come membro dell'Orda, sai che Thrall predica l'onore e lo spirito guerriero. La rete di Therzok mostra che l'Orda dipende anche da lame nascoste e informatori segreti."},sec={{t="Una convocazione sussurrata",b="La nuova Orda onora Thrall, eppure non tutti i suoi servitori combattono apertamente sotto il suo vessillo. A Orgrimmar giunge voce di un combattente abile nella violenza e nella furtività, disposto ad aggirare le regole della guerra aperta. La gilda clandestina se ne accorge."},{t="Nella Spelonca delle Ombre",b="Kaplak ti manda sotto le scogliere di pietra rossa di Orgrimmar, alla Spelonca delle Ombre. Therzok attende lì, nascosto agli occhi dei grugnitori della città. Borseggiatori e assalitori solitari vengono accolti nella Shattered Hand, la rete segreta di pugnali nell'oscurità al servizio dell'Orda."}},faq={{q="Chi è Therzok?",a="Nella Spelonca delle Ombre di Orgrimmar, Therzok serve la Shattered Hand. Incontra giovani ladri promettenti provenienti dai campi d'addestramento di Durotar e li introduce al servizio della gilda.",al={"chi è therzok","lore di therzok","npc therzok"}},{q="Perché Kaplak mi manda da lui?",a="Kaplak ha notato la tua abilità in combattimento e il tuo talento per la furtività e il sotterfugio. Sapendo che la Shattered Hand cerca furfanti capaci, ti manda da Therzok con la richiesta di reclutarti.",al={"perché andare da therzok","missione di kaplak","perché andare a orgrimmar"}},{q="Cos'è la The Shattered Hand a Orgrimmar?",a="A Orgrimmar, la Shattered Hand è una gilda segreta di assassini, spie e ladri al servizio dell'Orda. Svolgono incarichi difficili che gli onorevoli guerrieri di Thrall non possono compiere apertamente.",al={"cos'è la shattered hand","shattered hand orgrimmar","gilda dei ladri dell'orda"}},{q="Dove si trova la Spelonca delle Ombre?",a="La Spelonca delle Ombre è una caverna sotto il centro di Orgrimmar. Passaggi oscuri vi discendono dalla Valle della Forza e da Varcolargo. Offre riparo agli stregoni e ai ladri della città, lontano dagli sguardi indiscreti.",al={"dove si trova la spelonca delle ombre","come trovare therzok","posizione della spelonca delle ombre"}},{q="Cosa succede dopo aver incontrato Therzok?",a="Dopo che hai salutato Therzok, lui ti spiega i doveri del servizio nella Shattered Hand. Poi ti assegna degli incarichi per mettere alla prova le tue capacità, la tua furtività e la tua lealtà alla rete.",al={"missione successiva","cosa vuole therzok","dopo therzok"}},{q="I non-ladri ricevono questa missione?",a="No. Solo i ladri ricevono questa convocazione dopo aver acquisito una certa esperienza. Segna il loro passaggio dalle schermaglie locali alla rete di spionaggio dell'Orda.",al={"altre classi possono farlo","è solo per ladri","missione ladro"}}},fx={["89f659b0"]={q="Perché Kaplak ha scelto te per questo incontro?",a="Kaplak ha ricevuto l'ordine esplicito di cercare persone che corrispondessero alla tua descrizione. La gilda ha saputo che sai cavartela in combattimento e che, quando serve, non esiti a ricorrere alla furtività, all'inganno o a mezzi meno onorevoli. Therzok ha in mente un affare che richiede qualcuno con le tue specifiche e versatili capacità.",al={"perché proprio io per kaplak","perché mandarmi da therzok","perché kaplak ha scelto me"}}},fp="7,190,19.238.0,24.246.0,15.172.0,31.188.0,40.190.0,37.193.0,33.157.0,33.166.0"}
P.entries["quest:186"] = {n="Tiger Mastery",s="Alla Spedizione di Nesingwary, nella Valle di Rovotorto settentrionale, Ajeck Rouack ti manda a caccia di tigri adulte. Dopo che hai sconfitto i giovani predatori, ti mette alla prova contro dieci Tigri di Rovotorto adulte.",h="Alla Spedizione di Nesingwary, nella Valle di Rovotorto settentrionale, Ajeck Rouack ti manda a caccia di...",kw={"ajeck rouack","spedizione di nesingwary","tigri di rovotorto","valle di rovotorto","tiger mastery"},sec={{t="Cacciare i felini maturi",b="Ajeck Rouack ti manda a caccia di dieci Tigri di Rovotorto adulte. Il tuo successo contro i predatori più giovani ti ha portato a una prova più ardua nelle terre selvagge della Valle di Rovotorto. Sfide più grandi ti attendono dopo questa caccia."}},faq={{q="Chi assegna questa caccia?",a="Ajeck Rouack, una cacciatrice della Spedizione di Nesingwary nella Valle di Rovotorto settentrionale, ti affida questa caccia.",al={"chi assegna tiger mastery","posizione di ajeck rouack","chi assegna questa missione"}},{q="Quali bestie ti viene chiesto di cacciare?",a="Ti viene chiesto di rintracciare e uccidere dieci Tigri di Rovotorto adulte nella giungla circostante.",al={"quali tigri devo uccidere","quali felini","obiettivi di tiger mastery"}},{q="Dove si colloca questa prova nella caccia?",a="Questa caccia segue la tua prima prova di Tiger Mastery e conduce a una terza fase sotto la guida di Ajeck Rouack.",al={"cosa precede tiger mastery 2","cosa viene dopo","catena di tiger mastery"}}},fp="13,191,23.212.0,22.99.0,40.89.0,38.106.0"}
P.entries["quest:1860"] = {n="Speak with Jennea",s="A Roccavento, i maghi novizi di Borgodoro si presentano a Jennea Acquachiara dopo aver superato l'addestramento di base nella Foresta di Elwynn. È Zaldimar Wefhellt a mandarli da lei.",h="A Roccavento, i maghi novizi di Borgodoro si presentano a Jennea Acquachiara dopo aver superato...",kw={"foresta di elwynn","borgodoro","jennea acquachiara","quartiere dei maghi","speak with jennea","roccavento","santuario della magia","zaldimar wefhellt"},ang={["class:Mage"]="Come mago, lasci la pratica della magia nella campagna di Borgodoro per svolgere incarichi ufficiali con gli alti maghi al Santuario della Magia di Roccavento.",["faction:Alliance"]="Come membro dell'Alleanza, fai affidamento sulla vigilanza arcana della capitale per contribuire a proteggere la Foresta di Elwynn e Roccavento."},sec={{t="Una chiamata al Santuario della Magia",b="Nel Quartiere dei Maghi, il Santuario della Magia riunisce i maghi più esperti del regno per lo studio e l'insegnamento delle arti arcane. Coordinano le questioni magiche in tutto il regno, e il tuo addestramento trova ora posto in questo impegno più ampio."},{t="Questioni di sicurezza del regno",b="Jennea Acquachiara sovrintende agli incarichi locali, compresi i rapporti sulla sicurezza della Foresta di Elwynn e di Roccavento, oltre che ai tuoi studi. Cauta nel condividere grandi segreti con un apprendista appena arrivato, accoglie il tuo rapporto come l'inizio del tuo servizio all'ordine dei maghi."}},faq={{q="Chi mi assegna questa missione?",a="Zaldimar Wefhellt, l'istruttore dei maghi presso la Locanda del Fiero Leone a Borgodoro, ti manda da lei quando le tue abilità arcane sono sufficientemente progredite.",al={"fornitore di missioni","chi assegna la missione","zaldimar"}},{q="Dove posso trovare Jennea Acquachiara?",a="Jennea Acquachiara si trova nel Santuario della Magia, al centro del Quartiere dei Maghi di Roccavento.",al={"posizione jennea acquachiara","dove si trova jennea","trovare jennea"}},{q="Cos'è il Santuario della Magia?",a="Il Santuario della Magia è un'imponente torre magica nel Quartiere dei Maghi di Roccavento. I maghi e gli studiosi delle arti arcane del regno lo usano come accademia, biblioteca e base operativa.",al={"cos'è il santuario della magia","torre del mago roccavento"}},{q="Perché Zaldimar mi manda da Jennea invece di occuparsene lui stesso?",a="Zaldimar insegna ai giovani maghi i fondamenti a Borgodoro. Dalla capitale, studiosi di rango superiore come Jennea Acquachiara si occupano di minacce regionali più gravi e di incarichi specialistici che interessano il regno.",al={"perché andare a roccavento","perché jennea"}},{q="Cosa succede dopo aver fatto rapporto a Jennea Acquachiara?",a="Jennea ti manda a indagare su misteriose anomalie magiche nei pressi del Lago Riflesso, nella Foresta di Elwynn.",al={"cosa succede dopo","missione successiva","prossimo passo"}},{q="Questa missione è disponibile per qualsiasi classe?",a="No. Solo i maghi ricevono questo rito di passaggio dall'addestramento nel villaggio alla società arcana di Roccavento.",al={"i non maghi possono farlo","solo maghi","requisito di classe"}}},fx={["8f9ffa7f"]={q="Perché Zaldimar Wefhellt vuole che tu parli con Jennea?",a="Zaldimar Wefhellt agisce per proteggere sia Roccavento sia la Foresta di Elwynn. È sorto un problema urgente che richiede l'intervento di maghi capaci, ma invece di occuparsene direttamente, indirizza gli apprendisti promettenti da Jennea Acquachiara al Santuario della Magia, dove lei supervisiona i dettagli di questa delicata missione.",al={"motivo di zaldimar","perché incontrare jennea","perché mandarmi da jennea"}}},fp="17,156,30.230.0,27.284.0,27.129.0,31.89.0,29.173.0,67.196.0,46.97.1,37.98.0"}
P.entries["quest:1861"] = {n="Lago Riflesso",s="Nel Quartiere dei Maghi di Roccavento, i maghi novizi dell'Alleanza vengono inviati a verificare se il Lago Riflesso presenta contaminazioni magiche. Jennea Acquachiara li manda a sud-ovest delle porte della città per prelevare un campione degli spruzzi della cascata.",h="Nel Quartiere dei Maghi di Roccavento, i maghi novizi dell'Alleanza vengono inviati a verificare se il Lago...",kw={"contaminazione arcana","foresta di elwynn","jennea acquachiara","linee di ley","lago riflesso","campione acqua","santuario della magia"},ang={["class:Mage"]="Come mago, passi dallo studio nel Santuario della Magia all'indagine dei fenomeni arcani nel mondo. Questo lavoro ti procura il tuo primo bastone da mago o una sfera da tenere nella mano secondaria.",["faction:Alliance"]="Come membro dell'Alleanza, puoi aiutare i maghi del Santuario della Magia a proteggere le risorse naturali di Elwynn e il cuore del regno.",["race:Human"]="Come umano, sai che il Lago Riflesso alimenta i terreni agricoli e i corsi d'acqua di Elwynn, quindi la sua purezza è importante per i cittadini di Roccavento."},sec={{t="Linee di Ley e correnti mutevoli",b="Le correnti arcane di Azeroth furono scosse dai conflitti iniziati con l'apertura del Portale Oscuro e proseguiti attraverso la Terza Guerra e la battaglia sul Monte Hyjal. Quelle scosse strapparono antiche correnti dai loro canali stabili.\n\nNel Santuario della Magia di Roccavento, maghi come Jennea Acquachiara osservano attentamente i cambiamenti. Temono che il potere arcano deviato possa raggiungere le terre selvagge e corrompere gli ecosistemi locali."},{t="Analisi delle acque",b="Sotto le scogliere a sud-ovest delle porte di Roccavento, il Lago Riflesso è un bacino naturale alimentato da cascate montane. La campagna circostante dipende dalle sue acque.\n\nJennea invia i maghi novizi con una fiala di vetro alla base della cascata, dove raccolgono gli spruzzi d'acqua fresca. Il Santuario può quindi ricorrere alla divinazione e ad analisi con reagenti per scoprire se la magia selvaggia si sta infiltrando nell'approvvigionamento idrico pubblico."}},faq={{q="Perché Jennea Acquachiara vuole un campione d'acqua del Lago Riflesso?",a="I conflitti in tutta Azeroth hanno spezzato le correnti naturali delle linee di faglia. Jennea Acquachiara teme che energie arcane instabili stiano raggiungendo la falda acquifera intorno a Roccavento e possano nuocere a chiunque beva dal lago.",al={"perché acqua lago riflesso","campione acqua jennea","a cosa serve questa missione"}},{q="Dov'è esattamente il Lago Riflesso?",a="Il Lago Riflesso si trova nella parte nordoccidentale della Foresta di Elwynn, ai piedi delle alte scogliere a sud-ovest delle porte principali di Roccavento. Il campione proviene dalla pozza ai piedi della sua cascata.",al={"dove si trova il lago riflesso","posizione lago riflesso","trovare lago riflesso"}},{q="Cosa succede se l'acqua è contaminata?",a="Jennea teme che bere troppo a lungo acqua contaminata dalla magia possa nuocere a chi dipende dal lago. Gli effetti precisi non sono noti.",al={"l'acqua è avvelenata","cosa se l'acqua ha magia","effetti contaminazione magica"}},{q="Chi può intraprendere questa missione?",a="I maghi novizi dell'Alleanza in addestramento svolgono questo incarico come una delle loro prime indagini sul campo per il Santuario della Magia.",al={"chi riceve missione lago riflesso","lago riflesso solo per maghi"}},{q="Questa missione porta a ulteriori indagini?",a="Il primo incarico diretto, iniziato con la convocazione di Jennea Acquachiara, si conclude qui. Fornisce all'apprendista il suo primo strumento ufficiale da mago e sancisce il suo dovere di vigilare sulle perturbazioni magiche in tutto il regno.",al={"cosa viene dopo lago riflesso","catena missioni lago riflesso"}},{q="Cosa ha causato inizialmente la destabilizzazione delle correnti magiche?",a="Jennea riconduce i cambiamenti nelle correnti ai grandi conflitti mistici del mondo, ma non cita alcuna battaglia o evento specifico.",al={"perché le linee di ley sono danneggiate","significato lotte mistiche","cosa ha rotto la magia"}}},fx={["66ca747e"]={q="A cosa serve il Campione d'Acqua del Lago Riflesso?",a="Jennea Acquachiara ha bisogno del campione per verificare se le acque del Lago Riflesso sono contaminate dalla magia. Immensi sconvolgimenti mistici in tutta Azeroth hanno deviato i flussi arcani dai loro percorsi abituali e i maghi del Quartiere dei Maghi temono che queste energie instabili stiano filtrando direttamente nelle riserve idriche locali. Analizzare l'acqua del lago rivelerà se chi la beve rischia di subire una corruzione magica.",al={"uso del campione d'acqua del lago riflesso","perché raccogliere un campione d'acqua","a cosa serve il campione"}}},fp="11,190,31.402.0,18.382.0,60.200.0,29.169.0,37.139.0,31.124.0,47.206.0,67.112.0"}
P.entries["quest:187"] = {n="Tiger Mastery",s="Alla Spedizione di Nesingwary, Ajeck Rouack ti manda a caccia di dieci tigri anziane di Rovotorto. La loro morte dimostrerà la tua abilità prima della prova finale.",h="Alla Spedizione di Nesingwary, Ajeck Rouack ti manda a caccia di dieci tigri anziane di Rovotorto.",kw={"ajeck rouack","caccia grossa","tigre di rovotorto anziana","nesingwary","valle di rovotorto","tiger mastery"},sec={{t="Una prova di abilità",b="Ajeck Rouack ti manda nelle terre selvagge a caccia di dieci tigri anziane di Rovotorto. Dice che sono i felini più difficili da rintracciare e i più feroci da sconfiggere. La loro morte ti prepara a una prova finale. Dopo questa, promette di proclamarti maestro cacciatore di tigri davanti al Mastro Nesingwary."}},faq={{q="Chi assegna questa prova?",a="Ajeck Rouack ti affida la prova all'accampamento della Spedizione di Nesingwary, nella parte settentrionale della Valle di Rovotorto.",al={"chi dà tiger mastery","missione ajeck rouack","datore di missione"}},{q="Quale preda stai rintracciando?",a="Stai dando la caccia a dieci tigri anziane di Rovotorto.",al={"cosa devo uccidere","quali tigri","bersagli di tiger mastery"}},{q="Perché le tigri di Rovotorto anziane sono state scelte?",a="Ajeck Rouack dice che le tigri anziane di Rovotorto sono i felini locali più difficili da trovare e i più feroci da sconfiggere.",al={"perché le tigri anziane","difficoltà tigre anziana"}},{q="Cosa viene prima di questa caccia?",a="Questa caccia segue la seconda fase della serie Tiger Mastery di Ajeck Rouack.",al={"missione precedente","prerequisito"}}},fp="13,146,15.280.0,23.94.0,29.47.0,47.113.0,28.74.0"}
P.entries["quest:1878"] = {n="Water Pouch Bounty",s="A Meccania, l'Operatore delle Valvole Lordafiumi ti dà il bentornato e ti chiede altri cinque otri d'acqua dei Banditi del Deserto. Ti aspetta un pacchetto di rifornimenti con il tuo nome.",h="A Meccania, l'Operatore delle Valvole Lordafiumi ti dà il bentornato e ti chiede altri cinque otri d'acqua...",kw={"pacchetto di rifornimenti","operatore delle valvole lordafiumi","tanaris","otre d'acqua dei banditi del deserto","water pouch bounty"},sec={{t="Di nuovo qui",b="Lordafiumi ti dà il bentornato e ti chiede altri cinque otri d'acqua dei Banditi del Deserto. Un pacchetto di rifornimenti è già stato messo da parte con il tuo nome."},{t="Continua a portarli",b="Lordafiumi è soddisfatto degli otri recuperati. Ognuno di essi allontana tutti dal disastro. Lordafiumi promette di ricompensarti adeguatamente per ogni cinque otri che porterai."}},faq={{q="Chi offre questa taglia?",a="Lordafiumi, l'operatore delle valvole di Meccania, offre la ricompensa.",al={"chi offre water pouch bounty","missione lordafiumi","chi prende gli otri d'acqua"}},{q="Quanti otri d'acqua sono necessari?",a="Ti servono cinque otri d'acqua dei Banditi del Deserto, lo stesso numero di prima.",al={"quanti otri","conteggio otri d'acqua","otri per consegna"}},{q="Cosa ha preparato Lordafiumi?",a="Lordafiumi ha messo da parte un pacchetto di rifornimenti con il tuo nome.",al={"cos'è il pacchetto di rifornimenti","cosa ricevo"}},{q="Cosa precede questa fase?",a="Questa missione segue la precedente Water Pouch Bounty, quando hai portato per la prima volta degli otri a Lordafiumi.",al={"missione precedente","cosa devo fare prima"}}},fp="18,141,10.135.0,16.168.1,28.63.0,34.67.0,31.55.0,28.89.0"}
P.entries["quest:1879"] = {n="Speak with Bink",s="Magis Frizzamanto ti manda da Bink a Forgiardente, dove i suoi studi richiedono uno specialista arcano.",h="Magis Frizzamanto ti manda da Bink a Forgiardente, dove i suoi studi richiedono uno specialista arcano.",kw={"bink","dun morogh","hall of mysteries","forgiardente","mago","magis frizzamanto","guardia mistica"},ang={["class:Mage"]="Come mago, lasci l'addestramento introduttivo nella valle per dedicarti al lavoro più ampio degli studiosi arcani di Forgiardente.",["faction:Alliance"]="Come membro dell'Alleanza, vedi l'intelletto gnomesco e l'ospitalità nanica unirsi nello studio presso la Hall of Mysteries.",["race:Gnome"]="Come gnomo, trovi Bink e Magis Frizzamanto intenti a portare avanti la tradizione arcana gnomesca nelle accoglienti sale di Forgiardente dopo la perdita di Gnomeregan."},sec={{t="Il richiamo di un collega",b="Bink cerca qualcuno che sappia usare la magia e aiutarla nel suo lavoro. Nei pressi di Kharanos, Magis Frizzamanto manda gli apprendisti che hanno superato gli esercizi iniziali a rispondere alla chiamata di Bink."},{t="La Hall of Mysteries",b="Nella Guardia Mistica di Forgiardente, Bink studia nella Hall of Mysteries. Studiosi, sacerdoti e arcanisti si riuniscono lì. Osserva attentamente ogni apprendista in arrivo, perché il potenziale grezzo senza disciplina può rendere un incantatore pericoloso nel lavoro arcano."}},faq={{q="Chi fornisce questa missione?",a="Magis Frizzamanto manda i maghi novizi dell'Alleanza da Dun Morogh a Bink quando hanno superato l'addestramento iniziale.",al={"datore di missione","dove iniziare","chi avvia speak with bink"}},{q="Dove posso trovare Bink?",a="Bink si trova nella Hall of Mysteries, nella Guardia Mistica, nella parte settentrionale di Forgiardente.",al={"posizione di bink","dov'è bink","trovare bink"}},{q="Perché Bink vuole solo un mago?",a="Bink studia le energie arcane e delicate apparecchiature di monitoraggio. Ritiene che chi non è un mago non possa gestire i dettagli magici e i pericoli che comportano.",al={"perché solo maghi","requisito mago","bink vuole solo maghi"}},{q="Cosa succede dopo aver incontrato Bink?",a="Dopo averti salutato e aver valutato le tue capacità, Bink ti chiede di aiutarla nelle sue ricerche, che proseguono con Mage-tastic Gizmonitor.",al={"missione successiva","proseguimento di bink","cosa succede dopo speak with bink"}},{q="Questa missione è disponibile per classi diverse dai maghi?",a="No. La chiamata di Bink è rivolta ai maghi e li porta dall'addestramento locale per novizi al lavoro specializzato nella capitale.",al={"altre classi possono farlo","è solo per maghi","specifico per mago"}},{q="Che cos'è la Hall of Mysteries?",a="La Hall of Mysteries è il centro di Forgiardente per lo studio della magia arcana e sacra. Istruttori, studiosi e ricercatori vi rappresentano le arti magiche di nani e gnomi.",al={"hall of mysteries forgiardente","cos'è la hall of mysteries"}}},fx={["96ce9827"]={q="Perché Magis Frizzamanto ti manda da Bink?",a="Magis Frizzamanto è un addestratore gnomo di maghi stanziato a Kharanos, dove fa da mentore agli incantatori emergenti. La sua collega a Forgiardente, Bink, ha chiesto espressamente l'aiuto di un mago esperto per un'impresa importante. Riconoscendo la tua crescente padronanza delle arti arcane, Magis ti manda nella capitale dei nani per rispondere alla sua chiamata e proseguire il tuo addestramento magico.",al={"perché magis ti manda","motivo di magis frizzamanto","perché parlare con bink"}}},fp="15,94,21.170.0,21.245.0,21.122.0,22.75.0,31.143.0,32.134.0,52.104.0,30.162.0"}
P.entries["quest:188"] = {n="La maestria nella caccia alla tigre",s="Alla Spedizione di Nesingwary, Ajeck Rouack ti manda a caccia di una tigre che i suoi cacciatori seguono da settimane. Sin'dall attende nella Valle di Rovotorto settentrionale, e la sua zampa proverà che la caccia è conclusa.",h="Alla Spedizione di Nesingwary, Ajeck Rouack ti manda a caccia di una tigre che i suoi cacciatori seguono da...",kw={"ajeck rouack","maestro cacciatore di tigri","spedizione di nesingwary","zampa di sin'dall","sin'dall","valle di rovotorto","tiger mastery"},sec={{t="La tigre finale",b="Alla Spedizione di Nesingwary, Ajeck Rouack ti affida un'ultima caccia dopo le tue precedenti prove contro le tigri della Valle di Rovotorto. I suoi cacciatori seguono le tracce di Sin'dall nella giungla da settimane. Trova la sfuggente tigre, uccidila e riporta la sua zampa come prova."},{t="Maestro cacciatore di tigri",b="Quando torni al campo di Nesingwary con la zampa di Sin'dall, Ajeck Rouack riconosce la tua abilità nel seguire le tracce. Ti proclama un vero Maestro cacciatore di tigri."}},faq={{q="Chi offre questa caccia?",a="Ajeck Rouack, un cacciatore esperto della Spedizione di Nesingwary nella Valle di Rovotorto settentrionale, ti propone quest'ultima caccia.",al={"datore di missione","chi dà tiger mastery","posizione ajeck rouack"}},{q="Cos'è Sin'dall?",a="Sin'dall è una tigre sfuggente che i cacciatori della Spedizione di Nesingwary inseguono da settimane nelle giungle della Valle di Rovotorto.",al={"cos'è sindall","storia di sindall","chi è sin dall"}},{q="Quale prova richiede Ajeck Rouack?",a="Ajeck Rouack ti chiede di tornare con la zampa di Sin'dall come prova che hai sconfitto la tigre.",al={"cosa devo riportare","prova di tiger mastery","zampa di sindall"}},{q="Cosa precede questa caccia?",a="Questa caccia è la quarta e ultima tappa della serie di Ajeck Rouack. Segue la terza prova di Tiger Mastery nella Valle di Rovotorto settentrionale.",al={"prerequisiti","serie di tiger mastery","missione precedente"}}},fp="13,188,15.256.0,19.146.1,21.118.0,17.131.0,37.87.0,24.137.0"}
P.entries["quest:1881"] = {n="Speak with Anastasia",s="A Sepulcra, Cain Cantafuoco manda un promettente mago dei Reietti da Anastasia Cuorfosco. La sua convocazione ti chiama al Magic Quarter per svolgere incarichi pratici tra i maghi dei Reietti, in vista delle indagini sul campo nelle Radure di Tirisfal.",h="A Sepulcra, Cain Cantafuoco manda un promettente mago dei Reietti da Anastasia Cuorfosco.",kw={"anastasia cuorfosco","cascina dei balnir","cain cantafuoco","missione del mago","magic quarter","sepulcra"},ang={["class:Mage"]="Come mago, passi dall'addestramento arcano di base al servizio attivo per i maghi di Sepulcra.",["race:Undead"]="Come arcanista dei Reietti, puoi mettere il passato intellettuale di Lordaeron al servizio della lotta contro i pericoli che la minacciano oggi."},sec={{t="Una chiamata al Magic Quarter",b="Cain Cantafuoco addestra i giovani maghi dei Reietti a Brill. Quando vede del potenziale in un allievo, lo manda a Sepulcra. Lì, i maghi dei Reietti studiano le arti arcane e pianificano le difese in tutta Lordaeron. Cain decide quali allievi sono pronti a servire gli incantatori più esperti. Quelli dotati di vero talento vengono inviati da Anastasia Cuorfosco, che ha bisogno di aiutanti capaci sul campo."},{t="L'ambizione di Anastasia Cuorfosco",b="Anastasia Cuorfosco è una delle principali istruttrici dei maghi di Sepulcra. Affida agli allievi promettenti incarichi pratici al servizio degli interessi e del territorio dei Reietti, anziché lasciarli studiare formule magiche al sicuro. Rispondere alla sua chiamata dà inizio al tuo servizio tra i maghi dei Reietti e alle loro attività magiche pratiche negli anni successivi al Flagello."}},faq={{q="Chi ti manda a parlare con Anastasia Cuorfosco?",a="Cain Cantafuoco, il tuo istruttore dei maghi dei Reietti a Brill, ti manda da Anastasia Cuorfosco quando ritiene il tuo talento arcano pronto per incarichi più impegnativi a Sepulcra.",al={"chi assegna speak with anastasia","chi assegna la missione speak with anastasia","richiamo di cain cantafuoco"}},{q="Dove si può trovare Anastasia Cuorfosco?",a="Anastasia Cuorfosco si trova nel Magic Quarter di Sepulcra, dove istruisce i Reietti che praticano le arti arcane.",al={"dove si trova anastasia cuorfosco","posizione anastasia cuorfosco","trovare anastasia"}},{q="Qual è lo scopo di questo richiamo?",a="Anastasia cerca un incantatore capace per svolgere incarichi pratici oltre le mura della città. Gli incarichi sul campo iniziano nelle Radure di Tirisfal, con attività come le indagini alla Cascina dei Balnir.",al={"perché mi vuole","scopo speak with anastasia","cosa serve ad anastasia"}},{q="Quale missione segue Speak with Anastasia?",a="Dopo che ti sei presentato ad Anastasia, lei ti manda alla Cascina dei Balnir, nelle Radure di Tirisfal orientali, a raccogliere bocche di leone dal giardino.",al={"quale missione segue","prossima missione dopo speak with anastasia","seguito speak with anastasia"}},{q="Questa missione è limitata a determinate classi?",a="Sì. Questa convocazione è rivolta ai maghi dei Reietti e segna una tappa nel loro addestramento di classe, quando raggiungono le prime competenze intorno alla decima cerchia.",al={"è una missione solo per maghi","chi può fare speak with anastasia","requisito di classe"}},{q="Perché i maghi dei Reietti mantengono un proprio quartiere a Sepulcra?",a="Il Magic Quarter offre agli arcanisti, agli stregoni e ai ricercatori dei Reietti un luogo dove studiare e lanciare incantesimi, separato dai quartieri delle discipline fisiche. Lì, sotto Lordaeron, portano avanti tradizioni precedenti alla Terza Guerra.",al={"perché magic quarter","maghi reietti sepulcra"}}},fx={["34129032"]={q="Perché Cain Cantafuoco ti manda da Anastasia Cuorfosco?",a="Cain Cantafuoco è un istruttore dei maghi Reietti alle prime armi a Brill. Quando dimostri un'abilità sufficiente nelle arti arcane, il suo compito è indirizzare gli incantatori promettenti da Anastasia Cuorfosco nel Magic Quarter di Sepulcra. Cuorfosco coordina le imprese più importanti dell'ordine magico dei Reietti e Cain si assicura che i suoi ranghi si arricchiscano di praticanti capaci e pronti a servire.",al={"perché cain ti manda","motivo di cain cantafuoco","perché andare da anastasia cuorfosco"}}},fp="20,225,27.367.0,29.353.0,47.157.0,38.120.0,36.172.0,40.134.0,41.131.0,67.206.0"}
P.entries["quest:1882"] = {n="The Balnir Farmstead",s="A est di Tirisfal, le dragolose della Cascina dei Balnir possono rivelare fin dove si è diffusa la corruzione del Flagello. Anastasia Cuorfosco invia giovani maghi Reietti a raccogliere i fiori perché vengano studiati a Sepulcra.",h="A est di Tirisfal, le dragolose della Cascina dei Balnir possono rivelare fin dove si è diffusa la corruzione...",kw={"anastasia","balnir","cascina","cuorfosco","mago","terre infette","dragolose","tirisfal","sepulcra"},ang={["class:Mage"]="Come mago, impari presto che lo studio dell'arcano può aiutare a individuare la corruzione magica proveniente dall'esterno e a difendersene.",["profession:Herbalism"]="Come erborista, vedi come una pianta possa trattenere tracce di inquinamento magico e rivelarne la presenza.",["race:Undead"]="Come Reietto, devi tenere il Flagello lontano dai confini di Tirisfal per salvaguardare la tua sopravvivenza e la tua sovranità."},sec={{t="Un barometro magico",b="I maghi Reietti sorvegliano le terre di confine in cerca di corruzione magica. Anastasia Cuorfosco invia gli incantatori novizi alla Cascina dei Balnir, nelle Radure di Tirisfal orientali, per raccogliere dragolose dai suoi giardini. I fiori assorbono energie magiche dal suolo e dall'aria. Gli studiosi dell'arcano di Sepulcra li esaminano per scoprire se la corruzione del dominio del Re dei Lich abbia raggiunto Tirisfal."},{t="Il confine orientale",b="La Cascina dei Balnir sorge ai margini delle radure, vicino alle terre selvagge e corrotte delle Terre Infette Occidentali. I Reietti sanno che la piaga del Re dei Lich fa marcire la terra e che la corruzione del Flagello minaccia i loro confini e la loro sicurezza. Sebbene i Reietti pratichino a loro volta le arti oscure, Anastasia intende consegnare le dragolose agli speziali perché le studino. Insieme, maghi e alchimisti possono esaminare il pericolo e contribuire a difendere il cuore riconquistato di Lordaeron."}},faq={{q="Perché Anastasia Cuorfosco vuole proprio le Dragolose di Balnir?",a="Le Dragolose di Balnir sono sensibili alle forze magiche e assorbono energia dalla terra e dall'aria. Studiarle può rivelare ai maghi Reietti se la contaminazione arcana e necromantica delle Terre Infette stia raggiungendo le Radure di Tirisfal.",al={"perché le dragolose","scopo delle dragolose di balnir","a cosa servono le dragolose"}},{q="Dov'è situata la Cascina dei Balnir?",a="La Cascina dei Balnir sorge nelle Radure di Tirisfal orientali, vicino al confine con le corrotte Terre Infette Occidentali. Le dragolose crescono nelle aiuole e nei giardini attorno ai suoi edifici fatiscenti.",al={"posizione cascina dei balnir","dove si trova cascina dei balnir","trovare cascina dei balnir"}},{q="Chi è Anastasia Cuorfosco?",a="Anastasia Cuorfosco è una maga Reietta e un'istruttrice nel Quartiere dei Maghi di Sepulcra. Insegna agli incantatori non morti appena risorti la disciplina, l'equilibrio arcano e come difendere i propri confini dalle potenze rivali.",al={"storia di anastasia cuorfosco","chi è anastasia"}},{q="Perché ai maghi Reietti interessa fermare la piaga?",a="I Reietti considerano incontrollata la contagiosa magia pestilenziale del Re dei Lich, pur sperimentando a loro volta piaghe e contaminazioni. Se lasciato dilagare, il Flagello potrebbe consumare le Radure di Tirisfal e minacciare l'indipendenza dei Reietti.",al={"perché fermare la piaga","i reietti odiano la piaga"}},{q="Cosa succede ai fiori dopo averli raccolti?",a="Anastasia intende consegnare le dragolose agli speziali di Sepulcra. Alchimisti e maghi le esamineranno per scoprire quanto profondamente il Flagello abbia contaminato il suolo e le piante.",al={"cosa fa anastasia con i fiori","chi riceve le dragolose"}},{q="Questa missione è riservata ai maghi?",a="Sì. Anastasia propone questa prova solo ai giovani maghi Reietti che hanno terminato le prime lezioni ad Albamorta e raggiunto la capitale per dimostrare la propria padronanza della teoria arcana.",al={"la cascina dei balnir è solo per maghi","missione di classe mago"}}},fp="20,208,19.379.0,18.456.0,58.214.0,38.182.0,26.203.0,53.231.0,51.176.0,34.176.0"}
P.entries["quest:1884"] = {n="Ju-Ju Heaps",s="Sulle Isole dell'Eco, Un’thuwa ti chiede di distruggere gli ammassi di ju-ju di Zalazane. La loro corruzione minaccia il flusso della magia a Durotar.",h="Sulle Isole dell'Eco, Un’thuwa ti chiede di distruggere gli ammassi di ju-ju di Zalazane.",kw={"durotar","isole dell'eco","ammassi di ju-ju","magia","villaggio di sen'jin","feticci contaminati","un’thuwa","zalazane"},ang={["faction:Horde"]="Un’thuwa definisce questa un'impresa per il tuo popolo e dice che hai dimostrato il tuo valore alle classi dell'Orda."},sec={{t="Ammassi contaminati",b="Dal Villaggio di Sen'jin, Un’thuwa ti chiede di distruggere gli ammassi che Zalazane ha collocato tra le sue capanne sull'isola principale delle Isole dell'Eco. I feticci contaminati corrompono la fauna e potenziano gli stregoni e le creature infernali. Se lasciati intatti, potrebbero alterare per sempre il flusso della magia a Durotar."},{t="Il responso di Un’thuwa",b="Un’thuwa percepisce che gli ammassi sono stati distrutti. Crede che, con il tempo e un po' di fortuna, la magia di Durotar tornerà a scorrere normalmente. Loda la tua impresa per il tuo popolo e dice che hai dimostrato il tuo valore alle classi dell'Orda."}},faq={{q="Chi ha collocato gli ammassi di ju-ju?",a="Zalazane, uno stregone delle Isole dell’Eco, ha collocato gli ammassi contaminati tra le sue capanne sull’isola principale.",al={"chi ha creato gli ammassi","ammassi di zalazane","origine del ju-ju"}},{q="Che cosa fanno gli ammassi?",a="Gli ammassi corrompono la fauna e potenziano gli stregoni e le creature infernali.",al={"cosa sono gli ammassi di ju-ju","effetto degli ammassi","perché distruggere il ju-ju"}},{q="Dove sono gli ammassi di ju-ju?",a="Zalazane li ha collocati tra le sue capanne sull’isola principale delle Isole dell’Eco.",al={"dove sono gli ammassi","ammassi delle isole dell’eco","posizione del ju-ju"}},{q="Chi mi chiede di distruggerli?",a="Un’thuwa, nel Villaggio di Sen'jin, ti chiede di distruggere gli ammassi di ju-ju.",al={"chi assegna l'incarico","richiesta di un’thuwa","chi vuole eliminare gli ammassi"}},{q="Perché qui è importante la magia di Durotar?",a="Gli ammassi perturbano il normale flusso della magia a Durotar. Se rimangono, quel flusso potrebbe cambiare per sempre.",al={"flusso della magia","magia di durotar","perché importa la magia"}}},fp="11,123,13.261.0,16.225.1,27.96.0,21.74.0,26.58.0,28.64.0,37.95.0"}
P.entries["quest:1885"] = {n="Mennet Carkad",s="A Sepulcra, Marion Call ti manda a fare rapporto a Mennet Carkad. Nel cuore del Rogues' Quarter, mette alla prova gli agenti promettenti per i Deathstalkers.",h="A Sepulcra, Marion Call ti manda a fare rapporto a Mennet Carkad.",kw={"assassino","the deathstalkers","ladro reietto","marion call","mennet carkad","rogues' quarter","sepulcra"},ang={["class:Rogue"]="Come ladro, rispondi a una convocazione che segna il tuo passaggio da tagliaborse inesperto ad agente riconosciuto dei Deathstalkers, parte della rete d'élite dei Reietti che opera nell'ombra.",["race:Undead"]="Come non morto, sai che i Deathstalkers contribuiscono a tenere in vita i Reietti. Danno la caccia agli zeloti scarlatti e a ciò che resta del Flagello, e proteggono la regina Sylvanas dalle minacce nascoste."},sec={{t="Una convocazione dalle ombre",b="Marion Call ti porta una convocazione da parte di Mennet Carkad. A Sepulcra, i vertici tengono d'occhio gli agenti segreti, e Marion porta la notizia quando un esploratore o un assassino viene convocato. Il servizio segreto dei Reietti è temuto per le sue operazioni letali. Ignorare i suoi ordini non è una vera scelta."},{t="Unirsi ai The Deathstalkers",b="Mennet Carkad attende nel Rogues' Quarter, dove osserva le reclute e valuta se sono pronte. Chi risponde alla sua chiamata affronta delle prove per entrare nei Deathstalkers, il temuto braccio dei Reietti dedito allo spionaggio e all'assassinio. Per servire la Signora Oscura dalle ombre, l'obbedienza viene prima di tutto."}},faq={{q="Chi è Mennet Carkad?",a="Mennet Carkad addestra i ladri e supervisiona i Deathstalkers nel Rogues' Quarter di Sepulcra. Tiene d'occhio gli agenti segreti promettenti e assegna incarichi importanti per i vertici dei Reietti.",al={"lore di mennet carkad","chi è carkad"}},{q="Cosa succede se qualcuno ignora la convocazione di Mennet Carkad?",a="Marion Call ti avverte di non chiedere cosa sia successo a chi ha ignorato la chiamata di Carkad. Non spiega quale sia stata esattamente la loro sorte.",al={"ignorare carkad","cosa succede se ignori la convocazione"}},{q="Chi sono i The Deathstalkers?",a="I Deathstalkers sono un ordine d'élite di ladri, spie e assassini al servizio dei Reietti. Dalle ombre di Sepulcra, eliminano bersagli di grande valore, raccolgono informazioni e difendono Lordaeron da nemici come la Crociata Scarlatta e il Flagello.",al={"lore dei deathstalker","cosa sono i the deathstalkers"}},{q="Dove posso trovare Mennet Carkad?",a="Puoi trovare Mennet Carkad nel Rogues' Quarter di Sepulcra, tra agenti segreti, istruttori e forniture per le arti dell'ombra.",al={"posizione di carkad","dove si trova mennet carkad"}},{q="Chi assegna la missione per cercare Mennet Carkad?",a="Dalla Taverna dell'Impiccato di Brill, Marion Call ti manda a cercare Mennet Carkad. Ha notato le tue crescenti abilità e ti avverte che Carkad esige un'obbedienza immediata.",al={"chi inizia questa missione","missione di marion call"}},{q="Cosa succede dopo aver fatto rapporto a Mennet Carkad?",a="Fare rapporto a Mennet Carkad ti porta direttamente al servizio dei Deathstalkers. I tuoi primi incarichi servono a dimostrare la tua astuzia e la tua lealtà alla causa dei Reietti.",al={"missione successiva dopo carkad","cosa vuole carkad"}}},fx={f971228d={q="Perché Marion Call ti manda da Mennet Carkad?",a="Marion Call dice che Mennet Carkad ti ha notato e si aspetta di incontrarti. Ti esorta a rispondere alla sua convocazione e ti mette in guardia in modo sinistro su chi l'ha ignorata, senza spiegare quale sorte sia toccata loro.",al={"perché marion call vuole che venga fatto","perché andare da mennet carkad","motivo di marion call"}}},fp="13,149,26.283.0,25.290.0,21.185.0,56.121.0,26.257.0,31.123.0,46.161.0,44.163.0"}
P.entries["quest:1886"] = {n="The Deathstalkers",s="Mennet Carkad mette alla prova gli aspiranti Deathstalkers a Sepulcra, mandandoli sulle tracce di un messaggero in viaggio. Solo i più spietati troveranno posto nell'ordine segreto di Lord Varimathras.",h="Mennet Carkad mette alla prova gli aspiranti Deathstalkers a Sepulcra, mandandoli sulle tracce di un...",kw={"astor hadren","the deathstalkers","mennet carkad","rogues' quarter","selva pinargento","sepulcra","varimathras"},ang={["class:Rogue"]="Come ladro dei Reietti, entrare nei Deathstalkers ti porta ai vertici del servizio dello Stato. Lì, furfanti esperti della vita di strada diventano strumenti vincolati da un giuramento a Varimathras e alla Dark Lady.",["faction:Horde"]="Come membro dell'Orda, potresti non sapere fino a che punto i Deathstalkers operino in segreto. Mantengono reti informative vitali, mentre gli alleati meridionali dell'Orda restano perlopiù all'oscuro degli affari interni più loschi dei Reietti.",["race:Undead"]="Come non morto, vedi i Deathstalkers garantire la sicurezza interna di Lordaeron con il pugno di ferro. Vigilano sui nemici esterni ai Reietti e tengono d'occhio con diffidenza i potenziali traditori al loro interno."},sec={{t="Una prova nell'ombra",b="Nel Rogues' Quarter, Mennet Carkad prepara una prova per chiunque cerchi un posto tra i Deathstalkers. Servono Varimathras come polizia segreta e assassini d'élite dei Reietti. Un aspirante agente deve mostrare astuzia e discrezione, poi dimostrare la volontà di eliminare un bersaglio. Carkad intende respingere i deboli e chiunque sia tormentato da troppi scrupoli."},{t="L'intercettazione",b="Astor Hadren porta una lettera lungo la strada tra Sepulcra e la Selva Pinargento. Carkad lascia a te la scelta di come agire. Per ottenere la presentazione personale di Hadren, devi intercettarlo e impadronirti delle sue credenziali. Poi i Deathstalkers potranno farti passare per lui davanti ad Andron."}},faq={{q="Chi sono i The Deathstalkers?",a="I Deathstalkers sono l'ordine segreto dei Reietti e il loro corpo d'élite specializzato nelle operazioni furtive e nell'assassinio. Dal Rogues' Quarter di Sepulcra, raccolgono informazioni e conducono operazioni di spionaggio ed esecuzioni clandestine. Rispondono a Lord Varimathras.",al={"lore dei deathstalkers","cosa sono i deathstalkers","furfanti non morti"}},{q="Chi è Mennet Carkad?",a="Mennet Carkad è un supervisore dei Deathstalkers nel Rogues' Quarter di Sepulcra. Sovrintende alle prime prove e mette alla prova le reclute che sperano di entrare nei ranghi dell'ordine segreto.",al={"ruolo di mennet carkad","chi dà la missione"}},{q="Perché Mennet ha bisogno della lettera di Astor Hadren?",a="La Lettera di Presentazione di Astor Hadren permette a un nuovo agente di prendere il suo posto. I Deathstalkers possono usarla per ingannare Andron.",al={"lettera di astor hadren","perché intercettare il messaggero","lettera di presentazione di astor"}},{q="Dove viaggia Astor Hadren?",a="Astor Hadren percorre la strada tra Sepulcra e la Selva Pinargento, portando la corrispondenza destinata ai suoi contatti.",al={"rotta di astor hadren","posizione di astor hadren","dov'è astor"}},{q="Chi è Lord Varimathras?",a="Lord Varimathras è un signore del terrore Nathrezim che si è alleato con la regina Sylvanas Ventolesto per preservare la propria esistenza. Dal Quartiere Reale, sovrintende alla sicurezza, alla difesa e alle operazioni dei ladri di Sepulcra.",al={"ruolo di varimathras","signore del terrore a sepulcra"}},{q="Cosa succede dopo questa prova?",a="Superare la prova dimostra la competenza di un agente. Conduce a un incarico segreto sotto falsa identità: consegnare i documenti di Astor e infiltrarsi negli affari di Andron.",al={"what comes next","continuazione della serie di missioni dei deathstalkers"}}},fx={f8c6b26b={q="Perché Mennet Carkad manda te invece di un agente esperto?",a="Stai cercando di dimostrare di essere degno di unirti ai The Deathstalkers, i ladri d'élite al servizio di Lord Varimathras. Mennet impiega deliberatamente le reclute in prova in rischiose missioni sul campo, dove sono sacrificabili, per verificare se possiedono l'astuzia e la letalità richieste dall'ordine.",al={"perché io per i deathstalkers","perché mennet manda me","perché non usare un deathstalker esperto"}},["1398690a"]={q="Perché Mennet Carkad vuole che tu lo faccia?",a="Mennet Carkad sta conducendo un'operazione di infiltrazione che dipende dall'intercettazione di una comunicazione destinata a un contatto di nome Andron. Rubando la lettera di Astor Hadren, Mennet si assicura le credenziali necessarie per far entrare un agente nelle grazie di Andron senza destare sospetti.",al={"perché serve a mennet","motivo di mennet carkad","perché rubare la lettera"}},["763d70d5"]={q="Chi è Astor Hadren?",a="Astor Hadren è un corriere che viaggia tra la Selva Pinargento e Sepulcra. Porta con sé una lettera di presentazione destinata a un contatto di nome Andron, ignaro che The Deathstalkers stanno prendendo di mira la sua corrispondenza per i loro piani clandestini.",al={"chi è hadren","astor hadren","bersaglio astor hadren"}}},fp="17,175,21.348.0,16.280.1,26.245.0,21.152.0,43.122.0,31.116.0,24.207.0,30.155.1"}
P.entries["quest:189"] = {n="Bloodscalp Ears",s="A Baia del Bottino, Bloodscalp Ears offre a Kebok un modo per rendere conto delle perdite crescenti. Paga per una prova dell'uccisione dopo che gli scontri con la tribù Bloodscalp gli sono costati guardie e agenti.",h="A Baia del Bottino, Bloodscalp Ears offre a Kebok un modo per rendere conto delle perdite crescenti.",kw={"bloodscalp","baia del bottino","orecchie","kebok","granbottino","rovotorto","troll"},sec={{t="Costi in aumento",b="Nella Valle di Rovotorto, i troll Bloodscalp stanno uccidendo gli agenti e le guardie di Kebok. Molte delle sue migliori guardie sono cadute nelle scaramucce nella giungla. I costi crescenti lo preoccupano perché dovrà giustificarli al Barone Granbottino."},{t="Una taglia limitata",b="Kebok offre denaro ai viaggiatori che danno la caccia ai troll Bloodscalp nella giungla. Ti chiede di riportare quindici orecchie mozzate come prova delle uccisioni."}},faq={{q="Chi è Kebok?",a="Kebok è un goblin di Baia del Bottino i cui agenti e guardie lavorano nella giungla. Deve rendere conto dei loro costi al Barone Granbottino.",al={"kebok","chi è kebok","chi chiede orecchie di bloodscalp"}},{q="Perché Kebok vuole le orecchie dei Bloodscalp?",a="I troll Bloodscalp hanno ucciso gli agenti di Kebok e molte delle sue migliori guardie nelle scaramucce nella giungla. I costi aumentano e lui deve renderne conto al Barone Granbottino.",al={"perché le orecchie","perché orecchie di bloodscalp","perché raccogliere orecchie"}},{q="Quante orecchie sono richieste?",a="Kebok ti chiede di portargli quindici orecchie di Bloodscalp prima di pagarti.",al={"quante orecchie","conteggio orecchie"}},{q="Dove porta questa taglia?",a="Dopo averti pagato per le orecchie di Bloodscalp, Kebok rivolge l'attenzione a un'altra minaccia locale: Skullsplitter Tusks.",al={"what comes next","seguito orecchie di bloodscalp","prossima missione"}}},fp="15,179,14.215.0,16.142.0,13.124.0,36.165.0,27.71.0,33.100.1"}
P.entries["quest:1898"] = {n="The Deathstalkers",s="A Sepulcra, i Deathstalkers indagano sui sospetti tradimenti tra le file dei Reietti. Su richiesta di Lord Varimathras, ti fingi un messaggero atteso e interroghi un mercante che potrebbe aiutare una fazione esterna.",h="A Sepulcra, i Deathstalkers indagano sui sospetti tradimenti tra le file dei Reietti.",kw={"andron gant","apothecarium","astor hadren","deathstalkers","spionaggio","reietti","mennet carkad","sepulcra","varimathras"},ang={["class:Rogue"]="Come ladro, usi l'identità di un morto per far uscire allo scoperto un cospiratore poco accorto. I Deathstalkers conoscono bene questo metodo.",["faction:Horde"]="Come membro dell'Orda, sai che gli intrighi politici si spingono fin sotto Sepulcra. Anche entro i confini dell'Orda, la fiducia scarseggia.",["race:Undead"]="Come Reietto, sai che vigilare significa sopravvivere. Un cittadino scoperto ad aiutare fazioni esterne rischia di essere eliminato dalla polizia segreta della dama oscura."},sec={{t="Una Rete di Inganni",b="Su richiesta di Lord Varimathras, il Deathstalker Mennet Carkad avvia un'operazione di infiltrazione. I Deathstalkers sorvegliano i cittadini Reietti con la stessa attenzione con cui vigilano sulle minacce esterne. Con la lettera di presentazione di Astor Hadren, contraffatta o acquisita, ti avvicini al mercante locale Andron Gant. Cerchi di spacciarti per il corriere che attende."},{t="Il Negozio vicino all'Apothecarium",b="Andron Gant gestisce una bottega vicino all'Apothecarium. Mennet ritiene che il negoziante non abbia l'acume necessario per riconoscere un impostore. Quando mostri la lettera, Gant crede alla tua copertura da corriere e abbassa la guardia. Poi comincia a descrivere i suoi rapporti con una terza parte non identificata."}},faq={{q="Chi è Andron Gant?",a="Andron Gant è un negoziante di Sepulcra, vicino all'Apothecarium. I Deathstalkers e Lord Varimathras sospettano che passi informazioni e aiuti a una fazione esterna sconosciuta.",al={"andron gant","chi è gant","dove si trova andron gant"}},{q="Perché Lord Varimathras è interessato a questo mercante?",a="Lord Varimathras sospetta che Gant collabori con un'organizzazione esterna ai Reietti. Vuole prove dei contatti e delle intenzioni di Gant per proteggere la città e sradicare la sovversione.",al={"perché varimathras è interessato","varimathras andron gant","perché spiare andron"}},{q="Come fa il giocatore a ingannare Andron Gant?",a="Mennet Carkad ti consegna la Lettera di Presentazione di Astor. Gant attende un corriere e i Deathstalkers lo considerano facile da ingannare, quindi la lettera ti permette di conquistare la sua fiducia.",al={"lettera di astor","come ingannare andron gant","travestimento da messaggero"}},{q="Quale gruppo sono i The Deathstalkers?",a="I Deathstalkers sono l'ordine di ladri d'élite e il servizio segreto dei Reietti. Operano nell'ombra agli ordini della regina Sylvanas e di Lord Varimathras per scoprire sedizioni, sabotare i nemici ed eliminare le minacce interne.",al={"lore dei deathstalkers","chi sono i deathstalkers","ladri di sepulcra"}},{q="Dove si può trovare Andron Gant?",a="Andron Gant lavora nella sua bottega vicino all'ingresso del quartiere dell'Apothecarium a Sepulcra. Svolge i suoi affari sotto la sorveglianza della Royal Apothecary Society e dei Deathstalkers.",al={"posizione andron gant","dove si trova il negozio di gant"}},{q="Cosa succede dopo che Gant accetta la lettera?",a="Gant accetta la lettera senza sospetti e ti prende per un messaggero che non ha nulla da nascondere. Accenna a una collaborazione con conoscenze comuni, dandoti l'occasione di cercare ulteriori prove del suo tradimento.",al={"cosa fa gant","reazione di gant"}}},fx={["6d39edb7"]={q="Perché Mennet Carkad vuole che si indaghi su Andron Gant?",a="Mennet Carkad agisce direttamente agli ordini di Lord Varimathras. Il signore del terrore sospetta che Andron Gant stia fornendo di nascosto aiuti e informazioni a una fazione rivale sconosciuta dall'interno della Città Sotterranea. Per proteggere i capi dei Reietti dal sabotaggio interno, Mennet ha bisogno di prove certe del tradimento di Gant e dell'identità dell'organizzazione segreta per cui lavora.",al={"perché indagare su andron gant","motivo di mennet carkad","perché mennet mi manda da gant"}},["3bf738ba"]={q="Perché Mennet Carkad manda te invece di andarci di persona?",a="Mennet Carkad ha già incontrato Andron Gant di persona, quindi la sua presenza comprometterebbe immediatamente la missione. Gant riconoscerebbe subito un agente dei Deathstalkers. Poiché hai la lettera di presentazione di Astor Hadren, Gant non ha motivo di sospettare che tu sia altro che il corriere che aspettava di incontrare.",al={"perché mennet ha bisogno di me","perché mennet non può parlare con gant","perché usare un avventuriero"}}},fp="17,205,15.336.0,30.268.1,19.183.0,52.180.0,40.165.0,33.235.0,31.181.0,43.203.1"}
P.entries["quest:1899"] = {n="The Deathstalkers",s="A Sepulcra, i Deathstalkers rivolgono la fiducia di Andron Gant contro di lui. Credendo che tu sia il corriere che aspettava, Gant ti consegna un libro mastro per i suoi contatti segreti. Lo porti a Mennet Carkad nel Rogues' Quarter, aprendo la strada a operazioni segrete più complesse per lo stato dei Reietti.",h="A Sepulcra, i Deathstalkers rivolgono la fiducia di Andron Gant contro di lui.",kw={"andron gant","assassini","deathstalker","spionaggio","libro mastro","mennet carkad","rogues' quarter","sepulcra"},ang={["class:Rogue"]="Come ladro a Sepulcra, puoi dimostrare la tua discrezione trasportando messaggi riservati per Mennet Carkad senza attirare attenzioni indesiderate.",["race:Undead"]="Come non morto, sai che la sicurezza di Sepulcra è una questione di sopravvivenza. Aiutare i Deathstalkers rafforza il controllo della Dark Lady sulla capitale contro gli infiltrati viventi e i non morti rivali."},sec={{t="Un corriere nell'ombra",b="Andron Gant conserva nomi e informazioni in un libro mastro personale a Sepulcra. Credendo che tu sia il corriere che aspettava, ti affida il libro mastro da consegnare ai suoi contatti segreti. Gant chiede che sia lo stesso corriere a portare i messaggi futuri. Non sa che il libro mastro è destinato ai Deathstalkers."},{t="Intelligence nel Rogues' Quarter",b="Mennet Carkad riceve il libro mastro di Gant nel Rogues' Quarter e vi trova più informazioni utili di quante si aspettasse. I dettagli offrono a Carkad piste per ampliare le indagini dei Deathstalkers. Il regno dei Reietti è diffidente, e questi documenti potrebbero aiutare a scoprire attività sovversive interne e minacce esterne prima che raggiungano la capitale."}},faq={{q="Cosa c'è nel Libro Mastro di Andron?",a="Il libro mastro di Andron Gant contiene informazioni riservate e documenti da lui raccolti. Mennet Carkad vi trova più dettagli e informazioni preziose di quanto i Deathstalkers si aspettassero.",al={"contenuto del libro mastro di andron","cosa dice il libro mastro","libro mastro dei deathstalker"}},{q="Chi sono i The Deathstalkers?",a="I Deathstalkers sono l'organizzazione segreta e la gilda di assassini dei Reietti. Dalla loro base nel Rogues' Quarter di Sepulcra, servono Dama Sylvanas Ventolesto come occhi, orecchie e pugnali nascosti. Si occupano di spionaggio, raccolta di informazioni e assassinii mirati in tutta Lordaeron.",al={"lore dei deathstalker","chi sono i deathstalker","ladri di sepulcra"}},{q="Perché Gant vuole che in futuro venga usato lo stesso corriere?",a="Gant vuole che in futuro i documenti riservati siano trasportati da un messaggero di cui si fida. Affidarsi allo stesso corriere mantiene il loro accordo di collaborazione e riduce il rischio di furti o manomissioni.",al={"perché piaci a gant","fiducia di andron gant","corriere di gant"}},{q="Chi è Mennet Carkad?",a="Mennet Carkad è un agente dei Deathstalkers nel Rogues' Quarter. Coordina gli agenti locali, raccoglie informazioni sul campo da informatori come Andron Gant e dirige incarichi segreti nella capitale e nei territori circostanti.",al={"lore di mennet carkad","chi è carkad"}},{q="Dove si trova il Rogues' Quarter?",a="Il Rogues' Quarter si trova nel distretto meridionale di Sepulcra. È la base principale per agenti furtivi, ladri e assassini dei Reietti, con il Cortile d'Addestramento e alcove buie lontane dalle piazze pubbliche delle rovine sovrastanti.",al={"posizione del rogues quarter","dov'è il rogues quarter","rogues' quarter di sepulcra"}},{q="Perché i Reietti hanno bisogno di un servizio segreto interno?",a="Ai Reietti serve un servizio segreto interno per scoprire attività sovversive entro i confini di Lordaeron. I Deathstalkers aiutano la giovane nazione a sopravvivere alle minacce del Flagello, della Crociata Scarlatta, dei diffidenti superstiti dell'Alleanza, delle infiltrazioni e delle ribellioni.",al={"perché esistono i deathstalker","spie dei reietti","servizi segreti di sepulcra"}}},fx={["63e535f7"]={q="Perché Andron Gant vuole che gli venga consegnato il registro?",a="Andron Gant crede che tu sia il messaggero inviato dai contatti segreti a cui ha fornito informazioni. Ti consegna il registro perché tu lo porti a loro e ti chiede di tornare se vorranno proseguire l'accordo, senza sospettare che finirà direttamente nelle mani dei Deathstalkers.",al={"perché consegnare il registro","motivo di andron gant","perché andron collabora"}}},fp="17,280,24.297.0,35.334.1,27.170.0,26.272.0,55.170.0,21.242.0,37.231.0,57.245.0"}
P.entries["quest:19"] = {n="Tharil'zun",s="Vicino al Mastio di Guardamasso, il Maresciallo Marris prende di mira Tharil'zun, i cui esploratori infestano le strade. La sua morte è un passo cruciale per spezzare la presa del clan Roccianera sulle Montagne Crestarossa settentrionali, e la sua Testa Mozzata portata a Borgolago segna una vittoria duramente conquistata dalla guardia cittadina.",h="Vicino al Mastio di Guardamasso, il Maresciallo Marris prende di mira Tharil'zun, i cui esploratori infestano...",kw={"roccianera","borgolago","maresciallo marris","esploratori","montagne crestarossa","guardamasso","mastio di guardamasso","tharil'zun","tharilzun"},ang={["faction:Alliance"]="Borgolago è in gran parte isolata, senza rinforzi diretti da Roccavento. La taglia su Tharil'zun è una misura locale essenziale per impedire che la cittadina venga assediata.",["race:Human"]="Come umano, la presenza dei Roccianera nelle Montagne Crestarossa ti ricorda le First and Second Wars. Uccidere Tharil'zun significa riconquistare il territorio sottratto al regno.",["race:Orc"]="Come orco, affronti Tharil'zun, uno degli oscuri resti dell'Old Horde sotto lo stendardo dei Roccianera, al servizio di padroni che rifiutano il nuovo ordine di Thrall oltre il mare."},sec={{t="La strada per Guardamasso",b="La strada tra Borgolago e il Mastio di Guardamasso è diventata pericolosa per via delle imboscate improvvise. Esploratori e rinnegati Roccianera si aggirano tra le creste rocciose, isolando i ricognitori e minacciando i rinforzi diretti alla fortezza. Il Maresciallo Marris indica Tharil'zun come il comandante che dirige questi attacchi. Afferma che Tharil'zun deve essere eliminato, altrimenti Borgolago rischia di essere completamente accerchiata."},{t="Decapitazione degli esploratori",b="Tharil'zun è un pericoloso comandante sul campo, feroce e astuto, che riunisce gruppi sparsi di razziatori orchi in una forza efficace. Raggiungerlo all'ombra di Guardamasso significa farsi strada attraverso gli avamposti fortificati dei Roccianera. La sua morte spezza la coesione delle pattuglie di esploratori e apre la strada all'Alleanza per affrontare la guarnigione all'interno del mastio."}},faq={{q="Chi è Tharil'zun?",a="Tharil'zun è un formidabile comandante orco dei Roccianera che guida gli esploratori e i rinnegati nelle imboscate lungo i sentieri tra Borgolago e il Mastio di Guardamasso.",al={"chi è tharilzun","lore tharil'zun","boss tharilzun"}},{q="Dove si può trovare Tharil'zun?",a="Tharil'zun si trova vicino al Mastio di Guardamasso, nelle Montagne Crestarossa nordorientali, e comanda gli esploratori che pattugliano i passi e gli avamposti circostanti.",al={"dove si trova tharil'zun","posizione tharilzun","trovare tharil'zun"}},{q="Perché il Maresciallo Marris vuole la sua testa?",a="Marris considera Tharil'zun l'astuto stratega che dirige le imboscate che tormentano le Montagne Crestarossa. Esige la Testa di Tharil'zun per privare gli esploratori del loro comandante e dimostrare che la minaccia è stata eliminata.",al={"perché uccidere tharilzun","motivo taglia tharilzun"}},{q="Cosa succede dopo la sconfitta di Tharil'zun?",a="Sconfiggere Tharil'zun compromette il coordinamento degli esploratori, permettendo ai difensori di Borgolago e agli avventurieri di addentrarsi nel Mastio di Guardamasso e affrontare la guarnigione principale dei Roccianera.",al={"missione dopo tharilzun","cosa segue tharil'zun"}},{q="Perché gli orchi Roccianera si trovano nelle Montagne Crestarossa?",a="I resti del clan Roccianera si sono spostati a sud dalle Steppe Ardenti alle Montagne Crestarossa. Hanno fortificato vecchi avamposti umani come il Mastio di Guardamasso per minacciare i Regni Orientali, mentre le forze militari di Roccavento sono disperse su troppi fronti.",al={"perché gli orchi roccianera sono nelle montagne crestarossa","background orchi guardamasso"}},{q="Quale prerequisito deve essere completato prima di cacciare Tharil'zun?",a="Prima di mandarti contro Tharil'zun, il Maresciallo Marris ti chiede di dimostrare il tuo valore sfoltendo le forze d'invasione in 'Blackrock Menace'.",al={"prerequisiti tharilzun","come sbloccare missione tharilzun"}}},fx={["3b83e264"]={q="Perché il Maresciallo Marris ha bisogno della testa di Tharil'zun?",a="Il Maresciallo Marris pretende la testa di Tharil'zun come prova certa della morte del signore della guerra. Tharil'zun è un capo astuto e spietato che dirige imboscate contro i difensori di Borgolago, e Marris non può affidarsi a voci o rapporti errati quando la sicurezza dell'intera regione è appesa a un filo.",al={"a cosa serve la testa di tharil'zun","scopo della testa di tharil'zun","perché prendere la testa di tharil'zun"}},["66abe4be"]={q="Perché il Maresciallo Marris manda te invece delle guardie cittadine?",a="La guarnigione locale di Borgolago è allo stremo. Con Roccavento che nega i rinforzi e le imboscate degli orchi che si avvicinano alla città, il Maresciallo Marris non può privarsi di uomini per penetrare in profondità nel territorio di Guardamasso. Deve affidarsi ad avventurieri esperti e indipendenti per eliminare i comandanti nemici più importanti.",al={"perché mandare un avventuriero","perché non usare le guardie di redridge","perché marris ha bisogno di me"}}},fp="10,267,22.374.0,27.334.0,18.149.0,30.130.0,38.197.0,42.184.0,45.212.0,62.141.0"}
P.entries["quest:190"] = {n="Panther Mastery",s="Presso la Spedizione di Nesingwary, Ser S. J. Erlgadin mette alla prova chi cerca un posto nella compagnia di caccia di Hemet. Devono abbattere dieci giovani pantere per dimostrare la loro abilità nel seguirne le tracce.",h="Presso la Spedizione di Nesingwary, Ser S.",kw={"hemet","nesingwary","panther mastery","ser s. j. erlgadin","valle di rovotorto","giovani pantere"},sec={{t="Un gruppo di cacciatori d'élite",b="Hemet Nesingwary ha radunato esperti cacciatori di grossa selvaggina nella parte settentrionale della Valle di Rovotorto. Ser S. J. Erlgadin chiede ai nuovi arrivati di dimostrare di saper cacciare le pantere prima di unirsi alla compagnia."},{t="Tracciare i vagabondi",b="Prima di affidare ai nuovi arrivati prede più grandi, Erlgadin li mette alla prova. Devono trovare e uccidere dieci giovani pantere. Trovare questi predatori furtivi è solo metà della sfida."}},faq={{q="Chi assegna questa sfida di caccia?",a="Ser S. J. Erlgadin lancia la sfida all'accampamento della Spedizione di Nesingwary, nella parte settentrionale della Valle di Rovotorto. Mette alla prova i nuovi arrivati che sperano di unirsi alla compagnia di caccia di Hemet.",al={"datore missione panther mastery","chi inizia panther mastery","missione di erlgadin"}},{q="Quale preda deve essere cacciata?",a="I cacciatori devono seguire le tracce e uccidere dieci giovani pantere nel folto della giungla circostante.",al={"cosa devo uccidere per panther mastery","bersaglio di panther mastery","giovani pantere"}},{q="Perché Ser S. J. Erlgadin assegna questa prova?",a="Hemet Nesingwary ha radunato una squadra di cacciatori esperti. Erlgadin chiede ai nuovi arrivati di dimostrare di saper cacciare le pantere prima di unirsi alla caccia.",al={"perché uccidere giovani pantere","scopo di panther mastery"}},{q="Cosa succede dopo aver completato questa caccia?",a="Dopo questa prova iniziale, Ser S. J. Erlgadin assegna una caccia più difficile in Panther Mastery due.",al={"prossima missione panther mastery","cosa viene dopo panther mastery"}}},fp="15,166,24.181.0,21.163.0,33.161.0,27.79.0,45.135.0,43.87.0"}
P.entries["quest:191"] = {n="Panther Mastery",s="Alla Spedizione di Nesingwary, Ser S. J. Erlgadin ti chiede di dimostrare il tuo valore tra i cacciatori esperti. Dopo la tua caccia alle giovani pantere, ti manda nella Valle di Rovotorto a caccia di dieci esemplari adulti.",h="Alla Spedizione di Nesingwary, Ser S.",kw={"grossa selvaggina","erlgadin","caccia","maestria","nesingwary","pantera","rovotorto"},sec={{t="Uno standard più elevato",b="La tua caccia alle giovani pantere è conclusa e Ser S. J. Erlgadin alza l'asticella. Ti chiede di dimostrare di essere all'altezza degli esperti cacciatori di grossa selvaggina della spedizione. Così parti per rintracciare e uccidere dieci pantere adulte, più forti e pericolose dei loro simili più giovani."}},faq={{q="Chi offre questa prova?",a="Ser S. J. Erlgadin, un cacciatore della Spedizione di Nesingwary nella parte settentrionale della Valle di Rovotorto, sovrintende a questa fase della caccia.",al={"chi assegna panther mastery","missione di erlgadin","conferitore della missione"}},{q="Quale preda ti viene chiesto di cacciare?",a="Ti viene chiesto di rintracciare e uccidere dieci pantere adulte nella giungla circostante. Sono più resistenti delle giovani pantere che hai cacciato in precedenza.",al={"quali pantere uccidere","quali bestie","obiettivo di panther mastery"}},{q="Cosa precede questa sfida?",a="Una prova precedente, anch'essa intitolata Panther Mastery, ha messo alla prova la tua abilità contro le pantere più giovani della giungla.",al={"missione precedente","passaggio precedente","prerequisito di panther mastery"}},{q="Qual è lo scopo di cacciare queste pantere?",a="Ser S. J. Erlgadin ti chiede di dimostrare la tua abilità e il tuo coraggio per poter cacciare e trascorrere del tempo con gli esperti cacciatori di grossa selvaggina della spedizione.",al={"perché uccidere le pantere","motivo di erlgadin","scopo di nesingwary"}}},fp="15,204,17.279.0,22.120.0,34.140.0,33.97.0,46.144.0"}
P.entries["quest:1918"] = {n="L'elementale contaminato",s="Al Lago Mystral, gli spiriti dell'acqua uccisi lasciano globi luminosi d'acqua contaminata. Ne porti uno a Mastok Soffionero all'Avamposto di Troncorotto per scoprire cosa abbia avvelenato il lago e i suoi spiriti.",h="Al Lago Mystral, gli spiriti dell'acqua uccisi lasciano globi luminosi d'acqua contaminata.",kw={"valtetra","globo d'acqua contaminata","elementali corrotti","earthen ring","mastok soffionero","lago mystral","avamposto di troncorotto"},ang={["class:Shaman"]="Come sciamano, senti il dolore degli spiriti corrotti del Lago Mystral e sai che l'Earthen Ring deve intervenire.",["faction:Horde"]="Come membro dell'Orda, sai che l'Avamposto di Troncorotto non può permettere che una minaccia elementale incomba sul territorio circostante mentre le sentinelle dell'Alleanza e i furbolg minacciano le vie di rifornimento dell'Orda.",["race:Tauren"]="Come tauren, senti il profondo dovere culturale di risanare le acque corrotte della terra, rendendo il ripristino del Lago Mystral un compito spirituale urgente."},sec={{t="Acque Contaminate del Lago Mystral",b="Nella zona centro-meridionale di Valtetra, gli elementali dell'acqua del Lago Mystral sono diventati violenti e visibilmente corrotti. Quando vengono uccisi, lasciano strane sfere luminose di fluido putrido al posto della pura essenza elementale. I globi racchiudono la corruzione che si è posata sul lago. C'è qualcosa all'opera che va oltre la naturale aggressività territoriale."},{t="In cerca del consiglio di Troncorotto",b="All'Avamposto di Troncorotto, gli esploratori dell'Orda cercano consiglio da Mastok Soffionero, che sovrintende all'avamposto. Disgustato dal ripugnante campione, Mastok ammette di essere un soldato, non uno studioso. L'acciaio comune non può curare l'acqua malata, così ti indirizza agli esperti degli elementi dell'Earthen Ring."}},faq={{q="Cosa c'è dentro il Globo d'Acqua Contaminata?",a="Il Globo d'Acqua Contaminata racchiude un disgustoso campione concentrato della corruzione che avvelena il Lago Mystral. Si forma dagli elementali uccisi, mostrando che la loro corruzione spirituale ha assunto una forma fisica e potente.",al={"contenuto del globo contaminato","cosa c'è nel globo d'acqua","globo d'acqua lago mystral"}},{q="Dove inizia questa missione?",a="Trovi il globo combattendo contro gli elementali dell'acqua infuriati o contaminati al Lago Mystral, nella zona centro-meridionale di Valtetra.",al={"dove trovo il globo d'acqua","come iniziare l'elemento contaminato","inizio missione"}},{q="Perché Mastok Soffionero non vuole averci nulla a che fare?",a="Mastok Soffionero è un ufficiale dell'Orda che si occupa della sopravvivenza militare e della logistica all'Avamposto di Troncorotto. Non è portato a diagnosticare i mali delle acque magiche, così ti indirizza all'Earthen Ring.",al={"chi è mastok","perché parlare con mastok","ruolo di mastok soffionero"}},{q="Qual è l'interesse dell'Earthen Ring in questa vicenda?",a="L'Earthen Ring è un ordine di sciamani dediti a studiare gli elementi, placarli e ristabilirne l'armonia. Gli elementali corrotti come quelli del Lago Mystral rientrano nelle loro cure spirituali.",al={"perché l'earthen ring","collegamento con l'earthen ring","che cos'è l'earthen ring"}},{q="Dove porta l'indagine?",a="Mastok ti indirizza a Je'neu Sancrea, uno sciamano dell'Earthen Ring di stanza a Zoram'gar Strand, lungo la costa occidentale di Valtetra. Je'neu può esaminare la reliquia contaminata.",al={"what comes next","missione successiva a l'elemento contaminato","dove andare dopo"}}},fp="20,197,30.323.0,30.288.1,40.214.0,28.114.0,53.201.0,44.190.0,39.164.1"}
P.entries["quest:192"] = {n="Panther Mastery",s="Nella Valle di Rovotorto, Panther Mastery ti manda a caccia delle pantere più letali. Dopo le prove precedenti, le tue prede sono dieci Panther Shadowmaw.",h="Nella Valle di Rovotorto, Panther Mastery ti manda a caccia delle pantere più letali.",kw={"grossa selvaggina","nesingwary","panther mastery","panther shadowmaw","ser s. j. erlgadin","valle di rovotorto"},ang={["class:Hunter"]="Come cacciatore, affronti la sfida con cui Erlgadin mette alla prova la tua reputazione di cacciatore di grossa selvaggina. Si aspetta che tu segua le tracce dei predatori più feroci della giungla e li abbatta."},sec={{t="La preda più letale",b="Ser S. J. Erlgadin definisce le Panther Shadowmaw i felini più pericolosi delle giungle di Rovotorto. Per dimostrare il tuo valore come inseguitore, strisci nel fitto sottobosco e rintracci dieci bestie sfuggenti. La loro ferocia le rende più difficili da uccidere che da trovare."}},faq={{q="Chi offre questa caccia?",a="Ser S. J. Erlgadin propone questa caccia dall'accampamento della Spedizione di Nesingwary, nella parte settentrionale della Valle di Rovotorto.",al={"chi dà panther mastery","datore di missione panther mastery","chi assegna questa missione"}},{q="Quali bestie stai cacciando?",a="Dai la caccia a dieci Panther Shadowmaw, che Erlgadin definisce le pantere più letali di tutta Rovotorto.",al={"cosa devo uccidere","bersaglio di panther mastery","quali pantere"}},{q="Come si inserisce questo nelle prove di caccia?",a="Questa è la terza prova di caccia alle pantere, dopo la seconda prova di Panther Mastery e prima della quarta.",al={"quale missione precede questa","serie panther mastery","missione prerequisito"}}},fp="15,145,20.247.0,21.103.0,28.101.0,42.102.0"}
P.entries["quest:1920"] = {n="Investigate the Blue Recluse",s="Jennea Acquachiara ti chiede di indagare su strane creature invisibili nella taverna Blue Recluse. Teme che vi si sia aperta una frattura di mana.",h="Jennea Acquachiara ti chiede di indagare su strane creature invisibili nella taverna Blue Recluse.",kw={"blue recluse","canto della manifestazione","scrigno di contenimento","creature invisibili","jennea acquachiara","quartiere dei maghi","frattura di mana"},ang={["class:Mage"]="In quanto mago, porti le creature catturate a Jennea Acquachiara affinché possano essere studiate."},sec={{t="Al Blue Recluse",b="Jennea Acquachiara segnala strani fenomeni al Blue Recluse, nel Quartiere dei Maghi. Creature invisibili ora vagano per la taverna, e lei teme che si sia formata una frattura di mana. Ti viene chiesto di rendere visibili le creature e catturarle in scrigni di contenimento. A Jennea servono le creature catturate per studiarle."}},faq={{q="Cosa sta succedendo al Blue Recluse?",a="Creature invisibili vagano per il Blue Recluse, e Jennea Acquachiara teme che vi si sia formata una frattura di mana.",al={"strani fenomeni blue recluse","cosa non va alla taverna"}},{q="Chi mi ha mandato a indagare?",a="Jennea Acquachiara ti chiede di indagare sugli strani fenomeni al Blue Recluse.",al={"chi me l'ha chiesto","jennea blue recluse"}},{q="Perché Jennea vuole le creature?",a="Jennea vuole studiare le creature per determinare perché siano arrivate.",al={"perché catturarle","a cosa servono le creature"}},{q="Come faccio a rendere visibili le creature?",a="Il Canto della Manifestazione rende visibili le creature all'interno della taverna.",al={"uso del canto","rendere visibili le creature"}},{q="Cosa teme che sia successo Jennea?",a="Jennea teme che si sia formata una frattura di mana al Blue Recluse.",al={"frattura di mana taverna","frattura al blue recluse"}}},fp="28,133,19.289.0,38.105.0,27.74.0,35.66.0,36.77.0,35.56.0"}
P.entries["quest:193"] = {n="La maestria nella caccia alla pantera",s="Alla Spedizione di Nesingwary, Ser S. J. Erlgadin ti affida un'ultima prova. Hai già cacciato le pantere, ma il gruppo della spedizione non è riuscito a trovare Bhag'thera. Riporta la zanna del predatore per dimostrare la tua abilità di maestro della caccia.",h="Alla Spedizione di Nesingwary, Ser S.",kw={"bhag'thera","zanna di bhag'thera","spedizione di nesingwary","panther mastery","ser s. j. erlgadin","valle di rovotorto"},sec={{t="Il predatore sfuggente",b="Alla Spedizione di Nesingwary, Ser S. J. Erlgadin ti affida un'ultima prova. Bhag'thera si aggira ancora per la Valle di Rovotorto, fuori dalla portata del gruppo della spedizione. Rintraccia la grande pantera e riporta la sua zanna come prova della tua abilità."}},faq={{q="Chi offre questa caccia?",a="Ser S. J. Erlgadin propone questa caccia presso la Spedizione di Nesingwary, nella parte settentrionale della Valle di Rovotorto.",al={"datore di missione","chi fornisce panther mastery","missione erlgadin"}},{q="Quale bestia stai cacciando?",a="Stai dando la caccia a Bhag'thera, una grande pantera che si aggira nella giungla ed è sfuggita al gruppo della spedizione.",al={"qual è il bersaglio","chi è bhag'thera","bersaglio pantera"}},{q="Quale trofeo è richiesto?",a="Ser S. J. Erlgadin richiede la Zanna di Bhag'thera come prova che hai sconfitto la bestia.",al={"quale prova","quale oggetto","trofeo di bhag'thera"}},{q="Cosa precede questa caccia?",a="Questa caccia segue la terza prova della serie Panther Mastery e si basa sulle tue precedenti cacce alle pantere.",al={"missione precedente","prerequisito panther mastery"}}},fp="15,243,19.234.0,21.94.0,27.105.0,24.88.0,27.103.0"}
P.entries["quest:1938"] = {n="Trattato di Ur sull'Ombra",s="High Sorcerer Andromath cerca il Trattato di Ur sull'Ombra a Roccavento. Morganth ha rubato il tomo proibito e lo ha portato alla Torre di Ilgalar nelle Montagne Crestarossa.",h="High Sorcerer Andromath cerca il Trattato di Ur sull'Ombra a Roccavento.",kw={"andromath","ilgalar","morganth","shadow magic","roccavento","trattato","ur","santuario della magia"},ang={["class:Mage"]="Come mago, vedi quanto i maghi di Roccavento prendano sul serio la disciplina all'interno del loro ordine. Ti affidano il compito di contenere il pericolo lasciato da un loro pari che si è dedicato alla Shadow Magic proibita.",["class:Warlock"]="Come stregone, potresti bramare i poteri di evocazione extraplanare e di magia oscura sigillati nei trattati di Ur. Il Kirin Tor e i maghi di Roccavento temono quei poteri.",["faction:Alliance"]="Come membro dell'Alleanza, recuperando il tomo rubato aiuti a proteggere Redridge dalla crescente minaccia magica di Morganth e Roccavento dalla magia arcana dei rinnegati."},sec={{t="Uno scisma nella torre",b="Tre promettenti maghi studiavano insieme nel Santuario della Magia di Roccavento. Morganth si dedicò alle arti oscure e alla Shadow Magic nonostante i loro disperati avvertimenti. L'ordine magico della città lo bandì. Prima di andarsene, rubò un'opera pericolosa di Ur, un famigerato arcimago i cui studi andavano oltre la magia arcana ortodossa."},{t="Il covo del mago caduto",b="Morganth si impadronì della Torre di Ilgalar sulle alture delle Montagne Crestarossa, lontano dagli sguardi di Roccavento. High Sorcerer Andromath teme che il sapere del tomo sia nelle mani di un reietto che pratica stregoneria proibita. Perciò invia gli avventurieri dell'Alleanza nella torre per recuperarlo prima che le sue protezioni cedano."},{t="Protezioni intatte",b="Il trattato di Ur tornò al Santuario della Magia con gli incantamenti protettivi intatti. High Sorcerer Andromath è molto sollevato. Temeva che Morganth avesse dissolto le protezioni o nascosto il libro in un luogo irraggiungibile. I sigilli ressero, impedendo allo stregone rinnegato di accedere ai segreti catastrofici racchiusi nelle sue pagine."}},faq={{q="Chi ha scritto il trattato?",a="Ur scrisse il trattato. Il leggendario mago di Dalaran era rinomato per le sue ricerche esoteriche sulle entità extraplanari e sulla Shadow Magic.",al={"chi è ur","autore del trattato","autore di trattato di ur"}},{q="Chi ha rubato Trattato di Ur sull'Ombra?",a="Morganth rubò il Trattato di Ur sull'Ombra. Era un mago di Roccavento che si dedicò alla magia oscura e fu bandito dal Santuario della Magia.",al={"chi ha rubato il libro","chi ha preso il trattato","libro di morganth"}},{q="Dove viene conservato il libro?",a="Il libro si trova nella biblioteca della Torre di Ilgalar, sulle alture delle Montagne Crestarossa, dove Morganth stabilì il suo nuovo rifugio.",al={"dov'è il trattato","posizione del libro nella torre di ilgalar","dove si trova il trattato di ur"}},{q="Morganth è riuscito a leggere il libro?",a="No. High Sorcerer Andromath conferma che i sigilli protettivi del libro erano ancora intatti alla sua restituzione, quindi Morganth non lo ha mai aperto.",al={"morganth ha aperto il libro","il trattato è stato aperto","i sigilli sono rotti"}},{q="Perché i maghi di Roccavento vogliono indietro il libro?",a="I maghi di Roccavento rivogliono il libro perché i suoi profondi segreti sulla Shadow Magic possono portare alla rovina chi è inesperto. Temono di lasciarlo a Morganth, un reietto che pratica stregoneria proibita.",al={"perché recuperare il libro","perché il trattato è pericoloso","obiettivo di andromath"}},{q="Chi assegna questa missione?",a="High Sorcerer Andromath la assegna dal Santuario della Magia, nel Quartiere dei Maghi di Roccavento.",al={"datore di missione","dove ottenere la missione per il trattato di ur","missione di andromath"}}},fx={["705e1c6d"]={q="Che cos'è il Trattato di Ur sull'Ombra?",a="È un tomo potente e pericoloso che esplora i misteri oscuri della magia dell'ombra. Scritto dal mago del Kirin Tor Ur, non è destinato agli inesperti: addentrarsi nelle sue conoscenze proibite può condurre direttamente alla rovina. Per impedirne l'uso improprio, i maghi di Roccavento hanno sigillato il volume con incantesimi.",al={"trattato di ur sull'ombra","che cos'è il trattato","a cosa serve il trattato di ur"}}},fp="29,173,21.306.0,22.300.0,12.300.1,23.129.0,40.138.0,23.129.0,37.130.1,49.191.0,21.87.0"}
P.entries["quest:1939"] = {n="High Sorcerer Andromath",s="Al Santuario della Magia di Roccavento, i promettenti maghi dell'Alleanza vengono convocati in cima alla torre. Andromath opera tra i più eminenti arcimaghi del regno al di fuori di Dalaran in rovina.",h="Al Santuario della Magia di Roccavento, i promettenti maghi dell'Alleanza vengono convocati in cima alla...",kw={"andromath","arcano","dalaran","jennea acquachiara","quartiere dei maghi","roccavento","santuario della magia"},ang={["class:Mage"]="Come mago, passi dai consueti esercizi di magia con Jennea Acquachiara allo studio di conoscenze pericolose e specialistiche accanto a uno dei più eminenti arcimaghi di Roccavento.",["faction:Alliance"]="Come membro dell'Alleanza, dipendi dal Santuario di Roccavento per addestrare i maghi e contrastare le minacce soprannaturali mentre i maghi sopravvissuti di Dalaran ricostruiscono la loro città in rovina."},sec={{t="Convocazione alla Torre",b="Jennea Acquachiara, la coordinatrice degli apprendisti nel Quartiere dei Maghi di Roccavento, invia gli incantatori promettenti in cima al Santuario della Magia. High Sorcerer Andromath, uno dei più esperti praticanti delle arti arcane ancora attivi nei regni meridionali, ha chiesto di incontrare maghi pronti ad assumersi maggiori responsabilità."},{t="Un Maestro fuori Dalaran",b="La magocrazia di Dalaran è stata devastata durante la Terza Guerra, e i suoi maghi sopravvissuti sono impegnati nella ricostruzione. Senza un facile accesso alle biblioteche della Cittadella Violacea, l'Alleanza si affida agli arcimaghi esperti di Roccavento per studiare antiche minacce e guidare le ricerche sulle arti oscure e proibite."}},faq={{q="Chi è High Sorcerer Andromath?",a="In cima al Santuario della Magia di Roccavento, High Sorcerer Andromath è un mago di grande esperienza. Al di fuori di Dalaran, i suoi pari lo annoverano tra gli incantatori più potenti e sapienti del mondo.",al={"chi è andromath","lore di andromath","alto mago di roccavento"}},{q="Dove posso trovare High Sorcerer Andromath?",a="Andromath si trova in cima al Santuario della Magia, la torre a spirale nel Quartiere dei Maghi di Roccavento.",al={"posizione di andromath","dove si trova andromath","trovare high sorcerer andromath"}},{q="Perché Jennea Acquachiara mi manda da lui?",a="Jennea Acquachiara invia da Andromath gli incantatori promettenti che hanno superato gli insegnamenti di base, perché ricevano consigli avanzati e svolgano ricerche specialistiche e pericolose.",al={"perché parlare con andromath","riferimento di jennea acquachiara"}},{q="Con cosa ha bisogno di aiuto Andromath?",a="Andromath chiama i maghi capaci a indagare sugli oscuri segreti dell'arcano, anche recuperando il pericoloso volume storico Ur’s Treatise on Shadow Magic.",al={"serie di missioni di andromath","cosa vuole andromath"}},{q="Perché Dalaran viene descritta come 'chiusa'?",a="Le parole di Jennea riflettono quanto i Kirin Tor si siano isolati dalla Terza Guerra. Dopo che il Flagello e la Legione Infuocata hanno devastato Dalaran, i maghi sopravvissuti si sono concentrati sulla ricostruzione, lasciando pochi di loro coinvolti nelle vicende esterne.",al={"perché dalaran è chiusa","stato di dalaran","cosa è successo a dalaran"}},{q="Questa missione è esclusiva per i maghi?",a="Sì. La convocazione fa parte del percorso di addestramento dei maghi dell'Alleanza che perfezionano la propria arte.",al={"i non maghi possono farlo","missione solo per maghi"}}},fx={["56d3f2e8"]={q="Perché Jennea Cannon manda me invece di occuparsene personalmente?",a="Jennea Cannon è un'istruttrice nel Santuario della Magia e guida gli apprendisti delle arti arcane. High Sorcerer Andromath ha chiesto espressamente di parlare con te, un mago esperto e promettente, pronto ad affrontare questioni più complesse, invece di distogliere i mentori dell'accademia dai loro compiti d'insegnamento.",al={"perché mandare me","perché jennea non va","perché andromath vuole me"}}},fp="23,179,20.301.0,24.281.0,31.191.0,41.104.0,42.142.0,35.154.1,42.229.0,33.87.0"}
P.entries["quest:194"] = {n="Raptor Mastery",s="Nel suo accampamento a nord della Valle di Rovotorto, Hemet Nesingwary mette alla prova la tua abilità nella caccia. Ti chiede di trovare e uccidere dieci Rapaci di Rovotorto.",h="Nel suo accampamento a nord della Valle di Rovotorto, Hemet Nesingwary mette alla prova la tua abilità nella...",kw={"cacciatore di grandi prede","hemet nesingwary","raptor mastery","rapace di rovotorto","valle di rovotorto"},ang={["class:Hunter"]="Come cacciatore, affronti le prove di Hemet Nesingwary nella natura selvaggia. Lì dimostri la tua capacità di seguire le tracce e la tua abilità nel tiro."},sec={{t="Una prova di abilità",b="Dopo Benvenuto nella Giungla, Hemet Nesingwary mette alla prova la tua capacità di seguire le tracce e cacciare nella giungla. Non ti dà mappe né indicazioni. Trovare i Rapaci di Rovotorto fa parte della prova, e devi abbattere dieci di queste feroci bestie."}},faq={{q="Chi assegna questa sfida di caccia?",a="Hemet Nesingwary, il celebre cacciatore di grossa selvaggina, propone la sfida nel suo campo di spedizione nella parte settentrionale della Valle di Rovotorto.",al={"chi assegna raptor mastery","datore della missione raptor mastery","hemet nesingwary rapaci"}},{q="Quali bestie ti viene chiesto di rintracciare?",a="Ti viene chiesto di scovare e uccidere dieci Rapaci di Rovotorto sparsi per la giungla.",al={"quali rapaci","cosa uccidere per raptor mastery","bersaglio di raptor mastery"}},{q="Perché Hemet si rifiuta di dirti dove vivono i rapaci?",a="Hemet crede che trovare la preda sia metà della prova per diventare un vero cacciatore di grossa selvaggina. Perciò lascia a te la ricerca.",al={"dove si trovano i rapaci","perché non indica la posizione dei rapaci","posizioni dei rapaci"}},{q="Quale passaggio precede questa prova?",a="Questa prova segue la tua prima accoglienza nella natura selvaggia, Benvenuto nella Giungla.",al={"prerequisito per raptor mastery","missione precedente raptor mastery","inizio catena raptor mastery"}}},fp="14,134,15.245.0,33.122.0,40.92.0,57.120.0,34.80.0"}
P.entries["quest:1940"] = {n="Seta di Ragno Intatta",s="A Roccavento, l'High Sorcerer Andromath invia i maghi emergenti dell'Alleanza a Boscovespro in cerca di Seta di Ragno Intatta. Portano otto campioni a Wynne Larson nel Quartiere dei Maghi, dove lei tesse una veste da adepto.",h="A Roccavento, l'High Sorcerer Andromath invia i maghi emergenti dell'Alleanza a Boscovespro in cerca di Seta...",kw={"andromath","ragno recluso necrofago","boscovespro","larson clothiers","vesti da mago","seta di ragno intatta","santuario della magia","wynne larson"},ang={["class:Mage"]="Come mago, con questo rito passi dall'apprendistato al rango di adepto. Ogni mago di Roccavento indossa vesti tessute grazie ai pericoli che ha affrontato di persona.",["faction:Alliance"]="Come suddito dell'Alleanza, lasci il rifugio di Roccavento per avventurarti nella pericolosa Boscovespro e raccogliere una risorsa rara della regione.",["profession:Tailoring"]="Come sarto, puoi osservare come Wynne Larson trasforma le fibre pregiate dei mostri selvatici in un tessuto che accoglie gli incantamenti meglio della comune lana o del lino."},sec={{t="Vesti dell'Adepto",b="L'High Sorcerer Andromath segna il passaggio di un mago oltre l'apprendistato con vesti degne di un adepto. Nel Santuario della Magia, l'abilità di un mago si riconosce dalle vesti che indossa. Ogni mago deve quindi raccogliere seta intatta da ragni pericolosi e dimostrare sia competenza sul campo sia discernimento."},{t="Il Telaio di Boscovespro",b="I ragni reclusi necrofagi si aggirano nei boschi tenebrosi di Boscovespro, e le comuni bancarelle non vendono la loro seta. Raccogli otto campioni pregiati e attraversi Roccavento per portarli a Larson Clothiers, nel Quartiere dei Maghi. Lì, Wynne Larson intreccia i fili delicati per creare una veste dal significato arcano."}},faq={{q="Chi invia i maghi in questo incarico?",a="L'High Sorcerer Andromath invia gli incantatori che hanno dimostrato la propria dedizione. Presiede il Santuario della Magia a Roccavento.",al={"chi fornisce seta di ragno intatta","datore di missione seta di ragno intatta","missione andromath"}},{q="Dove viene raccolta la seta?",a="Raccogli la seta dai ragni reclusi necrofagi nelle foreste infestate e nelle radure coperte di ragnatele di Boscovespro.",al={"dove ottengo seta intatta","posizione ragni","posizione ragno recluso necrofago"}},{q="Chi confeziona la veste con la seta?",a="Wynne Larson tesse la veste presso Larson Clothiers, nel Quartiere dei Maghi di Roccavento.",al={"chi tesse la seta","wynne larson","larson clothiers"}},{q="Perché i maghi usano la seta di ragno per gli indumenti?",a="La Seta di Ragno Intatta è resistente e finemente intrecciata. Permette di creare un tessuto leggero capace di trattenere incantamenti sottili senza appesantire un incantatore.",al={"perché seta di ragno","vesti magiche in seta di ragno"}},{q="Cosa succede dopo aver consegnato la seta?",a="Dopo che Wynne ha ispezionato la seta e lavorato al suo telaio, consegna al mago l'Astral Knot Garment finito.",al={"prossima missione dopo seta di ragno intatta","cosa succede dopo"}},{q="Qualsiasi seta di ragno di Boscovespro è accettabile?",a="No. Per i suoi delicati incantamenti, Larson Clothiers ha bisogno di campioni intatti prelevati con cura dai reclusi necrofagi. Le ragnatele più grossolane non vanno bene.",al={"posso usare la normale seta di ragno","seta intatta contro seta normale"}}},fx={a495a13a={q="Perché High Sorcerer Andromath ti manda a raccogliere la seta?",a="High Sorcerer Andromath ha notato la tua dedizione incrollabile alle arti arcane e crede che sia giunto il momento che il tuo abbigliamento rifletta la tua crescente maestria. Invece di consegnarti una veste già pronta, il Santuario della Magia si aspetta che te la guadagni affrontando i pericoli di Boscovespro per raccogliere i materiali rari necessari a confezionare un abito da adepto.",al={"perché andromath vuole la seta","motivo di andromath","perché andromath assegna questa missione"}},["8d44c073"]={q="Quali creature devi cacciare per ottenere la seta?",a="Devi cacciare i ragni eremiti carognosi che si annidano nei boschi oscuri di Boscovespro. Questi aracnidi velenosi tessono un filo eccezionalmente resistente e risonante, ma solo i filamenti più pregiati e senza imperfezioni sono adatti a un abito incantato.",al={"chi devo cacciare per la seta intatta","quali ragni rilasciano la seta","ragni eremiti carognosi di boscovespro"}}},fp="20,201,22.284.0,20.289.0,35.133.0,28.102.0,34.79.0,42.150.0,37.113.0,44.141.0"}
P.entries["quest:1941"] = {n="Tonaca di Manatrama"}
P.entries["quest:1942"] = {n="Astral Knot Garment",s="A Roccavento, Wynne Larson tesse la Seta di Ragno Intatta per creare un abito adatto a viaggi pericolosi e incontri dell'alta società. Un avventuriero le porta seta rara dalle terre selvagge, e lei la trasforma in un tessuto magico.",h="A Roccavento, Wynne Larson tesse la Seta di Ragno Intatta per creare un abito adatto a viaggi pericolosi e...",kw={"astral knot garment","armatura di stoffa","quartiere dei maghi","seta di ragno intatta","veste di seta","roccavento","sartoria","wynne larson"},ang={["class:Mage"]="Come mago, puoi scorgere in questo abito la dignità arcana di Roccavento, con incantamenti utili per viaggiare oltre le mura fortificate del regno.",["faction:Alliance"]="Come campione dell'Alleanza, puoi trovare nell'artigianato di Roccavento creazioni adatte sia alle sale reali sia alle pericolose prime linee.",["profession:Tailoring"]="Il lavoro di Wynne Larson trasforma la Seta di Ragno Intatta in abiti di grande eleganza."},sec={{t="L'Arguzia di una Sarta",b="Nel Quartiere dei Maghi di Roccavento, i sarti servono le élite arcane e i nobili in visita. Wynne Larson tesse la Seta di Ragno Intatta per creare abiti resistenti e incantati. Il suo umorismo giocoso emerge quando scherza sul tenere qualche prezioso scampolo per il proprio guardaroba prima di consegnare il lavoro finito."},{t="Eleganza Versatile",b="Gli incantatori che indossano vesti di stoffa apprezzano l'Astral Knot Garment per la sua resistenza e raffinatezza. La sua seta proviene da ragni pericolosi, e la sua trama è fatta per resistere al combattimento. Mantiene l'aspetto elegante richiesto ai banchetti formali nel Forte di Roccavento."}},faq={{q="Che cos'è l'Astral Knot Garment?",a="Wynne Larson confeziona l'Astral Knot Garment a Roccavento usando la Seta di Ragno Intatta. È pensato per chi indossa vesti di stoffa e affronta combattimenti o partecipa a eventi dell'alta società.",al={"cos'è astral knot garment","veste astral knot","abiti astral knot"}},{q="Chi crea l'Astral Knot Garment?",a="Wynne Larson, una sarta del Quartiere dei Maghi di Roccavento, confeziona l'abito quando riceve i materiali esotici necessari.",al={"chi crea astral knot","missione wynne larson","sarto astral knot"}},{q="Quali materiali sono necessari per completare questo indumento?",a="L'abito richiede Seta di Ragno Intatta raccolta da ragni letali nelle regioni selvagge del mondo. La lavorazione sartoriale preserva la naturale resistenza della seta e la sua capacità di accogliere incantamenti.",al={"materiali per astral knot","seta di ragno necessaria","come viene realizzato"}},{q="Perché Wynne Larson scherza sul tenere la seta avanzata?",a="Wynne scherza sul confezionare l'abito corto per poter tenere qualche scampolo della rara e pregiata Seta di Ragno. Consegna il lavoro finito nella sua interezza.",al={"ha rubato la mia seta","scherzo di wynne larson","veste corta"}},{q="Dove avviene questa sartoria a Roccavento?",a="La lavorazione sartoriale avviene nel Quartiere dei Maghi di Roccavento, un distretto di studiosi, arcanisti e sarti esperti di tessuti incantati.",al={"dove si trova wynne larson","posizione astral knot","dove consegnare astral knot"}},{q="Chi indossa tipicamente l'Astral Knot Garment?",a="I maghi dell'Alleanza prediligono l'Astral Knot Garment per la sua trama leggera e protettiva e il suo aspetto dignitoso.",al={"chi usa astral knot","per quale classe è","chi lo indossa"}}},fx={["96918ee1"]={q="Perché Wynne Larson confeziona l'Astral Knot Garment?",a="Wynne Larson è un'abile sarta di Roccavento che accetta di tessere l'abito come coronamento dei tuoi sforzi. Dopo averti mandato attraverso terre pericolose a raccogliere componenti rari come la Seta di Ragno Intatta, è orgogliosa di confezionare paramenti eccezionali per chi pratica la magia, unendo protezione pratica e raffinata eleganza formale.",al={"perché wynne larson confeziona l'abito","motivo di wynne larson per l'astral knot garment","perché wynne confeziona la veste"}}},fp="19,217,14.294.0,18.245.0,32.180.0,35.110.0,53.172.0,56.144.0,50.134.0,44.102.0"}
P.entries["quest:1943"] = {n="Speak with Deino",s="A Orgrimmar, Deino chiama i maghi promettenti dell'Orda perché affinino la loro arte. La maga troll opera nella Valle degli Spiriti e cerca un adepto per un incarico importante. La sua convocazione apre la strada a studi più approfonditi e a compiti in tutta Kalimdor.",h="A Orgrimmar, Deino chiama i maghi promettenti dell'Orda perché affinino la loro arte.",kw={"anastasia cuorfosco","rifugio spinabruna","deino","missione del mago","orgrimmar","quithas","valle degli spiriti","waters of xavian"},ang={["class:Mage"]="Come mago, approfondisci il tuo addestramento arcano e incontri incantatori esperti a Orgrimmar.",["faction:Horde"]="Come membro dell'Orda, segui una convocazione che collega gli addestratori di Lordaeron e Durotar ai capi arcani di Orgrimmar.",["race:Troll"]="Come troll, scopri la disciplina arcana rigorosa praticata da pochi eletti tra i Puntascura."},sec={{t="Una convocazione a Orgrimmar",b="I maghi dell'Orda affinano le proprie abilità arcane sotto la guida dei loro istruttori. Quando uno studente è pronto per incarichi più impegnativi, un mentore come Anastasia Cuorfosco a Sepulcra gli indica la strada per Orgrimmar. Lì, nel quartiere dei troll, attendono conoscenze specialistiche e incarichi pericolosi."},{t="La Valle degli Spiriti e il Rifugio Spinabruna",b="Deino vive nel Rifugio Spinabruna, nella Valle degli Spiriti di Orgrimmar. Pochi tra i Puntascura studiano la magia arcana, accanto ai numerosi medici stregoni e sacerdoti, e questo rende Deino un'autorità nella capitale. Il suo lavoro interessa i maghi dell'Orda anche oltre le questioni locali. Cerca incantatori ambiziosi disposti ad affrontare pericoli lontano da casa."}},faq={{q="Chi ti manda a parlare con Deino?",a="Gli addestratori di maghi come Anastasia Cuorfosco nel Quartiere della Magia di Sepulcra mandano gli aspiranti maghi a Orgrimmar quando hanno raggiunto un livello di abilità sufficiente.",al={"datore di missione","chi inizia questa missione","dove ottengo speak with deino"}},{q="Dove posso trovare Deino?",a="Puoi trovare Deino all'interno del Rifugio Spinabruna, nella Valle degli Spiriti, sul lato occidentale di Orgrimmar.",al={"posizione di deino","dove si trova deino","posizione del rifugio spinabruna"}},{q="Perché Deino ha bisogno di aiuto?",a="Deino supervisiona ricerche e incarichi importanti per i maghi dell'Orda. Manda incantatori capaci in terre pericolose alla ricerca di risorse magiche rare.",al={"perché deino ha bisogno di aiuto","cosa vuole deino"}},{q="Cosa succede dopo essersi presentati a Deino?",a="Quando ti presenti da Deino, ti spiega il suo lavoro e ti manda a raccogliere le Acque di Xavian.",al={"missione successiva","cosa viene dopo","missione di seguito"}},{q="Questa missione è disponibile per tutte le classi?",a="No. Solo i maghi dell'Orda ricevono la convocazione di Deino durante il loro addestramento di classe.",al={"è solo per maghi","gli stregoni possono farlo","restrizione di classe"}},{q="I maghi troll sono comuni nell'Orda?",a="La magia arcana è meno diffusa tra i troll Puntascura rispetto allo sciamanesimo, al vudù o al servizio ai loa. Deino dimostra che alcuni troll hanno padroneggiato lo studio formale delle forze arcane.",al={"troll che usano l'arcano","storia dei maghi puntascura"}}},fx={["2e9f17ef"]={q="Perché gli istruttori dei maghi ti mandano da Deino?",a="Man mano che la tua padronanza delle arti arcane cresce, i tuoi mentori nelle città capitali capiscono che ti attendono misteri più profondi oltre l'addestramento standard. La troll maga Deino, a Orgrimmar, sovrintende a incarichi avanzati fondamentali per la comunità dei maghi dell'Orda. Istruttrici come Anastasia Cuorfosco, nella Città Sotterranea, indirizzano a lei gli apprendisti promettenti, affinché tu possa contribuire a questioni importanti per la vostra arte comune.",al={"perché mi mandano da deino","motivo dell'incarico di hartwell","perché anastasia cuorfosco mi manda"}}},fp="16,223,22.271.0,41.309.0,34.140.0,23.98.0,31.142.0,38.93.0,39.79.0,36.175.0"}
P.entries["quest:1944"] = {n="Waters of Xavian",s="A Valtetra, Deino cerca acqua di Xavian per studiare il potere arcano che ancora permea la città. Invia il suo apprendista a prelevare un campione dalla pozza sotto la cascata più alta.",h="A Valtetra, Deino cerca acqua di Xavian per studiare il potere arcano che ancora permea la città.",kw={"valtetra","deino","fiasca","missione per maghi","orgrimmar","satiro","avamposto di troncorotto","waters of xavian","xavian"},ang={["class:Mage"]="Come mago dell'Orda, studi i reagenti arcani avventurandoti in terre selvagge e ostili per raccoglierli.",["faction:Horde"]="Come membro dell'Orda, puoi usare l'Avamposto di Troncorotto come base più vicina a Valtetra orientale prima di attraversare le terre selvagge infestate dai satiri attorno a Xavian."},sec={{t="La curiosità di un mago",b="Deino, una maga troll nella Valle degli Spiriti di Orgrimmar, cerca tracce arcane primordiali in tutta Kalimdor. Ora ha rivolto la sua attenzione a Xavian, un'antica città degli Elfi della Notte sotto le chiome degli alberi di Valtetra orientale. Gli studiosi affermano che la città custodisse grandi conoscenze magiche prima del Grangorgo. Credono che le sue acque conservino ancora un potere arcano che i maghi moderni sperano di comprendere."},{t="Le rovine di Xavian",b="Xavian giace in rovina, invasa da satiri feroci e corrotti che difendono il loro territorio dagli estranei. Per raggiungere l'acqua, oltrepassi Satirnaar e attraversi pericolosi corsi d'acqua, evitando le bestie in agguato e le sentinelle demoniache. A Deino serve un campione dalla pozza alla base della cascata più alta della città."}},faq={{q="Chi è Deino?",a="Deino è un'istruttrice dei maghi e studiosa troll nella Valle degli Spiriti di Orgrimmar. Insegna ai maghi dell'Orda e studia le reliquie dell'antica magia di Kalimdor.",al={"chi assegna waters of xavian","deino orgrimmar"}},{q="Dove si trova Xavian?",a="Xavian è una città in rovina nel nord-est di Valtetra, a nord dell'Avamposto di Troncorotto e a nord-ovest di Satirnaar.",al={"posizione di xavian","dove si trova xavian","trovare xavian"}},{q="Perché Deino vuole quest'acqua?",a="Deino vuole studiare il potere arcano che ancora permea l'acqua. Gli studiosi affermano che Xavian custodisse grandi conoscenze magiche, e a Deino serve un campione fresco dalla sorgente della cascata per esaminarne le proprietà.",al={"perché prendere l'acqua di xavian","scopo dell'acqua di xavian"}},{q="Quali pericoli sorvegliano le rovine di Xavian?",a="I satiri infestano Xavian. Questi esseri demoniaci e corrotti disprezzano chi si avventura nelle loro terre e difendono il proprio territorio dagli intrusi.",al={"nemici a xavian","chi controlla xavian"}},{q="Dove viene raccolto esattamente il campione d'acqua?",a="Raccogli il campione dalla pozza alla base della cascata più alta di Xavian e lo versi nella Fiasca di Deino.",al={"posizione della cascata","dove riempire la fiasca","cascata di xavian"}},{q="Cosa succede dopo aver riportato il campione a Deino?",a="Dopo che hai riportato il campione, Deino ti manda a studiare le driadi a Valtetra.",al={"seguito di waters of xavian","missione successiva a waters of xavian"}}},fx={["6a4223ea"]={q="A cosa serve il Campione d'Acqua di Xavian?",a="L'antica città di Xavian è leggendaria tra gli studiosi per le conoscenze dimenticate che custodisce, e si dice che le sue acque possiedano grandi poteri magici. Deino vuole un campione incontaminato, raccolto direttamente ai piedi della cascata più alta della città, per studiarne le proprietà arcane latenti una volta tornata a Orgrimmar.",al={"a cosa serve l'acqua di xavian","perché raccogliere l'acqua di xavian","uso del campione d'acqua di xavian"}}},fp="16,174,18.362.0,19.301.0,13.145.0,24.105.0,31.190.0,39.119.0,44.109.0,52.78.1"}
P.entries["quest:1945"] = {n="Laughing Sisters",s="A Valtetra, i capelli delle driadi sono ricercati per una veste potenziata. A Crocevia, l'esperto sarto troll Kil'hala ha bisogno delle ciocche incantate per tessere una veste da mago, mentre i maghi dell'Orda incalzano i difensori nativi della foresta.",h="A Valtetra, i capelli delle driadi sono ricercati per una veste potenziata.",kw={"valtetra","crocevia","deino","driade","capelli","kil'hala","laughing sisters","rifugio di legnovivo","veste da stregone"},ang={["class:Mage"]="Come mago, scopri come gli spiriti sacri dei boschi di Valtetra vengono depredati per l'artigianato arcano, in un rito di passaggio.",["faction:Horde"]="Come membro dell'Orda, colpisci le driadi di Valtetra e inasprisci il conflitto con i guardiani della foresta sacra alleati degli Elfi della Notte.",["profession:Tailoring"]="Come sarto, scopri la rara arte di tessere fibre magiche viventi in armature di stoffa attraverso la tecnica di alto livello praticata da Kil'hala a Crocevia."},sec={{t="Tessere l'Arcano",b="Dopo che hai ottenuto l'acqua da Xavian, Deino a Orgrimmar invia i maghi emergenti a confezionare le proprie vesti incantate. Questi indumenti arcani richiedono materiali intrisi di magia pura. Le ciocche delle driadi racchiudono l'antica vitalità della foresta, fornendo ai maghi ciò che serve per tessere vesti elaborate che proteggono e rafforzano un incantatore."},{t="In agguato al Rifugio di Legnovivo",b="Nei pressi del Rifugio di Legnovivo a Valtetra, i maghi cercano le Laughing Sisters. Queste agili driadi sono alleate degli Elfi della Notte e difendono ferocemente i loro boschetti da taglialegna ed estranei. Non cederanno volontariamente i loro capelli agli incantatori dell'Orda. Così le ciocche vengono prese con la forza sotto gli alberi antichi."},{t="La prerogativa del tessitore",b="Le ciocche viaggiano verso sud oltre il confine, fino al polveroso insediamento di Crocevia nelle Savane. Lì, il sarto troll Kil'hala le riceve senza rimorsi. Kil'hala riconosce la perdita subita dalle creature silvane con un tocco d'ironia, poi mette a frutto i capelli incantati. Il potere dell'Orda esige risolutezza."}},faq={{q="Chi assegna la missione di cacciare le Laughing Sisters?",a="Deino, un mago troll presso Darkbriar Lodge a Orgrimmar, invia i maghi a raccogliere il necessario per le vesti della loro classe.",al={"chi assegna la missione laughing sisters","chi dà la missione laughing sisters","missione deino"}},{q="Cosa sono le Laughing Sisters?",a="Le Laughing Sisters sono driadi, figlie del semidio Cenarius. Con la parte superiore del corpo di un'Elfa della Notte e quella inferiore simile a un cerbiatto, proteggono le foreste e le radure sacre di Valtetra.",al={"cos'è una laughing sister","driade laughing sister","le laughing sisters sono driadi"}},{q="Dove si possono trovare le Laughing Sisters?",a="Vagano per la foresta vicino al Rifugio di Legnovivo e alla radura di Laughing Sister, nella zona centrale di Valtetra, non lontano dalla strada commerciale.",al={"posizione laughing sisters","dove si trovano le laughing sisters","dove trovare le laughing sisters"}},{q="Perché Kil'hala ha bisogno dei capelli delle driadi?",a="I capelli delle driadi sono naturalmente incantati e costituiscono un filato adatto a Kil'hala per tessere vesti specializzate che risuonano di magia e si prestano alle arti arcane.",al={"perché i capelli di driade","perché i capelli delle laughing sisters","a cosa servono i capelli"}},{q="Dove consegno i capelli una volta raccolti?",a="Porta i capelli a Kil'hala, un sarto a Crocevia nelle Savane.",al={"dove si trova kilhala","consegna missione laughing sisters","crocevia sarto stregone"}},{q="Cosa succede dopo che Kil'hala prende i capelli?",a="Kil'hala lavora brevemente i capelli, poi offre Nether-lace Garment per completare la veste.",al={"prossima missione dopo laughing sisters","dopo laughing sisters","nether-lace garment missione successiva"}}},fx={["6db1d5c5"]={q="Perché Deino ti manda a cacciare le Laughing Sisters?",a="Deino ricompensa il tuo continuo servizio ai maghi dell'Orda organizzando la confezione di vesti speciali. Invece di regalartеле, ti chiede di procurarti da solo i reagenti magici esotici e ti manda nel cuore di Valtetra a strappare i capelli delle driadi ai difensori della foresta.",al={"perché deino vuole i capelli delle laughing sisters","motivo di deino per le laughing sisters","perché raccogliere i capelli delle laughing sisters"}}},fp="16,223,18.311.0,18.298.0,24.301.0,51.117.0,30.188.0,40.127.0,34.161.0,49.69.0,43.89.0"}
P.entries["quest:1946"] = {n="Nether-lace Garment",s="A Crocevia, Kil'hala intesse capelli di driade in stoffa incantata per gli incantatori. Questo indumento completa il suo lavoro specializzato nelle Savane.",h="A Crocevia, Kil'hala intesse capelli di driade in stoffa incantata per gli incantatori.",kw={"valtetra","savane","crocevia","deino","kil'hala","laughing sisters","mago","nether-lace"},ang={["class:Mage"]="Come mago, ricevi un indumento forgiato dalle prove affrontate nelle terre selvagge di Valtetra e dall'abilità artigiana di Kil'hala sotto la guida di Deino.",["faction:Horde"]="Come membro dell'Orda, contribuisci a equipaggiare i suoi incantatori con materiali provenienti dai boschi sacri di Kalimdor. Questo lavoro fa parte del conflitto in corso tra l'Orda e i difensori dei boschi di Valtetra.",["profession:Tailoring"]="Come sarto, puoi vedere come i capelli di driade diventano una stoffa dotata di protezione magica innata."},sec={{t="Intrecciare il Nether-lace",b="A Crocevia, nelle Savane, Kil'hala tesse il nether-lace con le ciocche delle Laughing Sisters. Le driadi vivono a Valtetra, dove vengono raccolti i capelli per il suo lavoro. Intesse l'incanto silvestre racchiuso in quelle ciocche rare e risonanti in una stoffa comoda e resistente."},{t="Favori per Orgrimmar",b="Kil'hala cerca nel suo mestiere qualcosa di più della buona fattura. Spera di conquistare il favore di Deino, una rispettata maga troll della Valle degli Spiriti a Orgrimmar. Creando abiti eccezionali per aspiranti praticanti, spera di ottenere e conservare la benevolenza di Deino."}},faq={{q="Cos'è il nether-lace?",a="Il nether-lace è un tessuto incantato che Kil'hala tesse con le chiome delle Laughing Sisters. La stoffa è resistente e racchiude il loro incanto silvestre.",al={"stoffa nether lace","cos'è il nether-lace garment"}},{q="Chi crea il Nether-lace Garment?",a="Kil'hala realizza l'indumento alla sua postazione a Crocevia, nelle Savane, una volta ottenuti i capelli di driade necessari da Valtetra.",al={"chi crea il nether lace","kil hala nether lace"}},{q="Perché Kil'hala menziona Deino?",a="Deino è una rispettata maga troll che vive nella Valle degli Spiriti a Orgrimmar. Kil'hala spera di conservarne il favore e crede che la tua soddisfazione per il suo lavoro di sartoria lo metterà in buona luce.",al={"chi è deino","perché menzionare deino"}},{q="Da dove provengono i materiali per l'indumento?",a="Il materiale principale dell'indumento sono i capelli raccolti dalle Laughing Sisters, driadi che si trovano nelle foreste di tutta Valtetra.",al={"materiali nether lace","stoffa di capelli di driade"}},{q="Per chi è fatto questo indumento?",a="L'indumento è destinato soprattutto agli incantatori, in particolare ai maghi apprendisti. Le sue vesti incanalano le energie arcane senza ostacolare i movimenti.",al={"chi usa il nether-lace garment","classe nether lace"}},{q="Dove si trova Kil'hala?",a="Kil'hala vive a Crocevia, l'insediamento centrale nel cuore delle Savane.",al={"posizione kil hala","dove si trova kil hala"}}},fp="19,144,23.287.0,20.243.0,20.151.0,35.126.0,32.185.0,50.112.0,29.132.0,26.85.0"}
P.entries["quest:1947"] = {n="Journey to the Marsh",s="La tua classe ti manda ad Acquemorte, dove le conoscenze di Tabetha possono aiutarti a ottenere la tua bacchetta.",h="La tua classe ti manda ad Acquemorte, dove le conoscenze di Tabetha possono aiutarti a ottenere la tua...",kw={"casa","acquemorte","viaggio nella palude","rovine dei mazzapietra","tabetha","theramore","bacchetta"},sec={{t="La casa di Tabetha",b="A ovest di Theramore e appena a nord delle Rovine dei Mazzapietra, Tabetha vive in una casetta. La tua classe ti chiede di parlare con l’eremita e apprendere dal suo vasto sapere."}},faq={{q="Chi è Tabetha?",a="Tabetha è un’eremita di Acquemorte, nota per le sue vaste conoscenze.",al={"tabetha","eremita della palude","chi è l’eremita"}},{q="Dov’è la casa di Tabetha?",a="La casetta di Tabetha si trova a ovest di Theramore e appena a nord delle Rovine dei Mazzapietra.",al={"posizione di tabetha","dov’è tabetha","capanna di tabetha"}},{q="Perché mi mandano da Tabetha?",a="Parlare con Tabetha dà inizio al tuo tentativo di ottenere la bacchetta della tua classe.",al={"perché tabetha","missione della bacchetta","ottenere la mia bacchetta"}}},fp="20,98,19.164.0,15.70.0,29.79.0,31.69.0"}
P.entries["quest:195"] = {n="Raptor Mastery",s="Nella Valle di Rovotorto, Hemet Nesingwary manda i cacciatori in cerca di prede più letali. Dopo la loro prima caccia ai raptor, chiede loro di rintracciare e uccidere dieci Raptor Coda di Frusta.",h="Nella Valle di Rovotorto, Hemet Nesingwary manda i cacciatori in cerca di prede più letali.",kw={"forte di grom'gol","hemet nesingwary","caccia","raptor coda di frusta","raptor mastery","valle di rovotorto"},ang={["class:Hunter"]="Come cacciatore, metti alla prova la tua disciplina contro i predatori più letali che si aggirano nella Valle di Rovotorto nelle prove di Hemet Nesingwary."},sec={{t="Una sfida più ardua",b="A nord del Forte di Grom'gol, Hemet Nesingwary manda i cacciatori nel fitto sottobosco della giungla. Dopo la loro prima caccia ai raptor, si aspetta che dimostrino concentrazione e abilità affrontando prede più letali. Dieci feroci Raptor Coda di Frusta devono essere rintracciati e uccisi."},{t="Trofei per il focolare",b="Hemet Nesingwary accoglie con calorosa approvazione i cacciatori di ritorno dalla giungla. Per l'esperto cacciatore, questi pericolosi predatori sono prede degne e trofei da esporre sopra il focolare. Prepara il cacciatore a sfide più impegnative."}},faq={{q="Chi offre questa sfida di caccia?",a="Hemet Nesingwary, il celebre cacciatore di grossa selvaggina, propone la sfida dall'accampamento della sua spedizione nella Valle di Rovotorto settentrionale.",al={"chi inizia raptor mastery 2","datore di missioni raptor mastery","dove ottenere raptor mastery"}},{q="Quale preda ti viene assegnata da cacciare?",a="Devi rintracciare e uccidere dieci Raptor Coda di Frusta nella giungla.",al={"quali raptor uccidere","quale missione dei raptor","bersaglio raptor coda di frusta"}},{q="Dove si trovano i Raptor Coda di Frusta?",a="I Raptor Coda di Frusta si aggirano nella vegetazione selvaggia della Valle di Rovotorto settentrionale, soprattutto a nord del Forte di Grom'gol.",al={"dove sono i raptor coda di frusta","posizione raptor coda di frusta","dove trovare i coda di frusta"}},{q="Dove si inserisce questa caccia nelle prove di Nesingwary?",a="Questa è la seconda prova della serie di cacce ai raptor di Nesingwary. Segue la caccia introduttiva Raptor Mastery e conduce a una terza parte della sfida.",al={"cosa precede questa caccia ai raptor","progressione raptor mastery","catena di missioni dei raptor"}}},fp="14,160,19.240.0,23.221.1,34.122.0,40.59.0,37.110.0,50.147.0"}
P.entries["quest:1950"] = {n="Get the Scoop",s="Vicino alla Pista dei Miraggi, Magus Tirth ha dimenticato le parole per aprire il suo forziere sigillato. Il suo apprendista, Johnson, è scomparso da qualche parte nei dintorni della pista, e a Tirth serve il grimorio al suo interno.",h="Vicino alla Pista dei Miraggi, Magus Tirth ha dimenticato le parole per aprire il suo forziere sigillato.",kw={"get the scoop","johnson","magus tirth","pista dei miraggi","distese salate","forziere","millepicchi","missione bacchetta"},ang={["class:Mage"]="Se sei un mago, avere a che fare con Tirth ti mostra i pericoli delle maledizioni di metamorfosi e la distrazione che può affliggere gli studiosi potenti."},sec={{t="Un Mago e la Sua Memoria",b="Magus Tirth vive sul letto di sale incrinato delle Distese Salate, a Millepicchi. È un incantatore eccentrico, le cui conoscenze arcane e i cui libri attirano maghi desiderosi di progredire. La pazienza aiuta quando si ha a che fare con lui. Tirth si affida a un assistente per i dettagli quotidiani, persino le parole d'ordine che proteggono le sue scorte arcane. Ora un libro di potere è chiuso a chiave, e le parole magiche gli sono completamente sfuggite di mente."},{t="Scherzo da Pollo",b="I goblin e gli gnomi che gestiscono la Pista dei Miraggi possono dirti cos'è successo a Johnson, l'apprendista di Magus Tirth. Tirth ha trasformato Johnson in un comune pollo, e ora l'apprendista vaga per le distese salate senza poter parlare. Quando ti avvicini, la foschia dell'incantesimo si dirada per un momento. Johnson riesce così a starnazzare la parola d'ordine dimenticata."}},faq={{q="Chi è Magus Tirth?",a="Magus Tirth è un mago umano schivo che vive vicino alla Pista dei Miraggi, nelle Distese Salate di Millepicchi. I maghi cercano le sue conoscenze arcane avanzate per affinare la propria arte.",al={"lore su tirth","chi è magus tirth","tirth distese salate"}},{q="Perché Tirth ha bisogno della password per il proprio forziere?",a="Tirth ha chiuso il suo forziere con una frase pronunciata ad alta voce e si è affidato al suo assistente per ricordare simili dettagli quotidiani. Quando il suo apprendista è scomparso, Tirth ha dimenticato le parole.",al={"perché tirth ha dimenticato","password forziere tirth"}},{q="Dov'è andato l'apprendista?",a="Johnson vaga vicino alla pista, a est dell'accampamento di Tirth. Trovarlo è più difficile perché Tirth lo ha trasformato in un pollo.",al={"trovare assistente tirth","dov'è l'apprendista johnson","posizione johnson"}},{q="Perché l'apprendista è stato trasformato in un pollo?",a="Tirth ha maledetto Johnson, poi ha dimenticato di averlo fatto. Quando ha saputo cos'era successo al suo assistente, ha vagamente supposto che Johnson se lo fosse meritato, essendo un allievo ingrato.",al={"perché johnson è un pollo","tirth polimorfia apprendista"}},{q="Cosa c'è dentro il forziere di Tirth?",a="Il forziere di Tirth contiene un libro di rituali, istruzioni essenziali per il perfezionamento di un mago e strumenti magici.",al={"contenuto forziere tirth","che libro c'è nel forziere"}},{q="Chi può intraprendere questa missione?",a="Solo i maghi in cerca di insegnamenti specialistici e materiali per creare una potente bacchetta possono affrontare questa prova.",al={"i non maghi possono fare get the scoop","questa missione è solo per maghi"}}},fx={["25c94f6f"]={q="Perché Magus Tirth manda te invece di cercare personalmente l'apprendista?",a="Magus Tirth non ha intenzione di perlustrare le Distese Salate mentre sei tu a supplicarlo per ottenere le sue conoscenze. Sei venuto a cercare il suo raro tomo magico e, poiché non ricorda l'incantesimo verbale per aprire il suo forziere sigillato magicamente senza il suo assistente scomparso, ti chiede di aiutarlo in cambio del suo aiuto.",al={"perché mandare me","perché tirth non cerca johnson","perché devo trovare l'apprendista"}}},fp="13,192,22.417.0,9.319.1,19.165.0,48.164.0,28.119.1,45.169.1,33.123.0,28.105.0"}
P.entries["quest:1959"] = {n="Report to Anastasia",s="In Kalimdor e nei Regni Orientali, i maghi dell'Orda vengono convocati a Sepulcra. Anastasia Cuorfosco ha percepito un disturbo magico sconosciuto e ha bisogno di incantatori capaci che indaghino.",h="In Kalimdor e nei Regni Orientali, i maghi dell'Orda vengono convocati a Sepulcra.",kw={"anastasia cuorfosco","cain cantafuoco","investigate the alchemist shop","mago","magic quarter","report to anastasia","thurston xane","un'thuwa","sepulcra","uthel'nay"},ang={["class:Mage"]="Come mago dell'Orda, lasci il tuo avamposto regionale per raggiungere Sepulcra. Sotto le rovine di Lordaeron ti attendono misteri arcani più profondi e pericoli.",["faction:Horde"]="La convocazione riunisce i Reietti e gli altri maghi dell'Orda per proteggere i loro interessi comuni.",["race:Undead"]="In quanto Reietto, vieni convocato al Magic Quarter di Sepulcra per contribuire a proteggere il tuo giovane regno dalle minacce arcane che si celano entro le sue mura."},sec={{t="Una chiamata all'Arcano",b="I maghi dell'Orda di Kalimdor e dei Regni Orientali ricevono tutti la stessa convocazione. Raggiunge chi studia sulle alture di Picco del Tuono, nel caldo polveroso di Durotar e tra le rovine di Lordaeron. I maghi di Sepulcra hanno percepito un disturbo inspiegabile nel loro territorio. Hanno bisogno di aiuto per capirne il significato."},{t="La maga di Sepulcra",b="Anastasia Cuorfosco supervisiona le questioni arcane nel Magic Quarter di Sepulcra. I maghi della zona hanno rilevato energie insolite in città, ma nessuno sa se la magia sia innocua o ostile. Anastasia ha bisogno di un mago capace che indaghi senza dare nell'occhio. L'indagine comincia all'Apothecarium."}},faq={{q="Chi è Anastasia Cuorfosco?",a="Anastasia Cuorfosco è una maga Reietta e mentore dell'arcano nel Magic Quarter di Sepulcra. Guida chi muove i primi passi nella magia e sorveglia le anomalie arcane nella capitale dei Reietti.",al={"lore di anastasia cuorfosco","chi è anastasia","cuorfosco sepulcra"}},{q="Dove si trova Anastasia Cuorfosco?",a="Anastasia Cuorfosco si trova nel Magic Quarter, nell'ala settentrionale di Sepulcra. È una delle istruttrici di magia e delle ricercatrici arcane della città.",al={"dove si trova anastasia","posizione di cuorfosco","mappa di anastasia a sepulcra"}},{q="Perché convocano a Sepulcra maghi di Picco del Tuono o delle Savane?",a="I maghi di Sepulcra hanno rilevato un disturbo insolito e gli interessi dell'Orda a Lordaeron potrebbero essere a rischio. I mentori di Kalimdor vi mandano gli allievi più promettenti perché aiutino e facciano esperienza con fenomeni magici complessi.",al={"perché andare a sepulcra","perché presentarsi ad anastasia","missione del mago di picco del tuono"}},{q="Che tipo di disturbo sta indagando Anastasia?",a="I maghi hanno rilevato fluttuazioni magiche inspiegabili a Sepulcra. Anastasia Cuorfosco non sa se l'energia sia ostile, accidentale o innocua, quindi avvia un'indagine prudente.",al={"che disturbo","disturbo magico a sepulcra","cosa succede a sepulcra"}},{q="Chi assegna questa missione?",a="Gli istruttori dei maghi dell'Orda possono mandarti da Anastasia quando avrai abbastanza esperienza. Tra loro ci sono Uthel'nay a Orgrimmar, Thurston Xane a Picco del Tuono, Cain Cantafuoco a Brill e Un'Thuwa al Villaggio di Sen'jin.",al={"chi inizia report to anastasia","chi assegna la missione report to anastasia"}},{q="Cosa succede dopo essersi presentati ad Anastasia?",a="Dopo che avrai parlato con Anastasia e ricevuto le sue istruzioni, ti manderà a indagare sul disturbo nell'Apothecarium della città. Cominci con Investigate the Alchemist Shop.",al={"missione successiva a report to anastasia","seguito di report to anastasia"}}},fx={["22ef3f4a"]={q="Perché gli istruttori dei maghi ti mandano da Anastasia Cuorfosco invece di occuparsene loro?",a="I tuoi istruttori devono addestrare i maghi alle prime armi e mantenere la supervisione mistica sugli insediamenti di Kalimdor. Quando è giunta notizia che i maghi Reietti avevano bisogno di aiuto per indagare su un'anomalia arcana nella Città Sotterranea, gli istruttori hanno cercato apprendisti capaci e promettenti, pronti a svolgere incarichi sul campo senza abbandonare i loro posti d'insegnamento.",al={"perché mi mandano da anastasia","perché gli istruttori non possono andare alla città sotterranea","perché devo riferire ad anastasia"}}},fp="19,196,20.293.0,25.285.0,26.179.0,36.146.0,80.216.0,52.196.0,21.204.0,42.176.0"}
P.entries["quest:196"] = {n="Raptor Mastery",s="Nella Valle di Rovotorto, Hemet Nesingwary ti manda a caccia dei Predatori della Giungla. Dieci raptor guardinghi ti separano dalla sua caccia più prestigiosa.",h="Nella Valle di Rovotorto, Hemet Nesingwary ti manda a caccia dei Predatori della Giungla.",kw={"cacciatore di grosse prede","arena dei gurubashi","hemet nesingwary","predatori della giungla","raptor mastery","valle di rovotorto"},ang={["class:Hunter"]="Da cacciatore, rintracciare i guardinghi Predatori della Giungla mette alla prova la tua abilità con le prede e la tua mira nelle terre selvagge, sotto lo sguardo di Hemet Nesingwary."},sec={{t="Una preda scaltra",b="Hemet Nesingwary ti manda a caccia dei Predatori della Giungla, prede più impegnative dei raptor che hai cacciato in precedenza. Sono guardinghi e difficili da rintracciare o uccidere. Trovane e abbattili dieci nella giungla, poi torna all'accampamento. Hemet ti darà un indizio sulla sua caccia più prestigiosa fino a quel momento."}},faq={{q="Chi offre questa caccia?",a="Hemet Nesingwary, il cacciatore di grossa selvaggina, propone questa caccia dal suo accampamento nella parte settentrionale della Valle di Rovotorto.",al={"datore di missione","chi inizia raptor mastery 3","caccia di hemet nesingwary"}},{q="Quale bestia ti viene chiesto di rintracciare?",a="Ti viene chiesto di rintracciare e uccidere dieci Predatori della Giungla, una specie di raptor guardinga e sfuggente.",al={"quale raptor","raptor bersaglio","quali raptor uccidere"}},{q="Dove si trovano i Predatori della Giungla?",a="I Predatori della Giungla si aggirano per la Valle di Rovotorto, soprattutto a nord e a ovest dell'Arena dei Gurubashi.",al={"posizione predatore della giungla","dove vagano i predatori della giungla","trovare predatori della giungla"}},{q="Cosa precede questa sfida?",a="Questa caccia segue la seconda fase delle prove di Raptor Mastery, mentre Hemet Nesingwary passa in rassegna le specie di raptor locali.",al={"missione prerequisito","precedente raptor mastery","quale missione viene prima"}}},fp="14,128,14.247.0,21.101.0,39.87.0,32.90.0,33.127.0"}
P.entries["quest:1960"] = {n="Investigate the Alchemist Shop",s="Nel negozio di Algernon, creature invisibili si aggirano tra gli alambicchi. Anastasia Cuorfosco invia maghi dell'Orda a rivelarle e contenerle prima che facciano danni.",h="Nel negozio di Algernon, creature invisibili si aggirano tra gli alambicchi.",kw={"algernon","anastasia cuorfosco","apothecarium","canto della manifestazione","forziere di contenimento","magic quarter","progenie della frattura","sepulcra"},ang={["class:Mage"]="Nei panni di un mago, metti alla prova il tuo controllo delle forze arcane con canti di manifestazione e contenitori di contenimento, senza affidarti soltanto alla forza distruttiva.",["race:Undead"]="Nei panni di un Reietto, vedi gli studiosi arcani di Sepulcra proteggere la città dalle infiltrazioni magiche, accanto agli speziali dediti all'alchimia e alla peste."},sec={{t="Un disturbo nell'Apothecarium",b="Anastasia Cuorfosco invia iniziati arcani a indagare su un'anomalia nell'Apothecarium. Creature magiche invisibili si aggirano nel negozio di alchimia di Algernon, tra calderoni e reagenti. L'istruttrice dei maghi di Sepulcra sospetta una breccia nel flusso della magia. Le creature devono essere contenute prima che causino gravi danni."},{t="Manifestazione e contenimento",b="Anastasia dà ai suoi studenti un Canto della Manifestazione per rivelare le creature invisibili e robusti forzieri di contenimento per imprigionarle. I normali metodi di tracciamento non possono trovare esseri composti interamente di pura forza arcana. Una volta visibili, le progenie della frattura devono essere indebolite e sigillate nei forzieri, prima che possano destabilizzarsi o ferire gli alchimisti al lavoro."},{t="Incidente o assalto arcano?",b="Anastasia vuole scoprire da dove provengono le creature. Una frattura spontanea nel flusso della magia è preoccupante, ma una breccia intenzionale potrebbe indicare un attacco magico coordinato contro la capitale dei Reietti. Gli studiosi di Sepulcra esamineranno le creature catturate e determineranno se l'Apothecarium ha subito un incidente o è minacciato da un nemico mirato."}},faq={{q="Chi assegna questa missione e dove posso trovarli?",a="Anastasia Cuorfosco, l'istruttrice dei maghi, offre questa missione nel Magic Quarter di Sepulcra.",al={"datore di missione","dove iniziare","posizione di anastasia"}},{q="Dov'è localizzato il disturbo?",a="L'anomalia si trova nel negozio di alchimia di Algernon, nel quartiere Apothecarium di Sepulcra.",al={"dove andare","posizione negozio di alchimia","dov'è algernon"}},{q="Cosa sono le creature che vagano nel negozio?",a="Le creature sono progenie della frattura, esseri invisibili composti di energia magica concentrata, apparsi attraverso un'anomalia nel flusso locale della magia.",al={"cosa sono i mostri","creature invisibili","progenie della frattura"}},{q="Come si catturano le creature?",a="Reciti il Canto della Manifestazione nel negozio per rivelare le progenie della frattura, le indebolisci con gli incantesimi e poi le intrappoli in un forziere di contenimento.",al={"come catturarle","usare il forziere","come completare"}},{q="Perché Anastasia vuole che queste creature vengano catturate vive?",a="Anastasia e gli studiosi di Sepulcra hanno bisogno di esemplari vivi per scoprire se la lacerazione nella magia è stata causata da una frattura naturale o da un attacco intenzionale alla città da parte di una forza magica esterna.",al={"perché catturarle","scopo dei forzieri di contenimento","perché studiarle"}},{q="Altre classi oltre ai maghi possono svolgere questa missione?",a="Solo i maghi dell'Orda possono partecipare; fa parte del loro addestramento iniziale.",al={"solo maghi","chi può prendere la missione"}}},fx={["20993eae"]={q="A cosa serve il Canto della Manifestazione?",a="Il Canto della Manifestazione è un incantesimo scritto su una pergamena, fornita da Anastasia Cuorfosco per rivelare ciò che è invisibile. Le entità che infestano il negozio di Algernon sono pura energia magica e invisibili a occhio nudo. Leggendo il canto all'interno del negozio, squarci il loro velo di occultamento e le costringi a manifestarsi fisicamente, così puoi combatterle e sottometterle.",al={"scopo del canto della manifestazione","perché usare il canto della manifestazione","cosa fa il canto"}},["355e23e2"]={q="A cosa serve il Forziere di Casse di Contenimento?",a="Il Forziere di Casse di Contenimento contiene recipienti protetti da speciali incantesimi, creati per vincolare le entità magiche grezze. Poiché le creature generate dalla fenditura nell'Apothecarium non possono essere trasportate a mano, devi usare queste casse arcane una volta che i nemici sono indeboliti in combattimento, intrappolandoli al sicuro all'interno perché possano essere trasportati senza dissolversi.",al={"forziere di casse di contenimento","cosa sono le casse di contenimento","scopo delle casse di contenimento"}},["01d568c5"]={q="A cosa serve il Forziere di Contenimento Pieno?",a="Ogni Forziere di Contenimento Pieno custodisce una creatura vivente generata dalla fenditura del negozio di Algernon. Anastasia Cuorfosco vuole che tu le riporti intatte tutte e tre, affinché i più grandi studiosi arcani della Città Sotterranea possano esaminarle e capire se la loro improvvisa manifestazione sia stata causata da uno strappo accidentale nel tessuto della magia o da un attacco deliberato.",al={"uso del forziere di contenimento pieno","perché riportare i forzieri pieni","scopo del forziere di contenimento pieno"}}},fp="30,153,33.330.0,29.345.0,27.342.1,46.83.0,33.88.0,42.144.0,33.149.0,55.184.0,43.69.0"}
P.entries["quest:1961"] = {n="Gathering Materials",s="A Sepulcra, Gathering Materials manda i nuovi maghi dell'Orda nella Selva Pinargento a cercare gemme di mana di Dalaran. Serve anche del lino per confezionare le loro prime vere vesti da mago.",h="A Sepulcra, Gathering Materials manda i nuovi maghi dell'Orda nella Selva Pinargento a cercare gemme di mana...",kw={"mulino d'ambra","anastasia cuorfosco","gemma di mana di dalaran","gathering materials","josef gregorian","stoffa di lino","magic quarter","spellfire robes","sepulcra"},ang={["class:Mage"]="Come mago dell'Orda, raggiungi una tappa importante quando abbandoni i semplici abiti da apprendista per indossare vesti sartoriali intessute di potere arcano sottratto.",["profession:Tailoring"]="Come sarto, leghi un semplice tessuto di lino a potenti gemme di mana per creare abiti incantati resistenti.",["race:Undead"]="Da non morto, conosci la spietata visione dei Reietti. Le filosofie arcane condivise con gli stregoni di Dalaran non portano clemenza quando quei maghi si dimostrano troppo deboli per mantenere il controllo sulla Selva Pinargento."},sec={{t="Un rito di rango arcano",b="Gli iniziati di Sepulcra raccolgono una pezza di semplice lino e potenti gemme di mana di Dalaran per le loro prime vere vesti. Queste vesti segnano il loro rango e il loro valore personale. Anastasia Cuorfosco manda i novizi a raccogliere le materie prime per un tessuto incantato."},{t="Pragmatismo dei Reietti",b="Le gemme di mana non si possono comprare né evocare. I maghi di Dalaran sono stanziati in tutta la Selva Pinargento, soprattutto vicino a Mulino d'Ambra, e le gemme vanno sottratte a loro. Anastasia Cuorfosco dice che le filosofie arcane di Dalaran rispecchiano quelle dei Reietti. Eppure, a Sepulcra non c'è posto per i sentimentalismi. Per i Reietti, i maghi troppo deboli per difendere le proprie reliquie perdono i loro tesori e la vita."},{t="Il sarto del Magic Quarter",b="Josef Gregorian è un sarto nel Magic Quarter di Sepulcra, dove vengono portati il tessuto e le gemme raccolti. Gli manca il talento magico per giudicare la qualità pura delle pietre incantate di Dalaran. Ma possiede la rara abilità artigianale di intrecciarne il potere grezzo nelle vesti."}},faq={{q="Qual è lo scopo di Gathering Materials?",a="Il rito segna il passaggio di un mago dell'Orda alle sue prime vesti incantate formali. Il lino e le gemme di mana vengono consegnati a Josef Gregorian, un sarto che li usa per confezionarle.",al={"perché fare gathering materials","scopo missione gathering materials","missione veste da mago sepulcra"}},{q="Perché Anastasia Cuorfosco ti manda a caccia di maghi di Dalaran?",a="I maghi di Dalaran stanziati in tutta la Selva Pinargento portano gemme di mana raffinate, capaci di incanalare potenti correnti magiche. Anastasia Cuorfosco riconosce le loro filosofie arcane condivise, ma crede che chi è troppo debole per difendersi consegni la propria vita e le proprie risorse ai Reietti.",al={"perché uccidere maghi dalaran","lore gemme di mana dalaran","perché maghi selva pinargento"}},{q="Dove si trovano i maghi di Dalaran?",a="I maghi di Dalaran sono stanziati in tutta la Selva Pinargento, soprattutto vicino a Mulino d'Ambra e nei dintorni dei terreni a sud-est di Mausolea.",al={"dove trovare gemme di mana dalaran","posizione maghi selva pinargento","maghi mulino d'ambra"}},{q="Chi è Josef Gregorian?",a="Josef Gregorian è un sarto non morto nel Magic Quarter di Sepulcra. Non è un incantatore arcano, ma è specializzato nel cucire abiti incantati come le Spellfire Robes.",al={"josef gregorian sepulcra","chi è il sarto nel magic quarter","gregorian sarto"}},{q="Quali vesti vengono create con questi materiali?",a="Josef Gregorian usa il lino e le gemme di mana di Dalaran per cucire le Spellfire Robes. Questo indumento segna il passaggio di un apprendista a mago affermato.",al={"quale veste si ottiene","ricompensa spellfire robes","veste ricompensa gathering materials"}},{q="Perché Anastasia trova l'uccisione dei maghi di Dalaran in qualche modo spiacevole?",a="Anastasia Cuorfosco trova sgradevole l'uccisione, perché i maghi di Dalaran condividono molte credenze e filosofie arcane con i maghi Reietti. Eppure la sopravvivenza e la necessità prevalgono sui sentimenti.",al={"sentimenti di cuorfosco per dalaran","maghi reietti contro dalaran","lore anastasia cuorfosco"}}},fx={e61c0dee={q="A cosa serve la stoffa di lino?",a="La stoffa di lino costituisce la base materiale delle tue Spellfire Robes. Josef Gregorian, il sarto del Magic Quarter della Città Sotterranea, tesse il tessuto per ricavarne abiti pregiati, poi intreccia fili di reagenti magici per conferirgli potere.",al={"uso della stoffa di lino","perché la stoffa di lino","a cosa serve il lino"}},["8f9ef647"]={q="A cosa serve la Gemma di Mana di Dalaran?",a="Le gemme di mana di Dalaran racchiudono energia arcana grezza incanalata dai maghi del Kirin Tor. Josef Gregorian le cuce direttamente nelle tue vesti per infondere nel tessuto il potere magico necessario a forgiare veri indumenti di Spellfire.",al={"uso della gemma di mana di dalaran","a cosa servono le gemme di mana di dalaran","a cosa servono le gemme di mana"}},["608132d5"]={q="Chi sono i maghi di Dalaran nella Selva Pinargento?",a="Sono stregoni umani fedeli a Dalaran, stanziati nei pressi del Mulino d'Ambra, nella Selva Pinargento orientale. Sebbene la loro disciplina arcana rispecchi quella dei maghi dei Reietti, la loro presenza minaccia direttamente il dominio di Undercity sulla regione, rendendoli bersagli ideali per gli apprendisti ambiziosi.",al={"maghi di dalaran nella selva pinargento","chi sono i maghi di dalaran","umani di dalaran nella selva pinargento"}},["1cfe23fe"]={q="Perché Anastasia Hartwell manda un apprendista invece di occuparsene personalmente?",a="Guadagnarsi le prime vesti da mago è un rito di passaggio. Anastasia Hartwell si aspetta che dimostri il tuo valore e il tuo rango arcano sottraendo reagenti agli incantatori rivali con la forza della volontà e del potere personale.",al={"perché devo raccogliere i materiali","perché mandare un apprendista","perché anastasia non recupera le gemme"}}},fp="19,166,25.248.0,26.389.0,31.272.0,43.168.0,57.270.0,38.132.0,23.168.0,44.147.0,67.184.0"}
P.entries["quest:1962"] = {n="Spellfire Robes",s="A Sepulcra, le Spellfire Robes segnano il passaggio di un giovane mago dell'Orda verso la maestria. Josef Gregorian le completa dopo che l'apprendista gli porta componenti rari da ogni angolo del regno.",h="A Sepulcra, le Spellfire Robes segnano il passaggio di un giovane mago dell'Orda verso la maestria.",kw={"vesti arcane","gathering materials","josef gregorian","missione mago","magic quarter","spellfire robes","sepulcra"},ang={["class:Mage"]="Come mago dell'Orda, ricevi queste vesti come primo rito di passaggio. Il tessuto su misura resiste al fuoco instabile e alle energie arcane.",["profession:Tailoring"]="Come sarto, puoi vedere come reagenti esotici rendano il tessuto comune resistente alle potenti correnti magiche.",["race:Undead"]="Come incantatore Reietto a Sepulcra, porti avanti la disciplina arcana in stile Dalaran. La tua arte unisce antiche tradizioni magiche alla tua nuova esistenza tra le rovine di Lordaeron."},sec={{t="Vesti da Mago",b="A Lordaeron, per incanalare e proteggere la tua magia sempre più potente serve più di un tessuto comune. Josef Gregorian è un sarto nel Magic Quarter di Sepulcra. Crea abiti magici con materiali speciali raccolti da promettenti incantatori dell'Orda. Le ultime cuciture segnano il passaggio oltre gli incantesimi di base, verso la magia arcana e quella del fuoco."},{t="Potere Intessuto",b="Josef Gregorian ha bisogno di componenti alchemici e arcani per creare vesti che concentrino una magia potente. Raccogli i rifornimenti affrontando prove pericolose e li porti nel suo santuario a Sepulcra. Lì, Gregorian li intreccia. Le vesti segnano la tua crescente fama e ti proteggono mentre aspiri a diventare un mago."}},faq={{q="Qual è lo scopo della missione delle Spellfire Robes?",a="Queste vesti completano un primo rito di passaggio per i maghi dell'Orda. Dopo aver raccolto i componenti per la sartoria, ricevi vesti incantate su misura da Josef Gregorian.",al={"scopo spellfire robes","cosa fanno le spellfire robes","perché fare questa missione"}},{q="Chi è Josef Gregorian?",a="Josef Gregorian è un sarto Reietto nel Magic Quarter di Sepulcra. Confeziona i primi veri abiti di classe per i maghi appena iniziati che Anastasia Cuorfosco gli affida.",al={"chi è josef","chi crea la veste","josef gregorian sepulcra"}},{q="Dove si svolge questa missione?",a="Incontri Josef Gregorian nella sua sartoria nel Magic Quarter di Sepulcra.",al={"posizione spellfire robes","dove consegnare le spellfire robes"}},{q="Perché non devi allontanarti per compiere un altro compito per questa missione?",a="Hai raccolto i materiali nell'incarico precedente, Gathering Materials. Consegna i reagenti a Josef: lui intreccerà l'indumento e ti darà le vesti finite.",al={"perché è istantaneo","come completare le spellfire robes","completamento automatico veste"}},{q="Classi diverse dai Maghi possono ottenere queste vesti?",a="No. Solo i maghi alleati dell'Orda possono ricevere queste vesti incantate.",al={"è solo per maghi","può ottenerla uno stregone","chi può fare le spellfire robes"}},{q="Quali materiali sono stati richiesti per realizzare queste vesti?",a="Per le vesti servono rifornimenti rari raccolti in precedenza, tra cui stoffa di lino e gemme di mana di Dalaran sottratte ai maghi del Kirin Tor nella Selva Pinargento.",al={"cosa serve per la veste","ingredienti veste","consegna gathering materials"}}},fx={c778cc7d={q="Perché Josef Gregorian confeziona per te le Spellfire Robes?",a="Josef Gregorian fa da mentore ai maghi Reietti e dell'Orda in ascesa nel Magic Quarter. Intrecciando i reagenti raccolti in vesti incantate adatte, si assicura che tu sia equipaggiato a dovere per incanalare e sopportare le forze arcane richieste dalla tua arte, che continua a evolversi.",al={"perché josef confeziona le vesti","motivo di josef gregorian","perché josef ti aiuta"}}},fp="15,180,17.341.0,11.308.0,49.164.0,23.172.0,33.77.0,62.164.0,48.71.0,49.146.0"}
P.entries["quest:1963"] = {n="The Shattered Hand",s="A Orgrimmar, Therzok mette alla prova i furfanti che vogliono entrare nella segreta The Shattered Hand. La prova li manda sulle tracce di Tazan, un contrabbandiere troll, e della sua borsa chiusa a chiave.",h="A Orgrimmar, Therzok mette alla prova i furfanti che vogliono entrare nella segreta The Shattered Hand.",kw={"spelonca delle ombre","orgrimmar","porto paranco","furfante","valigetta","shattered hand","tazan","therzok"},ang={["class:Rogue"]="Da furfante dell'Orda, entri in The Shattered Hand attraverso un rito che premia l'efficienza spietata, gli assassinii e l'utilità più del combattimento aperto.",["faction:Horde"]="Come membro dell'Orda, vedi The Shattered Hand mettere silenziosamente in discussione la visione prudente di Thrall per la giovane Orda."},sec={{t="Ombre nella Faglia Infida",b="The Shattered Hand opera dalla Spelonca delle Ombre, sotto Orgrimmar. Questo ordine di assassini e ladri segue le antiche tradizioni orchesche. Il Capoguerra Thrall governa la giovane Orda con onore, diplomazia e prudenza. Ma i capi di The Shattered Hand credono che la moderazione indebolisca il loro popolo, e cercano di ripristinare la supremazia marziale con la violenza clandestina. Usano pugnali e veleno quando una carica sul campo di battaglia potrebbe fallire."},{t="Il destino di un contrabbandiere",b="Therzok mette alla prova i furfanti mandandoli sulle tracce di Tazan, un troll che opera vicino a Porto Paranco, nelle Savane. Tazan commercia con i pirati costieri e trasporta informazioni che la gilda vuole ottenere. Recuperare la sua borsa chiusa a chiave dimostra che un furfante sa seguire una preda oltre le mura della città. Per aprirla serve un'altra abilità."}},faq={{q="Cos'è Shattered Hand a Orgrimmar?",a="The Shattered Hand è una gilda segreta dell'Orda composta da furfanti, esploratori e assassini, con sede nella Spelonca delle Ombre di Orgrimmar. Un tempo era un antico clan orchesco noto per le brutali automutilazioni; ora raccoglie informazioni e compie omicidi. I suoi membri preferiscono il pragmatismo spietato alla cauta diplomazia di Thrall.",al={"chi sono i shattered hand","furfanti shattered hand","scopo shattered hand"}},{q="Chi è Therzok?",a="Therzok è un agente di The Shattered Hand nella Spelonca delle Ombre. Mette alla prova gli aspiranti furfanti per verificare che abbiano l'astuzia e la letalità richieste dalla gilda, e mette apertamente in dubbio la moderazione di Thrall.",al={"ruolo therzok","chi assegna la missione","therzok orgrimmar"}},{q="Perché Therzok vuole Tazan morto?",a="Tazan è un contrabbandiere troll che commercia con i pirati dei Mari del Sud vicino a Porto Paranco. Trasporta informazioni in una borsa che The Shattered Hand vuole usare per le proprie operazioni clandestine.",al={"perché uccidere tazan","storia di tazan","cosa ha fatto tazan"}},{q="Dove si trova Tazan?",a="Tazan opera nelle Savane, vicino alla costa e ai pirati a sud di Porto Paranco.",al={"posizione tazan","dove si trova tazan","trovare tazan"}},{q="Cosa succede dopo aver recuperato la Valigetta di Tazan?",a="Quando Therzok riceve la borsa, la trova chiusa a chiave. È soddisfatto della morte di Tazan, ma ha ancora bisogno delle informazioni al suo interno, quindi aprirla diventa un'altra prova dell'abilità del furfante nello scassinare serrature.",al={"prossima missione","valigetta chiusa","cosa fare con la valigetta"}},{q="Thrall conosce i metodi di The Shattered Hand?",a="The Shattered Hand serve nominalmente l'Orda, ma i suoi membri agiscono nell'ombra e disprezzano la cauta leadership di Thrall. Costruiscono in segreto reti di informatori e cercano di eliminare le minacce prima che la diplomazia del Capoguerra possa ritardare l'azione.",al={"thrall e the shattered hand","il capoguerra approva","thrall e furfanti"}}},fx={["6c6760e5"]={q="Cosa contiene la borsa di Tazan?",a="Therzok cerca la borsa perché contiene informazioni preziose. Tazan tratta direttamente con i Bucanieri dei Mari del Sud che operano nei pressi di Porto Paranco, e la corrispondenza o i documenti che porta con sé potrebbero dare alla Shattered Hand una posizione di vantaggio sui movimenti dei pirati lungo la costa. Purtroppo, il sacchetto è chiuso a chiave e non serve a nulla finché non trovi il modo di forzarlo.",al={"borsa di tazan","cosa contiene la borsa di tazan","a cosa serve la borsa di tazan"}},fc6df596={q="Chi è Tazan?",a="Tazan è un troll rinnegato che conduce affari illeciti con i pirati stanziati a sud di Porto Paranco. Operando nelle Distese oltre la portata delle leggi di Orgrimmar, traffica in segreti e contrabbando, attirando l'attenzione della Shattered Hand. I suoi rapporti con i fuorilegge lo rendono un bersaglio ideale da eliminare.",al={"chi è tazan","bersaglio tazan","perché uccidere tazan"}},beb36990={q="Perché Therzok manda te invece di occuparsi personalmente di Tazan?",a="La Shattered Hand opera nella più assoluta segretezza dalle profondità della Faglia Infida, nascondendo i propri metodi spietati allo sguardo vigile del Capoguerra Thrall. Therzok non può mandare guardie ufficiali dell'Orda né esporre gli agenti più esperti della gilda a banali missioni sul campo. Usa invece il contratto come prova d'iniziazione, per verificare se possiedi l'astuzia letale necessaria a servire la loro confraternita clandestina.",al={"perché mandare me","perché therzok ti vuole","perché therzok non uccide tazan personalmente"}}},fp="18,160,20.413.0,17.294.1,40.297.0,15.174.0,33.163.0,23.83.0,46.188.1,52.240.0"}
P.entries["quest:197"] = {n="La maestria nella caccia al raptor",s="Nella Valle di Rovotorto, Hemet Nesingwary ti manda a caccia del raptor che è sfuggito persino a lui. Dopo le prove contro bestie minori, dovrai rintracciare Tethis e riportare un suo artiglio a Hemet.",h="Nella Valle di Rovotorto, Hemet Nesingwary ti manda a caccia del raptor che è sfuggito persino a lui.",kw={"ajeck rouack","arena dei gurubashi","hemet nesingwary","raptor mastery","valle di rovotorto","artiglio di tethis","tethis"},sec={{t="L'astuto predatore della Valle",b="Hemet Nesingwary ti parla di Tethis, un raptor feroce che è sfuggito a ogni cacciatore, persino al capo della spedizione. Ajeck Rouack ha dato il nome alla bestia. Tra i raptor di Rovotorto, Tethis è la sfida più ardua per un cacciatore."},{t="Recuperare l'artiglio",b="Tethis si aggira a nord dell'Arena dei Gurubashi. Porta a Hemet un artiglio del raptor abbattuto e ti riconoscerà come maestro cacciatore di raptor. Nessun altro cacciatore di grande selvaggina ha compiuto quest'impresa."}},faq={{q="Chi ti manda a cacciare Tethis?",a="Hemet Nesingwary ti manda a caccia di Tethis dall'accampamento della sua spedizione, nel nord della Valle di Rovotorto, dopo che avrai dimostrato la tua abilità nel seguire le tracce dei normali raptor della giungla.",al={"chi fornisce raptor mastery","datore missione raptor mastery","chi vuole morto tethis"}},{q="Dove si può trovare Tethis?",a="Tethis si aggira nella giungla attorno all'Arena dei Gurubashi, soprattutto tra i cespugli a nord del colosseo.",al={"posizione tethis","dove si trova tethis","dove trovare tethis"}},{q="Quale prova richiede Hemet dell'uccisione?",a="Hemet esige l'artiglio di Tethis come prova che hai abbattuto il raptor.",al={"cosa devo portare a hemet","prova di tethis","oggetto consegna raptor mastery"}},{q="Chi ha dato originariamente il nome Tethis al rapace?",a="Ajeck Rouack, uno dei cacciatori dell'accampamento della Spedizione di Nesingwary, ha dato al raptor il nome Tethis.",al={"chi ha dato il nome a tethis","origine del nome tethis"}}},fp="14,192,29.229.0,18.187.0,29.173.0,26.100.0,42.77.0,39.98.0"}
P.entries["quest:1978"] = {n="The Deathstalkers",s="A Sepulcra, i Deathstalkers accolgono un nuovo agente nei loro ranghi. Porti il Libro Mastro di Andron a Varimathras come prova del lavoro segreto della Lega dei Tagliagole.",h="A Sepulcra, i Deathstalkers accolgono un nuovo agente nei loro ranghi.",kw={"alterac","libro mastro di andron","the deathstalkers","sala della dama oscura","mennet carkad","lega dei tagliagole","sepulcra","varimathras"},ang={["class:Rogue"]="In quanto ladro, entri nella schiera specializzata dei Reietti come agente dei servizi segreti, non come semplice borseggiatore.",["faction:Horde"]="Come membro dell'Orda, contribuisci a proteggere i territori settentrionali dal sabotaggio sorvegliando ciò che resta degli umani di Alterac.",["race:Undead"]="In quanto Reietto, giuri di proteggere la fragile sovranità di Lordaeron dai sopravvissuti umani e dai traditori nascosti."},sec={{t="Iniziazione nelle Ombre",b="Mennet Carkad ti accoglie nei Deathstalkers dopo che hai scoperto i documenti di Andron Gant. L'ordine serve Lady Sylvanas in tutta Lordaeron come suoi occhi, orecchie e pugnali. I suoi agenti ricorrono a informazioni, efficienza spietata e furtività per eliminare le minacce prima che si manifestino. Il riconoscimento dell'ordine segna il tuo primo passo al servizio dei Reietti."},{t="I legami con la Lega dei Tagliagole",b="Il Libro Mastro di Andron rivela legami segreti tra gli agenti locali e la Lega dei Tagliagole. Un tempo aristocrazia nobile di Alterac, dopo la caduta del regno nella Seconda Guerra la Lega si è data al banditismo e alla sovversione. Carkad accoglie la notizia con sorpresa e disprezzo. Nella lotta per riconquistare il potere, i lord decaduti di Alterac sono scesi a meschini complotti."},{t="Udienza con il Signore del Terrore",b="Consegni il delicato libro mastro a Varimathras nel Quartiere Reale di Sepulcra. Il comandante nathrezim supervisiona l'intelligence tattica dei Reietti al servizio di Sylvanas Ventolesto. Soddisfatto dell'iniziativa dei Deathstalkers, Varimathras apprezza le tue capacità e afferma che la sua divisione di intelligence può servirsi di qualcuno capace di ottenere risultati."}},faq={{q="Chi sono i The Deathstalkers?",a="I Deathstalkers sono l'ordine di spie, esploratori e assassini dei Reietti, con sede nel Rogues' Quarter di Sepulcra. I loro agenti operano in tutta Lordaeron per neutralizzare rivali politici, infiltrarsi nelle fazioni ostili e proteggere il regno dei Reietti dalle minacce esterne e dalla sovversione interna.",al={"chi sono i the deathstalkers","lore dei the deathstalkers","assassini reietti"}},{q="Perché è coinvolta la Lega dei Tagliagole?",a="Il Libro Mastro di Andron rivela legami segreti con la Lega dei Tagliagole, l'aristocrazia spodestata di Alterac, ormai dedita al banditismo organizzato. I Reietti sorvegliano ciò che resta di Alterac nei loro territori, dove gli agenti della Lega cercano occasioni per riconquistare le terre perdute e depredare le risorse nel nord di Lordaeron.",al={"perché la lega dei tagliagole","collegamento con alterac","libro mastro della lega dei tagliagole"}},{q="Perché fare rapporto direttamente a Varimathras?",a="Varimathras consiglia la regina Sylvanas sulle tattiche e supervisiona la sicurezza e l'intelligence di Sepulcra. Le scoperte sui complotti stranieri, compreso il lavoro segreto della Lega dei Tagliagole, vengono sottoposte al suo esame per decidere misure militari e diplomatiche più ampie.",al={"perché varimathras","chi è varimathras","ruolo del signore del terrore"}},{q="Chi era Mennet Carkad?",a="Mennet Carkad è un responsabile anziano e un contatto dei Deathstalkers a Sepulcra. Supervisiona gli agenti sul campo, valuta le reclute e vaglia le informazioni prima di trasmettere le scoperte più importanti ai superiori.",al={"ruolo di mennet carkad","carkad datore di missione"}},{q="Dove si svolge questa udienza?",a="L'incontro si svolge nella Sala della Signora Oscura, nel Quartiere Reale di Sepulcra. Varimathras è accanto alla regina Sylvanas Ventolesto, nel cuore del centro del potere dei Reietti.",al={"dov'è varimathras","posizione della sala della dama oscura"}},{q="Cosa succede dopo essersi uniti ai The Deathstalkers?",a="Dopo aver stabilito le tue credenziali e dimostrato la tua affidabilità a Mennet Carkad e Varimathras, i Reietti ti riconoscono come agente sul campo fidato. Le future missioni di ricognizione ed eliminazione potrebbero portarti nelle terre contese di Lordaeron.",al={"continuazione della linea di missioni dei the deathstalkers","cosa succede dopo"}}},fx={["123798f3"]={q="Perché Mennet Carkad vuole che il Libro Mastro di Andron venga consegnato a Varimathras?",a="Il libro mastro rivela che il Syndicate, composto dai nobili decaduti di Alterac, sta cospirando contro i Reietti. Smascherare il loro tradimento è una vittoria d'intelligence fondamentale per i Deathstalkers, e Mennet sa che una notizia così urgente sulla sicurezza di Lordaeron deve giungere direttamente nelle mani di Lord Varimathras, che supervisiona le operazioni dell'ordine.",al={"perché consegnare il libro mastro","motivo di mennet carkad","perché riferire a varimathras del syndicate"}},b0e675df={q="Perché Mennet manda te invece di riferire personalmente a Varimathras?",a="Sei stato tu a rintracciare i cospiratori e a recuperare sul campo il Libro Mastro di Andron. Mennet ritiene giusto che sia tu stesso a presentare le informazioni, così potrai ricevere il merito davanti a Lord Varimathras e sancire il tuo ingresso ufficiale nei ranghi dei Deathstalkers.",al={"perché io nei deathstalkers","perché mennet mi manda","perché consegnare personalmente il libro mastro"}}},fp="17,155,26.343.0,24.340.1,27.317.0,27.280.0,30.283.0,35.236.0,22.208.0,36.180.0,45.249.0"}
P.entries["quest:198"] = {n="Supplies to Private Thorsen",s="Krazek cerca a Baia del Bottino un corriere che porti provviste a nord, al Soldato Thorsen. Gli attacchi dei troll hanno interrotto le spedizioni regolari all'accampamento del Tenente Doren, vicino al confine settentrionale.",h="Krazek cerca a Baia del Bottino un corriere che porti provviste a nord, al Soldato Thorsen.",kw={"baia del bottino","boscovespro","provviste goblin","krazek","kurzen","tenente doren","soldato thorsen","valle di rovotorto"},ang={["faction:Alliance"]="Come soldato dell'Alleanza, sorvegli l'ingresso settentrionale da Boscovespro alla Valle di Rovotorto insieme agli uomini del Tenente Doren. Fate affidamento sulle provviste dei goblin per mantenere la posizione."},sec={{t="Una rotta interrotta",b="Gli uomini del Tenente Doren sorvegliano il confine tra la Valle di Rovotorto e Boscovespro. Krazek organizza spedizioni regolari per loro, ma i troll locali continuano ad attaccare. Le consegne abituali sono diventate pericolose, così il mercante goblin ti assume per portare un pacco a nord lungo la strada nella giungla. Il Soldato Thorsen può riceverlo all'accampamento a nord-ovest della strada o lungo il suo percorso di pattuglia verso sud."},{t="Il vero contenuto della spedizione",b="La spedizione del Soldato Thorsen contiene mine antiuomo, anche se nell'elenco sono indicate come varie provviste goblin. Dice che gli esplosivi aiuteranno a difendere la postazione dal Colonnello Kurzen e dai suoi uomini."}},faq={{q="Chi sta inviando queste provviste?",a="Krazek, un mercante goblin che commercia a Baia del Bottino, organizza e fornisce le provviste.",al={"chi consegna le provviste a thorsen","consegna di krazek","chi inizia supplies to private thorsen"}},{q="Perché le provviste sono in ritardo?",a="Gli attacchi dei troll locali nella Valle di Rovotorto hanno interrotto le consegne regolari, lasciando gli uomini del Tenente Doren in attesa delle merci previste.",al={"perché in ritardo","attacchi dei troll alle consegne","perché non è stata consegnata"}},{q="Dove si può trovare il Soldato Thorsen?",a="Puoi trovare il Soldato Thorsen all'accampamento del Tenente Doren, a nord-ovest della strada principale, vicino all'ingresso nella Valle di Rovotorto da Boscovespro. Pattuglia anche il sentiero appena a sud dell'accampamento.",al={"dove si trova thorsen","posizione di thorsen","trovare il soldato thorsen"}},{q="Cosa succede se le provviste vanno perse?",a="Krazek avverte che chiunque non consegni la spedizione sarà ritenuto finanziariamente responsabile e dovrà risarcirlo.",al={"cosa succede se perdo le provviste","risarcimento a krazek","fallire con krazek"}}},fp="27,181,17.387.0,28.190.1,30.90.0,35.142.0,35.182.0,38.120.0"}
P.entries["quest:199"] = {n="A Dark Threat Looms",s="Alla Diga di Pietrasalda, un sabotaggio minaccia la barriera che trattiene le acque del Loch Modan. Trovi un barile vicino alla riva e porti la sua Polvere dall'Odore Strano al Capo Ingegnere Hinderweir VII.",h="Alla Diga di Pietrasalda, un sabotaggio minaccia la barriera che trattiene le acque del Loch Modan.",kw={"a dark threat looms","hinderweir","loch modan","sabotaggio","diga di pietrasalda","polvere dall'odore strano","barile sospetto"},ang={["profession:Engineering"]="Da ingegnere, riconosci il pericolo delle polveri volatili collocate deliberatamente nei punti di tensione di una grande diga.",["race:Dwarf"]="Da nano, conosci la Diga di Pietrasalda come una delle più grandi opere architettoniche dei nani di Forgiardente. Qualsiasi minaccia contro di essa mette a rischio la sicurezza e l'orgoglio di Khaz Modan.",["race:Gnome"]="Da gnomo, apprezzi la precisione delle opere civili naniche. Per questo la natura chimica di questo rozzo sabotaggio è particolarmente preoccupante."},sec={{t="Una scoperta sospetta",b="Voci di sabotaggio sono giunte alla riva intorno alla Diga di Pietrasalda. Vicino al bordo dell'acqua, c'è un barile dove non dovrebbe esserci. Al suo interno si trova una polvere insolita e pungente, ben lontana dalle forniture di manutenzione della diga."},{t="Allarme alla diga",b="Il Capo Ingegnere Hinderweir VII si allarma quando gli porti un campione. La sua reazione conferma i peggiori timori di Loch Modan: una forza esterna trama contro la diga. Ora l'indagine è urgente, per la difesa della regione."}},faq={{q="Cos'è la Polvere dall'Odore Strano?",a="La Polvere dall'Odore Strano nel barile è un esplosivo o un agente alchemico collocato vicino alla base della Diga di Pietrasalda. È la prova che un nemico trama per distruggere o danneggiare la barriera.",al={"strana polvere","cosa c'è nel barile","polvere del barile sospetto"}},{q="Chi è il Capo Ingegnere Hinderweir VII?",a="Il Capo Ingegnere Hinderweir VII è il maestro ingegnere dei nani responsabile della manutenzione, dell'integrità e della sicurezza della Diga di Pietrasalda a Loch Modan.",al={"chi è hinderweir","capo ingegnere hinderweir","ingegnere della diga"}},{q="Dove si trova il barile sospetto?",a="Il barile sospetto è nascosto lungo la riva, vicino alle fondamenta della Diga di Pietrasalda, nel nord di Loch Modan.",al={"posizione del barile","dov'è il barile","barile a loch modan"}},{q="Perché la Diga di Pietrasalda è presa di mira?",a="La Diga di Pietrasalda trattiene l'immenso bacino di Loch Modan. Se cede, un'inondazione catastrofica travolgerebbe le Paludi Grigie sottostanti, paralizzando le rotte commerciali dell'Alleanza e devastando gli insediamenti nanici in tutto Khaz Modan.",al={"perché distruggere la diga","sabotaggio della diga","minaccia a loch modan"}},{q="Chi ha lasciato qui il barile sospetto?",a="Gli agenti che mirano a destabilizzare le terre dei nani hanno collocato il barile. Il Capo Ingegnere Hinderweir ha avviato un'indagine più ampia per scoprire chi c'è dietro al complotto.",al={"chi ha piazzato il barile","sabotatori","chi ha messo la polvere"}},{q="Cosa devo fare dopo aver raccolto la polvere?",a="Porta il campione al Capo Ingegnere Hinderweir VII in cima alla Diga di Pietrasalda, perché possa esaminarlo e preparare una risposta.",al={"cosa fare ora","consegna la polvere","a chi rivolgersi"}}},fp="19,205,22.211.0,16.224.1,36.192.0,37.149.0,37.114.0,43.219.0,36.151.0,45.119.0"}
P.entries["quest:1998"] = {n="Fenwick Thatros",s="A Sepulcra, Mennet Carkad manda i ladri promettenti a uccidere Fenwick Thatros per ordine di Lord Varimathras. Si sospetta che Thatros stia radunando non morti indipendenti lungo le coste della Selva Pinargento. La sua morte dimostra il valore di un agente ai The Deathstalkers e gli fa guadagnare accesso a un addestramento commerciale avanzato.",h="A Sepulcra, Mennet Carkad manda i ladri promettenti a uccidere Fenwick Thatros per ordine di Lord Varimathras.",kw={"the deathstalkers","fenwick thatros","lago lordamere","mennet carkad","rogues' quarter","selva pinargento","sepulcra","varimathras"},ang={["class:Rogue"]="Da ladro, dimostri furtività e letalità portando a termine questo incarico. Poi i The Deathstalkers potrebbero affidarti strumenti più avanzati del loro mestiere.",["race:Undead"]="Da Reietto, sai che le fazioni di non morti rivali non possono rivendicare la sovranità così vicino alla Città Capitale. La testa di Fenwick Thatros è una necessità politica."},sec={{t="Un ordine dal Signore del Terrore",b="Nel Rogues' Quarter di Sepulcra, Mennet Carkad gestisce i contratti dei Deathstalker e addestra i ladri. I The Deathstalkers sono il ramo di intelligence segreto dei Reietti. Lord Varimathras ha indicato Fenwick Thatros come bersaglio prioritario, un incarico troppo grave per le reclute alle prime armi. Thatros ha stabilito una testa di ponte tra i non morti rinnegati della Selva Pinargento. Se lasciati indisturbati, i loro capi indipendenti potrebbero minacciare il controllo dei Reietti sugli antichi possedimenti di Lordaeron."},{t="Il molo decrepito sul Lordamere",b="Gli esploratori dei Deathstalker hanno individuato Fenwick Thatros vicino a un molo decrepito sul Lago Lordamere, nella Selva Pinargento. Per raggiungerlo, devi attraversare terre selvagge infestate da bestie feroci, gnoll Pellemarcia e resti del Flagello. Varimathras pretende una prova dell'uccisione: la Testa Mozzata di Thatros. Riportala e potresti guadagnarti l'accesso a operazioni clandestine più delicate."}},faq={{q="Chi è Fenwick Thatros?",a="Fenwick Thatros guida dei non morti vicino al Lago Lordamere, nella Selva Pinargento. Comanda gruppi di non morti non affiliati a Sepulcra o ostili a essa, a differenza dei Reietti al servizio di Lady Sylvanas. Lord Varimathras lo ha condannato a morte.",al={"lore di fenwick","chi è thatros","background di fenwick thatros"}},{q="Perché Varimathras vuole Fenwick Thatros morto?",a="Varimathras vuole morto Fenwick Thatros perché potrebbe radunare i non morti dispersi nella Selva Pinargento contro i Reietti. I capi rivali che minacciano il controllo di Sylvanas sulla regione devono essere eliminati per proteggere i confini di Sepulcra.",al={"varimathras thatros","perché uccidere fenwick"}},{q="Chi sono i The Deathstalkers?",a="I The Deathstalkers sono l'agenzia dei Reietti incaricata di spionaggio, assassinio e ricognizione. Con sede nel Rogues' Quarter di Sepulcra, operano in tutta Lordaeron per eliminare le minacce interne, spiare le fazioni rivali e assicurare il territorio alla Dama Oscura.",al={"lore dei the deathstalkers","cosa sono i the deathstalkers","fazione ladri non morti"}},{q="Dove si trova Fenwick Thatros?",a="I rapporti dei Deathstalker indicano Fenwick Thatros vicino a un molo in rovina sulla riva del Lago Lordamere, nella parte nordorientale della Selva Pinargento.",al={"dov'è fenwick","posizione molo di fenwick","thatros lago lordamere"}},{q="Cosa si ottiene completando questa missione con i The Deathstalkers?",a="Uccidere Fenwick Thatros dimostra la tua abilità e lealtà a Mennet Carkad e ai The Deathstalkers. Dopo aver dimostrato di meritare fiducia, Carkad ti offre un addestramento specializzato nelle arti dell'ombra.",al={"lore ricompensa fenwick","cosa succede dopo fenwick"}},{q="Chi è Mennet Carkad?",a="Mennet Carkad addestra i ladri e gestisce gli affari dei Deathstalker nel Rogues' Quarter di Sepulcra. Supervisiona gli agenti sul campo e assegna incarichi legati alla sicurezza del regno dei Reietti.",al={"mennet carkad","chi assegna la missione di fenwick"}}},fx={eac48585={q="Perché Mennet Carkad vuole la Testa di Fenwick?",a="Fenwick Thatros rappresenta una minaccia organizzata che si annida proprio ai confini della Selva Pinargento. Mennet Carkad pretende la sua testa mozzata come prova inconfutabile che il comandante non morto rinnegato è stato eliminato. Nelle operazioni clandestine dei Deathstalkers e di Lord Varimathras, la parola di un assassino non basta mai senza un trofeo concreto che confermi l'uccisione.",al={"a cosa serve la testa di fenwick","perché prendere la testa di fenwick","scopo della testa di fenwick"}},bc8ca6fa={q="Perché Mennet Carkad ha scelto te per questa missione?",a="Mennet Carkad fa da coordinatore e istruttore ai Deathstalkers nel Rogues' Quarter. Quando Lord Varimathras ordina un assassinio mirato, le normali guardie cittadine non sono adatte alla ricognizione furtiva all'aperto. Mennet sceglie proprio te perché hai dimostrato talento nelle arti dell'ombra e usa questo incarico cruciale per valutare se sei pronto a un addestramento avanzato tra gli agenti d'élite dei Reietti.",al={"perché mandare me","perché mennet sceglie me","perché non mandare le guardie dei deathstalkers"}}},fp="15,300,28.448.0,30.338.0,23.232.0,47.226.0,26.253.0,33.122.0,62.190.0,21.177.0"}
P.entries["quest:1999"] = {n="Tools of the Trade",s="A Sepulcra, i furfanti dell'Orda ricevono l'incarico di rubare un rapporto da Mulino d'Ambra. Lord Varimathras ordina loro di procurarsi attrezzi da scasso e scoprire le condizioni di Dalaran tramite le informazioni del Kirin Tor.",h="A Sepulcra, i furfanti dell'Orda ricevono l'incarico di rubare un rapporto da Mulino d'Ambra.",kw={"mulino d'ambra","dalaran","deathstalkers","estelle gendry","kirin tor","scassinare","mennet carkad","rogues' quarter","sepulcra","varimathras"},ang={["class:Rogue"]="Come furfante dell'Orda, dimostri il tuo valore con gli attrezzi da scasso regolamentari, la furtività e la destrezza, anziché con la forza bruta.",["faction:Horde"]="Come membro dell'Orda, contribuisci ad assicurare informazioni umane nella Selva Pinargento e a rafforzare la presa dell'Orda nel nord del Lordaeron contro i resti dell'Alleanza.",["race:Undead"]="Da non morto, aiuti i Reietti a superare in astuzia i maghi del Kirin Tor che cercano di riconquistare il Lordaeron."},sec={{t="Occhi su Mulino d'Ambra",b="L'interrogatorio di un prigioniero conduce i Deathstalkers a informazioni nascoste a Mulino d'Ambra. La Selva Pinargento resta un fronte precario e i maghi umani proteggono ferocemente le comunicazioni del villaggio. Lord Varimathras ordina a Mennet Carkad, un gestore dei Deathstalkers, di guidare gli agenti promettenti oltre le sentinelle del Kirin Tor e recuperare il Rapporto sulla Situazione di Dalaran."},{t="L'Arte della Breccia",b="Infiltrazione e scasso mettono alla prova abilità che vanno oltre l'assassinio. Prima di entrare nel territorio del Kirin Tor, gli agenti raccolgono attrezzi da scasso specializzati da Estelle Gendry. Aprire la cassa protetta a Mulino d'Ambra dimostra che un agente sa andare oltre la brutalità di strada e servire i Reietti come risorsa di spionaggio."}},faq={{q="Chi ordina questa missione?",a="Mennet Carkad, un furfante dei Deathstalkers nel Rogues' Quarter di Sepulcra, assegna l'incarico. Lord Varimathras dà l'ordine e supervisiona la raccolta di informazioni dei Reietti.",al={"chi assegna tools of the trade","chi assegna la missione","missione di mennet carkad"}},{q="Cos'è il Rapporto sulla Situazione di Dalaran?",a="Il Rapporto sulla Situazione di Dalaran è un dispaccio sigillato del Kirin Tor sulle condizioni di Dalaran. Gli interrogatori dei Deathstalkers ne hanno appreso la posizione da un prigioniero, rivelando quanto siano vulnerabili le informazioni vitali sui vicini meridionali dei Reietti.",al={"cosa sono i documenti","documenti del kirin tor","rapporto sulla situazione"}},{q="Dove viene conservato il rapporto?",a="Il rapporto si trova in una cassa chiusa all'avamposto del Kirin Tor di Mulino d'Ambra, nella Selva Pinargento meridionale.",al={"dove trovo i documenti","posizione della cassa di mulino d'ambra","dove si trova il rapporto sulla situazione"}},{q="Chi fornisce gli strumenti per scassinare?",a="Estelle Gendry, una venditrice di equipaggiamento nel Rogues' Quarter di Sepulcra, fornisce gli attrezzi da scasso necessari per aprire la cassa chiusa.",al={"dove ottengo gli strumenti","ruolo di estelle gendry","strumenti da scasso"}},{q="Perché Dalaran è importante per i Reietti in questo momento?",a="I maghi sopravvissuti di Dalaran stanno ricostruendo la città dall'altra parte del Lago Lordamere rispetto alla Selva Pinargento. I Reietti sorvegliano il Kirin Tor per proteggere i loro possedimenti nel Lordaeron.",al={"perché interessarsi a dalaran","reietti contro dalaran","minaccia del kirin tor"}},{q="Quale prerequisito deve essere completato prima di intraprendere questa missione?",a="Gli agenti devono prima completare il contratto di assassinio Fenwick Thatros, dando la caccia a un bersaglio nella Selva Pinargento prima che Mennet Carkad affidi loro un delicato incarico d'infiltrazione.",al={"prerequisiti","quale missione viene prima","missione di fenwick thatros"}}},fx={["77cf7ea8"]={q="Perché Mennet Carkad vuole che questa missione venga portata a termine?",a="Lord Varimathras ha incaricato i Deathstalkers di recuperare il rapporto dopo averne scoperto l'ubicazione interrogando un prigioniero. In qualità di agente del Rogues' Quarter, Mennet Carkad esegue gli ordini del signore del terrore e, al contempo, mette alla prova le tue abilità ancora acerbe di infiltrazione e spionaggio.",al={"perché mennet carkad lo vuole","motivo di mennet carkad","perché recuperare il rapporto sulla situazione di dalaran"}},["9b719de0"]={q="Contro chi vieni mandato al Mulino d'Ambra?",a="Il tuo bersaglio è il Kirin Tor stanziato al Mulino d'Ambra, nella Selva Pinargento. Questi maghi umani mantengono un'enclave vicino alla città di Dalaran in ricostruzione e proteggono dai Reietti informazioni riservate sulle attuali condizioni della città in rovina.",al={"chi ha il rapporto","bersaglio di tools of the trade","chi devi prendere di mira"}},["6507a470"]={q="Perché Mennet Carkad ha bisogno di te per questa missione?",a="La missione è un rito di passaggio. Dopo aver dimostrato una competenza di base eliminando Fenwick Thatros, Mennet ti ha scelto per dimostrare che sai affrontare le operazioni più delicate dei Deathstalkers, facendo affidamento su furtività, scassinamento e infiltrazione anziché sulla forza bruta.",al={"perché mandare me","perché mennet carkad ha bisogno di me","perché i deathstalkers non possono recuperare il rapporto"}}},fp="18,191,17.363.0,21.305.0,24.170.0,34.238.0,25.104.0,35.129.0,51.176.0,63.178.0"}
P.entries["quest:2"] = {n="L'Artiglio di Grinfiafina",s="A Valtetra, gli attacchi di Tagliartiglio mettono a rischio le linee di rifornimento dell'Orda. Porta il suo artiglio a Senani Cuore Tonante all'Avamposto di Troncorotto, come prova che il predatore è stato abbattuto.",h="A Valtetra, gli attacchi di Tagliartiglio mettono a rischio le linee di rifornimento dell'Orda.",kw={"valtetra","caccia di valtetra","ippogrifo","peoni","senani cuore tonante","tagliartiglio","avamposto di troncorotto","cantaguerra"},ang={["class:Hunter"]="Da cacciatore, metti alla prova le tue abilità di tracciamento e di tiro contro Tagliartiglio, un temuto predatore volante sotto la fitta volta arborea di Valtetra.",["faction:Horde"]="In quanto membro dell'Orda, contribuisci a proteggere i sentieri usati dalle operazioni di raccolta del legname dei Cantaguerra. Proteggi i peoni in viaggio tra gli avamposti avanzati e l'Avamposto di Troncorotto.",["race:Orc"]="In quanto orco, allevi la dura fatica del clan Cantaguerra nel raccogliere legna eliminando una minaccia aerea dalla foresta.",["race:Tauren"]="In quanto tauren, segui la caccia di Senani Cuore Tonante e metti alla prova le tue capacità contro le belve più feroci della natura, come vuole la tradizione tauren."},sec={{t="Flagello dei sentieri della foresta",b="Tagliartiglio dà la caccia lungo i sentieri per l'Avamposto di Troncorotto, mentre l'Orda cerca risorse a Valtetra. Questo ippogrifo aggressivo assale peoni e corrieri in viaggio tra gli accampamenti avanzati di taglialegna e l'avamposto. I suoi attacchi intralciano il lavoro dell'Orda nella regione. Anche le sentinelle elfi della notte e la fauna pericolosa minacciano i nuovi arrivati."},{t="Prova della caccia",b="Senani Cuore Tonante, una cacciatrice tauren, guida i cacciatori dell'Orda contro i predatori più letali di Valtetra. L'artiglio di Tagliartiglio dimostra che l'ippogrifo è stato abbattuto. Porta il trofeo all'Avamposto di Troncorotto. I difensori dell'avamposto onorano la caccia e i lavoratori spaventati possono attraversare i boschi con meno timore."}},faq={{q="Chi è Tagliartiglio?",a="Tagliartiglio è un ippogrifo feroce e predatore che caccia a Valtetra. Tende imboscate ai viaggiatori che attraversano la foresta.",al={"chi è tagliartiglio","mob tagliartiglio","che tipo di bestia è tagliartiglio"}},{q="Perché Senani Cuore Tonante vuole l'artiglio?",a="Senani Cuore Tonante vuole l'artiglio come prova che Tagliartiglio è stato ucciso. Il predatore minaccia i lavoratori dell'Orda e le rotte di rifornimento.",al={"perché consegnare l'artiglio","trofeo di senani cuore tonante","scopo dell'artiglio di tagliartiglio"}},{q="Dove devo consegnare Artiglio di Tagliartiglio?",a="Porta l'artiglio a Senani Cuore Tonante all'Avamposto di Troncorotto, nella parte orientale di Valtetra.",al={"dove consegnare","chi prende l'artiglio","posizione consegna artiglio"}},{q="In che modo uccidere Tagliartiglio aiuta l'Orda?",a="Tagliartiglio attacca i peoni in viaggio tra le segherie remote e l'Avamposto di Troncorotto. Ucciderlo rende più sicuro il trasporto di rifornimenti, legname e messaggeri.",al={"perché uccidere tagliartiglio lore","interesse dell'orda per tagliartiglio"}},{q="Questa missione fa parte di una serie più ampia?",a="Sì. Fa parte di The Ashenvale Hunt, la serie di cacce alle belve di Senani Cuore Tonante. La serie termina con The Hunt Completed.",al={"serie di missioni caccia di valtetra","serie di missioni tagliartiglio"}},{q="Chi è Senani Cuore Tonante?",a="Senani Cuore Tonante è una cacciatrice tauren all'Avamposto di Troncorotto. Sorveglia l'equilibrio della foresta e mette alla prova i cacciatori dell'Orda contro le creature più pericolose di Valtetra.",al={"lore senani","chi è senani"}}},fp="17,164,30.325.0,17.293.0,19.118.0,43.127.0,37.80.0,43.153.0,37.124.0,27.165.0"}
P.entries["quest:20"] = {n="Blackrock Menace",s="Gli orchi di Roccianera premono da nord e da sud-est nelle Montagne Crestarossa, e Borgolago è sotto assedio. Il Maresciallo Marris ti chiede di decimarne le schiere e riportargli le loro asce logore dalla battaglia.",h="Gli orchi di Roccianera premono da nord e da sud-est nelle Montagne Crestarossa, e Borgolago è sotto assedio.",kw={"asce","roccianera","steppe ardenti","borgolago","marris","orchi","crestarossa","guardamasso","tharil'zun"},ang={["class:Warrior"]="Da guerriero, affrontare i veterani predoni di Roccianera scudo contro scudo mette alla prova la tua disciplina marziale e la tua forza in prima linea.",["faction:Alliance"]="Per l'Alleanza, difendere Borgolago aiuta a mantenere il confine meridionale di Roccavento contro avversari del vecchio mondo.",["race:Human"]="Da umano, affrontare il clan di Roccianera nelle Montagne Crestarossa suscita un dolore amaro. Distrussero il Regno originale di Roccavento durante la Prima Guerra."},sec={{t="Una città sotto assedio",b="Borgolago è minacciata da più fronti, ma gli orchi di Roccianera sono il pericolo più grave. Sono scesi a sud dalle infuocate Steppe Ardenti e ora si aggirano tra gli impervi passi delle Montagne Crestarossa. Dopo aver conquistato alcune roccaforti, hanno rinchiuso gli abitanti di Borgolago nel villaggio. Il commercio, la raccolta di provviste e i viaggi lungo le strade settentrionali sono stati interrotti."},{t="Colpire l'avanguardia",b="Il Maresciallo Marris comanda le guardie assediate di Borgolago, ma non può sottrarre soldati per attaccare le posizioni degli orchi. Perciò ti chiede di colpire i loro esploratori d'avanguardia e i fanti. Le loro rozze asce logore dalla battaglia dimostreranno che sono morti. Marris spera di decimare gli invasori presso Guardamasso a nord e nelle aspre zone del sud-est delle Montagne Crestarossa."}},faq={{q="Da dove vengono questi orchi di Roccianera?",a="Sono marciati a sud attraverso gli impervi passi montani delle Steppe Ardenti, dove si trova la loro antica roccaforte attorno al Massiccio Roccianera.",al={"da dove vengono gli orchi","invasione di roccianera a crestarossa","perché ci sono orchi a crestarossa"}},{q="Chi assegna questo compito?",a="Il Maresciallo Marris, alto ufficiale militare di Borgolago, impartisce l'ordine. È responsabile della difesa del villaggio e del mantenimento dell'ordine, mentre questo si ritrova sempre più circondato.",al={"chi assegna blackrock menace","committente missione blackrock menace","missione maresciallo marris"}},{q="Dove si trovano gli invasori di Roccianera?",a="Gli invasori di Roccianera occupano gli altopiani settentrionali attorno al Mastio di Guardamasso e alcuni avamposti nella zona sud-orientale delle Montagne Crestarossa.",al={"dove si trovano gli orchi di roccianera","posizioni ascia usurata","accampamenti orchi crestarossa"}},{q="Perché il Maresciallo Marris chiede le Ascia Usurata?",a="Le asce logore dalla battaglia forniscono al Maresciallo Marris la prova concreta che hai combattuto e ucciso i predoni di Roccianera che minacciano la valle.",al={"perché le asce","prova di morte","scopo ascia usurata"}},{q="Cosa succede dopo la sconfitta di questi esploratori?",a="Dopo aver decimato l'avanguardia, il Maresciallo Marris ordina un attacco contro Tharil'zun, il capo locale di Roccianera, trincerato tra i monti.",al={"cosa viene dopo blackrock menace","missione successiva a blackrock menace","chi guida gli orchi"}},{q="Gli orchi sono affiliati all'Orda di Thrall?",a="No. Il clan di Roccianera qui è composto da resti della Vecchia Orda. Rimane ferocemente ostile all'Alleanza e agisce indipendentemente dalla nuova Orda di Thrall a Kalimdor.",al={"questi orchi fanno parte dell'orda","il clan di roccianera fa parte dell'orda di thrall","orchi amichevoli a crestarossa"}}},fx={ded9bd4b={q="Perché il Maresciallo Marris vuole uccidere gli orchi Blackrock?",a="Il clan Blackrock è disceso dalle Steppe Ardenti, conquistando il Mastio di Guardamasso e devastando le terre a nord di Borgolago. Le loro incursioni incessanti hanno di fatto intrappolato i cittadini entro i confini della città, rinchiusi come bestiame. Il Maresciallo Marris vuole spezzare questo assedio soffocante, mettere in sicurezza i confini settentrionali della regione ed eliminare le bande di ricognizione prima che Borgolago venga completamente invasa.",al={"motivo di marris","perché uccidere gli orchi blackrock","perché la minaccia blackrock"}},["29f2a399"]={q="Chi sono gli invasori Blackrock che minacciano Borgolago?",a="Sei mandato contro gli orchi Blackrock, resti della Vecchia Orda discesi dalle Steppe Ardenti. Dopo aver conquistato il Mastio di Guardamasso a nord, devastano attivamente le terre selvagge e hanno iniziato a stabilire avamposti nelle zone sudorientali di Redridge, nel tentativo di soffocare Borgolago ed estendere il proprio controllo territoriale attraverso le montagne.",al={"chi sono gli orchi blackrock","chi è il bersaglio","orchi di guardamasso"}},e27bf976={q="Perché il Maresciallo Marris ha bisogno di avventurieri invece che delle guardie di Borgolago?",a="La guarnigione locale di Borgolago è allo stremo. Con l'esercito di Roccavento assente e incapace di inviare rinforzi, Marris e le poche guardie rimaste non possono permettersi di uscire in forze nelle terre selvagge senza lasciare la città completamente indifesa. Per respingere gli invasori in avanzata, si affida a mercenari indipendenti e avventurieri capaci.",al={"perché le guardie non combattono","perché marris ha scelto me","perché servono avventurieri"}}},fp="16,173,18.325.0,21.350.0,41.140.0,21.166.0,42.141.0,48.129.0,45.137.1,44.164.0"}
P.entries["quest:200"] = {n="Bookie Herod",s="Una fuga di notizie spinge il Tenente Doren a cercare un traditore tra i suoi uomini. Kurzen ha scoperto il segreto di Thorsen e Doren vuole i registri di Bookie Herod, l'ufficiale logistico di Kurzen, dall'Insediamento di Kurzen.",h="Una fuga di notizie spinge il Tenente Doren a cercare un traditore tra i suoi uomini.",kw={"bookie herod","colonnello kurzen","insediamento di kurzen","tenente doren","valle di rovotorto","thorsen"},ang={["faction:Alliance"]="Un tempo il Tenente Doren e i suoi uomini servivano sotto il Colonnello Kurzen, prima di ribellarsi. Ora cercano una spia tra le proprie fila."},sec={{t="Una falla nei ranghi",b="Il Tenente Doren sospetta che ci sia un traditore tra i suoi uomini. Kurzen ha scoperto il segreto di Thorsen e la fuga di notizie minaccia le loro operazioni. Doren deve quindi trovarne la fonte. Thorsen manteneva un contatto all'Insediamento di Kurzen tramite Bookie Herod, l'ufficiale logistico del colonnello. I registri scritti di Herod potrebbero rivelare come l'operazione sia stata scoperta."},{t="L'ufficio logistico",b="I documenti di Bookie Herod si trovano nell'Insediamento di Kurzen. Quando Doren prestava servizio sotto Kurzen, l'ufficio di Herod era all'ultimo piano dell'unica casa a due piani dell'insediamento. Le richieste di rifornimenti e i messaggi del Colonnello Kurzen potrebbero rivelare come il segreto di Thorsen sia stato tradito."}},faq={{q="Chi è Bookie Herod?",a="Bookie Herod è l'ufficiale logistico degli uomini del Colonnello Kurzen. Si occupa dei rifornimenti e delle operazioni del campo all'Insediamento di Kurzen. Un tempo era il contatto interno di Thorsen.",al={"ruolo di herod","chi è il bookie","storia di bookie herod"}},{q="Perché il Tenente Doren vuole i documenti di Herod?",a="Il Tenente Doren sospetta che una spia abbia tradito il loro campo dopo che il Colonnello Kurzen ha scoperto il segreto di Thorsen. Spera che i registri logistici e la corrispondenza di Herod rivelino come siano trapelate le informazioni.",al={"perché prendere i documenti di herod","spia di doren","come è stato catturato thorsen"}},{q="Dove si trovano i documenti di Bookie Herod?",a="L'ufficio di Herod è all'ultimo piano dell'unica casa a due piani nell'Insediamento di Kurzen. Doren crede che i suoi registri siano ancora lì.",al={"dove sono i documenti","posizione dell'ufficio di herod","casa a due piani di kurzen"}},{q="Cosa precede questa indagine?",a="L'indagine fa seguito a Jungle Secrets. Lì, il Tenente Doren conclude che qualcuno deve aver rivelato il segreto di Thorsen agli uomini di Kurzen.",al={"missione precedente","prerequisito di bookie herod"}}},fp="12,196,19.321.0,20.258.0,20.170.0,47.187.0,41.141.0,37.141.0"}
P.entries["quest:201"] = {n="Investigate the Camp",s="Krazek ha sentito dire che Hemet Nesingwary potrebbe trovarsi nella Valle di Rovotorto. Ti chiede di trovare l'accampamento dei cacciatori vicino al Lago Nazferiti e verificare la notizia.",h="Krazek ha sentito dire che Hemet Nesingwary potrebbe trovarsi nella Valle di Rovotorto.",kw={"baia del bottino","hemet nesingwary","accampamento cacciatori","investigate the camp","krazek","lago nazferiti","valle di rovotorto","s.p.r. & co."},ang={["class:Hunter"]="Da cacciatore, potresti sentirti attratto dal raduno di cui si vocifera, guidato da Hemet Nesingwary. Lì puoi mettere alla prova le tue abilità di tracciamento e di tiro nella giungla.",["race:Dwarf"]="Da nano, potresti essere fiero di Hemet Nesingwary, uno dei tiratori scelti e avventurieri nanici più famosi. La sua presunta presenza nelle remote terre selvagge meridionali della Valle di Rovotorto potrebbe stuzzicare la tua curiosità."},sec={{t="Rapporti nella giungla",b="Le notizie da Baia del Bottino parlano di un accampamento di cacciatori nel nord della Valle di Rovotorto. Krazek ha sentito dire che si trova lungo il fiume, appena oltre la concessione mineraria della S.P.R. & Co. vicino al Lago Nazferiti. La giungla è senza legge, piena di pericoli e interessi in competizione. Un accampamento armato attira l'attenzione."},{t="Un rinomato tiratore scelto",b="Hemet Nesingwary potrebbe essere tra i cacciatori dell'accampamento. Il rinomato tiratore scelto nanico è conosciuto in tutte le terre come un esploratore d'élite con legami influenti. Krazek ti manda risalendo il fiume per scoprire se il leggendario cacciatore è arrivato."}},faq={{q="Chi assegna l'incarico di investigare sull'accampamento?",a="Krazek, un agente di Baia del Bottino, ti manda a trovare l'accampamento e riferire dove si trova.",al={"chi vuole che l'accampamento venga indagato","chi ha dato questa missione","krazek baia del bottino"}},{q="Chi è Hemet Nesingwary?",a="Hemet Nesingwary è un rinomato cacciatore di grosse prede ed esploratore nanico. Le notizie a Baia del Bottino lo collocano tra i cacciatori accampati vicino al Lago Nazferiti, e la sua reputazione e i suoi legami hanno attirato l'interesse.",al={"hemet nesingwary rovotorto","chi è hemet nesingwary","famoso cacciatore nano rovotorto"}},{q="Dove si trova l'accampamento dei cacciatori?",a="L'accampamento dei cacciatori si trova risalendo il fiume rispetto alle attività minerarie della S.P.R. & Co., lungo il Lago Nazferiti, nel nord della Valle di Rovotorto.",al={"posizione accampamento cacciatori","dove si trova l'accampamento di nesingwary","dove si trova l'accampamento a monte"}},{q="Perché Krazek è interessato a questo accampamento di caccia?",a="Secondo le notizie, Hemet Nesingwary potrebbe trovarsi all'accampamento. La sua influenza e i suoi legami rendono Krazek cauto e curioso.",al={"perché a krazek importa","perché indagare sui cacciatori","motivo di krazek"}},{q="Qual è il rapporto tra i cacciatori e la S.P.R. & Co.?",a="I cacciatori non fanno parte della S.P.R. & Co. Il loro accampamento si trova risalendo il fiume rispetto al sito minerario della compagnia, vicino al Lago Nazferiti, che ne indica la posizione.",al={"connessione con la s.p.r. & co.","i cacciatori sono con la s.p.r. & co.","s.p.r. & co. lago nazferiti"}},{q="A chi bisogna riferire dopo aver trovato l'accampamento?",a="Dopo aver trovato e perlustrato l'accampamento sulla riva del fiume, torna a sud a Baia del Bottino e riferisci direttamente a Krazek.",al={"cosa fare dopo aver trovato l'accampamento","a chi riferire","dove consegnare investigate the camp"}}},fp="20,145,21.270.0,19.230.0,43.87.0,24.198.0,35.129.0,46.112.0,57.154.0,45.101.0"}
P.entries["quest:202"] = {n="Colonnello Kurzen",s="Al Campo dei Ribelli, il Tenente Doren ti manda contro il Colonnello Kurzen e la sua guardia scelta. La loro sconfitta potrebbe garantire la sopravvivenza dei ribelli.",h="Al Campo dei Ribelli, il Tenente Doren ti manda contro il Colonnello Kurzen e la sua guardia scelta.",kw={"colonnello kurzen","kurzen","tenente doren","campo dei ribelli","deposito","valle di rovotorto"},ang={["faction:Alliance"]="Come membro dell'Alleanza, puoi contribuire a spezzare la presa di un ufficiale rinnegato di Roccavento sulla parte settentrionale della Valle di Rovotorto eliminando Kurzen."},sec={{t="Il Cuore del Deposito",b="I disertori del Tenente Doren sono giunti allo scontro finale contro il loro ex comandante. Hai contribuito a sopprimere gli specialisti d'élite di Kurzen, ma i ribelli restano in pericolo finché lui mantiene il suo rifugio nella giungla. Doren ti manda nella caverna del Deposito, dove Kurzen dirige le sue forze al fianco dei suoi sottoposti e dei suoi veterani."},{t="Colpire la testa del serpente",b="Il Tenente Doren ha bisogno di una prova della caduta di Kurzen. Ti chiede di riportare la testa del colonnello rinnegato e di sconfiggere i suoi veterani e sottoposti. Lo scontro nella caverna offre ai ribelli la loro unica possibilità di tirare un sospiro di sollievo tra i pericoli della Valle di Rovotorto settentrionale."}},faq={{q="Chi assegna questo compito?",a="Dopo aver completato Special Forces, il Tenente Doren ti manda dal Campo dei Ribelli, nella parte settentrionale della Valle di Rovotorto.",al={"chi assegna la missione","datore di missione","dove prendere il colonnello kurzen"}},{q="Dove si trova il Colonnello Kurzen?",a="Kurzen dirige le sue truppe nel profondo del sistema di caverne del Deposito, all'interno del complesso di Kurzen nella parte settentrionale della Valle di Rovotorto.",al={"dove si trova kurzen","posizione di kurzen","come trovare il colonnello kurzen"}},{q="Quale prova richiede il Tenente Doren?",a="Il Tenente Doren ti chiede di riportare la testa di Kurzen come prova della caduta del comandante rinnegato, e di sconfiggere i suoi veterani e sottoposti.",al={"quale prova è necessaria","prova di kurzen","oggetto di consegna"}},{q="Cosa è successo prima di questo scontro?",a="Con Special Forces hai indebolito gli operativi specializzati di Kurzen. Poi ti sei rivolto al suo comando centrale.",al={"missione prerequisito","qual è la missione precedente","catena prima di kurzen"}}},fp="14,137,26.318.0,27.260.0,22.113.0,32.123.0,41.139.0,36.127.0"}
P.entries["quest:203"] = {n="The Second Rebellion",s="Al Campo dei Ribelli, nella parte settentrionale della Valle di Rovotorto, il Sergente Yohwa chiede aiuto contro le soverchianti forze del Colonnello Kurzen. In inferiorità numerica di dieci a uno, i ribelli non possono combattere una lunga guerra aperta. Colpiscono in fretta e di nascosto, nella speranza di ridurre le fila di Kurzen e allentare la pressione sul loro rifugio.",h="Al Campo dei Ribelli, nella parte settentrionale della Valle di Rovotorto, il Sergente Yohwa chiede aiuto...",kw={"colonnello kurzen","combattente della giungla","kurzen","campo dei ribelli","sergente yohwa","special forces","valle di rovotorto","yohwa"},sec={{t="Una battaglia persa",b="Al Campo dei Ribelli, i ribelli affrontano le forze del Colonnello Kurzen, che contano almeno dieci nemici per ciascuno dei loro. Il Sergente Yohwa sa che il Colonnello è un brillante tattico militare. Una guerra di logoramento a campo aperto non lascerebbe loro alcuna possibilità.\n\nCosì rivolgono contro Kurzen i suoi stessi metodi segreti. Colpiscono rapidamente il suo accampamento, poi fuggono prima che possano arrivare pesanti rinforzi."},{t="Colpire il complesso",b="Il Sergente Yohwa ti chiede di dirigerti a est, nella roccaforte di Kurzen, ed eliminare un nutrito contingente dei suoi combattenti della giungla. La loro superiorità numerica grava sul Campo dei Ribelli. Riduci le loro fila e il rifugio potrà respirare più facilmente."}},faq={{q="Chi è il Sergente Yohwa?",a="Il Sergente Yohwa è un ufficiale del Campo dei Ribelli, nella parte settentrionale della Valle di Rovotorto. Coordina attacchi segreti contro le forze del Colonnello Kurzen.",al={"yohwa","chi dà the second rebellion","sergente yohwa"}},{q="Dove si trova l'accampamento del Colonnello Kurzen?",a="Il complesso del Colonnello Kurzen si trova a est del Campo dei Ribelli, tra le fitte foreste della parte settentrionale della Valle di Rovotorto.",al={"posizione accampamento kurzen","dove sono i combattenti della giungla","posizione kurzen"}},{q="Perché i ribelli usano tattiche segrete invece della guerra aperta?",a="I ribelli affrontano almeno dieci combattenti del Colonnello Kurzen per ciascuno dei loro. Contro un brillante stratega militare, un attacco aperto è impossibile, quindi devono affidarsi a rapidi attacchi di guerriglia.",al={"perché tattiche segrete","perché non combattere kurzen a viso aperto","tattiche ribelli"}},{q="Cosa c'è dopo The Second Rebellion?",a="Dopo che avrai abbattuto i combattenti della giungla di Kurzen, il Sergente Yohwa ti proporrà il passo successivo, Special Forces.",al={"missione successiva","cosa c'è dopo the second rebellion","seguito di the second rebellion"}}},fp="20,293,15.380.0,21.217.0,22.140.0,39.112.0,60.200.0,38.97.0"}
P.entries["quest:2038"] = {n="Bingles' Missing Supplies",s="Sulla costa sud-orientale di Loch Modan, Bingles Scoppiamicce è bloccato dopo che i trogg gli hanno rubato l'equipaggiamento. Puoi recuperare i suoi attrezzi e gli esplosivi Blastencapper, così potrà riparare il suo girocottero e tornare a combattere per Gnomeregan.",h="Sulla costa sud-orientale di Loch Modan, Bingles Scoppiamicce è bloccato dopo che i trogg gli hanno rubato...",kw={"bingles","blastencapper","scoppiamicce","gnomeregan","girocottero","martello","loch modan","cacciavite","loch","trogg","chiave meccanica"},ang={["faction:Alliance"]="In quanto membro dell'Alleanza, aiutare un pilota a Loch Modan protegge le vie d'acqua e sostiene lo sforzo più ampio per riconquistare i territori perduti di Khaz Modan.",["profession:Engineering"]="In quanto ingegnere, sai che gli attrezzi specializzati e gli esplosivi volatili come il Blastencapper di Scoppiamicce sono pericolosi in mano ai trogg e un affronto all'artigianato.",["race:Dwarf"]="In quanto nano, sai che i trogg sulle isole del Loch minacciano il commercio e i viaggi locali. Ogni colpo inferto ai loro accampamenti aiuta i Montanari.",["race:Gnome"]="In quanto gnomo, ogni attrezzo che recuperi avvicina il tuo popolo a una controffensiva aerea contro i trogg e gli gnomi lebbrosi che soffocano Gnomeregan."},sec={{t="Una discesa umida",b="Bingles Scoppiamicce precipita con il suo girocottero nelle fredde acque del Loch. Si trascina a riva, stordito, e i trogg delle isole centrali del lago gli si avventano addosso. Gli rubano i suoi averi più preziosi."},{t="Ingegno gnomico sotto assedio",b="I trogg sparpagliano l'equipaggiamento di Bingles nei loro accampamenti sulle isole. Tra gli oggetti rubati ci sono una chiave meccanica, un cacciavite e un martello, oltre alla sua invenzione volatile e ad alto potenziale, il Blastencapper di Scoppiamicce. In mano ai trogg, gli esplosivi mettono immediatamente in pericolo i viaggiatori."},{t="Per Gnomeregan",b="Bingles lotta per liberare Gnomeregan, la sua patria, dai trogg sotterranei e dagli gnomi lebbrosi irradiati. Immagina un decisivo assalto aereo, ma senza i suoi attrezzi e i Blastencapper non può ricostruire la sua macchina volante. La sua campagna resta bloccata tra i canneti."}},faq={{q="Perché Bingles Scoppiamicce è bloccato a Loch Modan?",a="Bingles Scoppiamicce è bloccato a Loch Modan dopo essersi schiantato con il suo girocottero. Si trascina a riva sulla sponda sud-orientale, dove i trogg delle isole vicine lo tendono un'imboscata e gli rubano gli attrezzi e gli esplosivi sperimentali.",al={"perché bingles è qui","come si è schiantato bingles","incidente di bingles"}},{q="Quali provviste sono state rubate dai trogg?",a="I trogg rubano a Bingles la chiave meccanica, il cacciavite, il martello e il suo esplosivo specializzato, il Blastencapper di Scoppiamicce.",al={"cosa hanno rubato i trogg","rifornimenti di bingles","quali oggetti bingles"}},{q="Dove hanno portato l'attrezzatura di Bingles i trogg?",a="I trogg portano l'equipaggiamento di Bingles nei loro accampamenti sulle isole a nord del Loch. Sparpagliano gli attrezzi e gli esplosivi lungo le coste rocciose.",al={"dove sono gli attrezzi di bingles","posizione isola dei trogg","dove si trova il blastencapper"}},{q="Cos'è il Blastencapper?",a="Il Blastencapper di Scoppiamicce è un ordigno esplosivo progettato da Bingles per gli attacchi aerei contro i nemici che occupano Gnomeregan.",al={"cos'è il blastencapper","blastencapper di scoppiamicce","esplosivo di bingles"}},{q="A quale movimento fa riferimento Bingles?",a="Bingles parla di riconquistare Gnomeregan. Spera di guidare un bombardamento aereo contro i trogg sotterranei e gli gnomi lebbrosi che occupano la capitale degli gnomi.",al={"quale movimento","per gnomeregan","causa di bingles"}},{q="Perché Bingles non può recuperare le provviste da solo?",a="Bingles non può recuperare le provviste perché, dopo lo schianto, è solo e disarmato, mentre il suo girocottero è fuori portata. Attraversare acque aperte per affrontare trogg aggressivi senza armi né velivolo sarebbe un suicidio per un ingegnere solitario.",al={"perché bingles non li recupera","perché bingles aspetta"}}},fx={["008fc445"]={q="Perché Bingles Scoppiamicce vuole recuperare le sue provviste?",a="Bingles si è schiantato con la sua macchina volante nel Loch mentre la collaudava, ma aver perso l'equipaggiamento mette a rischio ben più del solo recupero dei rottami. Ha fabbricato attrezzi speciali ed esplosivi esclusivi Blastenheimer Blastencapper proprio per l'offensiva aerea degli gnomi volta a riconquistare Gnomeregan. Senza gli attrezzi per ricostruire e le munizioni da impiegare, non si può procedere con il bombardamento dei trogg e degli gnomi lebbrosi che occupano la sua patria.",al={"motivo di bingles","perché bingles ha bisogno dei suoi attrezzi","perché aiutare bingles"}},["0d3e655b"]={q="Chi ha preso le provviste di Bingles e perché si trova qui?",a="I trogg che infestano le isole di Loch Modan hanno teso un'imboscata a Bingles poco dopo il suo schianto e gli hanno razziato l'equipaggiamento. Questi bruti primitivi del sottosuolo sono stati portati alla luce dagli scavi dei nani in tutta Khaz Modan. Spinti da un violento istinto territoriale e dalla passione per gli strani gingilli meccanici luccicanti, hanno trascinato la cassetta degli attrezzi e gli esplosivi instabili di Bingles nei loro accampamenti sulle rive del lago.",al={"chi ha rubato gli attrezzi di bingles","trogg di loch modan e bingles","perché i trogg sono sulle isole"}}},fp="25,227,14.206.0,29.266.0,14.264.0,52.217.0,40.116.0,40.153.0,26.129.0,38.157.0,48.233.0"}
P.entries["quest:2039"] = {n="Trova Bingles",s="A Forgiardente, Gnoarn avvia le ricerche di Trova Bingles dopo più di una settimana senza notizie. Bingles Scoppiamicce è scomparso durante un volo verso Gnomeregan in rovina, e i cercatori vengono mandati sulle rive del Loch Modan. Lì Bingles è vivo e ha bisogno di rottami meccanici.",h="A Forgiardente, Gnoarn avvia le ricerche di Trova Bingles dopo più di una settimana senza notizie.",kw={"bingles","scoppiamicce","macchina volante","gnoarn","gnomeregan","forgiardente","loch modan","ricognizione","tinker town"},ang={["faction:Alliance"]="Come esploratore dell'Alleanza, aiuti a colmare il divario di comunicazione tra le sale di Forgiardente e le operazioni sul campo nel Loch Modan.",["profession:Engineering"]="Come ingegnere, conosci i pericoli dell'aviazione gnomica, dove perdere un dado o far esplodere un motore fa parte del lavoro sul campo.",["race:Gnome"]="Come gnomo, aiutare a ritrovare Bingles contribuisce a mantenere viva la speranza di riconquistare Gnomeregan, dove ogni esploratore e ogni Macchina Volante contano."},sec={{t="Un Pilota Scomparso",b="L'aviatore gnomo Bingles Scoppiamicce è stato mandato da Tinker Town, a Forgiardente, a sorvolare le rovine irradiate di Gnomeregan per una ricognizione. È passata più di una settimana senza notizie. Gnoarn teme che Bingles possa essersi fatto esplodere in cielo, un rischio dell'ingegneria gnomica. Il suo ultimo rapporto lo collocava da qualche parte sopra le acque del Loch Modan."},{t="Giù al Loch",b="I cercatori trovano Bingles vivo lungo la costa del Loch Modan, ben lontano da un tragico cumulo di rottami. Non si scompone per la sua lunga assenza e si risente un po' che qualcuno abbia dubitato delle sue capacità di pilotaggio. Invece di tornare subito a fare rapporto a Gnoarn, chiede al suo salvatore di recuperare gli attrezzi e gli esplosivi Blastencapper rubati dai trogg. Gli servono per riprendere i suoi doveri a sostegno del movimento gnomico."}},faq={{q="Chi è Bingles Scoppiamicce?",a="Bingles Scoppiamicce è un eccentrico aviatore e meccanico gnomo. È stato mandato a sorvolare Gnomeregan in rovina per una ricognizione, poi è precipitato vicino al Loch Modan.",al={"chi è bingles","lore di bingles scoppiamicce","chi è il pilota"}},{q="Perché Bingles stava volando sopra Gnomeregan?",a="Dopo che Gnomeregan è caduta in mano ai trogg e alle radiazioni, i capi e gli inventori gnomi hanno continuato a sorvegliarla. Bingles ha sorvolato la città per ricognire le posizioni e le condizioni dei nemici, nell'ambito degli sforzi per riconquistare la propria casa.",al={"missione di bingles","perché bingles stava volando","ricognizione di gnomeregan"}},{q="Dove si trova Bingles?",a="Bingles si trova sulla costa sudorientale del Loch Modan, intento a riordinare i pezzi della sua Macchina Volante precipitata.",al={"dove si trova bingles","trovare posizione di bingles","dove trovare bingles"}},{q="Chi è Gnoarn?",a="Gnoarn è un coordinatore gnomo a Tinker Town, Forgiardente. Tiene traccia del personale e delle missioni gnomiche, e avvia le ricerche quando Bingles non rientra in orario.",al={"chi è gnoarn","gnoarn conferitore di missioni"}},{q="Cosa succede dopo aver trovato Bingles?",a="Dopo aver trovato Bingles, gli avventurieri possono recuperare la sua chiave inglese, il cacciavite, il martello e gli esplosivi Blastencapper dai trogg sulle isole del Loch.",al={"cosa succede dopo aver trovato bingles","missione del dado ad alette","seguiti di bingles"}},{q="Bingles è ferito a causa dello schianto?",a="Bingles è illeso, anche se il suo orgoglio è ferito perché Gnoarn ha dubitato delle sue capacità di volo. È concentrato sul recupero degli attrezzi e degli esplosivi che i trogg gli hanno rubato.",al={"bingles è ferito","bingles è morto"}}},fx={b67b7bf8={q="Perché Gnoarn vuole che Bingles venga ritrovato?",a="Bingles è stato mandato in una missione cruciale di ricognizione aerea sopra Gnomeregan, ormai caduta, e non dà notizie da oltre una settimana. Considerata l'inaffidabilità delle macchine gnomiche e la propensione di Bingles agli incidenti, Gnoarn teme che il pilota sia saltato in aria da qualche parte nelle terre selvagge. Gli serve qualcuno che perlustri la zona vicino a Loch Modan, dove Bingles è stato visto l'ultima volta, per scoprire che fine ha fatto.",al={"perché trovare bingles","motivo di gnoarn","perché mandare qualcuno a cercare bingles"}}},fp="12,264,15.329.0,16.390.0,29.150.0,39.209.0,25.95.0,14.162.0,35.144.0,31.170.0"}
P.entries["quest:204"] = {n="Bad Medicine",s="Al Campo dei Ribelli, nella parte settentrionale della Valle di Rovotorto, il Sergente Yohwa cerca un modo per indebolire le forze del Colonnello Kurzen. I suoi uomini medicina curano i soldati e avvelenano i combattenti di Yohwa: la resistenza ha bisogno dei loro rimedi e delle loro tossine.",h="Al Campo dei Ribelli, nella parte settentrionale della Valle di Rovotorto, il Sergente Yohwa cerca un modo...",kw={"rimedio della giungla","kurzen","complesso di kurzen","uomini medicina","campo dei ribelli","sergente yohwa","valle di rovotorto","estratto di felce velenosa"},ang={["faction:Alliance"]="Per l'Alleanza, privare Kurzen del supporto medico può aiutare a tenere in vita più combattenti del Campo dei Ribelli nella lotta contro le sue forze."},sec={{t="Privare l'Accampamento del supporto",b="Gli uomini medicina del Colonnello Kurzen curano i suoi soldati e avvelenano i combattenti di Yohwa con l'estratto di felce velenosa. Il Sergente Yohwa ti chiede di raccogliere i loro rifornimenti nel Complesso di Kurzen. I rimedi possono curare i combattenti feriti al Campo dei Ribelli. Un campione di estratto di felce velenosa permetterà alla resistenza di studiare la tossina e preparare le proprie cure."}},faq={{q="Chi offre questo incarico?",a="Al Campo dei Ribelli, nella parte settentrionale della Valle di Rovotorto, il Sergente Yohwa ti chiede di recuperare i rifornimenti medici.",al={"chi dà bad medicine","datore missione bad medicine","missione yohwa"}},{q="Perché il Sergente Yohwa vuole i Rimedi della Giungla?",a="Gli uomini medicina di Kurzen usano i Rimedi della Giungla per curare i suoi soldati. La resistenza ha bisogno dei rimedi per curare i suoi combattenti feriti.",al={"perché servono rimedi della giungla","scopo rimedio della giungla"}},{q="A cosa serve l'Estratto di Felce Velenosa?",a="Le forze di Kurzen usano l'estratto di felce velenosa per avvelenare i combattenti di Yohwa. Yohwa ha bisogno di un campione perché il campo possa studiare la tossina e preparare rimedi contro di essa.",al={"perché estratto di felce velenosa","uso estratto"}},{q="Dove sono conservati questi rifornimenti medici?",a="I rifornimenti si trovano nel Complesso di Kurzen. Gli uomini medicina portano i rimedi, mentre le Scatole di Rifornimenti Medici sparse nell'accampamento contengono gli estratti di felce velenosa.",al={"dove trovare rimedi della giungla","posizione estratto"}}},fp="12,226,32.332.0,27.106.0,45.130.0,40.149.0,38.148.0"}
P.entries["quest:2040"] = {n="Underground Assault",s="Shoni la Shilente manda avventurieri dell'Alleanza nelle Miniere della Morte a impossessarsi di un nucleo energetico. Gli gnomi esiliati ne hanno bisogno per far avanzare i trapani nella roccia attorno a Gnomeregan e riconquistare la loro casa.",h="Shoni la Shilente manda avventurieri dell'Alleanza nelle Miniere della Morte a impossessarsi di un nucleo...",kw={"miniere della morte","sarchiapone","gnomeregan","sminuzzatore goblin","gyrodrillmatic","shoni la shilente","trogg","underground assault"},ang={["faction:Alliance"]="Da avventuriero dell'Alleanza, rafforzi il legame di Roccavento con i suoi alleati gnomi sfollati e colpisci la linea di rifornimento dei Defias.",["profession:Engineering"]="Da ingegnere, puoi apprezzare l'audace piano di sottrarre il nucleo energetico a uno sminuzzatore goblin e alimentare macchinari di scavo gnomeschi di precisione.",["race:Gnome"]="Da avventuriero gnomesco esiliato, aiuti a recuperare un nucleo energetico per i trapani che possono farsi strada tra le pareti rocciose della tua casa caduta e contribuire a scacciare i trogg da Gnomeregan."},sec={{t="Un ingegno disperato",b="Dopo che i trogg primitivi hanno fatto crollare Gnomeregan, gli inventori gnomi sono fuggiti attraverso Khaz Modan e Roccavento. Shoni la Shilente sta già studiando come perforare la roccia attorno alla loro casa perduta. I suoi Gyrodrillmatic Excavationators hanno bisogno di molta energia per scavare nella pietra sotterranea. Nelle terre umane non ci sono reti elettriche locali, così gli gnomi si sono rivolti ai pesanti macchinari goblin del sottobosco criminale."},{t="Saccheggiare le fonderie dei Defias",b="Nei cunicoli delle Miniere della Morte nelle Marche Occidentali, la Fratellanza dei Defias di Edwin VanCleef impiega ingegneri goblin per costruire macchine da guerra. Una di queste è uno sminuzzatore goblin funzionante, un automa mastodontico. Shoni manda agenti dell'Alleanza a distruggerlo o smantellarlo e a recuperare il suo cuore specializzato, il Sarchiapone. Gli gnomi esiliati hanno bisogno di quell'alimentazione goblin per far avanzare i trapani nella roccia sotterranea e avviare la controffensiva per riconquistare Gnomeregan."}},faq={{q="Chi assegna la missione Underground Assault?",a="Shoni la Shilente, un'ingegnera gnomesca nel Distretto dei Nani di Roccavento, ti manda in missione. Dopo aver ascoltato i suoi ambiziosi piani, altri gnomi spesso indirizzano gli avventurieri da lei.",al={"assegnatore missione underground assault","chi assegna underground assault","missione shoni"}},{q="Dove posso trovare il Sarchiapone?",a="Recuperi il Sarchiapone da uno sminuzzatore goblin funzionante, nelle profondità dei tunnel della fonderia delle Miniere della Morte nelle Marche Occidentali.",al={"posizione sarchiapone","dove si trova sarchiapone","pezzo sminuzzatore miniere della morte"}},{q="Perché Shoni ha bisogno di pezzi di uno sminuzzatore goblin?",a="I Gyrodrillmatic Excavationators gnomeschi hanno bisogno di molta energia portatile per farsi strada attraverso le barriere sotterranee rinforzate attorno a Gnomeregan. Il nucleo ad alta potenza che alimenta lo sminuzzatore goblin dei Defias fornisce la forza meccanica necessaria a quei trapani.",al={"perché pezzi goblin","perché riserva energetica sminuzzatore","scopo sarchiapone"}},{q="Qual è l'obiettivo più ampio di questa missione?",a="Gli gnomi esiliati progettano di alimentare pesanti trapani da scavo, scavare gallerie attraverso il perimetro roccioso di Gnomeregan occupata e lanciare un attacco a sorpresa contro i trogg che la occupano.",al={"perché fare underground assault","missione reclamare gnomeregan","piano d'assalto gnomi"}},{q="Cosa è successo a Gnomeregan che ha causato la pianificazione di questo assalto?",a="Un'invasione sotterranea di trogg è emersa dalle profondità sotto Gnomeregan e ha sopraffatto la città. Durante la caotica difesa, la contaminazione da radiazioni tossiche ha costretto i sopravvissuti a fuggire come profughi a Forgiardente e Roccavento.",al={"perché è caduta gnomeregan","cosa è successo a gnomeregan","invasione trogg"}},{q="La Fratellanza dei Defias e i trogg sono alleati?",a="No, la Fratellanza dei Defias e i trogg non hanno alcun legame. I Defias hanno assunto inventori goblin per costruire macchine da guerra nelle Marche Occidentali, e Shoni usa la fonderia delle Miniere della Morte per procurarsi potenti tecnologie goblin.",al={"defias e trogg","i trogg sono con i defias"}}},fx={["41842bc5"]={q="Che cos'è lo Sarchiapone?",a="Lo Sarchiapone è un'alimentazione per goblin intatta e molto efficiente, alloggiata nel trituratore in funzione nelle profondità delle Miniere della Morte. Shoni la Shilente intende integrare direttamente questo nucleo energetico nei Gyrodrillmatic Excavationators gnomici. Queste pesanti perforatrici hanno bisogno di un'enorme quantità di energia per scavare attraverso la densa barriera rocciosa sotterranea che circonda Gnomeregan, aprendo un varco alle forze d'assalto gnomiche in attesa di riconquistare la loro casa.",al={"cos'è lo sarchiapone","a cosa serve lo sarchiapone","a cosa serve l'alimentazione del trituratore"}},["37ad24fa"]={q="Perché Shoni ti manda a cercare il trituratore per goblin nelle Miniere della Morte?",a="La Fratellanza dei Defias impiega ingegneria goblin avanzata, compreso un trituratore per legname e minerali perfettamente funzionante, per scavare e costruire le proprie operazioni segrete sotto Rivoluna. Poiché queste macchine da guerra usano nuclei energetici straordinariamente potenti, Shoni ha individuato in questa macchina un bersaglio ideale da recuperare. Ti manda a smantellare o distruggere il trituratore nel cuore del complesso e a recuperare il suo nucleo intatto prima che la Fratellanza possa usarlo ancora.",al={"chi è il bersaglio nelle miniere della morte","perché uccidere il trituratore","perché c'è un trituratore nelle miniere della morte"}}},fp="19,187,21.404.0,28.462.0,40.170.0,43.120.0,49.243.0,41.178.0,67.215.0,49.212.0"}
P.entries["quest:2041"] = {n="Speak with Shoni",s="A Forgiardente, i viaggiatori dell'Alleanza vengono mandati a Roccavento per trovare Shoni la Shilente, la cui unità si prepara per Gnomeregan.",h="A Forgiardente, i viaggiatori dell'Alleanza vengono mandati a Roccavento per trovare Shoni la Shilente, la...",kw={"tram degli abissi","distretto dei nani","gnomeregan","gyrodrillmatic excavationator","forgiardente","shoni la shilente","roccavento","tinkertown","underground assault"},ang={["faction:Alliance"]="In quanto viaggiatore dell'Alleanza, puoi usare il Tram degli Abissi per spostare personale tra Forgiardente e Roccavento.",["profession:Engineering"]="In quanto ingegnere, puoi capire che il progetto di Shoni richiede Gyrodrillmatic Excavationators, complesse macchine gnomesche progettate per scavare in profondità nella terra.",["race:Gnome"]="In quanto gnomo a Forgiardente, puoi contribuire a riconquistare la tua casa irradiata seguendo gli ordini di Shoni e unendoti alla campagna per riprendere Gnomeregan."},sec={{t="Una chiamata da Tinkertown",b="Dopo che Gnomeregan fu avvolta dalle radiazioni, gli gnomi sopravvissuti crearono un quartiere d'esilio a Forgiardente. I suoi ingegneri, tecnici e strateghi continuano a cercare un modo per tornare nella loro casa perduta. Tinkertown dirige gli sforzi, ma i preparativi si estendono oltre Khaz Modan. Ora gli avventurieri vengono mandati a sud, a Roccavento, dove si prepara l'equipaggiamento militare per combattere nel sottosuolo."},{t="Ambizioni sotterranee",b="Nel Distretto dei Nani di Roccavento, Shoni la Shilente comanda una squadra d'élite addestrata per gli assalti sotterranei. I suoi genieri hanno bisogno di Gyrodrillmatic Excavationators per scavare gallerie verso i settori occupati dai trogg. Il Tram degli Abissi passa sotto le montagne tra Forgiardente e Roccavento, rendendo semplice il viaggio da Shoni."}},faq={{q="Chi è Shoni la Shilente?",a="Shoni la Shilente è un'ufficiale gnoma a Roccavento. Comanda un'unità d'assalto sotterraneo che costruisce e impiega pesanti macchine da scavo per aiutare a riconquistare Gnomeregan.",al={"chi è shoni","shoni la shilente","chi è l'npc"}},{q="Dove posso trovare Shoni la Shilente?",a="Shoni si trova nel Distretto dei Nani di Roccavento, vicino agli istruttori di forgiatura e alle fucine, a pochi passi dal terminal del Tram degli Abissi.",al={"dove si trova shoni","posizione di shoni","coordinate di shoni"}},{q="Come arrivo a Roccavento da Forgiardente?",a="Il modo più rapido per andare da Forgiardente a Roccavento è prendere il Tram degli Abissi, sul lato nord-orientale di Tinkertown. Il tram trasporta i viaggiatori sotto le montagne, direttamente al Distretto dei Nani di Roccavento.",al={"viaggiare a roccavento","da forgiardente a roccavento","come raggiungere roccavento"}},{q="Con cosa ha bisogno di aiuto Shoni?",a="Shoni sta equipaggiando una squadra d'assalto sotterraneo e ha bisogno di componenti per i suoi Gyrodrillmatic Excavationators. L'impresa porterà infine gli avventurieri nelle Marche Occidentali e nelle Miniere della Morte.",al={"obiettivo della missione di shoni","cosa vuole shoni"}},{q="Questa missione è richiesta per ottenere Underground Assault?",a="No. È un'indicazione facoltativa. Puoi andare direttamente al Distretto dei Nani di Roccavento e parlare con Shoni per intraprendere Underground Assault.",al={"speak with shoni è obbligatoria","posso andare direttamente da shoni"}},{q="Come si collega questo a Gnomeregan?",a="I capi degli gnomi stanno radunando forze e tecnologie di scavo per penetrare le difese di Gnomeregan. La squadra di Shoni sta sviluppando le trivelle sotterranee necessarie per farsi strada nella città contaminata.",al={"perché gnomeregan","connessione gnomica"}}},fx={["3fdd7df6"]={q="Perché chi ti ha assegnato la missione ti manda da Shoni la Shilente?",a="Gli gnomi stanno lottando duramente per riconquistare la loro casa caduta, Gnomeregan. Shoni la Shilente comanda una squadra d'assalto sotterranea che prepara Gyrodrillmatic Excavationators specializzati per lo sforzo bellico, ma le sue operazioni a Roccavento hanno bisogno di personale. Il comando centrale di Forgiardente ha bisogno di avventurieri capaci disposti a viaggiare verso sud e a sostenere il suo progetto ingegneristico cruciale, prima che l'offensiva possa avanzare.",al={"perché parlare con shoni","perché mandarmi da shoni","perché andare da shoni"}}},fp="16,117,22.360.0,22.321.0,25.171.0,35.133.0,41.188.0,31.179.0,50.139.0,36.189.0"}
P.entries["quest:205"] = {n="Troll Witchery",s="Fratello Nimetz ti manda nel territorio dei Fendicranio per scoprire cosa ha corrotto il Colonnello Kurzen. Dopo Kurzen's Mystery, ti chiede di raccogliere feticci dagli incantatori della tribù.",h="Fratello Nimetz ti manda nel territorio dei Fendicranio per scoprire cosa ha corrotto il Colonnello Kurzen.",kw={"fratello nimetz","colonnello kurzen","mistico","campo dei ribelli","fendicranio","valle di rovotorto","troll witchery","sciamano"},ang={["faction:Alliance"]="In quanto viaggiatore dell'Alleanza, puoi aiutare Fratello Nimetz al Campo dei Ribelli a scoprire cosa ha corrotto il Colonnello Kurzen."},sec={{t="Svelare la Corruzione",b="Fratello Nimetz sospetta che la magia oscura dei troll sia all'origine della caduta nel male del Colonnello Kurzen. Le leggende recuperate nella giungla lo hanno condotto alla seconda tribù di troll, più a sud. Ti chiede quindi di entrare nelle terre dei Fendicranio e prendere i feticci dai loro Sciamani e Mistici. Li studierà al Campo dei Ribelli per esaminarne la magia."}},faq={{q="Chi assegna la missione Troll Witchery?",a="Fratello Nimetz assegna Troll Witchery al Campo dei Ribelli, nella parte settentrionale della Valle di Rovotorto.",al={"chi assegna la missione troll witchery","chi inizia troll witchery","dove ottenere troll witchery"}},{q="Perché Fratello Nimetz vuole i feticci dei Fendicranio?",a="Fratello Nimetz vuole studiare gli oggetti magici oscuri e scoprire se la stregoneria dei troll spiega la caduta nel male del Colonnello Kurzen.",al={"perché fratello nimetz ha bisogno di feticci","scopo di troll witchery","feticci corruzione kurzen"}},{q="Quali nemici portano i feticci?",a="Gli Sciamani e i Mistici Fendicranio portano feticci nel territorio dei Fendicranio.",al={"chi rilascia i feticci dei fendicranio","quali troll hanno i feticci","fonte feticci troll witchery"}},{q="Quale missione precede Troll Witchery?",a="Troll Witchery segue Kurzen's Mystery e prosegue le indagini di Fratello Nimetz sulla follia del colonnello.",al={"catena troll witchery","cosa precede troll witchery","prerequisito per troll witchery"}}},fp="14,183,25.327.0,35.85.0,52.134.0,33.96.0,35.112.0"}
P.entries["quest:206"] = {n="Mai'Zoth",s="Nelle montagne orientali della Valle di Rovotorto, Mai'Zoth custodisce una reliquia che si dice capace di distorcere le menti. Fratello Nimetz crede che il mago ogre abbia corrotto il Colonnello Kurzen e vuole recuperare la reliquia prima che un altro comandante subisca la stessa sorte.",h="Nelle montagne orientali della Valle di Rovotorto, Mai'Zoth custodisce una reliquia che si dice capace di...",kw={"fratello nimetz","kurzen","mai'zoth","maizoth","occhio della mente","tumulo di ogre","campo dei ribelli","rovotorto"},ang={["faction:Alliance"]="Fratello Nimetz opera dal Campo dei Ribelli, nel nord della Valle di Rovotorto. Cerca campioni dell'Alleanza che pongano fine al male nascosto che ha corrotto Kurzen."},sec={{t="La fonte della corruzione",b="Fratello Nimetz crede che il potere dietro la ribellione di Kurzen sia ancora attivo. Le sue ricerche indicano Mai'Zoth, un mago ogre che vive in un tumulo di ogre sulle alture orientali della Valle di Rovotorto. Nimetz dice che Mai'Zoth ha usato la stregoneria per distorcere i pensieri di Kurzen. Finché Mai'Zoth è in vita, un altro comandante potrebbe subire la stessa corruzione."},{t="Recuperare la reliquia",b="Fratello Nimetz ti chiede di uccidere Mai'Zoth e sottrargli l'Occhio della Mente. Porta l'artefatto al Campo dei Ribelli."},{t="Dopo la consegna",b="Fratello Nimetz benedice chiunque gli porti l'Occhio della Mente. Intende studiarne il potere e scoprire se possa servire al bene. Se non è possibile, dice che deve essere distrutto."}},faq={{q="Chi è Mai'Zoth?",a="Mai'Zoth è un mago ogre che vive in un tumulo di ogre nelle montagne orientali della Valle di Rovotorto. Fratello Nimetz crede che la stregoneria di Mai'Zoth abbia corrotto la mente del Colonnello Kurzen.",al={"chi è maizoth","storia di maizoth","ogre magi maizoth"}},{q="Cos'è l'Occhio della Mente?",a="Mai'Zoth possiede l'Occhio della Mente, un artefatto che si dice abbia il potere di controllare le menti. Lo usa per corrompere e influenzare gli altri.",al={"storia dell'occhio della mente","cos'è l'artefatto","occhio della mente"}},{q="Perché Fratello Nimetz vuole che Mai'Zoth venga ucciso?",a="Fratello Nimetz teme che la corruzione di Mai'Zoth possa trasformare qualcun altro in un altro Kurzen, perciò vuole che l'ogre venga ucciso.",al={"motivo di nimetz","perché uccidere maizoth","motivo per cacciare maizoth"}}},fp="8,232,24.322.0,18.112.0,18.166.1,16.175.0,23.130.0,44.115.0"}
P.entries["quest:207"] = {n="Kurzen's Mystery",s="Al Campo dei Ribelli, Fratello Nimetz cerca la causa della caduta del Colonnello Kurzen. Sospetta la magia dei troll e ti manda a copiare le leggende da quattro tavolette nelle rovine dei troll di Stranglethorn.",h="Al Campo dei Ribelli, Fratello Nimetz cerca la causa della caduta del Colonnello Kurzen.",kw={"rovine di bal'lal","fratello nimetz","colonnello kurzen","campo dei ribelli","valle di rovotorto","leggenda troll","scogliera infame","zul'kunda"},sec={{t="In cerca di risposte",b="Fratello Nimetz, al Campo dei Ribelli, cerca la causa della caduta del Colonnello Kurzen, un tempo grande e nobile, nella depravazione. Sospetta che la magia dei troll abbia preso il sopravvento sul colonnello. Le leggende incise su quattro antiche tavolette potrebbero confermare i suoi sospetti. Ti chiede di copiare i segni di ogni tavoletta e riportarli al campo."},{t="Dove si trovano le tavolette",b="Una tavoletta si trova nelle Rovine di Bal'lal. Un'altra giace nelle profondità marine della Scogliera Infame, al largo della costa, vicino a una città sommersa occupata dai murloc Saltscale. Le ultime due tavolette sono nelle Rovine di Zul'Kunda."}},faq={{q="Chi inizia la ricerca delle tavolette dei troll?",a="Fratello Nimetz dà inizio alla ricerca al Campo dei Ribelli.",al={"chi assegna il mistero di kurzen","dove inizio il mistero di kurzen","missione fratello nimetz"}},{q="Perché il Fratello Nimetz vuole le copie delle leggende dei troll?",a="Fratello Nimetz vuole scoprire perché il Colonnello Kurzen, un tempo grande e nobile, sia sprofondato nella depravazione. Sospetta la magia dei troll e le leggende sulle tavolette potrebbero confermarlo.",al={"perché servono le tavolette dei troll","scopo mistero di kurzen","perché nimetz vuole le leggende"}},{q="Dove si trovano le quattro tavolette dei troll?",a="Una tavoletta si trova nelle Rovine di Bal'lal. Un'altra giace nelle profondità marine della Scogliera Infame, a ovest di Grom'gol. Le restanti due sono nelle Rovine di Zul'Kunda.",al={"posizioni tavolette","dove sono le tavolette","mappa tavolette kurzen"}},{q="Cosa succede dopo aver riportato le quattro tavolette?",a="Fratello Nimetz studia le leggende per trovare un legame tra i troll e la caduta del Colonnello Kurzen. La storia continua con Troll Witchery.",al={"cosa succede dopo il mistero di kurzen","seguito del mistero di kurzen","catena di missioni dopo le tavolette"}}},fp="16,185,21.297.0,21.198.0,44.51.0,53.162.0,41.149.0,51.133.0"}
P.entries["quest:2078"] = {n="Gyromast's Revenge",s="Lungo le coste di Rivafosca, Gelkak Giralbero cerca vendetta contro i murloc che hanno saccheggiato la sua nave naufragata. Ti manda a caricare il suo primo ufficiale meccanico, il Threshwackonator 4100.",h="Lungo le coste di Rivafosca, Gelkak Giralbero cerca vendetta contro i murloc che hanno saccheggiato la sua...",kw={"rivafosca","gelkak","golem","giralbero","chiave","murloc","threshwackonator","threshwackonator 4100"},ang={["faction:Alliance"]="Come viaggiatore dell'Alleanza, aiuti a liberare la costa tra Auberdine e le terre a sud da macchinari malfunzionanti e murloc aggressivi.",["profession:Engineering"]="Il primo ufficiale meccanico di Gelkak mostra quanto un capitano bloccato faccia affidamento sull'equipaggiamento ingegneristico.",["race:Gnome"]="Da gnomo, potresti riconoscere nella chiave di carica un metodo familiare per attivare un automa meccanico."},sec={{t="La vendetta di un capitano",b="Gelkak Giralbero è bloccato a Rivafosca, ma non cederà ai murloc lungo la costa. Ha raccolto i pezzi per il suo piano e cerca vendetta contro la loro tribù e il loro capo. Invece di affrontare i flutti con la sciabola, l'eccentrico capitano si affida all'ingegneria. Ti dà una chiave di carica e ti chiede di occuparti del suo subordinato meccanico."},{t="L'ammutinamento del primo ufficiale",b="Il primo ufficiale di Gelkak è il Threshwackonator 4100, un golem meccanico sferragliante lasciato nelle secche a sud del relitto. La macchina promette un facile massacro dei murloc, ma non ci si può fidare. La carichi e la riporti da Gelkak. Poi ha un malfunzionamento e scambia il suo salvatore e creatore per bersagli ostili, costringendoti a combattere sulla spiaggia."}},faq={{q="Chi è il primo ufficiale di Gelkak?",a="Il primo ufficiale di Gelkak è il Threshwackonator 4100, un golem meccanico automatico sulla costa a sud del suo accampamento improvvisato.",al={"primo ufficiale","gelkak primo ufficiale","chi è il primo ufficiale"}},{q="Perché Gelkak vuole vendetta?",a="La nave di Gelkak è naufragata lungo le coste di Rivafosca. I murloc locali Greymist hanno frugato tra i rottami e sottratto parte della chiave del suo primo ufficiale. Intende usare il golem contro la loro tribù e il loro capo.",al={"perché vendetta","vendetta murloc","motivazione gelkak"}},{q="Cosa succede quando riporti indietro il Threshwackonator?",a="Usa la chiave di Gelkak per attivare il Threshwackonator, poi riportalo da lui. Scoprirai cosa accade quando raggiunge il capitano durante la scorta.",al={"attacco threshwackonator","malfunzionamento robot","perché il golem attacca"}},{q="Cosa faccio con la Chiave di Giralbero dopo aver terminato la missione?",a="La Chiave di Giralbero attiva il Threshwackonator. Una volta terminato il lavoro, la chiave non serve più.",al={"uso chiave di giralbero","conservare chiave di giralbero","posso eliminare la chiave"}},{q="Dove ha preso Gelkak il Threshwackonator?",a="Il Threshwackonator era tra il carico e l'equipaggiamento recuperati dal disastroso viaggio di Gelkak lungo le coste settentrionali di Kalimdor. Era stato progettato per fornire al suo equipaggio una potente forza meccanica.",al={"chi ha costruito il threshwackonator","origine threshwackonator"}},{q="Gelkak si arrende dopo la distruzione del golem?",a="I piani e la reazione di Gelkak diventano chiari quando riporti il suo primo ufficiale.",al={"cosa succede a gelkak","dopo la vendetta di giralbero"}}},fx={a39a7119={q="Perché Gelkak ha bisogno che tu vada a prendere il suo primo ufficiale invece di andarci lui?",a="Gelkak è bloccato sulla spiaggia di Rivafosca dopo un disastroso naufragio, ossessionato dal recupero del carico della sua nave affondata e dalla vendetta contro i murloc Grigiomanto del posto. Dopo essersi già affidato a te per recuperare sott'acqua i componenti vitali del suo primo ufficiale meccanico, è rimasto accampato vicino all'equipaggiamento recuperato e ti ordina, in qualità di membro della ciurma assoldato — o, come ti definisce lui, terricolo — di avviare il marchingegno e ricondurlo da lui sano e salvo.",al={"perché io per gelkak giralbero","perché gelkak ha bisogno di aiuto","perché gelkak non può recuperare il golem da solo"}}},fp="18,171,20.354.0,23.352.1,27.120.0,29.200.0,54.150.1,59.101.1,42.173.0,49.76.1"}
P.entries["quest:208"] = {n="Caccia grossa",s="Nella Valle di Rovotorto, la caccia di Hemet Nesingwary a King Bangalash giunge alla prova finale. Il celebre tiratore è venuto nella giungla per la grande tigre bianca.",h="Nella Valle di Rovotorto, la caccia di Hemet Nesingwary a King Bangalash giunge alla prova finale.",kw={"bangalash","bhag'thera","big game hunter","hemet nesingwary","sin'dall","valle di rovotorto","tethis","tigre bianca"},ang={["class:Hunter"]="Da cacciatore, abbattere King Bangalash dimostra a Hemet Nesingwary la tua maestria nel seguire le tracce e nella caccia."},sec={{t="La Preda del Maestro",b="Hai ucciso Sin'Dall, Bhag'thera e Tethis nelle prove stabilite dai cacciatori della spedizione. Hemet Nesingwary ora conosce la tua abilità con le armi. Pochi gli hanno mostrato abilità migliori sui campi di battaglia di Lordaeron o nel cuore della giungla.\n\nRimane una sola caccia. Abbatti King Bangalash, la grande tigre bianca che Hemet è venuto a cacciare, e dimostra che le tue abilità non hanno eguali."},{t="Una Bestia Leggendaria",b="King Bangalash ha attirato Hemet Nesingwary nella Valle di Rovotorto. La grande bestia ha più volte costretto il capo della spedizione a ritirarsi al campo sconfitto. La sua testa dimostrerebbe che la tua abilità di cacciatore non è seconda a nessuno."}},faq={{q="Chi assegna questa caccia?",a="Hemet Nesingwary assegna questa caccia al campo della sua spedizione, nella parte settentrionale della Valle di Rovotorto, dopo che hai completato le precedenti maestrie di caccia.",al={"datore di missione","chi inizia big game hunter","missione di hemet nesingwary"}},{q="Quali cacce preliminari devono essere completate per prime?",a="Per prima cosa, completa tutte e tre le cacce del campo. Uccidi Sin'Dall con Tiger Mastery, Bhag'thera con Panther Mastery e Tethis con Raptor Mastery.",al={"prerequisiti","quali missioni precedono big game hunter","requisiti per bangalash"}},{q="Perché Hemet Nesingwary vuole King Bangalash?",a="King Bangalash ha attirato Hemet nella Valle di Rovotorto. La grande tigre bianca gli è sfuggita ripetutamente e ha costretto il veterano tiratore a tornare al campo più di una volta.",al={"perché king bangalash","perché cacciare bangalash","storia di bangalash"}},{q="Che prova richiede Hemet?",a="Hemet vuole la testa di King Bangalash come prova che hai ucciso la grande tigre bianca.",al={"quale oggetto serve","obiettivo bangalash","prova dell'uccisione"}},{q="Dove dice Hemet di aver combattuto in precedenza?",a="Hemet paragona la tua abilità con le armi a ciò che ha visto sui campi di battaglia di Lordaeron e nel cuore della giungla. Dice di aver visto raramente qualcuno fare di meglio.",al={"storia bellica di hemet","passato di hemet","cacciatore di lordaeron"}}},fp="15,156,19.353.0,15.203.0,20.141.0,47.136.0,46.157.0,30.88.0,47.145.0"}
P.entries["quest:2098"] = {n="Gyromast's Retrieval",s="Gelkak Giralbero ha bisogno del tuo aiuto sulla costa di Rivafosca. Il suo primo ufficiale meccanico non può funzionare senza una chiave di carica, andata in frantumi sugli scogli. La fauna e i murloc ne hanno portato via i tre pezzi.",h="Gelkak Giralbero ha bisogno del tuo aiuto sulla costa di Rivafosca.",kw={"rivafosca","primo ufficiale","strider delle foreste","gelkak giralbero","foscanebbia","gyromast's retrieval","pirata","granchio di scogliera","trecciodonte"},ang={["profession:Engineering"]="Da ingegnere, puoi apprezzare quanto sia difficile mantenere in funzione i congegni a orologeria dopo un violento naufragio in acqua salata.",["race:Gnome"]="Da gnomo, forse riconosci l'affidamento di Gelkak sui meccanismi a orologeria al posto di compagni di bordo in carne e ossa. La sua vita da pirata è insolita tra i tuoi simili."},sec={{t="Naufrago a Rivafosca",b="A Rivafosca, Gelkak Giralbero è un pirata gnomo bloccato lontano dai Mari del Sud. Racconta che dei trecciodonti aggressivi hanno attaccato e affondato la sua nave appena al largo della costa. Il naufragio lo ha trascinato a riva tra i rottami, lasciandolo isolato e separato dalla ciurma."},{t="La chiave recuperata",b="La prima preoccupazione di Gelkak non sono le provviste o l'oro, ma il suo primo ufficiale. Il compagno ha bisogno di una chiave speciale per funzionare, ma la chiave si è spezzata in tre pezzi quando Gelkak si è schiantato sulle secche rocciose. I granchi di scogliera sulla spiaggia, gli svettanti strider delle foreste vicino ai boschi e gli spazzini murloc Foscanebbia hanno portato via i pezzi luccicanti."},{t="Un compagno peculiare",b="Gelkak parla del suo primo ufficiale con la feroce lealtà di un capitano di mare. Dice che il compagno deve tornare in condizioni di funzionare e che la chiave rotta è fondamentale per caricarlo di nuovo."}},faq={{q="Chi è Gelkak Giralbero?",a="Gelkak Giralbero è un pirata gnomo la cui nave è stata attaccata e affondata da trecciodonti predatori al largo di Rivafosca.",al={"gelkak giralbero","chi è il pirata gnomo","pirata gnomo di rivafosca"}},{q="A cosa serve la chiave?",a="La chiave serve a riattivare e caricare il primo ufficiale meccanico di Gelkak, che si è spento durante il naufragio.",al={"perché gelkak ha bisogno della chiave","scopo chiave gelkak","chiave primo ufficiale"}},{q="Dove sono finiti i tre pezzi della chiave?",a="Gli svettanti strider delle foreste hanno preso il pezzo superiore, i murloc Foscanebbia quello centrale e i granchi di scogliera quello inferiore dopo che la chiave si è rotta a riva.",al={"dove sono i pezzi della chiave","chi ha rubato la chiave","chiave rotta rivafosca"}},{q="Perché un pirata gnomo navigava vicino a Rivafosca?",a="Gelkak navigava al largo della costa settentrionale di Kalimdor in cerca di bottino, quando i trecciodonti ostili misero fine al suo viaggio.",al={"perché gelkak è a rivafosca","pirati a rivafosca"}},{q="Cosa succede dopo che la chiave è stata riassemblata?",a="Con tutti e tre i pezzi della chiave, Gelkak può caricare il suo compagno e proseguire con Gyromast's Revenge.",al={"cosa fare dopo la chiave","prosieguo recupero giralbero"}},{q="Chi sono i murloc che tengono il pezzo della chiave?",a="I murloc Foscanebbia hanno recuperato il pezzo centrale. La loro tribù vive tra i relitti delle navi affondate lungo le secche di Rivafosca.",al={"murloc di rivafosca","chiave murloc foscanebbia","murloc naufragio"}}},fx={["460afe34"]={q="Perché Gelkak Giralbero vuole che la sua chiave venga riparata?",a="Gelkak Giralbero ha fatto naufragio al largo della costa di Rivafosca quando i threshadon hanno affondato la sua nave. Bloccato e circondato da fauna ostile, ha un disperato bisogno che il suo primo ufficiale meccanico torni a funzionare, così da potersi difendere e vendicare delle creature che hanno mandato a monte il suo viaggio. Senza i tre frammenti della chiave di carica, il suo compagno a orologeria resta completamente inerte.",al={"perché gelkak vuole la chiave","motivazioni di gelkak giralbero","perché aiutare gelkak"}},["234cb20d"]={q="Perché Gelkak Giralbero ha bisogno del tuo aiuto?",a="Gelkak è un pirata naufragato, senza membri della ciurma al suo fianco e senza amici tra gli Elfi della Notte del posto. Dopo essere sopravvissuto a stento all'affondamento della sua nave e aver raggiunto la spiaggia malconcio, non è in condizioni di combattere i feroci granchi di barriera, gli Zampalunga della foresta e i murloc che si sono impossessati dei frammenti della sua chiave rotta.",al={"perché gelkak ha bisogno di me","perché gelkak non può recuperare la chiave","perché io per gelkak giralbero"}}},fp="20,189,21.241.0,17.309.0,20.172.1,23.101.0,25.113.0,41.142.0,46.104.0,42.104.1,42.122.0"}
P.entries["quest:21"] = {n="Skirmish at Echo Ridge",s="A Echo Ridge, il Maresciallo McBride ti manda in una miniera invasa dai kobold. La guarnigione teme che, se lasciati soli, rafforzeranno la loro presa.",h="A Echo Ridge, il Maresciallo McBride ti manda in una miniera invasa dai kobold.",kw={"cresta dell'eco","miniera cresta dell'eco","elwynn","kobold","lavoratore","maresciallo mcbride","mcbride","contea del nord","scaramuccia","esercito di roccavento"},ang={["class:Warrior"]="Come guerriero, affronti a distanza ravvicinata sciami di lavoratori kobold, tra i primi nemici trincerati che incontri.",["faction:Alliance"]="Come membro dell'Alleanza, aiuti a riconquistare miniere che custodiscono pietra e minerali utili a ricostruire e fortificare gli insediamenti umani dopo la guerra.",["profession:Mining"]="Come minatore, contribuisci a rendere sicura l'estrazione e la fusione dei preziosi filoni minerari in tutta la Valle della Contea del Nord.",["race:Human"]="Come umano, liberare Echo Ridge è la tua prima vera prova d'armi in difesa del regno dei tuoi antenati. Dimostri il tuo valore agli ufficiali di Roccavento."},sec={{t="Epurazione della Miniera",b="I kobold scavano in profondità nella Miniera Cresta dell'Eco, accumulano ciò che rubano e aumentano di numero. Riduci subito le loro schiere, prima che si diffondano nella Valle della Contea del Nord, tra le sue fattorie e nel suo rifugio spirituale."},{t="Una Difesa Esigua",b="McBride ha pochi soldati da poter impiegare. La guarnigione protegge i confini meridionali, mentre si vocifera di disordini in tutta Elwynn. Dimostrati affidabile a Echo Ridge e ti guadagnerai il rispetto dell'esercito, oltre a essere pronto per incarichi più impegnativi altrove nel regno."}},faq={{q="Perché i kobold stanno infestando la Miniera Cresta dell'Eco?",a="I kobold sono attratti dai tunnel ricchi di minerali e dalle cave abbandonate. Con le forze di Roccavento impegnate su troppi fronti, si addentrano in luoghi senza guardie come Echo Ridge per scavare tane, accumulare oro e trovare riparo sottoterra.",al={"perché i kobold nella miniera","kobold della cresta dell'eco","cosa fanno i kobold"}},{q="Chi ordina la scaramuccia?",a="Il Maresciallo McBride ordina la scaramuccia. Comanda le forze dell'esercito di Roccavento all'Abbazia della Contea del Nord e sovrintende alla difesa della valle con pochi uomini.",al={"chi assegna la missione della scaramuccia","ordini del maresciallo mcbride"}},{q="Qual è l'importanza strategica della Miniera Cresta dell'Eco?",a="La Miniera Cresta dell'Eco contiene pietra e minerali necessari a mantenere la Contea del Nord e contribuire alla ricostruzione di Roccavento. I kobold al confine settentrionale della Contea del Nord minacciano l'abbazia e i vigneti vicini.",al={"perché la cresta dell'eco è importante","importanza della miniera cresta dell'eco"}},{q="Dove porta questa missione in seguito?",a="Dopo aver scacciato dalla miniera i primi lavoratori kobold, il Maresciallo McBride ti manda verso Borgodoro per aiutare a difendere la regione.",al={"che missione dopo la scaramuccia","passo successivo dopo la cresta dell'eco"}},{q="Perché l'esercito di Roccavento non ripulisce la miniera di persona?",a="Roccavento ha pochi soldati a disposizione mentre difende confini lontani e respinge gli attacchi dei banditi in tutta Elwynn. McBride si affida alle nuove reclute per affrontare le minacce locali, mentre le guardie esperte presidiano le linee difensive.",al={"perché le reclute","dove sono i soldati di roccavento"}},{q="I kobold sono abbastanza intelligenti da rappresentare una minaccia militare organizzata?",a="I lavoratori kobold sono codardi e poco svegli da soli, ma diventano territoriali e aggressivi in gruppo. Se lasciati indisturbati, scavano tunnel tortuosi, tendono trappole nelle caverne e attirano parassiti più grossi e meglio armati.",al={"i kobold sono intelligenti","livello di pericolo dei kobold"}}},fx={a391cdc3={q="Perché il Maresciallo McBride vuole eliminare i koboldi nella Miniera Cresta dell'Eco?",a="Il Maresciallo McBride sa che più a lungo i koboldi restano indisturbati nella Miniera Cresta dell'Eco, più salda diventa la loro presa sulla Contea del Nord. Lasciarli in pace li invita a rafforzare ulteriormente le proprie posizioni e a minacciare la valle, rendendo la loro futura eliminazione molto più sanguinosa e mettendo a rischio la sicurezza stessa dell'Abbazia della Contea del Nord.",al={"perché uccidere i koboldi alla cresta dell'eco","motivazioni di mcbride alla cresta dell'eco","perché ripulire la miniera cresta dell'eco"}}},fp="22,134,16.190.0,14.235.0,46.210.0,24.149.0,52.176.0,34.132.0,57.211.0,66.194.0"}
P.entries["quest:210"] = {n="Krazek's Cookery",s="A Baia del Bottino, il Caporale Kaleb ha una pentola rotta da far riparare. Ti chiede di portare a Krazek la pentola meccanica che ha comprato da un mercante goblin.",h="A Baia del Bottino, il Caporale Kaleb ha una pentola rotta da far riparare.",kw={"baia del bottino","caporale kaleb","pentola a pressione","krazek","valle di rovotorto"},sec={{t="Una pentola rotta",b="Il Caporale Kaleb si occupa della maggior parte della cucina dell'accampamento. Prima di comprare una pentola meccanica da un mercante goblin a Baia del Bottino, cucinare gli richiedeva ore. La pentola gli risparmiava quel lavoro, finché non si è rotta. Ora ti chiede di portare la Pentola a Pressione di Krazek a Krazek, il goblin che può ripararla."},{t="Krazek dà un'occhiata",b="Krazek definisce la pentola un lavoro ingegnoso, anche se una molla può saltare o un ingranaggio slittare. Esaminandola, trova il caricatore a vapore arrugginito, la guarnizione a snodo incrinata e il fobulatore senza denti. Krazek può ripararla, ma le riparazioni hanno un prezzo."}},faq={{q="Chi ti manda da Krazek?",a="Il Caporale Kaleb ti manda da Krazek. Kaleb si occupa della maggior parte della cucina dell'accampamento, e la pentola meccanica che ha comprato si è rotta.",al={"chi dà krazek's cookery","chi inizia krazek cookery","missione del caporale kaleb"}},{q="Dove si trova Krazek?",a="Krazek è un mercante goblin a Baia del Bottino, dove ha venduto la pentola a Kaleb.",al={"dove si trova krazek","posizione krazek","krazek baia del bottino"}},{q="Cosa vuole che porti a Krazek il Caporale Kaleb?",a="Kaleb ti chiede di portare la Pentola a Pressione di Krazek, una pentola meccanica che si è rotta dopo avergli risparmiato molte ore di lavoro.",al={"cos'è la pentola a pressione di krazek","cosa devo portare a krazek"}},{q="Perché Kaleb ha comprato una pentola da Krazek?",a="Kaleb si occupa della maggior parte della cucina dell'accampamento, e la pentola gli ha risparmiato molte ore di lavoro, finché non si è rotta.",al={"perché una pentola meccanica","pentola di kaleb"}}},fp="16,145,12.269.0,19.247.1,24.127.0,26.71.0,48.116.0,44.99.0"}
P.entries["quest:2118"] = {n="Plagued Lands",s="La fauna di Rivafosca soccombe a una malattia insidiosa, e Tharnariun Lieveramo cerca un modo per salvarla. Ti chiede di calmare un orso del cardo rabbioso con una reliquia incantata e riportarlo vivo.",h="La fauna di Rivafosca soccombe a una malattia insidiosa, e Tharnariun Lieveramo cerca un modo per salvarla.",kw={"cleansing of the infected","rivafosca","plagued lands","rabid thistle bear","tharnariun lieveramo","speranza di tharnariun","thistle bear"},ang={["class:Druid"]="Da druido, condividi il dolore di Tharnariun mentre la natura soccombe alla corruzione. La tragica perdita dell'orso mostra quanto la malattia si sia diffusa nella regione.",["faction:Alliance"]="Da viaggiatore dell'Alleanza in transito nel nord di Kalimdor, affronti una corruzione selvaggia che preme sui confini delle terre abitate.",["race:NightElf"]="Da elfo della Notte, vedere la flora e la fauna native di Rivafosca cadere in una follia rabbiosa offende Cenarius e l'equilibrio della natura che hai giurato di proteggere."},sec={{t="Una piaga nella natura selvaggia",b="Una malattia insidiosa trasforma le bestie di Rivafosca in creature furiose e violente. Gli orsi del cardo soffrono più di tutti, e la loro furia minaccia i viaggiatori e il fragile equilibrio della costa. Le sentinelle elfo della Notte rispondono con l'acciaio, mentre i druidi cercano di comprendere la malattia e curarne la causa."},{t="Speranza di Tharnariun",b="Tharnariun Lieveramo non vuole uccidere le bestie corrotte prima di aver provato a salvarle. Ha creato una trappola chiamata Speranza di Tharnariun. Posata sul suolo della foresta, la sua luce rasserenante calma per breve tempo un orso del cardo furioso. Placato, l'orso ti segue fino all'avamposto di Tharnariun per essere studiato."},{t="Medicina tragica",b="Quando un orso infetto raggiunge l'accampamento, Tharnariun cerca di liberarlo dalla malattia con la magia rigenerante. Il suo primo tentativo finisce in tragedia. Le energie purificatrici sopraffanno l'animale indebolito, che crolla e muore. Il fallimento dimostra quanto profondamente la piaga oscura abbia attecchito."}},faq={{q="Chi assegna la missione Plagued Lands?",a="Tharnariun Lieveramo, un druido elfo della Notte di Auberdine, ti chiede aiuto. Cerca una cura per la fauna malata di Rivafosca.",al={"assegnatore missione plagued lands","missione tharnariun rivafosca","chi inizia plagued lands"}},{q="Qual è l'obiettivo di Plagued Lands?",a="Usa la Speranza di Tharnariun per intrappolare e calmare un orso del cardo rabbioso a Rivafosca, poi riportalo vivo da Tharnariun.",al={"obiettivo plagued lands","cosa fare in plagued lands","come catturare un orso a rivafosca"}},{q="Cosa succede all'orso quando lo riporti indietro?",a="Tharnariun cerca di purificare l'orso con la magia curativa, ma la malattia è troppo avanzata. Lo sforzo lo sopraffà e muore dopo il trattamento.",al={"l'orso muore","risultato cura orso tharnariun","morte orso plagued lands"}},{q="Quale oggetto usi per catturare l'orso?",a="Tharnariun ti dà la Speranza di Tharnariun, una trappola incantata. La sua luce calmante placa l'orso furioso, che ti seguirà.",al={"trappola plagued lands","oggetto speranza di tharnariun","gabbia per orsi a rivafosca"}},{q="Quale missione segue Plagued Lands?",a="Cleansing of the Infected segue Plagued Lands, poi viene Speranza di Tharnariun.",al={"prossima missione dopo plagued lands","catena plagued lands","seguito tharnariun"}},{q="Perché gli orsi del cardo sono rabbiosi?",a="Una piaga insidiosa si diffonde a Rivafosca, avvelena la fauna locale e spinge gli orsi del cardo a un'aggressività cieca.",al={"perché gli orsi sono malati a rivafosca","orsi della piaga a rivafosca","corruzione di rivafosca"}}},fx={bbb593c2={q="Perché Tharnariun Lieveramo vuole che catturi un orso cardospino rabbioso?",a="Una malattia oscura si diffonde a Rivafosca, avvolgendo le menti e i corpi della fauna locale. Gli orsi cardospino ne hanno sofferto più di tutti, trasformandosi da nobili bestie dei boschi in furie distruttive. Tharnariun Lieveramo crede di aver forse trovato una cura per il morbo, ma ha bisogno che gli venga portato direttamente un esemplare rabbioso vivo, così da poter provare il suo rimedio e fermare la corruzione prima che colpisca tutte le creature della foresta.",al={"perché catturare un orso cardospino","motivazioni di tharnariun nelle terre appestate","perché tharnariun vuole un orso"}},["1b7f183c"]={q="Cosa sono gli orsi cardospino rabbiosi e perché li prendi di mira?",a="Gli orsi cardospino sono predatori nativi delle foreste di Rivafosca, solitamente venerati come bestie nobili e valorose. Tuttavia, un contagio innaturale ha recentemente infettato i loro ranghi, gettandoli in una furia folle e deformandone la mente. Ti mandano a cercarli non per massacrarli, ma per attirare e calmare un esemplare malato con la trappola di Tharnariun, così che possa essere esaminato in sicurezza nella speranza di sviluppare un antidoto.",al={"cosa sono gli orsi cardospino rabbiosi","perché prendere di mira gli orsi cardospino rabbiosi","orso cardospino rabbioso a rivafosca"}}},fp="13,195,26.284.0,17.281.0,15.276.1,34.128.0,39.114.0,48.154.1,41.126.0,33.80.0,32.126.0"}
P.entries["quest:213"] = {n="Hostile Takeover",s="A Baia del Bottino, l’ultima mossa di Gelriz scatena l’ira del Barone Granbottino in Hostile Takeover. Gelriz ha estromesso i magnati nominati dai principi mercanti e ora punta al pirata più famigerato di tutti. Kebok ti manda a rubare strani cristalli blu che i geologi della S.P.R. & Co. hanno trovato vicino al Lago Nazferiti.",h="A Baia del Bottino, l’ultima mossa di Gelriz scatena l’ira del Barone Granbottino in Hostile Takeover.",kw={"baia del bottino","gelriz","gigglefont","kebok","lago nazferiti","barone granbottino","cristallo burattato","s.p.r. & co."},sec={{t="Questione d'affari",b="Il Barone Granbottino autorizza Kebok a rispondere all’insulto come meglio crede. Kebok sceglie il furto e punta alle strane pietre blu che le squadre della Venture Company Mining hanno riportato alla luce."},{t="Il deposito dei geologi",b="I geologi della S.P.R. & Co. al lavoro nei dintorni del Lago Nazferiti si sono interessati molto agli insoliti cristalli. Kebok vuole che tu gli riporti otto campioni a Baia del Bottino. Non gli importa come li ottieni, purché finiscano nelle sue mani."},{t="Una scoperta burrascosa",b="I cristalli riportati sono stati sottoposti a burattatura, segno che la S.P.R. & Co. intende usarli come combustibile o catalizzatore industriale. Kebok intende inviare campioni al Capo Chimico Gigglefont per uno studio più approfondito."}},faq={{q="Chi assegna la missione Hostile Takeover?",a="Kebok, a Baia del Bottino nella Valle di Rovotorto, ti affida questo incarico per conto del Barone Granbottino.",al={"datore di missione hostile takeover","chi inizia hostile takeover","missione di kebok"}},{q="Perché il Barone Granbottino è arrabbiato con Gelriz?",a="Gelriz ha estromesso i magnati nominati dai principi mercanti e ora ha puntato al pirata più famigerato. Il Barone Granbottino non lo tollererà.",al={"perché revilgaz è arrabbiato","conflitto tra gelriz e revilgaz","perché kebok vuole i cristalli"}},{q="Dove si trovano i cristalli?",a="I geologi della S.P.R. & Co. al lavoro nei dintorni del Lago Nazferiti trasportano i cristalli.",al={"dove trovare cristalli burattati","posizione cristallo burattato","cristalli lago nazferiti"}}},fp="16,308,20.175.0,21.243.0,20.197.1,37.96.0,40.147.0,31.76.0"}
P.entries["quest:2138"] = {n="Cleansing of the Infected",s="A Rivafosca, Tharnariun Lieveramo ti chiede di fermare gli orsi cardo infetti. Il suo tentativo di purificarne uno è fallito e teme che le bestie rabbiose feriscano altre creature e diffondano la malattia.",h="A Rivafosca, Tharnariun Lieveramo ti chiede di fermare gli orsi cardo infetti.",kw={"auberdine","cleansing","rivafosca","infected","orso cardo rabbioso","tharnariun","lieveramo"},ang={["class:Druid"]="Da druido, l'ordine di Tharnariun potrebbe addolorarti. È un gesto di pietà e di cura per la foresta, non una normale battuta di caccia.",["class:Hunter"]="Da cacciatore, sai che abbattere i predatori malati può proteggere l'intero ecosistema, anche quando la causa resta ignota.",["race:NightElf"]="Da kaldorei, porti il peso di ordinare l'uccisione di bestie corrotte. Dalla guerra, la malattia si è spinta in profondità nella tua terra ancestrale."},sec={{t="Un'amara necessità",b="Tharnariun Lieveramo ha cercato una cura per la malattia che colpisce la fauna selvatica di Rivafosca. Ha provato a purificare un orso catturato, ma gli orsi cardo sono ancora malati e violenti. Perciò ti chiede di abbatterli prima che sbranino altre creature o diffondano la malattia ancora più a fondo negli antichi boschi."},{t="Contenere la natura selvaggia",b="Tharnariun ti chiede di uccidere venti orsi rabbiosi, pur sapendo che questo non curerà la piaga. Le uccisioni fanno guadagnare tempo ai difensori di Auberdine. Finché qualcuno non troverà e reciderà la fonte della corruzione della foresta, l'insediamento non ha altro modo per fermare i branchi aggressivi e il pericolo che rappresentano."}},faq={{q="Perché Tharnariun vuole che gli orsi cardo vengano uccisi invece che curati?",a="Tharnariun ha provato a purificare un orso catturato, ma la cura è fallita e la bestia è morta. Ora gli orsi malati minacciano altre creature, quindi ucciderli è l'ultima risorsa per rallentare la diffusione della malattia.",al={"perché uccidere gli orsi","perché non curare gli orsi","missione orso di tharnariun"}},{q="Chi è Tharnariun Lieveramo?",a="Tharnariun è un custode Elfo della Notte ad Auberdine. Studia le malattie che colpiscono le piante e gli animali di Rivafosca e lavora per preservare l'equilibrio della natura contro la corruzione dilagante.",al={"ruolo di tharnariun","chi assegna cleansing of the infected"}},{q="Uccidere gli orsi rabbiosi pone davvero fine alla piaga?",a="No. Tharnariun avverte che uccidere gli orsi rabbiosi non fermerà la piaga. Rallentando la diffusione dell'infezione e della violenza, dà alla foresta e agli abitanti di Auberdine più tempo.",al={"questo risolve la situazione a rivafosca","la piaga è curata"}},{q="Cosa succede dopo Cleansing of the Infected?",a="Dopo che torni a riferire, Tharnariun ti chiede di prepararti ad altro spargimento di sangue e ti offre Speranza di Tharnariun, che prosegue gli sforzi per affrontare la fauna selvatica corrotta.",al={"missione successiva dopo cleansing","cosa segue cleansing of the infected"}},{q="Dove si trovano gli orsi cardo rabbiosi?",a="Gli orsi cardo rabbiosi vagano nelle foreste costiere e interne della Rivafosca centrale, tra i pini nebbiosi a sud e a est di Auberdine.",al={"posizione orso cardo rabbioso","dove si trovano gli orsi a rivafosca"}},{q="Cosa ha causato la rabbia negli orsi cardo?",a="Una misteriosa contaminazione che si diffonde nei boschi del nord di Kalimdor ha corrotto gli orsi. Ha trasformato la fauna pacifica in bestie frenetiche e aggressive, che il tentativo di cura di Tharnariun non può guarire.",al={"perché gli orsi sono malati","malattia degli orsi a rivafosca"}}},fx={acd0862d={q="Cosa sono gli orsi cardospino rabbiosi e perché vanno uccisi?",a="Gli orsi cardospino sono predatori nativi delle foreste, che di solito vivono in armonia con le terre selvagge di Rivafosca. Tuttavia, una piaga innaturale che si diffonde nei boschi ne ha resi rabbiosi e violentemente deliranti molti esemplari. Nella loro follia corrotta, queste bestie malate attaccano gli altri animali, minacciano i viaggiatori nei pressi di Auberdine e devastano l'ecosistema boschivo. Poiché i tentativi di curarli sono falliti, abbatterli è l'unico modo per contenere la devastazione.",al={"orsi cardospino rabbiosi","chi sono gli orsi cardospino rabbiosi","perché uccidere gli orsi cardospino rabbiosi"}}},fp="25,196,18.299.0,20.306.1,67.199.0,29.187.0,53.174.0,43.165.0,40.128.0,42.197.0"}
P.entries["quest:2139"] = {n="Speranza di Tharnariun",s="Ad Auberdine, la lotta di Tharnariun Lieveramo contro la malattia della fauna volge al peggio. I viandanti hanno abbattuto bestie infette in tutta Rivafosca, e ora lui manda un campione dell'Alleanza a caccia della rabbiosa Madre della Tana, a nord-est della città.",h="Ad Auberdine, la lotta di Tharnariun Lieveramo contro la malattia della fauna volge al peggio.",kw={"auberdine","bashal'aran","cleansing of the infected","rivafosca","madre della tana","orso cardo rabbioso","tharnariun lieveramo","speranza di tharnariun"},ang={["class:Druid"]="Come druido, nutri una profonda venerazione spirituale per gli orsi grazie agli insegnamenti di Ursoc. Uccidere una Madre della Tana corrotta ti ricorda il delicato equilibrio della natura e le tragedie della corruzione.",["class:Hunter"]="Come cacciatore, comprendi la tragedia di un predatore al vertice della catena alimentare reso folle dalla malattia. Sai che abbattere una bestia infetta può essere il più sincero atto di misericordia.",["faction:Alliance"]="Come membro dell'Alleanza, contribuisci a proteggere Auberdine e a rafforzare la presenza dell'Alleanza lungo la costa settentrionale del Kalimdor. Difendi le terre degli Elfi della Notte dalle crescenti minacce della natura selvaggia.",["race:NightElf"]="Per gli Elfi della Notte, uccidere le bestie dei boschi, soprattutto un'orsa matriarca, viola la loro profonda venerazione per la natura. È un dovere amaro e doloroso."},sec={{t="Una tragica necessità",b="Dalla Terza Guerra, una malattia innaturale rende rabbiose le creature selvatiche di Rivafosca. Tharnariun Lieveramo è di stanza ad Auberdine, dove ha chiesto ai viandanti di abbattere le bestie infette e alleviare le sofferenze della foresta. Eppure, uccidere gli orsi cardo rabbiosi cura solo un sintomo. Tharnariun decide che la fonte tra gli orsi locali va eliminata: la loro matriarca, la Madre della Tana."},{t="La Madre della Tana",b="La Madre della Tana si annida in una caverna a nord-est di Auberdine, vicino alle antiche rovine di Bashal'aran. Un tempo guardiana della fauna boschiva, fu consumata dal morbo che si diffondeva nel Kalimdor settentrionale. Continuò a partorire e allevare cucciolate di piccoli rabbiosi. Gli eroi dell'Alleanza la stanarono nella sua tana, ponendo fine al suo tormento e arginando l'ondata di orsi frenetici che infestavano la strada costiera."},{t="La cruda realtà di Kalimdor",b="Dopo la morte della Madre della Tana, Tharnariun esprime profonda gratitudine, ma le sue parole sono velate di malinconia. Per i kaldorei, levare le armi contro le creature dei boschi è straziante. Forze oscure premono contro la loro nuova casa, e molti disperano o cercano riparo. I difensori di Auberdine accettano il pesante fardello di proteggere la loro natura selvaggia."}},faq={{q="Chi è Tharnariun Lieveramo?",a="Tharnariun Lieveramo è un custode Elfo della Notte di stanza ad Auberdine. Sconvolto dalla corruzione e dalla follia che stravolgono la fauna di Rivafosca, dirige le ricerche e il monitoraggio degli animali sofferenti, per poi porre fine alle loro pene.",al={"tharnariun","chi assegna speranza di tharnariun","lieveramo auberdine"}},{q="Dove si trova la Madre della Tana?",a="La Madre della Tana vive in una caverna tra le colline a nord-est di Auberdine, appena a est delle rovine di Bashal'aran.",al={"dove si trova la madre della tana","posizione grotta madre della tana","trovare la madre della tana"}},{q="Perché la Madre della Tana deve essere uccisa invece di essere curata?",a="Il morbo che devasta la fauna di Rivafosca si impadronisce delle bestie e le spinge a furiose violenze. Senza una cura immediata e con la Madre della Tana che alleva cuccioli rabbiosi, Tharnariun decide che ucciderla è l'unico modo per impedire alla malattia di diffondersi ancora.",al={"la madre della tana può essere salvata","perché uccidere la madre della tana","curare la madre della tana"}},{q="Quali missioni portano a Speranza di Tharnariun?",a="Tre parti conducono a Speranza di Tharnariun. La serie comincia con \"Terre infestate\", prosegue con \"Purificazione degli infetti\" e termina con \"Speranza di Tharnariun\".",al={"prerequisiti per speranza di tharnariun","catena di missioni tharnariun"}},{q="Cosa fa ammalare gli animali di Rivafosca?",a="Tharnariun non indica una causa. Sa solo che una malattia si sta diffondendo in tutta Rivafosca, colpendo la mente e il corpo di chi ne è affetto. Gli orsi cardo sono i più colpiti.",al={"perché gli orsi sono rabbiosi a rivafosca","causa della peste animale a rivafosca","cosa ha corrotto gli orsi"}},{q="Perché Tharnariun menziona persone che scappano verso terre fortificate?",a="Auberdine è un avamposto costiero esposto, assediato da fantasmi, fauna corrotta e creature ostili. La civiltà degli Elfi della Notte lotta per ricostruirsi dopo l'invasione della Legione Infuocata, e alcuni abitanti si sentono sopraffatti e si nascondono o si ritirano verso bastioni dell'Alleanza più sicuri.",al={"fuggire da auberdine","terre fortificate dell'alleanza"}}},fx={f873ab28={q="Chi è la Madre della Tana?",a="La Madre della Tana è un enorme orso corrotto che vive in una caverna a nord-est, vicino alle rovine di Bashal'aran. È la fonte da cui nascono, o in cui trovano rifugio, gli orsi cardospino rabbiosi che infestano la regione. Ucciderla interrompe l'afflusso delle bestie malate che minacciano Auberdine.",al={"cos'è la madre della tana","chi è la madre della tana","madre della tana a rivafosca"}}},fp="17,235,18.381.0,14.390.1,28.324.0,29.234.0,32.107.0,51.259.0,41.159.0,45.176.0,63.268.0"}
P.entries["quest:214"] = {n="Red Silk Bandanas",s="Nelle Miniere della Morte, l'Esploratrice Riell manda la Milizia Popolare a recuperare le Red Silk Bandanas. La loro trama pregiata contraddistingue i capi dei Defias che dirigono la rivolta nelle Marche Occidentali.",h="Nelle Miniere della Morte, l'Esploratrice Riell manda la Milizia Popolare a recuperare le Red Silk Bandanas.",kw={"miniere della morte","fratellanza dei defias","rivoluna","the people's militia","red silk bandanas","esploratrice riell","vancleef","marche occidentali"},ang={["class:Rogue"]="Da furfante, sai che la seta rossa contraddistingue veterani tagliagole e cospiratori clandestini, secondo le tecniche malavitose dei Defias.",["faction:Alliance"]="Da alleato dell'Alleanza, sai che ogni ufficiale abbattuto nelle Miniere della Morte è uno in meno a mantenere il comando della Fratellanza nel granaio di Roccavento.",["profession:Tailoring"]="Da sarto, sai che la seta rossa pregiata costa troppo per i banditi comuni. Il suo uso dimostra quanto siano ben equipaggiati e finanziati i capi della Fratellanza."},sec={{t="Una gerarchia in stoffa",b="L'Esploratrice Riell e la Milizia Popolare hanno scoperto che nella Fratellanza dei Defias il tessuto indica il rango. Nelle Marche Occidentali, comuni borseggiatori e banditi si legano stoffa rossa grezza sul viso. I cospiratori di alto rango e gli operativi della cerchia interna indossano seta rossa pregiata. Recuperare le loro bandane colpisce gli ufficiali esperti che coordinano la rivolta di Edwin VanCleef."},{t="Colpire il cuore",b="I fuorilegge di alto rango si radunano nelle profondità delle Miniere della Morte, sotto Rivoluna. Sentinelle ed esploratori fuori da Guardiacolle si affidano a campioni indipendenti per addentrarsi nei tunnel contesi. Ogni bandana di seta recuperata significa un luogotenente in meno a organizzare imboscate, sorvegliare depositi di armi o imporre il dominio di VanCleef nelle Marche Occidentali."}},faq={{q="Perché i Defias indossano bandane rosse?",a="I Defias indossano bandane rosse per nascondere il volto e mostrare fedeltà alla ribellione di Edwin VanCleef. Il tessuto contraddistingue la loro Fratellanza nei territori di Roccavento.",al={"significato maschera defias","perché maschere rosse","uniforme defias"}},{q="Cosa rende le Red Silk Bandanas speciali rispetto alle bandane normali?",a="L'Esploratrice Riell dice che il tessuto indica il rango nella Fratellanza. I comuni teppisti di strada indossano stoffa grezza ed economica, mentre veterani, ufficiali e luogotenenti fidati portano seta rossa.",al={"perché seta rossa","seta contro stoffa defias","differenza bandana di seta"}},{q="Chi è l'Esploratrice Riell?",a="L'Esploratrice Riell serve la Milizia Popolare nelle Marche Occidentali. L'operativa segue gli spostamenti dei Defias e guida gli avventurieri contro i loro covi nei pressi delle Miniere della Morte.",al={"esploratrice riell marche occidentali","chi assegna la missione red silk bandanas"}},{q="Dove si trovano i Defias che indossano bandane di seta?",a="I Defias con bandane di seta si radunano dentro e intorno alle Miniere della Morte, sotto Rivoluna. Le forze di alto rango di Edwin VanCleef dirigono le operazioni sotterranee.",al={"dove trovare bandane di seta","posizione bandana di seta miniere della morte"}},{q="Cos'è la The People's Militia?",a="La Milizia Popolare è una forza di difesa volontaria fondata da Gryan Stoutmantle e dai contadini delle Marche Occidentali, messi alle strette. Proteggono le loro terre dopo che l'esercito di Roccavento non è riuscito a fornire guarnigioni sufficienti.",al={"chi è la the people's militia","the people's militia marche occidentali"}},{q="Queste bandane hanno qualche utilità oltre a provare un'uccisione?",a="Per la Milizia Popolare, le bandane dimostrano che i fuorilegge di alto rango sono stati eliminati. Ognuna indebolisce la catena di comando della Fratellanza.",al={"si può indossare la bandana di seta rossa","a cosa servono le bandane"}}},fx={["09c03d28"]={q="Perché l'Esploratrice Riell vuole che vengano raccolte le bandane dei Defias?",a="L'Esploratrice Riell vuole infliggere un colpo decisivo ai capi della Fratellanza dei Defias in nome della The People's Militia. La milizia sa che le bandane di seta contraddistinguono gli ufficiali di alto rango, non i semplici teppisti. Eliminando queste figure chiave e chiedendo le loro bandane come prova, Riell spera di distruggere la struttura di comando della fratellanza e riconquistare finalmente le Marche Occidentali per la sua gente.",al={"perché l'esploratrice riell vuole le bandane","motivazioni dell'esploratrice riell","perché raccogliere le bandane di seta rossa"}},["762e9a74"]={q="Contro chi ti mandano?",a="Stai dando la caccia agli ufficiali d'élite e ai veterani della Fratellanza dei Defias stanziati nella roccaforte di Edwin VanCleef, all'interno delle Miniere della Morte e nei dintorni. A differenza dei rozzi tagliagole che vagano per le fattorie delle Marche Occidentali, questi membri di alto rango sorvegliano la base operativa della fratellanza, dirigono i lavori segreti nelle profondità sotto Rivoluna e comandano le attività del sindacato in tutta la regione.",al={"chi dobbiamo cacciare","bersagli delle bandane di seta rossa","chi lascia cadere le bandane di seta"}},["966e78fe"]={q="Perché l'Esploratrice Riell si rivolge a te invece che alle guardie di Roccavento?",a="Roccavento ha praticamente abbandonato le Marche Occidentali e offre poco o nessun sostegno militare, mentre la Casata dei Nobili ignora la crisi crescente. La The People's Militia locale è allo stremo e non ha uomini, addestramento né risorse sufficienti per sferrare un assalto frontale contro i bastioni criminali fortificati. Riell e gli altri esploratori devono affidarsi ad avventurieri capaci per infiltrarsi nelle pericolose Miniere della Morte e affrontare direttamente i capi della fratellanza.",al={"perché non l'esercito di roccavento","perché mandare un avventuriero","perché hanno bisogno di me"}}},fp="17,159,20.356.0,17.317.0,36.165.0,70.169.0,19.162.0,51.151.0,29.197.0,57.146.0"}
P.entries["quest:215"] = {n="Jungle Secrets",s="Nella parte settentrionale della Valle di Rovotorto, il Soldato Thorsen spiega perché si è riunito agli uomini di Kurzen dopo che lo hai salvato da un'imboscata. Ti manda al Campo dei Ribelli perché il suo comandante confermi il motivo.",h="Nella parte settentrionale della Valle di Rovotorto, il Soldato Thorsen spiega perché si è riunito agli...",kw={"doren","kurzen","campo dei ribelli","rovotorto","thorsen","traditore","yohwa"},ang={["faction:Alliance"]="Il Campo dei Ribelli dipende dalle informazioni urgenti che il Soldato Thorsen spera di riportare dagli uomini di Kurzen."},sec={{t="Un'operazione segreta",b="Il Soldato Thorsen dice che la situazione sembra grave e ti chiede di ascoltarlo. Il Tenente Doren gli ha ordinato di arruolarsi di nuovo tra gli uomini del Colonnello Kurzen e raccogliere informazioni disperatamente necessarie per la ribellione. Thorsen sperava così di entrare nell'Insediamento di Kurzen, ma le cose sono presto andate male. Ti manda da Doren al Campo dei Ribelli per avere conferma e ti implora di mantenere il segreto."},{t="Sospetti al campo",b="Il Tenente Doren conferma che il Soldato Thorsen ha agito ai suoi ordini. Un tempo i ribelli erano ferocemente leali a Kurzen, ma la corruzione ha trasformato quella lealtà in rabbia. Se si venisse a sapere dei rapporti di Thorsen, i suoi stessi compagni gli taglierebbero la gola. Solo Doren, il Sergente Yohwa e Thorsen avrebbero dovuto conoscere il piano. L'imboscata fallita indica la presenza di un traditore sconosciuto tra i ribelli."}},faq={{q="Perché il Soldato Thorsen si stava incontrando con le forze del Colonnello Kurzen?",a="Il Tenente Doren ha ordinato al Soldato Thorsen di arruolarsi di nuovo tra gli uomini del Colonnello Kurzen e raccogliere informazioni militari vitali per i ribelli.",al={"perché thorsen ha incontrato kurzen","thorsen è un traditore","perché thorsen era fuori dal campo"}},{q="Dove ti manda il Soldato Thorsen?",a="Il Soldato Thorsen ti manda dal Tenente Doren al Campo dei Ribelli, nella parte settentrionale della Valle di Rovotorto, dove il suo comandante può confermare la storia.",al={"dove devo andare","consegna missione thorsen","dove si trova doren"}},{q="Perché Thorsen insiste sulla segretezza?",a="Un tempo i ribelli erano ferocemente leali al Colonnello Kurzen. Se scoprissero che Thorsen ha avuto rapporti con gli uomini di Kurzen, potrebbero ucciderlo nel sonno.",al={"perché mantenere il segreto","perché missione segreta"}},{q="Cosa succede dopo aver fatto rapporto al Tenente Doren?",a="Dopo aver parlato con il Tenente Doren, la tua ricerca ti conduce da Bookie Herod.",al={"prossima missione","cosa segue jungle secrets"}}},fp="14,196,20.388.0,18.372.1,53.135.0,36.138.0,35.141.0,47.73.0"}
P.entries["quest:2158"] = {n="Riposo e relax",s="Da Contea del Nord, i nuovi avventurieri dell’Alleanza seguono la strada verso sud fino a Borgodoro, in cerca di riposo e accoglienza. Alla Locanda del Fiero Leone, il Locandiere Farley offre cibo, bevande e un posto accanto al focolare.",h="Da Contea del Nord, i nuovi avventurieri dell’Alleanza seguono la strada verso sud fino a Borgodoro, in cerca...",kw={"taverna dell’alleanza","foresta di elwynn","borgodoro","locandiere farley","locanda del fiero leone","contea del nord","riposo e relax"},ang={["faction:Alliance"]="La Locanda del Fiero Leone è un rifugio e un punto d’incontro per i viaggiatori dell’Alleanza nella Foresta di Elwynn.",["race:Human"]="Da recluta umana in partenza dalla Valle della Contea del Nord, segui la strada verso sud fino a Borgodoro. Qui il Locandiere Farley offre un’ospitalità familiare vicino a Roccavento."},sec={{t="Un rifugio lungo la strada",b="I viaggiatori stanchi lasciano Contea del Nord e seguono la strada verso sud fino a Borgodoro. La strada conduce direttamente alla Locanda del Fiero Leone, dove il Locandiere Farley accoglie chi parte alla scoperta della Foresta di Elwynn. Per i nuovi avventurieri, la locanda è il primo avamposto importante oltre l’Abbazia, con riparo e pasti caldi."},{t="Il focolare e l'ospitalità di Farley",b="Il Locandiere Farley accoglie chi è stanco e infreddolito. Menziona la tua referenza e potrai accomodarti accanto al fuoco acceso per un pasto caldo, una birra robusta e un po’ di riposo prima di proseguire attraverso Elwynn."}},faq={{q="Dove posso trovare la Locanda del Fiero Leone?",a="La Locanda del Fiero Leone si trova a Borgodoro, a sud della Valle della Contea del Nord, lungo la strada principale. Segui la strada verso sud fino alla taverna nel cuore della città.",al={"dove si trova la locanda del fiero leone","come arrivare alla locanda del fiero leone","trovare la locanda del fiero leone"}},{q="Chi è il Locandiere Farley?",a="Il Locandiere Farley gestisce la Locanda del Fiero Leone a Borgodoro. È un caro amico dei suoi contatti a Contea del Nord e accoglie gli avventurieri stanchi con cibo, bevande e un focolare caldo.",al={"chi è il locandiere farley","farley locanda del fiero leone"}},{q="Qual è lo scopo di Riposo e relax?",a="Viaggi da Contea del Nord a Borgodoro, dove il Locandiere Farley offre cibo, bevande e alloggio alla Locanda del Fiero Leone.",al={"qual è lo scopo di questa missione","perché andare alla locanda del fiero leone"}},{q="Il Locandiere Farley offre davvero cibo e bevande a prezzo scontato?",a="Menziona la tua referenza al Locandiere Farley e potrai chiedere uno sconto su cibo e bevande mentre ti riprendi dal viaggio.",al={"sconto alla locanda del fiero leone","cibo più economico da farley"}},{q="Perché il riposo è importante per gli avventurieri in viaggio?",a="Viaggiare per Elwynn è difficile e pericoloso. In una locanda puoi ripararti dalle terre selvagge, scaldarti accanto al fuoco, riprenderti e fare provviste prima di ripartire.",al={"perché gli avventurieri hanno bisogno di riposo","storia di riposo e relax"}},{q="Qual è il motto della Locanda del Fiero Leone?",a="Il Locandiere Farley dice che il motto della Locanda del Fiero Leone è «Riposo e relax per chi è stanco e infreddolito». Gli ospiti stanchi trovano conforto accanto al suo focolare.",al={"qual è il motto della locanda del fiero leone","slogan della locanda del fiero leone"}}},fp="19,187,19.287.0,31.188.0,38.145.0,24.165.0,43.120.0,61.127.0,48.176.0,42.144.0"}
P.entries["quest:2159"] = {n="Pacco per Dolanaar",s="A Vallombra, i viaggiatori portano erbe a sud, fino a Dolanaar. Porthannius è impegnato con i druidi, mentre la strada oltre la radura riparata si apre davanti ai giovani avventurieri.",h="A Vallombra, i viaggiatori portano erbe a sud, fino a Dolanaar.",kw={"consegna","dolanaar","pacco per dolanaar","erbe","locandiere keldamyr","elfo della notte","porthannius","vallombra","teldrassil"},ang={["class:Druid"]="Da druido, sai che Porthannius è impegnato con i druidi di Vallombra e con i doveri spirituali e gli squilibri naturali che interessano il Circolo Cenariano tra i rami di Teldrassil.",["profession:Herbalism"]="Da erborista, sai che le erbe grezze raccolte nel terreno di Vallombra sono importanti per i guaritori, i cuochi e i custodi di Dolanaar.",["race:NightElf"]="Da elfo della notte, lasci la culla protetta di Aldrassil e assumi responsabilità più ampie nella difesa di Teldrassil."},sec={{t="Un messaggero per Vallombra",b="Porthannius chiede ai viaggiatori diretti a sud da Vallombra di portare erbe appena raccolte lungo il sentiero nella foresta. Gli affari urgenti con i druidi che si prendono cura della radura gli impediscono di fare il viaggio di persona. Il pacco procede verso sud mentre i giovani avventurieri lasciano il Cortile d'Addestramento e si avventurano nelle distese più ampie di Teldrassil."},{t="La strada per Dolanaar",b="La strada a sud da Vallombra raggiunge Dolanaar, uno dei principali insediamenti degli elfi della notte sui grandi rami di Teldrassil. Il Locandiere Keldamyr si occupa di riposo, ospitalità e rifornimenti per viandanti, sentinelle e druidi. Quando riceve le erbe di Porthannius, esorta i giovani avventurieri a riposare mente e spirito prima di affrontare la corruzione che si diffonde nell'albero del mondo."}},faq={{q="Chi è Porthannius?",a="Porthannius è un elfo della notte che vive a Vallombra, la radura iniziale di Teldrassil. Collabora con i druidi del luogo e chiede ai viaggiatori che lasciano la radura di portare rifornimenti a sud per lui.",al={"porthannius","chi assegna pacco per dolanaar","datore di missione porthannius"}},{q="Perché Porthannius non può consegnare le erbe di persona?",a="Gli affari urgenti con i druidi di Vallombra tengono Porthannius impegnato nella valle riparata, così dipende dagli avventurieri di passaggio per portare le erbe a sud.",al={"perché porthannius ha bisogno di aiuto","perché porthannius non può andare"}},{q="Cosa c'è dentro il pacco?",a="Il pacco contiene erbe raccolte a Vallombra, destinate alla locanda di Dolanaar.",al={"contenuto del pacco per dolanaar","cosa sono le erbe"}},{q="Chi è il Locandiere Keldamyr?",a="Il Locandiere Keldamyr gestisce la locanda di Dolanaar e offre ospitalità, alloggio e pietre del focolare ai viaggiatori. Coordina anche gli scambi commerciali e di rifornimenti con gli altri insediamenti di Teldrassil.",al={"keldamyr","locandiere di dolanaar","chi riceve le erbe"}},{q="Dove si trova Dolanaar?",a="Dolanaar si trova a sud di Vallombra. La strada principale dall'uscita della radura conduce i viaggiatori direttamente al centro del villaggio.",al={"dove si trova dolanaar","posizione di dolanaar","indicazioni per dolanaar"}},{q="Perché questa consegna è importante per i giovani avventurieri?",a="La consegna porta i giovani avventurieri oltre Vallombra e fa loro conoscere la locanda, gli addestratori e i fornitori di servizi di Dolanaar.",al={"significato della consegna","perché consegnare erbe"}}},fx={e1815add={q="Perché Porthannius ha bisogno che questo pacco venga consegnato a Dolanaar?",a="Porthannius ha preparato un prezioso fascio di erbe fresche raccolte a Vallombra, che il Locandiere Keldamyr aspetta a Dolanaar. Tuttavia, gli impegni urgenti con i druidi locali impediscono a Porthannius di mettersi in viaggio. Per fare in modo che il locandiere riceva queste scorte necessarie senza ritardi, si affida a un viaggiatore di passaggio diretto fuori da Teldrassil.",al={"motivazioni della consegna di porthannius","perché mandare erbe a dolanaar","scopo del pacco per dolanaar"}}},fp="17,164,26.324.0,20.373.0,19.181.0,48.153.0,27.78.0,26.190.0,26.115.0,53.126.0"}
P.entries["quest:2160"] = {n="Supplies to Tannok",s="Hands Giraruota ha delle provviste della locanda per Tannok Gelmartello, ma i trogg hanno reso insicuro il passo. Ti chiede di portare la cassa dalla Valle Crestafredda alla Distilleria Birratuono a Kharanos.",h="Hands Giraruota ha delle provviste della locanda per Tannok Gelmartello, ma i trogg hanno reso insicuro il...",kw={"forgiamara","passo crestafredda","hands giraruota","kharanos","supplies to tannok","tannok gelmartello","thunderbrew","trogg"},ang={["faction:Alliance"]="Come membro dell'Alleanza, ripristinare gli scambi tra avamposti isolati aiuta a mantenere attive le linee di rifornimento interne di Forgiardente, nonostante le incursioni dei trogg.",["race:Dwarf"]="Come nano, portare provviste da Forgiamara a Kharanos ti conduce oltre la valle riparata e al servizio di Forgiardente.",["race:Gnome"]="Come gnomo, aiutare Hands Giraruota dimostra la collaborazione tra gli esuli di Gnomeregan e i loro ospiti nani a Dun Morogh."},sec={{t="Una valle bloccata",b="I trogg hanno invaso il Passo Crestafredda, rendendo pericoloso il percorso in uscita dalla Valle Crestafredda. I Montanari sono impegnati a difendere insediamenti e fortificazioni, perciò le scorte possono subire giorni di ritardo. La cassa della locanda non ha un percorso sicuro."},{t="Hands e l'assistente del locandiere",b="Hands Giraruota è uno gnomo inventore in attesa al passo, ma non può trasportare la cassa senza rischi. Puoi portare le provviste a Tannok Gelmartello, l'assistente della locanda Thunderbrew a Kharanos."},{t="Un focolare accogliente a Kharanos",b="Tannok Gelmartello riceve le provviste a Kharanos. Dice che da Forgiamara arrivano poche notizie da quando i trogg hanno interrotto i viaggi. Senza la consegna, le comunicazioni e gli scambi tra le due comunità naniche isolate restano precari."}},faq={{q="Chi è Hands Giraruota?",a="Hands Giraruota è uno gnomo inventore in attesa all'imboccatura del Passo Crestafredda, nella Valle Crestafredda. Chiede ai viaggiatori di portare merci a Kharanos, perché non può attraversare il passo da solo senza correre rischi.",al={"hands giraruota","datore di missione","chi consegna le provviste a tannok"}},{q="Chi è Tannok Gelmartello?",a="Tannok Gelmartello è l'assistente della Distilleria Birratuono a Kharanos. Riceve provviste inviate da luoghi come Forgiamara.",al={"tannok","tannok gelmartello","assistente locandiere kharanos"}},{q="Perché Hands non può consegnare le provviste da solo?",a="I trogg hanno invaso il passo tra la Valle Crestafredda e Kharanos, rendendo pericolosi i viaggi. Anche le scorte dei Montanari subiscono ritardi, perché sono impegnati a difendere insediamenti e fortificazioni.",al={"perché hands non può consegnare","perché serve un avventuriero","perché il passo è pericoloso"}},{q="Dov'è situata la locanda di Kharanos?",a="La Distilleria Birratuono si trova al centro di Kharanos, lungo la strada principale verso est, in direzione di Forgiardente. Tannok Gelmartello è all'interno.",al={"dove si trova tannok","posizione della distilleria birratuono","posizione locanda kharanos"}},{q="Cosa c'è dentro la Cassa di Scorte della Locanda?",a="La cassa contiene rifornimenti da taverna e provviste raccolte a Forgiamara per la locanda Thunderbrew a Kharanos.",al={"cosa contiene la cassa","cassa di scorte della locanda"}},{q="Perché le comunicazioni tra Forgiamara e Kharanos sono interrotte?",a="I trogg provenienti da gallerie sotterranee hanno invaso il Passo Crestafredda. La loro presenza ha interrotto il passaggio a piedi e le spedizioni regolari tra la Valle Crestafredda e il resto di Dun Morogh.",al={"perché scarse notizie da forgiamara","problema trogg passo"}}},fx={["6d15a4f4"]={q="Perché Hands Giraruota vuole che le scorte vengano consegnate a Kharanos?",a="Hands Giraruota aveva promesso provviste essenziali a Tannok Gelmartello, l'assistente della locanda di Kharanos, ma gli attacchi dei trogg hanno interrotto i viaggi attraverso il passo che esce dalla Valle Crestafredda. Le spedizioni regolari sono bloccate e le scorte dei Montanari arriveranno solo tra giorni; Tannok è costretto ad aspettare, preoccupato e con le provviste in esaurimento. Hands vuole mantenere la promessa e assicurarsi che la vivace Distilleria Birratuono e la locanda siano rifornite per i viaggiatori stanchi della strada.",al={"perché mandare scorte a tannok","motivazioni di hands giraruota","perché consegnare la cassa di scorte della locanda"}}},fp="18,195,18.238.0,35.206.0,30.232.0,28.192.0,26.136.0,45.193.0,37.129.0,41.104.0,59.178.0"}
P.entries["quest:2161"] = {n="A Peon's Burden",s="Ukor aspetta fuori dalla Valle delle Sfide con provviste che non riesce a riportare a casa. Le reclute nel canyon rosso hanno rifiutato il suo cibo, così chiede ai viaggiatori di riportarlo a Tranciacolle.",h="Ukor aspetta fuori dalla Valle delle Sfide con provviste che non riesce a riportare a casa.",kw={"durotar","cibo","locandiere grosk","peone","tranciacolle","provviste","ukor","valle delle sfide"},ang={["faction:Horde"]="Lasci la Piana del Conflitto e ti dirigi a Tranciacolle, centro della difesa e dei rifornimenti dell'Orda nel sud di Durotar.",["race:Orc"]="La cultura orchesca dà valore alla forza fisica e al coraggio, relegando peoni come Ukor al gradino più basso dell'ordine sociale. Aiutarlo con la consegna dimostra come il lavoro umile tenga in funzione la nascente nazione di Durotar."},sec={{t="Una consegna fuori posto",b="Ukor è partito da Tranciacolle con provviste per le nuove reclute in addestramento nel canyon rosso. Pensava che avessero bisogno di cibo, ma i sovrintendenti lo hanno mandato via. Mantengono scarse le razioni, convinti che le difficoltà insegnino disciplina e resistenza ai giovani guerrieri dell'Orda. In seguito, il Locandiere Grosk spiega che la fame fa parte del loro addestramento."},{t="I pericoli della Desolazione Rossa",b="Ukor ha raggiunto il passo, ma teme di attraversare Durotar per tornare indietro. Gli scorpidi, i ragni velenosi e i cinghiali in agguato infestano il sentiero roccioso. Non ha armi né armatura e gli manca lo spirito combattivo che ci si aspetta da un fante orco.\n\nCosì Ukor aspetta lungo il sentiero e chiede ai viaggiatori in partenza dalla Piana del Conflitto di riportare le sue pesanti provviste alla locanda di Tranciacolle."}},faq={{q="Chi è Ukor?",a="Ukor è un timido peone orco in attesa sulla strada che esce dalla Valle delle Sfide. È partito da Tranciacolle con delle provviste, ma teme troppo la fauna locale per affrontare il viaggio di ritorno da solo.",al={"ukor","chi è il peone sulla strada","peone vicino alla valle delle sfide"}},{q="Perché gli istruttori nella Valle delle Sfide non volevano il cibo?",a="I sovrintendenti tengono affamati gli apprendisti perché credono che le difficoltà insegnino disciplina e resistenza. Il Locandiere Grosk spiega che le scarse razioni fanno parte del loro addestramento, perciò le provviste di Ukor sono state rifiutate.",al={"perché rifiutare il cibo","perché ukor trasportava cibo","locandiere grosk inedia"}},{q="Dove deve andare questa consegna?",a="Porta le provviste a nord lungo la strada principale di Durotar, fino a Tranciacolle. Consegnale al Locandiere Grosk nella locanda dell'insediamento.",al={"dov'è tranciacolle","a chi do il cibo","dove consegnare il fardello di ukor"}},{q="Cosa rende il viaggio pericoloso per un peone?",a="Scorpidi, ragni velenosi striscianti e cinghiali selvatici si aggirano nelle lande rocciose di Durotar. Ukor è un lavoratore senza armatura né addestramento, mentre le reclute esperte sanno affrontare simili parassiti.",al={"perché ukor è spaventato","pericoli strada durotar"}},{q="Qual è il ruolo dei peoni nell'Orda?",a="I peoni occupano il gradino più basso della società orchesca e svolgono lavori umili, dal trasportare rifornimenti e tagliare legna al costruire fortificazioni. I fanti e i campioni ricevono elogi e gloria, mentre i peoni vengono spesso trascurati, anche se provvedono al sostentamento e alla manutenzione degli insediamenti.",al={"tradizione peoni orchi","status peone","cosa sono i peoni"}},{q="Chi è il Locandiere Grosk?",a="Il Locandiere Grosk gestisce la locanda di Tranciacolle, con i suoi alloggi e le sue provviste. Offre cibo, bevande e un focolare ai guerrieri di passaggio e ricorda alle reclute di riposare prima di affrontare il mondo esterno.",al={"locandiere grosk","grosk tranciacolle","locandiere di tranciacolle"}}},fx={["777a74e1"]={q="Perché Ukor vuole che il cibo venga riportato a Tranciacolle?",a="Ukor era davvero in buona fede quando ha trasportato le scorte da Tranciacolle, sperando di aiutare le giovani reclute che si addestrano sotto il sole cocente della Valle delle Sfide. Quando gli istruttori hanno rifiutato le razioni, non ha potuto semplicemente abbandonare le scorte o lasciarle andare a male lungo la strada. Il cibo dovrebbe tornare sugli scaffali della dispensa del Locandiere Grosk, ma dopo essere sopravvissuto a stento al viaggio tra gli scorpidi e i ragni della regione, Ukor è terrorizzato all'idea di affrontare da solo il pericoloso ritorno.",al={"perché riportare il cibo","motivazioni di ukor","perché dare il cibo a grosk"}},fe82ef3c={q="Perché Ukor ti chiede di farti carico del peso invece di farlo lui?",a="Ukor è un semplice peone, poco avvezzo alla violenza e disarmato contro le terre selvagge. È riuscito ad affrontare gli scorpioni e i ragni lungo la strada che esce da Tranciacolle, ma il terrore di dover affrontare di nuovo quei feroci predatori lo ha paralizzato. Vedendoti uscire vittorioso dalla Valle delle Sfide, riconosce in te un eroe capace e senza paura, e spera che accetterai volentieri di farti carico del peso mentre vai a Tranciacolle.",al={"perché ukor non può trasportarlo","perché io per il fardello di un peone","perché ukor chiede a me"}}},fp="15,178,20.329.0,23.361.0,12.189.0,62.212.0,36.136.0,44.168.0,39.264.0,23.197.0"}
P.entries["quest:217"] = {n="In Defense of the King's Lands",s="Il Capitano Granchiasso ti manda nella Valle Pietrarotta per fermare gli attacchi alle Terre del Re. Gli esploratori li hanno ricondotti a Grawmug, capoclan dei trogg Pietraspezzata. La sua morte potrebbe spezzare la determinazione del branco e aiutare a riconquistare il sud di Loch Modan.",h="Il Capitano Granchiasso ti manda nella Valle Pietrarotta per fermare gli attacchi alle Terre del Re.",kw={"brawler","gnasher","grawmug","terre del re","loch modan","granchiasso","pietraspezzata","trogg"},ang={["faction:Alliance"]="Come membro dell'Alleanza, difendere Loch Modan aiuta a preservare il collegamento terrestre tra Forgiardente e le frontiere orientali. Aiuta anche a mantenere sicure le linee di rifornimento delle forze dell'Alleanza.",["race:Dwarf"]="Come nano, scacciare i trogg dall'antico suolo di Khaz Modan significa difendere la tua patria e renderle onore. Aiuti a tenere le roccaforti montane libere dalle piaghe sotterranee."},sec={{t="Decapitazione dello Sciame",b="Gli esploratori del Capitano Granchiasso hanno scoperto che i trogg Pietraspezzata seguono il capoclan Grawmug. I loro attacchi minacciano le Terre del Re nel sud di Loch Modan. Ti mandano nel loro covo per uccidere Grawmug e i suoi bruti personali. Spezzare la coesione del branco potrebbe fermarne l'avanzata."},{t="Nel Covo Pietraspezzata",b="Grawmug occupa una caverna nelle scogliere sudorientali della Valle Pietrarotta. I suoi bruti più fidati, Gnasher e Brawler, gli stanno accanto, e insieme sono una minaccia per un soldato solitario. Sconfiggerli potrebbe gettare nel caos i trogg rimasti. Questo darebbe ai Montanari, messi alle strette, il tempo di fortificare le strade e ricacciare le bestie sottoterra."}},faq={{q="Chi è Grawmug?",a="Grawmug è il capoclan dei trogg Pietraspezzata che guidano nel sud di Loch Modan. Gli esploratori nanici hanno ricondotto a lui gli assalti organizzati che tormentano la valle. Gnasher e Brawler lo proteggono.",al={"storia di grawmug","chi è il capo dei trogg","capoclan grawmug"}},{q="Dove si trovano Grawmug e le sue guardie?",a="Grawmug, Gnasher e Brawler si trovano nel profondo di una caverna sul margine sudorientale della Valle Pietrarotta, a Loch Modan.",al={"posizione di grawmug","dove si trova grawmug","dove trovare grawmug"}},{q="Chi è il Capitano Granchiasso?",a="Il Capitano Granchiasso è un ufficiale nanico di stanza alla Torre di Guardia Meridionale di Loch Modan. Supervisiona la difesa dalle incursioni dei trogg e impartisce ordini per proteggere le Terre del Re.",al={"granchiasso","ruolo del capitano granchiasso","chi dà in defense of the king's lands"}},{q="Perché devono essere uccise anche le guardie di Grawmug?",a="Gnasher e Brawler sono gli esecutori personali di Grawmug e gli stanno sempre accanto. Per spezzare il comando dei trogg, devi sconfiggerli insieme al loro capo.",al={"perché uccidere gnasher e brawler","gnasher e brawler","guardie del corpo di grawmug"}},{q="Cosa succede dopo l'eliminazione di Grawmug?",a="La morte di Grawmug potrebbe portare sollievo a Loch Modan. Senza di lui a coordinare le incursioni, i trogg Pietraspezzata potrebbero perdere la loro organizzazione. La milizia nanica locale avrebbe così maggiori possibilità di difendere i confini e ricacciare le bestie sottoterra.",al={"risultato dell'uccisione di grawmug","trogg dopo la morte di grawmug","abbiamo salvato loch modan"}},{q="Perché i trogg stanno invadendo Loch Modan?",a="I trogg vivono da tempo in caverne sotterranee sotto Khaz Modan. Gli scavi e le caverne rimaste aperte hanno permesso loro di raggiungere la superficie, dove scacciano gli abitanti dagli insediamenti e attaccano i viaggiatori sulle strade del Re.",al={"perché i trogg sono qui","invasione trogg loch modan","origine dei trogg pietraspezzata"}}},fx={["440a3b53"]={q="Perché il Capitano Granchiasso vuole che Grawmug venga ucciso?",a="Il Capitano Granchiasso considera Grawmug la mente dietro le incursioni dei trogg che minacciano Loch Modan. Le guarnigioni naniche faticano a tenere a bada le orde sotterranee e Granchiasso crede che eliminare i loro capi, in particolare Grawmug e le sue guardie del corpo d'élite, ne spezzerà lo slancio e darà ai nani una possibilità di ricacciarli sottoterra.",al={"motivazioni di granchiasso","perché uccidere grawmug","scopo di in difesa delle terre del re"}}},fp="30,250,22.286.0,23.351.0,15.197.0,41.112.0,25.194.0,43.148.0,41.255.1,35.209.0"}
P.entries["quest:2178"] = {n="Easy Strider Living",s="Ad Auberdine, Alanndarian Cantanotte offre ai cacciatori la sua ricetta dello Stufato di Zampalunga, se le portano carne di zampalunga della foresta.",h="Ad Auberdine, Alanndarian Cantanotte offre ai cacciatori la sua ricetta dello Stufato di Zampalunga, se le...",kw={"alanndarian cantanotte","auberdine","cucina","rivafosca","easy strider living","zampalunga","carne di zampalunga","stufato di zampalunga"},ang={["class:Hunter"]="Da cacciatore, puoi esercitarti a seguire le tracce e cacciare i veloci zampalunga della foresta lungo i sentieri nebbiosi di Rivafosca.",["profession:Cooking"]="Da cuoco in viaggio per Rivafosca, puoi imparare a preparare lo Stufato di Zampalunga usando la fauna locale.",["race:NightElf"]="Da elfo della Notte a Kalimdor, sai quanto sia importante vivere dei frutti della terra. Lo stufato di zampalunga è un piatto tipico della costa di Auberdine."},sec={{t="Un assaggio di natura selvaggia",b="Gli abitanti della costa di Auberdine sfruttano la fauna selvatica che li circonda. Alanndarian Cantanotte ha una sua ricetta per un sostanzioso stufato di zampalunga, preparato con i grandi zampalunga della foresta che si aggirano nei boschi di Rivafosca. Ti chiede di cacciare gli uccelli e riportarne la carne prima di condividere la sua ricetta."},{t="A caccia di zampalunga",b="I zampalunga della foresta si aggirano nei boschi e sulle spiagge a nord e a sud di Auberdine. Il loro becco affilato e il temperamento irascibile li rendono pericolosi se provocati, ma la loro carne è ottima per uno stufato ricco. Porta carne fresca ad Alanndarian e lei condividerà la sua ricetta."}},faq={{q="Chi è Alanndarian Cantanotte?",a="Alanndarian Cantanotte vive ad Auberdine, a Rivafosca. Si offre di insegnare la sua ricetta dello stufato di zampalunga ai viaggiatori che dimostrano la propria abilità nella caccia.",al={"alanndarian","chi è alanndarian cantanotte","cuoca stufato auberdine"}},{q="Dove trovo la carne di zampalunga?",a="Caccia i zampalunga della foresta in tutta Rivafosca per procurarti la loro carne. I grandi uccelli incapaci di volare si aggirano lungo le coste e nei boschetti fuori da Auberdine.",al={"posizione carne di zampalunga","dove si trovano gli zampalunga","come ottenere carne di zampalunga"}},{q="Qual è lo scopo di questa missione?",a="Dai la caccia ai zampalunga della foresta e porta cinque pezzi di carne ad Alanndarian Cantanotte. In cambio, ti insegna a preparare lo Stufato di Zampalunga.",al={"perché fare easy strider living","scopo missione","obiettivi easy strider living"}},{q="Gli zampalunga sono pericolosi da cacciare?",a="I zampalunga della foresta hanno becchi affilati e zampe veloci, e diventano aggressivi se ti avvicini. Caccia con cautela.",al={"gli zampalunga sono difficili da uccidere","pericolo zampalunga"}},{q="Questa missione sblocca una ricetta di cucina?",a="Sì. Porta ad Alanndarian la carne che ti chiede e ti insegnerà la ricetta dello Stufato di Zampalunga.",al={"ottengo la ricetta","ricetta stufato di zampalunga","ricompensa cucina"}},{q="Dove si svolge questa missione?",a="Parti e torni ad Auberdine, mentre cacci nelle terre selvagge di Rivafosca.",al={"zona missione","dove si trova easy strider living"}}},fx={["64984ff6"]={q="Perché Alanndarian Cantanotte vuole che tu lo faccia?",a="Alanndarian Cantanotte ha una pentola vuota e una gran voglia di stufato fresco di Zampalunga. Prima di rivelarti la sua ricetta segreta, vuole vedere se hai il fegato di cacciare tu stesso gli uccelloni e portarle carne fresca da cuocere sul fuoco.",al={"motivazioni di alanndarian","perché alanndarian vuole carne di zampalunga","perché lo stufato di zampalunga"}},["624f04e5"]={q="A cosa serve la Carne di Zampalunga?",a="Questa carne succulenta è l'ingrediente principale dello stufato saporito di Zampalunga di Alanndarian. Portandole cinque pezzi, riempirai il suo paiolo vuoto e le dimostrerai di meritare di imparare la sua ricetta segreta delle terre selvagge.",al={"a cosa serve la carne di zampalunga","perché serve la carne di zampalunga","uso della carne di zampalunga"}}},fp="19,120,19.288.0,26.253.0,29.143.0,33.152.0,34.129.0,41.105.0,40.94.0,33.72.0"}
P.entries["quest:218"] = {n="The Stolen Journal",s="Grelin Barbabianca ha bisogno che il suo diario rubato venga recuperato per valutare fino in fondo la minaccia dei troll nella Valle Crestafredda. Grik'nir il Gelido, capo dei Geloscaglia, lo ha portato nella caverna dei troll, privando Grelin della maggior parte delle sue informazioni raccolte sul campo.",h="Grelin Barbabianca ha bisogno che il suo diario rubato venga recuperato per valutare fino in fondo la...",kw={"valle crestafredda","dun morogh","covo dei mantogelido","troll geloscaglia","grelin barbabianca","grik'nir il gelido","senir barbabianca","the stolen journal"},ang={["faction:Alliance"]="Come membro dell'Alleanza, aiuti a proteggere le valli iniziali di Dun Morogh dai disordini. Lo fai reprimendo la tribù aggressiva dei Geloscaglia.",["race:Dwarf"]="Come nano, aiuti a proteggere le giovani reclute che muovono i primi passi oltre Forgiamara. Spezzi la leadership dei Geloscaglia nella Valle Crestafredda.",["race:Gnome"]="Come gnomo, fai affidamento sulla sicurezza dei passi della Valle Crestafredda. I rifugiati gnomi trovano riparo a Forgiamara e si riorganizzano nel territorio dei nani."},sec={{t="Gli appunti smarriti di uno studioso",b="I troll Geloscaglia si sono spinti nella Valle Crestafredda, e gli appunti di Grelin Barbabianca li tengono sotto controllo. Raccontano le abitudini dei troll e la loro improvvisa aggressività. Durante i disordini, un troll imponente ha rubato il diario personale di Grelin ed è fuggito nelle profondità dell'antro. Il diario contiene la maggior parte delle sue informazioni raccolte sul campo, quindi Grelin non può completare la sua valutazione finché non verrà recuperato."},{t="Confrontarsi con Grik'nir il Gelido",b="Grik'nir il Gelido tiene corte nel cuore della caverna dei troll della valle. Pitture distintive gli ricoprono il corpo e il volto. Sconfiggere questo potente troll Geloscaglia spezza la leadership immediata dei troll della caverna e mette al sicuro il diario di Grelin. Una volta restituito, Grelin potrà completare le sue scoperte, giudicare gestibile la situazione locale dei troll e inviare il rapporto a suo fratello Senir."}},faq={{q="Chi ha preso il diario di Grelin Barbabianca?",a="Grik'nir il Gelido ha preso il Diario di Grelin Barbabianca. Il grosso troll Geloscaglia ha strani segni sulla pelle e sul volto e si aggira nelle profondità della caverna dei troll.",al={"chi ha rubato il diario","chi ha il diario di grelin","ladro del diario"}},{q="Dove si può trovare Grik'nir il Gelido?",a="Grik'nir il Gelido si trova nella caverna dei troll, nelle zone meridionali della Valle Crestafredda.",al={"dove si trova griknir","posizione di grik'nir","come trovare grik'nir"}},{q="Perché il diario è importante per Grelin?",a="Il diario di Grelin contiene i suoi appunti e le sue scoperte sulle attività dei troll nella Valle Crestafredda. Gli serve per completare un rapporto per suo fratello Senir.",al={"perché grelin vuole il suo diario","cosa c'è nel diario di grelin"}},{q="Cosa succede dopo aver restituito il diario?",a="Dopo aver recuperato il diario, Grelin completa il suo rapporto sulla situazione dei troll nella Valle Crestafredda. Ti chiede di portare le sue scoperte a suo fratello Senir Barbabianca a Kharanos.",al={"cosa succede dopo the stolen journal","prossima missione the stolen journal"}},{q="I troll Geloscaglia vengono scacciati dalla Valle Crestafredda dopo questo?",a="Grelin ritiene che la situazione dei troll nella Valle Crestafredda sia sotto controllo dopo la sconfitta di Grik'nir. I Geloscaglia restano una minaccia nei passi montani di Dun Morogh.",al={"i troll sono sconfitti a crestafredda","la valle crestafredda è al sicuro dai troll"}},{q="Chi è Senir Barbabianca?",a="Senir Barbabianca è il fratello di Grelin, uno scout dell'Alleanza di stanza fuori dalla Valle Crestafredda, vicino a Kharanos. Raccoglie informazioni sulle minacce che incombono sul regno.",al={"chi è senir","grelin fratello senir"}}},fx={["78f0c4e3"]={q="Perché Grelin Barbabianca vuole che venga fatto?",a="Grelin sta preparando per suo fratello Senir un rapporto ufficiale sulla minaccia dei Frostmane nella Valle Crestafredda. Senza il suo diario, non può completare gli appunti né valutare la sicurezza della valle, lasciando i capi locali senza informazioni fondamentali sulle attività dei troll.",al={"perché grelin vuole il suo diario","motivazioni di grelin barbabianca","perché recuperare il diario di grelin"}},beb6a987={q="Perché Grelin ha bisogno che tu recuperi il suo diario?",a="Grelin è un osservatore, non un combattente in prima linea, e un possente bruto troll ha portato il diario nel profondo della caverna dei troll della Valle Crestafredda. Dopo aver già visto come hai respinto i troll nella valle, si affida a te perché ti addentri nella caverna e affronti il pericolo.",al={"perché grelin ha bisogno di me","perché mandare un avventuriero a cercare il diario","perché grelin non recupera il suo diario da solo"}}},fp="18,225,22.372.0,29.364.0,37.154.0,37.87.0,39.145.0,42.180.1,67.172.0,24.160.0"}
P.entries["quest:219"] = {n="Missing In Action",s="Il Caporale Keeshan è disperso nelle Montagne Crestarossa dopo che gli orchi Roccianera hanno travolto il suo reggimento. Lo hanno tramortito e portato in una fortezza scavata nella roccia. Ora ha bisogno di una scorta fino a Borgolago, dove la guarnigione attende il suo ritorno.",h="Il Caporale Keeshan è disperso nelle Montagne Crestarossa dopo che gli orchi Roccianera hanno travolto il suo...",kw={"orchi roccianera","caporale keeshan","scorta","keeshan","borgolago","maresciallo marris","missing in action","crestarossa"},ang={["class:Warrior"]="Da guerriero, difendi la prima linea dalle ondate di attaccanti Roccianera e proteggi lo stordito Keeshan mentre fugge dal loro accampamento armato.",["faction:Alliance"]="Da soldato dell'Alleanza, ogni combattente salvato è prezioso per la guarnigione di Borgolago, già sotto pressione mentre difende il Regno dal clan Roccianera."},sec={{t="Un reggimento sopraffatto",b="Gli orchi Roccianera scendono dalle vette settentrionali e rendono più pericolose le Montagne Crestarossa. Le pattuglie della guardia cittadina cadono spesso in imboscate, e il reggimento del Caporale Keeshan ha subito la sorte peggiore. In inferiorità numerica e sopraffatti, quasi tutti i soldati sono caduti. Keeshan è sopravvissuto perché un colpo devastante lo ha tramortito prima che gli orchi potessero giustiziarlo. Lo hanno trascinato nella loro caverna come prigioniero."},{t="Fuga dalle caverne",b="Malconcio e stordito, Keeshan è prigioniero nel profondo del territorio nemico. Non può scendere dalla montagna da solo, quindi lo scorti verso Borgolago, superando le bande di guerra degli orchi sulle creste. Il Maresciallo Marris sta cercando di scoprire cosa sia accaduto al reggimento disperso. Si prepara anche a fronteggiare altri attacchi a Borgolago, e il ritorno sano e salvo di Keeshan gli dà un sollievo di cui ha molto bisogno."}},faq={{q="Chi è il Caporale Keeshan?",a="Il Caporale Keeshan è un fantaccino dell'Alleanza di stanza nelle Montagne Crestarossa. Durante una pattuglia sulle colline rocciose, gli orchi Roccianera hanno sopraffatto il suo reggimento e lo hanno trascinato via. È l'unico sopravvissuto noto.",al={"caporale keeshan","chi è keeshan","storia di keeshan"}},{q="Dove è stato catturato il Caporale Keeshan?",a="Il Caporale Keeshan è prigioniero nel profondo di una caverna infestata dagli orchi, sulle colline settentrionali di Crestarossa, circondato da guerrieri Roccianera ostili.",al={"dove si trova keeshan","posizione di keeshan","caverna di keeshan"}},{q="Cosa è successo al resto dell'unità di Keeshan?",a="Gli orchi Roccianera hanno teso un'imboscata al reggimento di Keeshan e lo hanno sopraffatto. Quasi tutti gli uomini sono morti nel primo scontro.",al={"squadra di keeshan","cosa è successo al reggimento","uomini di keeshan"}},{q="Chi manda i giocatori a salvare Keeshan?",a="Il Caporale Keeshan ti chiede di liberarlo dalla sua caverna-prigione. Gli avventurieri dell'Alleanza lo trovano lì.",al={"chi inizia missing in action","chi assegna la missione","dove accettare missing in action"}},{q="Dove va Keeshan dopo essere stato liberato?",a="Dopo averlo liberato, Keeshan ha bisogno di una scorta giù per il versante della montagna fino a Borgolago. Si presenta al Maresciallo Marris vicino al ponte della città.",al={"consegna missing in action","dove corre keeshan","destinazione di keeshan"}},{q="Perché gli orchi Roccianera si trovano a Crestarossa?",a="Il clan Roccianera avanza a sud dalle sue roccaforti nelle Steppe Ardenti fino a Crestarossa. Minaccia Borgolago, che dispone di poche difese, e tende imboscate alle pattuglie del Regno.",al={"orchi roccianera crestarossa","perché gli orchi a borgolago","invasione roccianera"}}},fx={["64cb6fe2"]={q="Perché il Caporale Keeshan ha bisogno del tuo aiuto per fuggire?",a="Il Caporale Keeshan è intrappolato nel cuore del territorio nemico, dopo che il suo intero reggimento è stato teso in un'imboscata e massacrato dal clan Roccianera. Durante lo scontro ha ricevuto un grave colpo alla testa: è ferito, disorientato e ha bisogno di una scorta. Senza qualcuno che lo guidi tra gli orchi circostanti, rischia di essere giustiziato o di morire di fame nella caverna.",al={"perché aiutare keeshan","motivazioni di keeshan","perché keeshan ha bisogno di essere salvato"}},["1d637b84"]={q="Perché Keeshan non può fuggire da solo o aspettare la guardia di Borgolago?",a="Keeshan è gravemente ferito e ha bisogno di aiuto per farsi strada tra i predoni Roccianera. Nel frattempo, i difensori di Borgolago sono già al limite nel tentativo di proteggere la città da gnoll e orchi, e non hanno forze da destinare a una missione di ricerca e soccorso in profondità. Quando ti imbatti nella sua cella, sei letteralmente la sua unica speranza di tornare vivo.",al={"perché keeshan non può fuggire da solo","perché keeshan ha bisogno di me","perché non ci sono guardie cittadine"}}},fp="17,238,18.386.0,21.379.0,24.208.0,36.129.0,44.106.0,36.101.0,40.132.0,39.178.0"}
P.entries["quest:22"] = {n="Pasticcio di Fegato di Cinghiospino",s="Alla Saldean Farm nelle Marche Occidentali, Salma Saldean prepara un pasticcio nonostante i tempi duri. I banditi hanno devastato il granaio del regno e i coloni cacciano cinghiali aggressivi per sfamare le loro famiglie.",h="Alla Saldean Farm nelle Marche Occidentali, Salma Saldean prepara un pasticcio nonostante i tempi duri.",kw={"cinghiale","cucina","pasticcio di fegato","saldean farm","salma saldean","marche occidentali"},ang={["faction:Alliance"]="Aiutare coloni rurali come i Saldean sostiene fedeli famiglie umane che lottano per difendere la frontiera del regno senza l'esercito di Roccavento.",["profession:Cooking"]="Il piatto di Salma riflette la cucina rurale umana. Erbe dell'orto come aglio, rosmarino e aneto trasformano le interiora della selvaggina in un pasto nutriente."},sec={{t="Ospitalità di Frontiera",b="Un tempo le Marche Occidentali sfamavano Roccavento con il loro fertile granaio. Ora, strade trascurate, fuorilegge erranti e campi incolti rendono dura la vita per i pochi coloni rimasti. Alla Saldean Farm, Salma Saldean lavora per conservare un senso di casa nonostante i pericoli. Un tradizionale pasticcio di carne offre uno dei pochi conforti ai coloni che cercano di preservare il proprio stile di vita."},{t="Le Bestie Ferali delle Marche Occidentali",b="I cinghiali dalle zanne affilate vagano in gran numero per le pianure delle Marche Occidentali. La loro pelle coriacea e le zanne feroci li rendono pericolosi per i braccianti isolati, ma la loro carne sfama le famiglie tagliate fuori dal commercio regolare. La ricetta di Salma richiede rosmarino sminuzzato, aglio tritato, aneto tagliato e sugo lasciato sobbollire. Preparati con cura, gli organi pungenti delle bestie diventano un pasto ricco e saporito."}},faq={{q="Chi è Salma Saldean?",a="Salma Saldean è una colona resiliente che vive con suo marito, il Contadino Saldean, nella loro fattoria nel centro delle Marche Occidentali. I suoi pasti fatti in casa risollevano gli animi nonostante i pericoli dei banditi e delle bestie selvatiche.",al={"salma saldean","chi è salma","moglie del contadino"}},{q="Perché Salma vuole i fegati di cinghiale?",a="Salma vuole dei fegati di cinghiale per il suo famoso pasticcio di carne saporito, che sta preparando da condividere con suo marito. La crosta è cotta e i condimenti sono pronti; mancano solo i fegati prima che possa finire di cuocere il ripieno a fuoco lento.",al={"perché fegato di cinghiale","di cosa è fatto il pasticcio","scopo del pasticcio di fegato"}},{q="Dove si trovano solitamente i cinghiali nelle Marche Occidentali?",a="I cinghiali vagano per le pianure dorate delle Marche Occidentali e per i campi incolti, rovistando nei terreni abbandonati e percorrendo le strade sterrate.",al={"posizioni cinghiali","dove trovare cinghiali","caccia al fegato di cinghiale"}},{q="I cinghiali sono pericolosi per gli agricoltori locali?",a="Sì. I cinghiali sono animali selvatici aggressivi e territoriali, dotati di zanne affilate. Minacciano il bestiame e rappresentano un grave pericolo per i viaggiatori senza protezione che attraversano le pianure.",al={"i cinghiali sono ostili","pericolo cinghiali marche occidentali"}},{q="Perché il cibo scarseggia così tanto nelle Marche Occidentali in questo momento?",a="Il cibo scarseggia perché Roccavento offre poco sostegno e bande organizzate di banditi saccheggiano le fattorie. Molti contadini sono stati scacciati dalle loro terre, lasciando l'ex granaio del regno come una frontiera impoverita.",al={"carestia marche occidentali","perché niente cibo marche occidentali","tempi duri marche occidentali"}},{q="Completare questo compito aiuta la Saldean Farm a sopravvivere?",a="La carne fresca non può risolvere le crisi più ampie delle Marche Occidentali, ma aiuta a sostenere la famiglia Saldean e offre ai viaggiatori razioni sostanziose per il cammino che li attende.",al={"il pasticcio è importante","approvvigionamento alimentare saline"}}},fx={["3baa4b09"]={q="A cosa servono i Fegati di Cinghiospino?",a="Salma Saldean ha bisogno di fegati freschi di Cinghiospino per completare la sua celebre torta di carne delle Marche Occidentali. Ha già preparato la crosta speziata, tritato aneto, aglio e rosmarino e messo il sugo a sobbollire, ma le manca la carne per finire il pasto di famiglia.",al={"a cosa serve il fegato di cinghiospino","perché serve il fegato di cinghiospino","ricetta della torta di fegato di cinghiospino"}},ad043644={q="Perché Salma chiede aiuto a un'avventuriera o a un avventuriero invece di cacciare i Cinghiospino da sé?",a="Salma è impegnata a mandare avanti la fattoria e a occuparsi della cucina, mentre i Saldean lottano per sopravvivere alle difficoltà che affliggono le Marche Occidentali. Con cinghiali selvatici che si aggirano aggressivi fuori dalla sicurezza della recinzione e pochi membri della milizia in zona, deve affidarsi a viaggiatori capaci per procurarsi carne fresca.",al={"perché mi serve il fegato di cinghiospino","perché salma ha bisogno di me","perché salma non va a caccia"}}},fp="18,193,20.355.0,23.358.0,21.204.0,36.226.0,48.136.0,45.169.0,44.207.0,56.147.0"}
P.entries["quest:220"] = {n="Call of Water",s="L'acqua preparata da Brine raggiunge ora Islen Scruta Lagune sulla costa orientale delle Savane. Qui dà inizio alla fase successiva della prova sciamanica e sarà la base di un sapta che permette a un iniziato di vedere gli spiriti dell'acqua nella Selva Pinargento.",h="L'acqua preparata da Brine raggiunge ora Islen Scruta Lagune sulla costa orientale delle Savane.",kw={"brine","call of water","islen scruta lagune","sapta","selva pinargento","le savane","fiala d'acqua purissima","sapta dell'acqua","totem dell'acqua"},ang={["class:Shaman"]="Come sciamano dell'Orda, completi i riti di Call of Water per entrare in comunione con gli spiriti e ottenere il Totem dell'Acqua, che governa la guarigione e il ristoro.",["faction:Horde"]="Come membro dell'Orda, viaggi dalle Savane di Kalimdor alla Selva Pinargento a Lordaeron, attraversando terre controllate dai Reietti mentre affronti la prova."},sec={{t="Ritorno alla Costa",b="Dopo le prove nelle Savane Meridionali, Brine ti consegna una Fiala d'Acqua Purissima. Proviene da sorgenti pure ed è stata consacrata dai riti di Brine. La riporti sulla costa orientale, dove Islen Scruta Lagune veglia. L'acqua unisce gli insegnamenti di Brine ai riti del totem."},{t="Lo Scopo del Sapta",b="Islen spiega che gli occhi mortali non riescono a vedere facilmente gli spiriti dell'acqua. Per incontrarli, bevi una bevanda chiamata sapta. L'acqua di Brine è la base di questo infuso e apre i tuoi sensi a ciò che la vista comune non può scorgere. Vedere gli spiriti è solo una parte del viaggio. Ti metteranno alla prova."},{t="Una Traversata verso Lordaeron",b="Islen ti manda oltre Kalimdor, attraverso il mare fino alla Selva Pinargento, a sud di Sepulcra. Accanto a un santuario isolato, bevi il sapta e affronti direttamente gli elementali. Solo allora potrai guadagnarti il diritto di manifestare il Totem dell'Acqua."}},faq={{q="Cosa c'è dentro la Fiala d'Acqua Purissima?",a="La Fiala d'Acqua Purissima contiene acqua raccolta da sorgenti pure e consacrata dai riti di Brine. È la base per preparare un sapta, che permette a uno sciamano di comunicare con gli spiriti dell'acqua.",al={"fiala d'acqua purissima","acqua di brine","cosa mi ha dato brine"}},{q="Chi è Islen Scruta Lagune?",a="Islen Scruta Lagune è un'anziana sciamana che vive sulla costa sudorientale isolata delle Savane, a sud di Porto Paranco. Fa da mentore agli sciamani dell'Orda che cercano di entrare in comunione con l'acqua e con il Totem dell'Acqua.",al={"islen","chi è islen scruta lagune","lore di islen scruta lagune"}},{q="Cos'è un sapta?",a="Un sapta è una bevanda cerimoniale preparata dai mentori sciamanici. Cambia la percezione dello sciamano, permettendogli di vedere e incontrare gli spiriti elementali nascosti alla vista dei mortali.",al={"significato di sapta","sapta dell'acqua","cosa fa il sapta"}},{q="Perché devo andare nella Selva Pinargento subito dopo?",a="Il santuario per questa comunione si trova nelle acque costiere della Selva Pinargento, a sud di Sepulcra, nei Regni Orientali. Gli spiriti lì ti chiedono di incontrarli e affrontare una prova finale prima di ottenere la padronanza dell'acqua.",al={"perché selva pinargento","totem dell'acqua selva pinargento","santuario nella selva pinargento"}},{q="Dove vive Brine?",a="Brine vive in una capanna isolata nelle Savane Meridionali, in alto sulle colline a ovest della strada che porta al Grande Ascensore e a Millepicchi.",al={"posizione di brine","dov'è brine","trovare brine"}},{q="Uno sciamano può evitare di creare il sapta?",a="No. I riti di comunione richiedono che il tuo spirito sia in sintonia con il mondo invisibile. Senza un sapta che ti apra quella via, non puoi incontrare né sfidare gli spiriti dell'acqua al santuario.",al={"saltare il sapta","il sapta è richiesto","missione di visione dello sciamano"}}},fx={["5a67c999"]={q="Perché Brine ti rimanda da Islen Scruta Lagune?",a="Brine ha fatto la sua parte: ha purificato le acque che hai raccolto in giro per Kalimdor e le ha sigillate in una fiala benedetta. Sa di essere soltanto una guida sul tuo cammino, non la veggente che ti introduce ai misteri più profondi. Islen Scruta Lagune ti ha mandato da Brine per mettere alla prova la tua resistenza e, ora che l'acqua più pura è pronta, solo Islen possiede la saggezza necessaria per preparare la tua sapta e guidare la prova finale della tua comunione.",al={"perché brine ti manda via","motivazioni di brine per call of water","perché tornare da islen"}},["51ede7cd"]={q="Perché Brine ha bisogno che sia tu a portare la fiala invece di consegnarla lei stessa?",a="Questo pellegrinaggio è una prova per te, in quanto sciamano, non una commissione di comodo. La fiala contiene l'acqua che hai attinto personalmente dalla pozza ai piedi della capanna di Brine a The Barrens, dal pozzo al Mulino di Tarren e dalle Rovine della Polvere Stellare a Valtetra, e che è stata benedetta grazie al tuo lavoro. Riportarla da Islen attraverso le pianure completa il tuo legame personale con l'elemento prima che tu tenti di entrare in comunione con gli spiriti.",al={"perché devo consegnare la fiala","perché io per brine in call of water","perché brine non può portarla"}}},fp="13,231,19.287.0,24.282.0,23.236.1,40.185.0,23.183.0,16.167.0,46.222.0,22.133.0,39.174.0"}
P.entries["quest:2205"] = {n="Seek out SI: 7",s="Da Borgodoro, Keryn Sylvius manda i nuovi ladri a Roccavento con un pacco sigillato. La consegna li porta al cospetto del Maestro Mathias Shaw, che guida la rete di intelligence segreta della corona.",h="Da Borgodoro, Keryn Sylvius manda i nuovi ladri a Roccavento con un pacco sigillato.",kw={"borgodoro","keryn sylvius","mathias shaw","città vecchia","ladro","seek out si: 7","si:7","roccavento"},ang={["class:Rogue"]="Da ladro, entri nella principale agenzia di spionaggio di Roccavento, passando dai trucchi dei vicoli alla ricognizione reale.",["faction:Alliance"]="Come membro dell'Alleanza, fai affidamento sull'SI:7 per proteggere il regno dalle minacce dentro e fuori dai suoi confini, mentre Re Varian Wrynn è ancora disperso."},sec={{t="Il test di un corriere",b="L'istruttrice dei ladri Keryn Sylvius dubita che le reclute fresche sembrino agenti segreti. Affida loro una consegna sigillata per la capitale, mettendo alla prova la loro affidabilità come corrieri. Così giudica in silenzio se potrebbero servire il regno come esploratori."},{t="A porte chiuse nella Città Vecchia",b="SI: 7, ovvero Intelligence di Roccavento, Sezione 7, opera nella zona sud-orientale della Città Vecchia a Roccavento. In questo quartiere malridotto, il Maestro Mathias Shaw dirige le operazioni segrete del regno. Riceve il pacco con scetticismo asciutto, poi giudica se hai la grinta necessaria per il vero spionaggio."}},faq={{q="Cos'è l'SI:7?",a="SI: 7 significa Intelligence di Roccavento, Sezione 7. Dalla sua sede nella Città Vecchia, il Maestro Mathias Shaw guida l'intelligence segreta e le operazioni clandestine del Regno di Roccavento.",al={"cosa significa si 7","cos'è l'si7","storia dell'si:7"}},{q="Chi è Keryn Sylvius?",a="Keryn Sylvius addestra i ladri alla Locanda del Fiero Leone a Borgodoro. Collabora con SI: 7, valuta le reclute del posto e manda gli esploratori promettenti dal Maestro Mathias Shaw a Roccavento.",al={"keryn sylvius","istruttore ladri borgodoro"}},{q="Dove si trova Mathias Shaw a Roccavento?",a="Il Maestro Mathias Shaw si trova al piano superiore della sede dell'SI:7, nella zona sud-orientale della Città Vecchia a Roccavento, oltre gli istruttori dei ladri della città.",al={"dove si trova shaw","trova mathias shaw","posizione mathias shaw"}},{q="Cosa succede dopo aver consegnato il pacchetto a Shaw?",a="Dopo aver fatto rapporto a Mathias Shaw, metti alla prova le tue abilità da ladro. Ti manda al Molo di Jerod per rubare un programma delle spedizioni a un capomastro dei Defias.",al={"prossima missione dopo seek out si 7","cosa vuole shaw"}},{q="Perché Keryn prende in giro il giocatore prima di consegnare la consegna?",a="Gli agenti dell'SI:7 apprezzano la competenza e l'intuito. Keryn Sylvius tratta duramente le nuove reclute per giudicarne il temperamento e capire se hanno la determinazione necessaria per avvicinare il Maestro Shaw.",al={"perché keryn mi insulta","insulto consegna formaggio"}}},fx={["5aa3ad9f"]={q="Perché Keryn Sylvius vuole che questo pacco venga consegnato a Mathias Shaw?",a="Keryn si è formalmente impegnata a consegnare il pacco al Maestro Mathias Shaw nell'ambito di un incarico ufficiale. Anche se è evidente che detesta fare di persona le normali commissioni da corriere, mandare te le consente di raggiungere due obiettivi: onorare il suo obbligo verso l'agenzia e mettere alla prova le tue acerbe capacità di furfante davanti ai suoi superiori a Roccavento.",al={"perché consegnare a mathias","motivazioni di keryn sylvius","perché consegnare il pacco alla si:7"}},["6bd14f9c"]={q="Perché Keryn manda un furfante senza esperienza invece di consegnare il pacco di persona?",a="Keryn è di stanza a Borgodoro, dove tiene d'occhio e addestra le nuove reclute, e non ha alcuna voglia di riportare di persona piccole consegne alla Città Vecchia. Affidare l'incarico a una novizia o a un novizio entusiasta come te le risparmia la fatica e le permette di valutare sul campo se sei abbastanza sveglio da trovare il quartier generale dei servizi segreti di Roccavento.",al={"perché keryn manda me","perché cercare la si:7","perché non lo consegna lei stessa"}}},fp="14,191,16.247.0,31.284.0,13.180.0,21.181.0,43.140.0,50.148.1,64.186.0"}
P.entries["quest:2206"] = {n="Furto con destrezza",s="Al Molo di Jerod, il Maestro Mathias Shaw invia agenti a scoprire come la Fratellanza dei Defias trasporta i rifornimenti. La Fratellanza usa il molo sul fiume per spedire merci di nascosto.",h="Al Molo di Jerod, il Maestro Mathias Shaw invia agenti a scoprire come la Fratellanza dei Defias trasporta i...",kw={"lago di cristallo","defias","capitano del porto","borgodoro","molo di jerod","mathias shaw","programma delle spedizioni","si:7","snatch and grab"},ang={["class:Rogue"]="Da ladro, incontri l'SI:7 e dimostri la tua furtività e il tuo talento nel borseggio. Ottieni il riconoscimento di Mathias Shaw e una lama distintiva.",["faction:Alliance"]="Come membro dell'Alleanza, aiuti a intercettare i rifornimenti dei Defias al Molo di Jerod. Così proteggi la Foresta di Elwynn e indebolisci il sindacato criminale che minaccia i territori attorno a Roccavento."},sec={{t="Una prova del mestiere",b="Il Maestro Mathias Shaw mette alla prova chi aspira a entrare tra gli agenti segreti di Roccavento. Chiede finezza e furtività, non forza bruta. Gli agenti dell'SI:7 eliminano silenziosamente figure chiave e recuperano documenti importanti. Lo fanno senza trascinare il regno in uno scandalo pubblico. Ogni nuovo operativo deve dimostrare di saper agire senza farsi vedere."},{t="Contrabbandieri sul fiume",b="Il Molo di Jerod sorge sul fiume, nella parte meridionale di Elwynn, a sud di Borgodoro e appena a est delle Vigne dei Maclure. La Fratellanza dei Defias ha conquistato il molo, un tempo tranquillo, e lo ha trasformato in una rotta clandestina. Armi, rifornimenti e contrabbando attraversano l'acqua da Redridge verso le Marche Occidentali. Le pattuglie reali sulle strade non possono raggiungerli."},{t="Negabilità plausibile",b="Il Maestro Mathias Shaw avverte gli agenti che, se vengono catturati, compromessi o uccisi, resteranno senza il sostegno della Corona. Roccavento e i suoi capi dello spionaggio negheranno che siano mai esistiti. Il programma del Capitano del Porto dei Defias fornisce all'SI:7 prove delle linee di rifornimento della Fratellanza. Recuperarlo mantiene nascosto il coinvolgimento ufficiale di Roccavento."}},faq={{q="Chi assegna la missione Snatch and Grab?",a="Il Maestro Mathias Shaw, capo del servizio segreto SI:7 di Roccavento, assegna gli incarichi dalla sede centrale nella Città Vecchia.",al={"chi assegna snatch and grab","chi assegna missione snatch grab"}},{q="Dov'è il Molo di Jerod?",a="Il Molo di Jerod è un approdo fluviale nella parte meridionale della Foresta di Elwynn, a sud di Borgodoro e appena a est delle Vigne dei Maclure. La Fratellanza dei Defias controlla i moli e la rimessa.",al={"posizione molo di jerod","dov'è il molo di jerod","posizione capitano del porto"}},{q="Cosa stanno contrabbandando i Defias attraverso il Molo di Jerod?",a="I Defias trasportano contrabbando e rifornimenti sull'acqua, tra Redridge e le Marche Occidentali, al di là dei posti di guardia del regno e dei posti di blocco sulle strade.",al={"cosa stanno contrabbandando","contrabbando defias"}},{q="Chi trasporta il Programma delle Spedizioni dei Defias?",a="Il Capitano del Porto dei Defias porta con sé il programma delle spedizioni e sorveglia la rimessa al Molo di Jerod.",al={"dov'è il programma delle spedizioni","chi lascia il programma delle spedizioni","capitano del porto defias"}},{q="Cosa succede se un operativo viene catturato durante questa missione?",a="Il Maestro Mathias Shaw avverte che l'SI:7 negherà ogni legame con un operativo scoperto o catturato.",al={"cosa succede se fallisco","rinnegato dall'si:7"}},{q="Perché all'SI:7 interessa questo Programma delle Spedizioni?",a="Il programma descrive come la Fratellanza dei Defias trasporta contrabbando tra Redridge e le Marche Occidentali. Permette alla rete di intelligence di Roccavento di mappare le linee di rifornimento nemiche senza mettere in allerta il sindacato.",al={"perché serve il programma delle spedizioni","programma delle spedizioni si:7"}}},fx={["170a7301"]={q="Cos'è il Programma delle Spedizioni dei Defias?",a="Il programma descrive il trasporto di merci illecite lungo i corsi d'acqua della Foresta di Elwynn. La Fratellanza dei Defias ha preso il controllo del Molo di Jerod per far passare grandi quantità di contrabbando tra Redridge e le Marche Occidentali proprio sotto il naso del regno. Recuperare questi orari fornisce alla SI:7 informazioni concrete sui corridoi di movimento e sulle rotte logistiche dei Defias.",al={"programma delle spedizioni dei defias","cos'è il programma delle spedizioni","uso del programma delle spedizioni"}},["5dd0ffd3"]={q="Chi è il mastro di porto dei Defias?",a="Il mastro di porto supervisiona le operazioni segrete della Fratellanza al Molo di Jerod, una rimessa portuale sul fiume a sud di Borgodoro. Da questa posizione coordina il flusso di rifornimenti di contrabbando, armi e carichi rubati tra Redridge e le Marche Occidentali, tenendo con sé i registri del contrabbando per dirigere i battellieri dei Defias.",al={"mastro di porto dei defias","chi è il mastro di porto","mastro di porto al molo di jerod"}},a07026c6={q="Perché Mathias Shaw manda te invece di agenti esperti della SI:7?",a="Keryn Sylvius ti ha presentato a Mathias Shaw come una promettente nuova recluta furfante. Infiltrarti al Molo di Jerod serve sia come prova sul campo delle tue capacità di furtività e borseggio, sia come missione negabile. Poiché la SI:7 intende negare di sapere chi sei se ti catturano, impiegare un agente alle prime armi protegge dall'esposizione pubblica la principale rete d'intelligence di Roccavento.",al={"perché mandare me","perché reclutare per la si:7","perché mathias shaw ha bisogno di te"}}},fp="15,158,20.313.0,22.321.0,21.312.0,38.121.0,25.175.0,54.135.0,41.97.0,61.104.0,48.197.0"}
P.entries["quest:221"] = {n="Worgen in the Woods",s="I Corridori Oscuri Nightbane avanzano dal Frutteto Marcescente, a Boscovespro, verso Borgoscuro. Calor ti manda a decimare i loro ranghi prima che il branco circondi la città.",h="I Corridori Oscuri Nightbane avanzano dal Frutteto Marcescente, a Boscovespro, verso Borgoscuro.",kw={"calor","carevin","corridore oscuro","borgoscuro","boscovespro","the night watch","nightbane","frutteto marcescente","worgen"},ang={["class:Hunter"]="Da cacciatore, affronti al Frutteto Marcescente lupi innaturali e bipedi. Il loro istinto sfida l'ordine naturale di Azeroth.",["faction:Alliance"]="Boscovespro ha ricevuto pochissimi rinforzi dalla corona di Roccavento. I volontari locali di The Night Watch si affidano agli eroi dell'Alleanza di passaggio per decimare i branchi di predatori che premono sulla città."},sec={{t="Un perimetro che si restringe",b="Le ricognizioni di Calor hanno rivelato un pericolo ben più grande del worgen solitario visto per la prima volta mentre tesseva magie oscure ai margini della foresta. Corridori Oscuri Nightbane più grandi e rapidi si sono radunati nel Frutteto Marcescente, appena a sud-ovest di Borgoscuro. Formano la maggior parte del branco e hanno trasformato il frutteto in un punto di raccolta da cui possono raggiungere le porte del villaggio."},{t="Una marea inesauribile",b="Quando abbatti un Corridore Oscuro, The Night Watch ottiene solo un breve sollievo. Calor ne vede un altro aggirarsi nella nebbia al suo posto, e i difensori non riescono a spiegare la resistenza o il numero dei Nightbane. Si affidano a cacciatori di mostri veterani come il Maestro Jonathan Carevin per scoprire quale vile catalizzatore abbia richiamato questi orrori alieni a Boscovespro."}},faq={{q="Cosa sono i Corridori Oscuri Nightbane?",a="I Corridori Oscuri Nightbane sono worgen più grandi e imponenti, che formano la principale forza d'assalto del branco a Boscovespro. A differenza dei mistici Tessitori d'Ombre, fanno affidamento sulla velocità, sugli artigli e sulla ferocia predatoria.",al={"corridori oscuri","cosa sono i corridori oscuri","corridore oscuro nightbane"}},{q="Dov'è situato il Frutteto Marcescente?",a="Il Frutteto Marcescente si trova appena a sud-ovest di Borgoscuro. Un tempo erano campi fertili, ora è una radura corrotta che il branco Nightbane ha conquistato come avamposto vicino alla città.",al={"posizione frutteto marcescente","dove si trova il frutteto marcescente"}},{q="Chi è Calor?",a="Calor è un ranger di Borgoscuro al servizio del Maestro Jonathan Carevin. Esplora i dintorni dell'insediamento e segue le tracce dei branchi di worgen che minacciano la sopravvivenza della città.",al={"chi è calor","calor boscovespro","calor datore di missioni"}},{q="Perché il numero di worgen sembra infinito per i difensori?",a="I difensori non riescono a spiegare la presenza soprannaturale dei worgen. Credono che un potere malvagio li richiami o li attiri a Boscovespro, così nuove ondate arrivano non appena altre bestie vengono uccise.",al={"perché così tanti worgen","worgen inesauribili","da dove vengono i worgen"}},{q="Chi è il Maestro Carevin?",a="Il Maestro Jonathan Carevin guida da Borgoscuro la lotta della sua famiglia contro i non morti e gli altri mali di Boscovespro. Calor si affida alla sua esperienza per scoprire la causa delle mostruose infestazioni che affliggono la regione.",al={"maestro carevin","jonathan carevin","chi è carevin"}},{q="In che modo questo compito si inserisce nella difesa di Borgoscuro?",a="Borgoscuro è isolata, le sue scorte diminuiscono e Roccavento non ha inviato aiuti. Liberare il Frutteto Marcescente impedisce ai Nightbane di preparare imboscate dirette e travolgenti sul perimetro sud-occidentale della città.",al={"perché uccidere i corridori oscuri","difesa di borgoscuro"}}},fx={e2dcc78b={q="Perché Calor vuole eliminare i Corridori Oscuri di Nottefonda?",a="Calor tiene d'occhio le incursioni delle bestie intorno a Borgoscuro e sa che i Corridori Oscuri costituiscono la maggior parte dei worgen che si aggirano nella foresta. Peggio ancora, hanno invaso completamente il Frutteto Marcescente, appena a sud-ovest della città. Lasciare indisturbato un branco così numeroso e feroce tanto vicino a Borgoscuro sarebbe un disastro, perciò Calor ha bisogno che tu ne riduca il numero prima che l'insediamento venga sopraffatto.",al={"motivazioni di calor","perché uccidere i corridori oscuri","perché calor vuole che venga fatto"}},["99fe833d"]={q="Perché Calor si affida a te invece di liberare il frutteto da solo?",a="Calor è un esploratore e un ranger, e il suo compito principale è sorvegliare i boschi, seguire gli spostamenti delle bestie e riferire le minacce a Borgoscuro. I worgen Nottefonda sono aggressivi, resistenti e sembrano inesauribili, mettendo a dura prova i difensori della città. Con Borgoscuro assediata da orrori da ogni lato, ranger come Calor devono affidarsi ad avventurieri capaci di portare lo scontro direttamente in luoghi infestati come il Frutteto Marcescente.",al={"perché proprio io","perché calor non se ne occupa","perché calor ha bisogno di aiuto"}}},fp="19,158,22.351.0,21.333.1,32.192.0,37.164.0,13.164.0,56.200.0,22.208.0,53.204.0"}
P.entries["quest:2218"] = {n="Road to Salvation",s="Hogral Bakkan ti manda da Hulfdan Blackbeard a Forgiardente. Hulfdan mette alla prova la tua convinzione di essere un furfante degno di unirsi ai suoi prescelti.",h="Hogral Bakkan ti manda da Hulfdan Blackbeard a Forgiardente.",kw={"prescelti","circolo segreto","hulfdan blackbeard","forgiardente","la via della salvezza","furfante"},sec={{t="La prova di Hulfdan",b="Hulfdan Blackbeard, a Forgiardente, vuole sapere se ti consideri un furfante. Sta valutando se ammetterti tra i prescelti del Circolo Segreto. La sua decisione dipende da quanto ti stimi."}},faq={{q="Chi vuole parlarmi?",a="Hogral Bakkan ti manda a parlare con Hulfdan Blackbeard a Forgiardente.",al={"chi è hulfdan","hulfdan blackbeard"}},{q="Cos'è il Circolo Segreto?",a="Il Circolo Segreto è un'organizzazione con membri e ufficiali scelti. Hulfdan Blackbeard cerca furfanti da accogliere tra i suoi prescelti.",al={"circolo segreto","quale circolo"}},{q="Perché Hulfdan mi chiama furfante?",a="Hulfdan ti chiede se ti consideri un furfante degno di unirsi ai prescelti del Circolo Segreto.",al={"hulfdan furfante","perché furfante"}},{q="Cosa vuole da me Hulfdan?",a="Hulfdan vuole parlarti della possibilità di diventare uno dei prescelti del Circolo Segreto.",al={"cosa vuole hulfdan","reclutamento di blackbeard"}}},fp="17,140,14.214.0,31.70.0,26.139.0,37.95.0,31.85.0"}
P.entries["quest:222"] = {n="Worgen in the Woods",s="Calor ti manda nel sud di Boscovespro a combattere il branco dei Nightbane. Le loro tane e miniere portano la minaccia dei worgen vicino a Borgoscuro.",h="Calor ti manda nel sud di Boscovespro a combattere il branco dei Nightbane.",kw={"calor","carevin","borgoscuro","boscovespro","nightbane","tainted one","vile fang","worgen"},ang={["class:Hunter"]="Da cacciatore, ti trovi davanti a prede insolite nel furbo branco dei Nightbane. Resta vigile vicino alle loro tane oscure.",["faction:Alliance"]="Da viandante dell'Alleanza, contribuisci a proteggere le linee di rifornimento di Borgoscuro e le fattorie rimaste a Boscovespro ripulendo le caverne meridionali."},sec={{t="Una testa di ponte ferina",b="A sud di Borgoscuro, i worgen Nightbane fortificano caverne e pozzi minerari abbandonati per farne accampamenti. Calor osserva i loro falò e teme ciò che la loro crescente presenza significa per la città. Nel branco, i Vile Fang e i Tainted One sono le razze più feroci. La loro ferocia e ostinazione minacciano il perimetro di Borgoscuro."},{t="L'approvazione di Calor",b="Calor sorveglia la prima linea di Borgoscuro e sa quanto siano pericolosi i worgen. Sconfiggere i Vile Fang e i Tainted One mette alla prova ogni eroe. Chi li sconfigge si guadagna il suo rispetto e una raccomandazione personale per Master Carevin, che coordina la lotta più ampia contro i worgen."}},faq={{q="Dove si trovano i Vile Fang e i Tainted One?",a="I Vile Fang e i Tainted One si radunano attorno alle caverne e alla miniera nel sud di Boscovespro, spesso vicino ai falò.",al={"dove si trovano i tainted one","dove si trovano i vile fang","posizioni worgen boscovespro"}},{q="Chi è Calor?",a="Calor vive a Borgoscuro e sorveglia la minaccia dei worgen nei boschi. Recluta avventurieri capaci per fermare la loro avanzata.",al={"calor borgoscuro","chi dà worgen in the woods 3"}},{q="Chi è Jonathan Carevin?",a="Master Carevin è Jonathan Carevin di Borgoscuro. La sua famiglia combatte i mali della regione e lui coordina gli sforzi per eliminare i worgen dei dintorni.",al={"jonathan carevin","carevin boscovespro"}},{q="Perché i worgen accendono dei fuochi?",a="I worgen Nightbane si radunano in accampamenti organizzati, usano il fuoco e occupano posizioni fortificate come le miniere. I loro accampamenti rivelano un'intelligenza inquietante, nascosta sotto il loro aspetto mostruoso e simile a quello dei lupi.",al={"perché i worgen accendono fuochi","fuochi nightbane"}},{q="Cosa succede dopo aver completato questa caccia?",a="Fare colpo su Calor ti fa guadagnare una lettera di raccomandazione per Master Carevin. Poi potrai aiutarlo nella fase successiva della caccia.",al={"prossima missione dopo worgen in the woods 3","seguito di worgen in the woods"}},{q="Perché Borgoscuro è così preoccupata per questi specifici worgen?",a="I Vile Fang e i Tainted One sono tra i membri più letali e aggressivi del branco. Se lasciati indisturbati vicino alle miniere meridionali, potrebbero invadere le strade circostanti.",al={"perché nightbane vile fang","pericolo vile fang"}}},fx={["0c2f2969"]={q="Perché Calor vuole che questi worgen vengano uccisi?",a="Calor sta cercando di proteggere Borgoscuro e di aiutare il Maestro Carevin nella sua continua crociata contro la minaccia lupina. Il branco Nottefonda si è insediato nel sud, dove accende falò e stabilisce avamposti in caverne e miniere. Mandandoti a eliminare i suoi combattenti più pericolosi, Calor spera di indebolire il branco prima che sopraffaccia quel poco che resta delle difese di Boscovespro.",al={"perché uccidere i worgen","motivazioni di calor","perché calor lo vuole"}},["5cfb2401"]={q="Chi sono le Zanne Vili e i Contaminati che stai cercando?",a="Sono tra i membri più letali e feroci del branco Nottefonda. A differenza delle bestie inferiori che si aggirano nelle terre selvagge, questi worgen hanno organizzato accampamenti vicino alla Rovina di Roland e ad altre caverne meridionali, dove accendono fuochi e dimostrano un'astuzia e un'organizzazione che minacciano tutta Borgoscuro.",al={"chi sono le zanne vili","i contaminati di boscovespro","worgen bersaglio"}},["5e6f00dd"]={q="Perché Calor recluta te invece di affrontare le bestie da solo?",a="I difensori di Borgoscuro, la Night Watch, sono allo stremo e riescono a malapena a proteggere il perimetro della città da non morti, ragni e bestie fuori controllo. Portare lo scontro nel cuore del territorio dei worgen richiede campioni esperti, capaci di resistere alla magia oscura e alla ferocia brutale; i tuoi successi passati hanno dimostrato a Calor che hai le capacità per sopravvivere.",al={"perché calor ha bisogno di me","perché mandare me","perché la night watch non se ne occupa"}}},fp="19,131,16.308.0,19.276.1,50.107.0,13.122.0,22.147.0,32.194.0,40.125.0,58.175.0"}
P.entries["quest:223"] = {n="Worgen in the Woods",s="In Worgen in the Woods, Calor ti manda a Borgoscuro con una lettera per Jonathan Carevin. Le tue cacce ai worgen di Boscovespro gli hanno ispirato fiducia, e crede che la tua abilità possa aiutare Carevin.",h="In Worgen in the Woods, Calor ti manda a Borgoscuro con una lettera per Jonathan Carevin.",kw={"calor","nota di calor","borgoscuro","boscovespro","jonathan carevin","the night watch","worgen in the woods"},ang={["class:Paladin"]="Paladino, Carevin accoglie alleati fidati nel nome della Sacra Luce e cerca campioni sacri che affrontino i mali impuri di Boscovespro.",["class:Priest"]="Sacerdote, ascolti la benedizione d'addio di Carevin: «Gloria sotto la Luce». Esprime la fede dei difensori nel mezzo della corruzione incessante di Borgoscuro.",["faction:Alliance"]="Poiché il Regno di Roccavento non può risparmiare soldati per le terre di confine di Boscovespro, gli avventurieri indipendenti dell'Alleanza e i vigilanti come Carevin sono l'unica linea di difesa della città."},sec={{t="Una rara raccomandazione",b="Hai scacciato il branco Nightbane dalla Rovina di Roland e dalle radure in ombra, guadagnandoti il rispetto di Calor. Serve sulla frontiera oscura del bosco e raramente fa complimenti o presentazioni formali. Ora ti affida un brandello di pergamena sbiadito per Jonathan Carevin a Borgoscuro. Calor crede che altri combattenti come te possano aiutare il suo piccolo gruppo a superare The Night Watch, messa a dura prova."},{t="La veglia di Carevin",b="Jonathan Carevin lavora a Borgoscuro sotto una forte pressione. Worgen, non morti inquieti, forze demoniache e cultisti che alimentano la corruzione dall'interno minacciano la città. Diffidente verso gli estranei e a corto di tempo, Carevin si fida della raccomandazione di Calor. Ti considera un combattente affidabile, capace di aiutare a preservare la Luce contro i terrori di Boscovespro."}},faq={{q="Chi mi invia in questa missione?",a="Calor ti manda a consegnare una lettera di raccomandazione sbiadita a Jonathan Carevin. I tuoi successi contro i branchi di worgen in tutta Boscovespro ti hanno guadagnato il suo rispetto.",al={"datore di missione","chi inizia questa missione","calor"}},{q="Chi è Jonathan Carevin?",a="Jonathan Carevin vive a Borgoscuro e coordina la difesa della città contro le minacce soprannaturali. Diffidente verso gli estranei, collabora con alleati fidati come Calor contro non morti, demoni e chi li aiuta.",al={"carevin","chi è carevin","maestro carevin"}},{q="Perché Calor è così sprezzante nei confronti di The Night Watch?",a="Calor crede che The Night Watch fatichi a fronteggiare i molti pericoli di Boscovespro. Pensa che pochi combattenti capaci possano fare più del piccolo gruppo della città.",al={"calor the night watch","superare in numero the night watch","perché competere con the night watch"}},{q="Di quali minacce avverte Carevin al momento della consegna?",a="Carevin affronta worgen, non morti inquieti, forze demoniache e cultisti che aiutano la corruzione dall'interno. Le minacce premono sulla città da ogni lato.",al={"nemici di carevin","cosa dice carevin","cosa stiamo combattendo"}},{q="Questa missione richiede combattimento?",a="No. Devi solo portare la lettera di Calor a Carevin a Borgoscuro. Le tue precedenti cacce ai worgen Nightbane sono ormai alle spalle.",al={"serve combattere","devo uccidere qualcuno","solo consegna"}},{q="Dove posso trovare Jonathan Carevin?",a="Jonathan Carevin si trova a Borgoscuro e si occupa della difesa della città.",al={"posizione di carevin","dove si trova carevin","dove consegnare la missione"}}},fx={f56a577c={q="Perché Calor ti manda da Jonathan Carevin?",a="Calor ritiene che tu abbia dimostrato il tuo valore nei boschi e vuole presentarti ufficialmente al suo superiore, il Maestro Jonathan Carevin. Il suo piccolo ordine agisce nell'ombra di Boscovespro, separato dalla Night Watch, messa a dura prova; Calor spera che accogliere nel gruppo combattenti capaci come te rafforzi gli sforzi clandestini contro le minacce oscure che affliggono la regione.",al={"perché mandarmi da carevin","motivazioni di calor","perché portare un messaggio a carevin"}},["47a08b52"]={q="Perché Calor si affida a te invece che alla Guardia Notturna?",a="Calor ha poca fiducia nelle guardie cittadine tradizionali e considera inadeguata la Guardia Notturna per il lavoro cupo e specializzato intrapreso dal suo ordine. Poiché hai dimostrato il tuo valore affrontando direttamente la minaccia dei worgen, laddove altri hanno fallito, ti considera davvero in grado di aiutarli nella loro crociata segreta contro gli orrori più oscuri di Boscovespro.",al={"perché non la guardia notturna","perché fidarsi di me invece che delle guardie","perché calor ha bisogno di me"}}},fp="19,197,21.382.0,15.339.0,29.158.0,24.210.0,46.153.0,51.150.0,35.137.0,34.66.0"}
P.entries["quest:224"] = {n="In Defense of the King's Lands",s="Alla torre di guardia meridionale, il Montanaro Selcedura chiede aiuto mentre i trogg Pietrarotta avanzano verso la Valle dei Re. Le forze di Forgiardente combattono su fronti lontani.",h="Alla torre di guardia meridionale, il Montanaro Selcedura chiede aiuto mentre i trogg Pietrarotta avanzano...",kw={"selcedura","ghiaiadoro","forgiardente","loch modan","montanaro","pietrarotta","trogg","valle dei re"},ang={["class:Hunter"]="Come cacciatore, puoi sfruttare le pareti rocciose e gli affioramenti della Valle Pietrarotta per colpire dall'alto le sentinelle e gli esploratori trogg.",["faction:Alliance"]="Come avventuriero dell'Alleanza, contribuire a mettere in sicurezza la Valle dei Re risponde all'appello di Forgiardente mentre le truppe naniche combattono su lontani fronti alleati.",["race:Dwarf"]="Come nano, rispondere alla chiamata di Selcedura aiuta a difendere le valli ancestrali di Re Magni dai parassiti sotterranei, mentre l'esercito combatte altrove."},sec={{t="Una linea sottile nella Valle dei Re",b="Selcedura e le guardie sono troppo poche per fermare la crescente invasione di trogg sotto i grandi monumenti nanici. Re Magni Barbabronzea ha inviato gran parte del suo esercito regolare all'estero per sostenere l'Alleanza. Le pattuglie locali e le lame mercenarie devono impedire che la provincia venga sopraffatta."},{t="L'incursione Pietrarotta",b="La Valle Pietrarotta attraversa le vette meridionali di Loch Modan, dove i trogg sono emersi dalle profondità scavando gallerie. I loro esploratori perlustrano le strade, mentre i guerrieri costruiscono accampamenti sul fondovalle. Se non fermati, i loro gruppi minacciano le strade verso i passi meridionali. I Montanari devono combatterli senza tregua."}},faq={{q="Perché la guarnigione di Loch Modan è così a corto di uomini?",a="Re Magni Barbabronzea ha inviato gran parte delle forze armate di Forgiardente su lontani campi di battaglia dell'Alleanza e in avamposti sparsi per Azeroth. Loch Modan e gli altri territori interni dipendono soprattutto dalle pattuglie leggere dei Montanari, che chiedono ai viaggiatori di contribuire a respingere le invasioni locali.",al={"perché così poche guardie","dove sono i soldati di forgiardente","perché a corto di uomini"}},{q="Chi è il Montanaro Selcedura?",a="Il Montanaro Selcedura è una sentinella nana nella torre di guardia meridionale della Valle dei Re. Coordina la sicurezza lungo il confine meridionale di Loch Modan e dirige gli attacchi contro le tribù trogg.",al={"selcedura","chi dà le missioni","datore di missioni"}},{q="Dove si trova la Valle Pietrarotta?",a="La Valle Pietrarotta si trova a sud di Thelsamar. Il suo ingresso è vicino alla strada principale, prima delle imponenti statue naniche nella Valle dei Re, e i trogg mantengono diversi accampamenti sul suo fondo roccioso.",al={"posizione pietrarotta","dove sono i trogg","trovare valle pietrarotta"}},{q="Perché i trogg sono una minaccia così grave per i nani?",a="I trogg scavano gallerie nella roccia compatta e possono aggirare mura e fortificazioni in superficie. Possono sbucare sotto strade, insediamenti e miniere, mettendo a rischio la sicurezza di Forgiardente.",al={"minaccia trogg","perché combattere i trogg","i trogg sono pericolosi"}},{q="A chi devo rivolgermi dopo aver aiutato Selcedura?",a="Dopo aver decimato i trogg e gli esploratori Pietrarotta, Selcedura ti manda dal Montanaro Ghiaiadoro. Si trova appena dentro la torre di guardia adiacente e gestisce la pattuglia successiva lungo il fronte della valle.",al={"missione successiva","dove andare dopo","ghiaiadoro"}},{q="I trogg Pietrarotta sono organizzati?",a="Il clan Pietrarotta invia esploratori specializzati a perlustrare le strade, mentre i fanti presidiano accampamenti difensivi in tutta la gola.",al={"esploratori trogg","i trogg sono intelligenti","struttura pietrarotta"}}},fx={abec66b9={q="Perché il Montanaro Selcedura vuole che i trogg vengano eliminati?",a="Il Montanaro Selcedura considera l'infestazione di trogg la più grande minaccia per Loch Modan e per la stessa Forgiardente. Queste creature scavano gallerie emergendo da ogni fessura e minacciano la Valle dei Re e le terre circostanti. Poiché l'esercito regolare dei nani è impegnato su campi di battaglia lontani, Selcedura deve affidarsi a volontari audaci per ridurne il numero prima che le torri e gli insediamenti locali vengano sopraffatti del tutto.",al={"perché uccidere i trogg","motivo di selcedura","perché selcedura vuole uccidere i trogg"}},["515fdd78"]={q="Cosa ci fanno i trogg Pietrarotta a Loch Modan?",a="I trogg Pietrarotta sono mutanti selvaggi del sottosuolo che hanno scavato gallerie fino alle regioni meridionali del Loch, stabilendo accampamenti in tutta la Valle Pietrarotta. I loro esploratori sondano continuamente il territorio dei nani, cercando punti deboli lungo le strade della valle e vicino alla torre di guardia meridionale. Se lasciati indisturbati, la loro rapida espansione rischia di interrompere le vie di comunicazione e invadere la regione.",al={"chi sono i trogg","perché i trogg pietrarotta sono qui","bersaglio dei trogg pietrarotta"}}},fp="30,170,34.273.0,27.321.0,49.266.0,31.204.0,38.197.0,54.178.0,44.193.0,39.136.0"}
P.entries["quest:2242"] = {n="Destiny Calls",s="Vicino alla Radura dell'Oracolo, Syurna ti chiede di scoprire cosa sa Sethir l'Antico della corruzione di Teldrassil. Il satiro ha respinto sia la forza sia la diplomazia.",h="Vicino alla Radura dell'Oracolo, Syurna ti chiede di scoprire cosa sa Sethir l'Antico della corruzione di...",kw={"rivafosca","darnassus","destiny calls","diario","radura dell'oracolo","satiro","sethir l'antico","syurna","teldrassil"},ang={["class:Rogue"]="Da furfante, metti alla prova la tua abilità sottraendo informazioni riservate sotto il naso di un satiro pericoloso, su ordine degli addestratori della furtività di Darnassus.",["faction:Alliance"]="Da difensore dell'Alleanza, scopri che la corruzione nei boschi di Teldrassil si estende oltre l'isola, verso le terre settentrionali di Kalimdor.",["race:NightElf"]="Da difensore kaldorei, scopri che l'antica maledizione di Rivafosca ha attraversato il mare fino a Teldrassil, minacciando il tuo rifugio sacro."},sec={{t="Una Ricognizione Silenziosa",b="La malattia sempre più grave di Teldrassil preoccupa i capi degli Elfi della Notte a Darnassus. Syurna, l'addestratrice di furfanti, ha bisogno di qualcuno che agisca senza farsi notare, perché pattuglie armate sono morte nel tentativo di raggiungere Sethir l'Antico. Il satiro si è stabilito su un ramo remoto vicino alla Radura dell'Oracolo. Ha respinto sia la forza sia la diplomazia. Per scoprire cosa sa, devi entrare nel suo covo e prendere i suoi effetti personali."},{t="Una minaccia incombente da Rivafosca",b="Il diario di Sethir l'Antico collega la corruzione di Teldrassil alla putrefazione che consuma foreste e corsi d'acqua di Rivafosca, oltre il mare nebbioso. La malattia si estende oltre il suolo sotto l'Albero del Mondo. La sua diffusione indica una malvagità deliberata che minaccia il cuore dei kaldorei."}},faq={{q="Chi è Sethir l'Antico?",a="Sethir l'Antico è un satiro nascosto su un ramo vicino al confine settentrionale della Radura dell'Oracolo di Teldrassil. Ha sconfitto gli assalitori armati e respinto le richieste pacifiche di chi voleva scoprire cosa sa della corruzione dell'isola.",al={"sethir","chi è sethir","satiro nella radura dell'oracolo"}},{q="Perché Syurna vuole il Diario di Sethir?",a="Syurna crede che il diario di Sethir contenga indizi sulla malattia innaturale che si diffonde per Teldrassil. Le sue pagine descrivono le sue attività e la corruzione oscura.",al={"perché il diario di sethir","obiettivo di syurna","cosa c'è nel diario"}},{q="Cosa rivela il diario al completamento?",a="Il diario di Sethir collega la malattia tra i rami di Teldrassil alla piaga demoniaca che avvinghia le antiche foreste e le coste di Rivafosca, oltre il canale.",al={"storia del diario","cosa ha trovato sethir","legame con rivafosca"}},{q="Dove si riceve questa missione?",a="Syurna, l'addestratrice di furfanti a Darnassus, ti affida questo incarico dopo una prima valutazione delle tue capacità.",al={"dove ricevo destiny calls","datore di quest destiny calls","chi assegna destiny calls"}},{q="Dove dovrebbero andare gli avventurieri dopo aver completato questa missione?",a="Syurna dice che qui non si può fare altro al riguardo. Ti ricompensa con una lama per il tuo servizio a Teldrassil.",al={"what comes next","passo successivo dopo destiny calls","dopo sethir"}},{q="Perché un'addestratrice di furfanti si occupa della corruzione della foresta invece dei druidi?",a="La forza e la diplomazia druidica hanno entrambe fallito contro Sethir, con esiti fatali. Syurna ricorre alla furtività e all'infiltrazione dopo che i tentativi in campo aperto si sono conclusi nel sangue.",al={"perché quest per furfanti","perché syurna","perché non il circolo cenariano"}}},fp="13,158,23.375.0,31.268.1,26.231.0,38.154.0,45.152.1,29.106.0,58.120.1,68.159.0"}
P.entries["quest:2258"] = {n="Badlands Reagent Run",s="A Kargath, Jarkal Fondimuschio ha bisogno di reagenti delle Maleterre per rifornire le scorte. Ti offre monete se glieli porti.",h="A Kargath, Jarkal Fondimuschio ha bisogno di reagenti delle Maleterre per rifornire le scorte.",kw={"alchimia","maleterre","ventriglio di poiana","zanna di coyote delle rupi","jarkal fondimuschio","kargath","frammento di elementale della roccia","uldaman"},sec={{t="Rifornire gli scaffali",b="A Jarkal Fondimuschio servono ventrigli di cinque poiane, zanne di dieci coyote delle rupi e frammenti di cinque elementali della roccia. Prendili direttamente dalle creature. Se non combatti, trova amici che lo facciano. Jarkal ti paga in monete quando gli porti i reagenti."},{t="Dopo il bottino",b="Jarkal è soddisfatto di ciò che gli porti e dice che dovrebbe bastare per un po'. Tuttavia, gli servono altri reagenti dalle profondità degli scavi di Uldaman, dove sarà difficile raccoglierli. Lascia intendere che la ricompensa potrebbe valere più di monete luccicanti."}},faq={{q="Chi richiede questi reagenti?",a="Jarkal Fondimuschio, un alchimista di un certo calibro a Kargath, ha bisogno di reagenti per rifornire le scorte.",al={"chi dà badlands reagent run","jarkal fondimuschio","chi è jarkal fondimuschio"}},{q="Quali ingredienti servono a Jarkal?",a="A Jarkal servono ventrigli di cinque poiane, zanne di dieci coyote delle rupi e frammenti di cinque elementali della roccia. Prendili direttamente dalle creature.",al={"quali oggetti servono","elenco reagenti delle maleterre","reagenti richiesti"}},{q="Dove si trova Jarkal Fondimuschio?",a="Jarkal Fondimuschio si trova nell'avamposto di Kargath, nelle Maleterre.",al={"posizione jarkal fondimuschio","dove si trova l'alchimista di kargath","dove consegnare badlands reagent run"}},{q="Cosa offre Jarkal in cambio degli ingredienti?",a="Jarkal ti offre monete quando gli porti i reagenti a Kargath. Prima non ti paga.",al={"ricompensa badlands reagent run","cosa ottengo"}}},fp="20,116,20.253.0,14.243.1,33.94.0,34.149.0,33.62.0,55.94.0"}
P.entries["quest:2259"] = {n="Erion Shadewhisper",s="Dalle foreste di Teldrassil, i ladri promettenti vengono mandati a Darnassus. All'Enclave Cenariana, Erion Shadewhisper li indirizza verso incarichi oltre le foreste.",h="Dalle foreste di Teldrassil, i ladri promettenti vengono mandati a Darnassus.",kw={"enclave cenariana","darnassus","erion shadewhisper","erion's behest","jannok cantabrezza","missione introduttiva per ladri","syurna"},ang={["class:Rogue"]="Da ladro, lasci gli incarichi da novizio a Teldrassil e ti presenti da Erion Shadewhisper. Ha incarichi che richiedono finezza oltre le foreste iniziali.",["faction:Alliance"]="Come agente dell'Alleanza nel nord di Kalimdor, ti coordini con i referenti di Darnassus prima di avventurarti in territorio conteso.",["race:NightElf"]="Come Elfo della Notte predatore delle ombre, ti presenti da Erion a Darnassus. Ora i tuoi doveri vanno oltre la sorveglianza locale e si estendono per tutto il continente."},sec={{t="Una convocazione all'Enclave",b="Jannok Cantabrezza ti manda da Teldrassil a Darnassus per trovare Erion Shadewhisper. Non temere: non ti sta convocando Syurna, l'esigente addestratrice. Erion ti aspetta all'Enclave Cenariana, dove si occupa di incarichi che richiedono un tocco più discreto."},{t="Sguardo all'orizzonte",b="Per i ladri nelle terre degli Elfi della Notte, le foreste di Teldrassil non bastano più a contenere i loro doveri. Erion Shadewhisper manda agenti capaci in un mondo più vasto e pericoloso. I loro incarichi si svolgono oltre il mare."}},faq={{q="Chi ti invia a cercare Erion Shadewhisper?",a="Jannok Cantabrezza ti manda da Teldrassil a Darnassus per parlare con Erion Shadewhisper all'Enclave Cenariana.",al={"datore di missione","chi avvia erion shadewhisper","missione di jannok cantabrezza"}},{q="Dove si trova Erion Shadewhisper?",a="Erion Shadewhisper si trova all'Enclave Cenariana di Darnassus, tra gli alberi sui livelli superiori dell'enclave.",al={"posizione di erion","dove si trova erion","dove trovare erion shadewhisper"}},{q="Perché Jannok menziona Syurna?",a="Syurna è una rinomata addestratrice di ladri a Darnassus, nota per le sue lezioni severe e impegnative. Jannok ti rassicura con una battuta scherzosa: non sei nei guai e non ti sta mandando da lei per addestrarti.",al={"chi è syurna","perché non syurna","battuta di jannok su syurna"}},{q="Cosa succede dopo esserti presentato a Erion?",a="Dopo il tuo rapporto, Erion ti affida il suo prossimo incarico, Erion's Behest. Ti manda oltre Teldrassil per ampliare il tuo raggio d'azione a Kalimdor.",al={"cosa fare dopo","seguito di erion","missione dopo erion shadewhisper"}},{q="Che tipo di lavoro supervisiona Erion?",a="Erion dirige i nuovi ladri a Darnassus e mette in contatto gli agenti locali con le operazioni più ampie dell'Alleanza.",al={"erion è un addestratore di ladri","ruolo di erion shadewhisper","cosa fa erion"}},{q="Perché un addetto ai ladri è di stanza nell'Enclave Cenariana?",a="L'Enclave Cenariana è nota per i druidi e il culto della natura. I suoi alberi offrono luoghi appartati dove gli agenti furtivi possono incontrarsi e sbrigare i propri affari lontano da The Temple of the Moon.",al={"ladro all'enclave cenariana","perché un'area druidica per i ladri"}}},fx={["8fe8a3c2"]={q="Perché Jannok Cantabrezza ti manda da Erion?",a="Jannok Cantabrezza non ti sta assegnando un incarico per conto suo, ma fa da messaggero. Erion Shadewhisper ha chiesto espressamente la tua presenza all'Enclave Cenariana per mettere alla prova le tue capacità e mandarti oltre Teldrassil man mano che progredisce il tuo addestramento.",al={"perché jannok ti manda","motivo di jannok cantabrezza","perché incontrare erion shadewhisper"}}},fp="18,159,24.243.0,19.194.0,41.114.0,36.105.0,31.197.0,38.131.0,37.95.0,57.175.0"}
P.entries["quest:226"] = {n="Wolves at Our Heels",s="Nella parte occidentale di Boscovespro, Lars affronta lupi terribili affamati e rabbiosi. Cacciarli gli permette di procurarsi cibo mentre lui e Sven Yorgen portano avanti la loro vendetta contro il negromante Morbent Fel.",h="Nella parte occidentale di Boscovespro, Lars affronta lupi terribili affamati e rabbiosi.",kw={"lupo terribile","boscovespro","flash bundles","lars","morbent fel","lupo terribile rabbioso","lupo terribile affamato","sven","sven's camp"},ang={["class:Hunter"]="Da cacciatore, ti serve un occhio attento per domare o abbattere la fauna selvatica corrotta di Boscovespro. Questi lupi terribili sono più disperati e feroci delle normali bestie della foresta.",["faction:Alliance"]="Come viaggiatore dell'Alleanza, aiuti a mantenere al sicuro il remoto accampamento di Lars e a garantire un avamposto alleato contro le forze non morte che infestano la parte occidentale di Boscovespro."},sec={{t="Un accampamento precario",b="Sven Yorgen e Lars mantengono un accampamento isolato sulle colline occidentali di Boscovespro, vicino al confine con le Marche Occidentali. Lontani da Borgoscuro, dipendono dalla caccia e dalla raccolta per sopravvivere. Mentre Lars trasporta selvaggina fresca attraverso i boschi oscuri, predatori famelici si aggirano lungo le rive del fiume e nel sottobosco."},{t="Ripulire i boschi",b="Lupi terribili affamati e rabbiosi si aggirano a nord e a est dell'accampamento, verso il fiume. Uccidere le bestie furiose rende più sicura la caccia di Lars. Con meno pericoli mentre procurano il cibo quotidiano, Sven e Lars possono concentrarsi su Morbent Fel, il negromante più a est."}},faq={{q="Chi è Lars?",a="Lars aiuta Sven Yorgen nel loro piccolo accampamento sulle colline occidentali di Boscovespro. Caccia e raccoglie ciò che serve loro ogni giorno, mentre Sven è ossessionato dalla vendetta contro le forze oscure che minacciano la regione.",al={"lars","chi offre wolves at our heels","lars datore di missione"}},{q="Dove si aggirano i lupi?",a="Lupi terribili si aggirano nei boschi a nord e a est di Sven's Camp, soprattutto lungo le rive del fiume che separa Boscovespro dalle zone settentrionali.",al={"posizione dei lupi","dove si trovano i lupi terribili rabbiosi","dove si trovano i lupi terribili affamati"}},{q="Perché i lupi terribili sono così aggressivi?",a="La natura selvaggia di Boscovespro è diventata più ostile sotto l'ombra che avanza. La selvaggina scarseggia e i lupi terribili sono quasi ridotti alla fame. Malattie o corruzione oscura ne hanno resi molti rabbiosi e sconsideratamente violenti con chiunque trasporti carne fresca.",al={"perché i lupi attaccano","lupi rabbiosi boscovespro"}},{q="Chi è Morbent Fel?",a="Morbent Fel è un potente negromante che pratica le arti oscure nei cimiteri e nei tumuli a est. Sven e Lars gli serbano un rancore profondo e si preparano ad affrontarlo non appena avranno provveduto ai bisogni essenziali.",al={"morbent fel","il negromante","chi è il negromante a est"}},{q="Cosa sono i Flash Bundles che Lars dà come ricompensa?",a="Le Cariche Luminose sono dispositivi accecanti fabbricati dagli abitanti di Borgoscuro. Residenti solidali le hanno donate all'accampamento di Sven per aiutarlo a combattere i non morti e le bestie che infestano i boschi.",al={"flash bundles","ricompensa di lars","cos'è un flash bundle"}},{q="Perché Sven e Lars non vivono a Borgoscuro?",a="La famiglia di Sven fu colpita da una tragedia che lo rese un vigilante amareggiato e determinato. Sven e Lars vivono nella natura selvaggia anziché sotto la protezione di The Night Watch a Borgoscuro, così possono dare la caccia in prima persona ai mali che infestano i boschi.",al={"perché vivere in un accampamento","posizione di sven's camp","perché non in città"}}},fx={e2641657={q="Perché Lars vuole che i lupi feroci vengano uccisi?",a="Isolati nella parte occidentale di Boscovespro, Sven e Lars devono cacciare per procurarsi il cibo necessario a sopravvivere. Ogni volta che Lars prova a riportare la carne all'accampamento, branchi di lupi feroci affamati lo assalgono. Eliminare i predatori protegge le scorte di cibo del loro accampamento e permette loro di concentrarsi sulla minaccia incombente del negromante Morbent Fel.",al={"perché uccidere i lupi","motivo di lars per i lupi","perché lars vuole uccidere i lupi"}},["8ad2a450"]={q="Che cosa sono i lupi feroci che si aggirano nella parte occidentale di Boscovespro?",a="Queste bestie feroci si aggirano nei boschi e lungo le rive del fiume a nord e a est dell'accampamento di Sven. Spinti da una fame estrema e da una malattia dilagante, i lupi feroci, affamati e rabbiosi, sono diventati spazzini sconsiderati, attratti all'istante dalla carne fresca e una minaccia mortale per chiunque attraversi le terre selvagge occidentali.",al={"cosa sono i lupi","lupi feroci affamati a boscovespro","lupi feroci rabbiosi"}},["6ca73ecd"]={q="Perché Lars non può occuparsi dei lupi da solo?",a="Lars e Sven sono soli ai margini più remoti del territorio, ben oltre la portata della Guardia Notturna o delle guardie di Roccavento. Impegnato a prepararsi allo scontro con Morbent Fel e a malapena in grado di dedicarsi alla caccia quotidiana, Lars semplicemente non può permettersi di affrontare branchi interi di lupi feroci senza l'aiuto di un avventuriero.",al={"perché lars non uccide i lupi","perché chiedere a me di occuparmi dei lupi","perché non lars"}}},fp="19,185,17.272.0,18.254.0,12.199.0,30.140.0,38.228.0,19.203.0,50.188.0,42.229.0"}
P.entries["quest:2260"] = {n="Erion's Behest",s="A Darnassus, Erion Shadewhisper invia i ladri elfi della notte più promettenti oltre il Grande Mare. Vedendoli affinare le loro abilità furtive, li indirizza a Roccavento perché facciano rapporto all'intelligence di Roccavento.",h="A Darnassus, Erion Shadewhisper invia i ladri elfi della notte più promettenti oltre il Grande Mare.",kw={"darnassus","erion shadewhisper","erion's behest","città vecchia","renzik stiletto","ladro","si:7","roccavento"},ang={["class:Rogue"]="Da ladro, lasci le schermaglie locali di Kalimdor per dedicarti allo spionaggio continentale e all'addestramento letale del SI:7.",["faction:Alliance"]="Come membro dell'Alleanza, puoi vedere il SI:7 coordinare le operazioni segrete e inviare esploratori capaci di ogni razza alleata dove servono alla corona.",["race:NightElf"]="Da elfo della notte, lasciare Darnassus e Teldrassil per servire l'intelligence umana nei vicoli di pietra di Roccavento può provocarti un forte shock culturale."},sec={{t="Una convocazione oltre il mare",b="I ladri elfi della notte si addestrano all'ombra di Teldrassil sotto la guida di mentori come Erion Shadewhisper. Quando uno di loro mostra un talento eccezionale, la voce arriva ben oltre l'Albero del Mondo. Tramite Erion, l'intelligence di Roccavento, detta anche SI:7, ti invita oltre il Grande Mare, nella capitale umana."},{t="Entrare al servizio del SI:7",b="Dal nord di Kalimdor, raggiungi Roccavento passando per i moli di Rivafosca o delle Paludi Grigie. Nella capitale, ti rechi al quartier generale del SI:7 nella Città Vecchia e fai rapporto a Renzik \"Stiletto\". Valuta le reclute e apre loro la strada verso lo spionaggio avanzato, la maestria nei veleni e le operazioni segrete per l'Alleanza."}},faq={{q="Chi mi manda in questa missione?",a="Erion Shadewhisper, l'istruttore dei ladri di Darnassus, ti manda da loro quando le tue prime imprese attirano l'attenzione delle reti di intelligence oltre il mare.",al={"datore di missione","erion shadewhisper","chi mi ha dato questo"}},{q="Perché l'intelligence di Roccavento contatta un elfo della notte?",a="L'Alleanza si affida al SI:7 per coordinare intelligence segreta e sabotaggi, accanto alle tradizioni furtive degli elfi della notte. L'intelligence di Roccavento cerca ladri capaci di ogni razza dell'Alleanza da arruolare.",al={"perché si:7","perché roccavento","perché agli umani importa"}},{q="Dove trovo Renzik \"Stiletto\"?",a="Renzik \"Stiletto\" si trova nel quartier generale del SI:7, nella Città Vecchia di Roccavento.",al={"posizione di renzik","dov'è stiletto","trovare renzik"}},{q="Questa missione è solo per i ladri?",a="Sì. Questo incarico dell'Alleanza guida i ladri da Kalimdor a Roccavento, il centro dell'addestramento dell'intelligence dell'Alleanza.",al={"solo ladro","altre classi possono farlo","è una missione da ladro"}},{q="Cosa succede dopo aver incontrato Renzik?",a="Facendo rapporto a Renzik entri nelle operazioni di addestramento del SI:7 nei Regni Orientali. Ti attendono addestramenti specializzati e incarichi segreti in tutte le terre umane.",al={"missione successiva","cosa ottengo","dopo renzik"}},{q="Come fa un elfo della notte ad arrivare a Roccavento a questo stadio?",a="Puoi salpare da Auberdine, a Rivafosca, e attraversare il mare fino al Porto di Roccavento.",al={"come arrivare a roccavento","viaggio verso roccavento","percorso per roccavento"}}},fx={["4c3449b0"]={q="Perché Erion Shadewhisper ti manda a Roccavento?",a="Erion Shadewhisper agisce in seguito a una convocazione formale dell'Intelligence di Roccavento. La tua crescente reputazione di furfante è giunta alle orecchie degli umani al di là del Grande Mare, e SI:7 ha chiesto proprio di te. Erion sa che la gilda clandestina della Città Vecchia offre addestramento specializzato e risorse ben superiori a quelle disponibili nelle tranquille ombre di Teldrassil, e ti esorta ad approfittarne invece di restare isolato a Darnassus.",al={"perché mandare a roccavento","motivo di erion shadewhisper","perché l'incarico di erion"}}},fp="14,198,24.270.0,28.321.0,29.144.0,53.208.0,34.75.0,30.117.0,34.165.0,57.85.0"}
P.entries["quest:2281"] = {n="Redridge Rendezvous",s="A Borgolago, promettenti ladri dell'Alleanza si addestrano per incarichi pericolosi sotto la guida di operativi esperti. L'SI:7 li manda a est, dal quartier generale dell'intelligence di Roccavento, per prepararli al campo.",h="A Borgolago, promettenti ladri dell'Alleanza si addestrano per incarichi pericolosi sotto la guida di...",kw={"borgolago","lucius","redridge rendezvous","renzik lo sgherro","missione ladro","si:7","roccavento"},ang={["class:Rogue"]="Da ladro, qui inizi il tuo servizio ufficiale sul campo per l'SI:7. Passi dai furti nei vicoli allo spionaggio di Stato pianificato.",["faction:Alliance"]="Da membro dell'Alleanza, vedi il braccio clandestino di Roccavento estendersi fino a insediamenti periferici come Borgolago, dove sono di stanza operativi discreti."},sec={{t="Una Misura di Sopravvivenza",b="Renzik \"Lo Sgherro\", secondo in comando dell'SI:7 a Roccavento, sa che i ladri senza addestramento raramente sopravvivono alle operazioni pericolose. Mandare reclute inesperte in territorio ostile causa perdite invece di ottenere informazioni. Perciò l'SI:7 manda gli agenti promettenti a est, nelle Montagne Crestarossa. Lì Lucius li addestra tra i moli di Borgolago."},{t="Occhi a Borgolago",b="Borgolago offre a Lucius un buon terreno per l'addestramento clandestino. Gnoll e orchi del Roccianera minacciano la città di frontiera. I suoi moli gli permettono di mettere alla prova furtività, riflessi e capacità di scasso di un ladro senza attirare l'attenzione degli abitanti o delle guardie."}},faq={{q="Chi assegna la missione Redridge Rendezvous?",a="Renzik \"Lo Sgherro\", un maestro delle spie goblin nella Città Vecchia di Roccavento, assegna l'incarico dal quartier generale dell'SI:7 ai ladri che rispondono al comando dell'intelligence.",al={"chi inizia redridge rendezvous","datore di missione redridge rendezvous","chi assegna la missione"}},{q="Dove si trova Lucius?",a="Lucius aspetta lungo i moli di legno di Borgolago, nelle Montagne Crestarossa, tra perdigiorno del posto e pescatori in riva all'acqua.",al={"dove si trova lucius","posizione di lucius","trovare lucius"}},{q="Perché l'SI:7 invia i ladri nelle Crestarossa?",a="Renzik ritiene che i ladri inesperti non siano adatti a pericolosi incarichi d'intelligence. A Borgolago, Lucius ne affina le abilità ancora grezze e ne mette alla prova capacità come borseggio e scasso nelle condizioni della frontiera.",al={"perché borgolago","scopo di redridge rendezvous","perché crestarossa"}},{q="Cosa succede dopo aver completato Redridge Rendezvous?",a="Riferire a Lucius porta a esercitazioni alla Segheria di Alther, dove l'agente mette alla prova furtività e destrezza manuale.",al={"prossima missione","seguito di redridge rendezvous","dopo redridge rendezvous"}},{q="Questa missione è disponibile per classi diverse dai ladri?",a="No. Redridge Rendezvous è per i ladri dell'Alleanza e fa parte del loro addestramento sul campo dell'SI:7.",al={"i guerrieri possono fare redridge rendezvous","è solo per ladri","requisito di classe"}},{q="Perché Renzik lavora per l'intelligence di Roccavento?",a="Pur essendo un goblin, Renzik \"Lo Sgherro\" è un fidato luogotenente del maestro delle spie Mathias Shaw. Supervisiona l'accoglienza e l'addestramento degli operativi dalla roccaforte dell'SI:7.",al={"perché un goblin nell'si:7","storia di renzik","goblin a roccavento"}}},fx={da1ebf68={q="Perché Renzik ha bisogno di me per questo incarico?",a="SI:7 ha bisogno di nuovi agenti capaci di svolgere pericolose operazioni segrete, ma Renzik sa che gettare un furfante inesperto direttamente in missioni sul campo equivale praticamente a condannarlo a morte. Per non sprecare un talento promettente, ti manda da Lucius proprio perché tu possa affinare le tue abilità prima di affrontare missioni che potrebbero costarti la vita.",al={"perché io, renzik","perché scegliere me a redridge","perché mandarmi da lucius"}}},fp="19,183,21.327.0,17.237.0,40.154.0,24.120.0,38.206.0,48.117.0,53.85.0,48.160.0"}
P.entries["quest:2282"] = {n="Segheria di Alther",s="Lucius manda i ladri dell'Alleanza a mettere alla prova la loro abilità alla Segheria di Alther. Si trova a nord-est di Borgolago, lungo la strada, dove gli orchi di Roccianera si stanno avvicinando.",h="Lucius manda i ladri dell'Alleanza a mettere alla prova la loro abilità alla Segheria di Alther.",kw={"segheria di alther","orchi di roccianera","borgolago","scasso","lucius","montagne crestarossa","si:7","attrezzi da scasso","emblema del ladro"},ang={["class:Rogue"]="In quanto ladro, ricevi i tuoi attrezzi da scasso e le credenziali sul campo mentre metti alla prova la tua pazienza e furtività vicino agli orchi di Roccianera.",["faction:Alliance"]="In quanto membro dell'Alleanza, aiuti ad addestrare ladri e infiltrati vicino a Borgolago, tenendo d'occhio i movimenti di Roccianera."},sec={{t="Una prova di grazia e destrezza",b="Lucius ti manda a nord-est da Borgolago, lungo la strada per la Segheria di Alther, con il tuo primo set di attrezzi da scasso. Lì, un baule chiuso metterà alla prova la tua abilità. Apri la cassetta personale di Lucius e riportagli il gettone all'interno per ottenere l'Attestato di Ladro."},{t="Ombre attorno alle seghe",b="La Segheria di Alther un tempo era un avamposto per il taglio del legname. Ora gli orchi di Roccianera avanzano nelle Montagne Crestarossa e si sono avvicinati, così Lucius ne fa parte della prova. La SI:7 si aspetta che i suoi agenti scassinino serrature senza farsi vedere mentre attraversano territori in mano al nemico."}},faq={{q="Qual è lo scopo della missione alla Segheria di Alther?",a="Lucius mette alla prova sul campo la tua abilità nello scassinare serrature. Ti dà degli attrezzi da scasso e ti chiede di recuperare un gettone da un baule chiuso, come prova della tua abilità.",al={"perché andare alla segheria di alther","scopo della missione","cosa fa questa missione"}},{q="Chi è Lucius?",a="Lucius addestra ladri a Borgolago, nelle Montagne Crestarossa. Forma le reclute inviate da contatti in tutta l'Alleanza, mettendo alla prova la loro furtività e abilità manuale.",al={"chi è lucius","lucius borgolago","chi dà questa missione"}},{q="Dove si trova la Segheria di Alther?",a="La Segheria di Alther si trova poco distante dalla strada a nord-est e a est di Borgolago, ai piedi delle colline, prima dei passi montani più elevati.",al={"dove si trova la segheria","posizione segheria di alther","come trovo la segheria di alther"}},{q="Perché ci sono orchi attorno alla Segheria di Alther?",a="Gli orchi del clan di Roccianera sono scesi da Guardamasso e dalle creste infuocate sovrastanti. Fanno razzie negli insediamenti umani e stabiliscono avamposti in tutte le Montagne Crestarossa, anche nei dintorni della segheria abbandonata.",al={"perché ci sono orchi qui","orchi di roccianera crestarossa","chi controlla la segheria di alther"}},{q="Quale ricompensa concede Lucius al completamento dell'incarico?",a="Lucius ti assegna l'Attestato di Ladro. Attesta la tua padronanza di molle e grimaldelli e la tua preparazione a servire come ladro da campo certificato.",al={"qual è la ricompensa","attestato di ladro","ricompensa completamento missione"}},{q="In che modo questa missione si inserisce nell'addestramento dei ladri in tutta l'Alleanza?",a="I ladri di tutte le terre dell'Alleanza ricevono dai contatti, come gli agenti della SI:7 di Mathias Shaw a Roccavento, l'indicazione di incontrare Lucius a Borgolago. La prova alla Segheria di Alther è l'ultimo esame pratico del loro addestramento di base sul campo.",al={"catena missioni ladro","collegamento si:7","seguito di redridge rendezvous"}}},fx={bca91f0e={q="Perché Lucius ti manda alla Segheria di Alther?",a="Lucius addestra i furfanti in erba per l'Alleanza e vuole mettere alla prova la tua abilità pratica sotto pressione. Collocare uno scrigno chiuso a chiave proprio vicino alla Segheria di Alther, in una zona invasa dagli orchi Roccianera, ti costringe a dimostrare di saper davvero scassinare serrature in un ambiente ostile, invece che in un'aula confortevole.",al={"motivo di lucius","perché lucius vuole che lo faccia","perché mandarmi alla segheria di alther"}},["7e02fd2a"]={q="A cosa serve l'Emblema del Ladro?",a="L'Emblema del Ladro è la prova del tuo operato. Chiuso a chiave nello scrigno di Lucius, dimostra concretamente che sei riuscito a infiltrarti nella Segheria di Alther, forzare la serratura e andartene senza farti scoprire. Riportandolo, otterrai da Lucius l'Attestato di Ladro ufficiale.",al={"a cosa serve l'emblema del ladro","che cos'è l'emblema del ladro","scopo dell'emblema del ladro"}}},fp="13,151,27.269.0,23.241.0,52.148.0,14.159.0,31.126.0,40.198.0,55.153.0,64.218.0"}
P.entries["quest:23"] = {n="Ursangous's Paw",s="The Ashenvale Hunt ti ha portato Ursangous's Paw. Portala a Senani Cuore Tonante all'Avamposto di Troncorotto e guadagna onore tra i cacciatori dell'Orda.",h="The Ashenvale Hunt ti ha portato Ursangous's Paw.",kw={"valtetra","caccia di valtetra","orso","emblema a mezzaluna","zampa","senani cuore tonante","avamposto di troncorotto","ursangous"},ang={["class:Hunter"]="Da cacciatore, seguire le tracce e sconfiggere uno dei predatori più antichi e letali di Valtetra mette alla prova le tue capacità sul campo, la tua abilità di sopravvivenza e il tuo talento in combattimento.",["faction:Horde"]="Come membro dell'Orda, puoi guadagnare onore all'Avamposto di Troncorotto sconfiggendo il pericoloso Ursangous.",["race:Tauren"]="Come cacciatore tauren, prendere la zampa di Ursangous rende onore alla bestia. Dimostra la tua determinazione marziale e il rispetto per gli spiriti della caccia."},sec={{t="Un trofeo della Grande Caccia",b="I cacciatori dell'Avamposto di Troncorotto danno la caccia alle antiche bestie che dominano la volta arborea di Valtetra. Ursangous è tra le più feroci. Uccide viaggiatori e guerrieri che incrociano il suo cammino, quindi la sua zampa prova che la bestia possente è caduta sotto i tuoi colpi."},{t="Il legame con gli Elfi della Notte",b="Sulla zampa di Ursangous compare un marchio a quarto di luna, inciso o impresso. Senani Cuore Tonante riconosce nel segno l'influenza kaldorei. Gli Elfi della Notte addestrano e stringono legami con formidabili bestie della foresta per proteggere i loro confini sacri. Ursangous potrebbe aver sorvegliato quei confini o essere servito all'Alleanza come arma."}},faq={{q="Cos'è Ursangous?",a="Ursangous è un orso eccezionalmente enorme e letale che vaga per Valtetra. Cacciatori e viandanti lo temono. Ha mietuto innumerevoli vittime prima che la caccia dell'Orda lo abbattesse.",al={"chi è ursangous","orso ursangous","tradizioni su ursangous"}},{q="Cosa significa l'emblema a mezzaluna sulla zampa?",a="Quando esamini il trofeo, il marchio a quarto di luna sulla zampa di Ursangous è un mistero. Senani Cuore Tonante potrà esaminarlo quando le porterai la zampa.",al={"marchio a mezzaluna sulla zampa","emblema sulla zampa","perché c'è una mezzaluna"}},{q="A chi devo portare la Ursangous's Paw?",a="Porta Ursangous's Paw a Senani Cuore Tonante, la cacciatrice tauren all'Avamposto di Troncorotto, nella parte orientale di Valtetra.",al={"dove consegnare la zampa","chi vuole la zampa di ursangous","posizione senani cuore tonante"}},{q="Come si inserisce tutto ciò in The Ashenvale Hunt?",a="Ursangous è una delle tre grandi bestie cacciate a Valtetra, insieme a Shadumbra e Sharptalon. Sconfiggile tutte e presenta i loro trofei per completare il rito.",al={"catena di missioni della caccia di valtetra","cos'è la caccia","serie di missioni di caccia"}},{q="Perché l'Orda dà la caccia alle grandi bestie di Valtetra?",a="I cacciatori dell'Orda all'Avamposto di Troncorotto, soprattutto tauren e orchi, danno la caccia a queste bestie letali per mettere alla prova la loro abilità marziale. Limitano anche le minacce vicino alle vulnerabili linee di rifornimento e agli accampamenti.",al={"perché cacciare gli orsi","tradizioni di caccia di avamposto di troncorotto"}},{q="Cosa succede dopo aver consegnato la zampa?",a="Dopo aver raccolto il trofeo di Ursangous e quelli delle altre prede designate, Senani Cuore Tonante riconoscerà il tuo trionfo nella prova conclusiva, The Hunt Completed.",al={"missione successiva alla zampa","cosa segue ursangous"}}},fp="15,147,26.230.0,24.306.1,18.173.0,46.149.0,34.108.0,42.161.0,55.188.0,38.173.0"}
P.entries["quest:230"] = {n="Sven's Camp",s="Sulle colline occidentali di Boscovespro, Sven Yorgen piange ancora la sua famiglia uccisa e cerca risposte. Un diario sepolto nella sua fattoria in rovina potrebbe rivelare chi assistette al massacro.",h="Sulle colline occidentali di Boscovespro, Sven Yorgen piange ancora la sua famiglia uccisa e cerca risposte.",kw={"cavalieri oscuri","boscovespro","cumulo di terra smossa","the shadowy figure","sven yorgen","fattoria yorgen"},ang={["faction:Alliance"]="Come membro dell'Alleanza, puoi aiutare a indagare sul massacro degli Yorgen mentre l'Alleanza cerca di comprendere le forze oscure che minacciano Boscovespro."},sec={{t="Indizio nella terra",b="Trovi un piccolo libro macchiato di terra sotto la terra smossa di fresco nella fattoria Yorgen in rovina. I cavalieri oscuri colpirono mentre Sven Yorgen era lontano, uccidendo la sua famiglia e riducendo la fattoria in rovine. Il dolore e la vendetta spinsero i suoi alleati a cercare tra i resti. Qualcuno aveva nascosto in fretta il libro lì."},{t="Un testimone silenzioso",b="Nel suo accampamento sulle colline occidentali, Sven scopre cosa contiene il diario. Le pagine rivelano che una The Shadowy Figure sconosciuta assistette al massacro della sua famiglia. La scoperta non gli dà pace. Ora Sven cerca il testimone e pretende risposte."}},faq={{q="Qual è il libro trovato nel cumulo di terra?",a="Il libro è un piccolo diario senza titolo, macchiato di terra e sepolto nella fattoria Yorgen. Le sue pagine rivelano che una The Shadowy Figure non identificata assistette al massacro della famiglia di Sven Yorgen.",al={"che libro è questo","libro dalla fattoria di sven","cosa ho dissotterrato"}},{q="Dove porta questa missione?",a="Consegnare il libro a Sven Yorgen dà inizio alla ricerca del misterioso testimone e conduce a The Shadowy Figure.",al={"what comes next","prossima missione dopo sven's camp","chi è la shadowy figure"}},{q="Dove si trova Sven Yorgen?",a="Sven si è rifugiato in un accampamento sulle colline nordoccidentali di Boscovespro. Piange la sua famiglia e prepara la vendetta.",al={"dove si trova sven","posizione di sven yorgen","dove consegno questa missione"}},{q="Perché il libro era sepolto alla fattoria?",a="Il libro giaceva nascosto nella terra smossa, tra i resti della fattoria. Chi assistette alla scena potrebbe averlo lasciato cadere o nascosto in fretta.",al={"perché sepolto","chi ha nascosto il libro","cumulo di terra smossa"}},{q="Chi ha ucciso la famiglia di Sven?",a="I cavalieri oscuri provenienti dal Valico Ventomorto massacrarono la famiglia di Sven mentre lui era lontano dalla fattoria.",al={"chi ha attaccato la fattoria","chi ha ucciso la famiglia di sven","assassini della famiglia di sven"}},{q="Quale fazione può completare questa missione?",a="Solo i membri dell'Alleanza possono aiutare Sven Yorgen, che cerca sostegno tra i difensori di Boscovespro e nell'Alleanza.",al={"è solo per l'alleanza","l'orda può fare l'accampamento di sven"}}},fp="11,161,18.288.0,16.220.1,44.171.0,32.112.0,29.114.0,36.131.0,25.89.0,37.101.0"}
P.entries["quest:2300"] = {n="SI:7",s="Da Borgodoro, i giovani ladri promettenti vengono mandati a presentarsi a Renzik \"Stiletto\" a Roccavento. Lì entri al servizio del Maestro Mathias Shaw, dove ti attendono missioni segrete.",h="Da Borgodoro, i giovani ladri promettenti vengono mandati a presentarsi a Renzik \"Stiletto\" a Roccavento.",kw={"keryn sylvius","mathias shaw","città vecchia","renzik stiletto","ladro","guardiacolle","si:7","roccavento"},ang={["class:Rogue"]="In quanto ladro, questa convocazione ti porta dalle missioni locali al servizio come agente del ramo ufficiale d'intelligence di Roccavento.",["faction:Alliance"]="In quanto membro dell'Alleanza, puoi rivolgerti al SI:7 per missioni di spionaggio pericolose, fuori dalla portata dei normali marescialli e fanti."},sec={{t="Una convocazione nella Città Vecchia",b="Alla Locanda del Fiero Leone, Keryn Sylvius osserva le reclute locali di Borgodoro. Dimostri astuzia e capacità contro la crescente minaccia dei Defias, e Sylvius ti trasmette un messaggio dal quartier generale. Presentati subito a Renzik \"Stiletto\". Lasci i campi di Elwynn per unirti ai ranghi segreti di Roccavento."},{t="Gli occhi nascosti di Roccavento",b="Dietro un'anonima caserma nella Città Vecchia, a Roccavento, si trova il quartier generale dell'agenzia segreta della città. Il Maestro Mathias Shaw ne comanda le operazioni in tutto il regno e oltre. L'agenzia si occupa di operazioni segrete, ricognizione e assassinii.\n\nRenzik \"Stiletto\" è il vice dal linguaggio tagliente di Shaw. Valuta gli agenti promettenti, poi li manda in missioni pericolose fuori dalla portata dell'esercito regolare del regno."}},faq={{q="Chi mi invia a fare rapporto al SI:7?",a="Keryn Sylvius, l'addestratrice di ladri alla Locanda del Fiero Leone a Borgodoro, ti manda a presentarti al SI:7. Dopo che dimostri la tua abilità sul campo, Sylvius ti ordina di recarti al quartier generale di Roccavento.",al={"chi assegna la missione","datore di missione","keryn sylvius"}},{q="Chi è Renzik \"Stiletto\"?",a="Renzik \"Stiletto\" è un agente goblin e il vice del SI:7 alle dipendenze del Maestro Mathias Shaw. Valuta gli agenti sul campo e coordina le missioni segrete d'intelligence dal quartier generale nella Città Vecchia.",al={"renzik stiletto","chi è renzik","renzik"}},{q="Cos'è il SI:7?",a="Il SI:7, o Intelligence di Roccavento, si occupa di spionaggio segreto, ricognizione e assassinii per il Regno di Roccavento. Guidati da Mathias Shaw, i suoi agenti raccolgono informazioni sulle minacce che le guardie e i soldati del regno non possono affrontare.",al={"cos'è il si7","cosa fa il si7","intelligence di roccavento"}},{q="Dove si trova il quartier generale del SI:7?",a="Il quartier generale del SI:7 si trova nella parte orientale della Città Vecchia, a Roccavento. L'agenzia opera da una sala di gilda fortificata e da una caserma d'addestramento, lontane dalle strade principali.",al={"dove si trova il si7","posizione si7","dove si trova renzik"}},{q="Cosa succede dopo aver fatto rapporto a Renzik?",a="Dopo che ti presenti a Renzik, lui mette alla prova la tua preparazione. Poi ti manda fuori dalle mura della città a incontrare un agente di stanza a Redridge.",al={"prossima missione","cosa succede dopo","redridge rendezvous"}},{q="Perché Keryn Sylvius mi chiama 'pesce'?",a="\"Pesce\" è un termine gergale per indicare un novizio inesperto o una nuova recluta. Gli agenti dell'agenzia usano soprannomi coloriti e pungenti per tenere i novellini con i piedi per terra, finché non dimostrano il loro valore sul campo.",al={"perché chiamato pesce","significato di pesce"}}},fx={d2c94cb8={q="Perché Keryn Sylvius mi manda da SI:7?",a="Keryn Sylvius sta eseguendo ordini provenienti dall'alto. Renzik \"Stiletto\" ha fatto sapere espressamente che ti stava cercando, e Keryn sa bene che non si ignora una convocazione del secondo in comando di Mathias Shaw. Nella gerarchia clandestina dei servizi segreti di Roccavento, quando Renzik richiede un agente, intermediari come Keryn trasmettono subito l'ordine senza far attendere il quartier generale.",al={"perché keryn mi manda","motivo di keryn sylvius","perché presentarsi a si:7"}},fe886311={q="Perché SI:7 ha bisogno di me invece che dei propri agenti?",a="Renzik \"Stiletto\" ha chiesto espressamente di te, per nome. Come furfante emergente che opera nella rete dell'Alleanza, rappresenti una nuova risorsa al di fuori dello sguardo diretto degli avversari locali. Shaw e Renzik si affidano spesso ad agenti sul campo capaci e da poco messisi alla prova per incarichi discreti in tutto il regno, dove volti esperti e conosciuti potrebbero attirare attenzioni indesiderate.",al={"perché io per si:7","perché renzik mi vuole","perché convocarmi"}}},fp="4,166,21.292.0,23.413.0,31.202.0,25.204.0,13.239.0,39.159.0,39.136.1,38.183.0"}
P.entries["quest:231"] = {n="A Daughter's Love",s="Sarah Ladimore ti chiede di portare il suo anello alla tomba di Morgan Ladimore. L’incontro riguarda l’anima tormentata di Morgan.",h="Sarah Ladimore ti chiede di portare il suo anello alla tomba di Morgan Ladimore.",kw={"l’amore di una figlia","archeus","tomba","lys","morgan ladimore","anello","sarah ladimore"},ang={["class:Paladin"]="Morgan dice che Archeus è stata forgiata per fare del bene e ti chiede di portare avanti la Luce attraverso di essa."},sec={{t="Alla tomba",b="Quando porti l’anello di Sarah Ladimore alla tomba di Morgan Ladimore, una voce risponde nel vento. Morgan si chiede se Sarah sia ancora viva e dice che l’anello gli toglie un peso dalle spalle. Ti affida la sua spada, Archeus, e ti chiede di tenere l’anello mentre parla a Lys, il suo amore."}},faq={{q="Cosa succede quando porto l’anello di Sarah alla tomba di Morgan?",a="Una voce risponde nel vento. Morgan si chiede se Sarah sia ancora viva e dice che l’anello gli toglie un peso dalle spalle.",al={"anello di sarah tomba","anello di morgan ladimore","finale l’amore di una figlia"}},{q="Chi è la voce alla tomba?",a="Morgan Ladimore parla con una voce spettrale nel vento.",al={"voce spettrale","chi parla alla tomba","morgan fantasma"}},{q="Cosa mi dà Morgan?",a="Morgan ti dà la sua spada, Archeus.",al={"spada di morgan","spada archeus","prendere archeus"}},{q="Cosa mi chiede Morgan di tenere?",a="Morgan ti chiede di tenere l’anello di Sarah.",al={"tenere l’anello","anello di morgan","anello alla tomba"}},{q="Chi è Lys?",a="Morgan chiama Lys il suo amore.",al={"lys morgan","amore di morgan","lys ladimore"}}},fp="17,124,12.293.1,60.121.0,30.54.0,25.36.0,32.39.0,11.26.0"}
P.entries["quest:233"] = {n="Coldridge Valley Mail Delivery",s="A Forgiamara, Sten Braccioforte ti manda a ovest con la posta per gli esploratori oltre il lago ghiacciato. La neve e i trogg nelle vicinanze possono isolare i difensori della valle, impedendo la consegna di notizie importanti.",h="A Forgiamara, Sten Braccioforte ti manda a ovest con la posta per gli esploratori oltre il lago ghiacciato.",kw={"forgiamara","valle crestafredda","dun morogh","grelin barbabianca","consegna posta","sten braccioforte","talin occhioforte"},ang={["faction:Alliance"]="Come membro dell'Alleanza, aiuti a mantenere collegati gli avamposti della Valle Crestafredda, un aspetto importante per coordinare la difesa di Dun Morogh.",["race:Dwarf"]="Come nano, portare notizie tra gli avamposti aiuta a mantenere collegati ai loro clan gli esploratori dispersi per la valle, lontani da Forgiardente.",["race:Gnome"]="Come gnomo che vive tra gli alleati di Dun Morogh dopo la caduta di Gnomeregan, portare messaggi aiuta a conquistare la fiducia dei difensori nani locali."},sec={{t="Un Corriere nella Neve",b="La posta proveniente da ogni angolo di Dun Morogh raggiunge Forgiamara attraverso il passo montano, dove i corrieri invernali la lasciano accumulare. Sten Braccioforte si occupa dei rifornimenti e della sicurezza, così le reclute portano i pacchi lungo la strada occidentale. Senza il tuo aiuto, i messaggi importanti restano nella sala."},{t="Avamposti di Frontiera",b="Talin Occhioforte sorveglia il lago ghiacciato a ovest di Forgiamara, in cerca di trogg e fauna selvatica pericolosa. Anche in un avamposto gelido, le notizie da Forgiardente e dagli accampamenti circostanti sono importanti. Le dure condizioni montane rendono difficile smistare la posta, così le lettere destinate a diversi esploratori possono finire nello stesso pacco."}},faq={{q="Chi avvia la consegna della posta?",a="Sten Braccioforte ti affida la consegna fuori da Forgiamara. Le lettere sono appena arrivate attraverso il passo montano, ma i suoi incarichi gli impediscono di portarle di persona.",al={"datore di missione","chi assegna coldridge valley mail delivery","missione di sten braccioforte"}},{q="Dove si trova Talin Occhioforte?",a="Talin Occhioforte è accampato a ovest di Forgiamara, accanto alla strada vicino al lago ghiacciato nella Valle Crestafredda.",al={"dove si trova talin occhioforte","posizione di talin occhioforte","trovare talin occhioforte"}},{q="Tutte le lettere nella catasta sono destinate a Talin?",a="No. Talin trova una lettera per Grelin Barbabianca, che si trova qui vicino, nella valle.",al={"la posta è tutta per talin","lettera di grelin barbabianca","posta smarrita"}},{q="Perché Sten ha bisogno di un avventuriero per recapitare la posta?",a="Le incursioni dei trogg e le minacce locali tengono Sten e gli altri difensori nani occupati con i rifornimenti e la sicurezza. Viaggiatori e reclute possono portare lettere agli avamposti più lontani.",al={"perché recapitare la posta","perché sten non la consegna","dovere di consegna posta"}},{q="Questa missione porta ad altri incarichi?",a="Sì. Dopo la consegna, Talin ti chiede di portare la lettera recapitata per errore a Grelin Barbabianca, proseguendo le consegne della posta.",al={"missione successiva","catena di consegna posta","seguito di consegna posta"}},{q="Da dove provenivano originariamente le lettere?",a="Le lettere sono arrivate attraverso il passo nella Valle Crestafredda, dalle terre più ampie di Dun Morogh e Forgiardente.",al={"da dove viene la posta","origine delle lettere"}}},fx={bf556c8e={q="Perché Sten Braccioforte vuole che le lettere vengano consegnate?",a="È appena arrivato un nuovo fascio di corrispondenza attraverso il passo montano, ma Sten è impegnato con i suoi doveri a Forgiamara e non può allontanarsi per consegnarlo. Per evitare che notizie e dispacci importanti prendano polvere mentre i montanari sul campo attendono aggiornamenti, si affida a un viaggiatore disponibile perché li porti a destinazione in tutta sicurezza.",al={"perché consegnare le lettere","motivo di sten braccioforte","perché consegnare la posta"}}},fp="30,181,21.258.0,17.299.0,29.159.0,31.99.0,52.86.1,49.173.0,36.124.1,43.108.0"}
P.entries["quest:234"] = {n="Coldridge Valley Mail Delivery",s="Nella Valle Crestafredda, un dispaccio parte dalla postazione di Talin Occhioforte e raggiunge l'accampamento di Grelin Barbabianca. Lo porti lungo la strada sud-orientale, mantenendo i montanari in contatto con Forgiardente.",h="Nella Valle Crestafredda, un dispaccio parte dalla postazione di Talin Occhioforte e raggiunge l'accampamento...",kw={"valle crestafredda","corriere","dun morogh","grelin barbabianca","forgiardente","consegna posta","talin occhioforte"},ang={["faction:Alliance"]="Come membro dell'Alleanza, fai affidamento sulle rotte dei corrieri attraverso i passi innevati, che portano ordini e informazioni vitali agli esploratori più isolati.",["race:Dwarf"]="Come nano, fai affidamento sui dispacci dalla sede di re Magni a Forgiardente per coordinare le difese di Dun Morogh."},sec={{t="Un legame con la montagna",b="Forgiamara è il centro del potere nella Valle Crestafredda. Da lì, esploratori e sentinelle sul campo portano dispacci lungo i sentieri tra gli alti passi e Forgiardente."},{t="Messaggio per Barbabianca",b="Grelin Barbabianca tiene un piccolo accampamento a sud-est della postazione di Talin Occhioforte. I montanari veterani in questi punti di osservazione remoti affrontano gelide derive e le continue molestie dei trogg. Le lettere regolari li tengono aggiornati sugli affari di tutta Dun Morogh e del regno oltre."}},faq={{q="Chi è Grelin Barbabianca?",a="Grelin Barbabianca è un veterano nano di un avamposto lungo la strada sud-orientale della Valle Crestafredda. Sorveglia le strade e difende la zona da trogg e bestie.",al={"grelin","informazioni su grelin barbabianca","chi è grelin"}},{q="Dove ha avuto origine questa lettera?",a="La lettera arriva da Forgiardente, la capitale dei nani. Corrieri e sentinelle del posto l'hanno trasportata attraverso la Valle Crestafredda e giù per i passi montani fino al destinatario.",al={"origine della lettera","lettera di forgiardente","mittente della lettera"}},{q="Perché qui la posta viene consegnata a piedi?",a="I corrieri a piedi portano la posta attraverso la Valle Crestafredda, perché le vette circostanti la isolano dalle strade principali di Dun Morogh. Viaggiatori fidati e montanari portano i dispacci a mano agli accampamenti sul campo.",al={"perché corriere a piedi","perché consegnare posta","nessuna cassetta postale a crestafredda"}},{q="Dove si trova l'accampamento di Grelin Barbabianca?",a="L'accampamento di Grelin Barbabianca si trova più avanti lungo la strada sud-orientale della Valle Crestafredda, oltre i terreni di caccia e di esplorazione del passo superiore.",al={"dove si trova l'accampamento di grelin","posizione di grelin barbabianca","trovare grelin"}},{q="Chi ha consegnato la lettera da portare a Grelin?",a="Talin Occhioforte, cacciatore ed esploratore di stanza lungo il passo, ti ha consegnato la lettera. Arriva dai terreni di raduno vicino a Forgiamara.",al={"chi ha dato la lettera","ruolo di talin occhioforte","chi inizia la missione"}},{q="Cosa succede dopo che Grelin riceve la sua posta?",a="Dopo aver ricevuto notizie da Forgiardente, Grelin si occupa dei pericoli della valle. Spesso manda le reclute contro i troll Freddomanto e i trogg.",al={"cosa succede dopo la posta","prossima missione di grelin","dopo la consegna della posta"}}},fx={c573251b={q="Perché Talin Occhioforte vuole che questa consegna venga fatta?",a="Talin Occhioforte è di stanza al freddo lungo la strada e sa che Grelin Barbabianca attende notizie al suo accampamento. Avendo ricevuto il dispaccio da Forgiamara, Talin vuole assicurarsi che il suo compagno nano riceva finalmente la corrispondenza da Forgiardente, invece di lasciarlo bloccato e all'oscuro nella valle.",al={"perché talin vuole che venga consegnata","motivo di talin occhioforte","perché mandare la lettera a grelin"}},d47c3713={q="Perché Talin Occhioforte ti chiede di consegnare la lettera invece di portarla lui stesso?",a="Talin Occhioforte è di guardia lungo la strada della Valle Crestafredda e tiene d'occhio i sentieri e la fauna locale. Abbandonare il suo posto per raggiungere a piedi l'accampamento di Grelin Barbabianca lascerebbe il passo senza sorveglianza, quindi un viaggiatore di passaggio come te è la scelta più ovvia per portare a destinazione la lettera.",al={"perché talin ha bisogno di me","perché talin non può consegnare la lettera","perché io, talin"}}},fp="30,185,22.157.0,19.257.0,25.155.0,32.162.0,35.200.0,42.147.0,47.130.0,44.144.0"}
P.entries["quest:2342"] = {n="Reclaimed Treasures",s="Patrick Garrett ti chiede di recuperare il tesoro della sua famiglia da Uldaman. Ti aspetta a Sepulcra.",h="Patrick Garrett ti chiede di recuperare il tesoro della sua famiglia da Uldaman.",kw={"forziere di famiglia","tesoro di famiglia","patrick garrett","tesori recuperati","sala comune sud","uldaman","sepulcra"},sec={{t="Un forziere di famiglia",b="Il forziere di famiglia si trova nella Sala Comune Sud di Uldaman. Patrick Garrett ti aspetta a Sepulcra per il tesoro custodito al suo interno."}},faq={{q="Chi chiede il tesoro?",a="Patrick Garrett ti chiede di portargli il tesoro della sua famiglia a Sepulcra.",al={"patrick garrett","chi lo vuole"}},{q="Dov'è il forziere di famiglia?",a="Il forziere di famiglia si trova nella Sala Comune Sud di Uldaman.",al={"posizione del forziere","dov'è il tesoro"}},{q="Dove devo portare il tesoro?",a="Porta il tesoro della famiglia di Patrick Garrett da lui a Sepulcra.",al={"dove portarlo","tesoro di sepulcra"}}},fp="19,108,14.120.0,31.75.0,26.56.0,30.64.0"}
P.entries["quest:235"] = {n="Caccia a Valtetra",s="L'Invocatore della Guerra Gorlach invia l'Orda a nord, a Valtetra, dove la sua frontiera si spinge in un'antica foresta. Devi fare rapporto a Senani Cuore Tonante all'Avamposto di Troncorotto e unirti alla caccia.",h="L'Invocatore della Guerra Gorlach invia l'Orda a nord, a Valtetra, dove la sua frontiera si spinge in...",kw={"valtetra","savane","gorlach","caccia","orgrimmar","senani","avamposto di troncorotto","cuore tonante"},ang={["class:Hunter"]="In quanto cacciatore, trovi a Valtetra un terreno di prova, tra la fitta volta degli alberi e le bestie pericolose, quando rispondi alla chiamata di Senani Cuore Tonante.",["faction:Horde"]="In quanto membro dell'Orda, ne estendi il potere oltre Durotar, in terre straniere ricche di risorse ma ostili.",["race:Tauren"]="In quanto tauren, sotto la guida di Senani Cuore Tonante porti la tua profonda riverenza per la grande caccia nella foresta selvaggia."},sec={{t="Richiamo dei Selvaggi",b="Orgrimmar ha bisogno di legname, carne e rotte commerciali sicure per continuare a crescere. L'Invocatore della Guerra Gorlach riceve ordini dall'alto comando dell'Orda e invia veterani erranti e nuovi avventurieri nelle campagne attive. Per chi diventa adulto a Durotar e nelle Savane, Valtetra è la prossima prova di abilità e sopravvivenza."},{t="Una Frontiera Insidiosa",b="A nord delle Savane, l'Orda mantiene due roccaforti a Valtetra. L'Avamposto di Troncorotto sorge nei boschi orientali, mentre l'Avamposto di Zoram'gar si trova sulla costa occidentale. Senani Cuore Tonante coordina le operazioni dall'Avamposto di Troncorotto. Organizza tracciatori e cacciatori contro le bestie sotto la volta degli alberi e le sentinelle degli elfi della notte che contestano le rivendicazioni dell'Orda."}},faq={{q="Chi assegna questa missione e dove posso trovarli?",a="L'Invocatore della Guerra Gorlach impartisce l'ordine a Orgrimmar, capitale dell'Orda. Invia avventurieri capaci nelle campagne oltre Durotar.",al={"datore di missione","dove si trova gorlach","chi assegna the ashenvale hunt"}},{q="Dove si trova l'Avamposto di Troncorotto?",a="L'Avamposto di Troncorotto sorge a nord delle Savane, nella parte orientale di Valtetra, lungo la principale strada forestale che prosegue a est verso Azshara.",al={"posizione avamposto di troncorotto","dove si trova l'avamposto di troncorotto","come raggiungere l'avamposto di troncorotto"}},{q="Chi è Senani Cuore Tonante?",a="Senani Cuore Tonante è una veterana tracciatrice tauren all'Avamposto di Troncorotto. Dirige la caccia in tutta Valtetra e valuta gli avventurieri che vogliono partecipare alle prove locali.",al={"chi è senani","posizione di senani cuore tonante","npc di consegna"}},{q="Qual è lo scopo della caccia a Valtetra?",a="La caccia a Valtetra procura selvaggina e pelli preziose. Inoltre elimina i predatori al vertice della catena alimentare che minacciano le pattuglie vicino all'Avamposto di Troncorotto e le operazioni di disboscamento circostanti.",al={"perché cacciare a valtetra","storia di the ashenvale hunt","obiettivo dell'orda a valtetra"}},{q="Quali altri avamposti controlla l'Orda a Valtetra?",a="L'Orda controlla anche l'Avamposto di Zoram'gar, all'estremo occidentale di Valtetra, lungo la Spiaggia di Zoram.",al={"basi dell'orda a valtetra","avamposto di spiaggia di zoram","avamposti di valtetra"}},{q="Questa missione comporta dei combattimenti?",a="No. Viaggi da Orgrimmar attraverso le Savane per fare rapporto a Senani Cuore Tonante. Il viaggio in sé non richiede combattimenti.",al={"ci sono combattimenti in questa missione","devo combattere qualcosa","consegna semplice"}}},fx={["70907bc1"]={q="Perché l'Invocatore della Guerra Gorlach vuole mandare avventurieri a Valtetra?",a="L'Invocatore della Guerra Gorlach fa da araldo e reclutatore a Orgrimmar, chiamando a raccolta guerrieri desiderosi di rafforzare le campagne di frontiera dell'Orda. L'Orda si è assicurata un punto d'appoggio a Valtetra con l'Avamposto di Troncorotto e l'Avamposto della Spiaggia di Zoram, ma mantenere e difendere questa presenza richiede un flusso costante di combattenti capaci. Mandandoti a partecipare alla caccia di Senani Cuore Tonante, Gorlach rafforza la frontiera settentrionale e offre alle reclute già messe alla prova l'occasione di conquistare onore e gloria per l'Orda.",al={"motivo dell'invocatore della guerra gorlach","perché mandare a valtetra","perché la caccia di gorlach"}}},fp="18,185,17.300.0,22.367.0,48.124.0,27.113.0,27.165.0,42.163.0,53.95.0,35.123.0"}
P.entries["quest:2359"] = {n="Klaven's Tower",s="Da un accampamento nelle Marche Occidentali, l'Agente Kearnen sorveglia Klaven's Tower. Spedizioni insolite e guardie mutate indicano un pericolo tra le file della Fratellanza dei Defias.",h="Da un accampamento nelle Marche Occidentali, l'Agente Kearnen sorveglia Klaven's Tower.",kw={"agente kearnen","fratellanza dei defias","forziere di boscovespro","klaven mortwake","klaven's tower","mathias shaw","veleni","si:7","marche occidentali","zanzil"},ang={["class:Rogue"]="Nei panni di un ladro dell'Alleanza, affronti un'infiltrazione segreta che richiede furtività, borseggio, scassinamento e la capacità di trovare il punto debole fisico di un nemico.",["faction:Alliance"]="I Defias di Klaven's Tower si sono alleati con i troll della giungla e l'alchimia oscura per minacciare il regno. Sono molto più che semplici mastri muratori scontenti.",["race:Human"]="Da umano difensore di Roccavento, potresti inorridire nello scoprire che ex compatrioti sono stati trasformati in droni non morti privi di volontà nelle Marche Occidentali."},sec={{t="Un appostamento nelle Marche Occidentali",b="All'estremità sud-orientale delle Marche Occidentali, il fiume scorre sotto Klaven's Tower, a nord della Catena delle Daghe. La Fratellanza dei Defias occupa la guglia di pietra, sebbene i suoi ladri e briganti umani siano comuni in tutte le pianure. L'Agente Kearnen sorveglia la torre da sola da settimane. Di recente ha notato cose insolite: una spedizione bizzarra è arrivata direttamente dai boschi ombrosi di Boscovespro, scortata da sentinelle mostruose e deformi, diverse dai comuni banditi di strada."},{t="La Guglia di Ghiaccio e la Guardia Spinata",b="Klaven Mortwake comanda la torre, dove sentinelle mutate respirano con rantoli aspri e affannosi. Tra le guardie barcollanti, un enorme zombi porta la Defias Tower Key. Sottrargliela richiede silenzio e finezza. Con la chiave, un agente può aggirare le difese al pianterreno, raggiungere i livelli superiori della roccaforte e aprire il forziere chiuso a chiave di Boscovespro."},{t="La concozione di Zanzil",b="Il diario personale di Klaven Mortwake collega i Defias, la S.P.R. & Co. e i troll della giungla della Valle di Rovotorto. Racconta che lo sciamano Zanzil ha scoperto un veleno alchemico capace di creare droni non morti, privi di volontà e obbedienti. Per il Maestro Mathias Shaw e il SI:7, questa scoperta rivela le ambizioni sempre più vaste dei Defias. I loro agenti devono conoscere a fondo i veleni."}},faq={{q="Dove si trova Klaven's Tower?",a="Klaven's Tower sorge vicino al fiume, all'estremità sud-orientale delle Marche Occidentali, a nord della Catena delle Daghe. La guglia fortificata è occupata dalla Fratellanza dei Defias.",al={"posizione klavens tower","dov'è klavens tower","posizione torre defias marche occidentali"}},{q="Chi è l'Agente Kearnen?",a="L'Agente Kearnen fa parte del servizio segreto di Roccavento, il SI:7. Da settimane sorveglia in segreto Klaven's Tower da un accampamento vicino, seguendo le spedizioni insolite e preparando un'infiltrazione.",al={"agente kearnen","chi assegna la missione klavens tower","chi è il ladro nelle marche occidentali"}},{q="Cosa rende insolite le guardie di Klaven's Tower?",a="Le sentinelle della torre sono non morti mutati, diversi dai soliti banditi umani dei Defias. Una miscela alchemica esotica, giunta nelle Marche Occidentali, li ha trasformati in lavoratori privi di volontà.",al={"perché le guardie sono zombi","guardie klaven tower","cosa sono le guardie della torre"}},{q="Come fanno i Defias ad avere servitori non morti?",a="I Defias hanno ottenuto da Zanzil una miscela tossica speciale. Zanzil è uno sciamano troll della giungla della Valle di Rovotorto. Il veleno è arrivato grazie a trattative con la S.P.R. & Co. e trasforma i soggetti viventi in droni obbedienti.",al={"come hanno ottenuto gli zombi i defias","perché i defias hanno non morti","connessione zanzil defias"}},{q="Chi è Klaven Mortwake?",a="Klaven Mortwake è un sorvegliante di alto rango dei Defias presso la torre. Ha supervisionato le spedizioni oscure da Boscovespro e tenuto un diario privato sulla loro alchimia sinistra.",al={"lore klaven mortwake","chi è klaven mortwake","klaven"}},{q="Perché a Mathias Shaw interessa il diario recuperato?",a="Il Maestro Mathias Shaw ha bisogno di informazioni utili sulle alleanze dei Defias e sui pericolosi agenti stranieri. La notizia che i troll di Zanzil possano creare non morti con il veleno avverte il SI:7 di una grave minaccia per Roccavento. Perciò l'agenzia deve addestrare i suoi agenti nell'arte dei veleni.",al={"perché mathias shaw vuole il diario","si7 veleno zanzil","mathias shaw klaven"}}},fx={af44437f={q="Perché l'Agente Kearnen vuole che venga fatto?",a="L'Agente Kearnen sorveglia la Torre di Klaven da settimane, seguendo le attività dei Defias. Quando da Boscovespro è arrivato un carico inquietante, scortato da creature disumane, ha capito che la Fratellanza dei Defias stava nascondendo qualcosa di pericoloso. Il suo compito per SI:7 è sorvegliare e raccogliere informazioni; scoprire cosa è chiuso dentro quello scrigno svelerà la sinistra impresa che i Defias stanno architettando proprio sotto il naso di Roccavento.",al={"motivo di kearnen","perché l'agente kearnen ne ha bisogno"}},["043ff283"]={q="A cosa serve la Chiave della Torre dei Defias?",a="La Chiave della Torre dei Defias permette di accedere alla roccaforte pesantemente fortificata e allo scrigno di Boscovespro custodito al suo interno. La porta una delle mostruosità grottesche e irte di spuntoni che pattugliano il perimetro: è l'unico modo per aggirare le serrature dei Defias e indagare su ciò che i loro strani alleati hanno introdotto di contrabbando nelle Marche Occidentali.",al={"defias tower key","cosa apre la torre di klaven","a cosa serve la chiave della torre"}},d5d17d25={q="Che cos'è il Diario di Klaven Vegliamorte?",a="Chiuso nello scrigno di Boscovespro in cima alla torre, questo diario contiene i resoconti e i segreti di Klaven Vegliamorte. Descrive come la Fratellanza dei Defias si sia alleata con forze esterne per preparare intrugli abietti e rivela che strane pozioni dei troll di Zanzil possono indurre uno stato di morte apparente e creare droni incapaci di disobbedire.",al={"diario di klaven vegliamorte","diario di klaven","cosa contiene il diario"}},["738a266c"]={q="Perché Agente Kearnen manda te invece di andarci di persona?",a="Agente Kearnen è un'esploratrice dei SI:7, incaricata principalmente di svolgere ricognizioni a lungo termine. Se abbandonasse la copertura per infiltrarsi in un avamposto fortificato pieno di guardie innaturali, comprometterebbe la propria posizione e metterebbe in allarme i Defias prima che i SI:7 scoprano i loro piani. Le serve un agente capace che superi le sentinelle, recuperi le informazioni e le consegni direttamente a Mathias Shaw.",al={"perché io alla torre di klaven","perché kearnen non si infiltra","perché mandare me"}}},fp="14,146,22.434.0,30.342.1,19.366.2,32.145.0,21.189.0,48.164.1,41.214.1,23.160.0,55.252.1"}
P.entries["quest:2360"] = {n="Mathias and the Defias",s="Nelle Marche Occidentali, SI:7 ha scoperto un’attività insolitamente intensa dei Defias. Ti mandano dall’Agente Kearnen, vicino a una torre di guardia dell’Alleanza abbandonata, per un resoconto.",h="Nelle Marche Occidentali, SI:7 ha scoperto un’attività insolitamente intensa dei Defias.",kw={"agente kearnen","defias","mathias","crestarossa","guardiacolle","si:7","torre di guardia","marche occidentali"},ang={["faction:Alliance"]="I Defias hanno preso una torre di guardia dell’Alleanza abbandonata nelle Marche Occidentali e la usano come base per il contrabbando."},sec={{t="La torre di guardia",b="I Defias hanno preso una torre di guardia dell’Alleanza abbandonata a sud-est di Guardiacolle. SI:7 riferisce che la usano come base per contrabbandare merci lungo la rotta dei rifornimenti di Crestarossa. Ti mandano nelle Marche Occidentali a cercare l’Agente Kearnen, nascosta vicino alla torre, e a ricevere il suo resoconto."}},faq={{q="Cosa succede nelle Marche Occidentali?",a="SI:7 segnala un’attività insolitamente intensa dei Defias nelle Marche Occidentali. I Defias hanno preso una torre di guardia dell’Alleanza abbandonata e la usano per contrabbandare merci lungo la rotta dei rifornimenti di Crestarossa.",al={"defias nelle marche occidentali","attività dei defias nelle marche occidentali"}},{q="Dov’è la base dei Defias?",a="La base dei Defias è una torre di guardia dell’Alleanza abbandonata a sud-est di Guardiacolle.",al={"torre dei defias","dov’è la loro base"}},{q="Chi è l’Agente Kearnen?",a="L’Agente Kearnen è l’agente di SI:7 che ti mandano a cercare vicino alla torre per un resoconto.",al={"kearnen","chi è kearnen"}},{q="Cosa vuole che faccia SI:7?",a="SI:7 ti manda nelle Marche Occidentali a cercare l’Agente Kearnen, nascosta vicino alla torre, e a ricevere un resoconto.",al={"incarico di si:7","trovare kearnen"}},{q="Cosa contrabbandano i Defias?",a="I Defias contrabbandano merci lungo la rotta dei rifornimenti di Crestarossa.",al={"merci dei defias","rifornimenti di crestarossa"}}},fp="22,143,15.264.0,30.173.0,25.80.0,21.85.0,29.98.0,30.62.0"}
P.entries["quest:237"] = {n="In Defense of the King's Lands",s="Nella parte meridionale di Loch Modan, il Montanaro Ghiaiadoro chiede aiuto contro i trogg Pietrarotta. Con le forze naniche impegnate sul fronte dell'Alleanza, gli avamposti locali si affidano ai volontari per tenere la linea.",h="Nella parte meridionale di Loch Modan, il Montanaro Ghiaiadoro chiede aiuto contro i trogg Pietrarotta.",kw={"ghiaiadoro","forgiardente","loch modan","montanaro","veggente","spaccateschi","pietrarotta","trogg","valle dei re"},ang={["faction:Alliance"]="Questa missione mostra il costo della guerra più ampia dell'Alleanza. Mentre le sue forze mettono al sicuro terre lontane, le patrie dei suoi stessi membri restano vulnerabili alle minacce locali.",["race:Dwarf"]="Da nano, difendere la Valle dei Re è una questione personale. È un omaggio ai più grandi sovrani di Forgiardente, e i trogg profanano quella terra mentre i tuoi consanguinei sanguinano su campi di battaglia lontani. È un boccone amaro da mandare giù."},sec={{t="Una difesa sottile",b="I Montanari che sorvegliano il passo meridionale verso Dun Morogh sono pochi. Re Magni Barbabronzea ha inviato gran parte delle forze di Forgiardente sul più ampio fronte dell'Alleanza, lasciando le torri della Valle dei Re a corto di fanteria regolare. Perciò il Montanaro Ghiaiadoro chiama i volontari a colpire la Valle Pietrarotta e tenere a bada i trogg. I rinforzi potrebbero non arrivare mai."},{t="Sciamani e Picchiatori Pietrarotta",b="I trogg Pietrarotta non sono privi di senno né vagano senza meta. Le loro bande da guerra combattono con forza bruta e rozza magia elementale. Ghiaiadoro vuole che i loro veterani Spaccateschi e i Veggenti, che guidano con poteri mistici, siano estromessi dal combattimento. Senza quei capi, gli accampamenti meridionali della tribù perdono ogni ordine e non riescono a radunarsi contro la strada per Forgiardente."},{t="Tristi notizie dal fronte",b="Quando torni a riferire, Ghiaiadoro ha notizie cupe. I rinforzi nanici promessi non arriveranno. Le pesanti perdite sul lontano fronte dell'Alleanza hanno prosciugato le riserve di Forgiardente, lasciando i Montanari locali e i mercenari di passaggio a difendere Loch Modan."}},faq={{q="Dove si trova il Montanaro Ghiaiadoro?",a="Il Montanaro Ghiaiadoro si trova nella torre di guardia meridionale lungo la strada che attraversa la Valle dei Re. Sorveglia il passo tra Loch Modan e Dun Morogh.",al={"posizione di ghiaiadoro","dov'è ghiaiadoro","consegna ghiaiadoro"}},{q="Perché i Montanari nanici sono così a corto di uomini?",a="Re Magni Barbabronzea ha inviato gran parte dell'esercito regolare di Forgiardente sul più ampio fronte dell'Alleanza. Mentre lì le perdite aumentano, i posti di frontiera di Loch Modan restano con guarnigioni ridotte all'osso e devono affidarsi ai volontari di passaggio.",al={"perché niente guardie naniche","dove sono i rinforzi","esercito di forgiardente loch modan"}},{q="Dove si possono trovare gli Spaccateschi e i Veggenti Pietrarotta?",a="Gli Spaccateschi e i Veggenti Pietrarotta si radunano soprattutto negli accampamenti meridionali della Valle Pietrarotta, a est della Valle dei Re. Alcuni infestano anche l'isola più settentrionale del Loch.",al={"posizione spaccateschi pietrarotta","posizione veggente pietrarotta","dove sono i trogg"}},{q="Perché prendere di mira specificamente gli Spaccateschi e i Veggenti?",a="Gli Spaccateschi sono le truppe d'assalto della tribù Pietrarotta, mentre i Veggenti brandiscono rozza magia e guidano i trogg minori. Sconfiggerli entrambi priva la tribù della sua forza e coordinazione.",al={"perché uccidere i veggenti","perché gli spaccateschi","bersagli trogg"}},{q="Dove ti manda Ghiaiadoro dopo?",a="Ghiaiadoro ti manda dal Montanaro Muroforte, nella torre di guardia meridionale della Valle dei Re, per contribuire alla difesa della valle.",al={"prossima missione ghiaiadoro","chi è muroforte","dopo difesa delle terre del re"}}},fx={c78d8208={q="Perché Montanaro Ghiaiadoro vuole che venga fatto?",a="Montanaro Ghiaiadoro cerca di guadagnare tempo prezioso per i difensori di Loch Modan. I trogg Scheggiaterra si spingono senza sosta nella valle meridionale, mentre le truppe naniche sono disperatamente necessarie sui lontani campi di battaglia dell'Alleanza. Indebolendo le forze d'invasione, spera di mantenere sicuri i passi meridionali finché non arriveranno rinforzi da Forgiardente.",al={"perché uccidere i trogg","motivo di ghiaiadoro","motivo della difesa delle terre del re"}}},fp="30,199,14.366.0,34.347.0,27.248.1,39.150.0,48.213.0,61.184.0,48.179.0,35.130.1"}
P.entries["quest:2378"] = {n="Find the Shattered Hand",s="Un ladro Reietto delle Radure di Tirisfal è diretto a Orgrimmar, dove lo attende The Shattered Hand. I Deathstalkers mandano il promettente iniziato oltre il mare, a Durotar, per apprendere le arti specialistiche del clan.",h="Un ladro Reietto delle Radure di Tirisfal è diretto a Orgrimmar, dove lo attende The Shattered Hand.",kw={"spelonca delle ombre","deathstalkers","mennet carkad","orgrimmar","missione ladro","shattered hand","shenthul"},ang={["class:Rogue"]="Da ladro, passi dall'addestramento locale alla più ampia rete criminale e clandestina dell'Orda. A Kalimdor incontri gli addestratori del mondo sotterraneo.",["faction:Horde"]="Come membro dell'Orda, vedi la collaborazione tra i servizi segreti di Orgrimmar e Sepulcra, oltre i fanti e gli sciamani in prima linea.",["race:Undead"]="Da giovane ladro Reietto, ti lasci alle spalle i resti del Flagello di Lordaeron e raggiungi il cuore dell'Orda a Durotar."},sec={{t="Una Lega d'Ombre",b="Mennet Carkad ha visto un ladro dimostrare il proprio valore nelle Radure di Tirisfal. I Reietti addestrano il proprio ordine segreto, i Deathstalkers. La loro alleanza con l'Orda apre la strada ad arti più oscure. Mennet indirizza così i ladri promettenti verso The Shattered Hand a Orgrimmar, unendo gli agenti non morti di Lordaeron agli assassini orcheschi di Kalimdor."},{t="Nella Spelonca delle Ombre",b="Il viaggio termina sotto Orgrimmar, nella Spelonca delle Ombre. Stregoni, ladri e legademoni operano lì lontano da occhi indiscreti. Shenthul, addestratore di The Shattered Hand, attende l'agente non morto appena arrivato. Il burbero troll accoglie l'inviato con aspro scetticismo. La sola reputazione non gli basta: vuole scoprire se l'inviato possiede vera astuzia o ha sprecato il viaggio attraverso il Grande Mare."}},faq={{q="Chi assegna la missione Find the Shattered Hand?",a="Mennet Carkad, addestratore dei Deathstalkers nel Rogues' Quarter di Sepulcra, ti manda in missione dopo che hai dimostrato le tue abilità di base nelle Radure di Tirisfal.",al={"chi inizia find the shattered hand","missione mennet carkad","chi mi manda a orgrimmar"}},{q="Dove si trova Shenthul?",a="Shenthul si trova nella Spelonca delle Ombre, la buia voragine sotto i passaggi centrali di Orgrimmar.",al={"trovare shenthul","posizione di shenthul","dov'è shenthul a orgrimmar"}},{q="Qual è il rapporto tra i Deathstalkers e The Shattered Hand?",a="I Deathstalkers sono la rete d'intelligence e la gilda di assassini dei Reietti. The Shattered Hand svolge un ruolo simile per l'Orda a Orgrimmar. I due ordini sono alleati ufficiali: condividono addestramento avanzato e incarichi clandestini in tutta l'Orda.",al={"deathstalkers e shattered hand","ladri reietti ladri orchi","perché mandato a orgrimmar"}},{q="Perché Shenthul mi definisce poco stimolante?",a="Shenthul ti definisce poco stimolante perché The Shattered Hand dà valore alla resistenza fisica e all'astuzia spietata. Insulta i nuovi arrivati per spezzarne l'orgoglio e mettere alla prova la loro capacità di sopportare un rigoroso addestramento da assassini.",al={"dialogo di shenthul","perché shenthul è cattivo","testo di completamento di shenthul"}},{q="Cosa succede dopo aver raggiunto Shenthul?",a="Shenthul ti affida a Zando'zan, poi ti manda a sud, verso Porto Paranco, per operazioni sul campo nelle Savane.",al={"cosa viene dopo find the shattered hand","prossima missione dopo shenthul","catena shattered hand"}},{q="I ladri che non sono Reietti possono ricevere questa missione?",a="No. I Deathstalkers affidano questa versione ai ladri Reietti. I ladri orchi e troll a Durotar ricevono una missione equivalente, chiamata «To Orgrimmar!».",al={"ladro orco find the shattered hand","versione troll","alternativa to orgrimmar"}}},fx={aa6bb2de={q="Perché Mennet Carkad vuole che vada a Orgrimmar?",a="Mennet Carkad riconosce che, sebbene tu abbia servito bene i Deathstalkers e dimostrato talento nella furtività e nell'inganno, per ora hai raggiunto i limiti di ciò che puoi imparare a Sepulcra. Per affinare ulteriormente la tua letale arte, vuole che ti avventuri nel vasto territorio dell'Orda. Mandandoti alla Shattered Hand a Orgrimmar, Mennet sfrutta l'alleanza tra le due fazioni di assassini, assicurandoti un insegnamento avanzato da parte di veterani ladri orcheschi, che possono insegnarti tecniche sconosciute alle ombre di Lordaeron.",al={"perché mandarmi a orgrimmar","motivo di mennet carkad","perché trovare la shattered hand"}}},fp="23,206,19.336.0,24.387.0,44.142.0,26.88.0,74.255.0,38.209.0,37.114.0,39.148.0"}
P.entries["quest:2379"] = {n="Zando'zan",s="Nella Spelonca delle Ombre di Orgrimmar, Shenthul manda un ladro promettente da Zando'zan.",h="Nella Spelonca delle Ombre di Orgrimmar, Shenthul manda un ladro promettente da Zando'zan.",kw={"spelonca delle ombre","scassinamento","orgrimmar","ladro","shattered hand","shenthul","furtività","wrenix","zando'zan"},ang={["class:Rogue"]="Da ladro, entri nei ranghi segreti della Shattered Hand. Cominci come combattente con il coltello senza addestramento e ti prepari a diventare un agente riconosciuto dell'Orda.",["faction:Horde"]="La Shattered Hand si occupa dello spionaggio e delle operazioni segrete dell'Orda, proteggendola dalle minacce nascoste. Il capoguerra parla di onore e assalti frontali."},sec={{t="Una passeggiata nell'ombra",b="I governanti di Orgrimmar sanno che la sola forza non basta a vincere ogni guerra. Sotto la città si trova la Spelonca delle Ombre, dimora della Shattered Hand, una gilda segreta al servizio dell'Orda con spionaggio, sabotaggio e furti. Quando l'istruttore dei ladri Shenthul vede del potenziale in un iniziato, lo manda da Zando'zan per addestrarlo come agente."},{t="Dimostrare il proprio valore",b="Prima di concedere il suo rispetto, Zando'zan mette alla prova ogni ladro inesperto che entra nella caverna. Incontrarlo segna l'inizio dell'addestramento formale in furtività, sotterfugio e furto. Le sue lezioni colmano il divario tra i rozzi borseggiatori di strada e gli agenti dell'intelligence organizzata. Da lì, i ladri si preparano al lavoro sul campo, oltre la sicurezza delle pareti del canyon rosso della capitale."}},faq={{q="Chi è Zando'zan?",a="Zando'zan addestra i ladri e si occupa delle reclute della Shattered Hand nella Spelonca delle Ombre di Orgrimmar. Mette alla prova i nuovi arrivati e insegna loro furtività, scasso e lavoro operativo.",al={"zandozan","chi è zando'zan","zando'zan spelonca delle ombre"}},{q="Perché Shenthul manda i ladri da Zando'zan?",a="Shenthul manda i ladri promettenti da Zando'zan per l'addestramento specialistico della Shattered Hand. Zando'zan insegna a scassinare e manomettere serrature per le missioni segrete sul campo.",al={"perché parlo con zando'zan","shenthul zando'zan","scopo della missione"}},{q="Cos'è la The Shattered Hand a Orgrimmar?",a="La Shattered Hand nacque su Draenor come clan orchesco brutale, noto per le mutilazioni rituali. Divenne il braccio segreto dell'Orda, dedito all'intelligence e agli assassinii. Dalle ombre di Orgrimmar, i suoi membri praticano spionaggio, uso dei veleni e ricognizione.",al={"cos'è la shattered hand","shattered hand orgrimmar","ladri dell'orda shattered hand"}},{q="Dove porta questa catena di addestramento?",a="Dopo aver fatto rapporto a Zando'zan, ti manda a Porto Paranco, sulla costa delle Savane. Lì consulti Wrenix, un contatto goblin, e inizi le esercitazioni pratiche di scasso sul campo.",al={"prossima missione","cosa succede dopo zando'zan","wrenix of ratchet"}},{q="Dove posso trovare Zando'zan?",a="Zando'zan lavora nella Spelonca delle Ombre, una rete di caverne nelle profondità del centro di Orgrimmar. Stregoni, sacerdoti dell'ombra e agenti ladri si radunano lì, lontano dalla luce del giorno.",al={"posizione di zando'zan","dov'è zando'zan","come trovare zando'zan"}},{q="Perché Zando'zan si scusa quando mi incontra?",a="Forse Zando'zan dubitava del tuo coraggio prima del tuo arrivo. Vedendoti pronto ad addestrarti, riconosce il tuo impegno e ritira il suo dubbio iniziale.",al={"perché zandozan si scusa","dialogo di completamento zando'zan"}}},fx={["1d4b3aab"]={q="Perché Shenthul affida questo addestramento a te invece che a un altro ladro?",a="Shenthul riconosce la tua determinazione, ma sa che il puro zelo non basta per sopravvivere alle battaglie segrete che attendono l'Orda. Hai dimostrato di meritare di andare oltre le basi della strada, ma per servire davvero la Shattered Hand devi essere formato ufficialmente come agente dedicato. Shenthul manda proprio te perché il tuo percorso e il tuo potenziale hanno attirato l'attenzione vigile della gilda.",al={"perché io per shenthul","perché zando'zan manda me","perché sono stato scelto"}}},fp="9,145,23.316.0,19.351.0,17.182.0,47.156.0,40.245.0,41.164.1,27.176.0,45.149.0"}
P.entries["quest:2380"] = {n="To Orgrimmar!",s="Kaplak invia un giovane ladro da Tranciacolle a nord, verso Orgrimmar. Devi trovare Shenthul nella Spelonca delle Ombre ed entrare nella rete di The Shattered Hand.",h="Kaplak invia un giovane ladro da Tranciacolle a nord, verso Orgrimmar.",kw={"spelonca delle ombre","kaplak","tranciacolle","ladro","the shattered hand","shenthul","to orgrimmar"},ang={["class:Rogue"]="Da ladro, entri nella rete segreta della capitale sotto la supervisione di Shenthul. Il lavoro si sposta su veleni, furti e inganni oltre le scaramucce di frontiera.",["faction:Horde"]="Come membro dell'Orda, senti la tensione tra il nuovo e onorevole cammino di Thrall e le più antiche organizzazioni dei clan che resistono sotto Orgrimmar."},sec={{t="Una Convocazione nelle Ombre",b="Kaplak ti manda a nord da Tranciacolle verso Orgrimmar. La tua abilità crescente ha attirato l'attenzione di agenti più influenti, anche se la tua tecnica è ancora acerba. Lasci alle spalle le rocce rosse di Durotar e ti dirigi verso la capitale."},{t="Sotto l'Occhio Vigile di Thrall",b="Shenthul ti accoglie nella Spelonca delle Ombre, sotto Orgrimmar. Osserva con inquietudine le riforme politiche del Capoguerra Thrall. The Shattered Hand non può proteggere i propri interessi solo con la forza o la sfida aperta. Pazienza, sotterfugi e inganno l'aiutano a sopravvivere e a preservare la propria influenza."}},faq={{q="Chi mi invia in questa missione?",a="Kaplak, l'addestratore di ladri a Tranciacolle, ti manda a nord dopo che le tue abilità attirano l'attenzione di agenti più esperti a Orgrimmar.",al={"datore di missioni","chi assegna to orgrimmar","missione kaplak"}},{q="Dove trovo Shenthul?",a="Trovi Shenthul nella Spelonca delle Ombre, un quartiere sotterraneo sotto Orgrimmar dove si radunano ladri, stregoni e altri emarginati.",al={"posizione shenthul","dove si trova shenthul","spelonca delle ombre shenthul"}},{q="Qual è l'agenda di The Shattered Hand a Orgrimmar?",a="The Shattered Hand è una gilda di spionaggio e assassini all'interno dell'Orda. Shenthul osserva con inquietudine le onorevoli riforme di Thrall, e la gilda fa affidamento sulla furtività per sopravvivere e preservare la propria influenza.",al={"motivi di the shattered hand","perché the shattered hand a orgrimmar","the shattered hand thrall"}},{q="Perché vengo mandato proprio in questa fase?",a="Le tue prime ricognizioni e scaramucce hanno dimostrato le tue capacità, perciò entri al servizio formale della gilda. Si comincia con lo scassinamento e il lavoro sul campo sotto copertura nella capitale.",al={"missione ladro livello 16","perché andare a orgrimmar ora","convocazione addestramento ladro"}},{q="Questa missione differisce da 'Find the Shattered Hand'?",a="Entrambi i percorsi portano i ladri da Shenthul a Orgrimmar. Quello che ricevi dipende da dove ti addestri o ricevi ordini, e ciascuno fa proseguire la stessa catena di addestramento.",al={"find the shattered hand vs to orgrimmar","missione alternativa"}},{q="Cosa succede dopo aver fatto rapporto a Shenthul?",a="Shenthul mette alla prova le tue capacità e ti fa proseguire lungo la catena. Incontri contatti come Zando'zan, poi intraprendi missioni segrete con contatti goblin a Porto Paranco.",al={"missione successiva a to orgrimmar","cosa dà shenthul"}}},fx={a9995c5c={q="Perché Kaplak vuole che vada a Orgrimmar?",a="Kaplak agisce su ordine diretto dei suoi superiori. Pur riconoscendo che sei ancora ben lontano dal padroneggiare la furtività, i tuoi talenti in erba hanno attirato l'attenzione di Shenthul in persona. La Shattered Hand ha bisogno di agenti astuti, addestrati per i suoi piani segreti, e il compito di Kaplak è indirizzare ladri promettenti come te verso le ombre più profonde della capitale, dove potrai iniziare il vero addestramento.",al={"perché kaplak mi manda","motivo di kaplak","perché andare a orgrimmar"}}},fp="13,150,24.224.0,27.282.1,27.128.0,25.134.0,49.207.0,47.179.0,54.156.0,41.164.0"}
P.entries["quest:2381"] = {n="Plundering the Plunderers",s="Vicino a Porto Paranco, Wrenix il Miserabile manda nuove reclute di The Shattered Hand contro i Bucanieri dei Mari del Sud. A bordo della Tide Razor, affrontano pirati, forzieri chiusi a chiave e un pericoloso guardiano prima di reclamare il Tesoro dei Mari del Sud.",h="Vicino a Porto Paranco, Wrenix il Miserabile manda nuove reclute di The Shattered Hand contro i Bucanieri dei...",kw={"e.c.a.c.","scasso","plundering the plunderers","polly","porto paranco","pirati mari del sud","tesoro dei mari del sud","tè di sboccialesto","tide razor","wrenix il miserabile"},ang={["class:Rogue"]="Da ladro, impari a scassinare serrature sotto pressione e ricevi il Tè di Sboccialesto, una bevanda pregiata per gli agenti al servizio dell’Orda.",["faction:Horde"]="The Shattered Hand si serve di contatti goblin a Porto Paranco per mettere alla prova i potenziali agenti contro i Bucanieri dei Mari del Sud, che minacciano la costa delle Savane.",["profession:Cooking"]="Da ladro appassionato di cucina, puoi guadagnare il Tè di Sboccialesto, un tonico alle erbe apprezzato perché ripristina l’energia."},sec={{t="Una prova di furtività e acciaio",b="Wrenix il Miserabile mette alla prova gli aspiranti agenti di The Shattered Hand a Porto Paranco. Manda i ladri a sud, lungo la costa delle Savane, fino a una baia dove la Tide Razor è all’ancora. I Bucanieri dei Mari del Sud presidiano la nave. I ladri devono salire a bordo senza farsi vedere e raggiungere il covo dei pirati, dove si addestrano i borseggiatori. Poi scassinano i forzieri nella stiva e riportano il bottino."},{t="Polly e il marchingegno",b="Wrenix avverte che i ladri venuti prima sono tornati da lui a pezzi. Un pappagallo feroce di nome Polly sorveglia la stiva più bassa della nave. Per aiutare un ladro ad affrontare l’uccello, Wrenix fornisce un E.C.A.C. sperimentale. Dopo aver forzato il forziere dei pirati, lancia il congegno contro Polly. Lo disorienta e lo indebolisce, rendendo possibile vincere lo scontro."}},faq={{q="Chi è Wrenix il Miserabile?",a="Wrenix il Miserabile è un contatto goblin ladro a Porto Paranco. Collabora con agenti legati a The Shattered Hand di Orgrimmar e manda nuovi ladri in territorio pirata per esercitarsi con le serrature e recuperare il bottino rubato.",al={"wrenix","chi è wrenix","missione ladro goblin porto paranco"}},{q="Dove si trova la Tide Razor?",a="La Tide Razor è all’ancora a sud di Porto Paranco, lungo la costa orientale delle Savane, in una baia dei Bucanieri dei Mari del Sud. La nave è la base e il covo d’addestramento dei pirati.",al={"posizione tide razor","dove si trova la nave pirata","dove sono i pirati dei mari del sud"}},{q="Cos'è un E.C.A.C. e come lo uso?",a="L’E.C.A.C. è un congegno goblin sperimentale distribuito dall’Apparato Gizmotronico di Wrenix. Usalo contro Polly, il pappagallo gigante che sorveglia il Tesoro dei Mari del Sud nella stiva della Tide Razor. Indebolisce l’uccello, così puoi sconfiggerlo.",al={"ecac","cos'è l'ecac","come sconfiggere polly"}},{q="Perché l'area di scasso sulla nave è significativa?",a="Il secondo ponte della Tide Razor ospita la sala d’addestramento dei pirati dei Mari del Sud. Le sue cassette con serratura permettono ai ladri di esercitarsi sul campo prima di tentare di scassinare il forziere sottostante.",al={"pratica di scasso","nave addestramento ladri","scassinare forzieri savane"}},{q="Perché questa missione è così vitale per i ladri?",a="Il colpo dimostra il valore di un ladro alla rete di The Shattered Hand. Wrenix ti dà il Tè di Sboccialesto come tua parte, una bevanda che ripristina rapidamente l’energia da combattimento di un ladro.",al={"missione ladro tè di sboccialesto","perché fare plundering the plunderers","ricompensa missione ladro"}},{q="Chi è Polly?",a="Polly è un pappagallo feroce che sorveglia la stiva inferiore della Tide Razor per i Bucanieri dei Mari del Sud. Senza la tecnologia goblin per indebolire l’uccello, Polly è letale per gli infiltrati inesperti.",al={"polly","pappagallo gigante","boss tide razor"}}},fx={d00111f9={q="Perché Wrenix il Miserabile vuole il tesoro dei Mari del Sud?",a="Wrenix è un astuto ladro e faccendiere goblin che opera da Porto Paranco e vuole il bottino illecito dei Bucanieri dei Mari del Sud come ricco compenso. I precedenti tentativi di saccheggiare la nave dei pirati si sono rivelati disastrosi: altri cinque ladri sono morti, fatti a pezzi. Mandandoti a infiltrarti nell'imbarcazione e recuperare il bottino, Wrenix si assicura un ricco premio e mette alla prova il tuo valore contro i tagliagole che l'hanno rubato per primi.",al={"motivo di wrenix","perché rubare il tesoro dei mari del sud","perché wrenix vuole che venga fatto"}},abe44597={q="Perché Wrenix ha bisogno di te invece di assoldare delle guardie o andare di persona?",a="Rubare ai Bucanieri dei Mari del Sud è un lavoro delicato e illecito, che non può essere svolto con la forza bruta o con le guardie neutrali di Porto Paranco. I pirati addestrano i propri ladri a bordo della Lama delle Maree: serve qualcuno esperto in furtività e scassinamento, capace di intrufolarsi nella stiva senza farsi notare. Essendo un goblin che opera al di fuori dei normali accordi commerciali, Wrenix preferisce assoldare un agente capace e sacrificabile invece di rischiare la pelle.",al={"perché io per wrenix","perché mandare un ladro","perché wrenix non recupera il tesoro"}}},fp="25,225,27.350.0,19.321.1,27.216.0,32.160.0,40.233.0,52.168.0,40.165.0,13.187.0"}
P.entries["quest:2382"] = {n="Wrenix of Ratchet",s="A Orgrimmar, Wrenix of Ratchet attira i ladri dell'Orda verso un porto goblin molto a sud. Zando'zan ti manda ad aiutare Wrenix il Miserabile, un goblin poco raccomandabile a Porto Paranco.",h="A Orgrimmar, Wrenix of Ratchet attira i ladri dell'Orda verso un porto goblin molto a sud.",kw={"porto paranco","ladro","shattered hand","le savane","thrall","wrenix","zando'zan"},ang={["class:Rogue"]="Come ladro dell'Orda, lasci la sicurezza di Orgrimmar ed entri nel territorio neutrale dei pirati. È un passo essenziale del tuo addestramento.",["faction:Horde"]="Come membro dell'Orda, sai che The Shattered Hand tiene occhi e orecchie oltre i confini di Durotar. L'ordine si affida spesso a porti neutrali come Porto Paranco per gli incarichi delicati."},sec={{t="Un profeta nell'ombra",b="Nella Spelonca delle Ombre, la gilda dei ladri di Orgrimmar opera tra anfratti tortuosi, perlopiù invisibile. Zando'zan è un troll che accoglie gli agenti con farneticazioni selvagge e presagi oscuri. Parla del Capoguerra Thrall, abbattuto dal veleno e da una lama. Poi non spiega la visione e manda gli agenti a sud, a Porto Paranco, una città portuale nelle Savane."},{t="Il risolutore di problemi di Porto Paranco",b="Porto Paranco si trova sulla costa delle Savane, a est del Crocevia. Mascalzoni, mercenari e inventori si radunano in questo porto neutrale, dove vive Wrenix il Miserabile. Wrenix ha poca pazienza per gli strani metodi di Zando'zan. Dice che le reclute precedenti del troll hanno fatto una brutta fine nella baia, in pasto ai suoi affamati predatori."}},faq={{q="Chi ti manda a Porto Paranco?",a="Zando'zan, un troll dei The Shattered Hand nella Spelonca delle Ombre di Orgrimmar, ti manda a sud dopo averti parlato di strane visioni.",al={"chi assegna la missione","datore di missione","zandozan"}},{q="Chi è Wrenix il Miserabile?",a="Wrenix il Miserabile è un contatto goblin a Porto Paranco. Si occupa di operazioni segrete e rifornimenti meccanici per i ladri di tutte le Savane.",al={"chi è wrenix","wrenix porto paranco","identità di wrenix"}},{q="Cosa è successo agli agenti inviati prima di me?",a="Wrenix dice che i cinque agenti mandati prima di te da Zando'zan hanno fallito i loro incarichi e sono diventati cibo per squali al largo della costa di Porto Paranco.",al={"ladri precedenti","cibo per squali","altre reclute"}},{q="Di cosa parlava Zando'zan a proposito di Thrall?",a="Zando'zan dice di aver visto Thrall abbattuto alle spalle da un pugnale avvelenato. Poi si interrompe e cambia argomento.",al={"profezia di thrall","thrall avvelenato","visione di zando'zan su thrall"}},{q="Dove si trova Porto Paranco?",a="Porto Paranco si trova sulla costa orientale delle Savane, proprio a est del Crocevia. Le strade che partono a sud del Fiume Furialunga la collegano a Durotar.",al={"dove si trova porto paranco","trovare porto paranco","posizione di porto paranco"}},{q="Cosa succede dopo aver incontrato Wrenix?",a="Quando saluti Wrenix, ti affida «Saccheggiare i saccheggiatori», che ti manda a infiltrarti tra i Bucanieri dei Mari del Sud lungo la costa a sud di Porto Paranco.",al={"prossima missione","dopo wrenix","seguito missione porto paranco"}}},fx={["17a3bd65"]={q="Perché Zando'zan ti manda da Wrenix?",a="Zando'zan è sconvolto da frenetiche visioni di sventura: prevede veleno e un pugnale traditore puntato alla schiena del Capoguerra Thrall. Disperato all'idea di contrastare queste minacce invisibili che si annidano nell'ombra, il troll eccentrico si affida a contatti esterni come Wrenix il Miserabile a Porto Paranco per condurre operazioni segrete e procurare equipaggiamento specializzato.",al={"perché mandarmi da wrenix","motivo di zando'zan","perché andare da wrenix"}},["2311cb82"]={q="Perché Zando'zan manda te invece di occuparsene lui stesso?",a="Zando'zan rimane confinato nelle ombre della Spelonca delle Ombre di Orgrimmar, intento a osservare oscuri presagi e a mormorare sulle sue visioni di cospirazioni. Il suo comportamento imprevedibile e la paura di aver «parlato troppo» gli impediscono di operare apertamente sul campo, perciò si affida a ladri capaci che agiscano come suoi emissari discreti oltre le mura della città.",al={"perché mandare me","perché zando'zan ha bisogno di me","perché non andarci di persona"}}},fp="17,171,24.337.0,24.316.0,25.123.0,27.129.0,47.121.0,50.124.0,25.150.0,37.153.1"}
P.entries["quest:2383"] = {n="Cartapecora semplice",s="Nella Valle delle Sfide ti aspetta un messaggio, arrivato mentre eri via. Frang, il tuo addestratore di classe, è fuori dall'Antro del Tirocinio.",h="Nella Valle delle Sfide ti aspetta un messaggio, arrivato mentre eri via.",kw={"addestratore di classe","antro","frang","pergamena","pergamena semplice","valle delle sfide"},sec={{t="Un messaggio da Frang",b="La pergamena ti chiede di leggerne le parole e parlare con Frang. Il tuo addestratore di classe ti aspetta fuori dall'Antro del Tirocinio, nella Valle delle Sfide."}},faq={{q="Chi ha mandato la pergamena?",a="La pergamena sembra provenire da Frang, il tuo addestratore di classe.",al={"mittente della pergamena","chi l'ha scritta"}},{q="Dove posso trovare Frang?",a="Frang ti aspetta fuori dall'Antro del Tirocinio, nella Valle delle Sfide.",al={"dov'è frang","posizione di frang"}},{q="Che cosa vuole Frang?",a="Frang ha qualcosa da dirti quando sarai pronto.",al={"perché frang mi cerca","messaggio della pergamena"}},{q="Che cosa dovrei fare con la pergamena?",a="Leggi la pergamena, poi parla con Frang nella Valle delle Sfide.",al={"leggere la pergamena","pergamena semplice"}}},fp="16,121,20.128.0,23.66.0,23.52.0,21.43.0,36.66.0"}
P.entries["quest:239"] = {n="Il Presidio Rivombroso ha bisogno d'aiuto!",s="Al Presidio Rivombroso, il Vicesceriffo Rainer e le sue guardie devono affrontare una pressione crescente e hanno pochi soldati da impiegare. Il Maresciallo Dughan manda a ovest gli avventurieri disponibili, verso l'avamposto al confine tra la Foresta di Elwynn e le Marche Occidentali. L'esercito di Roccavento è disperso per tutto il regno, così il presidio deve vedersela con gli gnoll Zampafiume e i ladri erranti senza rinforzi regolari.",h="Al Presidio Rivombroso, il Vicesceriffo Rainer e le sue guardie devono affrontare una pressione crescente e...",kw={"vicesceriffo rainer","foresta di elwynn","gnoll","borgodoro","maresciallo dughan","zampafiume","presidio rivombroso"},ang={["faction:Alliance"]="Come volontario dell'Alleanza, svolgi il lavoro dei soldati regolari e aiuti a impedire che i territori centrali sprofondino nel caos più completo.",["race:Human"]="Come umano di Roccavento, noti un segno inquietante dell'abbandono del regno. Le difese della corona si sono indebolite da quando il Re è scomparso."},sec={{t="Una frontiera allo stremo",b="Il Presidio Rivombroso sorveglia il margine occidentale della Foresta di Elwynn, dove i boschi abitati incontrano le travagliate pianure delle Marche Occidentali. Le bande di guerra degli gnoll e i banditi diventano sempre più audaci lungo i corsi d'acqua e le strade occidentali, perciò il piccolo presidio ha chiesto altri uomini. Il Maresciallo Dughan e l'amministrazione di Borgodoro non hanno soldati di Roccavento da risparmiare. I comandanti locali devono assoldare mercenari di passaggio e avventurieri erranti."},{t="La minaccia oltre il ruscello",b="Il Vicesceriffo Rainer e i suoi uomini affrontano gli gnoll Zampafiume, che molestano i viaggiatori e le fattorie vicine. Il branco si aggira nelle terre di confine tra Elwynn e le Marche Occidentali. Roccavento è distratta da problemi politici e militari, e gli gnoll si spingono sempre più in profondità nelle terre abitate. Il Presidio Rivombroso sorveglia il confine per impedire che avanzino indisturbati nel cuore della foresta."}},faq={{q="Perché Roccavento non può inviare soldati regolari al Presidio Rivombroso?",a="Le forze regolari di Roccavento sono disperse lungo diverse frontiere. Con Re Varian Wrynn scomparso e il regno sconvolto da conflitti interni, l'alto comando ha rifiutato o non è riuscito a inviare soldati regolari agli avamposti rurali. Marescialli di città come Dughan devono affidarsi a volontari indipendenti.",al={"perché non ci sono truppe di roccavento","perché inviare avventurieri","dove si trova l'esercito di roccavento"}},{q="Dove si trova il Presidio Rivombroso?",a="Il Presidio Rivombroso si trova sul margine occidentale della Foresta di Elwynn. Segui la strada principale verso ovest da Borgodoro, oltrepassando il piccolo ruscello. La torre fortificata è alla tua destra, poco prima del confine con le Marche Occidentali.",al={"posizione presidio rivombroso","come arrivare a presidio rivombroso","dove si trova il vicesceriffo rainer"}},{q="Quali minacce affliggono il presidio?",a="Il Vicesceriffo Rainer deve affrontare le ripetute incursioni degli gnoll Zampafiume, oltre alla crescente attività di ladri e banditi nelle terre di confine tra le Marche Occidentali e la Foresta di Elwynn.",al={"cosa attacca il presidio rivombroso","perché rainer ha bisogno di aiuto","chi attacca il presidio rivombroso"}},{q="Chi è il Vicesceriffo Rainer?",a="Il Vicesceriffo Rainer è l'ufficiale di Roccavento al comando del Presidio Rivombroso. Deve difendere il confine occidentale e affidarsi a volontari civili e mercenari, perché i rinforzi militari ufficiali scarseggiano.",al={"lore rainer","vicesceriffo rainer","chi è rainer"}},{q="Cosa succede dopo essersi presentati al Vicesceriffo Rainer?",a="Il Vicesceriffo Rainer ti chiede aiuto contro gli gnoll Zampafiume del luogo. Mette una taglia sui loro collari per ridurne il numero e proteggere la strada di confine.",al={"what comes next","catena missioni presidio rivombroso","missione rainer"}},{q="Perché gli gnoll si stanno spingendo nella Foresta di Elwynn?",a="Gli gnoll Zampafiume hanno accampamenti lungo i fiumi che separano Elwynn dalle Marche Occidentali. Con meno soldati a presidiare il confine, sono diventati abbastanza audaci da assalire le rotte commerciali e spingersi verso le fattorie dell'entroterra di Elwynn.",al={"gnoll zampafiume elwynn","perché ci sono gli gnoll qui","problema gnoll"}}},fx={["76645dec"]={q="Perché il Maresciallo Dughan vuole che tu vada al Presidio Rivombroso?",a="Il Maresciallo Dughan è responsabile dell'ordine e della sicurezza in tutta la Foresta di Elwynn, con base a Borgodoro, ma le sue risorse sono al limite. Il Presidio Rivombroso sorveglia il confine occidentale del regno e il Vicesceriffo Rainer ha inviato un urgente avviso sull'aumento dei banditi e sull'avanzata dei gnoll. Senza truppe regolari da mandare come rinforzi, Dughan deve affidarsi ad avventurieri indipendenti perché rispondano alla richiesta d'aiuto dell'avamposto prima che il confine occidentale crolli del tutto.",al={"perché mandarmi al presidio rivombroso","motivo del maresciallo dughan","perché serve aiuto al presidio rivombroso"}}},fp="30,367,25.395.0,27.357.0,64.289.0,36.195.0,40.157.0,21.205.0,46.153.0,46.211.0"}
P.entries["quest:2399"] = {n="Piante rigogliose",s="Nel giardino di Denalan, vicino al Lago Al'ameth, la fronda piantata ha messo radici e germogliato. I nuovi germogli spuntano tra le aiuole.",h="Nel giardino di Denalan, vicino al Lago Al'ameth, la fronda piantata ha messo radici e germogliato.",kw={"denalan","erboristeria","vaso","semi","fronda scintillante","fronde germogliate","teldrassil","lago di buonpozzo"},ang={["class:Druid"]="Da druido, puoi vedere la vita prosperare grazie alle cure attente nel vaso di Denalan, mentre Teldrassil affronta pericoli crescenti.",["profession:Herbalism"]="Le ricerche di Denalan mostrano il lavoro di raccolta e studio delle piante di Teldrassil. Mostrano anche quanto rapidamente i semi locali si adattino al terreno coltivato.",["race:NightElf"]="Da kaldorei, contribuisci a vegliare sulla vita che attecchisce e cresce in tutta la tua giovane Albero del Mondo."},sec={{t="Un giardino presso il Lago Al'ameth",b="Trovi il giardino di Denalan vicino al Lago Al'ameth. Qui il botanico studia le piante peculiari di Teldrassil. Dopo aver piantato una Fronda Scintillante, nel suo vaso spuntano nuove fronde dal terreno, pronte per essere raccolte e studiate."},{t="La strana flora dell'Albero del Mondo",b="La giovane Teldrassil è immensa e le sue piante crescono rapidamente. Gli erboristi Elfi della Notte trovano questa crescita affascinante e preoccupante. Le Fronde Scintillanti e i loro germogli mostrano quanto rapidamente la vita attecchisca sui rami dell'Albero del Mondo. Eppure, la sua vitalità può essere difficile da prevedere."}},faq={{q="Cosa sono le fronde germogliate?",a="Sono le piante germogliate dopo che Denalan ha piantato una Fronda Scintillante nel suo accampamento, vicino al Lago Al'ameth. Le peculiari fronde tremano quando sono pronte per essere raccolte.",al={"fronde germogliate","cosa sono queste piante","fronde di denalan"}},{q="Dove si trova il giardino di Denalan?",a="Denalan mantiene il suo giardino e il suo campo di ricerca lungo il bordo orientale del Lago Al'ameth, a sud-est di Dolanaar a Teldrassil.",al={"posizione di denalan","dove si trova denalan","giardino del lago al'ameth"}},{q="Perché Denalan pianta queste fronde?",a="Denalan studia la crescita curiosa e rapida delle piante di Teldrassil. Pianta semi in un terreno preparato per conoscerle e verificarne le proprietà curative o erboristiche.",al={"perché piantare fronde","esperimento di denalan","scopo delle fronde"}},{q="Le fronde germogliate sono pericolose?",a="No. Queste fronde germogliate sono piante innocue, pronte per essere raccolte, a differenza di alcune piante corrotte o ostili che si trovano altrove sui rami di Teldrassil.",al={"le fronde sono pericolose","le fronde attaccano","la pianta è dannosa"}},{q="Cosa precede questa missione?",a="Gli avventurieri trovano una Fronda Scintillante nelle terre selvagge di Teldrassil e la portano a Denalan. Lui la pianta nel vaso del suo giardino, nella speranza che attecchisca.",al={"prerequisiti per fronde germogliate","quale missione viene prima"}},{q="Perché le fronde tremano?",a="Le fronde tremano mentre aspettano di essere raccolte. Non si sa cosa provochi il movimento.",al={"fronde tremanti","perché tremano"}}},fp="19,132,25.216.0,35.263.0,29.168.0,34.120.0,36.172.0,34.141.0,29.150.0,26.78.0"}
P.entries["quest:24"] = {n="La Testa di Shadumbra",s="All'Avamposto di Troncorotto, la testa di Shadumbra dimostra che un predatore temuto è stato abbattuto. Consegnarla a Senani Cuore Tonante completa una prova della The Ashenvale Hunt e contribuisce a mettere in sicurezza le strade occidentali verso la Spiaggia di Zoram.",h="All'Avamposto di Troncorotto, la testa di Shadumbra dimostra che un predatore temuto è stato abbattuto.",kw={"the ashenvale hunt","gattopardo delle notti","senani cuore tonante","shadumbra","avamposto di troncorotto","trofeo","spiaggia di zoram"},ang={["class:Hunter"]="Da cacciatore, metti alla prova la mira, la pazienza e la capacità di sopravvivere nei boschi, seguendo le tracce di una gattopardo delle notti elusiva come Shadumbra.",["faction:Horde"]="Come membro dell'Orda, contribuisci a mantenere aperte le linee di rifornimento dall'isolato Avamposto di Troncorotto alla Spiaggia di Zoram, eliminando minacce come Shadumbra.",["race:Tauren"]="Come tauren, onori l'ordine naturale della Madre Terra mettendo alla prova le tue capacità contro un predatore dominante e proteggendo i tuoi fratelli tribali lungo la strada."},sec={{t="Una minaccia per la strada occidentale",b="Shadumbra cacciava nei boschi a ovest dell'Avamposto di Troncorotto. Gli esploratori e i corrieri dell'Orda percorrevano quei sentieri per raggiungere la Spiaggia di Zoram. La sua velocità e furtività rendevano pericoloso ogni viaggio, e ogni pattuglia diretta a ovest teneva in allerta i difensori dell'avamposto."},{t="Prova della caccia",b="Senani Cuore Tonante, una cacciatrice tauren, sfida i campioni dell'Orda a rintracciare e abbattere le grandi bestie di Valtetra. La testa di Shadumbra dimostra che la cacciatrice ha ucciso uno dei predatori indigeni più letali di Kalimdor. Ora i viaggiatori possono percorrere le strade con meno pericoli."}},faq={{q="Chi era Shadumbra?",a="Shadumbra era una feroce gattopardo delle notti che si aggirava nelle foreste a ovest dell'Avamposto di Troncorotto. Tendeva agguati ai viaggiatori diretti alla costa ed era considerata una delle bestie locali più pericolose di Valtetra.",al={"cos'è shadumbra","lore di shadumbra","chi è il gatto"}},{q="Perché Senani Cuore Tonante vuole la testa?",a="Senani Cuore Tonante sovrintende alla The Ashenvale Hunt all'Avamposto di Troncorotto. La testa di Shadumbra onora una caccia difficile e conferma che i viaggiatori diretti a ovest non devono più affrontare questa minaccia.",al={"perché portare la testa","trofeo di senani cuore tonante","prova della caccia di valtetra"}},{q="Dove si inserisce questo nella The Ashenvale Hunt?",a="Shadumbra è una delle prove principali della The Ashenvale Hunt. Ucciderla insieme a grandi bestie della foresta come Ursangous e Sharptalon porta al riconoscimento finale e al completamento della caccia.",al={"cos'è la the ashenvale hunt","serie di missioni di caccia","prossima missione di caccia"}},{q="Perché eliminare questa bestia è importante per l'Orda?",a="Gli esploratori e i corrieri viaggiano a ovest dall'Avamposto di Troncorotto fino all'accampamento dell'Orda all'Avamposto di Zoram'gar, sulla Spiaggia di Zoram. Shadumbra minacciava chi attraversava a piedi i boschi selvaggi.",al={"perché importa all'orda","pericolo sulla strada per la spiaggia di zoram","sicurezza dell'avamposto di troncorotto"}},{q="Dove si può trovare Shadumbra?",a="Shadumbra si aggira nei boschi a ovest dell'Avamposto di Troncorotto. Caccia tra gli alberi, tra la strada e le antiche rovine degli Elfi della Notte sparse nella parte centrale e occidentale di Valtetra.",al={"posizione di shadumbra","dov'è shadumbra","trovare shadumbra"}},{q="Shadumbra è alleata con gli elfi della notte?",a="No. Shadumbra è una gattopardo delle notti selvatica e feroce che minaccia chiunque attraversi il suo territorio. Gli Elfi della Notte spesso addomesticano e venerano le gattopardi delle notti, ma Shadumbra segue il suo istinto predatorio.",al={"shadumbra è un animale domestico","animale domestico sentinella","shadumbra elfo della notte"}}},fp="16,210,28.231.0,17.250.0,18.190.0,43.175.0,44.180.0,50.182.0,29.181.0,41.175.0"}
P.entries["quest:240"] = {n="Return to Jitters",s="A Collecorvo, porti a Jitters il Teso un pasto preparato da Chef Grual. I tortini placano la sua fame, ma la paura continua a trattenerlo lì.",h="A Collecorvo, porti a Jitters il Teso un pasto preparato da Chef Grual.",kw={"chef grual","borgoscuro","boscovespro","tortino di granchio scuro","stomaco brontolante","jitters il teso","taverna del corvo scarlatto"},ang={["faction:Alliance"]="La dieta povera e insolita di Borgoscuro riflette quanto la città sia isolata dai rifornimenti di Roccavento. Gli abitanti si affidano a ciò che striscia nell'ombra.",["profession:Cooking"]="Chef Grual trasforma le zampe viscide dei ragni tessivelenosi in tortini appetitosi, dimostrando come la cucina sfrutti tutto ciò che offre la frontiera."},sec={{t="Una prelibatezza dubbia",b="Chef Grual cucina alla Taverna del Corvo Scarlatto di Borgoscuro. Con pochi animali da allevamento o creature marine a Boscovespro, sfrutta ciò che offre la foresta corrotta. I suoi Tortini di Granchio Scuro non contengono polpa di granchio. Al suo posto, la sua specialità sono le zampe viscide dei ragni tessivelenosi. Grual la chiama cucina ingegnosa, ma chi ha lo stomaco delicato potrebbe dissentire."},{t="Calmare i nervi di Jitters il Teso",b="A Collecorvo, Jitters il Teso trema di paura, incapace di affrontare gli orrori che lo hanno cacciato dai boschi. Il terrore gli impedisce di cacciare o cercare cibo, e la fame accresce il suo tormento. I tortini caldi gli regalano un raro momento di sollievo. Disperato per la fame, mangia senza chiedere che tipo di granchio abbia usato Grual."}},faq={{q="Cosa contengono i Tortini di Granchio Scuro?",a="I Tortini di Granchio Scuro non contengono granchio. Chef Grual usa le zampe viscide dei ragni tessivelenosi del posto e le condisce per imitare i tradizionali tortini di mare.",al={"ingredienti dei tortini di granchio","di cosa sono fatti i tortini di granchio scuro","sono vero granchio"}},{q="Jitters il Teso sa che i tortini sono fatti di bava di ragno?",a="Chef Grual tiene per sé la ricetta. Affamato e terrorizzato, Jitters il Teso mangia avidamente i tortini senza chiedere cosa contengano.",al={"jitters il teso sa","jitters il teso sa dei ragni"}},{q="Perché Jitters il Teso non riusciva a procurarsi il cibo da solo?",a="Jitters il Teso è sopraffatto dalla paura dopo ciò che ha incontrato nei boschi selvaggi di Boscovespro. Il panico lo tiene nei pressi di Collecorvo, dove dipende dai viaggiatori compassionevoli per procurarsi da mangiare.",al={"perché jitters il teso è affamato","perché jitters il teso non caccia"}},{q="Chi è Chef Grual?",a="Chef Grual cucina alla Taverna del Corvo Scarlatto di Borgoscuro. Con la città isolata da ombre e bestie, usa ingredienti insoliti che i raccoglitori gli portano per sfamare gli avventori della taverna.",al={"ruolo di chef grual","cuoco a borgoscuro"}},{q="Dove inizia questa catena di missioni?",a="Jitters il Teso chiede aiuto per la fame a Collecorvo, nella missione Jitters' Growling Gut. Dai la caccia ai ragni tessivelenosi per Chef Grual, poi torni con il pasto pronto.",al={"come iniziare la missione del cibo di jitters il teso","inizio catena missioni jitters il teso"}},{q="Jitters il Teso si riprende dopo aver mangiato?",a="Il pasto placa la fame di Jitters il Teso, che ti ringrazia di cuore. Il cibo non può alleviare il suo profondo terrore: resta ansioso e tormentato dagli oscuri segreti della foresta.",al={"jitters il teso è curato","il cibo aiuta jitters il teso"}}},fx={deba9bdd={q="Perché Chef Grual vuole che le torte di granchio siano consegnate a Jitters il Teso?",a="Chef Grual gestisce la cucina della Taverna del Corvo Scarlatto a Borgoscuro ed è orgoglioso di soddisfare le ordinazioni, anche quelle bizzarre preparate con le interiora dei ragni locali. Jitters il Teso sta morendo di fame nella pericolosa oscurità di Collecorvo, troppo spaventato per raggiungere la città. Dopo aver preparato le sue speciali torte di «granchio» alla Grual, il cuoco le affida a te perché tu soddisfi l'ordinazione di Jitters e faccia mangiare quel poveretto.",al={"perché consegnare le torte di granchio","motivo di grual e jitters","perché portare cibo a jitters"}}},fp="17,118,18.340.0,24.300.0,32.142.0,51.125.0,38.167.0,18.189.0,34.156.0,34.172.0"}
P.entries["quest:243"] = {n="Into the Field",s="A Tanaris metti alla prova le creature del deserto con il kit per analisi sul campo dello Speziale Zinge. Serve una fonte di alimentazione dei goblin di Meccania, così Zinge ti manda dal Capo Ingegnere Segachiodi.",h="A Tanaris metti alla prova le creature del deserto con il kit per analisi sul campo dello Speziale Zinge.",kw={"speziale","basilisco","segachiodi","meccania","iena","fonte di alimentazione","scorpide","tanaris","kit di analisi","zinge"},sec={{t="Tessuti nel deserto",b="Lo Speziale Zinge deve sapere se i tessuti dei basilischi, degli scorpidi e delle iene di Tanaris sono uniformi. Raccogli campioni e analizzali con il kit per analisi sul campo. Molti non saranno validi, quindi a Zinge servono otto campioni accettabili per ogni specie. Torna solo quando li avrai raccolti."},{t="Una fonte di alimentazione a Meccania",b="Il kit modificato ha bisogno di una fonte di alimentazione come quelle dei goblin di Meccania. Zinge ti manda dal Capo Ingegnere Segachiodi, a Meccania, per procurartene una."},{t="Niente è gratis",b="Il Capo Ingegnere Segachiodi conosce bene le fonti di alimentazione modello 4711-FTZ. Di solito alimentano i pozzi d'acqua, e al momento i vili nomadi ne hanno lasciate parecchie in giro. Segachiodi te ne procurerà una per qualunque esperimento tu stia cercando di nascondere. Ma non gratis. A Meccania, niente lo è."}},faq={{q="Chi ti manda a Tanaris per questa ricerca?",a="Lo Speziale Zinge ti manda a Tanaris con un kit per analisi sul campo. Vuole che analizzi i tessuti delle creature del deserto.",al={"chi inizia into the field","chi dà into the field","donatore missione into the field"}},{q="Perché devi incontrare il Capo Ingegnere Segachiodi?",a="Il kit per analisi modificato ha bisogno di una fonte di alimentazione come quelle dei goblin di Meccania. Il Capo Ingegnere Segachiodi può procurartene una.",al={"ruolo segachiodi","perché visitare segachiodi","fonte alimentazione kit di analisi"}},{q="Quali bestie sono il bersaglio dei test?",a="Metti alla prova i basilischi, gli scorpidi e le iene di Tanaris. A Zinge servono otto campioni accettabili per ogni specie.",al={"bestie da testare","tipi di creature into the field","campioni tessuti tanaris"}}},fp="14,188,20.267.0,27.151.0,15.282.1,43.119.0,51.132.0,38.94.0"}
P.entries["quest:2438"] = {n="L'acchiappasogni di smeraldo",s="A Dolanaar, Tallonkai Fontechiara ti chiede di recuperare l'Acchiappasogni di Smeraldo dalla sua casa abbandonata a Brezzastella. Gaerolas Talvethren gli diede il cimelio di famiglia, ma i furbolg Gnarlpine corrotti lo cacciarono dal villaggio prima che potesse prenderlo. La sua delicata magia è ancora lì ad attenderlo.",h="A Dolanaar, Tallonkai Fontechiara ti chiede di recuperare l'Acchiappasogni di Smeraldo dalla sua casa...",kw={"eremo di ban'ethil","dolanaar","sogno di smeraldo","acchiappasogni di smeraldo","furbolg","gaerolas talvethren","gnarlpine","brezzastella","tallonkai fontechiara","teldrassil"},ang={["class:Druid"]="Da druido, conosci Gaerolas Talvethren come il guardiano che si prende cura dei tuoi compagni addormentati nell'Eremo di Ban'ethil. Recuperare l'acchiappasogni che diede a Tallonkai è una questione d'onore druidico.",["faction:Alliance"]="Aiutando i Kaldorei sfollati di Dolanaar, contribuisci a mantenere la stabilità locale mentre la corruzione si diffonde tra le tribù di furbolg di Teldrassil.",["race:NightElf"]="Brezzastella era un tempo un rifugio tranquillo per la tua gente. Aiutare Tallonkai a recuperare la sua eredità sferra un piccolo colpo contro la follia che attanaglia la fauna selvatica di Teldrassil."},sec={{t="Un talismano druidico",b="Gaerolas Talvethren diede a Tallonkai un raro talismano druidico. Il guardiano veglia sui druidi addormentati nell'Eremo di Ban'ethil. L'amuleto incanala le correnti serene del Sogno di Smeraldo, portando pace e fortuna a chi lo porta. Doni simili sono riservati a pochi fidati, le cui vite sono legate alla cura della foresta."},{t="La fuga da Brezzastella",b="Brezzastella era un luogo pacifico, finché i furbolg Gnarlpine non furono sopraffatti da una follia violenta. Cacciarono gli abitanti dalle loro case ancestrali. Nella fuga dettata dalla paura, Tallonkai lasciò il suo bene più prezioso nascosto nel comò della sua casa, nella zona sud-orientale del villaggio. Da solo, non riuscì a recuperarlo."},{t="La minaccia della corruzione",b="L'Acchiappasogni di Smeraldo racchiude il potere del Sogno, e i Gnarlpine sono caduti sotto l'influenza di forze oscure. Quella magia potrebbe essere corrotta o usata per fare del male. Riportare l'amuleto a Tallonkai impedisce che il suo potere residuo finisca nelle mani dei furbolg e di altri esseri malvagi. Inoltre, gli restituisce un pezzo del patrimonio di Brezzastella."}},faq={{q="Cos'è l'Acchiappasogni di Smeraldo?",a="Gaerolas Talvethren diede a Tallonkai un raro amuleto che attinge energia dal Sogno di Smeraldo. Il guardiano si prende cura dei druidi addormentati nell'Eremo di Ban'ethil. La sua magia porta fortuna e armonia spirituale a chi lo porta.",al={"cos'è l'acchiappasogni","storia dell'acchiappasogni","acchiappasogni di smeraldo"}},{q="Perché l'acchiappasogni è stato lasciato a Brezzastella?",a="I furbolg Gnarlpine invasero Brezzastella in preda a una violenta frenesia. Tallonkai Fontechiara fuggì a Dolanaar, lasciando il cimelio nascosto nel comò della sua camera da letto.",al={"perché lasciarlo indietro","comò di brezzastella","comò di tallonkai"}},{q="Chi è Tallonkai Fontechiara?",a="Tallonkai Fontechiara è un Elfo della Notte rifugiato a Dolanaar. È fuggito da Brezzastella e cerca viaggiatori coraggiosi che recuperino i cimeli di famiglia e le reliquie druidiche dalle rovine occupate.",al={"chi è tallonkai","tallonkai fontechiara"}},{q="Chi ha creato l'acchiappasogni?",a="Tallonkai dice che Gaerolas Talvethren gli diede l'acchiappasogni. Gaerolas veglia sui druidi addormentati nell'Eremo di Ban'ethil, ma nessuno dice chi abbia creato l'amuleto.",al={"chi l'ha creato","gaerolas talvethren acchiappasogni","gaerolas"}},{q="Dove si trova l'acchiappasogni a Brezzastella?",a="L'acchiappasogni si trova nel comò di Tallonkai, nella casa più lontana a sud-est di Brezzastella. Ora i furbolg Gnarlpine si aggirano in gran numero nella casa.",al={"dov'è il comò","posizione comò di brezzastella","trova acchiappasogni"}},{q="Cosa succede dopo che l'acchiappasogni viene restituito?",a="Dopo aver esaminato l'amuleto recuperato, Tallonkai si accorge che manca lo smeraldo. Ferocitas il Divorasogni, capo dei Gnarlpine, l'ha rubato, e la caccia ha inizio.",al={"proseguimento missione","missione dopo acchiappasogni"}}},fx={["1ded4259"]={q="Perché Tallonkai Fontechiara vuole riavere l'Acchiappasogni di Smeraldo?",a="L'Acchiappasogni di Smeraldo è un tesoro raro e molto personale. Fu donato a Tallonkai da Gaerolas Talvethren, custode dei druidi nell'Eremo di Ban'ethil, e racchiude una potente magia tratta dal Sogno di Smeraldo, capace di portare fortuna. Quando Brezzastella cadde in mano ai furbolg Zannaspina corrotti, Tallonkai fu costretto a lasciarlo indietro. Teme che la sacra reliquia venga profanata o distrutta dai furbolg infuriati, se resterà nella sua casa abbandonata.",al={"perché tallonkai vuole l'acchiappasogni","motivo di tallonkai","perché recuperare l'acchiappasogni di smeraldo"}}},fp="24,289,18.312.0,26.299.0,24.312.1,33.219.0,59.160.0,27.187.0,26.165.0,56.146.0,48.167.1"}
P.entries["quest:244"] = {n="Encroaching Gnolls",s="Gli gnoll avanzano verso la strada occidentale delle Montagne Crestarossa e Borgolago teme di restare isolata. La guardia Parker individua accampamenti vicino al confine e avvisa il Vicesceriffo Feldon. L'allarme conferma il timore della città che gli uomini-bestia possano isolare le Montagne Crestarossa.",h="Gli gnoll avanzano verso la strada occidentale delle Montagne Crestarossa e Borgolago teme di restare isolata.",kw={"assessing the threat","vicesceriffo feldon","confine elwynn","encroaching gnolls","guardia parker","borgolago","crestarossa"},ang={["faction:Alliance"]="Da viaggiatore dell'Alleanza, sai che l'isolamento di Borgolago minaccia il fronte orientale. Le informazioni raccolte al confine sono importanti per i viaggiatori e i convogli di rifornimenti.",["race:Human"]="Da umano, puoi vedere come l'avanzata degli uomini-bestia vicino alla Foresta di Elwynn lasci vulnerabile il cuore del regno mentre il re è scomparso."},sec={{t="Occhi sul confine",b="La guardia Parker sorveglia il sentiero al confine occidentale, dove la strada dalla Foresta di Elwynn entra nelle Montagne Crestarossa. Le forze di Roccavento si sono assottigliate e lungo il percorso restano pochi difensori. Parker mantiene aperta la strada sterrata per i carri di rifornimenti, ma i suoi esploratori riferiscono che bande di guerra gnoll avanzano dalle rupi a nord e a est. I loro accampamenti sono allarmantemente vicini alla strada."},{t="Una città sotto assedio",b="Vicino al ponte di Borgolago, il Vicesceriffo Feldon riceve l'allarme e si rende conto del pericolo che minaccia la città. Gli gnoll delle Montagne Crestarossa razziano nei pressi di Borgolago, mentre i loro accampamenti vicino al confine della Foresta di Elwynn potrebbero permettere loro di circondare la città e avanzare nel cuore del regno. Roccavento ha ignorato le richieste di rinforzi, lasciando la guardia di Borgolago impreparata alle minacce da entrambi i lati."}},faq={{q="Chi inizia questa missione?",a="La guardia Parker ti consegna l'allarme lungo la strada nella parte occidentale delle Montagne Crestarossa, vicino al valico di confine della Foresta di Elwynn.",al={"datore di missione","dove iniziare","posizione della guardia parker"}},{q="Dove posso trovare il Vicesceriffo Feldon?",a="Il Vicesceriffo Feldon pattuglia i terreni di Borgolago, appena a sud del grande ponte di pietra della città.",al={"posizione feldon","chi è il vicesceriffo feldon","posizione consegna missione"}},{q="Perché gli gnoll sono un problema sulla strada?",a="La strada per la Foresta di Elwynn è l'unica via di terra sicura da Borgolago verso il resto del regno. Se gli gnoll prendono i pendii occidentali, la città potrebbe perdere i rifornimenti e ogni via di fuga.",al={"perché gli gnoll sono importanti","problema gnoll crestarossa","pericolo strada"}},{q="Perché Roccavento non invia aiuto a Borgolago?",a="Re Varian Wrynn è scomparso e i disordini mettono a dura prova il regno. L'Alto Signore Bolvar e la corte si sono rifiutati di inviare truppe reali nelle Montagne Crestarossa, così Borgolago affida la propria difesa ai vice sceriffi locali e ai volontari.",al={"dove sono le guardie di roccavento","nessun rinforzo","difesa di borgolago"}},{q="Cosa succede dopo aver segnalato gli gnoll?",a="In Assessing the Threat, il Vicesceriffo Feldon ti chiede di esplorare più da vicino gli accampamenti degli gnoll e scoprire quanti se ne sono radunati.",al={"missione successiva","seguito catena"}},{q="Quali branchi di gnoll stanno avanzando qui?",a="Gli gnoll delle Montagne Crestarossa si radunano sulle colline come Redridge Gnoll Pack. Man mano che il controllo umano sulla regione si indebolisce, sono diventati più audaci e meglio organizzati.",al={"quali gnoll","clan gnoll crestarossa"}}},fx={e50462f9={q="Perché la Guardia Parker vuole che venga fatto?",a="La Guardia Parker ha il compito di proteggere questo tratto di strada che porta alle Montagne Crestarossa, ma ha individuato accampamenti ostili di gnoll che si radunano poco più a nord e a est. Temendo un attacco imminente che potrebbe sopraffare la sua pattuglia e sbarrare il passo, ha urgente bisogno che le autorità di Borgolago siano avvertite prima che i gnoll assaltino la strada o avanzino verso Elwynn.",al={"motivo della guardia parker","perché avvertire borgolago","perché parker ti manda"}},be5d12a2={q="Perché la Guardia Parker manda te invece di andarci di persona?",a="Parker ha ordini rigorosi di sorvegliare e difendere la strada tra la Foresta di Elwynn e le Montagne Crestarossa. Se abbandonasse il suo posto per tornare in città, il confine resterebbe completamente sguarnito davanti ai branchi in agguato. Un viaggiatore in buona salute diretto a Borgolago è la sua migliore possibilità di far arrivare rapidamente l'avvertimento senza venir meno al suo dovere.",al={"perché mandare me","perché parker non va","perché la guardia parker non può riferire"}}},fp="18,234,18.369.0,18.363.0,22.120.0,31.94.0,40.176.0,45.206.0,40.125.0,39.148.0"}
P.entries["quest:245"] = {n="Eight-Legged Menaces",s="A Boscovespro, i ragni ragnatela velenosi infestano il confine occidentale e il Guardiano Dodds teme per la Night Watch. Chiede ai viaggiatori di ridurne il numero prima che altri guardiani finiscano nelle loro ragnatele.",h="A Boscovespro, i ragni ragnatela velenosi infestano il confine occidentale e il Guardiano Dodds teme per la...",kw={"borgoscuro","boscovespro","eight-legged menaces","the night watch","ragno ragnatela velenoso pigmeo","ragni","guardiano dodds"},ang={["class:Hunter"]="Da cacciatore, affronti feroci ragni ragnatela velenosi a Boscovespro. Muoversi con cautela e preparare un antidoto ti aiuta a dar loro la caccia.",["faction:Alliance"]="La Night Watch non riceve aiuto dalla House of Nobles. Il sostegno dei viaggiatori dell'Alleanza aiuta a mantenere aperte le strade."},sec={{t="Un confine sotto assedio",b="I ragni ragnatela velenosi pigmei brulicano tra i cespugli lungo la strada occidentale, da Marche Occidentali a Boscovespro. Sotto la fitta volta degli alberi, le loro ragnatele soffocano i roveti. I viaggiatori e le già fragili difese della Night Watch sono in pericolo."},{t="Il fardello di The Night Watch",b="Il Guardiano Dodds tiene un piccolo campo lontano da Borgoscuro, con troppo pochi soldati per difendere il confine. La Comandante Althea Serranero non può mandare aiuto mentre non morti e worgen premono contro la città. Dodds ha perso dei compagni a causa dei ragni. Li ha trovati appesi a testa in giù tra le fronde, paralizzati dal veleno che liquefaceva la loro carne."}},faq={{q="Chi offre questa missione?",a="Il Guardiano Dodds, membro della Night Watch in un piccolo campo a Boscovespro, chiede ai viaggiatori di liberare la zona dai ragni.",al={"datore di missioni","chi assegna eight-legged menaces","guardiano dodds"}},{q="Perché The Night Watch non può occuparsi dei ragni personalmente?",a="La Comandante Althea Serranero tiene la sua piccola guarnigione vicino a Borgoscuro per respingere i continui assalti dei non morti. Dodds ha troppo pochi soldati per attaccare i nidi al confine e mantenere la sua posizione.",al={"perché serve aiuto","perché chiamare avventurieri","carenza milizia borgoscuro"}},{q="Dove si trovano questi ragni?",a="I ragni ragnatela velenosi pigmei brulicano nei boschi occidentali di Boscovespro, tra i cespugli appena fuori dalla strada principale che arriva dalle Marche Occidentali.",al={"posizione ragni","dove sono i ragni ragnatela velenosi pigmei","boschi dei ragni"}},{q="Cosa rende questi ragni così pericolosi per la guardia?",a="I ragni sono numerosi e il loro veleno paralizza e dissolve la carne. I membri della Night Watch intrappolati nelle loro ragnatele restano appesi senza difesa tra i rami, facile preda.",al={"veleno di ragno","veleno dei ragni","vittime dei ragni"}},{q="Sono questi gli unici ragni a Boscovespro?",a="No. I ragni ragnatela velenosi pigmei sono i piccoli della nidiata. Ragni molto più grandi e letali vivono nelle profondità del bosco, dove minacciano i viaggiatori.",al={"altri ragni di boscovespro","specie di ragni","ragni ragnatela velenosi"}},{q="Perché la popolazione di insetti e ragni è cresciuta così aggressivamente?",a="Una corruzione magica ricopre Boscovespro e ha deformato la fauna locale. Le creature sono diventate più aggressive, più grandi e più letali.",al={"perché così tanti ragni","natura della corruzione di boscovespro","origine dei ragni"}}},fx={["19037cd1"]={q="Perché il Guardiano Dodds vuole che i ragni vengano sterminati?",a="I ragni velenosi della tela pigmea hanno invaso il confine occidentale di Boscovespro e la Night Watch ha troppo pochi uomini per occuparsene. Il Guardiano Dodds ha già perso diversi uomini a causa del loro veleno e delle loro ragnatele, e il Comandante Ebonlocke non può distaccare soldati così lontano da Borgoscuro.",al={"perché uccidere i ragni velenosi della tela pigmea","motivo di dodds per i ragni","perché dodds vuole che venga fatto"}},["3807547d"]={q="Che cosa sono i ragni velenosi della tela pigmea?",a="I ragni velenosi della tela pigmea sono aracnidi aggressivamente territoriali che infestano le terre di confine occidentali di Boscovespro. Benché siano più piccoli dei giganteschi ragni adulti che vivono nelle profondità del bosco, cacciano in sciami, intrappolano i viaggiatori imprudenti nei loro nidi di ragnatele e producono un potente veleno capace di sciogliere dall'interno la carne delle prede.",al={"ragni velenosi della tela pigmea","chi stiamo cacciando","ragni dell'ovest di boscovespro"}}},fp="20,182,20.221.0,29.325.0,22.106.0,56.174.0,32.106.0,51.148.0,39.145.0,63.137.0"}
P.entries["quest:2458"] = {n="Deep Cover",s="Shenthul manda un promettente ladro dell'Orda alla Palude Fangosa per incontrare un agente della S.P.R. & Co. La Shattered Hand ha impiegato un anno a infiltrare il Coordinatore Fizzule nei suoi terreni di trivellazione, dove tiene d'occhio i loro piani.",h="Shenthul manda un promettente ladro dell'Orda alla Palude Fangosa per incontrare un agente della S.P.R.",kw={"ladro delle savane","deep cover","pistola di segnalazione","the shattered hand","shenthul","palude fangosa","coordinatore fizzule","s.p.r. & co."},ang={["class:Rogue"]="Come ladro dell'Orda, stai passando dalle ricognizioni per le strade a incarichi sul campo di fiducia, coordinandoti in segreto.",["faction:Horde"]="Come membro dell'Orda, vedi il disboscamento e le trivellazioni della S.P.R. & Co. minacciare le terre e le risorse dell'Orda nelle Savane."},sec={{t="Una spia tra gli approfittatori",b="La Shattered Hand protegge gli interessi di Orgrimmar con intelligence segreta e assassinii. Per un anno, i suoi membri hanno lavorato per piazzare un agente nella S.P.R. & Co. Il Coordinatore Fizzule ha ottenuto un posto nel loro avamposto di trivellazione a nord della Palude Fangosa, tra i mercenari della compagnia."},{t="Segni e segnali",b="Fizzule deve mantenere la sua reputazione spietata per soddisfare i sorveglianti della S.P.R. & Co. Un visitatore inatteso potrebbe scatenare un attacco. Se raggiungi la sua torre, spara due razzi con la pistola di segnalazione mentre sei in vista, avvicinati in silenzio e fai il saluto segreto della Shattered Hand. Così Fizzule potrà condividere ciò che ha scoperto sui piani sempre più ambiziosi della compagnia."}},faq={{q="Chi è il Coordinatore Fizzule?",a="Il Coordinatore Fizzule è un agente della Shattered Hand infiltrato nella S.P.R. & Co. a nord della Palude Fangosa. Ha impiegato un anno a guadagnarsi autorità tra i mercenari, sorvegliando le loro attività e inviando informazioni a Orgrimmar.",al={"fizzule","chi è fizzule","identità coordinatore fizzule"}},{q="Perché Fizzule attacca se non gli viene inviato il segnale correttamente?",a="Fizzule mantiene i modi bruschi che ci si aspetta da un coordinatore della S.P.R. & Co. Senza il segnale dei due razzi e il saluto della Shattered Hand, scambia uno sconosciuto in avvicinamento per un intruso ostile o un agente rivale e attacca per proteggere la sua copertura.",al={"perché fizzule attacca","fizzule ostile","fizzule mi uccide"}},{q="Dove si trova la torre della S.P.R. & Co.?",a="La torre della S.P.R. & Co. domina i terreni di trivellazione a nord della Palude Fangosa, nella parte settentrionale delle Savane.",al={"posizione fizzule","posizione torre","dove si trova la torre della palude fangosa"}},{q="Perché l'Orda spia la S.P.R. & Co.?",a="La Shattered Hand spia la S.P.R. & Co. perché le sue estrazioni sconsiderate, lo sfruttamento e la violenza minacciano Kalimdor. Le informazioni recenti indicavano un piano importante nelle Savane, così Shenthul ha contattato la sua risorsa.",al={"perché spiare la s.p.r. & co.","minaccia s.p.r. & co."}},{q="Cosa succede dopo aver preso contatto con Fizzule?",a="Dopo aver preso contatto, Fizzule ti chiede di entrare nella vicina torre della S.P.R. & Co., ucciderne gli abitanti, incluso Grand Foreman Puzik Gallywix, e prendere Zanzil's Altered Mixture per dimostrare il tuo valore alla gilda.",al={"cosa fare dopo deep cover","dopo fizzule"}},{q="Cos'è la The Shattered Hand?",a="La Shattered Hand è una rete di ladri, spie e assassini con base nella Spelonca delle Ombre di Orgrimmar. Un tempo clan famigerato su Draenor, ora raccoglie informazioni in segreto per l'Orda.",al={"the shattered hand","chi è la the shattered hand"}}},fx={aa88dce8={q="Perché Shenthul manda te a prendere contatto invece di andarci di persona?",a="Shenthul è un istruttore che coordina le operazioni dei ladri dalle ombre di Orgrimmar, mentre il Coordinatore Fizzule è infiltrato in profondità nel territorio ostile della Palude Fangosa. Infiltrarsi in una base S.P.R. & Co. operativa richiede un agente agile sul campo, capace di superare le guardie e inviare un segnale a un infiltrato senza farsi notare, senza attirare l'attenzione dei mercenari della compagnia o compromettere l'intera cellula della Shattered Hand.",al={"perché mandare me","perché shenthul ha bisogno di me","perché non andarci di persona"}}},fp="10,218,22.282.0,17.353.0,26.220.0,58.236.0,43.102.0,47.223.0,47.216.1,27.190.0"}
P.entries["quest:2459"] = {n="Ferocitas il Mangiasogni",s="A Dolanaar, Tallonkai Fontechiara ti manda a nord a recuperare uno smeraldo rubato dai furbolg Gnarlpine. Il loro capo, Ferocitas il Divoratore di Sogni, lo porta al collo.",h="A Dolanaar, Tallonkai Fontechiara ti manda a nord a recuperare uno smeraldo rubato dai furbolg Gnarlpine.",kw={"dolanaar","divoratore di sogni","acchiappasogni di smeraldo","ferocitas","mistici gnarlpine","brezzastella","tallonkai fontechiara","smeraldo di tallonkai","teldrassil"},ang={["class:Druid"]="Da druido, sai che gli acchiappasogni sono strumenti potenti legati al Sogno di Smeraldo. Un furbolg corrotto ne ha profanato uno e la natura chiede una rapida punizione.",["race:NightElf"]="Come Elfo della Notte che difende Teldrassil, vedi la tragedia nella corruzione dei mistici Gnarlpine e nel furto dei talismani sacri. Gli Gnarlpine erano un tempo alleati dei Kaldorei."},sec={{t="Un cimelio profanato",b="Tallonkai Fontechiara fu sollevato quando il suo acchiappasogni tornò dalle terre selvagge corrotte. Poi ne vide le condizioni. Il sacro artefatto era stato vandalizzato e il suo smeraldo centrale era stato strappato dalla cornice intrecciata.\n\nGli Elfi della Notte parlavano di mistici Gnarlpine a nord di Brezzastella, caduti sotto il potere del loro capo, Ferocitas il Divoratore di Sogni. Portava al collo una brillante pietra verde. La gemma era inutile e corrotta nelle mani di Ferocitas, perciò Tallonkai mandò dei difensori a riprenderla."},{t="Purificare i mistici",b="Un tempo i furbolg Gnarlpine della parte settentrionale di Teldrassil erano vicini pacifici. La corruzione dell'Albero del Mondo li ha spinti alla frenesia e alla follia. I loro mistici praticavano riti naturali armoniosi, ma ora attingono a energie magiche distorte. Puoi raggiungere Ferocitas facendoti strada tra i mistici che proteggono il suo rifugio nel bosco. Riporta il gioiello a Tallonkai, così potrà ricomporre il suo acchiappasogni e ristabilire l'equilibrio nei boschi."}},faq={{q="Dove trovo Ferocitas il Divoratore di Sogni?",a="Ferocitas il Divoratore di Sogni attende nella foresta a nord di Brezzastella, su Teldrassil, tra mistici Gnarlpine corrotti e altri pericoli del bosco.",al={"posizione di ferocitas","dove si trova ferocitas","trovare il divoratore di sogni"}},{q="Chi è Ferocitas?",a="Ferocitas guida i furbolg Gnarlpine e comanda i mistici corrotti a nord di Brezzastella. Ha sottratto lo smeraldo dall'acchiappasogni di Tallonkai Fontechiara e ne ha fatto una rozza collana.",al={"chi è ferocitas","storia di ferocitas","cos'è il divoratore di sogni"}},{q="Perché Tallonkai Fontechiara vuole indietro il gioiello?",a="Tallonkai Fontechiara vuole riavere lo smeraldo perché è la fonte del potere del suo acchiappasogni. Senza di esso, il talismano non può essere riparato né incanalare le energie protettive del Sogno di Smeraldo.",al={"perché tallonkai vuole il gioiello","scopo del gioiello di tallonkai"}},{q="I Gnarlpine possono davvero usare la magia dello smeraldo?",a="No. Tallonkai Fontechiara dice che la magia dello smeraldo è inutile per Ferocitas e i mistici Gnarlpine. Lo desideravano solo come gingillo luminoso.",al={"i gnarlpine possono usare l'acchiappasogni","ferocitas usa lo smeraldo"}},{q="Cosa succede dopo questa missione?",a="Questo è il capitolo finale di una catena di due missioni iniziata con Acchiappasogni di Smeraldo. Porta il gioiello a Tallonkai a Dolanaar, così potrà riparare il suo cimelio.",al={"missione dopo ferocitas","prossima missione acchiappasogni"}},{q="Perché i mistici Gnarlpine sono ostili?",a="Una strana corruzione tra i rami dell'Albero del Mondo appena piantato ha colpito gran parte della fauna e delle tribù di furbolg di Teldrassil. Ha distorto le menti degli Gnarlpine e li ha resi aggressivi.",al={"perché i furbolg sono pazzi","corruzione gnarlpine"}}},fx={["80c83c66"]={q="A cosa serve lo Smeraldo di Tallonkai?",a="Lo smeraldo scomparso è il fulcro vitale dell'acchiappasogni danneggiato di Tallonkai Fontechiara. Senza di esso, il talismano non può funzionare; la pietra deve essergli restituita intatta, così potrà finalmente riparare il sacro amuleto protettivo.",al={"cos'è lo smeraldo di tallonkai","a cosa serve lo smeraldo di tallonkai","uso dello smeraldo scomparso"}}},fp="25,167,18.501.0,19.429.0,42.150.0,17.193.0,49.195.0,51.141.0,30.163.0,38.188.0"}
P.entries["quest:246"] = {n="Assessing the Threat",s="Vicino a Borgolago, il Vicesceriffo Feldon deve scoprire quanto sia cresciuta la minaccia degli gnoll. Con la guarnigione ridotta all'osso e Roccavento che nega i rinforzi, paga i viandanti perché assottiglino i branchi e ne valutino la forza.",h="Vicino a Borgolago, il Vicesceriffo Feldon deve scoprire quanto sia cresciuta la minaccia degli gnoll.",kw={"valutazione","feldon","gnoll","borgolago","mongrel","bracconiere","ricognizione","crestarossa","minaccia"},ang={["class:Warrior"]="Il Vicesceriffo Feldon ordina una ricognizione armata. Da guerriero, ti addentri negli accampamenti fortificati e spezzi l'avanguardia degli gnoll.",["faction:Alliance"]="Crestarossa mostra le difficoltà del cuore dell'Alleanza. Gli insediamenti di confine trascurati assoldano campioni per sopravvivere mentre la capitale distoglie lo sguardo.",["race:Human"]="Da difensore umano, proteggere Borgolago è una questione personale. Le famiglie di frontiera pagano il prezzo della paralisi politica al Forte di Roccavento."},sec={{t="Una Frontiera Sotto Pressione",b="Le bande da guerra degli orchi di Roccianera minacciano Borgolago dalle alture, mentre gnoll aggressivi si aggirano per le valli. La città ha troppo pochi difensori per le normali pattuglie di ricognizione. Quando i rapporti hanno mostrato che gli gnoll premevano verso il confine, il Vicesceriffo Feldon ha chiamato a raccolta i viandanti. Li paga per mettere alla prova il nemico nelle terre selvagge, risparmiando alle guardie un compito che la città non può permettersi di affidare loro."},{t="Ricognizione con la Forza",b="Esplori la strada meridionale di Crestarossa e assalti gli accampamenti dei Redridge Mongrels e dei bracconieri. Ogni scontro assottiglia gli esploratori avanzati degli gnoll e interrompe le loro linee di rifornimento. Gli scontri rivelano se i branchi siano spazzini dispersi o una forza organizzata che minaccia Borgolago. Feldon può usare ciò che scopri per pianificare la difficile difesa della città."}},faq={{q="Perché il Vicesceriffo Feldon invia avventurieri invece delle guardie cittadine?",a="La guarnigione di Borgolago è gravemente sotto organico. Roccavento non invia rinforzi e forze ostili premono da più direzioni. Le guardie non possono distogliere soldati per lunghe pattuglie lungo la strada meridionale.",al={"perché ingaggiare avventurieri","dove sono le guardie","carenza guardie borgolago"}},{q="Dove si trovano gli gnoll per questa missione?",a="I Redridge Mongrels e i bracconieri si accampano lungo la strada meridionale e sulle basse pendici delle Montagne Crestarossa, a sud di Borgolago e vicino ai passi di confine.",al={"dove sono i redridge mongrels","posizioni gnoll crestarossa","gnoll strada meridionale"}},{q="Qual è lo scopo strategico di decimare questi gnoll?",a="I combattimenti respingono gli gnoll che premono verso la strada e interrompono le loro linee di rifornimento. Inoltre, permettono a Feldon di conoscere direttamente le dimensioni dei branchi, le loro armi e la loro disciplina.",al={"perché uccidere gnoll","obiettivi valutazione minaccia","difesa borgolago"}},{q="Roccavento aiuta a contrastare la minaccia degli gnoll?",a="No. La Camera dei Nobili di Roccavento e il consiglio di reggenza negano il normale sostegno militare alle regioni periferiche come Crestarossa. I capi locali, tra cui il Magistrato Solomon e il Vicesceriffo Feldon, si affidano a mercenari assoldati.",al={"rinforzi roccavento","perché roccavento non aiuta","esercito roccavento borgolago"}},{q="Cosa fa il Vicesceriffo Feldon con il tuo rapporto?",a="Il Vicesceriffo Feldon valuta la forza e la tenacia dei branchi. Conferma che gli gnoll del sud rappresentano un serio pericolo militare, non una minaccia isolata di bestie. Poi ti incarica di aiutare gli altri capi della città a rafforzare le difese.",al={"reazione di feldon","cosa succede dopo assessing the threat","consegna rapporto"}},{q="Come si collega questo compito alla missione precedente?",a="Questa missione segue Encroaching Gnolls. Dopo che hai avvertito la guarnigione degli spostamenti degli gnoll, Feldon ti ha mandato in pattuglia da combattimento per scoprire quanto sia grave l'incursione.",al={"collegamento serie missioni","seguito encroaching gnolls","missione prerequisito"}}},fx={["6de7b21c"]={q="Chi sono i gnoll di Crestarossa che ti viene chiesto di sterminare?",a="Ti mandano contro i meticci e i bracconieri di Crestarossa accampati lungo la strada meridionale. Questi gnoll selvaggi si stanno ammassando proprio lungo la via vitale della città, molestano i viaggiatori, bloccano le rotte di rifornimento e si avvicinano pericolosamente a Borgolago, mentre le difese della città sono già al limite.",al={"meticci e bracconieri di crestarossa","chi sono i gnoll di crestarossa","minaccia dei gnoll di crestarossa"}}},fp="20,219,19.344.0,23.347.0,63.207.0,46.158.0,54.175.0,47.214.0,44.228.0,46.160.0"}
P.entries["quest:2460"] = {n="The Shattered Salute",s="Nella Spelonca delle Ombre di Orgrimmar, Shenthul insegna ai ladri una parola d’ordine silenziosa.",h="Nella Spelonca delle Ombre di Orgrimmar, Shenthul insegna ai ladri una parola d’ordine silenziosa.",kw={"spelonca delle ombre","copertura","deep cover","orgrimmar","ladro","shattered hand","shattered salute","shenthul"},ang={["class:Rogue"]="Come ladro dell’Orda, impari i segnali segreti di The Shattered Hand e passi da semplice borseggiatore ad agente fidato della rete d’intelligence di Orgrimmar.",["faction:Horde"]="Come membro dell’Orda, servi sotto il Capoguerra Thrall, che guida con onore. L’Orda si affida anche ai metodi segreti di The Shattered Hand per fermare le minacce prima che raggiungano la superficie."},sec={{t="Segni e Ombre",b="Dalla Spelonca delle Ombre di Orgrimmar, The Shattered Hand serve in segreto come rete di intelligence e braccio assassino dell’Orda di Thrall. Durante gli incarichi segreti e pericolosi, gli agenti non possono usare i segnali militari. Perciò Shenthul insegna ai ladri appena iniziati The Shattered Salute, un gesto silenzioso che permette agli alleati di riconoscersi."},{t="Preparazione per il Campo",b="Per i ladri di Shenthul, imparare il saluto è una tecnica operativa fondamentale, non una cerimonia. Gli agenti inviati in luoghi pericolosi o a infiltrarsi nelle fazioni rivali devono verificare i contatti senza allertare i passanti o i bersagli. Prima di affidare loro incarichi clandestini sul campo, Shenthul si aspetta che sappiano riconoscere e ripetere il gesto senza esitazione."}},faq={{q="Qual è lo scopo del The Shattered Salute?",a="The Shattered Salute permette agli agenti di The Shattered Hand di riconoscersi sotto copertura o in territorio ostile, senza rivelare i propri legami agli estranei.",al={"perché ho bisogno del saluto","scopo del shattered salute","cosa fa il saluto"}},{q="Chi insegna il The Shattered Salute?",a="Shenthul insegna il saluto. È un addestratore di ladri che opera nelle profondità della Spelonca delle Ombre di Orgrimmar.",al={"chi dà la missione","chi è shenthul","dove imparo il saluto"}},{q="Quale organizzazione usa questo gesto?",a="The Shattered Hand usa il gesto. Ladri, spie e assassini orcheschi dell’ordine servono l’Orda di Thrall dalle ombre di Orgrimmar.",al={"clan shattered hand","chi sono i shattered hand","quale gilda usa questo"}},{q="Perché imparare il saluto è necessario prima di andare sul campo?",a="Durante le missioni di infiltrazione, gli agenti usano il saluto per contattare gli alleati sotto copertura, senza svelarsi o scambiare un nemico per un alleato.",al={"perché praticare il saluto","il saluto è obbligatorio"}},{q="Dove si svolge questo addestramento?",a="L’addestramento si svolge nella Spelonca delle Ombre, un quartiere sotterraneo sotto Orgrimmar dove ladri, stregoni e altri praticanti delle arti proibite si riuniscono lontano dagli occhi del pubblico.",al={"posizione del saluto","dove si trova shenthul"}},{q="Quale incarico segue dopo aver padroneggiato il saluto?",a="Quando Shenthul è soddisfatto della preparazione di un agente, gli assegna operazioni Deep Cover. L’incarico mette alla prova la sua capacità di usare il segnale per contattare gli agenti sul campo.",al={"what comes next","missione successiva dopo il saluto","missione deep cover"}}},fp="20,157,17.315.0,25.325.0,44.147.0,33.101.0,36.132.0,65.138.0,36.186.0,51.179.0"}
P.entries["quest:247"] = {n="Caccia completata",s="A Valtetra, un campione dell'Orda affronta tre predatori leggendari. Ursangous, Shadumbra e Sharptalon mettono alla prova forza, tenacia e abilità di caccia nella natura selvaggia.",h="A Valtetra, un campione dell'Orda affronta tre predatori leggendari.",kw={"valtetra","bestie","caccia","predatore","senani","shadumbra","sharptalon","cuore tonante","trofeo","ursangous"},ang={["class:Hunter"]="Da cacciatore, metti alla prova le tue capacità di tracciamento e di tiro contro tre dei più grandi predatori di Valtetra. Il tuo istinto deve essere pari a quello delle bestie selvagge.",["faction:Horde"]="Come membro dell'Orda, contribuisci a consolidare la presenza del tuo popolo a Valtetra, una foresta pericolosa, popolata da predatori e sentinelle dell'Alleanza.",["race:Tauren"]="Come tauren, onori un'antica prova di rispetto, equilibrio e orgoglio ancestrale cacciando Ursangous, Shadumbra e Sharptalon."},sec={{t="La Prova di un Cacciatore",b="Senani Cuore Tonante mette alla prova i viaggiatori tra le forze dell'Orda a Valtetra. La sua caccia verifica la lealtà al capoguerra e chiede se un cacciatore sappia sopravvivere nella natura selvaggia. Le prede sono tre predatori leggendari: l'orso Ursangous, il felino Shadumbra e il feroce ippogrifo Sharptalon. Un cacciatore deve abbatterli tutti e tre e assicurarsi i loro trofei per dimostrare che il suo sangue è autentico."},{t="Onorare gli Antenati",b="Per i tauren, la caccia è sacra. Onora l'equilibrio e il rispetto, anche su un fronte di guerra attivo. Superando i più grandi terrori di Valtetra, un cacciatore onora gli spiriti della terra e ottiene le benedizioni ancestrali di Cuore Tonante. Un encomio formale e un pegno di favore segnano la fine della caccia, e la reputazione del campione si diffonde per tutta la foresta."}},faq={{q="Chi offre questa missione e dove si trova?",a="Senani Cuore Tonante, cacciatrice tauren, propone la caccia tra le forze dell'Orda a Valtetra.",al={"chi offre la missione","dove consegnare","dove si trova senani cuore tonante"}},{q="Quali sono i requisiti per completare la caccia?",a="Devi uccidere tre grandi predatori e portare la prova della loro morte: Ursangous's Paw, la testa di Shadumbra e l'artiglio di Sharptalon.",al={"quali bestie uccidere","prerequisiti","quali animali"}},{q="Perché Senani Cuore Tonante vuole che queste bestie vengano uccise?",a="La caccia mette alla prova forza e tenacia. Abbattere bestie tanto formidabili dimostra che un viaggiatore ha il cuore e l'istinto di un predatore, e che può sopravvivere nella pericolosa natura selvaggia di Valtetra.",al={"perché cacciarli","motivo di senani","scopo della caccia"}},{q="Qual è il significato culturale della caccia per l'Orda?",a="Per i tauren come Senani Cuore Tonante, mettere alla prova il proprio valore contro bestie possenti è una tradizione onorevole. Onora gli spiriti e gli antenati e dimostra maestria nella natura selvaggia senza ricorrere a una disonorevole imprudenza.",al={"lore caccia tauren","significato culturale","perché i tauren cacciano le bestie"}},{q="Questa prova è riconosciuta da tutta l'Orda?",a="Sì. Completare la caccia ti rende un cacciatore affermato tra le forze dell'Orda a Valtetra. Ottieni le benedizioni ancestrali e il rispetto dei tuoi compagni.",al={"riconoscimento dell'orda","è ufficiale","encomio dell'orda"}},{q="Quali tre bestie sono prese di mira nella caccia di Valtetra?",a="I tre bersagli sono Ursangous, il grande orso, Shadumbra, il saberon notturno, e Sharptalon, l'ippogrifo.",al={"le tre bestie","bersagli della caccia","animali nominati"}}},fx={ded238b8={q="Quali bestie dovevi uccidere per la caccia di Valtetra?",a="La prova ti richiedeva di rintracciare e abbattere tre dei predatori più feroci di Valtetra: l'antico orso Ursangous, l'elusivo saberon notturno Shadumbra e il feroce ippogrifo Sharptalon. Queste bestie selvagge dominavano le chiome degli alberi e i boschetti della foresta, rappresentando una grave minaccia per i viaggiatori e costituendo la prova suprema di forza, pazienza e abilità venatoria nella natura selvaggia e incontaminata.",al={"quali bestie ho ucciso","bersagli della caccia di valtetra","quali bestie nella caccia completata"}}},fp="18,159,16.377.0,22.343.0,49.90.0,47.126.0,53.178.0,59.204.0,45.153.0,54.104.0"}
P.entries["quest:2478"] = {n="Mission: Possible But Not Probable",s="Nelle Savane settentrionali, i ladri dell'Orda si infiltrano in un avamposto della S.P.R. & Co. per rubare una mistura potente per la Shattered Hand. La missione mette alla prova furtività, furto e combattimento.",h="Nelle Savane settentrionali, i ladri dell'Orda si infiltrano in un avamposto della S.P.R.",kw={"savane","fizzule","scasso","veleni","puzik gallywix","the shattered hand","shenthul","silixiz","palude fangosa","zanzil"},ang={["class:Rogue"]="Da ladro, impari abilità sul campo come scassinare serrature, borseggiare e sfruttare le vulnerabilità. Queste abilità aprono la strada alle arti letali e ai veleni della Shattered Hand.",["faction:Horde"]="La Shattered Hand opera nell'ombra di Orgrimmar e tiene d'occhio pericolosi intrusi aziendali come la S.P.R. & Co., mentre sfruttano le Savane."},sec={{t="Infiltrazione nella S.P.R. & Co.",b="A nord degli impianti petroliferi della Palude Fangosa, la S.P.R. & Co. mantiene una torre di trivellazione isolata. Coordinatore Fizzule, un operativo della Shattered Hand sotto copertura che si spaccia per un supervisore della S.P.R. & Co., manda i ladri a ricorrere alle arti criminali invece di attaccare apertamente. Chiede loro di borseggiare la Chiave Infernale a Capocantiere Silixiz e di tenerla per lui. Poi si fanno strada oltre operai e sentinelle mutate dagli esperimenti della torre."},{t="Una catastrofe chimica",b="La Miscela Alterata di Zanzil ha cambiato gli abitanti della torre. Il suo veleno indebolisce le guardie, rendendole vulnerabili a colpi rapidi, attacchi sanguinanti e imboscate improvvise. La sostanza ha anche reso instabile la struttura. In cima, Gran Capocantiere Puzik Gallywix sorveglia una cassetta di sicurezza che contiene la mistura."},{t="Il prezzo del dovere",b="I vapori della Miscela Alterata fuoriescono quando apri la cassetta di sicurezza di Gallywix. Spezzano la tua furtività, consumano la tua vitalità e ti infliggono un'afflizione debilitante che dura a lungo. A Orgrimmar, Shenthul, il mentore della Shattered Hand, riceve la testa di Gallywix e il campione chimico. Si rammarica che la copertura di Fizzule sia compromessa e manda l'agente morente a cercare una cura."}},faq={{q="Dove si trova la torre della S.P.R. & Co.?",a="La torre della S.P.R. & Co. sorge nelle Savane settentrionali, appena a nord dell'impianto di trivellazione della Palude Fangosa. Operai ostili della S.P.R. & Co. la circondano, mentre Coordinatore Fizzule si nasconde vicino a un albero poco più a est.",al={"posizione torre s.p.r. & co.","dove si trova la torre di gallywix","torre di palude fangosa"}},{q="Come si ottiene la chiave della torre?",a="Capocantiere Silixiz porta la Chiave della Torre e si aggira nei terreni ai piedi della torre. Borseggialo mentre sei nascosto per prenderla. Ucciderlo non ti darà la chiave.",al={"chiave della torre di silixiz","come ottenere la chiave della torre","dove si trova la chiave"}},{q="Cos'è la Miscela Alterata di Zanzil?",a="La Miscela Alterata di Zanzil è una mistura alchemica ricavata dalle formule del famigerato stregone vudù troll Zanzil. La S.P.R. & Co. l'ha acquisita e i suoi fumi instabili hanno avvelenato i lavoratori della torre. Li hanno resi malaticci, mutati e vulnerabili alle arti di combattimento dei ladri.",al={"miscela di zanzil","cos'è il veleno","miscela alterata"}},{q="Perché non riesco a usare la furtività dopo aver aperto la cassetta di sicurezza?",a="Aprire la cassetta di sicurezza di Gallywix libera fumi concentrati della Miscela Alterata. L'afflizione tossica dura giorni, indebolisce i tuoi attributi e spezza la tua furtività finché un alchimista esperto non ti cura.",al={"tocco di zanzil","avvelenato dopo lo scrigno","impossibile furtività missione ladro","veleno 7 giorni"}},{q="Chi è il Coordinatore Fizzule?",a="Coordinatore Fizzule è un agente sotto copertura della Shattered Hand, la gilda dei ladri dell'Orda. Il nano Ferroscuro si spaccia per un brutale caposquadra della S.P.R. & Co. nelle Savane. Indirizza le reclute a sabotare le risorse della compagnia senza esporsi.",al={"fizzule","chi ha assegnato questa missione","storia di fizzule"}},{q="Chi è Gran Capocantiere Puzik Gallywix?",a="Gran Capocantiere Puzik Gallywix è il sorvegliante goblin che comanda la torre della S.P.R. & Co. vicino alla Palude Fangosa. Sorveglia il deposito rubato delle pozioni di Zanzil finché gli operativi della Shattered Hand non lo uccidono.",al={"puzik gallywix","gallywix è nelle savane","capocantiere gallywix"}}},fx={["2a5cd36a"]={q="Perché Coordinatore Fizzule vuole che la torre della S.P.R. & Co. venga distrutta?",a="Operando sotto copertura per The Shattered Hand, Coordinatore Fizzule ha visto la S.P.R. & Co. sperimentare un veleno volatile e mutageno. Ora che la mistura contaminata ha corrotto e indebolito tutti coloro che si trovano nella torre, Fizzule vede l'occasione di eliminare l'intera operazione, recidere la leadership di Caposquadra Gallywix e mettere al sicuro il composto letale per Orgrimmar prima che si diffonda senza controllo.",al={"motivo di fizzule","perché fizzule vuole uccidere gallywix","perché attaccare la torre della s.p.r. & co."}},f260e633={q="Perché Shenthul vuole la Testa di Gallywix?",a="Recidere la testa di Caposquadra Puzik Gallywix costituisce una prova inconfutabile della sua morte e dello smantellamento della gerarchia della torre della S.P.R. & Co. Presentarla a Shenthul nella Faglia Infida conferma che il principale sovrintendente dell'operazione regionale è stato eliminato definitivamente.",al={"a cosa serve la testa di gallywix","perché prendere la testa di gallywix"}},["53be2ad7"]={q="A cosa serve la chiave della torre di Silixiz?",a="Caposquadra Silixiz porta la chiave fuori dalla torre. Fizzule ti chiede di rubarla e tenerla, perché potrebbe servirgli più avanti; recuperarla è uno degli obiettivi della missione.",al={"chiave della torre di silixiz","a cosa serve la chiave della torre","perché rubare la chiave della torre"}},["78e0c22c"]={q="A cosa serve la Cassa di Mistura di Zanzil Alterata?",a="Chiusa a chiave in cima alla torre, nel forziere personale di Gallywix, questa scorta rimanente contiene la strana mistura debilitante ricavata dalle formule di Zanzil. The Shattered Hand ha bisogno che tu recuperi la mistura, affinché i maestri dei furfanti di Orgrimmar possano studiarne e contenere in sicurezza le proprietà tossiche e mutagene.",al={"cassa di mistura alterata di zanzil","cassa della mistura di zanzil","perché prendere la mistura"}},["07291131"]={q="Perché ti mandano contro Caposquadra Puzik Gallywix e i lavoratori della torre?",a="Ti mandano a eliminare il personale corrotto della S.P.R. & Co. che occupa la torre nelle Savane settentrionali. Sotto il comando di Caposquadra Puzik Gallywix, questa squadra ha maneggiato senza cautela il composto tossico di Zanzil, trasformando i droni in mostruosità mutate e mettendo in pericolo la regione. Eliminando vedette, pattugliatori, droni e Gallywix stesso, spazzi via la loro presenza industriale sempre più invadente.",al={"contro chi combatti nella torre","bersagli nella torre della s.p.r. & co.","perché uccidere gallywix"}},fa60081f={q="Perché Fizzule ha bisogno di te invece di occuparsi lui della torre?",a="Fizzule sta mantenendo una precaria identità sotto copertura come coordinatore della S.P.R. & Co. Se venisse scoperto mentre si infiltra apertamente nella torre, uccide i sovrintendenti o saccheggia lo scrigno di Gallywix, la sua copertura salterebbe all'istante. Come agente esterno di The Shattered Hand, possiedi la furtività letale necessaria per ripulire l'impianto senza smascherare il suo ruolo.",al={"perché io, fizzule","perché fizzule ha bisogno di aiuto","perché fizzule non ripulisce la torre"}}},fp="34,166,31.391.0,22.298.1,17.370.2,39.210.0,39.156.0,33.280.0,53.210.1,26.259.0,36.199.0"}
P.entries["quest:2479"] = {n="Hinott's Assistance",s="A Orgrimmar, i ladri avvelenati cercano aiuto prima che la Fiala della Mistura di Zanzil li uccida. La tossina proviene da un'infiltrazione nelle Savane. Serge Hinott, a Mulino di Tarren, può offrire una cura e insegnare ai ladri a preparare veleni.",h="A Orgrimmar, i ladri avvelenati cercano aiuto prima che la Fiala della Mistura di Zanzil li uccida.",kw={"alture di colletorto","hinott's assistance","missione veleno ladro","serge hinott","shenthul","mulino di tarren","zeppelin per sepulcra","zanzil","fiala della mistura di zanzil"},ang={["class:Rogue"]="Come ladro, affronti un rito di passaggio che mette alla prova la tua resistenza e ti apre la strada alla creazione dei tuoi veleni.",["faction:Horde"]="Come membro dell'Orda, assisti alla collaborazione concreta tra i ladri orchi e troll di Kalimdor e le conoscenze alchemiche dei Reietti a Lordaeron."},sec={{t="Un problema tossico",b="La tua infiltrazione nella torre della S.P.R. & Co. a nord della Palude Fangosa ti ha avvelenato con la Fiala della Mistura di Zanzil alterata. La tossina rallenta i tuoi riflessi e minaccia la tua vita. Shenthul, l'istruttore dei ladri a Orgrimmar, sa che i rimedi locali non possono aiutarti. Perciò ti manda oltre il mare, nei Regni Orientali, a cercare una cura."},{t="Viaggio a Mulino di Tarren",b="La tua ricerca di una cura ti conduce a sud attraverso Lordaeron, fino a Mulino di Tarren, un villaggio nelle Alture di Colletorto. Serge Hinott vive lì e fa l'apotecario, affascinato dagli intrugli virulenti. I guaritori comuni rifuggono il veleno di Zanzil, ma Hinott affronta il composto letale con gioia professionale. Può analizzare la ripugnante mistura e insegnare ai ladri meritevoli a preparare i propri veleni."}},faq={{q="Perché devo vedere Serge Hinott?",a="Serge Hinott è un apotecario di Mulino di Tarren, specializzato in tossine rare e nei loro antidoti. I guaritori comuni non possono purificarti dalla Fiala della Mistura di Zanzil alterata, perciò Hinott può analizzarla, salvarti la vita e insegnarti l'arte dei veleni.",al={"perché hinott","chi cura il veleno","ruolo di serge hinott"}},{q="Dove si trova Mulino di Tarren?",a="Mulino di Tarren è un insediamento dei Reietti nella parte settentrionale delle Alture di Colletorto. Da Orgrimmar, prendi lo zeppelin per Sepulcra, nelle Radure di Tirisfal, viaggia a sud attraverso la Selva Pinargento, poi svolta a est lungo la strada verso Colletorto.",al={"posizione mulino di tarren","come arrivare a mulino di tarren","dove si trova hinott"}},{q="Come sono stato avvelenato?",a="Sei stato infettato durante Mission: Possible But Not Probable, nella torre della S.P.R. & Co. a nord della Palude Fangosa, nelle Savane. Aprire il forziere ad alta sicurezza ti ha esposto alla Fiala della Mistura di Zanzil alterata e ti ha lasciato un'afflizione debilitante e persistente.",al={"come ho preso il veleno di zanzil","veleno missione possibile","perché sono avvelenato"}},{q="Cosa succede dopo che Serge Hinott riceve il campione?",a="Dopo aver ricevuto il campione, Serge Hinott ne esamina le proprietà e prepara un antidoto per purificare il tuo organismo. Una volta neutralizzata la tossina, condivide le sue conoscenze affinché i ladri imparino a preparare e applicare i propri veleni.",al={"proseguimento missione hinott","verrò curato","dopo hinott's assistance"}},{q="Chi è Shenthul e perché mi ha mandato via?",a="Shenthul è l'istruttore dei ladri di The Shattered Hand nella Spelonca delle Ombre, a Orgrimmar. Ha supervisionato la tua prova di abilità nelle Savane e ha capito che le conoscenze mediche di Orgrimmar non bastavano per affrontare l'intruglio di Zanzil. Così ti ha mandato da uno specialista di Colletorto.",al={"chi è shenthul","shenthul orgrimmar","perché l'istruttore mi ha mandato via"}},{q="Altre classi possono completare questa missione?",a="No. Questo addestramento appartiene alla tradizione dei ladri e insegna le basi per preparare veleni e rimedi.",al={"missione solo per ladri","i guerrieri possono fare hinott's assistance"}}},fp="19,214,19.312.0,22.372.0,34.221.0,29.226.0,42.256.0,52.221.1,44.250.0,40.108.0"}
P.entries["quest:248"] = {n="Looking Further",s="Theocritus osserva la parte orientale delle Montagne Crestarossa dalla Foresta di Elwynn attraverso un condotto incantato. Cerca la causa del conflitto tra Morganth e gli orchi Roccianera nel Mastio di Guardamasso, e ti manda a collocare il Glifo - Azora nella vicina torre di guardia.",h="Theocritus osserva la parte orientale delle Montagne Crestarossa dalla Foresta di Elwynn attraverso un...",kw={"barattolo vuoto","glifo - azora","looking further","morganth","statua del leone antico","guardamasso","mastio di guardamasso","theocritus","torre di ilgalar"},ang={["class:Mage"]="Theocritus usa il Glifo - Azora per la chiaroveggenza a lunga distanza, mostrando come il Mago di Azora sorvegli magicamente i territori ostili.",["faction:Alliance"]="Il Mastio di Guardamasso resta la principale roccaforte del clan Roccianera a Redridge. Scoprire i dettagli del conflitto con Morganth è fondamentale per difendere Borgolago."},sec={{t="Una spaccatura a Crestarossa",b="Dal suo santuario nella Foresta di Elwynn, Theocritus osserva la parte orientale delle Montagne Crestarossa con la magia di divinazione. Mentre studia la Torre di Ilgalar, rileva uno scontro tra Morganth, uno stregone umano rinnegato, e gli orchi Roccianera trincerati nel Mastio di Guardamasso. Entrambe le fazioni ostili dovrebbero unirsi contro il Regno di Roccavento, eppure combattono per un premio sconosciuto. Theocritus interviene prima che il conflitto cambi gli equilibri."},{t="L'occhio su Guardamasso",b="Theocritus ha bisogno di un secondo punto di ancoraggio magico per penetrare le difese del Mastio di Guardamasso. Ti manda quindi a salire sulla torre di guardia intatta accanto alla fortezza in rovina. Tra le cianfrusaglie della guarnigione, un barattolo vuoto abbandonato dalle sentinelle orche offre un nascondiglio comune. Fissa al suo interno il Glifo - Azora, e Theocritus potrà sondare telepaticamente le menti all'interno di Guardamasso per scoprire cosa ha diviso Morganth e i Roccianera."}},faq={{q="Chi mi invia in questa missione?",a="Theocritus, il Mago di Azora, ti parla attraverso la statua del leone antico nelle Montagne Crestarossa dopo che hai completato il suo incarico precedente.",al={"chi assegna la missione","statua del vecchio leone","statua del leone antico"}},{q="Perché Theocritus spia il Mastio di Guardamasso?",a="Theocritus ha rilevato un'aperta ostilità tra Morganth, il mago oscuro rinnegato nella Torre di Ilgalar, e gli orchi Roccianera che occupano il Mastio di Guardamasso. Vuole scoprire cosa ha innescato il loro conflitto.",al={"perché spiare gli orchi","scopo di theocritus","perché guardamasso"}},{q="Dove si trova il contenitore?",a="Il barattolo vuoto si trova sopra alcuni barili, in cima alla torre di guardia intatta accanto all'ingresso principale del Mastio di Guardamasso.",al={"posizione barattolo vuoto","dove piazzare il glifo","dove si trova la torre di guardia"}},{q="Cosa fa il Glifo - Azora?",a="Il Glifo - Azora è un focus magico per la chiaroveggenza e la divinazione. Permette a Theocritus di sorvegliare a distanza l'area circostante e di scrutare le menti degli orchi Roccianera all'interno del mastio.",al={"scopo del glifo di azora","cosa fa il glifo"}},{q="Cosa succede dopo aver piazzato il glifo?",a="Una volta scoperta la causa del conflitto, Theocritus ti manda a dare la caccia a Morganth nella Torre di Ilgalar e a recuperare il suo Pendente dell'Ombra.",al={"missione successiva","cosa succede dopo","seguito di looking further"}},{q="Perché usare un barattolo vuoto?",a="Una runa magica di spionaggio ha bisogno di un contenitore poco appariscente, così le guardie non la noteranno né la distruggeranno. Il barattolo di liquore maleodorante, abbandonato sui barili, è un nascondiglio ideale.",al={"perché il barattolo","storia del barattolo vuoto"}}},fx={["3912e7be"]={q="Chi devo spiare al Mastio di Guardamasso?",a="Stai spiando gli orchi dei Roccianera che hanno preso il Mastio di Guardamasso. Dal suo punto d'osservazione, il mago Theocritus ha percepito una discordia serpeggiare tra questi orchi ostili e lo stregone oscuro Morganth, presso la Torre di Ilgalar. Collocare il glifo permette al mago di sondare le menti di chi si trova a Guardamasso per scoprire la vera causa di questo attrito.",al={"chi c'è nel mastio di guardamasso","bersaglio nel mastio di guardamasso","bersaglio di looking further"}},["6347ef38"]={q="Perché Theocritus ha bisogno di un avventuriero che collochi il glifo?",a="Theocritus è legato alla Torre di Azora e incanala la sua magia attraverso reliquie incantate come la Vecchia Statua del Leone per sorvegliare le minacce in tutta la Cresta di Roccavento. Il Mastio di Guardamasso pullula di pericolosi orchi dei Roccianera, e infiltrarsi nella roccaforte richiede qualcuno capace di combattere per farsi strada senza essere visto, anziché un mago solitario e vulnerabile che abbandoni il suo posto.",al={"perché mandarmi a looking further","perché non ci pensa theocritus","perché io a guardamasso"}}},fp="15,241,18.418.0,21.425.1,29.133.0,44.201.0,31.114.0,32.182.0,38.141.1,21.170.0"}
P.entries["quest:2480"] = {n="Hinott's Assistance",s="Al Mulino di Tarren, Serge Hinott studia il veleno che annebbia la mente di un ladro dell'Orda e prepara una cura.",h="Al Mulino di Tarren, Serge Hinott studia il veleno che annebbia la mente di un ladro dell'Orda e prepara una...",kw={"antitossina","cura","colletorto","hinott","veleni","missione ladro","serge hinott","mulino di tarren","zanzil"},ang={["class:Rogue"]="Da ladro, guarisci dall'afflizione contratta durante l'iniziazione e impari a preparare veleni tattici.",["faction:Horde"]="Come membro dell'Orda, puoi imparare dall'alchimia dei Reietti, che trasforma le tossine dei troll della giungla in conoscenze utili sul campo.",["race:Undead"]="Da Undead, osservi la distaccata ammirazione dello speziale Hinott per un veleno creato con maestria, qualunque sia la sua origine."},sec={{t="Un capolavoro tossico",b="I tuoi guai sono iniziati con un incarico nelle Savane. Ora ti mandano a nord, al Mulino di Tarren, con una tossina che ti annebbia la mente. Serge Hinott, un chimico dei Reietti, studia il veleno creato da Zanzil, un troll della giungla esiliato. L'identità e la stirpe del troll interessano poco a Hinott. Ammira il feroce effetto della mistura e vuole capire come agisce prima di preparare un antidoto."},{t="L'antidoto e il mestiere",b="Serge Hinott ha bisogno di tempo per isolare i principi attivi del veleno. Il suo rimedio arresta la follia strisciante, anche se dice che il fetore persiste. Quando il veleno non ti indebolisce più, Hinott ti racconta ciò che ha imparato dal lavoro di Zanzil. Con queste conoscenze, puoi preparare i tuoi veleni tattici."}},faq={{q="Cosa succede durante Hinott's Assistance?",a="Aspetta qualche istante al Mulino di Tarren mentre Serge Hinott prepara l'antidoto. Quando è pronto, parlagli per ricevere la cura e liberarti dal veleno di Zanzil.",al={"cosa devo fare qui","guida hinott assistance","come finire la missione"}},{q="Chi è Serge Hinott?",a="Serge Hinott è un alchimista dei Reietti ed esperto di veleni al Mulino di Tarren, nelle Alture di Colletorto. Aiuta i ladri dell'Orda a curare afflizioni insolite e a imparare a preparare veleni.",al={"storia serge hinott","chi è hinott","speziale mulino di tarren"}},{q="Perché Serge Hinott è colpito dal veleno?",a="Hinott ammira la maestria della formula di Zanzil, che provoca follia strisciante e debolezza fisica. Lavora per arrestarne gli effetti, ma elogia l'abilità con cui è stata creata la mistura letale.",al={"reazione veleno zanzil","perché a hinott piace"}},{q="Cos'è l'odore persistente menzionato da Hinott?",a="La mistura di Zanzil lascia un odore pungente e nauseabondo nei pori della vittima. L'antidoto di Hinott arresta il veleno e libera la mente, ma il fetore persiste per un po'.",al={"perché puzzo","odore di follia","odore missione"}},{q="Qual è la ricompensa per aver completato questa missione?",a="La cura elimina l'afflizione che ti porti dietro dall'addestramento da ladro e ti permette di imparare Rogue Poisons, così potrai preparare rivestimenti debilitanti.",al={"cosa ottengono i ladri","ricompensa hinotts assistance"}},{q="Dove si consegna questa missione?",a="Incontri Serge Hinott al Mulino di Tarren, nella parte settentrionale delle Alture di Colletorto. È lì che inizia e completa il lavoro.",al={"dove si trova hinott","luogo di consegna"}}},fp="19,100,19.369.0,26.295.1,40.154.0,20.172.0,44.181.0,44.166.0,45.147.0,30.113.0"}
P.entries["quest:249"] = {n="Morganth",s="Nelle Montagne Crestarossa, Morganth cerca la Falce di Elune mentre Theocritus lo osserva da lontano.",h="Nelle Montagne Crestarossa, Morganth cerca la Falce di Elune mentre Theocritus lo osserva da lontano.",kw={"elwynn","morganth","pendente dell'ombra","crestarossa","falce di elune","theocritus","torre di azora","torre di ilgalar"},ang={["class:Mage"]="Come mago, segui la diligente tradizione accademica di Theocritus. I maghi umani osservano il regno da alte torri per proteggerlo dagli incantatori rinnegati.",["class:Warlock"]="Come stregone, conosci i pericoli di ambizioni sfrenate legate alla magia vile e alle arti oscure. Braccare reliquie come la Falce di Elune conduce a una rapida rovina.",["faction:Alliance"]="Come membro dell'Alleanza, contribuisci a proteggere gli esposti confini orientali di Roccavento. Sconfiggere Morganth impedisce che le Montagne Crestarossa cadano sotto la stregoneria oscura.",["race:NightElf"]="Come elfo della Notte, dovresti allarmarti sentendo che la Falce di Elune è nelle mani degli umani. Il suo nome richiama misteri sacri e instabili per i kaldorei."},sec={{t="Un Osservatore Oltre il Confine",b="Dalla Torre di Azora, nella parte orientale della Foresta di Elwynn, Theocritus usa incantesimi di chiaroveggenza per osservare le rupi delle Montagne Crestarossa. Lì vede Morganth, uno stregone nella Torre di Ilgalar, alla ricerca della Falce di Elune. Temendo che Morganth sia vicino a impossessarsene, Theocritus chiede ai campioni dell'Alleanza di fermarlo prima che Roccavento sia minacciata."},{t="Assalto alla Guglia di Ghiaccio",b="La Torre di Ilgalar si erge sopra il bacino delle Montagne Crestarossa, dove vagano gli gnoll e le energie arcane contorcono i suoi corridoi. Morganth attende in cima, padroneggiando la Shadow Magic e proteggendo le sue ricerche. Ti fai strada in territorio ostile per affrontarlo direttamente. Riporta il suo Pendente dell'Ombra come prova che la torre è caduta e la minaccia è stata spezzata."},{t="L'Ombra Persistente della Falce",b="La sconfitta di Morganth rimuove una minaccia immediata per Roccavento, ma la sua ricerca della Falce di Elune mostra quanto lontano arrivi la leggenda oscura dell'artefatto. Theocritus è sollevato quando riceve il Pendente dell'Ombra. L'ubicazione dell'antica falce resta ignota nelle province circostanti, così come il caos che potrebbe scatenare."}},faq={{q="Chi è Morganth?",a="Morganth è un potente stregone rinnegato che vive in cima alla Torre di Ilgalar, nelle Montagne Crestarossa. Studia le arti oscure e cerca la Falce di Elune, un artefatto capace di scatenare una magia catastrofica.",al={"identità di morganth","chi è morganth","retroscena su morganth"}},{q="Dove si trova la Torre di Ilgalar?",a="La Torre di Ilgalar sorge nella parte orientale delle Montagne Crestarossa, oltre il Mastio di Guardamasso. Gli gnoll Shadowhide si accampano ai piedi della torre.",al={"posizione torre di ilgalar","dove si trova la torre di morganth","torre di crestarossa"}},{q="Perché Theocritus vuole Morganth morto?",a="Con gli incantesimi di chiaroveggenza, Theocritus scoprì che Morganth cercava la Falce di Elune e temeva fosse vicino a trovarla. Il potere che Morganth bramava minacciava le Montagne Crestarossa e il vicino regno di Roccavento.",al={"movente di theocritus","perché uccidere morganth","motivo missione theocritus"}},{q="Cos'è la Falce di Elune?",a="La Falce di Elune è un artefatto avvolto nel mistero. Theocritus non ne spiega i poteri, ma teme che, se Morganth la troverà, le Montagne Crestarossa e Roccavento subiranno la sua oscura potenza.",al={"storia falce di elune","cos'è la falce","perché la falce è pericolosa"}},{q="Cos'è il Pendente dell'Ombra?",a="Il Pendente dell'Ombra è il talismano magico di Morganth. Concentra le sue arti oscure; portarlo a Theocritus, alla Torre di Azora, dimostra che Morganth è stato sconfitto.",al={"pendente dell'ombra","pendente di morganth","prova morte di morganth"}},{q="Quale catena di missioni porta a questo?",a="La catena inizia con Theocritus' Retrieval nella Foresta di Elwynn, seguita da Un Occhio Vigile e Looking Further. Queste tappe permettono di recuperare strumenti e preparare la chiaroveggenza per sorvegliare la torre di Morganth. Questa è la parte finale della catena.",al={"catena missioni morganth","prerequisiti morganth","come sbloccare morganth"}}},fx={["23819dbd"]={q="Perché Theocritus ti manda ad affrontare Morganth invece di andarci lui?",a="Theocritus ammette senza tanti giri di parole di non essere pronto a misurare direttamente la propria potenza magica con quella di Morganth. Mentre sorveglia i confini dalla Torre di Azora e coordina le difese contro la magia delle ombre, un assalto alla Torre di Ilgalar richiede un avventuriero audace e capace, disposto a penetrare nella roccaforte dello stregone prima che le oscure ambizioni di Morganth minaccino tutta Roccavento.",al={"perché mandarmi","perché theocritus non combatte morganth","perché non ci va theocritus"}}},fp="8,87,27.327.0,18.335.0,29.330.1,16.217.0,30.126.0,39.210.0,28.191.0,30.166.0,34.214.0"}
P.entries["quest:2498"] = {n="Return to Denalan",s="Al Lago Al'ameth, porti a Denalan le allarmanti notizie di Rellian Greenspyre, il botanico che studia la corruzione di Teldrassil. Dopo aver esaminato i tumori muschiosi sui timberling, ti dirigi a sud per aiutare Denalan con la sua scoperta.",h="Al Lago Al'ameth, porti a Denalan le allarmanti notizie di Rellian Greenspyre, il botanico che studia la...",kw={"denalan","dolanaar","lago al'ameth","oakenscowl","rellian greenspyre","teldrassil","timberling","tumori"},ang={["class:Druid"]="Come druido, sai che indagare sui tumori innaturali degli spiriti dei boschi serve al dovere Cenarion di mantenere l'equilibrio della natura e purificare le piaghe.",["race:NightElf"]="Come elfo della Notte, conosci i timberling come segni viventi della vitalità di Teldrassil. Aiutare Denalan fa parte del tuo dovere di guarire la corruzione che minaccia la nuova casa del tuo popolo."},sec={{t="Un messaggio attraverso i rami",b="Rellian Greenspyre studia i tumori muschiosi che affliggono i timberling di Teldrassil quando riceve notizie urgenti dal collega Denalan. Nel suo accampamento accanto al Lago Al'ameth, Denalan è finalmente riuscito a isolare la causa di queste escrescenze innaturali sugli spiriti della natura della foresta. Rellian comprende la gravità della scoperta e ti manda subito a sud per dare una mano."},{t="La minaccia al lago",b="Al Lago Al'ameth, Denalan affronta creature corrotte che avvelenano i rami di Teldrassil. Il suo lavoro comincia con piante corrotte e timberling malati, poi lo porta a scontrarsi direttamente con il timberling corrotto Oakenscowl."}},faq={{q="Chi è Denalan?",a="Denalan è un ricercatore e naturalista elfo della Notte, al Lago Al'ameth, nella parte meridionale di Teldrassil. Studia le piante dell'isola, le strane mutazioni delle piantine e le afflizioni innaturali che si diffondono tra i timberling locali.",al={"lore denalan","chi è denalan","denalan lago al'ameth"}},{q="Perché Rellian Greenspyre ti manda di nuovo al Lago Al'ameth?",a="Rellian riceve notizie che Denalan ha trovato la probabile causa dei tumori che corrompono i timberling. La scoperta si fa rapidamente più chiara e minaccia la foresta, così Rellian ti manda subito ad aiutare sul campo.",al={"perché andare da denalan","missione rellian greenspyre"}},{q="Cosa sono i tumori che affliggono i timberling?",a="I timberling sono pacifici spiriti della natura nati dalla flora dell'isola, ma la corruzione che attecchisce a Teldrassil fa spuntare su di loro bizzarre escrescenze muschiose. Questi tumori rendono le creature ostili e fuori di sé.",al={"tumori timberling","perché i timberling hanno i tumori","tumori muschiosi"}},{q="Dove posso trovare Denalan?",a="Denalan ha un accampamento sulle rive del Lago Al'ameth, appena a sud di Dolanaar, nei boschi meridionali di Teldrassil.",al={"posizione denalan","dove si trova denalan"}},{q="Cosa succede dopo aver raggiunto Denalan?",a="Denalan accoglie volentieri il tuo aiuto e dice di aver scoperto qualcosa di inquietante. Quando raggiungi il suo accampamento, ti spiega cosa succederà.",al={"what comes next","proseguimento oakenscowl"}},{q="Come collega questa commissione Rellian e Denalan?",a="Rellian Greenspyre studia i timberling a Darnassus, mentre Denalan lavora dal suo accampamento al Lago Al'ameth. Le ricerche di Rellian sui tumori arrivano a Denalan, la cui nuova scoperta riguarda la loro causa.",al={"perché rellian mi manda da denalan","scopo return to denalan"}}},fp="17,222,27.349.0,22.223.1,15.214.0,59.211.0,47.214.0,25.109.0,37.129.1,49.198.0"}
P.entries["quest:2499"] = {n="Quercipiglio",s="Al Lago Al'ameth, il flagello si diffonde da Quercipiglio, un tempo guardiano di Teldrassil. Denalan ti chiede di porre fine alla minaccia. Lo spirito arboreo impazzito dimora in una caverna sulla sponda meridionale del lago.",h="Al Lago Al'ameth, il flagello si diffonde da Quercipiglio, un tempo guardiano di Teldrassil.",kw={"corruzione","denalan","tumore gigantesco","lago al'ameth","tumori muschiosi","oakenscowl","teldrassil","spirito arboreo"},ang={["class:Druid"]="Da druido, vedi un guardiano degli spiriti arborei deformato da strane escrescenze. Il giovane ecosistema di Teldrassil è gravemente malato.",["profession:Herbalism"]="Da erborista, mentre aiuti Denalan, vedi come una putrefazione invisibile deforma la vita vegetale trasformandola in flagelli maligni ricoperti di muschio.",["race:NightElf"]="Da elfo della notte, vedi come la caduta di Quercipiglio minacci il Lago Al'ameth, appena a sud di Dolanaar e vicino al cuore del tuo popolo."},sec={{t="Un Guardiano Caduto",b="Gli spiriti arborei si prendono cura dei rami di Teldrassil, e un tempo Quercipiglio li guidava. Ora la corruzione raggiunge tanto l'umile fauna dell'albero del mondo quanto i suoi antichi protettori. Una crescita enorme si gonfia sulla corteccia di Quercipiglio e fa impazzire lo spirito arboreo. Un tempo aveva il compito di proteggere la foresta. Ora il flagello prende piede."},{t="Purificare il Lago Al'Ameth",b="Quercipiglio si nasconde in una caverna sulla sponda meridionale del Lago Al'ameth. Da lì avvelena le acque vicine e le bestie dei boschi. Denalan non può affrontare la creatura da solo, perciò ne cerca la distruzione. Spera di arrestare la corruzione e studiare la strana crescita che affligge gli spiriti del lago."}},faq={{q="Chi è Oakenscowl?",a="Quercipiglio è un enorme spirito arboreo, uno spirito della foresta legato alla flora di Teldrassil. Un tempo guidava i suoi simili, prima che una crescita maligna prendesse piede.",al={"chi è oakenscowl","lore di oakenscowl","che tipo di creatura è oakenscowl"}},{q="Perché Oakenscowl deve essere distrutto?",a="L'enorme crescita di Quercipiglio gli ha contorto la mente e lo ha reso violentemente aggressivo. Dalla sua caverna presso il Lago Al'ameth, diffonde il flagello tra gli spiriti arborei e le bestie vicine.",al={"perché uccidere oakenscowl","oakenscowl ostile"}},{q="Dove risiede Oakenscowl?",a="Quercipiglio dimora in una caverna sulla sponda meridionale del Lago Al'ameth, nel sud di Teldrassil.",al={"posizione di oakenscowl","dov'è la caverna di oakenscowl"}},{q="Chi è Denalan e perché sta studiando il tumore?",a="Denalan è un erborista e naturalista che vive sulla sponda orientale del Lago Al'ameth. Studia piante e animali dell'albero del mondo, cercando di comprendere e curare la strana putrefazione che infetta gli spiriti arborei della zona.",al={"chi fornisce la missione di oakenscowl","denalan oakenscowl"}},{q="Cosa ha causato il tumore su Oakenscowl?",a="Il tumore di Quercipiglio indica una malattia più profonda che si diffonde nel suolo e nelle radici di Teldrassil. Corrompe gli spiriti della natura dall'interno.",al={"perché gli spiriti arborei hanno i tumori","fonte della corruzione"}},{q="Oakenscowl è oltre ogni salvezza?",a="Quando gli avventurieri trovano Quercipiglio, il suo male è ormai troppo avanzato. La crescita ha completamente deformato lo spirito arboreo, e Denalan chiede di porre fine alle sue sofferenze.",al={"oakenscowl può essere guarito","curare oakenscowl"}}},fx={a853a20e={q="A cosa serve a Denalan il Tumore Gigantesco?",a="Denalan ha bisogno del Tumore Gigantesco per studiare l'afflizione innaturale che avvelena i ramoscelli di Teldrassil. Ricercatore della natura, vive sulle rive del Lago Al'ameth e ha visto le creature cadere nella follia e nella corruzione. Poiché Oakenscowl aveva la crescita più grande che avesse mai visto, esaminare un esemplare così estremo offre a Denalan la migliore possibilità di capire la malattia che affligge la fauna locale.",al={"perché il tumore gigantesco","a cosa serve il tumore gigantesco","uso del tumore gigantesco"}},["47d0c5c8"]={q="Perché Denalan ha bisogno del tuo aiuto contro Oakenscowl?",a="Denalan è un ricercatore e un erborista isolato, non un guerriero capace di affrontare un enorme ramoscello corrotto nella sua tana. Ha ammesso di non aver osato nemmeno avvicinarsi alla bestia mentre perlustrava la riva meridionale. Poiché hai già dimostrato il tuo valore raccogliendo tumori muschiosi e aiutandolo nel suo lavoro, ti affida il compito di eliminare la minaccia che incombe sulla sua casa in riva al lago.",al={"perché io, denalan","perché mandare un avventuriero contro oakenscowl","perché denalan non può combattere oakenscowl"}}},fp="10,186,17.294.0,21.284.0,19.142.0,33.168.0,29.92.0,48.206.0,36.133.0,28.158.0"}
P.entries["quest:25"] = {n="Stonetalon Standstill",s="Al Lago Mystral, gli spiriti dell'acqua corrotti hanno bloccato i trasporti di rifornimenti dell'Orda diretti alle Vette di Petrartiglio. Mastok Soffionero, all'Avamposto di Troncorotto, ti manda a eliminare gli elementali ostili e a esplorare un gazebo degli Elfi della Notte che domina il Rifugio Vento Argentato.",h="Al Lago Mystral, gli spiriti dell'acqua corrotti hanno bloccato i trasporti di rifornimenti dell'Orda diretti...",kw={"water elemental contaminato","gazebo","mastok soffionero","lago mystral","avamposto di troncorotto","stonetalon standstill","sentiero di graffiofondo","tideress"},ang={["class:Shaman"]="Da sciamano, riconosci nello stato contorto degli elementali dell'acqua un segno di profonda disarmonia elementale nelle antiche foreste di Valtetra.",["faction:Horde"]="Come membro dell'Orda, sai che l'Avamposto di Troncorotto dipende da rotte di rifornimento aperte. Mantenere libero il Sentiero di Graffiofondo garantisce le comunicazioni e il commercio con le Vette di Petrartiglio.",["race:Orc"]="Da orco, sai che l'Orda dipende dal legname e dai sentieri di Valtetra per rifornire i suoi insediamenti. Le interruzioni delle linee di rifornimento montane non possono essere tollerate."},sec={{t="Una rotta di rifornimento soffocata",b="L'Orda ha bisogno di legname, rifornimenti e messaggeri che viaggino tra Valtetra e le Vette di Petrartiglio. Il Sentiero di Graffiofondo costeggia la riva occidentale del Lago Mystral, dove gli elementali dell'acqua ostili hanno bloccato il passaggio e assalito le carovane di rifornimenti. Mastok Soffionero chiede di intervenire prima che le linee di rifornimento dell'Orda collassino."},{t="Le acque corrotte",b="Gli elementali dell'acqua del Lago Mystral sono diventati corrotti, aggressivi e imprevedibili. Attaccano i viaggiatori sui sentieri vicini, quindi ti viene chiesto di decimarli e sconfiggere lo spirito maggiore Tideress. La causa della corruzione degli spiriti del lago è ancora ignota, nel mezzo dei disordini nei boschi sacri di Valtetra."},{t="Occhi oltre l'acqua",b="Un gazebo degli Elfi della Notte sorge sull'isola centrale del Lago Mystral e offre una visuale nitida sull'acqua fino al Rifugio Vento Argentato. Gli esploratori dell'Orda devono valutare se possa servire da avamposto d'osservazione avanzato. Da lì, i comandanti dell'Avamposto di Troncorotto potrebbero sorvegliare senza essere visti i movimenti dell'Alleanza nelle vicinanze."}},faq={{q="Cosa sta causando lo stallo vicino alle Vette di Petrartiglio?",a="Gli elementali dell'acqua corrotti del Lago Mystral sono diventati violenti e attaccano i viaggiatori sul vicino Sentiero di Graffiofondo. I loro assalti hanno bloccato i trasporti di rifornimenti tra Valtetra e le Vette di Petrartiglio.",al={"perché i trasporti sono bloccati","sentiero di graffiofondo bloccato","cosa ha bloccato la rotta di rifornimento"}},{q="Chi ordina di eliminare gli elementali?",a="Mastok Soffionero, un orco dell'Avamposto di Troncorotto, a Valtetra orientale, ti ordina di eliminare gli elementali e di esplorare la posizione dell'Alleanza.",al={"chi assegna stonetalon standstill","missione di mastok soffionero","chi è mastok"}},{q="Perché esplorare il gazebo nel mezzo del Lago Mystral?",a="Il gazebo sull'isola centrale del Lago Mystral offre una visuale sull'acqua verso il vicino insediamento degli Elfi della Notte, il Rifugio Vento Argentato. Mastok vuole valutare se possa diventare un posto d'osservazione nascosto per sorvegliare i movimenti nemici.",al={"perché esplorare il gazebo","scopo del gazebo del lago mystral","gazebo come posto di osservazione"}},{q="Cos'è il Sentiero di Graffiofondo?",a="Il Sentiero di Graffiofondo è il sentiero montano che collega il sudovest di Valtetra alle Vette di Petrartiglio. Passa accanto alla riva occidentale del Lago Mystral.",al={"posizione sentiero di graffiofondo","sentiero per le vette di petrartiglio","strada delle vette di petrartiglio"}},{q="Perché gli elementali dell'acqua del Lago Mystral sono corrotti?",a="La causa della corruzione degli elementali dell'acqua è ignota. I disordini a Valtetra hanno sconvolto il lago e reso i suoi spiriti ostili agli estranei.",al={"perché gli elementali sono corrotti","acqua del lago mystral corrotta","origine degli elementali contaminati"}},{q="Quale avamposto dell'Alleanza viene sorvegliato dal gazebo?",a="Il gazebo domina il Rifugio Vento Argentato, un insediamento degli Elfi della Notte appena a nord del lago. Le Sentinelle lì difendono Valtetra dalle operazioni di raccolta del legname dell'Orda.",al={"quale base dell'alleanza vicino al lago mystral","avamposto dell'alleanza a valtetra"}}},fx={["46f9d708"]={q="Contro cosa combatti al Lago Mystral?",a="Ti mandano a distruggere gli elementali dell'acqua corrotti che abitano il Lago Mystral, oltre a Tideress. Le acque del lago si sono animate e aggrediscono chiunque percorra la strada vicina.",al={"bersagli al lago mystral","contro chi ti mandano","cosa uccidere per stonetalon standstill"}}},fp="21,237,21.322.0,20.296.0,21.289.0,47.204.0,34.135.0,51.221.0,27.148.0,54.146.0,56.171.0"}
P.entries["quest:250"] = {n="A Dark Threat Looms",s="Il Capo Ingegnere Hinderweir VII teme che genieri Ferroscuro vicino alla rampa orientale minaccino la Diga di Pietrasalda. Con gran parte della guarnigione inviata al Fronte dell'Alleanza, indaghi sul pericolo.",h="Il Capo Ingegnere Hinderweir VII teme che genieri Ferroscuro vicino alla rampa orientale minaccino la Diga di...",kw={"ferroscuro","dun modr","hinderweir","loch modan","genieri","diga di pietrasalda","barile sospetto","viadotto di thandol"},ang={["faction:Alliance"]="Come recluta dell'Alleanza, aiuti a proteggere importanti centri di rifornimento e opere regionali, mentre gli eserciti in prima linea sono sparsi per tutto il continente.",["profession:Engineering"]="Come ingegnere, puoi vedere l'immensa portata della diga e il pericolo rappresentato dai genieri che usano esplosivi chimici volatili contro le fondamenta portanti.",["race:Dwarf"]="Come nano, conosci la Diga di Pietrasalda come un capolavoro d'artigianato e motivo d'orgoglio nanico. I tuoi parenti Ferroscuro la minacciano e tu difendi la tua patria."},sec={{t="Una Meraviglia Vulnerabile",b="La Diga di Pietrasalda trattiene le acque del Loch Modan. Gli ingegneri di Forgiardente l'hanno costruita come una grande opera, ma gran parte del personale di sicurezza è stata inviata al Fronte dell'Alleanza. Se ci sarà un attacco, il Capo Ingegnere Hinderweir VII e la sua piccola squadra avranno ben poca protezione."},{t="Echi dal Nord",b="I nani Ferroscuro hanno colpito il Viadotto di Thandol e saccheggiato Dun Modr nelle Paludi Grigie. Ora, alcuni genieri già noti si aggirano vicino alla rampa orientale della diga. Hinderweir teme che il clan abbia preso di mira l'ancora di salvezza del Loch Modan e voglia demolirla."},{t="Il Barile Sospetto",b="Tra le rocce dove si erano radunati i genieri giace un barile sospetto. Al suo interno c'è polvere volatile dall'odore strano. Il barile rivela i preparativi per far saltare le fondamenta della Diga di Pietrasalda."}},faq={{q="Perché il Capo Ingegnere Hinderweir è preoccupato per la diga?",a="Le forze Ferroscuro hanno colpito il Viadotto di Thandol e saccheggiato Dun Modr nelle Paludi Grigie. Quando Hinderweir ha visto i loro genieri vicino alla rampa orientale della Diga di Pietrasalda, ha temuto che la diga fosse il loro prossimo bersaglio.",al={"preoccupazione di hinderweir","minaccia alla diga di pietrasalda","perché attaccare la diga"}},{q="Dove è finita la guarnigione della diga?",a="La maggior parte delle forze di sicurezza della Diga di Pietrasalda è stata riassegnata al Fronte dell'Alleanza. Il miglior ispettore di Hinderweir è partito con loro, lasciando la diga scarsamente difesa.",al={"perché non ci sono guardie alla diga","sicurezza della diga","dove sono i soldati"}},{q="Cosa trovi alla rampa orientale?",a="Vicino alla rampa orientale trovi un barile sospetto, pieno di polvere dall'odore strano. La sua presenza conferma che i Ferroscuro si stanno preparando a sabotare la diga.",al={"qual è l'indizio","indizio del barile sospetto","cosa stanno facendo i genieri"}},{q="Qual è il significato strategico della Diga di Pietrasalda?",a="La Diga di Pietrasalda regola il bacino del Loch Modan. Se crollasse, l'alluvione devastarebbe le Paludi Grigie e prosciugherebbe il cuore del territorio nanico.",al={"perché distruggere la diga","cosa succede se la diga crolla","storia della diga"}},{q="Qual è stato l'attacco a Dun Modr menzionato da Hinderweir?",a="Dun Modr era un avamposto nanico fortificato nella parte settentrionale delle Paludi Grigie, vicino al Viadotto di Thandol. Gli infiltrati Ferroscuro sopraffecero la città e colpirono il viadotto, interrompendo importanti vie di rifornimento via terra.",al={"attacco a dun modr","cosa è successo a dun modr","distruzione del viadotto di thandol"}},{q="Chi prende di mira il Loch Modan, tra i nani Ferroscuro?",a="Il clan Ferroscuro è da tempo acerrimo rivale dei nani Barbabronzea, fin dalla Guerra dei Tre Martelli. Dal Massiccio Roccianera e dalla Gorgia Rovente, spesso sabota le infrastrutture dei Barbabronzea e le difese di confine.",al={"chi sono i ferroscuro","motivo dei genieri ferroscuro","perché i ferroscuro odiano forgiardente"}}},fx={f99be494={q="Perché ci sono sabotatori Ferroscuro alla Diga di Pietrasalda?",a="Dopo aver attaccato il Viadotto di Thandol e la città di Dun Modr a nord, i nani Ferroscuro si sono spinti furtivamente a sud, a Loch Modan. Capo Ingegnere Hinderweir ha notato i loro sabotatori aggirarsi di nascosto presso la rampa orientale della Diga di Pietrasalda e sospetta che intendano sabotare anche questa enorme struttura.",al={"sabotatori ferroscuro alla diga","perché i ferroscuro sono alla diga","sabotatori ferroscuro a loch modan"}}},fp="19,196,19.267.0,21.221.0,19.194.1,55.196.0,32.161.0,37.160.1,59.148.0,56.196.0,51.230.0"}
P.entries["quest:251"] = {n="Translate Abercrombie's Note",s="A Borgoscuro, una lettera misteriosa arriva ai capi della città perché venga tradotta. Il sindaco Ello Serranero si rivolge a Sirra Von'indi, lo studioso esperto di scritture oscure.",h="A Borgoscuro, una lettera misteriosa arriva ai capi della città perché venga tradotta.",kw={"abercrombie","cifrario","borgoscuro","boscovespro","ello serranero","eremita","sirra von'indi","traduzione"},ang={["class:Mage"]="Da mago, potresti riconoscere il lavoro che Sirra Von'indi intraprende mentre studia le scritture oscure di Borgoscuro.",["faction:Alliance"]="In quanto campione dell'Alleanza che aiuta Boscovespro, vedi quanto si sentono vulnerabili e isolati i capi di Borgoscuro, circondati dall'oscurità."},sec={{t="Un Messaggio Indecifrabile",b="Abercrombie manda al sindaco Ello Serranero una lettera sigillata dalla sua dimora. Serranero si aspetta un'eccentrica supplica o amare invettive dall'eremita del cimitero, ma la pergamena reca una scrittura misteriosa che il Comune non può decifrare. Il sindaco non sa leggere lingue antiche o oscure, quindi non la liquida. Anche un eremita folle può rappresentare un pericolo a Boscovespro."},{t="Lo Studioso di Borgoscuro",b="Serranero ti manda dall'altra parte della piazza da Sirra Von'indi, lo studioso di Borgoscuro esperto di conoscenze esoteriche. Sirra conosce le arti antiche e le lingue dimenticate. Si fa beffe della sanità mentale di Abercrombie e dice che chiunque viva accanto a un cimitero infestato deve avere il cervello marcio. Eppure prende sul serio la pergamena e comincia il lento lavoro di trascrizione."},{t="Uno Sguardo nella Mente dell'Eremita",b="La lettera cifrata di Abercrombie rivela una mente ben diversa da quella del fragile e solitario vecchio che chiede provviste e protezione dai ghoul. Il suo messaggio annuncia una resa dei conti, e Borgoscuro è mal preparata ad affrontarla."}},faq={{q="Perché il sindaco Serranero non riesce a leggere la nota da solo?",a="Il sindaco Ello Serranero non sa leggere la strana scrittura della lettera, quindi la affida a Sirra Von'indi, lo studioso di Borgoscuro esperto di scritture oscure.",al={"perché ello non riesce a leggere la nota","traduzione lettera serranero","perché serve un traduttore"}},{q="Chi è Sirra Von'indi?",a="Sirra Von'indi è lo studioso di Borgoscuro, noto per la sua conoscenza di lingue oscure, storia e arti antiche. Esamina testi misteriosi e reliquie provenienti dai boschi circostanti.",al={"chi è sirra von indi","chi è il traduttore","studioso di borgoscuro"}},{q="Dove vive Abercrombie?",a="Abercrombie vive in una baracca malandata appena a nord-est del Cimitero di Collecorvo, nella parte occidentale di Boscovespro, tra non morti inquieti e bestie feroci.",al={"dove si trova abercrombie","posizione eremita","abercrombie boscovespro"}},{q="Qual è la reazione di Sirra alla nota di Abercrombie?",a="Sirra dubita della sanità mentale di Abercrombie e dice che chiunque viva accanto a un cimitero deve avere il cervello marcio. Eppure esamina la lettera e comincia a tradurne la scrittura oscura.",al={"cosa pensa sirra di abercrombie","dialogo sirra von indi"}},{q="Cosa succede dopo aver consegnato la nota a Sirra?",a="Sirra Von'indi ti chiede di aspettare mentre trascrive la lettera. Quando ha finito, riporti la traduzione a Ser Ello Serranero.",al={"missione successiva dopo traduci nota","cosa succede dopo traduci la nota di abercrombie"}},{q="Perché Abercrombie ha scritto al sindaco Serranero?",a="Abercrombie ha scritto al sindaco Serranero in una scrittura che Ello non sa leggere. La traduzione di Sirra Von'indi rivela ciò che ha scritto l'eremita.",al={"perché abercrombie ha inviato la lettera","scopo nota eremita"}}},fp="28,164,25.356.0,24.337.0,32.205.1,48.134.0,22.179.0,28.142.0,47.176.0,44.137.1,45.126.1"}
P.entries["quest:2518"] = {n="Lacrime della luna",s="Al Temple of the Moon, la Sacerdotessa A'moora piange Lady Sathrah. Un tempo benedetta da Elune, ora la ragna è una minaccia, e The Sisterhood of Elune vuole alleviarne le sofferenze e recuperare le sue filiere sacre.",h="Al Temple of the Moon, la Sacerdotessa A'moora piange Lady Sathrah.",kw={"darnassus","elune","lady sathrah","sacerdotessa a'moora","filatura argentea","lacrime della luna","teldrassil","temple of the moon","lago di buonpozzo"},ang={["class:Druid"]="Come druido, vedi la ferocia improvvisa e il tormento di Sathrah come un altro segno preoccupante dello squilibrio di Teldrassil. Restituire la pace al suo spirito è necessario per la salute della natura selvaggia.",["class:Priest"]="Come sacerdote di The Sisterhood of Elune, sai che la misericordia può richiedere un colpo doloroso e un'offerta rituale per ricondurre un'anima corrotta all'abbraccio della Dea.",["race:NightElf"]="Come Kaldorei, sai che la corruzione nelle terre selvagge di Teldrassil non risparmia né le bestie più umili né le sacre compagne di Elune."},sec={{t="La caduta di una creatura amata",b="Al Temple of the Moon di Darnassus, la Sacerdotessa A'moora piange Lady Sathrah. Un tempo Elune aveva benedetto la ragna. Sotto il cielo notturno, Sathrah tesseva ragnatele argentate tra i rami di Teldrassil, dove si raccoglieva la nebbia serale. The Sisterhood of Elune raccoglieva la rugiada scintillante per le sue proprietà curative durante i riti sacri."},{t="Misericordia per Sathrah",b="Lady Sathrah è impazzita, come gran parte della fauna selvatica del giovane Albero del Mondo. Vicino al Lago di Buonpozzo, nelle terre settentrionali, la sua furia minaccia i viaggiatori e le sue covate non ancora schiuse. The Sisterhood of Elune non può purificarla mentre è in preda a un violento accesso di furia, perciò ha deciso di porre fine alle sue sofferenze per pietà.\n\nLe sacerdotesse intendono recuperare la Filatura Argentea di Sathrah e consacrare i suoi resti sull'altare di Elune. Pregano che la Dea della Luna le conceda la pace e una rinascita pura."}},faq={{q="Chi è Lady Sathrah?",a="Lady Sathrah è un'antica ragna originaria di Teldrassil, un tempo amata da Elune. Le sue ragnatele argentate catturavano la nebbia notturna, la cui rugiada aveva proprietà curative.",al={"storia lady sathrah","chi è lady sathrah","retroscena sathrah","ragna sathrah"}},{q="Perché Lady Sathrah deve essere uccisa?",a="Lady Sathrah è impazzita, come la fauna selvatica di Teldrassil. È violenta e pericolosa per la sua prole e per gli altri, così The Sisterhood of Elune intende ucciderla per pietà.",al={"perché uccidere sathrah","sathrah può essere salvata","perché sathrah è aggressiva"}},{q="Dove si trova Lady Sathrah?",a="Lady Sathrah si trova nella parte settentrionale di Teldrassil, vicino alle rive del Lago di Buonpozzo.",al={"posizione lady sathrah","dove si trova sathrah","trovare sathrah"}},{q="A cosa servivano le ragnatele di Lady Sathrah?",a="Le ragnatele di Lady Sathrah catturavano la nebbia serale, formando una rugiada argentata dalle proprietà curative. The Sisterhood of Elune la conservava al Temple of the Moon.",al={"significato lacrime della luna","uso ragnatele sathrah","storia rugiada argentea"}},{q="Chi assegna la missione Lacrime della Luna?",a="La Sacerdotessa A'moora affida questo compito ad avventurieri fidati dell'Alleanza, al Temple of the Moon di Darnassus.",al={"chi assegna lacrime della luna","conferitore missione lacrime della luna","sacerdotessa amoora"}},{q="Che cosa faranno le sacerdotesse con le filiere di Sathrah?",a="Le sacerdotesse intendono offrire le filiere di Sathrah a Elune, sull'altare del tempio. Chiedono alla dea di accogliere lo spirito di Sathrah, benedirla e concederle una rinascita serena.",al={"che ne sarà delle filiere","a cosa servono le filiere","sacrificio a elune"}}},fp="17,205,25.317.0,17.497.1,20.148.0,40.199.0,28.81.0,39.144.0,38.105.0,55.174.0"}
P.entries["quest:2519"] = {n="The Temple of the Moon",s="A Darnassus, Sorella Aquinne chiede aiuto per un'antica creatura sofferente a Teldrassil. La Sisterhood of Elune non può occuparsene da sola e il suo appello dà inizio a un solenne rituale di misericordia.",h="A Darnassus, Sorella Aquinne chiede aiuto per un'antica creatura sofferente a Teldrassil.",kw={"darnassus","elune","sacerdotessa a'moora","sathrah","sorella aquinne","the sisterhood of elune","giardini del tempio","temple of the moon"},ang={["class:Druid"]="Come druido, ti sta a cuore quando una grande creatura selvaggia è in difficoltà. L'appello dai Giardini del Tempio ti chiede di contribuire a ristabilire l'armonia naturale.",["class:Priest"]="Come sacerdote, potresti sentirti attratto dal lavoro della Sisterhood of Elune a Darnassus. Aiuti gli altri servitori del divino con riti di guarigione e misericordia.",["race:NightElf"]="Come Elfo della Notte, contribuisci a proteggere il sacro ecosistema di Teldrassil e a seguire la guida del sacerdozio di Elune quando rispondi a Sorella Aquinne."},sec={{t="Una supplica nei giardini",b="Nei Giardini del Tempio di Darnassus, Sorella Aquinne ti chiede di aiutare una venerabile creatura della foresta che soffre. Serve Elune e parla a nome del suo ordine. Le Sorelle non possono occuparsene da sole."},{t="Nel The Temple of the Moon",b="Sorella Aquinne ti manda a sud-est, al Temple of the Moon. Qui, la Sacerdotessa A'moora coordina i rituali e le mansioni pratiche per la fauna in difficoltà di Teldrassil. Prepara gli alleati a un doloroso atto di misericordia."}},faq={{q="Chi avvia la missione The Temple of the Moon?",a="Sorella Aquinne lancia il suo appello dal quartiere dei Giardini del Tempio a Darnassus.",al={"datore missione the temple of the moon","dove prendere missione the temple of the moon","chi dà the temple of the moon"}},{q="Dove si trova la Sacerdotessa A'moora?",a="La Sacerdotessa A'moora si trova all'interno del Temple of the Moon, appena a sud-est dei Giardini del Tempio di Darnassus.",al={"dove si trova sacerdotessa a'moora","trovare a'moora","posizione sacerdotessa a'moora"}},{q="Qual è la creatura che ha bisogno di aiuto?",a="La creatura è Sathrah, un ragno venerato di Teldrassil. La sua sorte porta a un rituale di misericordia guidato dal sacerdozio.",al={"quale creatura ha bisogno di aiuto","chi è la creatura della foresta","di cosa tratta questa catena di missioni"}},{q="Questa missione è obbligatoria per proseguire la catena?",a="No. Il Temple of the Moon è una prima tappa facoltativa. Puoi parlare direttamente con la Sacerdotessa A'moora all'interno del tempio e assumerti i compiti del rituale senza passare prima da Sorella Aquinne.",al={"the temple of the moon è necessaria","posso saltare the temple of the moon","the temple of the moon missione di collegamento"}},{q="Quale missione segue questa?",a="La Sacerdotessa A'moora ti affida Tears of the Moon. Ti chiede di porre fine alle sofferenze di Lady Sathrah e di riportarle la Filatura Argentea.",al={"missione successiva dopo the temple of the moon","seguito di the temple of the moon","what comes next"}},{q="Perché The Sisterhood of Elune chiede aiuto agli esterni?",a="La corruzione persiste nella flora e nella fauna di Teldrassil e mette a dura prova la Sisterhood of Elune. Le sacerdotesse cercano viaggiatori capaci, rispettosi della natura e della Dea.",al={"perché chiedere agli esterni","perché il sacerdozio ha bisogno di aiuto","motivo sorella aquinne"}}},fx={e3d31678={q="Perché Sorella Aquinne ti manda dalla Sacerdotessa A'moora?",a="Sorella Aquinne riconosce che una venerabile creatura delle foreste di Teldrassil sta soffrendo e ha un disperato bisogno d'aiuto, ma la questione richiede la guida diretta del sacerdozio. Sapendo che ti attende un compito delicato e difficile, indirizza i viaggiatori capaci dalla Sacerdotessa A'moora, nel Temple of the Moon, affinché ricevano le istruzioni adeguate su come intervenire.",al={"perché sorella aquinne vuole questo","perché mandarmi al temple of the moon","scopo di sorella aquinne"}}},fp="22,184,21.189.0,20.213.0,44.81.0,35.102.0,37.122.0,46.186.0,34.127.0,57.158.0"}
P.entries["quest:252"] = {n="Translation to Ello",s="A Boscovespro porti la traduzione di Sirra Von'indi a Ser Ello Serranero, a Borgoscuro. Fa parte della storia di Abercrombie e la lettera riporta notizie degli scritti di The Hermit.",h="A Boscovespro porti la traduzione di Sirra Von'indi a Ser Ello Serranero, a Borgoscuro.",kw={"abercrombie","borgoscuro","ello serranero","collecorvo","sirra von'indi","translation to ello"},ang={["faction:Alliance"]="Come campione dell'Alleanza, affronti una dura lezione sui tradimenti di Boscovespro: fidarsi delle persone sbagliate nei boschi può mettere in pericolo un intero insediamento di cittadini innocenti."},sec={{t="Una Realizzazione Tardiva",b="Le richieste di Abercrombie hanno tenuto i viaggiatori in giro per Boscovespro per giorni. L'anziano eremita chiedeva filo, reagenti conservati ed effetti personali, sostenendo che gli servissero per sopravvivere. Sirra Von'indi ha finalmente decifrato la sua pergamena privata, rivelando la verità: il gentile vecchio è un imbalsamatore squilibrato. I componenti raccolti sono serviti a creare una terrificante arma di vendetta diretta contro Borgoscuro."},{t="La Strada per Borgoscuro",b="Quando la lettera tradotta giunge a Ser Ello Serranero, il sindaco sbianca in volto. Qualunque nobile motivo ti abbia spinto ad aiutare, consegnare quelle ultime forniture ha permesso ad Abercrombie di completare la sua mostruosa creazione, Cuciture. La consegna della lettera mette in marcia il colosso verso est, lungo la strada dal Cimitero di Collecorvo. Ogni pattuglia della Night Watch sul suo cammino viene massacrata."}},faq={{q="Cosa c'è scritto nella lettera tradotta?",a="Sirra teme che Abercrombie abbia compiuto qualcosa di indicibile. Porta subito la lettera tradotta a Ser Ello Serranero, che può valutare il pericolo per Borgoscuro.",al={"cosa dice la lettera","testo della lettera di abercrombie","cosa è stato tradotto"}},{q="Chi è Sirra Von'Indi?",a="Sirra Von'indi è uno studioso che vive a Borgoscuro. La sua abilità con le lingue e nell'analisi gli permette di decifrare gli appunti e le lettere criptiche di Abercrombie, quando gli altri non riescono a leggere la scrittura.",al={"chi è sirra","lore di sirra von indi"}},{q="Perché Ser Ello incolpa il giocatore?",a="La reazione di Ser Ello arriverà quando leggerà la lettera tradotta. Portagli l'avvertimento il prima possibile.",al={"perché ello è arrabbiato","ho causato la nascita di cuciture","reazione di ello"}},{q="Cosa succede subito dopo aver completato questa missione?",a="Porta la lettera tradotta a Ser Ello Serranero, a Borgoscuro. La sua risposta e il pericolo descritto nella lettera emergeranno quando la leggerà.",al={"cosa scatena cuciture","cuciture appare","evento di cuciture"}},{q="Dove va Cuciture dopo questo?",a="Cuciture è legato alla strada tra il Cimitero di Collecorvo e Borgoscuro. Il suo ruolo nel piano di Abercrombie emergerà durante le indagini.",al={"percorso di cuciture","dove sta marciando cuciture"}},{q="Quale missione viene dopo?",a="Dopo che avrai consegnato la lettera, Ser Ello manderà gli avventurieri da Bride of the Embalmer.",al={"prossima missione","dopo translation to ello"}}},fx={["203575b3"]={q="Perché Sirra Von'indi vuole che la lettera venga consegnata a Ello?",a="Dopo aver decifrato la lettera, Sirra ha capito che Abercrombie ha compiuto qualcosa di indicibile e scatenato una mostruosa calamità che sta già avanzando verso Borgoscuro. Ti manda ad avvertire subito Ser Ello Serranero, affinché i capi della città possano prepararsi all'imminente catastrofe prima che raggiunga le porte.",al={"perché consegnare la lettera a ello","motivo di sirra von'indi","perché consegnare la lettera tradotta"}},["4e225af8"]={q="Perché Sirra ti manda ad avvertire Ser Ello invece di andarci lui?",a="È stato Ser Ello ad affidarti il compito di decifrare gli scritti sospetti di Abercrombie, e sei stato tu a portare la strana lettera a Sirra. Con una minaccia mostruosa già in marcia e ogni secondo prezioso, mandare l'avventuriero capace che si trova proprio davanti a lui è il modo più rapido per far arrivare l'avvertimento al sindaco.",al={"perché io per translation to ello","perché sirra non va da ello","perché mandare il giocatore da ello"}}},fp="19,177,21.388.1,21.368.1,41.154.0,22.179.0,36.109.0,53.137.1,34.137.2,22.90.1"}
P.entries["quest:2520"] = {n="Sacrificio di Sathrah",s="Al Temple of the Moon, Sacrificio di Sathrah offre a Lady Sathrah un ultimo rito. Porti le sue Silvery Spinnerets alle acque sacre di Elune, dove il Priesthood cerca di purificare la sua anima dalla corruzione.",h="Al Temple of the Moon, Sacrificio di Sathrah offre a Lady Sathrah un ultimo rito.",kw={"a'moora","darnassus","elune","fontana","lady sathrah","purificazione","sathrah","filature","teldrassil","temple of the moon"},ang={["class:Druid"]="Come druido, puoi trovare conforto nel sapere che le bestie cadute possono tornare al ciclo naturale attraverso la purificazione, anche mentre la malattia affligge Teldrassil.",["class:Priest"]="Come sacerdote, vedi come la Sacra Luce di Elune e le sue acque sacre possano risanare gli spiriti colpiti dalla follia e dalla corruzione.",["race:NightElf"]="Come Elfo della Notte, onori la flora e la fauna di Kalimdor con questo rito solenne. Anche quando una creatura deve essere uccisa, la grazia di Elune onora e purifica il suo spirito."},sec={{t="Una purificazione nelle acque sacre",b="Dopo che Lady Sathrah viene uccisa, la Sacerdotessa A'moora ti chiede di compiere per lei un ultimo rito. La follia oscura che si diffonde su Teldrassil ha trasformato la natura pacifica del grande ragno in un'aggressività insensata. Il Priesthood of Elune cerca di redimere la sua essenza caduta, non di trattare la sua morte come un semplice abbattimento. Poni le sue Silvery Spinnerets nella fontana al centro del Temple of the Moon. Le sue acque consacrate lavano via la corruzione e le donano la liberazione."},{t="Il rinnovamento di Sathrah",b="Lo spirito pacifico di Lady Sathrah si leva quando le sue Silvery Spinnerets toccano la pozza illuminata dalla luna. Purificata dall'afflizione che l'aveva resa folle, la Sisterhood of Elune la considera salva. La perdita della grande creatura si fa sentire profondamente, ma la fede degli Elfi della Notte insegna che la purificazione sacra può permetterle un giorno di rinascere con uno spirito non corrotto."}},faq={{q="Chi era Lady Sathrah?",a="Lady Sathrah era un grande ragno che viveva su Teldrassil e soccombette alla corruzione che si diffondeva tra le creature viventi del World Tree. La contaminazione la rese folle e dovette essere uccisa, affinché i suoi resti potessero essere santificati.",al={"lady sathrah","chi è sathrah","cos'è sathrah"}},{q="Dove viene offerto il sacrificio?",a="Offri il sacrificio nella fontana sacra al centro del Temple of the Moon, il santuario principale della Sisterhood of Elune a Darnassus.",al={"dove metto il sacrificio","posizione fontana","fontana del tempio"}},{q="Cosa accade quando poni le filature nella fontana?",a="Quando poni le Silvery Spinnerets nelle acque benedette, lo spirito purificato di Sathrah appare per un breve istante nella pozza e si allontana libero e in pace. È il segno che Elune l'ha accolta.",al={"cosa succede alla fontana","spirito di sathrah fontana"}},{q="Perché Lady Sathrah doveva morire?",a="La corruzione nella mente di Lady Sathrah era troppo profonda per essere curata mentre era in vita. La Sacerdotessa A'moora e la Sisterhood credevano di poter salvare la sua anima solo ponendo fine alle sue sofferenze e purificando i suoi resti nelle acque sacre di Elune.",al={"perché uccidere sathrah","sathrah poteva essere salvata","follia di sathrah"}},{q="Chi assegna la missione Sacrificio di Sathrah?",a="La Sacerdotessa A'moora assegna e conclude Sacrificio di Sathrah al Temple of the Moon di Darnassus, affacciata sulla sala centrale.",al={"chi assegna la missione","dove consegnare la missione","posizione di amoora"}},{q="Quale convinzione è alla base di questo rituale per gli Elfo della Notte?",a="Gli Elfi della Notte credono che le anime purificate dalla Madre Luna possano rinascere nel mondo naturale, rinnovate e libere dalla corruzione.",al={"reincarnazione elfo della notte","purificazione di elune","lore della rinascita"}}},fx={f4be164d={q="Perché la Sacerdotessa A'moora vuole che tu lo faccia?",a="La Sacerdotessa A'moora vuole dare pacificamente sepoltura a Lady Sathrah ed estirpare la corruzione che tormentava la creatura un tempo nobile. Collocando le filiere di Sathrah nelle acque sacre del Temple of the Moon, la grazia di Elune può purificare la contaminazione residua che ha fatto impazzire il grande ragno, permettendo al suo spirito di redimersi e infine rinascere rinnovato.",al={"motivo di a'moora","perché offrire il sacrificio","perché a'moora vuole il sacrificio di sathrah"}}},fp="19,193,28.462.0,22.335.1,21.212.0,31.143.0,59.180.1,33.225.0,40.130.0,54.123.0"}
P.entries["quest:253"] = {n="Bride of the Embalmer",s="A Borgoscuro, Ser Ello Serranero ti manda a cercare la tomba di Eliza. Ora la città sa che l'Imbalsamatore esiste davvero. Devi strappare il suo cuore ancora pulsante dai resti maledetti di lei e privarlo del suo potere.",h="A Borgoscuro, Ser Ello Serranero ti manda a cercare la tomba di Eliza.",kw={"alchimista","bride of the embalmer","borgoscuro","boscovespro","eliza","ser ello serranero","cuore dell'imbalsamatore","tomba","l'imbalsamatore"},ang={["class:Paladin"]="Da paladino, puoi vedere nella ripugnante rianimazione di Eliza un affronto alla Luce e alle leggi della natura. Puoi purificare l'orrore divoratore di carne e recidere il blasfemo legame vitale del negromante.",["class:Priest"]="Da sacerdote, puoi riconoscere la tragedia del vedovo in lutto. Eppure, la famelica imitazione della vita che è Eliza deve trovare riposo una volta per tutte, per mano sacra.",["faction:Alliance"]="Con The Night Watch impegnata a fronteggiare gli orrori ferini di Boscovespro, devi intervenire come campione dell'Alleanza e difendere Borgoscuro da questa follia antica e strisciante."},sec={{t="Una favola della buonanotte che prende vita",b="I bambini di Boscovespro crescevano ascoltando storie sull'Imbalsamatore. Si diceva che fosse un alchimista gentile, impazzito dopo la morte dell'amata moglie, Eliza. Disperato all'idea di poter ingannare la morte, si rivolse alla stregoneria, si strappò il cuore ancora pulsante e lo mise nel petto di lei. Un tempo Ser Ello Serranero liquidava la storia come folklore paesano. Recenti scoperte provano che l'Imbalsamatore è tra i vivi e che le sue opere imputridiscono sotto la terra del cimitero."},{t="La sposa resuscitata",b="Eliza tornò in vita a un prezzo terribile. La scintilla rubata la rianimò come un abominio famelico, condannato ad avere sempre fame di carne umana viva. Inorridito da ciò che aveva creato e incapace di distruggerla, l'Imbalsamatore nascose la sua sposa in una tomba isolata. Andava a trovarla di nascosto mentre tramava altre malefatte.\n\nOra Ser Ello Serranero ti manda a scoprire la tomba di Eliza e a uccidere l'orrore affamato di carne. Prendi il cuore ancora pulsante che alimenta l'arte oscura dell'Imbalsamatore."},{t="L'egida di Borgoscuro",b="Quando porti a Borgoscuro il cuore pulsante di Eliza, Ser Ello Serranero si sente sollevato. Il sindaco non intende distruggerlo. Vuole usare contro l'alchimista la sua stessa arte, sfruttando la magia arcana del cuore come talismano difensivo per Borgoscuro.\n\nSpera che protegga la città assediata da qualsiasi ira l'Imbalsamatore indebolito riesca ancora a scatenare per vendicarsi."}},faq={{q="Chi è l'Imbalsamatore?",a="L'Imbalsamatore era un alchimista di Boscovespro, impazzito dopo la morte della moglie, Eliza. Si rivolse alla negromanzia e si strappò il cuore ancora vivo. Mettendolo nel cadavere di lei, la rianimò e divenne un mostro sfuggente.",al={"folclore imbalsamatore","chi è l'imbalsamatore","storia imbalsamatore"}},{q="Perché Eliza è stata sepolta se è stata riportata in vita?",a="L'alchimista rianimò Eliza con il proprio cuore, ma la magia oscura la rese famelica di carne umana viva. Incapace di riportarla in sicurezza tra la gente o di placare la sua fame ferina, la nascose in un cimitero.",al={"perché eliza è sepolta","tomba di eliza","perché tenere eliza in una tomba"}},{q="Perché Ser Ello Serranero vuole il Cuore dell'Imbalsamatore?",a="Ello crede che il cuore dell'Imbalsamatore sia la fonte del suo potere. Ti chiede di prenderlo dalla tomba di Eliza mentre batte ancora, nella speranza di spezzare il potere dell'alchimista.",al={"perché prendere il cuore","scopo cuore imbalsamatore"}},{q="Dove inizia questa catena di missioni?",a="La catena prosegue direttamente da «Translation to Ello». Le vecchie lettere e le ricerche consegnate a Ser Ello Serranero provano che l'Imbalsamatore delle storie locali per bambini è attivo e pericoloso.",al={"prerequisito missione","come ottenere bride of the embalmer","pre-missione imbalsamatore"}},{q="Il recupero del cuore sconfigge definitivamente l'Imbalsamatore?",a="Ello crede che prendere il cuore spezzerà il potere dell'Imbalsamatore. Scoprirai cosa succede quando tornerai a Borgoscuro.",al={"l'imbalsamatore è morto","questo uccide l'imbalsamatore"}},{q="Chi assegna questa missione?",a="Ser Ello Serranero, sindaco e capo di Borgoscuro, ti affida questo incarico nel Darkshire Town Hall. Ha scoperto la verità dietro il folklore della città.",al={"datore di missione","chi inizia bride of the embalmer"}}},fx={a9aedc81={q="Perché Ser Ello Serranero vuole che la tomba di Eliza venga profanata?",a="Ser Ello Serranero vuole spezzare il potere dell'Imbalsamatore prima che il folle alchimista porti rovina a Borgoscuro. L'Imbalsamatore ha riversato la propria magia oscura e il proprio cuore nella resurrezione della moglie defunta, Eliza. Recuperando il cuore mentre ancora batte, Serranero intende sottrarre al mostro la sua forza soprannaturale e trasformare la magia protettiva residua in un'egida per difendere la città.",al={"perché ser ello vuole che venga fatto","motivo di serranero per bride of the embalmer","perché trovare la tomba di eliza"}},b836fb1b={q="Chi è Eliza e perché è sepolta a Collecorvo?",a="Eliza è la sposa rianimata dell'Imbalsamatore e riposa in una tomba trascurata nel cimitero di Collecorvo. Impazzito dal dolore, suo marito le ha messo il proprio cuore nel cadavere per riportarla in vita. Il rituale è riuscito, ma l'ha maledetta con una fame insaziabile di carne umana viva, costringendolo a tenerla sepolta finché non avesse trovato il modo di sostenerla.",al={"chi è eliza","bersaglio di bride of the embalmer","perché eliza è sepolta"}}},fp="21,196,26.429.0,21.461.1,17.361.2,20.207.0,53.198.0,50.165.0,34.190.0,58.120.1,21.153.0"}
P.entries["quest:254"] = {n="Digging Through the Dirt",s="Nel Cimitero di Collecorvo cerchi il Cuore dell'Imbalsamatore, scomparso. Un cumulo di terra segnato con il nome Eliza potrebbe custodire la risposta, sepolta sotto la terra.",h="Nel Cimitero di Collecorvo cerchi il Cuore dell'Imbalsamatore, scomparso.",kw={"abercrombie","bride of the embalmer","bara","digging through the dirt","boscovespro","eliza","terra della tomba di eliza","cuore dell'imbalsamatore","cimitero di collecorvo"},ang={["class:Paladin"]="Profanare una tomba fresca viola i riti funebri della Sacra Luce. Liberare e distruggere il mostro innaturale al suo interno purifica la tomba.",["class:Priest"]="Artigliare e digrignare i denti sotto la terra consacrata offende il riposo pacifico promesso dalla Luce ai morti di Boscovespro.",["faction:Alliance"]="The Night Watch lotta contro il terrore che si riversa dal Collecorvo. Trovare gli orrori sepolti dall'Imbalsamatore è essenziale per la sicurezza di Borgoscuro."},sec={{t="Una tomba profanata",b="Nel Cimitero di Collecorvo, una zolla di terra smossa porta il nome Eliza. Altre tombe a Boscovespro sono aperte agli sciacalli o ai ghoul selvatici, ma questa terra è stata posata con cura. Scavando sotto lo strato superficiale trovi assi di bara scheggiate. Coprono ciò che l'Imbalsamatore voleva nascondere alla luce del giorno."},{t="Il graffiare dall'interno",b="Eliza giace sotto assi di bara scheggiate, ma non riposa. Il coperchio trema mentre dita artigliate raschiano il legno e mascelle marce battono tra loro. L'esperimento di Abercrombie si agita nella sua bara di pino. Il Cuore dell'Imbalsamatore batte nel suo petto, mentre attende mani imprudenti che aprano la tomba."}},faq={{q="Cosa c'è sepolto nella tomba di Eliza?",a="Sotto la terra giace una bara che custodisce Eliza, una creatura non morta creata dall'Imbalsamatore. Il suo cuore riposa nel petto di lei.",al={"cosa c'è nella tomba","chi è eliza","contenuto tomba di eliza"}},{q="Dove si trova questa tomba?",a="La tomba di Eliza si trova nel Cimitero di Collecorvo, nella parte occidentale di Boscovespro, tra cripte infestate e non morti erranti.",al={"dov'è la tomba di eliza","posizione tomba di eliza","posizione terra della tomba"}},{q="Perché devi scavare nella bara?",a="Scavi nella tomba per affrontare Eliza e recuperare il cuore dell'Imbalsamatore. Così termina la ricerca dei suoi piani nefasti.",al={"perché scavare la tomba","scopo dello scavo","perché aprire la bara"}},{q="Cosa succede quando la bara viene aperta?",a="Quando apri la bara, Eliza si libera. Devi distruggere il ghoul artigliante per recuperare il cuore sigillato al suo interno.",al={"cosa succede dopo","bara aperta","aprire la bara di eliza"}},{q="Chi ha messo Eliza sotto terra?",a="L'Imbalsamatore seppellì Eliza nel Cimitero di Collecorvo, nascondendo la sua creazione e il suo prezioso cuore tra le tombe.",al={"chi ha sepolto eliza","chi l'ha messa lì"}},{q="Eliza è un comune ghoul?",a="Eliza era la moglie dell'Imbalsamatore. La sua magia nera l'ha risvegliata, con il suo cuore nel petto. È più resistente e agisce con maggiore intenzione dei ghoul senza senno che vagano per le strade di Boscovespro.",al={"che tipo di mostro è eliza","eliza è un ghoul"}}},fp="24,137,17.297.0,21.292.1,32.118.1,28.105.0,39.115.1,39.124.1,28.104.1,27.175.1"}
P.entries["quest:2541"] = {n="Il Druido addormentato",s="Nell'Eremo di Ban'ethil, Oben Malartiglio giace addormentato mentre il suo spirito è intrappolato nel Sogno di Smeraldo. Gli sciamani Gnarlpine l'hanno estratto dal suo corpo e hanno messo in movimento la sua carne nell'eremo.",h="Nell'Eremo di Ban'ethil, Oben Malartiglio giace addormentato mentre il suo spirito è intrappolato nel Sogno...",kw={"eremo di ban'ethil","eremo","sogno di smeraldo","gnarlpine","oben malartiglio","talismano sciamanico vudù","teldrassil","il druido dormiente"},ang={["class:Druid"]="Da druido, puoi vedere la sorte di Oben come un incubo a occhi aperti. Subire il furto del proprio corpo mentre si è in comunione con il Sogno di Smeraldo viola l'essenza stessa del sonno druidico.",["race:NightElf"]="Da elfo della notte, sai che la profanazione dell'Eremo di Ban'ethil da parte dei furbolg Gnarlpine mostra quanto si siano allontanati dal loro antico legame con i Kaldorei."},sec={{t="Un Sonno Interrotto",b="I druidi elfi della notte dormono negli eremi di Kalimdor mentre i loro spiriti vagano nel Sogno di Smeraldo. I loro corpi riposano in alcove di pietra per secoli. La corruzione di Teldrassil ha spinto i furbolg Gnarlpine a una ferocia disperata. Nell'Eremo di Ban'ethil, gli sciamani Gnarlpine hanno violato il riposo sacro di Oben Malartiglio e hanno estratto il suo spirito vivente dal corpo addormentato."},{t="Vudù e Corruzione",b="Un Talismano Sciamanico Vudù permette agli sciamani Gnarlpine di animare il corpo vuoto di Oben. Il suo spirito è intrappolato nel Sogno di Smeraldo e guarda la sua carne aggirarsi per i corridoi dell'eremo, attaccando alla cieca chiunque vi entri. Lo spirito di Oben ti chiede di recuperare un talismano Gnarlpine, così potrà studiarlo e cercare un modo per spezzare l'incantesimo e riavere il suo corpo."}},faq={{q="Chi è Oben Malartiglio?",a="Oben Malartiglio è un druido elfo della notte che si è abbandonato a un sonno sacro nell'Eremo di Ban'ethil per entrare in comunione con il Sogno di Smeraldo. I furbolg Gnarlpine ostili hanno preso il controllo del suo corpo, lasciando il suo spirito senza dimora.",al={"oben malartiglio","chi è il druido dormiente","elfo della notte dormiente nell'eremo"}},{q="Perché il corpo di Oben attacca le persone?",a="Gli sciamani Gnarlpine hanno separato lo spirito di Oben dalla sua carne e hanno animato il suo corpo vuoto con la magia oscura. Ora sorveglia le profondità dell'Eremo di Ban'ethil.",al={"perché oben è ostile","perché oben attacca","corpo di oben malartiglio che attacca"}},{q="Cos'è il Talismano Sciamanico Vudù?",a="Il Talismano Sciamanico Vudù è un catalizzatore incantato portato dagli sciamani Gnarlpine nell'Eremo di Ban'ethil. Usano il suo potere oscuro per strappare gli spiriti dei druidi addormentati dai loro corpi e animarne i gusci fisici.",al={"talismano sciamanico","talismano vudù teldrassil","cos'è il talismano sciamanico vudù"}},{q="Dov'è il vero spirito di Oben durante la missione?",a="Lo spirito di Oben è intrappolato nel Sogno di Smeraldo e non può ricongiungersi al suo corpo. Vicino al luogo in cui riposa, riesce a comunicare con il mondo dei svegli come uno spirito scintillante.",al={"dov'è oben","posizione dello spirito di oben","oben sogno di smeraldo"}},{q="Perché i furbolg nell'Eremo di Ban'ethil sono ostili?",a="La corruzione e la follia crescenti di Teldrassil hanno rivoltato la tribù Gnarlpine contro i suoi antichi alleati elfi della notte. I furbolg Gnarlpine hanno profanato i luoghi sacri dei druidi.",al={"perché i gnarlpine sono folli","corruzione furbolg teldrassil","perché i furbolg sono aggressivi"}},{q="Il corpo di Oben può essere salvato senza ucciderlo?",a="Oben spera di studiare il Talismano Sciamanico Vudù e di esaminare gli incantesimi che vincolano la sua carne. Spera di comprendere la magia e trovare un modo per risolvere la crisi.",al={"salvare oben malartiglio","oben può essere salvato","curare oben"}}},fx={["08a1a718"]={q="Perché Oben Malartiglio vuole il talismano?",a="Gli sciamani furbolg Zannaspina sono riusciti a strappare lo spirito di Oben Malartiglio dal suo corpo addormentato. Il suo corpo vagante è stato animato dalla loro magia oscura per attaccare violentemente chiunque entri nell'Eremo di Ban'ethil, mentre la sua vera coscienza resta intrappolata nel Sogno di Smeraldo. Oben vuole un talismano per esaminarne il maleficio e cercare un modo di liberare il suo corpo dalla presa dei furbolg.",al={"motivo di oben malartiglio","perché oben vuole il talismano","perché aiutare oben malartiglio"}},["21a70b6c"]={q="Perché gli sciamani degli Gnarlpine si trovano nell'Eremo di Ban'ethil?",a="La tribù degli Gnarlpine ha invaso il sacro Eremo di Ban'ethil, approfittando della vulnerabilità dei druidi elfi della notte addormentati. I loro sciamani hanno iniziato a praticare vili rituali per separare gli spiriti dei druidi dalla carne, impadronendosi dei corpi fisici e trasformandoli in sentinelle violente a guardia del dominio sotterraneo appena occupato.",al={"perché gli sciamani gnarlpine sono qui","gnarlpine nell'eremo","chi sono gli sciamani gnarlpine"}},["2131a103"]={q="Perché Oben ha bisogno che tu recuperi il talismano?",a="Oben è del tutto incapace di agire da solo. Il suo spirito è separato dal regno dei viventi e intrappolato nel Sogno di Smeraldo, mentre il suo corpo fisico è una marionetta animata controllata dagli sciamani degli Gnarlpine. Privo di forma fisica e di autonomia, dipende interamente da un avventuriero venuto da fuori perché affronti i furbolg e porti il talismano al suo spirito.",al={"perché oben ha bisogno di me","perché oben non può prendere il talismano da solo","perché io nella missione di oben"}}},fp="18,187,19.382.0,21.336.1,21.205.0,36.151.0,32.208.0,45.162.0,53.169.0,44.162.0"}
P.entries["quest:255"] = {n="Mercenaries",s="A Thelsamar, il Magistrato Nasotozzo assolda combattenti di passaggio mentre gli ogre Mo'grosh avanzano nel nord-est del Loch Modan. Forgiardente ha promesso soldati per difendere la valle, ma arriveranno tra mesi. Insediamenti, scavi e la Diga di Pietrasalda restano esposti.",h="A Thelsamar, il Magistrato Nasotozzo assolda combattenti di passaggio mentre gli ogre Mo'grosh avanzano nel...",kw={"loch modan","magistrato nasotozzo","mercenari","mo'grosh","ogre","diga di pietrasalda","thelsamar"},ang={["faction:Alliance"]="Da viaggiatore dell'Alleanza, sai che il Loch Modan è un corridoio vitale tra Khaz Modan e i regni settentrionali. Le incursioni degli ogre che gettano la regione nel caos minacciano le linee di rifornimento dell'Alleanza in tutti i Regni Orientali.",["race:Dwarf"]="Per un nano, la Diga di Pietrasalda è un gioiello dell'ingegneria nanica. Vederla lasciata senza guardia per colpa della burocrazia di Forgiardente rende personale la chiamata alle armi di Nasotozzo, che tu sia un montanaro o un viaggiatore arrivato dalla capitale."},sec={{t="La lentezza di Forgiardente",b="Forgiardente ha impiegato due mesi per promettere una manciata di soldati per la difesa locale del Loch Modan. Ne passeranno altri due prima che arrivino. Le guardie di Thelsamar sono allo stremo mentre forze ostili si radunano oltre la valle. Il Magistrato Nasotozzo non può aspettare i rinforzi."},{t="La minaccia sulle colline",b="Gli ogre Mo'grosh hanno fortificato un accampamento sulle colline a nord-est del Loch. La loro presenza crescente minaccia Thelsamar, il Sito di Scavo Ironband e la Diga di Pietrasalda. Se la diga venisse attaccata o danneggiata, la devastazione a valle sarebbe catastrofica.\n\nSenza distaccamenti ufficiali di montanari, Nasotozzo assolda combattenti indipendenti per assottigliare le fila degli ogre. Spera così di guadagnare tempo per la valle contro ogre e trogg."}},faq={{q="Perché il Magistrato Nasotozzo assume mercenari invece di usare le guardie?",a="Forgiardente ha tardato a rispondere alle richieste d'aiuto del Loch Modan. Sono passati due mesi prima che il Senato approvasse l'invio anche solo di una manciata di soldati per difendere la valle, e ne passeranno altri due prima che arrivino. Con Thelsamar, la diga e i siti di scavo locali minacciati nell'immediato, Nasotozzo assolda combattenti indipendenti.",al={"perché assumere mercenari","guardie di thelsamar","aiuto di forgiardente"}},{q="Dove si trovano gli ogre Mo'grosh?",a="Gli ogre Mo'grosh si trovano alla Roccaforte di Mo'grosh, tra le aspre rupi e colline a nord-est del grande lago del Loch Modan.",al={"posizione degli ogre","dove si trovano i mogrosh","accampamento mogrosh"}},{q="Perché la Diga di Pietrasalda è considerata in pericolo?",a="La Diga di Pietrasalda regola l'intero lago ed è un gioiello architettonico dei nani. È quasi priva di difese militari e un accampamento Mo'grosh si trova nelle vicinanze. Nasotozzo teme che un attacco organizzato possa danneggiare o sabotare la struttura, scatenando inondazioni catastrofiche.",al={"perché proteggere la diga","ogre e la diga"}},{q="Quali altre minacce affronta Thelsamar oltre agli ogre?",a="I trogg sono spuntati in tutta la zona del Loch, provenendo da rovine sotterranee e scavi. Nasotozzo li considera una minaccia enorme, ma la vicina roccaforte degli ogre lo costringe ad assoldare combattenti per respingere i Mo'grosh. Così le guardie locali potranno concentrarsi sulle incursioni dei trogg.",al={"altre minacce al loch modan","minaccia dei trogg"}}},fx={bfea2c9c={q="Perché il Magistrato Nasotozzo vuole che gli ogri Mo'grosh vengano uccisi?",a="Il Magistrato Nasotozzo teme per la sopravvivenza di Thelsamar e della regione circostante. Gli ogri Mo'grosh hanno stabilito un accampamento ben difeso a nord-est del lago, lasciando la città, il sito di scavi locale e la Diga di Pietrasalda esposti a un assalto catastrofico, mentre Forgiardente ritarda l'invio di truppe difensive. Ricacciando indietro gli ogri, spera di eliminare una minaccia imminente e di permettere alla gente del posto di occuparsi delle infestazioni di trogg ormai dilaganti.",al={"motivo del magistrato nasotozzo","perché uccidere gli ogri mogrosh","perché nasotozzo vuole mercenari"}},["5f9f9ec0"]={q="Chi sono gli ogri Mo'grosh che minacciano Loch Modan?",a="I Mo'grosh sono un clan di ogri brutali che si è spinto nel nord-est di Loch Modan, reclamando le aspre colline oltre il lago. I loro sorveglianti e bruti ostentano una forza fisica formidabile proprio accanto ai vulnerabili territori dei nani. La loro crescente presenza costituisce una minaccia immediata per i viaggiatori, la Diga di Pietrasalda e gli insediamenti nanici vicini, approfittando delle difese indebolite della regione.",al={"chi sono i mogrosh","ogri mogrosh a loch modan","chi sono gli ogri mogrosh"}}},fp="11,262,23.274.0,23.420.0,71.330.0,37.118.0,49.268.0,59.258.0"}
P.entries["quest:256"] = {n="WANTED: Chok'sul",s="Nel nord-est di Loch Modan, gli ogre di Chok'sul minacciano gli insediamenti e le opere che sostengono la valle. Il Magistrato Nasotozzo vuole il signore della guerra morto prima che si perdano altre vite.",h="Nel nord-est di Loch Modan, gli ogre di Chok'sul minacciano gli insediamenti e le opere che sostengono la...",kw={"nasotozzo","taglia","chok'sul","choksul","loch modan","ogre","diga di pietrasalda","thelsamar"},ang={["faction:Alliance"]="Come membro dell'Alleanza, dipendi da Loch Modan per l'agricoltura e come via di rifornimento verso Dun Morogh. La sicurezza di Thelsamar è importante per le operazioni militari dell'Alleanza.",["profession:Engineering"]="Come ingegnere, sai che la Diga di Pietrasalda è una delle più grandi opere d'ingegneria civile nanica. È impensabile lasciare che gli ogre la danneggino.",["race:Dwarf"]="Come nano, sai che gli attacchi alla Diga di Pietrasalda e ai vicini scavi archeologici minacciano l'orgoglio e il retaggio del tuo popolo, oltre alla sicurezza delle terre di Forgiardente."},sec={{t="Una minaccia per il Loch",b="Gli ogre ora minacciano il nord-est di Loch Modan, dove trogg e bestie selvagge mettono da tempo alla prova i confini della valle. Hanno creato accampamenti sulle colline impervie e sono passati dal semplice saccheggio. Gli esploratori locali e le autorità cittadine riferiscono che le loro incursioni sono mirate, persistenti e pericolose."},{t="Il prezzo sulla Testa di Chok'sul",b="Il Magistrato Nasotozzo ritiene che Chok'sul diriga gli attacchi contro Thelsamar, un vicino sito di scavi nanico, e la Diga di Pietrasalda. Temendo per la vita dei civili e per la grande opera ingegneristica della valle, offre una taglia per la morte del capo degli ogre, con qualsiasi mezzo. La Testa Mozzata di Chok'sul è richiesta come prova."}},faq={{q="Chi ha posto la taglia su Chok'sul?",a="Il Magistrato Nasotozzo, principale autorità civile di Thelsamar, ha affisso la taglia a nome della città per proteggere la regione dalle incursioni organizzate.",al={"chi vuole morto choksul","chi ha pubblicato la taglia su choksul","poster ricercato thelsamar"}},{q="Perché Chok'sul è considerato un obiettivo ad alta priorità?",a="Si ritiene che Chok'sul diriga gli attacchi degli ogre contro Thelsamar, gli scavi archeologici di Forgiardente e la Diga di Pietrasalda, mettendo a rischio vite naniche e opere fondamentali del regno.",al={"perché uccidere choksul","cosa ha fatto choksul","minaccia choksul"}},{q="Dove si può trovare Chok'sul?",a="Chok'sul si trova in un accampamento di ogre tra le colline impervie, nell'angolo nord-est di Loch Modan.",al={"posizione choksul","dove si trova choksul","accampamento ogre loch modan"}},{q="Quale prova richiede il Magistrato Nasotozzo?",a="Il Magistrato Nasotozzo richiede la Testa Mozzata di Chok'sul come prova per la taglia e per ottenere la gratitudine di Forgiardente. Portagliela direttamente a Thelsamar.",al={"testa di choksul","prova taglia","consegna choksul"}},{q="Perché gli ogre dovrebbero attaccare la Diga di Pietrasalda?",a="La Diga di Pietrasalda trattiene le vaste acque del lago di Loch Modan ed è una grande opera d'ingegneria nanica. Un sabotaggio potrebbe inondare le paludi e devastare le linee di rifornimento naniche, rendendola un bersaglio prezioso per le forze nemiche.",al={"perché attaccare la diga","diga di pietrasalda sotto attacco"}},{q="Ci sono altri ogre che lavorano con Chok'sul?",a="Sì. Chok'sul comanda un accampamento di ogre sulle colline nord-orientali e dirige incursioni in tutto il territorio circostante.",al={"clan di choksul","ogre di loch modan","seguaci di choksul"}}},fx={["761222eb"]={q="Chi è Chok'sul?",a="Chok'sul è un bruto ogro che ha preso il comando dell'accampamento degli ogri nel nord-est di Loch Modan. Ritenuto l'astuto coordinatore delle incursioni contro Thelsamar, la Diga di Pietrasalda e il sito di scavi nanico locale, rappresenta la più grave minaccia organizzata alla sicurezza della valle.",al={"chi è chok'sul","bersaglio chok'sul","informazioni su chok'sul"}}},fp="16,180,20.280.0,28.306.0,34.138.0,55.180.0,28.103.0,45.143.0,44.216.0,44.123.0"}
P.entries["quest:2561"] = {n="Druido dell'Unghia",s="Sotto Teldrassil, lo spirito di Oben Malartiglio attende di essere liberato. I furbolg corrotti di Gnarlpine hanno vincolato il suo corpo con un incantesimo oscuro; puoi liberarlo distruggendo il suo guscio senz'anima.",h="Sotto Teldrassil, lo spirito di Oben Malartiglio attende di essere liberato.",kw={"ban'ethil","druido dell'artiglio","sogno di smeraldo","gnarlpine","oben malartiglio","teldrassil","il druido dormiente","talismano vudù"},ang={["class:Druid"]="Da druido, riconosci il pericolo quando i furbolg corrotti profanano il sonno di un Druido dell'Unghia. Il corpo resta indietro mentre il suo spirito entra in comunione con il Sogno di Smeraldo.",["race:NightElf"]="Da Elfo della Notte, sai che Teldrassil doveva essere il tuo rifugio. La corruzione dei furbolg di Gnarlpine minaccia ormai persino i tumuli sacri."},sec={{t="Uno spirito reciso",b="Oben Malartiglio dormiva nei tumuli sotto Teldrassil. Poi i furbolg corrotti di Gnarlpine hanno lanciato un incantesimo vudù sul suo corpo. La magia ha strappato il suo spirito dalla carne mortale e l'ha intrappolato nel Sogno di Smeraldo. Ora lo spirito di Oben vaga nei paraggi, incapace di riposare o di riprendersi il corpo."},{t="Pietà per la carne",b="Il guscio fisico di Oben Malartiglio è ancora sotto il controllo dei furbolg. Nella camera vicina, distruggi il suo involucro ostile e privo di mente. Poi usa il talismano dei furbolg sui suoi resti per spezzare la magia che tiene vincolata la sua anima."}},faq={{q="Perché devo uccidere Oben Malartiglio?",a="I furbolg di Gnarlpine hanno incantato Oben mentre dormiva e hanno trasformato il suo corpo in un burattino senz'anima. La sua carne è ancora sotto il loro controllo, quindi distruggerla è l'unico modo per spezzare l'incantesimo e liberare il suo spirito.",al={"perché uccidere oben","uccidere druido dormiente","corpo di oben malartiglio"}},{q="A cosa serve il Talismano Vudù?",a="Il talismano spezza l'incantesimo che controlla Oben. Dopo aver distrutto il suo corpo senz'anima, usa il talismano sui suoi resti per dissolvere la magia che trattiene il suo spirito.",al={"uso talismano vudù","come usare talismano vudù","talismano gnarlpine oben"}},{q="Dove va Oben dopo questa missione?",a="Quando il corpo di Oben Malartiglio sarà distrutto e l'incantesimo dissolto, il suo spirito potrà lasciare il mondo mortale e raggiungere il Sogno di Smeraldo per riposare.",al={"destino di oben","cosa succede a oben malartiglio","oben sopravvive"}},{q="Perché i Gnarlpine usano la magia vudù?",a="I furbolg di Gnarlpine sono caduti nella corruzione e nella follia. Hanno abbandonato l'armonia ancestrale per dedicarsi a stregonerie vili e magie oscure, con cui soggiogano le creature vicine e i druidi addormentati.",al={"vudù furbolg","magia vudù gnarlpine","perché i furbolg hanno talismani"}},{q="Chi era Oben Malartiglio?",a="Oben era un Elfo della Notte, un Druido dell'Unghia che si era addormentato nei tumuli di Teldrassil per entrare in comunione con il Sogno di Smeraldo. I furbolg di Gnarlpine hanno interrotto il suo riposo e reso schiavo il suo corpo.",al={"chi è oben","storia di oben","background oben malartiglio"}},{q="Lo spirito di Oben mi parla ancora mentre il suo corpo è vivo?",a="Sì. L'incantesimo ha strappato lo spirito di Oben dalla sua carne. Il suo fantasma è apparso vicino all'ingresso della camera, incapace di controllare o di rientrare nel guscio vuoto e incantato all'interno.",al={"fantasma e corpo di oben","due oben","perché oben è in due posti"}}},fx={bff893ba={q="Chi devo affrontare nell'Eremo di Ban'ethil?",a="Devi distruggere il corpo fisico senz'anima dello stesso Oben Malartiglio. Mentre il suo spirito vaga altrove, il suo involucro mortale addormentato è caduto sotto un potente incantesimo lanciato dai furbolg Gnarlpine all'interno dell'Eremo di Ban'ethil. Privo della sua anima, il guscio è ora al servizio del loro dominio corrotto.",al={"chi devo uccidere","bersaglio oben","corpo senz'anima di oben"}},["6e4ee394"]={q="Perché Oben Malartiglio ha bisogno di me invece di occuparsene da solo?",a="Oben è attualmente uno spirito etereo, del tutto separato dalla sua forma mortale. Intrappolato come apparizione fuori dalla camera del tumulo, non ha consistenza fisica per affrontare il suo guscio incantato né per impugnare il Talismano Vudù necessario a spezzare la magia. Nel profondo dell'eremo, lontano dalla portata delle sentinelle elfe della notte, sei l'unica persona presente in grado di intervenire.",al={"perché oben ha bisogno di me","perché oben non può uccidere il suo corpo","perché io per oben malartiglio"}}},fp="17,189,16.290.0,19.213.1,36.214.0,34.159.0,36.153.1,41.201.0,22.193.0,61.168.0"}
P.entries["quest:257"] = {n="A Hunter's Boast",s="Al Padiglione Lungopasso, Daryl il Giovincello ti assegna una caccia a tempo a Loch Modan: abbatti sei poiane montane entro quindici minuti.",h="Al Padiglione Lungopasso, Daryl il Giovincello ti assegna una caccia a tempo a Loch Modan: abbatti sei poiane...",kw={"a hunter's boast","daryl l'audace","daryl il giovincello","padiglione lungopasso","sfida di caccia","loch modan","poiane montane","missione a tempo"},ang={["class:Hunter"]="Da cacciatore, puoi battere al tiro un novellino pieno di boria sul suo terreno e aggiudicarti un arco o un fucile affidabile.",["faction:Alliance"]="Da membro dell'Alleanza, puoi trovare riparo al Padiglione Lungopasso, un avamposto lungo le strade sudorientali di Loch Modan, e partire per cacce nelle sue aspre vallate.",["race:Dwarf"]="Da nano, conosci i cacciatori esperti del padiglione e puoi rispondere alle vuote vanterie di questo giovane umano con la tua silenziosa abilità."},sec={{t="L'arroganza di un giovane tiratore",b="Daryl si fa chiamare Daryl l'Audace e liquida i viaggiatori come novellini incapaci di eguagliare la sua abilità venatoria. Poi ti indica le poiane montane che rovistano tra le rupi e i pendii vicino al padiglione."},{t="Diradare gli spazzini",b="La caccia mette alla prova la tua velocità, pazienza e mira contro il rapido volo delle poiane. Abbattile tutte e sei prima che scada il tempo, e Daryl cederà di malavoglia una delle sue armi a distanza. Ti proporrà anche altre sfide di caccia."}},faq={{q="Dove si svolge questa sfida di caccia?",a="La sfida comincia al Padiglione Lungopasso, nella parte sudorientale di Loch Modan. Le poiane montane si aggirano tra le rupi vicine e le creste aperte della zona.",al={"luogo missione","dove si trova daryl","dove sono le poiane"}},{q="Chi è Daryl il Giovincello?",a="Daryl il Giovincello è un giovane umano pieno di vanterie che alloggia al Padiglione Lungopasso. Si fa chiamare Daryl l'Audace e provoca i viaggiatori con cacce a tempo per dimostrare la sua immaginaria superiorità.",al={"chi è daryl","storia di daryl l'audace","daryl padiglione lungopasso"}},{q="Perché c'è un limite di tempo per la caccia?",a="Il limite di quindici minuti fa parte della scommessa di Daryl. È convinto che un viaggiatore qualunque non riesca ad abbattere poiane selvatiche sotto pressione.",al={"perché 15 minuti","timer missione","prova a tempo"}},{q="Cosa succede dopo aver superato la sfida di Daryl?",a="Daryl resta sbalordito quando riesci nell'impresa, ma si rifiuta di ammettere la sconfitta. Rispetta la scommessa e ti dà un'arma, poi ti propone un'altra caccia, A Hunter's Challenge, per prede più grosse.",al={"what comes next","seguito boast","serie di caccia"}},{q="Perché cacciare proprio le poiane montane?",a="Le poiane montane si radunano sui pendii rocciosi di Loch Modan. Il loro rapido volo mette alla prova la disciplina sul campo di chi usa arco o fucile.",al={"perché poiane","scopo poiane","poiane loch modan"}},{q="Questa missione è collegata alle altre attività del Padiglione Lungopasso?",a="Le cacce di Daryl aprono una serie più ampia per il padiglione. La serie culmina nella caccia a Ol' Sooty, l'orso che ha sfregiato Daryl, parte del piano di Vyrin Balestra Avventata per vendicarsi di lui.",al={"collegamento con vyrin","storia del padiglione","trama padiglione lungopasso"}}},fx={["4c8cb4f1"]={q="Perché Daryl il Giovincello ti sfida a cacciare gli avvoltoi?",a="Daryl ha un'alta opinione delle proprie capacità e vuole mettersi in mostra. Si fa chiamare «Daryl il Coraggioso», disprezza i viaggiatori che passano dal Padiglione Lungopasso e si aspetta che tu fallisca. Scommette la sua arma da caccia con una sfida impegnativa di quindici minuti, solo per dimostrare che un estraneo non è alla sua altezza.",al={"perché daryl vuole che venga fatto","motivo di daryl","perché la sfida di caccia di daryl"}},["3b45bb0a"]={q="Perché Daryl non caccia gli avvoltoi da solo?",a="Daryl non ti sta chiedendo aiuto né vuole ridurre il numero degli avvoltoi per proteggersi: ti propone una scommessa sportiva piena di vanterie. Ritiene che l'impresa sia al di sotto delle sue capacità e dà per scontato che un avventuriero senza esperienza non riesca ad abbattere sei uccelli in quindici minuti. Così potrà vantarsi quando, inevitabilmente, non ce la farai.",al={"perché io per daryl","perché daryl non caccia gli avvoltoi","perché daryl lo chiede a me"}}},fp="16,134,28.214.0,23.220.0,45.141.0,27.179.0,38.131.0,45.163.1,40.127.0,62.171.1"}
P.entries["quest:258"] = {n="A Hunter's Challenge",s="Al Padiglione Lungopasso, Daryl il Giovincello ti sfida a uccidere cinque cinghiali di montagna anziani entro dodici minuti. Si aspetta che gli aspri altipiani di Loch Modan e la fauna pericolosa ti facciano fallire.",h="Al Padiglione Lungopasso, Daryl il Giovincello ti sfida a uccidere cinque cinghiali di montagna anziani entro...",kw={"cinghiale","valle crestafredda","daryl","cinghiale di montagna anziano","padiglione lungopasso","caccia","loch modan","giovincello"},ang={["class:Hunter"]="Da cacciatore, mettere alla prova la tua abilità con la preda richiede di seguire le tracce di cinque cinghiali di montagna anziani tra il sottobosco degli altipiani e abbatterli entro un limite di tempo rigoroso.",["faction:Alliance"]="In quanto membro dell'Alleanza, puoi considerare il Padiglione Lungopasso una base operativa per i guardaboschi che proteggono il confine orientale di Loch Modan dalle bestie selvagge e dalle minacce degli altipiani.",["race:Dwarf"]="Se sei un nano cresciuto nella Valle Crestafredda, riconoscerai il paragone di Daryl, anche se il suo tono condiscendente potrebbe esserti più difficile da sopportare."},sec={{t="Il vanto di un giovane",b="Daryl il Giovincello vive tra i cacciatori esperti del Padiglione Lungopasso, ma gli manca la loro quieta pazienza. Nasconde la sua giovane età dietro la spavalderia e lunghi racconti di caccia, compresi resoconti sconclusionati su come si sia guadagnato la sua «famosa» cicatrice. Si rifiuta di ammettere che qualcun altro sia abile. Continua anche a sbagliare i nomi dei suoi compagni cacciatori e impone prove severe ai nuovi arrivati, nella speranza di umiliarli e riaffermare la propria posizione tra gli abitanti del padiglione."},{t="La caccia nelle alture",b="I cinghiali di montagna anziani vagano tra le rocce e i pendii di Loch Modan. Sono enormi, hanno la pelle spessa e diventano pericolosi se provocati. Daryl ti dà dodici minuti per trovarne e ucciderne cinque. Se finisci in tempo, il giovane spaccone si ritira impacciato e finge di non ricordare la stravagante scommessa fatta con tanta leggerezza."}},faq={{q="Chi è Daryl il Giovincello?",a="Daryl è un giovane cacciatore umano e borioso del Padiglione Lungopasso, nel sud-est di Loch Modan. Nel disperato tentativo di sembrare formidabile quanto i veterani più anziani che lo circondano, si vanta della propria abilità, inventa storie grandiose e sfida gli avventurieri di passaggio a cacce difficili.",al={"chi è daryl","lore di daryl il giovincello","daryl al padiglione lungopasso"}},{q="Dove si trovano i cinghiali di montagna anziani?",a="I cinghiali di montagna anziani vagano tra le colline pedemontane, i prati e le creste attorno al Padiglione Lungopasso, e in tutto il sud e l'est di Loch Modan. Pascolano sulle alture tra il padiglione e il lago centrale.",al={"posizione cinghiale di montagna anziano","dove trovare i cinghiali","area di caccia al cinghiale"}},{q="Perché questa caccia è a tempo?",a="Daryl ti concede solo dodici minuti perché si aspetta che tu fallisca. La scadenza è stretta e spera che ti metta in imbarazzo e dimostri che i tuoi precedenti successi nella caccia sono stati solo fortuna da principiante.",al={"perché dodici minuti","perché è a tempo","timer sfida del cacciatore"}},{q="Quale scommessa ha fatto Daryl?",a="Daryl scommette la camicia che indossa se uccidi cinque cinghiali di montagna anziani in tempo. Quando torni vittorioso, finge in fretta di non ricordare la scommessa.",al={"scommessa di daryl","la camicia che indossa","cosa ha scommesso daryl"}},{q="Come si confronta questo con i cinghiali di Valle Crestafredda?",a="I cinghiali di montagna anziani di Loch Modan sono più resistenti e aggressivi dei cinghiali più piccoli che i nani alle prime armi cacciano nella Valle Crestafredda. Hanno la pelle più spessa e zanne pericolose, affilate dal granito degli altipiani.",al={"cinghiali di coldridge contro cinghiali di montagna","confronto con coldridge"}},{q="Dove porta in seguito questa catena di missioni di caccia?",a="Dopo aver completato la sfida di Daryl e messo a tacere le sue vanterie, al padiglione l'attenzione si sposta su questioni più serie: uno scontro con il pericoloso orso anziano Ol' Sooty in Vyrin's Revenge.",al={"quale missione segue","dopo a hunter's challenge","serie di missioni di caccia"}}},fx={["4ae04a68"]={q="Che cosa sono i cinghiali montani anziani?",a="I cinghiali montani anziani sono bestie robuste e temprate, originarie delle gole e delle colline che circondano Loch Modan. A differenza dei cinghiali più piccoli che vagano in luoghi come la Valle Crestafredda, queste creature sono molto più resistenti e pericolose da affrontare. Daryl li sceglie apposta per mettere al limite le tue capacità di seguire le tracce e combattere, aspettandosi che tu fallisca entro il tempo stabilito.",al={"cinghiali montani anziani a loch modan","perché i cinghiali anziani","chi sono i cinghiali"}},["33153764"]={q="Perché Daryl ti manda a caccia invece di andarci lui?",a="Daryl il Giovincello preferisce tenere banco al Padiglione Lungopasso, raccontando storie esagerate su come si è procurato la sua famosa cicatrice, invece di tornare a faticare nelle terre selvagge. Convinto della propria superiorità, ti sottopone a prove sempre più difficili solo per umiliarti e conservare il prestigio che si è autoproclamato tra i cacciatori.",al={"perché daryl non caccia","perché daryl ha bisogno di me","perché daryl non va a caccia"}}},fp="20,188,15.446.0,17.327.0,27.255.0,43.198.0,23.188.0,24.165.0,48.217.0,40.191.1"}
P.entries["quest:26"] = {n="A Lesson to Learn",s="A Darnassus, Mathrengyl Domaorsi manda i giovani druidi a Radaluna per apprendere le vie dell’acqua. Qui, un anziano del Circolo Cenariano li guida nei primi passi verso l’Aquatic Form.",h="A Darnassus, Mathrengyl Domaorsi manda i giovani druidi a Radaluna per apprendere le vie dell’acqua.",kw={"a lesson to learn","aquatic form","darnassus","dendrite ardistella","missione druidica","mathrengyl domaorsi","radaluna","nottequieta"},ang={["class:Druid"]="Da druido, raggiungi una tappa importante nel tuo addestramento e apri la via per entrare in comunione con i doni di Cenarius sotto le onde.",["race:NightElf"]="Come kaldorei di Darnassus, onori la tradizione rispondendo alla chiamata del Circolo Cenariano a Radaluna e riallacciando i legami con i tuoi antichi maestri."},sec={{t="Il Richiamo Selvaggio",b="Mathrengyl Domaorsi guida i giovani druidi elfi della notte mentre si esercitano tra le fronde di Darnassus. Quando un iniziato dimostra un saldo legame con la natura ed è pronto ad assumersi maggiori responsabilità, Mathrengyl lo manda a padroneggiare le acque. I doni di Cenarius richiedono concentrazione. Per attraversare le profondità senza annegare, i giovani druidi hanno bisogno della guida degli anziani del Circolo Cenariano."},{t="Viaggio verso Nottequieta",b="Lasci Darnassus per raggiungere Radaluna, un antico santuario sotto il Monte Hyjal. A Nottequieta ti attende Dendrite Ardistella, anziano mentore del Circolo Cenariano. Ardistella giudica se i giovani mutaforma sono pronti per le prove che conducono all’Aquatic Form. Padroneggiare l’acqua richiede resistenza fisica e risolutezza mentale."}},faq={{q="Chi mi invia in questa missione?",a="Mathrengyl Domaorsi, addestratore di druidi nell’Enclave Cenariana di Darnassus, ti manda da lui quando hai progredito abbastanza nell’addestramento druidico iniziale.",al={"datore di missione","chi assegna a lesson to learn","chi inizia questa missione"}},{q="Qual è lo scopo di questa missione?",a="Inizi il cammino verso l’Aquatic Form recandoti a Radaluna per ricevere istruzioni e affrontare le prove dell’anziano Dendrite Ardistella.",al={"perché fare questa missione","introduzione all'aquatic form","cosa ottengo"}},{q="Dove si trova Dendrite Ardistella?",a="Dendrite Ardistella vive a Nottequieta, sulla sponda settentrionale del Lago Elune'ara, a Radaluna.",al={"posizione di dendrite","dov'è dendrite ardistella","trovare dendrite"}},{q="Come fanno i druidi a raggiungere Radaluna per questa missione?",a="Puoi usare Teletrasporto: Radaluna per raggiungere direttamente il boschetto sacro, guidato dalla tua sintonia spirituale.",al={"come arrivare a radaluna","raggiungere nottequieta"}},{q="Cosa succede dopo aver parlato con Dendrite Ardistella?",a="Dopo aver parlato con Dendrite Ardistella, ti manda alla Trial of the Lake. Lì metteranno alla prova la tua resistenza e la tua lucidità sott’acqua.",al={"missione successiva","cosa succede dopo","dopo a lesson to learn"}}},fx={["67389e7a"]={q="Perché Mathrengyl Domaorsi ti manda a Radaluna?",a="Mathrengyl Domaorsi ha seguito i tuoi progressi e crede che tu sia pronto ad approfondire il tuo legame con la natura selvaggia. Gli aspetti animali donati da Cenarius richiedono un insegnamento più approfondito di quello offerto dall'addestramento standard. Per apprendere i segreti della padronanza acquatica, ti manda da Dendrite Ardistella e dal Circolo Cenariano a Nottequieta, dove vengono supervisionate antiche prove druidiche.",al={"perché mathrengyl ti manda","motivo di mathrengyl domaorsi","perché andare a radaluna"}}},fp="17,180,20.365.0,21.318.0,27.137.0,34.126.0,36.94.0,45.108.0,48.147.0"}
P.entries["quest:2605"] = {n="The Thirsty Goblin",s="A Meccania, Marin Granstrippo desidera una bevanda che possa placare la sua sete insaziabile. Ha sentito dire che i raccoglitori di rugiada del giardino di cactus a sud-ovest della città conservano l’acqua in ghiandole speciali e spera che una di esse renda possibile prepararla.",h="A Meccania, Marin Granstrippo desidera una bevanda che possa placare la sua sete insaziabile.",kw={"giardino di cactus","raccoglitore di rugiada","ghiandola della rugiada","meccania","marin granstrippo","tanaris","valle dei cardosecco"},sec={{t="Una ghiandola degna di essere bevuta",b="Marin Granstrippo ha sentito parlare dei raccoglitori di rugiada nel giardino di cactus a sud-ovest di Meccania. Conservano l’acqua in ghiandole speciali, e lui crede che una ghiandola piena possa essere l’inizio di una bevanda capace di placare per sempre la sua sete. Ti chiede di trovare il loro giardino e portargliene una."}},faq={{q="Chi ti manda a caccia della ghiandola della rugiada?",a="Marin Granstrippo, a Meccania, ti chiede di trovare una ghiandola piena di rugiada, sperando che possa guarire la sua terribile sete.",al={"datore di missione goblin assetato","chi avvia goblin assetato","marin granstrippo"}},{q="Dove si trovano i raccoglitori di rugiada?",a="I raccoglitori di rugiada vivono nel giardino di cactus della Valle dei Cardosecco, a sud-ovest di Meccania, a Tanaris.",al={"posizione raccoglitore di rugiada","dove trovare ghiandola della rugiada","posizione giardino di cactus"}},{q="Quale creatura trasporta la ghiandola della rugiada carica?",a="I raccoglitori di rugiada portano le ghiandole, che a quanto si dice conservano l’acqua.",al={"cosa lascia cadere la ghiandola della rugiada carica","mostro raccoglitore di rugiada"}},{q="Cosa succede dopo nella catena?",a="La catena continua con In Good Taste.",al={"seguito goblin assetato","prossima missione dopo goblin assetato"}}},fp="18,232,22.259.0,40.107.0,37.103.0,42.76.0,29.39.0"}
P.entries["quest:2606"] = {n="In Good Taste",s="Marin Granstrippo trova disgustoso da bere il Succo di Cardosecco, ma continua a lavorare alla bevanda. Ti manda da Sprizzy a Meccania con il succo.",h="Marin Granstrippo trova disgustoso da bere il Succo di Cardosecco, ma continua a lavorare alla bevanda.",kw={"meccania","in good taste","marin granstrippo","sprizzy","tanaris","succo di cardosecco"},sec={{t="Un cuoco per una bevanda pessima",b="Marin Granstrippo assaggia il succo e lo trova disgustoso. Eppure continua a lavorare alla bevanda. Ti manda da Sprizzy, sua amica a Meccania e ottima cuoca. Porti il succo e spieghi che la bevanda deve essere più facile da mandare giù. Marin vuole anche che abbia un po' di grinta."}},faq={{q="Dove si colloca questo passaggio nella catena?",a="Segue The Thirsty Goblin, poi viene l'ingrediente segreto di Sprizzy.",al={"quale missione precede questa","cosa segue nella catena","progressione missione"}},{q="Perché Marin Granstrippo vuole che il succo venga portato a Sprizzy?",a="Marin Granstrippo trova disgustoso da bere il succo. Spera che Sprizzy, che considera un'ottima cuoca, riesca a renderlo più facile da mandare giù e a dargli un po' di grinta.",al={"perché sprizzy","cosa vuole marin da sprizzy","chi è sprizzy"}},{q="Dove si trova Sprizzy?",a="Sprizzy è a Meccania, la stessa città in cui si trova Marin Granstrippo.",al={"posizione di sprizzy","dove si trova sprizzy","trovare sprizzy"}}},fp="13,143,21.278.0,38.75.0,59.155.0,28.62.0"}
P.entries["quest:2608"] = {n="The Touch of Zanzil",s="Doc Mixilpixil ti esamina e cerca la causa delle tue condizioni allarmanti. Ti chiede di prelevarti del sangue prima di consultare i suoi colleghi per trovare una cura.",h="Doc Mixilpixil ti esamina e cerca la causa delle tue condizioni allarmanti.",kw={"sangue","cura","doc mixilpixil","dr. montgomery","visita","mr. noarm","il tocco di zanzil","zanzil"},sec={{t="La visita",b="Doc Mixilpixil pensa che tu abbia un aspetto peggiore della morte e dice che gli serve un campione di sangue per aiutarti. Puoi sdraiarti per la visita, anche se dal suo avvertimento sembra che la cura possa fare male. Dopo averti visitato, chiama Dr. Montgomery e Mr. Noarm per consultarsi sul tuo caso."}},faq={{q="Chi mi sta visitando?",a="Doc Mixilpixil ti visita e ti chiede di prelevarti del sangue per cercare la causa delle tue condizioni.",al={"doc mixilpixil","chi è il dottore","mixilpixil"}},{q="Perché Doc Mixilpixil vuole il mio sangue?",a="Doc Mixilpixil dice che gli serve un campione di sangue per trovare la causa e aiutarti.",al={"campione di sangue","perché il sangue","prelievo di sangue"}},{q="Chi sono Dr. Montgomery e Mr. Noarm?",a="Dr. Montgomery e Mr. Noarm sono colleghi di Doc Mixilpixil, che li chiama per consultarsi sul tuo caso.",al={"montgomery e noarm","colleghi del dottore","noarm"}},{q="Cosa succede dopo la visita?",a="Dopo averti visitato, Doc Mixilpixil chiama Dr. Montgomery e Mr. Noarm per consultarsi.",al={"dopo la visita","e adesso","consulto medico"}}},fp="19,143,15.274.0,20.98.0,38.75.0,37.102.0,35.81.0"}
P.entries["quest:2609"] = {n="The Touch of Zanzil",s="Doc Mixilpixil ti chiede di raccogliere delle provviste per l'«ite». Dice che il male non guarirà da solo.",h="Doc Mixilpixil ti chiede di raccogliere delle provviste per l'«ite».",kw={"bronze tube","doc mixilpixil","ite","leaded vial","light chartreuse silk thread","simple wildflowers","zanzil"},sec={{t="La richiesta di un medico",b="Doc Mixilpixil ha bisogno che gli porti Simple Wildflowers, un Leaded Vial, un Bronze Tube e uno Spool of Light Chartreuse Silk Thread. Dice che l'«ite» ha bisogno di una cura e che queste sono le provviste che ti chiede di portargli."}},faq={{q="Chi ti chiede queste provviste?",a="Doc Mixilpixil ti chiede di portargli le provviste.",al={"chi le vuole","richiesta doc mixilpixil"}},{q="Di cosa ha bisogno Doc Mixilpixil?",a="Ha bisogno di Simple Wildflowers, un Leaded Vial, un Bronze Tube e uno Spool of Light Chartreuse Silk Thread.",al={"quali oggetti","elenco provviste"}},{q="Cos'è l'«ite»?",a="Doc Mixilpixil chiama il male «ite».",al={"quale malattia","ite"}}},fp="19,100,18.214.0,33.46.0,30.103.0,19.44.0"}
P.entries["quest:261"] = {n="Down the Scarlet Path",s="Al Presidio di Nijel, Brother Anton ti chiede di dimostrare la tua lealtà alla Crociata Scarlatta.",h="Al Presidio di Nijel, Brother Anton ti chiede di dimostrare la tua lealtà alla Crociata Scarlatta.",kw={"brother anton","desolanda","down the scarlet path","presidio di nijel","crociata scarlatta","flagello","devastatore non morto","valle delle ossa"},sec={{t="Prova di lealtà",b="Brother Anton dice che il Flagello va fermato prima che inghiotta la terra e avvolga il mondo nell'oscurità. La Crociata Scarlatta si è votata a questa lotta. Per dimostrare il tuo coraggio e la tua lealtà, distruggi trenta devastatori non morti nella Valle delle Ossa, a sud di Anton. Se ci riuscirai, la Crociata ti accoglierà."}},faq={{q="Chi ti chiede di distruggere i devastatori non morti?",a="Brother Anton della Crociata Scarlatta ti interpella al Presidio di Nijel.",al={"chi assegna down the scarlet path","missione brother anton","npc crociata scarlatta desolanda"}},{q="Dove si trovano i devastatori non morti?",a="I devastatori non morti si trovano nella Valle delle Ossa, a sud del Presidio di Nijel, in Desolanda.",al={"posizione devastatore non morto","dov'è la valle delle ossa","devastatori a desolanda"}},{q="Perché Brother Anton vuole che i devastatori vengano distrutti?",a="Brother Anton dice che la Crociata combatte il Flagello, che corrompe la gente e infetta la terra. Ti chiede di dimostrare la tua lealtà.",al={"perché uccidere i devastatori non morti","motivo brother anton","ragione crociata scarlatta"}},{q="Quanti devastatori devono essere distrutti?",a="Devi distruggere trenta devastatori non morti.",al={"quanti devastatori","conteggio devastatori"}},{q="Cosa viene prima di questo?",a="Incontri per primo Brother Anton.",al={"missione precedente","prerequisito per down the scarlet path"}}},fp="21,93,19.315.0,44.63.0,36.83.0,51.132.0,36.33.0,23.29.0"}
P.entries["quest:262"] = {n="The Shadowy Figure",s="Vicino alla sua fattoria in rovina, Sven Yorgen cerca lo sconosciuto che guardò morire la sua famiglia. Ti consegna uno strano libro trovato tra le macerie e ti chiede di scoprire chi l’ha lasciato lì.",h="Vicino alla sua fattoria in rovina, Sven Yorgen cerca lo sconosciuto che guardò morire la sua famiglia.",kw={"libro","borgoscuro","boscovespro","dama eva","the shadowy figure","sven yorgen","sven's camp"},ang={["class:Priest"]="Da sacerdote, vedi come la chiaroveggenza spirituale, Shadow Magic e le impressioni che persistono sugli oggetti comuni possano entrare in contatto.",["faction:Alliance"]="Borgoscuro riceve poco sostegno da Roccavento. I suoi uomini di frontiera traumatizzati e i veggenti del posto si affidano ai campioni erranti dell’Alleanza per indagare sulle atrocità mortali di Boscovespro."},sec={{t="Echi di un massacro",b="Sulle colline occidentali di Boscovespro, Sven Yorgen piange ancora la sua famiglia sterminata. In passato incolpava i cavalieri neri che terrorizzano i boschi. Eppure ricorda una figura misteriosa nei paraggi la notte del massacro. Sven ti consegna lo strano libro trovato nella fattoria saccheggiata, l’unico indizio materiale tra le macerie."},{t="In cerca di divinazione in città",b="Senza una pista chiara nella pericolosa natura selvaggia, ti dirigi a est, verso Borgoscuro. Sven spera che uno degli abitanti superstiziosi riconosca il curioso libro. Tra loro c’è Dama Eva, i cui sensi occulti vanno oltre la vista comune. Le sue divinazioni potrebbero rivelare le impressioni lasciate sulle reliquie misteriose."},{t="Trame straniere",b="Dama Eva legge deboli impressioni nel libro. Il recente desiderio di vendetta di Sven ne ha segnato le pagine. Sotto quel segno si cela un’altra presenza. Eva percepisce che il primo proprietario veniva da oltre Borgoscuro e Boscovespro, e che aveva visitato la fattoria prima che iniziasse il massacro."}},faq={{q="Chi è Sven Yorgen?",a="Sven Yorgen è un contadino devastato che vive in esilio sulle colline occidentali di Boscovespro. Dopo che i cavalieri neri hanno sterminato la sua famiglia nella fattoria, il dolore lo ha spinto nella natura selvaggia. Lì cerca vendetta contro i responsabili.",al={"chi è sven","retroscena sven","sven yorgen"}},{q="Cos'è il libro trovato alla fattoria di Sven?",a="Il libro è un reperto materiale recuperato dalla terra e dalle macerie della fattoria distrutta di Sven. Un osservatore sfuggente lo ha lasciato lì dopo essersi aggirato nell’ombra durante l’attacco alla famiglia di Sven.",al={"che libro è questo","libro dalla fattoria di sven","libro misterioso"}},{q="Perché portare il libro a Dama Eva?",a="Dama Eva è la veggente e chiromante di Borgoscuro. Gli abitanti comuni possono ricavare poco da un volume senza segni, ma la sua chiaroveggenza le permette di leggere le impressioni lasciate da chi lo possedeva o lo portava in precedenza.",al={"perché dama eva","chi legge il libro","mistico di borgoscuro"}},{q="Cosa impara Dama Eva dal libro?",a="Dama Eva percepisce che il recente contatto di Sven con il libro vi ha lasciato una potente impronta di vendetta. Sotto di essa, rileva deboli tracce che mostrano come il primo proprietario venisse da oltre Borgoscuro.",al={"cosa dice eva","identità del proprietario del libro","risultato della divinazione"}},{q="Dove porta questa indagine ora?",a="Dama Eva scopre che il proprietario del libro veniva da oltre Borgoscuro. Ti manda a cercare nei registri della città e nei luoghi frequentati da tutti chi ricorda un viaggiatore sconosciuto come quella figura.",al={"cosa fare dopo","prossima missione dopo il libro","chi è the shadowy figure"}}},fx={d371091b={q="Perché Sven Yorgen vuole che venga fatto?",a="Sven è consumato dal dolore e da un disperato bisogno di risposte. La notte in cui la sua famiglia fu massacrata nella fattoria, vide una figura misteriosa aggirarsi nell'ombra. Crede che scoprire l'identità di quella figura furtiva sia la sua unica possibilità di conoscere la verità sul massacro e ottenere giustizia.",al={"perché sven vuole trovare la figura misteriosa","motivo di sven yorgen","perché trovare il proprietario del libro"}},["35559963"]={q="Perché Sven Yorgen si rivolge a te invece che alla The Night Watch?",a="Sven è un eremita isolato e traumatizzato, nascosto nelle terre selvagge di Boscovespro, lontano da Borgoscuro. Hai già dimostrato la tua intraprendenza trovando il diario distrutto nella sua fattoria devastata, convincendolo che possiedi la tenacia e l'astuzia necessarie per svelare il mistero quando nessun altro è disposto a farlo.",al={"perché sven non chiede alla the night watch","perché sven ha bisogno del mio aiuto","perché io per sven yorgen"}}},fp="18,172,21.313.0,26.302.0,15.275.1,19.232.0,38.201.0,32.213.0,41.191.1,40.199.1"}
P.entries["quest:2622"] = {n="The Missing Orders",s="Il Comandante delle Comunicazioni Ruag ti manda a cercare Bengor dopo la scomparsa degli ordini.",h="Il Comandante delle Comunicazioni Ruag ti manda a cercare Bengor dopo la scomparsa degli ordini.",kw={"imboscata","bengor","comandante delle comunicazioni ruag","ordini mancanti","murloc","palude del dolore"},sec={{t="Il resoconto di Ruag",b="Il Comandante delle Comunicazioni Ruag si irrigidisce quando gli chiedi degli ordini scomparsi. Dice che erano con i soldati mandati a trasportarli. I murloc hanno teso un'imboscata ai soldati e li hanno picchiati brutalmente, e solo uno è sopravvissuto. Bengor riesce a malapena a parlare, non può camminare e viene nutrito con un sondino. Ruag ti manda a cercarlo lì vicino, poi ti avverte di badare a dove metti il naso."},{t="Le parole spezzate di Bengor",b="Bengor riesce a pronunciare solo frammenti di parole sconnesse. Tra queste, cogli le parole parlatore della palude."}},faq={{q="Chi ha inviato gli ordini che sono scomparsi?",a="Il Comandante delle Comunicazioni Ruag dice che gli ordini erano con i soldati mandati in missione. Quando gli chiedi che ne è stato di loro, si mette sulla difensiva.",al={"chi ha dato gli ordini mancanti","chi ha perso gli ordini"}},{q="Cosa è successo ai soldati che trasportavano gli ordini?",a="Il Comandante delle Comunicazioni Ruag dice che i murloc hanno teso un'imboscata ai soldati che trasportavano gli ordini e li hanno picchiati brutalmente. Solo uno è sopravvissuto.",al={"cosa è successo ai corrieri","come sono andati persi gli ordini"}},{q="Chi è Bengor?",a="Bengor è l'unico sopravvissuto all'imboscata. Riesce a malapena a parlare, non può camminare e viene nutrito con un sondino.",al={"chi è il sopravvissuto","lore di bengor"}},{q="Dove si può trovare Bengor?",a="Il Comandante delle Comunicazioni Ruag dice che Bengor si trova da qualche parte qui vicino.",al={"posizione di bengor","dove si trova bengor"}}},fp="18,77,14.352.0,22.93.1,38.125.0,50.116.0,14.103.0,26.56.0"}
P.entries["quest:2623"] = {n="The Swamp Talker",s="Gli ordini diretti alle Terre Devastate spariscono durante un'imboscata dei murloc. Bengor ti racconta cos'è successo prima di perdere i sensi.",h="Gli ordini diretti alle Terre Devastate spariscono durante un'imboscata dei murloc.",kw={"bengor","terre devastate","eroe dell'orda caduto","murloc","palude del dolore","the swamp talker","ordini del capoguerra"},sec={{t="Resoconto frammentario di Bengor",b="Bengor dice che il comandante di dispaccio ha consegnato gli ordini. Il suo gruppo era diretto alle Terre Devastate quando molti murloc li assalirono. Uno di loro, The Swamp Talker, strappò gli ordini a Bengor mentre una lancia gli colpiva il cranio. Prima di perdere i sensi, Bengor parla di una caverna a est. Recupera gli ordini e portali all'Eroe dell'Orda Caduto."},{t="La resa dei conti dell'Eroe Caduto",b="L'Eroe dell'Orda Caduto trova la situazione peggiore di quanto immaginasse. Diciannove dei suoi uomini avrebbero potuto essere risparmiati dall'agonia se l'Eroe non avesse agito in modo così irrazionale. Impotente e incapace di aiutarli, l'Eroe ti chiede di soccorrere quegli uomini."}},faq={{q="Chi ha rubato gli Ordini del Capoguerra?",a="Durante l'imboscata, un murloc chiamato The Swamp Talker strappò gli ordini dalle mani di Bengor.",al={"chi ha preso gli ordini","chi è the swamp talker","chi ha rubato gli ordini"}},{q="Dove è andato The Swamp Talker?",a="Mentre Bengor perde i sensi, parla di una caverna a est.",al={"dove si trova the swamp talker","posizione di the swamp talker","dove si trova la caverna dei murloc"}},{q="Dove erano diretti Bengor e la sua unità?",a="Bengor e la sua unità portavano gli ordini del comandante di dispaccio alle Terre Devastate quando i murloc li tesero un'imboscata.",al={"destinazione di bengor","dove stava andando bengor","obiettivo dell'unità di bengor"}},{q="A chi devono essere restituiti gli ordini?",a="Porta gli ordini all'Eroe dell'Orda Caduto.",al={"chi riceve gli ordini del capoguerra","dove consegno gli ordini","consegna missione the swamp talker"}}},fp="16,123,23.342.0,27.223.1,32.83.0,30.49.0,39.117.0,38.48.0"}
P.entries["quest:263"] = {n="In Defense of the King's Lands",s="Alla Southern Guard Tower, il Montanaro Muroforte chiama i viaggiatori a difendere Loch Modan dai trogg Pietrarotta. Con le riserve di Forgiardente inviate su fronti lontani, il passo meridionale è presidiato da poche guardie. Muroforte manda reclute esperte nella Valle Pietrarotta contro gli sciamani e gli sfasciaossa del clan.",h="Alla Southern Guard Tower, il Montanaro Muroforte chiama i viaggiatori a difendere Loch Modan dai trogg...",kw={"sfasciaossa","forgiardente","loch modan","magni","montanaro","sciamano","pietrarotta","trogg","muroforte"},ang={["class:Shaman"]="Da sciamano, affrontare gli incantatori trogg Pietrarotta ti mostra una rozza magia della terra, plasmata da istinti selvaggi.",["faction:Alliance"]="Da viaggiatore dell'Alleanza, aiutare la Southern Guard Tower protegge le vitali rotte commerciali e di viaggio che collegano Dun Morogh alle Eastern Wetlands e a Roccavento.",["race:Dwarf"]="Da nano, rispondere alla chiamata di Muroforte significa difendere le fattorie di Loch Modan mentre gli eserciti regolari della tua gente vengono mandati all'estero."},sec={{t="Una sottile linea nanica",b="Le difese di Loch Modan sono tese al limite. Le riserve regolari di Forgiardente sono state richiamate su fronti lontani in tutta Azeroth, lasciando la Southern Guard Tower a corto di personale. Il Montanaro Muroforte e i suoi pochi compagni affrontano la pressione costante del clan Pietrarotta. Per tenere il passo meridionale, dipendono dai viaggiatori dell'Alleanza di passaggio."},{t="Prendere di mira l'avanguardia Pietrarotta",b="La lotta va oltre le vedette isolate e colpisce la forza del clan Pietrarotta. I suoi sfasciaossa ricorrono alla forza bruta, mentre gli sciamani usano la magia della terra per radunare i loro simili. Uccidere venti di questi nemici indebolisce le incursioni del clan nelle pianure. È anche un modo per servire la difesa del regno di Re Magni Barbabronzea."}},faq={{q="Chi è il Montanaro Muroforte?",a="Il Montanaro Muroforte è un nano di Forgiardente di stanza alla Southern Guard Tower, a Loch Modan. Sorveglia i trogg che scendono dalle montagne e coordina la milizia per mantenere sicura la principale strada meridionale.",al={"muroforte","chi è muroforte","storia del montanaro muroforte"}},{q="Perché i Montanari chiedono aiuto ai viaggiatori?",a="Le riserve militari di Forgiardente sono state richiamate sui fronti di battaglia del regno e oltre. Gli avamposti di confine, come le torri di guardia meridionali di Loch Modan, sono a corto di personale e faticano a fronteggiare le minacce locali.",al={"perché i nani hanno bisogno di aiuto","dove sono le guardie di forgiardente","perché non ci sono riserve"}},{q="Dove si trovano questi trogg?",a="I trogg Pietrarotta si radunano nella Valle Pietrarotta, tra le aspre colline a sudovest del Loch. Piccoli gruppi di sciamani e sfasciaossa infestano anche le isole settentrionali del lago.",al={"dove sono i trogg pietrarotta","posizione sciamano pietrarotta","dove si trova la valle pietrarotta"}},{q="Cosa rende il clan Pietrarotta una minaccia?",a="I trogg si moltiplicano rapidamente e possono invadere terre abitate in sciami sotterranei. Gli sciamani Pietrarotta padroneggiano una rozza magia elementale, mentre gli sfasciaossa attaccano gli esploratori nani. Gli insediamenti vicini e le rotte commerciali sono a rischio.",al={"perché i trogg sono pericolosi","minaccia pietrarotta"}},{q="Cosa fa il Montanaro Muroforte dopo questo compito?",a="Muroforte è soddisfatto che tu abbia dimostrato di saper combattere al servizio di Re Magni. Ti manda a riferire al Capitano Granchiasso per ricevere altri ordini sulla difesa di Loch Modan.",al={"cosa succede dopo muroforte","chi è il capitano"}},{q="Chi governa Forgiardente durante questa crisi?",a="Re Magni Barbabronzea governa il regno dei nani dall'High Seat di Forgiardente. Si opera per proteggere Loch Modan in suo nome e difendere le sue terre.",al={"chi è il re dei nani","re di forgiardente"}}},fx={["20cd043f"]={q="Perché il Montanaro Muroforte vuole che questi trogg vengano uccisi?",a="Il problema dei trogg in tutta Loch Modan continua a peggiorare e minaccia la sicurezza del territorio sovrano di Forgiardente. Con le riserve dei Montanari richiamate su fronti lontani, Muroforte e i suoi compagni alla torre di guardia meridionale sono isolati e senza rinforzi. Ha bisogno di decimare le schiere dei trogg per proteggere la valle e tenere la linea in nome del Re.",al={"perché uccidere i trogg stonesplinter","motivo di muroforte","perché muroforte vuole morti i trogg"}},c0ccff20={q="Chi sono gli sciamani e gli Spezzaossa Stonesplinter?",a="Sono le avanguardie specializzate del clan di trogg Stonesplinter, che avanza su Loch Modan. Gli Spezzaossa sono i brutali picchiatori del clan, mentre gli sciamani incanalano magie grezze e primordiali. Insieme costituiscono il nucleo della forza che spinge i trogg fuori dalle profondità e nelle terre dei nani.",al={"sciamano stonesplinter","spezzaossa stonesplinter","chi sono i bersagli trogg"}}},fp="30,305,19.346.0,36.308.0,28.214.0,51.201.0,31.186.0,43.218.0,50.174.0,39.159.0"}
P.entries["quest:264"] = {n="Finché morte non ci separi",s="Nella Selva Pinargento, Clarice Foster manda il suo ricordo alla tomba di Yuriv. Dalle Pozze delle Visioni sotto Picco del Tuono, la Reietta ti chiede di deporlo sulla tomba del marito che abbandonò lei e i loro figli.",h="Nella Selva Pinargento, Clarice Foster manda il suo ricordo alla tomba di Yuriv.",kw={"clarice foster","crociata","reietti","pendente","mausolea","selva pinargento","tomba","yuriv"},ang={["class:Priest"]="Da sacerdote, puoi vedere come la devozione alla Luce possa dividere le famiglie e lasciare un'amarezza duratura in chi resta.",["faction:Horde"]="Come membro dell'Orda, intravedi le tragedie personali e il rancore duraturo che legano i Reietti nella Selva Pinargento.",["race:Undead"]="Come Reietto, puoi vedere la sorte di Clarice come un esempio dell'ipocrisia dei vivi. I guerrieri sacri lasciarono le loro famiglie a morire nel fervore religioso, mentre i sopravvissuti trasformati portano il peso dei ricordi."},sec={{t="Un amaro ricordo",b="Clarice Foster ricorda con amarezza il suo matrimonio da mortale. Mentre Lordaeron crollava, Yuriv lasciò lei e i loro figli per unirsi a una crociata contro i non morti che avanzavano. Dichiarò che servire la Sacra Luce veniva prima di tutto. La sua devozione non salvò né la sua famiglia né lui. Clarice fu riportata in vita come non morta, mentre Yuriv giace sotto una pietra deturpata. Vuole liberarsi dell'ultimo ricordo tangibile delle sue promesse infrante."},{t="La tomba trascurata",b="La tomba di Yuriv si trova nel cimitero attorno al Mausolea, segnata da fenditure, rifiuti ed erbacce. Posa il Pendente di Clarice sul rilievo delle mani scolpite. Non seguono grandi magie né una pace spirituale. La gemma si opacizza e una folata fredda e silenziosa passa sulle tombe. Gli antichi rancori del popolo caduto di Lordaeron restano."}},faq={{q="Chi era Yuriv?",a="Yuriv era il marito mortale di Clarice Foster. La lasciò con i loro figli per combattere il Flagello in nome della Sacra Luce, anteponendo la sua crociata alla famiglia.",al={"chi è yuriv","storia di yuriv","marito di clarice"}},{q="Perché Clarice odia così tanto il suo defunto marito?",a="Clarice attese notte dopo notte mentre Yuriv anteponeva i suoi doveri religiosi. La sua crociata non riuscì a proteggerli. Morì in una tomba trascurata, e lei fu riportata in vita come una delle creature non morte che lui combatteva.",al={"perché clarice è arrabbiata","storia di clarice foster"}},{q="Cosa succede quando restituisci il pendente?",a="Quando il pendente poggia sulle mani di pietra scolpite nella tomba di Yuriv, la gemma si opacizza. Una brezza fredda e pungente spazza il Mausolea, dove la tomba deturpata giace in silenzio.",al={"pendente sulla tomba","finale di finché morte non ci separi"}},{q="Dov'è situata la tomba di Yuriv?",a="La tomba di Yuriv si trova nel cimitero del Mausolea, una roccaforte dei Reietti nella Selva Pinargento settentrionale.",al={"dov'è la tomba di yuriv","posizione tomba di yuriv"}},{q="Perché la tomba di Yuriv è così danneggiata?",a="La tomba è segnata da fenditure, cosparsa di rifiuti e invasa dalle erbacce. I Reietti del Mausolea non provano simpatia né riverenza per un crociato morto combattendo la loro gente.",al={"perché la tomba è deturpata","tomba abusata"}},{q="I figli di Clarice sono sopravvissuti?",a="Clarice dice che Yuriv abbandonò anche i loro figli, ma non rivela che fine fecero. Con Lordaeron devastata, potrebbero aver avuto una fine tragica.",al={"cosa è successo ai figli","figli di clarice"}}},fp="22,220,17.409.0,19.328.0,14.166.0,47.191.0,41.178.1,30.104.0,32.174.0,31.149.0"}
P.entries["quest:2641"] = {n="Sprinkle's Secret Ingredient",s="A Meccania, Sprizzy sa come rendere bevibile la disgustosa bevanda di Marin Granstrippo con un'Amanita Viola. Il fungo cresce sott'acqua in un piccolo lago nelle Entroterre.",h="A Meccania, Sprizzy sa come rendere bevibile la disgustosa bevanda di Marin Granstrippo con un'Amanita Viola.",kw={"meccania","entroterre","fungo","granstrippo","sprizzy","tanaris","amanita viola"},sec={{t="Il segreto di un cuoco",b="Da bambina, la sorella di Sprizzy si occupava di tutta la cucina e il cibo era difficile da mandare giù. Sprizzy trovò un fungo chiamato Amanita Viola e ne fece il suo ingrediente segreto. Dice che rendeva delizioso ogni piatto. Ora lo userà per rendere bevibile l'orribile bevanda di Marin."},{t="Sotto l'acqua",b="L'Amanita Viola cresce sott'acqua in un piccolo lago nelle Entroterre. Il Lago di Ardivento si trova appena a sud della strada che attraversa la zona. Immergiti per raccogliere il fungo, poi torna da Sprizzy a Meccania."}},faq={{q="Chi è Sprizzy?",a="Sprizzy è una cuoca di Meccania e un'amica di Marin Granstrippo. Marin ti ha mandato da lei con una bevanda dal sapore disgustoso.",al={"chi è sprizzy","sprizzy meccania","chi assegna la missione ingrediente segreto di sprizzy"}},{q="Cos'è l'Amanita Viola?",a="L'Amanita Viola è un fungo che Sprizzy trovò da bambina e che chiama il suo ingrediente segreto. Dice che rende tutto delizioso.",al={"amanita viola","cos'è l'amanita viola","fungo ingrediente segreto"}},{q="Dove si può trovare l'Amanita Viola?",a="L'Amanita Viola cresce sott'acqua in un piccolo lago nelle Entroterre. Il Lago di Ardivento si trova appena a sud della strada che attraversa la zona.",al={"dove si trova l'amanita viola","dove trovare l'ingrediente segreto","posizione amanita viola"}},{q="Come si collega a Marin Granstrippo?",a="La bevanda di Marin aveva un sapore terribile, così Sprizzy vuole usare l'Amanita Viola per renderla bevibile.",al={"perché sprizzy ne ha bisogno","collegamento marin granstrippo","serie di missioni granstrippo"}}},fp="28,172,15.274.0,15.223.0,16.114.0,26.130.0,37.130.0,44.87.0"}
P.entries["quest:265"] = {n="The Shadowy Search Continues",s="A Boscovespro, segui le tracce del diario da Dama Eva al Cancelliere Daltry a Borgoscuro. Proviene dalle rovine della fattoria saccheggiata di Sven Yorgen.",h="A Boscovespro, segui le tracce del diario da Dama Eva al Cancelliere Daltry a Borgoscuro.",kw={"libro","cancelliere daltry","borgoscuro","boscovespro","diario","dama eva","shadowy figure","sven yorgen"},ang={["class:Rogue"]="Da ladro, sai che i registri degli acquisti e la memoria di un mercante possono aiutarti a seguire per la città le tracce di un bersaglio nervoso.",["faction:Alliance"]="Per l’Alleanza, scoprire chi ha rifornito e aiutato i negromanti a Boscovespro è importante per la sicurezza di Borgoscuro e per rendere giustizia ai coloni di frontiera massacrati."},sec={{t="Tracciare The Binding",b="Dama Eva ha scoperto che l’autore del diario era un forestiero, anche se la sua rilegatura proveniva da Borgoscuro. Il Cancelliere Daltry vende registri e tomi vuoti a studiosi, incantatori e archivisti di passaggio. Segui così le vendite locali, in cerca di indizi sul sinistro intruso nei boschi di Boscovespro."},{t="Un acquirente nervoso",b="Il Cancelliere Daltry ricorda la vendita, anche se molti documenti passano dal Municipio di Borgoscuro. Circa un mese fa, un viaggiatore nervoso comprò il libro vuoto senza dare il proprio nome. L’acquirente furtivo continuava a guardarsi alle spalle, lasciando un’impressione netta sul cancelliere. The Shadowy Figure di Sven aveva camminato apertamente tra i cittadini di Borgoscuro."}},faq={{q="Da dove proviene il libro misterioso?",a="Dama Eva dice che l’autore era un forestiero, ma il libro fu comprato a Borgoscuro. Il Cancelliere Daltry vende libri vuoti e potrebbe ricordare chi lo acquistò.",al={"origine del libro","chi ha venduto il libro","fonte del libro"}},{q="Perché Dama Eva ti manda dal Cancelliere Daltry?",a="Dama Eva ha scoperto che la rilegatura e i materiali del libro provenivano da un acquisto locale. Il Cancelliere Daltry vende registri e diari vuoti agli abitanti del posto e agli studiosi di passaggio.",al={"perché daltry","connessione eva daltry","chi ha fatto il libro"}},{q="Cosa ricorda il Cancelliere Daltry dell'acquirente?",a="Daltry ricorda un viaggiatore nervoso e senza nome che comprò il libro vuoto circa un mese fa.",al={"chi ha comprato il libro","descrizione dell'acquirente","aspetto della shadowy figure"}},{q="Come si collega questo alla fattoria di Sven?",a="Il libro fu recuperato dalla fattoria distrutta di Sven Yorgen, nel sud di Boscovespro. Fu lasciato lì dopo che un’incursione omicida sterminò la sua famiglia.",al={"connessione con sven","perché stiamo cercando","sven yorgen"}},{q="Dove porta l'indagine ora?",a="La ricerca prosegue alla Taverna del Corvo Scarlatto di Borgoscuro. Qualcuno potrebbe sapere dove alloggiò lo straniero nervoso o con chi parlò.",al={"cosa fare dopo","dopo daltry","prossimo indizio"}},{q="Il Cancelliere Daltry è in pericolo?",a="Daltry sta aiutando a identificare un acquirente tra i suoi normali clienti. Nulla nello scambio fa pensare che sia minacciato personalmente.",al={"pericolo per il cancelliere daltry","daltry è al sicuro"}}},fx={["9bf6b406"]={q="Perché Dama Eva aiuta nelle ricerche?",a="Dama Eva è la veggente e consigliera di Borgoscuro e sorveglia i presagi oscuri che affliggono Boscovespro. Quando le hai portato il libro macchiato di terra trovato nella fattoria in rovina di Sven, ha percepito che qualcuno spinto dalla vendetta lo aveva maneggiato di recente, mentre le deboli tracce del proprietario originario indicavano che era uno straniero a Borgoscuro. Ha anche capito che il libro era stato acquistato in città, perciò ti manda a interrogare gli abitanti, nella speranza che possano collegarlo al suo proprietario.",al={"perché dama eva aiuta","motivo di dama eva","perché dama eva si interessa al libro"}}},fp="28,143,19.295.0,15.332.1,40.144.0,45.164.0,48.90.0,37.143.0,39.139.1,26.126.0"}
P.entries["quest:266"] = {n="Inquire at the Inn",s="Il Cancelliere Daltry ti manda da Borgoscuro alla Taverna del Corvo Scarlatto con un diario della fattoria in rovina di Sven Yorgen. Spera che qualcuno sappia chi ne fosse il proprietario.",h="Il Cancelliere Daltry ti manda da Borgoscuro alla Taverna del Corvo Scarlatto con un diario della fattoria in...",kw={"cancelliere daltry","borgoscuro","boscovespro","inquire at the inn","collecorvo","corvo scarlatto","figura misteriosa","sven yorgen","taverniere smitts"},ang={["class:Rogue"]="Da ladro, puoi seguire le tracce di un fuggitivo, dai discorsi in taverna alle rovine desolate, indagando con attenzione.",["faction:Alliance"]="Da avventuriero dell'Alleanza, contribuisci a proteggere Borgoscuro, un isolato insediamento di frontiera nel sud dei Regni Orientali, indagando sulle minacce che si annidano tra le sue mura."},sec={{t="Una traccia al Corvo Scarlatto",b="Il Cancelliere Daltry ha finito di esaminare il libro logoro della fattoria di Sven Yorgen. Crede che ogni forestiero giunto a Borgoscuro sia passato dalla sua taverna. La Taverna del Corvo Scarlatto si trova dall'altra parte della città ed è l'unico luogo di ritrovo e alloggio di Borgoscuro. Lì puoi scoprire chi è passato e dove è andato."},{t="L'ospite paranoico",b="Il Taverniere Smitts riconosce il diario quando glielo mostri. Il proprietario ha affittato una stanza per diversi giorni e trascorreva le serate a scarabocchiare al bancone. Poi l'ospite è fuggito da Borgoscuro terrorizzato, convinto che un inseguitore invisibile gli stesse dando la caccia. Lo sconosciuto ha preso la strada verso ovest, in direzione di Collecorvo."}},faq={{q="Chi ti manda alla locanda?",a="Il Cancelliere Daltry, custode dei registri cittadini di Borgoscuro, ti manda alla Taverna del Corvo Scarlatto dopo aver esaminato il diario. Spera che qualcuno riconosca il proprietario.",al={"chi assegna questa missione","datore di missione","dove inizia inquire at the inn"}},{q="Che libro stai portando?",a="Il diario logoro proviene dalla fattoria in rovina di Sven Yorgen, nel sud di Boscovespro. Si ritiene che appartenesse alla figura ombrosa vista aggirarsi nei dintorni.",al={"cos'è il libro","libro della fattoria di sven","diario"}},{q="Chi gestisce la Taverna del Corvo Scarlatto?",a="Il Taverniere Smitts gestisce la Taverna del Corvo Scarlatto. Serve da bere e affitta stanze ai viaggiatori che si avventurano a Boscovespro.",al={"chi è il taverniere","locandiere borgoscuro","chi è smitts"}},{q="Cosa rivela il Taverniere Smitts riguardo all'ospite?",a="Il proprietario del diario ha affittato una stanza per diversi giorni e trascorreva le serate a scrivere al bancone. Poi è fuggito da Borgoscuro terrorizzato, convinto che un inseguitore invisibile gli stesse dando la caccia.",al={"cosa ha detto smitts","cosa è successo alla figura misteriosa","cosa sa il locandiere"}},{q="Dove è fuggita la figura misteriosa?",a="Lo sconosciuto è fuggito da Borgoscuro verso ovest, lungo la strada in direzione di Collecorvo.",al={"dove è andato","dove si trova la figura misteriosa","dove andare dopo"}},{q="Quale missione segue Inquire at the Inn?",a="Il Taverniere Smitts ti indica la strada verso ovest, per seguire le tracce dello sconosciuto in Finding the Shadowy Figure.",al={"prossima missione","cosa viene dopo inquire at the inn","missione successiva"}}},fx={["5b964541"]={q="Perché il Cancelliere Daltry vuole che tu faccia domande alla locanda?",a="Il Cancelliere Daltry tiene i registri cittadini di Borgoscuro, ma i suoi registri non possono rendere conto degli enigmatici viandanti che scivolano nell'ombra. Sapendo che stai seguendo le tracce della figura sfuggente legata ai tragici eventi della fattoria di Sven, ti indica la Taverna del Corvo Scarlatto. In una città guardinga come Borgoscuro, qualsiasi straniero che si fosse fermato per bere o pernottare avrebbe attirato l'attenzione dell'oste.",al={"perché daltry ti manda alla locanda","motivo di daltry per la locanda","perché chiedere alla taverna del corvo scarlatto"}}},fp="18,155,27.320.0,18.289.1,25.161.0,34.148.0,34.121.0,51.172.0,34.71.0,38.95.0"}
P.entries["quest:2661"] = {n="Delivery for Marin",s="A Meccania, Sprizzy invia la Polvere Viola a Marin Granstrippo e le ricorda il favore che Marin le deve.",h="A Meccania, Sprizzy invia la Polvere Viola a Marin Granstrippo e le ricorda il favore che Marin le deve.",kw={"meccania","marin granstrippo","elisir noggenfogger","sprizzy","tanaris","polvere viola"},sec={{t="Una consegna in città",b="A Meccania, Sprizzy ti dà la Polvere Viola dopo che le hai portato l’Amanita Viola. Marin Granstrippo si trova nella stessa città, e Sprizzy ti chiede di ricordarle che Marin le deve un favore."}},faq={{q="Chi ti manda da Marin Granstrippo?",a="Dopo che le hai portato l’Amanita Viola, Sprizzy ti manda da Marin Granstrippo con la Polvere Viola.",al={"chi ti dà la consegna per marin","datore missione consegna per marin","consegna di sprizzy"}},{q="Quale oggetto stai consegnando?",a="Sprizzy ti dà la Polvere Viola da consegnare a Marin Granstrippo.",al={"cosa porti a marin","oggetto consegna marin","che polvere è"}},{q="Dove si trova Marin Granstrippo?",a="Marin Granstrippo si trova a Meccania, la stessa città di Sprizzy.",al={"posizione marin granstrippo","dov'è marin","trovare marin granstrippo"}},{q="Che messaggio vuole che tu riferisca Sprizzy a Marin?",a="Sprizzy ti chiede di dire a Marin Granstrippo che le deve un favore.",al={"messaggio di sprizzy","cosa dice sprizzy a marin","favore di sprizzy"}}},fp="18,105,15.186.0,36.98.0,29.66.0,36.62.0,48.73.0"}
P.entries["quest:2662"] = {n="Elisir di Granstrippo",s="A Meccania, Marin Granstrippo mescola la Polvere Viola alla rugiada. Ti chiede di tornare tra poco, quando il suo elisir favoloso dovrebbe essere pronto.",h="A Meccania, Marin Granstrippo mescola la Polvere Viola alla rugiada.",kw={"rugiada","meccania","goblin","marin granstrippo","elisir noggenfogger","polvere","sprizzy","tanaris"},sec={{t="Mescolare l'Elisir",b="Marin ha la rugiada e la polvere. Comincia a mescolarle e l'Elisir Noggenfogger dovrebbe essere pronto dopo una breve attesa. Poi parlargli di nuovo."},{t="Il verdetto di Marin",b="Quando Marin ha finito, ti rifila una bevanda e la definisce meravigliosa. Si vanta dei milioni che gli frutterà, poi ti chiede di farti da parte per non intralciare gli affari. Sprizzy sostiene che Marin gli debba un favore, ma Marin ride e liquida la cosa come uno scherzo."}},faq={{q="Chi offre questa missione?",a="Marin Granstrippo lo offre a Meccania.",al={"datore di missione noggenfogger","chi dà l'elisir noggenfogger","missione di marin granstrippo"}},{q="Cosa è successo prima di questa fase?",a="Segue Delivery for Marin. Prima sono venuti The Thirsty Goblin, In Good Taste e Sprizzy's Secret Ingredient.",al={"prerequisiti dell'elisir noggenfogger","missione precedente per marin","cosa viene prima dell'elisir noggenfogger"}},{q="Quali ingredienti combina Marin qui?",a="Marin mescola la Polvere Viola di Sprizzy alla rugiada.",al={"ingredienti noggenfogger","cosa sta mescolando marin","cosa c'è nell'elisir"}}},fp="19,143,17.145.0,15.244.1,22.42.0,27.117.0,41.50.0"}
P.entries["quest:267"] = {n="The Trogg Threat",s="Al Cancello Meridionale di Loch Modan, il Capitano Granchiasso affronta una minaccia crescente di trogg con troppo pochi difensori. La Riserva di Forgiardente è stata richiamata sui fronti dell'Alleanza, lasciandolo a difendere il passo mentre i trogg minacciano le colline vicine.",h="Al Cancello Meridionale di Loch Modan, il Capitano Granchiasso affronta una minaccia crescente di trogg con...",kw={"capitano granchiasso","riserva di forgiardente","khaz modan","loch modan","magni barbabronzea","cancello meridionale","trogg","dente roccioso di trogg"},ang={["faction:Alliance"]="In quanto membro dell'Alleanza, vedi come gli impegni in terre lontane abbiano lasciato senza riserve difensive guarnigioni locali come quella di Loch Modan.",["race:Dwarf"]="In quanto nano, ridurre il numero dei trogg vicino al Cancello Meridionale è un dovere diretto verso Khaz Modan. Re Magni Barbabronzea in persona ti loderà per questo."},sec={{t="Una frontiera sguarnita",b="I montanari nanici e la Riserva di Forgiardente sono partiti per rinforzare i fronti dell'Alleanza. Ora il Capitano Granchiasso ha soltanto una piccola guarnigione. Ordini rigorosi lo trattengono al cancello e gli impediscono di guidare un attacco negli altopiani. Coloni e viaggiatori che si trovano là restano esposti alle imboscate."},{t="Fermare l'avanzata",b="I trogg delle gole vicine minacciano Khaz Modan. Se lasciati indisturbati, si moltiplicano in fretta e potrebbero sopraffare gli avamposti nanici. Granchiasso chiede aiuto per guadagnare tempo e ridurne il numero. Attacca i trogg nelle loro tane sulle colline, poi porta indietro i loro denti di pietra recisi come prova."}},faq={{q="Chi è il Capitano Granchiasso?",a="Il Capitano Granchiasso è un ufficiale militare nanico nella torre di guardia al Cancello Meridionale di Loch Modan. Con una piccola guarnigione, deve difendere il passo dagli intrusi.",al={"capitano granchiasso","chi assegna the trogg threat","granchiasso"}},{q="Perché il Cancello Meridionale è a corto di personale?",a="La Riserva di Forgiardente è stata inviata a combattere su lontani fronti dell'Alleanza. Al cancello resta soltanto una piccola forza, vincolata al proprio incarico difensivo e incapace di contrattaccare.",al={"perché non ci sono guardie","riserva di forgiardente assente","dove sono i soldati nanici"}},{q="Cosa sono i Denti di Pietra dei Trogg?",a="I denti di pietra recisi dei trogg sono denti naturalmente pietrificati, simili alla pietra, e testimoniano la loro discendenza sotterranea e terragna. Granchiasso li richiede come prova che i trogg siano stati uccisi.",al={"dente roccioso di trogg","denti di pietra","perché i denti dei trogg"}},{q="Dove si trovano i trogg?",a="I trogg vivono tra le colline rocciose, nelle gole e nei siti di scavo lungo la strada vicino al Cancello Meridionale di Loch Modan.",al={"dove trovare i trogg","posizioni trogg loch modan","dove sono i trogg per questa missione"}},{q="Perché i trogg sono una minaccia così grande al momento?",a="I trogg si moltiplicano in fretta e attaccano con ferocia per difendere il proprio territorio. Con le truppe impegnate altrove, possono sopraffare le terre abitate e minacciare i passi che collegano Loch Modan ai territori vicini.",al={"perché i trogg sono pericolosi","problema trogg","cosa vogliono i trogg"}},{q="In che modo completare questa missione aiuta Re Magni Barbabronzea?",a="Re Magni Barbabronzea è responsabile della sicurezza di tutto Khaz Modan. Ridurre il numero dei trogg mentre gli eserciti di Forgiardente combattono all'estero aiuta a proteggere le linee di rifornimento interne e gli insediamenti di frontiera vulnerabili.",al={"legame con magni barbabronzea","magni se ne cura","perché aiutare forgiardente"}}},fx={["5b5ee45d"]={q="Perché il Capitano Granchiasso vuole che venga fatto?",a="Con la Riserva di Forgiardente schierata sul fronte dell'Alleanza, il Capitano Granchiasso non ha uomini a sufficienza per mettere in sicurezza la regione. Il suo reggimento è bloccato a difendere la torre di guardia meridionale da una possibile invasione. Se i trogg che si radunano sulle colline vicine non vengono fermati, potrebbero facilmente sopraffare l'avamposto e invadere Loch Modan.",al={"motivo di granchiasso","perché combattere i trogg","scopo del capitano granchiasso"}},ba878bae={q="Perché i trogg infestano le colline vicino alla Porta Meridionale?",a="I trogg sono riemersi in tutte le terre dei nani e avanzano aggressivamente verso gli insediamenti e le rotte di viaggio. Le gole circostanti sono un terreno ideale per un'invasione, così si aggirano sulle creste vicino alla Porta Meridionale, in attesa di colpire le difese vulnerabili, indebolite dalla continua carenza di truppe.",al={"chi sono i trogg","bersagli trogg","perché i trogg sono qui"}}},fp="16,241,19.279.0,17.283.0,25.170.0,38.173.0,27.184.0,29.111.0,43.196.0,58.204.0"}
P.entries["quest:268"] = {n="Return to Sven",s="Porti il diario completo di Jitters il Teso all’accampamento di Sven Yorgen, vicino alle Marche Occidentali. Le sue pagine potrebbero rispondere alle domande che lo tormentano dall’assassinio della sua famiglia.",h="Porti il diario completo di Jitters il Teso all’accampamento di Sven Yorgen, vicino alle Marche Occidentali.",kw={"cavalieri oscuri","boscovespro","magione desolata","jitters il teso","diario completo di jitters il teso","morbent fel","sven yorgen","cascina degli yorgen"},ang={["class:Paladin"]="Come paladino, aiuti Sven a scoprire chi ha orchestrato l’assassinio della sua famiglia. Il tuo sacro dovere ti chiama a proteggere gli innocenti e a cercare giustizia.",["faction:Alliance"]="La distruzione della Cascina degli Yorgen dimostra che Roccavento non è riuscita a proteggere gli insediamenti di frontiera di Boscovespro dalle ombre incombenti."},sec={{t="La confessione di un codardo",b="Quando la fattoria di Sven Yorgen fu attaccata, Jitters il Teso fuggì nei boschi, lasciandosi dietro un diario incompleto. Temendo l’ira di Sven e tormentato da ciò che aveva visto, si nascose nel profondo di Boscovespro. Quando lo trovi, ti consegna volentieri il suo diario completo. Spera che il resoconto integrale gli eviti di affrontare Sven di persona."},{t="Smascherare i Cavalieri Oscuri",b="Il resoconto completo di Jitters il Teso spiega perché i Cavalieri Oscuri hanno ucciso la famiglia di Sven. Cercavano un artefatto, non si trattò di un’ondata casuale di non morti né di un attacco di bestie feroci. Sven ricorda anche di aver visto quelle stesse figure incappucciate incontrarsi di nascosto con il negromante Morbent Fel, vicino alla Magione Desolata. Ora il suo dolore cieco si è trasformato in una caccia per vendicarsi di Morbent Fel."}},faq={{q="Perché Jitters il Teso è così terrorizzato da Sven Yorgen?",a="Jitters il Teso è fuggito dalla fattoria di Sven e teme di affrontare l’ira del contadino in lutto. Ti chiede di portare il suo diario a Sven, così che possa leggere il resoconto.",al={"perché jitters il teso è spaventato","jitters il teso ha paura di sven","cosa ha fatto jitters il teso"}},{q="Cosa c'è nel Diario completo di Jitters il Teso?",a="Il diario completo di Jitters il Teso racconta per intero ciò che è accaduto alla fattoria di Sven. Sven deve leggerlo per capire cosa è successo alla sua famiglia.",al={"cosa dice il diario","storia del diario completo di jitters il teso"}},{q="Chi sono i Cavalieri Oscuri menzionati da Sven?",a="I Cavalieri Oscuri sono misteriose figure incappucciate che vagano per Boscovespro. Cercano potenti reliquie magiche e si lasciano alle spalle morte e rovina.",al={"chi sono i cavalieri oscuri","cavalieri a boscovespro","cavalieri neri"}},{q="Come è collegato Morbent Fel all'attacco alla fattoria di Sven?",a="Morbent Fel è un potente negromante nella parte occidentale di Boscovespro. Le indagini di Sven e il diario di Jitters il Teso rivelano il suo legame con l’attacco.",al={"legame con morbent fel","perché morbent fel","chi è morbent fel"}},{q="Dove si può trovare Sven Yorgen?",a="Sven ha lasciato la sua cascina in rovina e si è trasferito in un piccolo accampamento sulle colline nordoccidentali di Boscovespro, vicino al passaggio di confine con le Marche Occidentali.",al={"dove si trova sven","posizione di sven yorgen","accampamento di sven"}},{q="Cosa succede dopo aver dato il diario a Sven?",a="Dopo aver letto il resoconto di Jitters il Teso, Sven ti chiede di dimostrare le tue abilità in combattimento in Proving Your Worth.",al={"missione dopo return to sven","prossima missione di sven"}}},fx={ba46c9da={q="Perché Jitters ha bisogno che tu consegni il diario invece di portarlo lui stesso?",a="Jitters è completamente sopraffatto dalla paura. Si nascose senza farsi vedere nel fienile di Sven mentre la famiglia di quest'ultimo veniva massacrata, poi fuggì lasciandosi alle spalle il diario incompleto. Piuttosto che rischiare di affrontare di persona l'ira di Sven, ti affida volentieri il diario completo, così potrai rivelare la verità su ciò che è davvero accaduto.",al={"perché mandare me da jitters","perché jitters non può parlare con sven","perché consegnare il diario di jitters"}}},fp="14,156,21.321.0,25.373.1,43.139.0,38.146.1,42.137.0,58.137.1,31.125.0,43.99.1"}
P.entries["quest:269"] = {n="Seeking Wisdom",s="A Roccavento, Sven Yorgen chiede al Vescovo Farthing un consiglio sacro su Boscovespro. Gli invia il Diario completo di Jitters il Teso, nella speranza che il vescovo riveli come infrangere lo scudo di Morbent Fel.",h="A Roccavento, Sven Yorgen chiede al Vescovo Farthing un consiglio sacro su Boscovespro.",kw={"vescovo farthing","cathedral of light","borgoscuro","boscovespro","jitters il teso","morbent fel","seeking wisdom","roccavento","sven yorgen"},ang={["class:Paladin"]="Da paladino, portare le richieste d'aiuto sacro dalle terre di confine abbandonate alla Cathedral of Light mette alla prova il dovere della Mano d'Argento di proteggere i dimenticati e purificare la necromanzia.",["class:Priest"]="Da sacerdote, il Vescovo Farthing ti spiega come le protezioni oscure corrompano il corpo e l'anima. La stregoneria dell'ombra richiede una consacrazione mirata, oltre alla lama.",["faction:Alliance"]="Da viaggiatore dell'Alleanza, il viaggio rivela il divario tra le sale di marmo sorvegliate di Roccavento e le città abbandonate di Boscovespro. Quelle città non ricevono rinforzi dalle guarnigioni."},sec={{t="Una supplica dalle ombre",b="Boscovespro soffre sotto antiche maledizioni e non morti voraci. La corte reale di Roccavento è diventata indifferente, e Sven Yorgen sa che la forza comune non può perforare le protezioni di Morbent Fel. Con il cuore spezzato, si rifugia in un accampamento vicino ai confini e ti chiede di portare alla chiesa il diario assemblato di Jitters il Teso. La strada verso nord conduce alla Cathedral of Light."},{t="Consiglio nella Cattedrale",b="Alla Cathedral of Light di Roccavento, il Vescovo Farthing ascolta le richieste d'aiuto di Boscovespro. Il resoconto di Jitters il Teso conferma il potere di Morbent Fel: una vile stregoneria protegge il negromante dai colpi comuni. Il solo coraggio non può superare quelle protezioni. Per sconfiggerlo, bisogna trovare uno strumento sacro incantato."}},faq={{q="Perché Sven ti invia dal Vescovo Farthing invece che dal Re Anduin?",a="Sven si fida del Vescovo Farthing, un uomo compassionevole e colto della Sacra Luce, che conosce la magia empia. La nobiltà e l'esercito di Roccavento hanno in gran parte abbandonato Borgoscuro e le terre circostanti, lasciandole a cavarsela da sole nella paralisi politica; perciò Sven non si aspetta soldati dai canali ufficiali.",al={"perché farthing","perché non i nobili di roccavento","roccavento ignora boscovespro"}},{q="Cos'è il diario di Jitters il Teso e perché il Vescovo ne ha bisogno?",a="Jitters il Teso ha annotato ciò che accadde durante l'attacco alla fattoria di Sven. Sven invia il resoconto completo al Vescovo Farthing, perché possa consigliarti mentre ti prepari ad affrontare Morbent Fel.",al={"cos'è il diario di jitters","perché il diario di jitters","diario completo di jitters"}},{q="Chi è Morbent Fel?",a="Morbent Fel è un potente negromante avvistato alla Magione Desolata, a Boscovespro. Comanda orde di scheletri e si protegge con potenti incantesimi che respingono le armi comuni.",al={"chi è morbent fel","storia di morbent fel"}},{q="Dove si trova il Vescovo Farthing?",a="Il Vescovo Farthing vive nella Cathedral of Light, la grande cattedrale degli umani nel quartiere di Piazza della Cattedrale, a Roccavento.",al={"dove si trova farthing","posizione di farthing","mappa vescovo farthing"}},{q="Cosa succede dopo che il Vescovo Farthing ha letto il diario?",a="Il Vescovo Farthing spiega che i colpi comuni non possono ferire Morbent Fel. Ti indica una reliquia consacrata capace di dissolvere le protezioni del negromante, dando inizio alla ricerca della Doomed Fleet.",al={"cosa fare dopo seeking wisdom","proseguimento seeking wisdom","dopo seeking wisdom"}},{q="Dove si trova Sven Yorgen a Boscovespro?",a="Sven Yorgen si rifugia in un piccolo accampamento nella parte nord-occidentale di Boscovespro, vicino al confine del fiume. Si trova a sud della Foresta di Elwynn e a ovest del Cimitero di Collecorvo, infestato dai fantasmi.",al={"dove si trova sven","posizione di sven yorgen","sven's camp"}}},fx={["12ed4f38"]={q="Perché Sven Yorgen ha bisogno che tu consegni il diario?",a="Sven resiste da solo a Boscovespro, consumato dalla sete di vendetta e dal dolore, mentre sopravvive in un accampamento circondato da orrori. Roccavento ha abbandonato Borgoscuro e le terre circostanti al loro destino, lasciandoli senza guardie reali in grado di aiutarlo. Sven non può lasciare Boscovespro senza difesa e non ha i mezzi per spezzare da solo la magia oscura di Morbent Fel. Dopo aver dimostrato il tuo valore contro le minacce locali, sei la sua unica speranza affidabile per portare la verità scoperta da Jitters a qualcuno che abbia la saggezza e il potere sacro necessari per aiutare.",al={"perché proprio io per sven","perché mandare il giocatore dal vescovo farthing","perché sven non va a roccavento"}}},fp="14,177,23.345.0,24.281.1,65.291.0,57.173.0,19.184.0,33.123.0,53.193.1,40.161.0"}
P.entries["quest:27"] = {n="A Lesson to Learn",s="A Picco del Tuono, Turak Totem Runico manda i giovani druidi tauren a nord per studiare le acque. Il loro viaggio li conduce a Nottequieta, a Radaluna, dove il Circolo Cenariano guida il loro addestramento.",h="A Picco del Tuono, Turak Totem Runico manda i giovani druidi tauren a nord per studiare le acque.",kw={"aquatic form","circolo cenariano","dendrite ardistella","altura degli anziani","a lesson to learn","radaluna","nottequieta","picco del tuono","turak totem runico"},ang={["class:Druid"]="Da druido, lasci alle spalle la sopravvivenza sulla terraferma e inizi a imparare a respirare e muoverti sott'acqua.",["faction:Horde"]="Come membro dell'Orda, onori la sacra neutralità di Radaluna e cammini al fianco degli Elfi della Notte sotto la volta condivisa di Cenarius.",["race:Tauren"]="Come tauren, ti unisci ai druidi di Picco del Tuono nella più ampia confraternita Cenariana di Radaluna."},sec={{t="Padronanza degli Abissi",b="Hai imparato la forma d'orso e la sua forza. Ora Turak Totem Runico orienta i suoi allievi verso l'adattabilità. Le vie d'acqua di Azeroth nascondono pericoli difficili da affrontare per chi è legato alla terra. Perciò manda a nord coloro che sono devoti alla natura, affinché imparino Aquatic Form."},{t="La Via per Nottequieta",b="Turak Totem Runico ti manda oltre Mulgore per imparare ad adattarti alle acque. Viaggi fino a Radaluna, il santuario ai piedi del Monte Hyjal, e raggiungi Nottequieta. Qui, i mentori Elfo della Notte del Circolo Cenariano accolgono gli allievi tauren. Mettono da parte i conflitti tra fazioni per preservare gli insegnamenti condivisi di Cenarius."},{t="Le Due Prove",b="Dendrite Ardistella ti attende a Nottequieta, dove inizia il tuo addestramento. L'anziano Elfo della Notte dice che la padronanza delle acque va meritata. Ti attendono due prove. Una mette alla prova la tua resistenza e la tua compostezza sott'acqua. L'altra richiede una profonda comprensione spirituale dell'aspetto acquatico."}},faq={{q="Chi assegna la missione A Lesson to Learn?",a="Turak Totem Runico te la affida dall'Altura degli Anziani a Picco del Tuono, dove addestra i druidi. Quando avrai abbastanza esperienza, ti manderà a seguire un addestramento avanzato.",al={"chi inizia a lesson to learn","dove ottengo a lesson to learn","missione turak totem runico"}},{q="Dove devo andare per completare questa missione?",a="Viaggi fino a Nottequieta, a Radaluna, e parli con Dendrite Ardistella del Circolo Cenariano.",al={"dove consegno a lesson to learn","posizione dendrite ardistella","dov'è nottequieta"}},{q="A quale abilità porta questa catena di missioni?",a="Questo cammino conduce ad Aquatic Form. Ti permette di nuotare rapidamente sott'acqua e respirare senza limiti sotto la superficie.",al={"quale forma concede","missione aquatic form","perché fare questa missione"}},{q="Perché i druidi tauren vanno da un Elfo della Notte per l'addestramento?",a="Il Circolo Cenariano è una confraternita neutrale devota a Cenarius e alla conservazione della natura. A Radaluna, gli Elfi della Notte e i tauren mettono da parte le tensioni tra Orda e Alleanza per apprendere insieme le arti sacre.",al={"perché radaluna","perché dendrite ardistella","circolo cenariano tauren"}},{q="Di quali prove parla Dendrite Ardistella?",a="Dendrite Ardistella ti parla di due prove. Una mette alla prova la tua compostezza sott'acqua, sotto pressione. L'altra mette alla prova la tua determinazione spirituale nel comprendere l'aspetto acquatico.",al={"quali sono le due prove","prove di dendrite","prove acquatiche"}},{q="Come raggiunge Radaluna un druido a questo stadio?",a="I druidi possono usare Teleport: Radaluna, un incantesimo nato dal loro legame spirituale, per raggiungere direttamente Nottequieta da qualsiasi luogo di Azeroth.",al={"come arrivare a radaluna","teletrasporto per radaluna","arrivare a nottequieta"}}},fx={b1c6f6a1={q="Perché Turak Totem Runico mi manda a Radaluna?",a="Turak Totem Runico ha seguito i tuoi progressi come protettore della natura e crede che tu sia pronto a proseguire il tuo cammino druidico. Ti manda a Radaluna affinché tu possa entrare in comunione con il Circolo Cenariano e apprendere l'aspetto animale concesso da Cenarius, che permette di padroneggiare le acque.",al={"perché turak mi manda","motivo di turak totem runico","perché a lesson to learn"}},["055244fc"]={q="Perché devo affrontare personalmente questo addestramento?",a="La metamorfosi non è un incarico che qualcun altro possa affidarti o svolgere al posto tuo. Ogni druido deve dimostrare di persona al Circolo Cenariano la propria forza spirituale e resistenza fisica, per entrare in sintonia con la benedizione di Cenarius e ottenere l'aspetto acquatico.",al={"perché devo affrontare le prove","perché mandarmi a radaluna","perché proprio io per a lesson to learn"}}},fp="17,180,21.253.0,22.320.0,15.288.0,38.155.0,39.95.0,43.113.0,52.206.0,45.168.0,47.132.0"}
P.entries["quest:270"] = {n="La flotta maledetta",s="Il Vescovo Farthing ti manda a nord da Roccavento per trovare un modo di superare le protezioni di Morbent Fel. La tua pista attraversa Khaz Modan e termina al relitto della Third Fleet di Kul Tiras, al largo delle Paludi Grigie.",h="Il Vescovo Farthing ti manda a nord da Roccavento per trovare un modo di superare le protezioni di Morbent...",kw={"vescovo farthing","flotta dannata","glorin frontesalda","kul tiras","lightforge iron","porto di menethil","morbent fel","third fleet","paludi grigie"},ang={["class:Paladin"]="Come paladino, cerchi un metallo sacro con cui abbattere un negromante empio. Impugni armi consacrate dalla Luce per purificare l’oscurità.",["class:Priest"]="Come sacerdote, segui la guida del Vescovo Farthing e le antiche conoscenze della Chiesa sulle reliquie benedette e i minerali consacrati.",["faction:Alliance"]="Come viaggiatore dell’Alleanza, fai da tramite tra gli isolati insediamenti umani del sud, i porti nanici e le antiche rotte marittime.",["profession:Blacksmithing"]="Come fabbro, scopri il raro Lightforge Iron, un metallo intriso di fede e forgiato con maestria."},sec={{t="Un'arma di Sacra Verità",b="Le protezioni di Morbent Fel respingono l’acciaio comune nel suo rifugio alla Magione Desolata. Il Vescovo Farthing ti manda a cercare un’arma legata alla Sacra Luce. La chiave è il Lightforge Iron, un raro metallo consacrato i cui colpi recano la verità sacra e perforano le difese magiche."},{t="Il Relitto della Third Fleet",b="A Boscovespro non si trova Lightforge Iron. Il Vescovo Farthing ricorda che la Third Fleet di Kul Tiras affondò anni fa lungo la pericolosa costa delle Paludi Grigie, a nord di Forgiardente. Un galeone trasportava un carico del prezioso minerale. Ti rechi a Porto di Menethil per incontrare Glorin Frontesalda, un contatto nanico che conosce le paludi e i loro relitti."}},faq={{q="Perché devo viaggiare fino alle Paludi Grigie?",a="Gli incantesimi oscuri di Morbent Fel respingono gli attacchi comuni. Il Vescovo Farthing dice che solo un’arma forgiata con il sacro Lightforge Iron può spezzare le sue protezioni. Il carico conosciuto si trova tra i relitti della Third Fleet di Kul Tiras, al largo di Porto di Menethil.",al={"perché andare alle paludi grigie","perché porto di menethil","viaggio alle paludi grigie"}},{q="Chi è Morbent Fel?",a="Morbent Fel è un negromante che dimora alla Magione Desolata, a Boscovespro. La sua stregoneria ha alimentato gran parte della rivolta dei non morti che minaccia la regione. La sopravvivenza di Borgoscuro dipende dalla sua sconfitta.",al={"identità di morbent fel","chi è il negromante","negromante di boscovespro"}},{q="Chi è Glorin Frontesalda?",a="Glorin Frontesalda è un nano che si trova a Porto di Menethil, nelle Paludi Grigie. È un alleato della Chiesa della Sacra Luce e conosce la costa, i relitti e il recupero dei carichi nelle paludi.",al={"chi è frontesalda","ruolo di frontesalda"}},{q="Cos'è il Lightforge Iron?",a="Il Lightforge Iron è un metallo consacrato in modo speciale, molto apprezzato dal clero. Le armi forgiate con esso recano un potere sacro capace di perforare scudi oscuri e maledizioni necromantiche che il ferro comune non può superare.",al={"cosa fa il lightforge iron","metallo lightforge","ferro benedetto"}},{q="Cosa è successo alla Third Fleet di Kul Tiras?",a="Anni fa, la Third Fleet di Kul Tiras affondò lungo la costa aspra e paludosa delle Paludi Grigie. I suoi scafi giacciono ancora sotto l’acqua, tra carichi perduti, marinai annegati e predatori acquatici.",al={"destino della third fleet","navi di kul tiras nelle paludi grigie","come sono affondate le navi"}},{q="Questa missione prevede combattimenti immediati?",a="Viaggi come messaggero da Boscovespro, attraversando il Regno di Roccavento e Khaz Modan fino a Porto di Menethil. Lì contatti Glorin Frontesalda.",al={"c'è combattimento","missione di solo viaggio"}}},fx={ade8f412={q="Perché il Vescovo Farthing ti manda in questa missione?",a="Il Vescovo Farthing sa che il negromante Morbent Fel rappresenta una minaccia mortale per Boscovespro e che non può essere sconfitto con mezzi ordinari. Per sconfiggere una forza tanto oscura, ti serve un'arma benedetta dal potere sacro e forgiata con Lightforge Iron consacrato. Poiché quel ferro andò perduto in mare insieme alla Third Fleet di Kul Tiras, Farthing ti manda a nord, a Porto di Menethil, per consultare il suo associato nano Glorin Frontesalda, nella speranza di recuperare il metallo sommerso.",al={"perché il vescovo farthing vuole lightforge iron","motivo di farthing per the doomed fleet","perché cercare the doomed fleet"}},a631378f={q="Perché il Vescovo Farthing o la Night Watch non possono occuparsi personalmente di Morbent Fel?",a="La Night Watch è già pericolosamente impegnata a impedire che i confini di Boscovespro cedano sotto il peso di non morti senza senno, worgen e ragni. Il Vescovo Farthing deve occuparsi dei suoi doveri alla Cathedral of Light di Roccavento, e né lui né la milizia locale possono permettersi il tempo e gli uomini necessari per un lungo viaggio attraverso il continente fino alle Paludi. In quanto viaggiatore indipendente, hai la libertà e la determinazione per cercare il ferro perduto e affrontare direttamente il negromante.",al={"perché mandarmi per the doomed fleet","perché non ci va la night watch","perché il vescovo farthing ha bisogno di me"}}},fp="16,186,22.267.0,28.330.0,52.242.0,19.194.0,24.176.0,24.197.0,46.191.0,48.142.0"}
P.entries["quest:271"] = {n="Vyrin's Revenge",s="Al Padiglione Lungopasso, un cacciatore ti chiede di regolare un vecchio conto con Ol' Sooty. L'orso ha sfregiato Daryl il Giovincello durante una caccia, un anno fa.",h="Al Padiglione Lungopasso, un cacciatore ti chiede di regolare un vecchio conto con Ol' Sooty.",kw={"orso","daryl il giovincello","padiglione lungopasso","ol' sooty","cicatrice","thelsamar","vendetta di vyrin"},ang={["class:Hunter"]="Da cacciatore, ti viene chiesto di affrontare l'orso sfuggito ai cacciatori del Padiglione Lungopasso e che ha sfregiato Daryl."},sec={{t="Una vecchia cicatrice",b="Un cacciatore del Padiglione Lungopasso ti chiede di affrontare Ol' Sooty, l'orso che ha sfregiato Daryl il Giovincello. I cacciatori del padiglione non erano riusciti ad abbatterlo, e Daryl ci aveva provato un anno fa. Il tentativo gli aveva lasciato un segno sopra l'occhio. Ol' Sooty si tiene nella sua tana, sulle colline sopra Thelsamar."},{t="Al padiglione",b="Al Padiglione Lungopasso, porti a Daryl il Giovincello la prova della fine di Ol' Sooty. Riconosce la Testa d'Orso e si tocca la cicatrice. Poi comincia a tremare e ti implora di portarla via."}},faq={{q="Chi è Ol' Sooty?",a="Ol' Sooty è l'orso che ha sfregiato Daryl il Giovincello durante una caccia, un anno fa.",al={"orso ol' sooty","sooty","orso ha sfregiato daryl"}},{q="Chi è Daryl il Giovincello?",a="Daryl il Giovincello è un abile cacciatore del Padiglione Lungopasso. Ol' Sooty gli ha lasciato una cicatrice sopra l'occhio.",al={"storia di daryl","chi è daryl","cicatrice di daryl"}},{q="Dove vive Ol' Sooty?",a="Puoi trovare Ol' Sooty nei dintorni della sua tana, sulle colline sopra Thelsamar.",al={"dove si trova ol' sooty","posizione di sooty","tana dell'orso"}},{q="Perché il cacciatore vuole uccidere Ol' Sooty?",a="Ol' Sooty ha sfregiato Daryl durante una caccia, un anno fa, e un cacciatore del Padiglione Lungopasso vuole vendicarsi.",al={"perché uccidere sooty","perché vendetta di vyrin","vendetta di daryl"}}},fp="15,140,11.292.0,12.182.1,17.80.0,27.105.0,26.68.0,42.97.0"}
P.entries["quest:272"] = {n="Trial of the Sea Lion",s="I druidi di Radaluna cercano lo spirito del leone marino attraverso un rito sacro. Recuperano due metà di pendente disperse, che rappresentano agilità e resistenza, poi le uniscono al Santuario di Remulos per prepararsi all'Aquatic Form.",h="I druidi di Radaluna cercano lo spirito del leone marino attraverso un rito sacro.",kw={"aquatic form","dendrite ardistella","mezzo pendente dell'agilità acquatica","mezzo pendente della resistenza acquatica","radaluna","nottequieta","pendente del leone marino","santuario di remulos","trial of the sea lion"},ang={["class:Druid"]="Questo rito è riservato ai druidi. Mette alla prova la loro maturità spirituale e il loro equilibrio prima che possano entrare in comunione con gli spiriti acquatici e assumere la forma del leone marino.",["race:NightElf"]="Custodi di lunga data di Radaluna e del Circolo Cenariano, i druidi Elfi della Notte venerano gli insegnamenti di Dendrite Ardistella e il suolo sacro attorno al Santuario di Remulos.",["race:Tauren"]="Per i druidi tauren appena accolti nel Circolo Cenariano, intraprendere la prova a Radaluna rafforza la loro comunione con gli spiriti della natura e approfondisce i loro legami con i loro mentori Elfo della Notte."},sec={{t="Il cammino verso la Aquatic Form",b="Gli iniziati druidi di Radaluna affrontano prove di sintonia mentre si preparano a navigare nelle acque profonde di Azeroth. La Trial of the Sea Lion segue le prime fasi del loro addestramento spirituale. Dendrite Ardistella la supervisiona a Nottequieta, dove gli iniziati imparano a bilanciare la grazia e la velocità del leone marino con la sua resistenza. Servono entrambe per assumerne la forma e affrontare le profondità oceaniche."},{t="Agilità e resistenza",b="La prova consiste nel riunire le due metà del Pendente del Leone Marino. Una rappresenta l'agilità del leone marino, che scivola tra correnti turbolente. L'altra rappresenta la sua resistenza, la forza necessaria per immergersi a lungo nell'acqua gelida senza cedere. Gli iniziati chiedono consiglio agli abitanti di Radaluna mentre cercano in tutto il mondo le reliquie disperse."},{t="Il Santuario di Remulos",b="Una volta trovate entrambe le metà, l'iniziato le porta vicino al Santuario di Remulos, dove possono essere unite in un unico talismano. Le energie del santuario fondono agilità e resistenza in armonia. Poi l'iniziato presenta il pendente restaurato a Dendrite Ardistella a Nottequieta. Con il pendente, il druido dimostra di essere pronto ad abbracciare l'aspetto del leone marino e a risvegliare l'Aquatic Form."}},faq={{q="Cos'è la Trial of the Sea Lion?",a="I druidi di Radaluna recuperano due metà di pendente e le uniscono al Santuario di Remulos. Le metà rappresentano agilità e resistenza, e il pendente restaurato viene presentato a Dendrite Ardistella come parte del cammino verso l'Aquatic Form.",al={"missione trial of the sea lion","cos'è la trial of the sea lion","prova del leone marino"}},{q="Chi assegna la missione Trial of the Sea Lion?",a="Il Custode Tajarri, al Santuario di Remulos a Radaluna, assegna la prova. Gli iniziati chiedono consiglio agli abitanti del luogo, uniscono le metà del pendente vicino al santuario, poi portano il pendente completo a Dendrite Ardistella a Nottequieta.",al={"chi assegna la trial of the sea lion","dove iniziare la trial of the sea lion","assegnatore missione trial of the sea lion"}},{q="Cosa rappresentano le due metà del pendente?",a="Le metà rappresentano l'agilità e la resistenza del leone marino. Una riflette la grazia e la rapidità necessarie per scivolare nelle acque profonde; l'altra, la tenacia e la forza per affrontare lunghi viaggi sott'acqua. Per padroneggiare le arti del mutamento di forma, i druidi devono rispettare e incarnare entrambe le qualità in egual misura.",al={"cosa sono le metà del pendente","significato metà del pendente","metà agilità e resistenza"}},{q="Dove si trovano le metà del pendente?",a="Gli iniziati scoprono dove sono nascoste la Mezzo Pendente dell'Agilità Acquatica e la Mezzo Pendente della Resistenza Acquatica parlando con gli abitanti di Radaluna. Druidi e abitanti del villaggio forniscono indizi sulle acque lontane dove ciascuna metà è andata perduta o è stata nascosta.",al={"come trovare le metà del pendente","dove trovare le metà del pendente","posizione metà pendente del leone marino"}},{q="Dove si assembla il Pendente del Leone Marino?",a="Le metà devono essere unite vicino al Santuario di Remulos a Radaluna. L'aura sacra del santuario aiuta a fondere agilità e resistenza in un unico talismano.",al={"come combinare le metà del pendente","dove unire le metà del pendente","dov'è il pendente del santuario di remulos"}},{q="Perché i druidi devono bilanciare agilità e resistenza?",a="Dendrite Ardistella insegna che agilità e resistenza devono essere bilanciate sott'acqua. La velocità senza tenacia porta allo sfinimento, mentre la resistenza senza rapidità lascia il nuotatore indifeso contro le forti correnti. Ai druidi servono entrambe le qualità per incarnare lo spirito del leone marino.",al={"perché agilità e resistenza","tratti leone marino druido","significato della prova del leone marino"}},{q="Cosa si ottiene completando la prova?",a="Completando la prova si ottiene il Pendente del Leone Marino restaurato e si supera una prova fondamentale per ottenere l'Aquatic Form. Padroneggiare agilità e resistenza dà all'iniziato le basi spirituali per assumere una forma capace di respirare e nuotare rapidamente sott'acqua.",al={"cosa ottieni dalla trial of the sea lion","ricompensa prova del leone marino","dà la aquatic form"}}},fp="21,210,24.398.0,21.373.0,21.372.0,34.228.0,42.224.0,41.281.0,37.254.0,50.144.0,46.274.0,39.259.0"}
P.entries["quest:273"] = {n="Rifornimenti per gli scavi",s="Jern Elmocorno ti manda da Thelsamar a cercare un carro lento che trasporta Polvere Esplosiva agli Scavi di Ferrocollo. I tre nani che lo trainano viaggiano verso sud lungo la riva del Loch.",h="Jern Elmocorno ti manda da Thelsamar a cercare un carro lento che trasporta Polvere Esplosiva agli Scavi di...",kw={"polvere esplosiva","huldar","ferrocollo","jern elmocorno","loch modan","miran","resupplying the excavation","saean","thelsamar"},ang={["profession:Mining"]="Conosci i pericoli di trasportare Polvere Esplosiva volatile su terreni impervi. La spedizione è fondamentale per gli scavatori del sud.",["race:Dwarf"]="Da nano Barbabronzea, aiuti a rifornire gli Scavi di Ferrocollo proteggendo la spedizione di Polvere Esplosiva sulle pericolose strade di Loch Modan."},sec={{t="Un carico pesante lungo la riva",b="Nel sud di Loch Modan, gli Scavi di Ferrocollo hanno bisogno di Polvere Esplosiva per farsi strada nella roccia dura. La polvere arriva prima a Thelsamar, dove Jern Elmocorno incarica Huldar, Miran e Saean di trasportare verso sud tre barili volatili. Il pesante carico rallenta la squadra lungo la strada in riva al lago, dandoti il tempo di raggiungerla e aiutarla lungo il cammino."},{t="Tradimento nell'ombra",b="Il carro di Huldar è stato assalito sulla strada meridionale. I nani Ferroscuro hanno attaccato per sabotare il lavoro archeologico della spedizione Barbabronzea. Saean aveva lavorato al fianco di Huldar per quasi un anno, eppure ha contribuito a organizzare l'imboscata da simpatizzante dei Ferroscuro."}},faq={{q="Chi avvia la missione Resupplying the Excavation?",a="Jern Elmocorno ti manda da Thelsamar dopo che gli hai portato la Polvere Esplosiva. Ti chiede di seguire la strada verso sud lungo il Loch e raggiungere la squadra di rifornimento.",al={"chi dà resupplying the excavation","iniziatore missione resupplying the excavation","dove iniziare resupplying the excavation"}},{q="Dove si possono trovare Huldar e il carro?",a="Huldar e il carro si trovano a sud di Thelsamar, lungo la strada che costeggia le rive occidentale e meridionale del Loch e porta agli Scavi di Ferrocollo.",al={"trovare huldar","posizione huldar","dov'è il carro a loch modan"}},{q="Perché la Polvere Esplosiva viene inviata a Ferrocollo?",a="Il Prospettore Ferrocollo e la sua squadra scavano alla ricerca di antichi cimeli nel sito di scavo meridionale. Hanno bisogno di Polvere Esplosiva per frantumare la pietra dura e farsi strada negli strati sotterranei.",al={"perché ferrocollo ha bisogno di polvere","ferrocollo polvere esplosiva","perché polvere esplosiva agli scavi"}},{q="Chi ha teso l'imboscata al carro di Huldar?",a="Jern si aspetta che la squadra di Huldar percorra la solita strada a sud di Thelsamar, lungo il Loch. Scoprirai chi ha attaccato il carro quando raggiungerai Huldar.",al={"chi ha attaccato il carro","imboscata carro loch modan","chi ha attaccato huldar"}},{q="Quale ruolo ha avuto Saean nell'attacco?",a="Saean viaggia con Huldar e Miran per trasportare i pesanti barili di Polvere Esplosiva. Scoprirai il suo ruolo nell'attacco quando raggiungerai la squadra.",al={"chi è saean","tradimento di saean","cosa ha fatto saean"}},{q="Quale missione segue dopo aver trovato Huldar?",a="Parlare con Huldar completa questa parte del viaggio. Il suo racconto della spedizione ti indica cosa viene dopo.",al={"missione successiva dopo resupplying the excavation","missione dopo huldar"}}},fx={["72005fbc"]={q="Perché Jern Elmocorno ti manda a cercare Huldar?",a="Jern Elmocorno si rende conto che sei arrivato a consegnare la polvere esplosiva appena dopo che Huldar e la sua squadra sono partiti con il pesante carro in direzione di Ironband's Excavation. Poiché il carro è carico di barili, Jern sa che avanzeranno lentamente lungo la strada meridionale che costeggia Loch. Ti manda avanti per raggiungerli e dare una mano con questa spedizione essenziale.",al={"motivo di jern elmocorno","perché raggiungere huldar","perché jern ti manda"}}},fp="26,172,29.342.0,24.247.1,48.162.0,40.143.0,42.169.0,28.140.1,39.141.1,43.119.1"}
P.entries["quest:274"] = {n="A Dark Threat Looms",s="Alla Diga di Pietrasalda, una polvere insolita mette a rischio Loch Modan e Forgiardente. Ashlan Pietroscura, a Dun Modr, la identifica come Seaforium instabile, capace di esplodere a contatto con l’acqua.",h="Alla Diga di Pietrasalda, una polvere insolita mette a rischio Loch Modan e Forgiardente.",kw={"ashlan pietroscura","polvere esplosiva","capo ingegnere hinderweir vii","un'oscura minaccia incombe","colloide disarmante","forgiardente","seaforium","paludi grigie"},ang={["faction:Alliance"]="I difensori dell’Alleanza devono agire in fretta per aiutare il Capo Ingegnere Hinderweir VII e mettere in sicurezza i bassopiani prima che i sabotatori nemici distruggano infrastrutture strategiche.",["profession:Engineering"]="Gli ingegneri riconosceranno il Seaforium come un composto volatile estremamente potente. Richiede una manipolazione attenta e contromisure chimiche precise per prevenire onde d’urto devastanti.",["race:Dwarf"]="Per i nani di Khaz Modan, il Seaforium volatile vicino alla porta d’accesso a Dun Morogh e Forgiardente è una minaccia esistenziale, se è nelle mani di sabotatori esperti di esplosivi."},sec={{t="Una scoperta volatile",b="Ashlan Pietroscura riconosce i cristalli argentati e l’odore pungente nei campioni della Diga di Pietrasalda. La polvere è Seaforium. Rimane inerte finché è asciutta, ma l’umidità la fa reagire violentemente. Ashlan avverte che un’esplosione incontrollata potrebbe far saltare Forgiardente fuori dalla montagna."},{t="Una corsa contro il tempo",b="Ashlan Pietroscura prepara un Colloide Disarmante per neutralizzare l’esplosivo. Per neutralizzare il Seaforium, ti servono il colloide, il Veleno di Solcatore, il Cristallo dei Mo'grosh frantumato e una Lacrima di Crocolisco. Bisogna avvertire subito il Capo Ingegnere Hinderweir VII, prima che l’umidità provochi una catastrofe."}},faq={{q="Che tipo di esplosivo è stato trovato alla diga?",a="Ashlan Pietroscura identifica la polvere della diga come Seaforium, riconoscibile dai cristalli argentati e dall’odore chimico pungente.",al={"che polvere è questa","cos'è la polvere","polvere di seaforium"}},{q="Perché il Seaforium è così pericoloso qui?",a="Il Seaforium è relativamente innocuo finché è asciutto, ma esplode con effetti catastrofici a contatto con l’acqua. Alla Diga di Pietrasalda, che trattiene le acque di Loch Modan, rappresenta un pericolo straordinario.",al={"perché il seaforium è pericoloso","cosa fa esplodere il seaforium"}},{q="Chi è Ashlan Pietroscura?",a="Ashlan Pietroscura è uno specialista nano dell’Alleanza che vive nelle Paludi Grigie. Le sue competenze ingegneristiche e chimiche gli permettono di studiare polveri misteriose e creare neutralizzatori.",al={"chi è ashlan","identità di ashlan pietroscura"}},{q="Chi è il Capo Ingegnere Hinderweir VII?",a="Il Capo Ingegnere Hinderweir VII supervisiona l’ingegneria e la difesa della regione dalla Diga di Pietrasalda, a Loch Modan. Protegge le infrastrutture dei nani.",al={"chi è hinderweir","capo ingegnere hinderweir"}},{q="Come si può neutralizzare il Seaforium?",a="Per disinnescare la reazione chimica, il Colloide Disarmante di Ashlan va combinato con il Veleno di Solcatore, il Cristallo dei Mo'grosh frantumato e una Lacrima di Crocolisco.",al={"come disinnescare il seaforium","ricetta per disinnescare il seaforium","ricetta del colloide disarmante"}},{q="Qual è il pericolo per Forgiardente?",a="Ashlan avverte che una detonazione incontrollata potrebbe provocare cedimenti sismici nei sistemi montuosi circostanti e far saltare Forgiardente fuori dalla montagna.",al={"forgiardente è in pericolo","come è minacciata forgiardente"}}},fx={["7e9e3f07"]={q="Perché Ashlan Pietroscura vuole che tu lo faccia?",a="Ashlan si è reso conto che la sostanza misteriosa non è comune polvere esplosiva, ma seaforium instabile. A contatto con l'acqua, il suo potere esplosivo potrebbe far crollare intere montagne. Ashlan deve avvertire immediatamente il Capo Ingegnere Hinderweir VII, così che gli ingegneri nani possano preparare una soluzione neutralizzante prima che il composto volatile esploda.",al={"perché ashlan ti manda","motivo di ashlan","perché avvertire hinderweir"}}},fp="19,182,20.262.0,16.280.1,44.120.0,35.189.0,25.175.0,37.161.0,37.142.0,32.148.0"}
P.entries["quest:2741"] = {n="The Super Egg-O-Matic",s="Al pannello di controllo, l'ultima invenzione di Curgle Criccaleva scoppietta furiosamente mentre le uova di ippogrifo entrano nella macchina.",h="Al pannello di controllo, l'ultima invenzione di Curgle Criccaleva scoppietta furiosamente mentre le uova di...",kw={"curgle criccaleva","egg-o-matic","eggometro","feralas","uovo di ippogrifo","tanaris"},sec={{t="Una Macchina di Curgle Criccaleva",b="Al suo pannello di controllo, l'ultima invenzione di Curgle Criccaleva scoppietta furiosamente. È fatta per un uovo di ippogrifo trovato sulle montagne del sud di Feralas, attorno alle Rovine di Isildien."},{t="Cosa fa la macchina",b="Inserisci un uovo di ippogrifo e la macchina risponde con bip e strani rumori meccanici. L'Eggometro pesa e misura l'uovo, poi lo impacchetta in pochi istanti. Ne esce una Scatola di Uova, che contiene un uovo di qualche tipo."}},faq={{q="Chi ha costruito il The Super Egg-O-Matic?",a="Curgle Criccaleva ha costruito The Super Egg-O-Matic come sua ultima invenzione.",al={"chi ha creato egg-o-matic","creatore egg-o-matic","invenzione curgle criccaleva"}},{q="Di cosa ha bisogno la macchina per funzionare?",a="Per funzionare, la macchina ha bisogno che vi venga inserito un uovo di ippogrifo.",al={"cosa dare alla egg-o-matic","oggetto richiesto egg-o-matic","macchina uova di ippogrifo"}},{q="Dove si trovano le uova di ippogrifo?",a="Trovi uova di ippogrifo sulle montagne del sud di Feralas, attorno alle Rovine di Isildien.",al={"posizione uova di ippogrifo","dove trovare uova di ippogrifo","dove sono le uova a feralas"}}},fp="21,114,30.175.0,21.210.1,32.70.0,38.49.0,34.92.0"}
P.entries["quest:2742"] = {n="Rin'ji is Trapped!",s="Al Padiglione Quel'Danil, Rin'ji ha perso un'ascia ed è prigioniero. Rin'ji chiede a un passante di aiutarlo a fuggire, offre qualcosa in cambio e parla di un segreto alle Scogliere dell'Osservatorio.",h="Al Padiglione Quel'Danil, Rin'ji ha perso un'ascia ed è prigioniero.",kw={"prigioniero","scorta","entroterre","scogliere dell'osservatorio","quel'danil","rin'ji","tavoletta"},sec={{t="Una richiesta di fuga",b="Al Padiglione Quel'Danil, Rin'ji è spaventato e prigioniero. L'ascia è sparita, così Rin'ji implora un passante di aiutarlo a fuggire. A molti non piace la gente di Rin'ji. Eppure, Rin'ji offre qualcosa a un'anima gentile che lo aiuti e dice che un segreto è nascosto alle Scogliere dell'Osservatorio."},{t="Alla fine della fuga",b="Una tavoletta troll reca strani segni. Nessuno riesce a capire cosa dica la scritta."}},faq={{q="Chi è Rin'ji?",a="Rin'ji è un troll che ha perso un'ascia ed è stato catturato al Padiglione Quel'Danil, negli Entroterre. Rin'ji parla di sé in terza persona e implora un passante di aiutarlo a fuggire.",al={"rinji","chi è il troll al quel'danil","chi è rin'ji"}},{q="Dov'è tenuto prigioniero Rin'ji?",a="Rin'ji è prigioniero al Padiglione Quel'Danil, negli Entroterre.",al={"dov'è rin'ji","posizione rinji","gabbia di quel'danil"}},{q="Cosa offre Rin'ji in cambio di aiuto?",a="Rin'ji offre qualcosa a chi lo aiuta e dice che un segreto è nascosto alle Scogliere dell'Osservatorio.",al={"qual è il segreto di rin'ji","ricompensa rinji","cosa si trova alle scogliere dell'osservatorio"}}},fp="18,182,17.257.0,24.81.1,14.176.0,29.62.0,32.93.0"}
P.entries["quest:2745"] = {n="Infiltrating the Castle",s="Al Forte di Roccavento, Elling Trias ti manda a incontrare il suo collega operativo Tyrion. Da settimane Tyrion sorveglia Lord Gregor Lescovar dai giardini reali.",h="Al Forte di Roccavento, Elling Trias ti manda a incontrare il suo collega operativo Tyrion.",kw={"formaggeria","defias","elling trias","infiltrating the castle","lescovar","forte di roccavento","tyrion"},ang={["class:Rogue"]="Da ladro, aiuti due esperti agenti clandestini a infiltrarsi nel centro del potere nobiliare umano. Il loro lavoro mostra l'abilità discreta e letale necessaria per proteggere Roccavento dalle minacce all'interno della sua stessa corte.",["faction:Alliance"]="Con Re Varian scomparso, il regno non può permettersi tradimenti nella più alta camera legislativa del Forte. Come membro dell'Alleanza, aiuti a smascherare i cospiratori e a mantenere stabile il regno.",["race:Gnome"]="Da gnomo, vedi Tyrion svolgere una sorveglianza segreta di lungo periodo all'interno del Forte di Roccavento. Il suo lavoro dimostra che l'ingegno gnomesco è utile tanto nello spionaggio quanto nella meccanica."},sec={{t="Una questione fuori dalla legge",b="Nella sua formaggeria del Distretto Commerciale, Elling Trias vede la minaccia della Fratellanza dei Defias insinuarsi fino al governo del regno. La legge ordinaria non può smascherare o punire un nobile tanto protetto e radicato quanto Lord Gregor Lescovar. Così Trias ti propone una via pericolosa: fare giustizia dentro il Forte di Roccavento, al di fuori della legge, e spezzare la cospirazione una volta per tutte."},{t="Occhi tra gli arbusti",b="Elling Trias ha un operativo nelle alte sale: Tyrion, un astuto gnomo esperto nell'occultamento. Da settimane Tyrion sorveglia i cortili e i giardini reali del forte. Ha seguito gli spostamenti di Lescovar, chi entra nelle sue stanze e quando il traditore incontra i contatti segreti dei Defias. Devi raggiungere Tyrion senza destare i sospetti della Guardia Reale."},{t="Tradimento a corte",b="L'alleanza di Lord Lescovar con l'assassino dei Defias Marzon la Lama Silenziosa mostra quanto sia corrotta la corte di Roccavento mentre Re Varian Wrynn è assente. I nobili tramano all'interno del regno, mentre i fuorilegge premono sui suoi confini dalle Marche Occidentali e dalle Montagne Crestarossa. Colpire Lescovar è un tentativo di estirpare la corruzione prima che il regno crolli."}},faq={{q="Perché Elling Trias vuole che questa faccenda venga gestita fuori dalla legge?",a="Lord Lescovar esercita grande influenza e possiede immense ricchezze nella House of Nobles. Senza prove inconfutabili, accusare un lord di alto rango potrebbe provocare un disastro politico, portare alla soppressione delle prove e far giustiziare chi denuncia i fatti. Trias crede che un'azione segreta e diretta sia l'unico modo affidabile per fermare la minaccia.",al={"perché fuori dalla legge","trias giustizia illegale","perché vigilante"}},{q="Dove si nasconde Tyrion?",a="Tyrion si nasconde nei giardini reali del Forte di Roccavento, appena oltre il cortile sulla sinistra, dopo aver superato il portone principale. Nascosto tra i cespugli, sorveglia gli alloggi di Lord Lescovar senza allertare le guardie.",al={"dove si trova tyrion","trova tyrion","posizione di tyrion"}},{q="Chi è Tyrion?",a="Tyrion è un agente segreto e un fidato collaboratore di Elling Trias. Da diverse settimane sorveglia il Forte di Roccavento per seguire Lord Gregor Lescovar e ricostruire i suoi legami segreti con i Defias.",al={"chi è tyrion","tyrion gnomo","amico di trias"}},{q="Chi è Lord Lescovar?",a="Lord Gregor Lescovar è un nobile influente di Roccavento che lavora in segreto con la Fratellanza dei Defias come infiltrato nella corte reale. Li aiuta a sabotare il regno dall'interno.",al={"lord lescovar","chi è lescovar","lescovar defias"}},{q="Chi è Marzon?",a="Marzon, detto la Lama Silenziosa, è un assassino d'élite dei Defias. Collabora direttamente con Lord Lescovar per coordinare gli attacchi e gli assassinii della Fratellanza.",al={"marzon","marzon la lama silenziosa","lama silenziosa"}},{q="Perché Tyrion è preoccupato per la sua reputazione?",a="Tyrion teme che tu possa compromettere la sua copertura durante la sorveglianza segreta. Si lamenta anche che avventurieri armati fino ai denti, appostati accanto a lui tra i cespugli reali sotto gli occhi delle guardie del castello, diano nell'occhio e siano sconvenienti.",al={"tyrion nascondiglio cespugli","reputazione tra i cespugli"}}},fx={ae2213ef={q="Chi devi affrontare nel Castello di Roccavento?",a="Elling Trias ti manda a occuparti di Lord Gregor Lescovar e del suo associato Marzon. Lescovar è un nobile che agisce proprio all'interno del Forte di Roccavento, sospettato di avere legami traditori, mentre Marzon è uno dei pericolosi cospiratori che operano fuori dalle mura del castello. Trias e il suo contatto Tyrion vogliono neutralizzare entrambi prima che i loro complotti possano minacciare il regno.",al={"chi dobbiamo colpire","chi è il bersaglio in infiltrating the castle","chi sono lescovar e marzon"}},["7d59c2b3"]={q="Perché Elling Trias manda te invece di rivolgersi alle guardie cittadine di Roccavento?",a="Lord Lescovar è un nobile di alto rango nel Forte di Roccavento, quindi un'accusa ufficiale sarebbe politicamente impossibile senza prove inconfutabili. Le guardie cittadine rispondono alla corte, dove la nobiltà esercita la propria influenza, e avvertire i canali ufficiali probabilmente metterebbe Lescovar in guardia o seppellirebbe la faccenda nella burocrazia. Trias si affida a un avventuriero indipendente che possa infiltrarsi, incontrare Tyrion e amministrare una giustizia risoluta senza mettere in allarme i cospiratori.",al={"perché mandare me","perché non avvertire le guardie","perché non le guardie di roccavento"}}},fp="23,152,24.337.0,21.349.0,20.354.1,56.312.0,23.203.0,14.185.0,21.183.0,14.162.1,43.223.0"}
P.entries["quest:2746"] = {n="Items of Some Consequence",s="Tyrion ha bisogno di seta e mele per preparare Spybot a infiltrarsi di nascosto da Lord Lescovar nel Forte di Roccavento. La spia meccanica deve superare le guardie reali e ascoltare il nobile.",h="Tyrion ha bisogno di seta e mele per preparare Spybot a infiltrarsi di nascosto da Lord Lescovar nel Forte di...",kw={"clara","elling trias","infiltrating the castle","lord lescovar","stoffa di seta","spybot","forte di roccavento","the attack","tyrion"},ang={["class:Rogue"]="Da Ladro, puoi vedere come operativi come Tyrion ed Elling Trias ricorrano a una sorveglianza anticonvenzionale, mentre conducono attività d'intelligence sotto il naso dei nobili.",["faction:Alliance"]="Come membro dell'Alleanza, aiuti a proteggere il giovane re Anduin e il Gran Signore Bolvar Domadraghi smascherando gli aristocratici corrotti che cospirano con i fuorilegge nel Forte di Roccavento.",["profession:Tailoring"]="Da Sarto, sai che la seta pregiata può aiutare le cospirazioni segrete oltre che servire a confezionare abiti da cerimonia."},sec={{t="Un programma serrato",b="Elling Trias, il mercante di formaggi, ha anticipato l'operazione contro Lord Gregor Lescovar. Sospetta che i piani di Lescovar nel Forte di Roccavento minaccino il regno. Tyrion accetta di stringere i tempi nei giardini del forte, ma il travestimento di Spybot richiede un'attenta preparazione."},{t="L'arte del travestimento",b="Tyrion intende mandare Spybot, un piccolo marchingegno meccanico, oltre le guardie del castello per raggiungere Lescovar nel forte. Il suo bizzarro travestimento da donna dovrebbe sviare i sospetti. Raccogli mele della misura giusta nel frutteto di Clara, appena fuori dalle mura cittadine, e rotoli di seta per gli abiti del fantoccio."},{t="Svelare il tradimento",b="Tyrion ha iniziato a sorvegliare Lord Lescovar dopo aver seguito indizi sospetti che collegavano il nobile al culto del Martello del Crepuscolo. Ora rivela che Lescovar collabora anche con i cospiratori della Fratellanza dei Defias. Smascherato il tradimento, Lescovar non può più restare alla corte reale. La sorveglianza di Tyrion diventa un'operazione sotto copertura nel cuore del regno."}},faq={{q="Perché Tyrion ha bisogno di mele e stoffa di seta?",a="Tyrion ha bisogno di mele e seta per travestire Spybot da donna e farlo passare oltre le guardie reali del Forte di Roccavento. La seta diventa un vestito, mentre le mele danno forma al travestimento.",al={"perché le mele","a cosa servono le mele","materiali travestimento tyrion","travestimento spybot"}},{q="Per chi lavora Tyrion?",a="Tyrion lavora con Elling Trias, un mercante di formaggi del Distretto Commerciale che gestisce una propria rete di conoscenze a Roccavento. Trias dice che l'operazione fa solo indirettamente un favore a Mathias Shaw e SI:7.",al={"a chi risponde tyrion","lealtà di tyrion","elling trias tyrion"}},{q="Dove trovo le mele di Clara?",a="Il frutteto di Clara si trova appena fuori dalle porte cittadine di Roccavento, nella parte settentrionale della Foresta di Elwynn. Puoi raccogliere mele fresche nei dintorni della fattoria.",al={"posizione fattoria clara","dove sono le mele di clara","mele fresche roccavento"}},{q="Di cosa sospettava originariamente Tyrion che si occupasse Lord Lescovar?",a="Tyrion e Trias sospettavano inizialmente che Lord Lescovar avesse legami con il culto del Martello del Crepuscolo. In seguito hanno scoperto la sua collaborazione con la Fratellanza dei Defias, un tradimento più grave e una minaccia imminente per la corona.",al={"lescovar martello del crepuscolo","perché lescovar è stato indagato","storia tyrion lescovar"}},{q="Qual è il prossimo passo dopo aver consegnato questi oggetti?",a="Dopo aver equipaggiato Spybot e averlo mandato nel forte, ti viene chiesto di affrontare ed eliminare i cospiratori in «L'attacco!».",al={"cosa succede dopo","dopo items of some consequence","prossima missione dopo items of some consequence"}},{q="Perché usare uno spybot meccanico invece di intrufolarsi di persona?",a="Le sentinelle reali del Forte di Roccavento controllano attentamente chiunque entri nella sala del trono e nei cortili privati. Travestito da sacerdotessa, Spybot può passare, parlare con Lescovar e attirarlo in giardino per incontrare Marzon, dove nessun agente conosciuto potrebbe avvicinarsi.",al={"perché usare spybot","perché non intrufolarsi di persona","sicurezza forte di roccavento"}}},fx={["7ec9a91a"]={q="Perché Tyrion vuole abbattere Lord Lescovar?",a="Tyrion e il suo associato Elling Trias seguono da settimane Lord Lescovar, sospettato di avere legami sovversivi. Inizialmente indagavano su un possibile coinvolgimento di cultisti con il Martello del Crepuscolo, ma scoprire che Lescovar sta cospirando attivamente con la Fratellanza dei Defias lo rende una minaccia immediata e grave per Roccavento. Tyrion intende smascherarlo e neutralizzarlo prima che il suo tradimento possa dilaniare la città.",al={"perché fermare lescovar","motivo di tyrion","perché indagare su lescovar"}},["73f45f0b"]={q="Perché Tyrion ha bisogno dell'aiuto di un estraneo invece di rivolgersi alle guardie cittadine?",a="Lord Lescovar è un nobile che si trova nel Forte di Roccavento, quindi un'accusa aperta o un intervento diretto delle guardie sono impossibili senza prove inconfutabili. Le autorità di Roccavento non possono agire sulla base di semplici sospetti contro un nobile di alto rango. Tyrion opera nell'ombra per conto di Master Trias e ha bisogno di un agente indipendente disposto a procurarsi rifornimenti clandestini e, infine, ad affrontare di persona il pericoloso confronto segreto.",al={"perché non le guardie cittadine","perché tyrion ha bisogno di me","perché affidarsi a un avventuriero"}}},fp="25,175,21.275.0,23.313.0,18.324.1,43.180.0,26.195.0,31.126.0,58.208.1,51.132.1,62.252.0"}
P.entries["quest:2747"] = {n="An Extraordinary Egg",s="A Tanaris, Curgle Criccaleva cerca un uovo straordinario proveniente da Feralas.",h="A Tanaris, Curgle Criccaleva cerca un uovo straordinario proveniente da Feralas.",kw={"curgle criccaleva","uovo straordinario","feralas","the super egg-o-matic","tanaris"},sec={{t="Una rarità da Feralas",b="Curgle Criccaleva dice che poche uova provenienti da Feralas arrivano in forma straordinaria. Uova simili sono le più rare di tutte. È proprio un uovo così che cerca Curgle."}},faq={{q="Chi sta cercando un uovo straordinario?",a="Curgle Criccaleva, inventore di Super Egg-O-Matic, cerca un uovo straordinario.",al={"chi inizia an extraordinary egg","chi dà la missione an extraordinary egg","curgle criccaleva uovo"}},{q="Da dove provengono queste uova straordinarie?",a="Queste uova straordinarie provengono da Feralas, anche se poche arrivano in forma straordinaria.",al={"posizione extraordinary egg","dove trovare extraordinary egg","uovo da feralas"}},{q="Cosa precede questa richiesta?",a="Questa richiesta fa seguito a Super Egg-O-Matic.",al={"prerequisito per an extraordinary egg","catena an extraordinary egg","missione precedente per an extraordinary egg"}}},fp="20,70,21.134.0,40.81.0,44.85.0,31.43.0"}
P.entries["quest:2748"] = {n="A Fine Egg",s="Curgle Criccaleva parla di un uovo che potrebbe schiudersi libero dagli incantesimi malvagi degli ogre Gordunni.",h="Curgle Criccaleva parla di un uovo che potrebbe schiudersi libero dagli incantesimi malvagi degli ogre...",kw={"curgle criccaleva","darnassus","uovo buono","gordunni","incantesimi ogre","the super egg-o-matic","tanaris"},sec={{t="Cosa lo rende buono",b="Curgle Criccaleva dice che un uovo ha buone probabilità di schiudersi senza essere intaccato dai canti malvagi degli ogre Gordunni, se le condizioni sono ideali."},{t="Cosa farà Curgle in seguito",b="Curgle prende l'uovo e progetta di mandarlo a Darnassus. Lì, si spera che si schiuda presto."}},faq={{q="Cosa rende un uovo un Uovo Buono?",a="In condizioni ideali, un uovo può schiudersi libero dal male portato dagli incantesimi degli ogre Gordunni.",al={"cos'è un uovo buono","lore uovo buono","perché uovo buono"}},{q="Cosa precede questa fase?",a="The Super Egg-O-Matic è venuto prima di questo passaggio.",al={"prerequisito uovo buono","missione precedente uovo buono"}}},fp="10,98,18.136.0,21.89.1,40.96.0,27.44.0"}
P.entries["quest:2749"] = {n="An Ordinary Egg",s="Curgle Criccaleva si occupa delle comuni uova di ippogrifo, anche se se ne schiude solo circa la metà.",h="Curgle Criccaleva si occupa delle comuni uova di ippogrifo, anche se se ne schiude solo circa la metà.",kw={"curgle criccaleva","feralas","ippogrifo","uovo comune","tanaris","the super egg-o-matic"},sec={{t="Una possibilità su due",b="Solo circa la metà delle comuni uova di ippogrifo si schiude. Curgle Criccaleva fa del suo meglio per accudire ogni uovo, sperando che la fortuna lo faccia schiudere."}},faq={{q="Chi è Curgle Criccaleva?",a="Curgle Criccaleva ha inventato il Super Egg-O-Matic e lavora con uova di ippogrifo provenienti da Feralas.",al={"chi è curgle","curgle criccaleva"}},{q="Cosa succede all'uovo comune di ippogrifo?",a="Curgle si occupa del comune uovo di ippogrifo e spera nella fortuna. Solo circa la metà di queste uova si schiude.",al={"cosa fa curgle con l'uovo","probabilità di schiusa dell'uovo"}},{q="Da dove provengono queste uova?",a="Le uova provengono da Feralas.",al={"dove trovo l'uovo","posizione dell'uovo comune"}},{q="Cosa precede questa fase?",a="Il passaggio precedente è il Super Egg-O-Matic.",al={"missione prerequisito","qual è la missione precedente"}}},fp="15,79,13.136.0,25.93.0,44.96.0,30.27.0,27.50.0"}
P.entries["quest:275"] = {n="Blisters on The Land",s="Nella parte orientale delle Paludi Grigie, Rethiel percepisce una malattia diffondersi nella palude. Il guardiano delle bestie di torba chiede ai viaggiatori di distruggere i Fen Creepers, sperando di placare la febbre crescente della terra.",h="Nella parte orientale delle Paludi Grigie, Rethiel percepisce una malattia diffondersi nella palude.",kw={"blisters on the land","fen creepers","guardiaverde","paludi","rethiel","torbiere delle paludi","paludi grigie"},ang={["class:Druid"]="Il lavoro di Rethiel riflette il dovere di un druido: guarire il mondo naturale e placare le piaghe elementali agitate, affinché la terra possa ritrovare l'equilibrio.",["class:Shaman"]="I Fen Creepers contorcono terra e acqua, perciò distruggerli aiuta a placare gli spiriti elementali discordanti.",["race:NightElf"]="Come Elfo della Notte, potresti trovare un solitario guardiano delle bestie di torba alleato di Roccavento nei Regni Orientali. Persino gli spiriti della terra cercano aiuto per guarire la terra ferita."},sec={{t="Paludi in decomposizione",b="Rethiel il Guardiaverde veglia sulle Paludi Grigie da una selva tra le paludi. La torbiera è sempre stata inospitale, ma ora una malattia innaturale si diffonde al suo interno. Rethiel sente la febbre nella terra. Questa contorce la natura selvaggia, trasformandola in orrori barcollanti e privi di mente."},{t="Purificare la palude",b="I Fen Creepers sono masse in decomposizione di piante palustri che vagano per i corsi d'acqua. Rethiel li chiama vesciche malate che si gonfiano sulla terra. La loro presenza tormentata agita la palude, perciò Rethiel chiede agli alleati di passaggio di distruggerli. I loro resti aggrovigliati potranno così depositarsi nel fango."}},faq={{q="Chi è Rethiel il Guardiaverde?",a="Rethiel il Guardiaverde è una bestia delle torbiere che vive nella Selva di Guardiaverde, nella parte orientale delle Paludi Grigie. Rethiel si prende cura dell'equilibrio naturale della palude e cerca di alleviarne i mali e contenere la crescita elementale corrotta.",al={"chi è rethiel","lore di rethiel guardiaverde","chi assegna blisters on the land"}},{q="Cosa sono i Fen Creepers?",a="I Fen Creepers sono elementali ostili di piante e paludi che vagano per i corsi d'acqua delle Paludi Grigie. Sono enormi masse animate di rampicanti, fango e piante palustri in decomposizione che avanzano barcollando.",al={"fen creepers","cos'è un fen creeper","fen creepers paludi grigie"}},{q="Perché Rethiel vuole che i Fen Creepers vengano distrutti?",a="Rethiel considera i Fen Creepers segni febbrili della malattia crescente della palude. Crede che distruggerli permetta alle loro forme di dissolversi nella terra e plachi la terra agitata.",al={"perché uccidere i fen creepers","perché blisters on the land"}},{q="Cosa causa il marciume nelle Paludi Grigie?",a="Rethiel non sa cosa causi il marciume nelle Paludi Grigie. Percepisce il malessere della terra e placa il tumulto elementale ovunque si manifesti.",al={"perché le paludi grigie sono malate","causa della malattia delle paludi"}},{q="Dove si trovano i Fen Creepers nelle Paludi Grigie?",a="I Fen Creepers vagano per i corsi d'acqua umidi, le rive fangose e i canali centrali delle Paludi Grigie, soprattutto vicino alle paludi più profonde a ovest della Selva di Guardiaverde.",al={"posizioni dei fen creepers","dove trovare i fen creepers"}},{q="Questa missione si collega ad altri compiti per Rethiel?",a="Sì. La preoccupazione di Rethiel per gli gnoll Mosshide che bruciano gli alberi delle Paludi Grigie ha portato a Fire Taboo. Rethiel continua a impegnarsi per proteggere l'equilibrio della palude.",al={"serie di missioni del guardiaverde","missioni di rethiel"}}},fp="20,184,19.253.0,17.279.0,31.211.0,22.169.0,49.184.0,42.149.0,45.143.0,51.148.0"}
P.entries["quest:2750"] = {n="A Bad Egg",s="Curgle Criccaleva interviene quando un uovo di ippogrifo non può essere salvato.",h="Curgle Criccaleva interviene quando un uovo di ippogrifo non può essere salvato.",kw={"uovo scaduto","curgle criccaleva","feralas","super egg-o-matic","tanaris"},sec={{t="Un uovo irrecuperabile",b="Alcune uova di ippogrifo non possono essere salvate. Curgle Criccaleva si occupa di quelle che non si schiuderanno mai."},{t="Cosa ne diventa",b="Curgle porta via l'uovo per smaltirlo correttamente. Dice che non tutte le uova possono essere salvate. Puoi riprovare con un altro uovo di Feralas."}},faq={{q="Chi accetta l'uovo scaduto?",a="Curgle Criccaleva accetta l'Uovo Scaduto.",al={"a chi do l'uovo scaduto","curgle criccaleva uovo","chi prende l'uovo scaduto"}},{q="L'uovo può essere salvato?",a="No. Un Uovo Scaduto non può essere salvato e non si schiuderà mai.",al={"l'uovo scaduto si può schiudere","l'uovo scaduto si schiuderà","salvare uovo scaduto"}},{q="Cosa c'è prima di questo?",a="Segue The Super Egg-O-Matic.",al={"missione precedente","prerequisito","prerequisito uovo scaduto"}}},fp="9,69,20.92.0,18.136.1,24.38.0,21.51.0,22.33.0"}
P.entries["quest:2751"] = {n="Bastioni barbarici",s="A Orgrimmar, Orokk Omosh cerca un apprendista a cui tramandare l’arte della forgia della sua famiglia. Senza eredi, chiede a un fabbro promettente di dimostrare di avere una mano sicura con il bronzo prima di condividere le sue conoscenze.",h="A Orgrimmar, Orokk Omosh cerca un apprendista a cui tramandare l’arte della forgia della sua famiglia.",kw={"barbaric battlements","fabbro","bronzo","eredità","omosh","orgrimmar","orokk omosh"},ang={["faction:Horde"]="Come membro dell’Orda, condividi la convinzione degli Omosh che la lavorazione dei metalli vada messa alla prova in combattimento e macchiata del sangue dei nemici.",["profession:Blacksmithing"]="Come fabbro dell’Orda, raggiungi una tappa importante nel percorso che ti porta dalle lavorazioni di base in bronzo e rame alle tradizioni più avanzate nella creazione di armature."},sec={{t="La fine della stirpe Omosh",b="Orokk Omosh lavora alle incudini di Orgrimmar, gravato dal peso del passato della sua famiglia. Per venti generazioni, la stirpe degli Omosh ha trasformato il minerale in armi e armature per l’Orda. Orokk non ha parenti e non può avere figli, perciò si considera un fallimento per la sua stirpe. Con l’arte di famiglia a rischio, mette da parte l’orgoglio del lignaggio e cerca un apprendista che porti avanti le tradizioni della forgia."},{t="Una prova di metallo e zanne",b="Orokk non condividerà i suoi segreti con un fabbro che non ha ancora dimostrato il proprio valore. Chiede due bracciali di bronzo decorati, due spadoni di bronzo e due artigli affilati di bestia come prova di abilità all’incudine. Per lui, la forgiatura non è un lusso ozioso. Il suo più grande onore è un’armatura e dell’acciaio macchiati dal sangue dei nemici. Soddisfa le sue richieste e potrebbe convincersi che un apprendista sappia mantenere viva l’eredità degli Omosh e meritare la possibilità di approfondire l’arte."}},faq={{q="Chi è Orokk Omosh?",a="Orokk Omosh è un maestro fabbro di Orgrimmar e appartiene alla ventesima generazione della stirpe degli Omosh. Senza parenti né eredi, cerca qualcuno al di fuori del clan che mantenga vive le conoscenze di forgiatura della famiglia.",al={"orokk omosh","chi è orokk","fabbro omosh"}},{q="Perché Orokk ha bisogno di qualcun altro a cui insegnare?",a="Orokk non ha parenti in vita e non può avere figli. Ha bisogno di un apprendista che erediti i progetti e le tecniche della sua officina, altrimenti venti generazioni di conoscenze sulla forgiatura finiranno con lui.",al={"perché apprendista","erede orokk","perché l'eredità omosh sta svanendo"}},{q="Quali oggetti sono richiesti per dimostrare la competenza a Orokk?",a="Orokk chiede due bracciali di bronzo decorati, due spadoni di bronzo e due artigli affilati strappati a feroci bestie predatrici.",al={"cosa mi serve per barbaric battlements","oggetti per barbaric battlements","consegna barbaric battlements"}},{q="Cosa succede dopo aver completato Barbaric Battlements?",a="Dopo aver dimostrato la tua abilità di base con il bronzo, Orokk prosegue il tuo addestramento con On Iron Pauldrons. Lì passerai alla forgiatura del ferro più pesante e alle complesse armature a piastre.",al={"prossima missione","catena dopo barbaric battlements","cosa segue"}}},fx={["2a7cea14"]={q="Perché Orokk ha bisogno dei Bracciali di Bronzo Decorati, degli Spadoni di Bronzo e degli Artigli Affilati?",a="Orokk Omosh cerca un apprendista degno di portare avanti la sacra tradizione di famiglia nella forgiatura. Invece di mettere le armi al servizio di qualcuno, pretende i Bracciali di Bronzo Decorati, gli Spadoni di Bronzo e gli Artigli Affilati come prova di abilità. Portargli questi manufatti di bronzo finemente lavorati, insieme ai trofei grezzi delle bestie, dimostra che possiedi la disciplina, la perizia tecnica e la forza rude necessarie per apprendere le ricette segrete del clan Omosh.",al={"a cosa servono gli oggetti","perché i bracciali di bronzo decorati","perché gli spadoni di bronzo e gli artigli affilati"}}},fp="20,185,25.390.0,25.413.0,19.183.0,42.191.0,53.124.0,49.167.0"}
P.entries["quest:2753"] = {n="Schiacciati come insetti",s="Nella Valle dell'Onore di Orgrimmar, Orokk Omosh mette alla prova i fabbri con lavori duri. L'armatura di ferro verde ne misura la resistenza e insegna a forgiare pesanti stivali di ferro, mentre le tecniche della stirpe Omosh sono in gioco.",h="Nella Valle dell'Onore di Orgrimmar, Orokk Omosh mette alla prova i fabbri con lavori duri.",kw={"armaiolo","fabbro","gorokk","ferro verde","orgrimmar","orokk omosh","trampled under foot","valle dell'onore"},ang={["faction:Horde"]="Le lezioni di Orokk insegnano modelli di armature di ferro resistenti, pensate per i brutali combattimenti prediletti sui fronti di guerra dell'Orda.",["profession:Blacksmithing"]="Per un armaiolo dell'Orda, questa prova segna un passo importante. Richiede di fondere molto ferro e preparare tintura verde per ottenere i progetti esclusivi degli stivali."},sec={{t="Le Prove di Omosh",b="Orokk Omosh addestra gli armaioli a Orgrimmar con prove di duro lavoro fisico. Per lui, lavorare il metallo è più che scaldare il minerale e dargli forma. È un omaggio al suo clan ancestrale e mette alla prova la resistenza del fabbro. Questa è la terza prova della sua serie, e forgiare più volte armature di ferro verde temprato sviluppa muscoli e disciplina."},{t="L'Eredità del Capo Gorokk",b="I fabbri che portano a Orokk l'equipaggiamento di ferro verde richiesto ricevono rari elogi dal brusco armaiolo. Paragona l'artigiano che resiste al lavoro a suo nonno, il Capo Gorokk degli Omosh. Per l'armatura, Orokk insegna il disegno ancestrale di robusti stivali di ferro. I guerrieri dell'Orda li indossano per schiacciare i nemici sotto i talloni."}},faq={{q="Chi offre la missione Trampled Under Foot?",a="Orokk Omosh, armaiolo orco nella Valle dell'Onore di Orgrimmar, propone la prova.",al={"datore di missione","chi assegna trampled under foot","posizione di orokk omosh"}},{q="Cosa richiede Orokk Omosh per questa prova?",a="Orokk richiede quattro Green Iron Helms, quattro Bracciali di Ferro Verdi e due Gambiere di Ferro Verdi. Questi pezzi mettono alla prova e dimostrano la maestria del fabbro nella lavorazione del ferro verde.",al={"consegna di trampled under foot","oggetti necessari","materiali necessari"}},{q="Qual è la storia dietro la catena di addestramento Omosh?",a="Orokk Omosh sottopone i giovani fabbri a un duro lavoro fisico per onorare l'eredità marziale dei suoi antenati. Crede che forgiare armature con fatica sviluppi la forza necessaria a creare equipaggiamento capace di resistere a guerre brutali.",al={"perché orokk fa forgiare armature","storia del clan omosh"}},{q="Chi è il Capo Gorokk degli Omosh?",a="Il Capo Gorokk degli Omosh è il nonno di Orokk Omosh. Orokk onora la prodezza marziale di suo nonno e paragona i fabbri che resistono alle sue dure prove di lavorazione del ferro al capo tribù.",al={"capo gorokk","nonno di orokk"}},{q="Quale missione precede Trampled Under Foot?",a="On Iron Pauldrons precede questa prova nella serie di sfide di forgiatura di armature di Orokk.",al={"missione prerequisito","missione precedente nella catena"}},{q="Qual è la missione successiva dopo aver completato Trampled Under Foot?",a="Dopo questa prova, Orokk Omosh propone Horns of Frenzy. Joys of Omosh conclude la serie dopo le due lezioni rimanenti.",al={"prossima missione","cosa viene dopo trampled under foot"}}},fx={["454b7030"]={q="Perché Orokk Omosh vuole che tu forgi questi pezzi di ferro verde?",a="Orokk Omosh ti sta addestrando nelle brutali tradizioni di forgiatura della sua stirpe. Crede che i veri guerrieri e fabbri debbano sopportare fatiche estenuanti per forgiare equipaggiamento degno del nome Omosh. Facendoti forgiare diversi elmi, bracciali e schinieri con pesante ferro verde, mette alla prova sia la tua resistenza fisica sia la tua abilità, preparandoti a scoprire i segreti per forgiare stivali temprati per la battaglia.",al={"motivo di orokk omosh","perché forgiare ferro verde","perché orokk vuole questo"}},["9ced7653"]={q="A cosa serve l'Elmo di Ferro Verde?",a="Gli Elmi di Ferro Verde sono una parte della dura prova di abilità e resistenza imposta da Orokk. Fusi e martellati di tua mano, dimostrano al fabbro che possiedi la precisione metallurgica e la resistenza fisica necessarie per creare pesanti protezioni da battaglia secondo la tradizione degli Omosh.",al={"a cosa serve l'elmo di ferro verde","perché l'elmo di ferro verde","uso dell'elmo di ferro verde"}},ae72eea8={q="A cosa servono i Bracciali di Ferro Verdi?",a="Questi bracciali dimostrano che sai forgiare robuste e affidabili protezioni per gli arti sotto la guida inflessibile di Orokk Omosh. Consegnargli quattro paia realizzate a regola d'arte prova che le tue abilità di forgiatura sono sufficienti a equipaggiare con costanza i guerrieri per le dure battaglie che li attendono.",al={"a cosa servono i bracciali di ferro verdi","perché i bracciali di ferro verdi","uso dei bracciali di ferro verdi"}},["9872ef5a"]={q="A cosa servono le Gambiere di Ferro Verdi?",a="Le gambiere richiedono grandi quantità di ferro lavorato e una forgiatura disciplinata. Fornirne due paia ben realizzate dimostra a Orokk che meriti di ereditare i segreti per creare potenti stivali corazzati, seguendo le orme del suo antenato, il Capo Gorokk.",al={"a cosa servono le gambiere di ferro verdi","perché le gambiere di ferro verdi","uso delle gambiere di ferro verdi"}},f314d286={q="Perché Orokk Omosh ha bisogno di te invece di occuparsi lui stesso della forgiatura?",a="Orokk non cerca qualcuno che gli consegni un'armatura; sta mettendo alla prova e istruendo te. In quanto maestro delle antiche tecniche del suo clan, pretende che siano i tuoi muscoli a dolerti davanti all'incudine, così da dimostrare la tua dedizione prima di condividere i modelli degli Omosh.",al={"perché proprio io per orokk","perché orokk ha bisogno di me","perché non li forgia lui"}}},fp="19,226,19.322.0,22.324.0,41.80.0,45.164.0,49.208.0,29.173.0,40.88.0,60.116.0"}
P.entries["quest:2755"] = {n="La gioia degli Omosh",s="Dopo averti ricevuto grande aiuto, Orokk Omosh condivide una tradizione di famiglia a Orgrimmar. Il fabbro veterano si asciuga le lacrime, dando la colpa alla fuliggine, poi danza dalla gioia per tramandare un’insolita eredità familiare.",h="Dopo averti ricevuto grande aiuto, Orokk Omosh condivide una tradizione di famiglia a Orgrimmar.",kw={"fabbro","ballo della gioia","le gioie di omosh","orgrimmar","orokk omosh","fuliggine nell'occhio","valle dell'onore"},ang={["faction:Horde"]="Nella Valle dell’Onore di Orgrimmar, l’orgoglio marziale incontra la gioia commossa e il vivace ballo di Orokk Omosh, tra il clangore dell’acciaio.",["profession:Blacksmithing"]="Per un fabbro, il sentimentale ballo di famiglia di Orokk Omosh offre uno sguardo tenero e divertente sulla vita di un artigiano veterano oltre la fucina."},sec={{t="Una lacrima sporca di fuliggine",b="Alla fucina di Orgrimmar, Orokk Omosh è noto per i pesanti colpi di martello, non per le lacrime. Il tuo grande aiuto ha toccato profondamente il robusto fabbro. Eppure, ostinatamente, dà la colpa a un granello di fuliggine nell’occhio invece di ammettere che sta piangendo."},{t="La tradizione di Omosh",b="Prima di congedarti, Orokk Omosh dice che deve condividere un ultimo segreto di famiglia. Esegue per il suo apprendista il vigoroso ed estenuante ballo della gioia di Omosh. Poi gli insegna a colpire con un pugno di ferro."}},faq={{q="Chi è Orokk Omosh?",a="Orokk Omosh è un fabbro orco nella Valle dell’Onore di Orgrimmar. È fieramente orgoglioso dell’arte e del lignaggio della sua famiglia, e accanto al suo lavoro alla fucina ne custodisce le vivaci tradizioni.",al={"chi è orokk","retroscena di orokk omosh","orokk fabbro"}},{q="Perché Orokk piange?",a="Orokk Omosh dà la colpa alla fuliggine della fucina che gli è finita nell’occhio, ma il tuo aiuto lo ha profondamente commosso. Ha trovato qualcuno degno di condividere le tradizioni della sua famiglia.",al={"perché orokk piange","orokk è triste","fuliggine nell'occhio"}},{q="Cos'è il ballo della gioia di Omosh?",a="Il ballo della gioia di Omosh è una vigorosa routine tramandata nella famiglia di Orokk Omosh. Lo lascia sfinito, e non lo pratica da moltissimo tempo.",al={"ballo di omosh","ballo della gioia","cos'è il ballo"}},{q="Dove si svolge questa missione?",a="La storia si svolge a Orgrimmar, alla fucina della Valle dell’Onore dove Orokk Omosh lavora il metallo.",al={"luogo della missione","dove si trovano le gioie di omosh","forgia di orgrimmar"}},{q="Cosa ti insegna Orokk?",a="Orokk Omosh ti insegna il ballo della gioia di Omosh e promette di tramandarti la conoscenza del pugno di ferro, legando fabbro e avventuriero.",al={"ricompensa di omosh","cosa imparo","pugno di ferro"}},{q="I personaggi dell’Alleanza possono partecipare a questa missione?",a="No. Orokk Omosh è alleato con l’Orda e vive entro le mura fortificate di Orgrimmar, quindi solo gli avventurieri dell’Orda possono incontrarlo lì.",al={"gioie di omosh alleanza","è solo per l’orda"}}},fx={["371650ab"]={q="Perché Orokk Omosh vuole insegnarti la danza della gioia?",a="Orokk è colmo di gratitudine per il tuo aiuto e vuole tramandarti l'ultima tradizione, custodita gelosamente, della sua stirpe. Insegnandoti la danza della gioia degli Omosh, sente di onorare la sua eredità e di poter finalmente morire da orco felice.",al={"perché insegnare la danza","motivo di orokk omosh","perché orokk vuole questo"}}},fp="13,195,19.219.0,19.207.0,19.170.0,20.154.0,31.163.0,33.91.0,26.135.0,47.132.0"}
P.entries["quest:276"] = {n="Tramping Paws",s="Nella Selva di Guardiaverde, nelle Paludi Grigie, Rethiel vede crescere i Muschiopelle vicino alla Porta di Algaz. I loro fuochi e il loro calpestio minacciano la palude, così chiede ai viaggiatori di ridurne il numero.",h="Nella Selva di Guardiaverde, nelle Paludi Grigie, Rethiel vede crescere i Muschiopelle vicino alla Porta di...",kw={"algaz","gnoll","guardiaverde","bastardi","muschiopelle","rethiel","tramping paws","paludi grigie"},ang={["class:Druid"]="Come druido, condividi il dovere cenariano di mantenere l’equilibrio della natura. Ridurre un aumento innaturale della popolazione può impedire che la palude collassi.",["race:Dwarf"]="Come nano, sai che gli gnoll sciamano appena fuori dalla Porta di Algaz. Ridurne il numero protegge la palude e mette al sicuro la strada vitale tra Forgiardente e Porto di Menethil.",["race:NightElf"]="Come Elfo della Notte, condividi antichi legami con gli spiriti selvaggi della natura. Aiutare Rethiel a risanare la palude è un dovere familiare e onorato."},sec={{t="Una minaccia crescente nella palude",b="Gli gnoll Muschiopelle hanno vissuto per molti anni nelle Paludi Grigie senza sopraffare l’ordine naturale. Ora il loro numero è aumentato e si sono spinti a sud verso il passo di Dun Algaz. I loro stivali pesanti e le loro zampe schiacciano rare piante palustri, mentre abbattono alberi per alimentare i fuochi degli accampamenti. Se i branchi continueranno a crescere, la fragile palude ne soffrirà."},{t="Il giudizio del Guardiaverde",b="Rethiel il Guardiaverde osserva la palude in cerca di segnali di squilibrio. Il problema non è l’esistenza degli gnoll, ma il fatto che il loro numero superi ciò che le Paludi Grigie possono sostenere. Ridurre gli gnoll Muschiopelle e i bastardi aiuta a preservare la palude e può guadagnare l’approvazione del suo antico guardiano."}},faq={{q="Chi è Rethiel il Guardiaverde?",a="Rethiel è una bestia delle paludi che vive nelle Paludi Grigie, lungo la strada tra i confini di Forgiardente e Arathi. Dedito a preservare la palude, ne osserva la salute e chiede ai viaggiatori di tenere sotto controllo le popolazioni che la danneggiano.",al={"lore di rethiel","chi assegna tramping paws","guardiaverde paludi grigie"}},{q="Perché gli gnoll Muschiopelle sono un problema ora?",a="Un tempo gli gnoll Muschiopelle vivevano accanto alla palude senza arrecarle danni duraturi, ma il recente boom della loro popolazione ha portato a un intenso abbattimento di alberi per la legna da ardere e al calpestio diffuso delle fragili piante palustri.",al={"perché uccidere gnoll nelle paludi","minaccia gnoll muschiopelle"}},{q="Dove stanno causando danni gli gnoll?",a="Gli gnoll Muschiopelle e i bastardi si radunano in gran numero nelle Paludi Grigie meridionali, soprattutto vicino al passo nanico di Dun Algaz.",al={"dove si trovano gli gnoll muschiopelle","posizione di tramping paws"}},{q="Cosa succede dopo aver abbattuto gli gnoll?",a="Dopo aver ridotto i branchi, Rethiel indaga sulle cause della loro attività insolita e del consumo di combustibile, poi manda i viaggiatori al Fire Taboo.",al={"missione successiva a tramping paws","seguito di tramping paws"}},{q="Perché Rethiel parla di aver avuto la propria fiducia messa alla prova?",a="Rethiel dice che in passato la sua fiducia nella tua gente è stata messa a dura prova e continua a diffidare dei mortali e della loro rapida espansione. Aiutare a proteggere la palude selvaggia dimostra che i mortali possono prendersi cura della natura invece di sfruttarla.",al={"dialogo di rethiel","fiducia messa a dura prova in passato"}}},fx={["24db34f0"]={q="Chi sono i gnoll Mosshide che devi andare a cacciare?",a="I Mosshide sono un clan di gnoll originario delle Paludi. Per generazioni hanno vissuto qui in pace, in armonia con la natura, ma ora la loro popolazione in crescita sta spogliando la palude. Le loro pesanti zampe calpestano la delicata flora delle torbiere, mentre le loro asce abbattono troppo legname per cucinare e accendere fuochi da campo, alterando completamente l'equilibrio dell'ecosistema locale.",al={"gnoll mosshide","chi sono i mosshide","bastardi mosshide"}}},fp="13,193,21.318.0,26.286.0,31.233.0,42.194.0,41.125.0,36.135.1,49.215.0"}
P.entries["quest:2766"] = {n="Find OOX-22/FE!",s="Un robot di puntamento è precipitato a Feralas, e Oglethorpe Obnoticus chiede aiuto attraverso uno strano uovo di metallo. Porta il suo radiofaro in una grotta vicino a Valsfregiata.",h="Un robot di puntamento è precipitato a Feralas, e Oglethorpe Obnoticus chiede aiuto attraverso uno strano...",kw={"radiofaro di soccorso","valsfregiata","feralas","robot di puntamento","pollo meccanico","oglethorpe obnoticus","oox-22/fe"},sec={{t="Una Voce nell'Uovo",b="Manovra la manopola dell'uovo di metallo e si apre un marchingegno gnomico. Oglethorpe Obnoticus parla dall'interno. Il suo robot di puntamento è precipitato e promette una ricompensa se lo recuperi. Ha calcolato che la macchina si trova in una grotta vicino a Valsfregiata. Porta lì il radiofaro."},{t="Cosa contiene la grotta",b="Nella grotta giace un pollo robotico in rovina. Oglethorpe Obnoticus conferma che è il suo robot di puntamento. Ha bisogno di una scarica per ripartire prima di poter volare a Baia del Bottino per le riparazioni. Inserisci il radiofaro e il robot si mette in moto ronzando. Poi la voce di Oglethorpe proviene dal robot stesso."}},faq={{q="Chi sta parlando attraverso il radiofaro di soccorso?",a="Oglethorpe Obnoticus parla attraverso il radiofaro. Il suo robot di puntamento è precipitato e ti chiede di portargli il radiofaro.",al={"chi ha creato il radiofaro","chi sta parlando","chi è oglethorpe"}},{q="Dove ti indica di andare il radiofaro?",a="Il radiofaro indica una grotta vicino a Valsfregiata, a Feralas. Oglethorpe ha calcolato le coordinate del robot.",al={"dov'è il robot","posizione robot di puntamento","dove portare il radiofaro"}},{q="Cos'è il radiofaro?",a="Il radiofaro è uno strano dispositivo metallico a forma di uovo. Gira la manopola e si apre, rivelando un marchingegno gnomico con una voce all'interno.",al={"cos'è l'uovo","cos'è oox-22/fe","radiofaro di soccorso"}},{q="Cosa succede dopo questa fase?",a="Segue Rescue OOX-22/FE!.",al={"prossima missione","cosa segue trova oox-22/fe","dopo la grotta"}}},fp="15,156,18.282.0,19.270.1,44.120.0,38.111.0,19.124.0,27.26.0"}
P.entries["quest:2767"] = {n="Rescue OOX-22/FE!",s="A Valsfregiata, OOX-22/FE! aspetta il tuo aiuto per raggiungere il molo della Costa dell'Oblio. Una volta arrivato, Oglethorpe Obnoticus vuole parlarti a Baia del Bottino.",h="A Valsfregiata, OOX-22/FE!",kw={"baia del bottino","valsfregiata","feralas","costa dell'oblio","robot trasmittente","oglethorpe obnoticus","oox-22/fe","pollo robot"},sec={{t="Un posto sicuro da cui decollare",b="OOX-22/FE ha bisogno di uno spazio aperto e sicuro per il suo lungo decollo. La voce dello gnomo gracchia attraverso il robot mentre spiega che il dispositivo di occultamento integrato ha bisogno di tempo prima di funzionare di nuovo. Anche Oglethorpe Obnoticus ha bisogno di tempo per farlo funzionare. Suggerisce il molo della Costa dell'Oblio, dove si può rimettere tutto in funzione. Scorti il robot fin lì da dove si trova."},{t="Successivamente, Baia del Bottino",b="Una volta che OOX-22/FE raggiunge il molo sano e salvo, Oglethorpe Obnoticus vuole che tu vada a parlargli a Baia del Bottino."}},faq={{q="Dove deve andare OOX-22/FE?",a="OOX-22/FE deve raggiungere il molo lungo la Costa dell'Oblio. Lo scorti da Valsfregiata, dove l'hai trovato.",al={"dove porto il pollo","destinazione oox-22/fe","percorso scorta pollo feralas"}},{q="Chi è Oglethorpe Obnoticus?",a="Oglethorpe Obnoticus è un inventore provetto e la sua serie di robot localizzatori include OOX-22/FE. Parla attraverso il robot e puoi trovarlo a Baia del Bottino.",al={"chi ha creato il pollo robot","chi è oglethorpe obnoticus","inventore pollo"}},{q="Perché il robot deve raggiungere il molo?",a="Il molo offre uno spazio aperto e sicuro per il lungo decollo, e Oglethorpe dice che c'è abbastanza spazio per rimettere tutto in funzione. Il dispositivo di occultamento integrato del robot ha bisogno di tempo prima di funzionare di nuovo.",al={"perché scortare oox-22","perché andare al molo"}},{q="Dove faccio rapporto dopo?",a="Una volta che OOX-22/FE raggiunge il molo sano e salvo, vai a parlare con Oglethorpe Obnoticus a Baia del Bottino.",al={"dov'è oglethorpe","luogo di consegna","con chi parlo dopo"}}},fp="17,166,24.363.0,21.102.0,32.116.0,28.146.0,42.192.0,29.83.0"}
P.entries["quest:277"] = {n="Fire Taboo",s="Nelle Paludi Grigie, Rethiel trasforma la preoccupazione per la foresta in azione. La bestia della palude chiede ai viaggiatori di prendere le Pietre Focaie Rudimentali che gli gnoll Pelomusco battono per dare fuoco agli alberi vivi, nella speranza di risparmiare gli antichi rami.",h="Nelle Paludi Grigie, Rethiel trasforma la preoccupazione per la foresta in azione.",kw={"pietra focaia rudimentale","fire taboo","gnoll","guardiaverde","legno vivo","pelomusco","rethiel","paludi grigie"},ang={["class:Druid"]="Da druido, condividi la venerazione di Rethiel per la natura selvaggia e comprendi il dolore degli alberi vivi che bruciano nelle fosse dei gnoll.",["faction:Alliance"]="Da viaggiatore dell'Alleanza, sai che gli gnoll Pelomusco minacciano chi attraversa le Paludi Grigie. Aiutare gli spiriti locali protegge le rotte commerciali tra Dun Morogh e Arathi.",["race:NightElf"]="Da elfo della Notte, potresti riconoscere in Rethiel un altro protettore degli alberi vivi: una bestia della palude che sente la sofferenza delle Paludi Grigie."},sec={{t="L'angoscia di un Guardiaverde",b="Rethiel il Guardiaverde considera gli alberi delle Paludi Grigie come suoi simili. Marciume e rinascita fanno parte della palude, eppure gli gnoll Pelomusco abbattono alberi vivi e li gettano nei loro focolari. I gemiti di quei rami pesano su Rethiel. Il Guardiaverde non può più restare a guardare in silenzio mentre gli alberi soffrono."},{t="Estinguere i Pelomusco",b="Rethiel spera di arginare i Pelomusco senza una lunga guerra, così la bestia della palude ti chiede di prendere le Pietre Focaie Rudimentali portate dai loro gnoll più forti. Senza quegli strumenti, il branco non può bruciare il legname che abbatte.\n\nRethiel intende frantumare ogni pietra e gettarne la polvere in mare, dove non potrà mai più incendiare la foresta."}},faq={{q="Chi è Rethiel il Guardiaverde?",a="Rethiel il Guardiaverde è una bestia della palude che vive nelle Paludi Grigie. Legato alla vita degli alberi e delle piante, Rethiel cerca di proteggere la palude ferita dagli gnoll Pelomusco.",al={"chi è rethiel","lore rethiel guardiaverde","chi dà fire taboo"}},{q="Perché Rethiel vuole le Pietra Focaia Rudimentale invece di uccidere i leader dei gnoll?",a="Rethiel considera il rogo del legno vivo una violazione imperdonabile. Prendere le pietre focaie impedisce ai gnoll di accendere fuochi tra gli alberi delle paludi e pone fine alla distruzione del legno vivo.",al={"perché pietre focaie","perché prendere le pietre focaie","scopo pietra focaia rudimentale"}},{q="Cosa succede alle pietre focaie una volta consegnate?",a="Rethiel frantuma le pietre focaie e ne getta i resti in mare, dove non potranno più incendiare il legname vivo.",al={"cosa fa con le pietre focaie","distruzione pietre focaie"}},{q="Quali gnoll trasportano le pietre focaie?",a="Gli gnoll Pelomusco più forti portano le Pietre Focaie Rudimentali. I Pelomusco più piccoli e i bastardi più deboli non ricevono strumenti per accendere il fuoco e non ne portano.",al={"chi rilascia le pietre focaie","quali gnoll hanno la pietra focaia rudimentale"}},{q="Perché i Pelomusco abbattono gli alberi?",a="Gli gnoll Pelomusco abbattono alberi vivi per alimentare i falò del loro accampamento e scaldarsi nella palude umida. Usano legname verde invece di legna secca caduta dagli alberi.",al={"perché i gnoll tagliano gli alberi","disboscamento pelomusco"}},{q="Cosa succede dopo aver raccolto le pietre focaie?",a="Dopo che hai preso le pietre focaie e privato i gnoll del fuoco, Rethiel ti manda ad affrontare un'altra piaga che affligge le paludi. Si chiama Blisters on The Land.",al={"quale missione segue fire taboo","missione successiva dopo le pietre focaie"}}},fx={e3ab03fe={q="Perché Rethiel il Guardiaverde vuole che venga fatto questo?",a="In quanto protettore legato alla terra e alla natura, Rethiel avverte profondamente la sofferenza delle Paludi. I gnoll Mantoscuro abbattono alberi vivi e li bruciano per scaldarsi, infliggendo agonia alla natura selvaggia. Privando i gnoll delle loro pietre focaie, Rethiel spera di fermare la distruzione della foresta e impedire loro di bruciare ancora legno vivo.",al={"motivazioni di rethiel","perché prendere le pietre focaie","perché rethiel odia il fuoco"}},b6cb9238={q="A cosa serve la Pietra Focaia Rudimentale?",a="I gnoll Mantoscuro portano pietre focaie rudimentali, strumenti primitivi con cui sprigionano scintille e accendono il fuoco. Senza di esse, non possono bruciare il legno vivo degli alberi che abbattono nelle Paludi. Rethiel ti chiede di raccogliere queste pietre focaie perché possa frantumarle e gettarne i resti in mare, privandoli della capacità di appiccare incendi.",al={"uso della pietra focaia rudimentale","cosa sono le pietre focaie rudimentali","perché i gnoll hanno pietre focaie"}},["25034295"]={q="Chi sono i Mantoscuro che devi affrontare?",a="Devi affrontare i gnoll Mantoscuro, un feroce clan di uomini-iena che infestano le Paludi. Si sono diffusi per le paludi, costruendo accampamenti e abbattendo aggressivamente alberi antichi per alimentare i fuochi e reclamare il territorio, devastando e turbando l'equilibrio naturale protetto da Rethiel.",al={"gnoll mantoscuro nelle paludi","chi sono i gnoll","gnoll mantoscuro"}}},fp="10,207,23.280.0,27.308.0,31.177.0,72.191.0,51.120.0,30.149.0,41.144.0,43.162.1"}
P.entries["quest:278"] = {n="A Dark Threat Looms",s="Gli esplosivi dei Ferroscuro minacciano la Diga di Pietrasalda e il Capo Ingegnere Hinderweir VII ha bisogno del tuo aiuto. Ti chiede di raccogliere rari reagenti a Loch Modan per preparare una miscela in grado di neutralizzarli.",h="Gli esplosivi dei Ferroscuro minacciano la Diga di Pietrasalda e il Capo Ingegnere Hinderweir VII ha bisogno...",kw={"lacrima di crocolisco","ferroscuro","hinderweir","loch modan","veleno di solcatore","cristallo dei mo'grosh","diga di pietrasalda"},ang={["faction:Alliance"]="Da viaggiatore dell'Alleanza, sai che la distruzione della diga interromperebbe le cruciali rotte terrestri di rifornimento tra Forgiardente e i regni settentrionali.",["profession:Engineering"]="Da ingegnere, puoi apprezzare l'ingegno di Hinderweir nel creare un reagente chimico che stabilizza sul campo le cariche esplosive volatili.",["race:Dwarf"]="Da nano di Khaz Modan, hai il dovere fondamentale di fermare il sabotaggio dei Ferroscuro alla Diga di Pietrasalda e proteggere le terre dei tuoi antenati e le loro grandi opere."},sec={{t="Una ricetta volatile",b="Il Capo Ingegnere Hinderweir VII ha bisogno di tre ingredienti per la sua miscela. Il veleno di Solcatore, una lacrima di crocolisco del Loch e un Cristallo dei Mo'grosh provocano reazioni diverse. Insieme, possono rendere inerti le cariche naniche."},{t="Raccolta pericolosa",b="Gli ingredienti si trovano nelle zone pericolose di Loch Modan. I ragni Solcatori delle foreste e i crocolischi minacciano i viaggiatori, mentre gli ogre Mo'grosh custodiscono i cristalli estratti in una roccaforte a nord-est. Per raggiungere i cristalli, dovrai affrontare gli ogre nei loro accampamenti."}},faq={{q="Perché l'ingegnere Hinderweir ha bisogno di questi specifici reagenti?",a="Il Capo Ingegnere Hinderweir VII ha bisogno dei reagenti per preparare un composto capace di disinnescare gli esplosivi dei Ferroscuro. Il veleno di Solcatore, le secrezioni dei crocolischi e i cristalli dei Mo'grosh forniscono le reazioni necessarie a rendere inerti le cariche dei sabotatori.",al={"perché veleno di ragno","perché lacrima di crocolisco","reagenti per miscela disinnescante"}},{q="Da dove provengono i Cristalli dei Mo'grosh?",a="Gli ogre Mo'grosh estraggono e accumulano i cristalli nelle colline nord-orientali di Loch Modan. Per raggiungerne uno, dovrai addentrarti nel loro territorio, difeso con forza.",al={"dove sono i cristalli","posizione cristallo mogrosh","chi ha il cristallo"}},{q="Qual è la minaccia oscura che incombe sul Loch Modan?",a="Gli infiltrati nani dei Ferroscuro vogliono distruggere la Diga di Pietrasalda. La sua distruzione inonderebbe le Paludi Grigie sottostanti, interromperebbe le linee di rifornimento dell'Alleanza e devasterebbe la regione.",al={"che minaccia oscura","chi sta attaccando la diga","storia della minaccia oscura"}},{q="Chi è il Capo Ingegnere Hinderweir VII?",a="Il Capo Ingegnere Hinderweir VII è l'ingegnere nanico che sovrintende al funzionamento e all'integrità della Diga di Pietrasalda. Ne dirige la manutenzione e le difese locali contro i sabotaggi.",al={"chi è hinderweir","capo ingegnere hinderweir"}},{q="Dove si possono trovare le creature indigene?",a="I ragni Solcatori delle foreste si aggirano nelle terre selvagge e boscose attorno alla valle. I crocolischi vivono dentro e attorno alle sponde del Loch.",al={"dove sono i solcatori","posizione crocolisco","dove trovare i ragni"}},{q="Perché le guardie di Forgiardente non raccolgono questi oggetti da sole?",a="I Montanari e le guardie locali sono impegnati a difendere città come Thelsamar e a sorvegliare gli esploratori dei Ferroscuro. Le ricerche specializzate e le incursioni nel territorio degli ogre spettano ai viaggiatori più capaci.",al={"perché aiutare hinderweir","dove sono le guardie di forgiardente"}}},fx={["0370975a"]={q="Perché Capo Ingegnere Hinderweir VII vuole che vengano raccolti questi oggetti?",a="Capo Ingegnere Hinderweir VII teme un imminente assalto dei nani Ferroscuro alla Diga di Pietrasalda. Per contrastare eventuali tentativi di demolizione, ha bisogno che tu raccolga reagenti volatili e speciali: Veleno di Solcatore, una Lacrima di Crocolisco e un raro Cristallo dei Mo'grosh. Con essi potrà preparare una mistura neutralizzante per disinnescare gli esplosivi nemici prima che Loch Modan venga devastata.",al={"perché hinderweir vuole che venga fatto","perché raccogliere i reagenti per hinderweir","motivazioni di hinderweir per la minaccia oscura"}}},fp="19,207,17.245.0,18.259.0,58.232.0,37.145.0,44.167.0,37.179.0,44.116.0,61.193.0"}
P.entries["quest:2781"] = {n="WANTED: Caliph Scorpidsting",s="Gli avvisi a Meccania e al Porto degli Spargifumo danno la caccia a Caliph Scorpidsting, capo dei fuorilegge Wastewander. La Gadgetzan Water Company cerca prove della sua morte a Meccania.",h="Gli avvisi a Meccania e al Porto degli Spargifumo danno la caccia a Caliph Scorpidsting, capo dei fuorilegge...",kw={"taglia","caliph scorpidsting","capo ingegnere segachiodi","meccania","gadgetzan water company","porto degli spargifumo","tanaris","wastewander"},sec={{t="Le accuse della Compagnia",b="A Meccania e al Porto degli Spargifumo, la Gadgetzan Water Company offre una lauta taglia per Caliph Scorpidsting. Gli avvisi lo accusano di aver ucciso dipendenti della compagnia, rubato le sue risorse e sequestrato le sue proprietà. Porta la prova della sua morte al Capo Ingegnere Segachiodi a Meccania."},{t="Le speranze della Water Company",b="Il Capo Ingegnere Segachiodi definisce la morte di Scorpidsting giustizia e un duro colpo contro i Wastewander. Li chiama vili nomadi e abusivi. L'ingegnere spera che la taglia, pagata dalla compagnia, li allontani finalmente dai pozzi d'acqua di Meccania."}},faq={{q="Chi è Caliph Scorpidsting?",a="Caliph Scorpidsting guida i fuorilegge Wastewander ed è ricercato dalla Gadgetzan Water Company.",al={"lore di caliph scorpidsting","chi guida i wastewander","scorpidsting"}},{q="Perché la Gadgetzan Water Company lo vuole morto?",a="La compagnia lo accusa di aver ucciso i suoi dipendenti, rubato le sue risorse e sequestrato le sue proprietà.",al={"perché taglia su scorpidsting","crimini di caliph scorpidsting","nemico della gadgetzan water company"}},{q="Chi paga la taglia per Caliph Scorpidsting?",a="La Gadgetzan Water Company paga la taglia. Il Capo Ingegnere Segachiodi a Meccania accetta le prove della morte di Scorpidsting.",al={"chi accetta la consegna di scorpidsting","dove consegnare la testa di caliph","taglia segachiodi"}},{q="Dove si trovano i manifesti dei ricercati?",a="Gli avvisi di ricerca sono a Meccania e al Porto degli Spargifumo.",al={"posizione manifesto caliph","dove prendere la taglia di caliph","avviso scorpidsting"}}},fp="27,179,21.282.0,32.254.1,27.95.0,51.100.0,44.122.0,37.61.0"}
P.entries["quest:2782"] = {n="Segreto di Rin'ji",s="Dopo aver aiutato Rin'ji, porti con te il Segreto di Rin'ji, una tavoletta con iscrizioni in lingua Witherbark che nessuno ha ancora letto. Oran Torciserpe studia i Witherbark e potrebbe decifrarla. Pare che viva nel Magic Quarter di Sepulcra.",h="Dopo aver aiutato Rin'ji, porti con te il Segreto di Rin'ji, una tavoletta con iscrizioni in lingua...",kw={"hinterlands","magic quarter","oran torciserpe","rin'ji","tavoletta","sepulcra","witherbark"},sec={{t="Una tavoletta che nessuno riesce a leggere",b="La tavoletta è coperta di segni dei troll Witherbark, ma il segreto di Rin'ji resta un mistero. Potrebbe valere moltissimo oppure niente. Un troll Witherbark nei guai potrebbe tentare qualsiasi cosa pur di uscirne."},{t="Uno studioso a Sepulcra",b="Oran Torciserpe è un noto studioso dei troll Witherbark. Pare che viva nel Magic Quarter di Sepulcra e potrebbe riuscire a leggere la tavoletta."}},faq={{q="Da dove proviene questa tavoletta?",a="La tavoletta è il segreto che Rin'ji nascose alle Scogliere dell'Osservatorio. L'hai trovata dopo aver aiutato Rin'ji a fuggire dal Padiglione Quel'Danil.",al={"origine tavoletta rinji","come ottengo la tavoletta"}},{q="Chi può leggere i segni sulla tavoletta?",a="Oran Torciserpe conosce bene i troll Witherbark e potrebbe riuscire a decifrare i segni.",al={"chi può decifrare la tavoletta","chi legge i segni dei witherbark"}},{q="Dove si trova Oran Torciserpe?",a="Pare che Oran Torciserpe viva nel Magic Quarter di Sepulcra.",al={"posizione oran torciserpe","dove si trova oran"}},{q="La tavoletta è di valore?",a="Nessuno può dirlo. La tavoletta potrebbe valere moltissimo oppure niente, perché un troll Witherbark in difficoltà potrebbe tentare qualsiasi cosa pur di cavarsela.",al={"qual è il segreto di rinji","significato tavoletta"}}},fp="15,227,24.201.0,26.160.0,32.123.0,40.91.0,34.72.0,23.146.0"}
P.entries["quest:28"] = {n="Trial of the Lake",s="Tajarri attende l'esito di una prova al Santuario di Remulos, a Radaluna. Al centro c'è una Bolla del Santuario proveniente dal Lago Elune'ara.",h="Tajarri attende l'esito di una prova al Santuario di Remulos, a Radaluna.",kw={"lago elune'ara","radaluna","bolla del santuario","santuario di remulos","tajarri","trial of the lake"},sec={{t="Al Santuario",b="Al Santuario di Remulos, nella parte nord-occidentale di Radaluna, Tajarri ti chiede di affrontare una prova. Trova una Bolla del Santuario nel Lago Elune'ara e portala al santuario. Usala lì, poi parla con Tajarri per completare la prova."}},faq={{q="Cosa mi chiede di fare Tajarri?",a="Tajarri ti chiede di trovare una Bolla del Santuario nel Lago Elune'ara, usarla al Santuario di Remulos e poi parlarle.",al={"prova di tajarri","cosa devo fare","prova del lago"}},{q="Dov'è il Santuario di Remulos?",a="Il Santuario di Remulos si trova nella parte nord-occidentale di Radaluna.",al={"posizione del santuario di remulos","dov'è il santuario","posizione del santuario"}},{q="Dove trovo la Bolla del Santuario?",a="La Bolla del Santuario si trova nel Lago Elune'ara.",al={"posizione della bolla","trova la bolla","bolla del lago"}},{q="Cosa devo fare con la Bolla del Santuario?",a="Porta la Bolla del Santuario al Santuario di Remulos e usala lì.",al={"usa la bolla","bolla al santuario","bolla del santuario"}},{q="Con chi devo parlare dopo aver usato la bolla?",a="Dopo aver usato la Bolla del Santuario, parla con Tajarri al santuario.",al={"parlare con tajarri","dopo il santuario","completare la prova"}}},fp="17,128,13.217.0,31.117.0,31.51.0,34.39.0,36.65.0,43.63.0"}
P.entries["quest:280"] = {n="A Dark Threat Looms",s="I sabotatori Ferroscuro minacciano la Diga di Pietrasalda a Loch Modan. Il Capo Ingegnere Hinderweir VII deve disinnescare la carica prima che il Loch inondi le pianure sottostanti.",h="I sabotatori Ferroscuro minacciano la Diga di Pietrasalda a Loch Modan.",kw={"diga","ferroscuro","disinnesco","esplosivo","hinderweir","insorti","barile","seaforium","pietrasalda"},ang={["faction:Alliance"]="Da membro dell'Alleanza, sai che la Diga di Pietrasalda protegge le rotte vitali che collegano Khaz Modan ai territori settentrionali dell'Alleanza.",["profession:Engineering"]="Da ingegnere, puoi capire come il Seaforium e le sostanze disarmanti portino le demolizioni e la chimica anti-esplosivi al loro limite più pericoloso.",["race:Dwarf"]="Da nano, conosci la Diga di Pietrasalda come monumento all'abilità e all'orgoglio dei nani. Proteggerla dal tradimento dei Ferroscuro è importante per Forgiardente.",["race:Gnome"]="Da gnomo, puoi comprendere la chimica del neutralizzatore di Hinderweir e la devastazione che una breccia nel Seaforium potrebbe causare all'ingegneria nanica."},sec={{t="Sabotaggio sotto la superficie",b="Il Capo Ingegnere Hinderweir VII ha visto degli Insorti del Ferro Nero nuotare verso la Diga di Pietrasalda con un barile di Seaforium esplosivo. Non c'erano Montanari nelle vicinanze per fermarli. Gli infiltrati hanno fissato il barile alle fondamenta sommerse della diga. Se la diga cede, il Loch inonderà le pianure sottostanti e paralizzerà il commercio e gli spostamenti dei nani."},{t="Un neutralizzante volatile",b="Il Capo Ingegnere Hinderweir VII ha mescolato ingredienti reattivi in una soluzione disarmante e manda un sommozzatore al barile sommerso. Il sommozzatore deve svitarlo e mescolare la soluzione alla polvere esplosiva. La miscela ferma il conto alla rovescia con un leggero sfrigolio sott'acqua e stabilizza la carica prima che possa squarciare la diga."}},faq={{q="Qual è l'obiettivo di questa missione?",a="Ti immergi nelle acque di Loch Modan fino alle fondamenta della Diga di Pietrasalda. Lì trovi il barile di Seaforium piazzato e vi mescoli la soluzione del Capo Ingegnere Hinderweir VII per fermare l'esplosione.",al={"obiettivi missione","cosa devo fare qui","obiettivo a dark threat looms"}},{q="Chi ha piazzato il barile esplosivo?",a="Gli Insorti del Ferro Nero hanno piazzato il barile. Si sono introdotti nelle acque di Loch Modan all'inizio della giornata, quando i Montanari del posto erano assenti, poi hanno fissato la carica alla parete sommersa della diga.",al={"chi ha messo la bomba","chi ha piazzato il seaforium","colpevoli a dark threat looms"}},{q="Cosa succede se la diga viene distrutta?",a="La Diga di Pietrasalda trattiene le acque di Loch Modan. Se si spacca, l'acqua inonderà le Paludi Grigie e le valli vicine, spazzando via strade, paesi e vite.",al={"perché salvare la diga","cosa succede se la bomba esplode","rischi esplosione diga"}},{q="Chi ha preparato la mistura disarmante?",a="Il Capo Ingegnere Hinderweir VII ha preparato il neutralizzatore chimico con reagenti raccolti. Può neutralizzare il Seaforium senza innescare un'esplosione accidentale.",al={"chi ha fatto la mistura","ruolo di hinderweir","chi ha preparato la sostanza chimica"}},{q="Dov'è situato il barile esplosivo?",a="Il barile si trova sott'acqua, contro la base profonda della Diga di Pietrasalda, sul lato meridionale rivolto verso il lago.",al={"dov'è la bomba","posizione barile","barile di polvere sott'acqua"}},{q="Che tipo di esplosivo è stato usato?",a="I sabotatori hanno usato il Seaforium, un composto volatile da demolizione stipato in un barile sigillato e impermeabile.",al={"di cosa è fatta la bomba","tipo di bomba","quale esplosivo"}}},fx={["8859d649"]={q="Perché Capo Ingegnere Hinderweir VII vuole che venga fatto questo?",a="In qualità di ingegnere capo responsabile della Diga di Pietrasalda, Hinderweir si assume personalmente la responsabilità della sua solidità strutturale. Gli insorti Ferroscuro hanno piazzato un potente esplosivo Seaforium proprio alle fondamenta. Se la diga cede, la catastrofica inondazione del Loch sommergerà le valli sottostanti e distruggerà una delle più grandi meraviglie architettoniche del popolo dei nani.",al={"perché hinderweir ci tiene","motivazioni di hinderweir","perché fermare l'esplosione"}},["34eba16d"]={q="Perché Capo Ingegnere Hinderweir VII ha bisogno di te invece che degli Esploratori?",a="Quando i sabotatori Ferroscuro si sono avvicinati, non c'erano Esploratori nei paraggi per fermarli, e il tempo stringe. La carica potrebbe esplodere da un momento all'altro e Hinderweir ha dovuto restare indietro per preparare d'urgenza la mistura disarmante con gli ingredienti grezzi. Sei l'unica persona capace sul posto che può immergersi e neutralizzare subito l'esplosivo.",al={"perché non possono farlo le guardie","perché io per hinderweir","dove sono gli esploratori"}}},fp="19,165,28.339.0,22.330.1,31.185.0,30.196.0,37.151.0,36.155.0,35.103.0,32.98.0"}
P.entries["quest:282"] = {n="Senir's Observations",s="Grelin Barbabianca ti manda a est, a Kharanos, con il suo rapporto per suo fratello Senir. I trogg hanno invaso il tunnel dalla Valle Crestafredda, dove il Montanaro Thalos sorveglia il passaggio.",h="Grelin Barbabianca ti manda a est, a Kharanos, con il suo rapporto per suo fratello Senir.",kw={"forgiamara","valle crestafredda","grelin barbabianca","rapporto di grelin","kharanos","montanaro thalos","senir barbabianca","trogg","tunnel"},ang={["faction:Alliance"]="Aiuti a mantenere sicuri i passaggi tra le valli dei nani, proteggendo Forgiardente e i corrieri dell'Alleanza.",["race:Dwarf"]="Da montanaro o recluta dei nani, attraversi il tunnel orientale durante il tuo primo incarico ufficiale oltre il Cortile d'Addestramento della Valle Crestafredda.",["race:Gnome"]="Da rifugiato gnomo tra i Bronzebeard, puoi portare questo dispaccio dal tuo primo rifugio verso i problemi che attanagliano Dun Morogh."},sec={{t="Un corriere per i Barbabianca",b="Il rapporto di Grelin Barbabianca racconta l'attività dei troll Frostmane nei dintorni della Valle Crestafredda. I troll gli hanno rubato il diario, che tu hai recuperato. Grelin ha giudicato i risultati troppo importanti perché li portasse un apprendista inesperto. Perciò affida il rapporto a te, perché lo consegni direttamente a suo fratello Senir a Kharanos."},{t="Il passo bloccato per Kharanos",b="I trogg hanno invaso il tunnel orientale dalla Valle Crestafredda verso il resto di Dun Morogh. Il Montanaro Thalos sorveglia l'ingresso per tenere i civili lontani dal pericolo. Lascia passare i viaggiatori solo se hanno questioni ufficiali urgenti da sbrigare."}},faq={{q="A chi sta inviando questo rapporto Grelin?",a="Grelin Barbabianca invia il suo rapporto a suo fratello Senir Barbabianca a Kharanos, dove Senir valuta le questioni della regione.",al={"destinatario del rapporto","senir barbabianca","destinatario rapporto"}},{q="Perché l'apprendista di Grelin non può consegnare il rapporto?",a="Grelin aveva pensato di mandare il suo apprendista, ma i troll Frostmane gli hanno rubato il diario. I risultati erano troppo importanti per affidarli a mani inesperte.",al={"perché non l'apprendista","apprendista di grelin"}},{q="Perché il tunnel che esce dalla Valle Crestafredda è sorvegliato?",a="I trogg hanno invaso il tunnel dalla Valle Crestafredda verso Dun Morogh. Il Montanaro Thalos sorveglia l'ingresso per proteggere i civili finché il passaggio non sarà libero.",al={"perché thalos sorveglia","tunnel bloccato","perché il tunnel è chiuso"}},{q="Dove si trova il Montanaro Thalos?",a="Il Montanaro Thalos è di guardia a est di Forgiamara, vicino all'ingresso del tunnel dalla Valle Crestafredda verso Kharanos.",al={"posizione di thalos","dove si trova thalos","trovare montanaro thalos"}},{q="Cosa ti permette di attraversare il tunnel infestato dai trogg?",a="Il Montanaro Thalos ti lascia passare perché porti l'urgente dispaccio di Grelin Barbabianca.",al={"attraversare il tunnel","permesso per il tunnel"}},{q="Cosa succede dopo aver parlato con il Montanaro Thalos?",a="Il Montanaro Thalos ti avverte del pericoloso tunnel e ti guida prima di lasciarti proseguire a est verso Kharanos.",al={"passo successivo","cosa fare dopo thalos"}}},fx={ba85e128={q="Perché Grelin Barbabianca vuole che venga consegnato questo rapporto?",a="Grelin Barbabianca documenta la crescente attività dei troll Mantogelido e le minacce nella Valle Crestafredda. Suo fratello, Senir Barbabianca, è di stanza a Kharanos e raccoglie informazioni sui problemi più ampi di Dun Morogh. Consegnare il rapporto a Senir senza intoppi è fondamentale per coordinare la difesa della regione, soprattutto ora che i Mantogelido si avvicinano sempre più agli insediamenti dei nani.",al={"perché consegnare il rapporto di grelin","motivazioni di grelin barbabianca","perché consegnare le osservazioni di senir"}}},fp="20,178,29.308.0,28.232.0,37.123.0,49.145.0,50.153.0,36.108.0,58.90.0,52.120.0"}
P.entries["quest:2821"] = {n="The Mark of Quality",s="Alla Roccaforte di Piumaluna, Pratt McGrubben cerca dieci spesse pelli di yeti e offre una scelta di articoli in cuoio.",h="Alla Roccaforte di Piumaluna, Pratt McGrubben cerca dieci spesse pelli di yeti e offre una scelta di articoli...",kw={"roccaforte di piumaluna","valsfregiata","feralas","costa dell'oblio","pratt mcgrubben","the mark of quality","spessa pelle di yeti","yeti"},sec={{t="La filosofia di Pratt",b="Pratt McGrubben, conciatore alla Roccaforte di Piumaluna, insiste per ottenere il lavoro migliore. In cerca di materiali pregiati, ha trovato spesse pelli di yeti. Gli yeti sono originari di Feralas e molti vivono attorno alla Valsfregiata, appena all'interno della Costa dell'Oblio."},{t="L'offerta",b="Porta una pila di dieci pelli a Pratt, alla Roccaforte di Piumaluna. In cambio, potrai scegliere uno degli articoli in cuoio che ha realizzato."},{t="Le riflessioni di Pratt sulle pelli",b="Pratt McGrubben ti chiede se hai sentito la consistenza delle pelli. Se trattate correttamente, potrebbero rivelarsi più resistenti del ferro, e pochi le conoscono. Pratt conosce molte soluzioni per trattarle. Spera di trasformare le pelli in oggetti degni di un vero marchio di qualità."}},faq={{q="Chi richiede le pelli?",a="Pratt McGrubben, il conciatore alla Roccaforte di Piumaluna, chiede le pelli.",al={"datore di missione","pratt mcgrubben","chi dà the mark of quality"}},{q="Dove si possono trovare gli yeti?",a="Attorno alla Valsfregiata, appena all'interno della Costa dell'Oblio, dove vivono molti degli yeti originari di Feralas.",al={"posizione yeti","dove si trovano gli yeti","valsfregiata"}},{q="Quante pelli vuole Pratt?",a="Pratt vuole dieci pelli in un'unica pila.",al={"quante pelli di yeti","numero pelli"}},{q="Cosa ricevo in cambio delle pelli?",a="In cambio della pila, Pratt ti offre la scelta di uno degli articoli in cuoio che ha realizzato.",al={"cosa dà pratt","ricompensa mark of quality"}}},fp="19,107,18.246.0,9.126.0,29.253.1,28.81.0,29.102.0,31.35.0,28.94.0"}
P.entries["quest:2822"] = {n="The Mark of Quality",s="All'Accampamento Mojache, Jangdor Passo Lesto cerca dieci pelli spesse di yeti e non accetta compromessi sulla qualità.",h="All'Accampamento Mojache, Jangdor Passo Lesto cerca dieci pelli spesse di yeti e non accetta compromessi...",kw={"accampamento mojache","valsfregiata","feralas","costa dell'oblio","jangdor passo lesto","concia","pelle di yeti spessa","yeti"},sec={{t="Questione d'orgoglio",b="Jangdor Passo Lesto è orgoglioso del suo lavoro di pelletteria. Ha trovato pelli spesse di yeti a Feralas, dove vivono gli yeti. Molti si aggirano a ovest dell'Accampamento Mojache, nella Valsfregiata, appena all'interno della Costa dell'Oblio."},{t="L'offerta",b="Porta a Jangdor una pila di dieci pelli all'Accampamento Mojache. In cambio, ti lascerà scegliere uno degli articoli in cuoio che ha realizzato."},{t="I pensieri di Jangdor sulle pelli",b="Jangdor dice che un trattamento speciale può rendere le pelli resistenti quanto il ferro. Trovare la miscela conciante giusta richiederà molti tentativi. Crede che queste pelli possano innalzare ancora il suo standard di qualità."}},faq={{q="Chi richiede le pelli?",a="Jangdor Passo Lesto, il conciatore dell'Accampamento Mojache a Feralas, chiede le pelli.",al={"chi assegna la missione","datore di missione mark of quality","dove si trova jangdor"}},{q="Dove si possono trovare gli yeti?",a="Gli yeti vivono a Feralas. Molti si aggirano a ovest dell'Accampamento Mojache, nella Valsfregiata, appena all'interno della Costa dell'Oblio.",al={"dove sono gli yeti","posizione pelle di yeti","dove si trova valsfregiata"}},{q="Quante pelli sono richieste?",a="Dieci pelli, portate in un'unica pila.",al={"quante pelli di yeti","conteggio pelli di yeti","requisiti mark of quality"}},{q="Cosa ottengo in cambio delle pelli?",a="In cambio della pila, Jangdor ti offre la possibilità di scegliere uno degli articoli in cuoio che ha realizzato.",al={"cosa dà jangdor","ricompensa mark of quality"}}},fp="19,100,17.215.0,9.123.0,31.203.1,28.92.0,29.120.0,28.32.0,28.87.0"}
P.entries["quest:283"] = {n="A Dark Threat Looms",s="Il Capo Ingegnere Hinderweir VII ti aspetta alla Diga di Pietrasalda, dove i sabotatori Ferroscuro hanno piazzato una carica. Disarmala prima che la valle sottostante sia in pericolo.",h="Il Capo Ingegnere Hinderweir VII ti aspetta alla Diga di Pietrasalda, dove i sabotatori Ferroscuro hanno...",kw={"ferroscuro","mistura disarmante","carica esplosiva","hinderweir","loch modan","sabotaggio","diga di pietrasalda"},ang={["faction:Alliance"]="Come membro dell'Alleanza, contribuisci a preservare le principali vie terrestri tra Forgiardente e le terre settentrionali di Arathi e Lordaeron.",["profession:Engineering"]="Come ingegnere, conosci l'importanza delle contromisure e della teoria degli esplosivi quando neutralizzi un ordigno instabile all'interno di un colossale progetto civile.",["race:Dwarf"]="Come nano, puoi essere fiero della Diga di Pietrasalda, una grande opera della maestria nanica nella lavorazione della pietra. Proteggerla difende l'orgoglio di Forgiardente dalla malizia dei Ferroscuro."},sec={{t="La carica nella diga",b="La Diga di Pietrasalda trattiene le acque del Loch sopra le pianure delle Paludi Grigie. Al suo interno si trova una carica esplosiva, un barile volatile lasciato lì dai Ferroscuro. Se esplode, la valle sottostante e chi vive lungo il fiume ne pagheranno le conseguenze. Sta a te applicare la Mistura Disarmante prima che accada, poi riferire tutto al Capo Ingegnere Hinderweir VII."},{t="Il sollievo di Hinderweir",b="Applichi la Mistura Disarmante e il barile volatile si spegne con un sibilo innocuo. Il pericolo immediato per la diga e per chi vive a valle è passato. Il Capo Ingegnere Hinderweir VII accoglie sollevato il tuo rapporto. Definisce il tuo intervento una vittoria per il Regno di Forgiardente e per l'Alleanza. Gli infiltrati Ferroscuro sono penetrati a fondo in Khaz Modan, e i loro amari cugini restano determinati a rovinare le imprese di Forgiardente."}},faq={{q="Qual era l'obiettivo di questa serie di missioni?",a="La catena di missioni mira a scoprire e fermare un complotto dei nani Ferroscuro, che vogliono far esplodere la Diga di Pietrasalda.",al={"a dark threat looms riassunto","obiettivo missione diga di pietrasalda","perché disinnescare la bomba"}},{q="Chi ha piazzato la carica esplosiva?",a="I sabotatori nani Ferroscuro hanno nascosto il barile esplosivo nella Diga di Pietrasalda per distruggerla.",al={"chi ha messo la bomba qui","chi ha attaccato la diga","diga dei ferroscuro"}},{q="Chi è il Capo Ingegnere Hinderweir VII?",a="Il Capo Ingegnere Hinderweir VII è il sovrintendente nanico responsabile della manutenzione, del funzionamento e della difesa della Diga di Pietrasalda a Loch Modan.",al={"chi è hinderweir","lore di hinderweir","ingegnere alla diga"}},{q="Cosa sarebbe successo se la diga si fosse rotta?",a="Se la Diga di Pietrasalda cedesse, il bacino di Loch Modan si svuoterebbe con violenza e inonderebbe le Paludi Grigie a valle, spazzando via strade, insediamenti e importanti vie di transito.",al={"cosa succede se la diga viene distrutta","conseguenze rottura diga","esplosione diga"}},{q="Come è stato disinnescato l'esplosivo?",a="Versi una Mistura Disarmante appositamente preparata sulla carica esplosiva, e il barile di polvere si spegne in sicurezza prima di poter detonare.",al={"come è stata fermata la bomba","mistura disarmante","come disinnescare la carica"}},{q="La Diga di Pietrasalda è al sicuro ora?",a="La detonazione imminente è stata impedita e la diga è salva. Hinderweir dice che la difesa è sicura solo per il momento, perché gli agenti Ferroscuro continuano a minacciare la regione.",al={"la diga è sicura","i ferroscuro se ne sono andati","diga sicura per sempre"}}},fp="19,157,21.377.0,19.433.1,38.115.0,33.96.0,37.143.0,42.169.0,31.137.1,33.176.1"}
P.entries["quest:284"] = {n="The Search Continues",s="La ricerca della Statuetta di Menethil continua tra le capanne dei Murloc vicine. Non ci trovi traccia, così passi ad altre due.",h="La ricerca della Statuetta di Menethil continua tra le capanne dei Murloc vicine.",kw={"barile","formaggio","capanne","statuetta di menethil","murloc","ricerca"},sec={{t="Capanne vuote",b="Esplori questo gruppo di capanne dei Murloc, ma non trovi traccia della Statuetta di Menethil. Due ripari vicini, a nord e a nord-est, potrebbero contenere indizi."}},faq={{q="Che cosa sto cercando?",a="Stai cercando la Statuetta di Menethil.",al={"ricerca della statuetta","statuetta di menethil","quale statuetta"}},{q="Che cosa trovo in queste capanne?",a="In questo gruppo di capanne dei Murloc non trovi tracce della Statuetta di Menethil.",al={"capanne dei murloc","capanne vuote","c'è qualcosa qui"}},{q="Dove dovrei cercare ora?",a="Cerca altri indizi nelle capanne vicine a nord e a nord-est.",al={"prossime capanne","dove cercare","capanne a nord"}},{q="Che cosa c'è nel barile?",a="La botte contiene formaggio umido e pungente, ma ancora gustoso.",al={"contenuto del barile","barile di formaggio","cosa c'è nel barile"}}},fp="20,135,12.149.0,24.45.0,31.77.0,25.68.0,22.58.0"}
P.entries["quest:2844"] = {n="The Giant Guardian",s="Roccia Dura cerca Shay, la bambina elfa della Notte che avrebbe dovuto sorvegliare. Preoccupato, ti chiede di cercarla.",h="Roccia Dura cerca Shay, la bambina elfa della Notte che avrebbe dovuto sorvegliare.",kw={"feralas","gigante guardiano","bambina smarrita","roccia dura","rovine","shay","shay fogliasvelta"},sec={{t="Scomparsa mentre era voltato",b="Roccia Dura ha visto Shay per l'ultima volta mentre camminavano tra le rovine appena a nord del punto in cui si trova. Poi si è voltato e lei era sparita. Non sapendo cosa fare, ti chiede di cercare la sua piccola amica. Le tue gambe possono portarti molto più in fretta delle sue."},{t="Quando la trovi",b="Shay è felice che tu l'abbia trovata. Un po' smarrita, non può comunque fare a meno di commentare quanto sia bello questo posto."}},faq={{q="Chi sta cercando Roccia Dura?",a="Roccia Dura sta cercando Shay, una bambina elfa della Notte e sua amica. Avrebbe dovuto sorvegliarla.",al={"chi è shay","chi è la bambina scomparsa","chi si è perso"}},{q="Dove è stata vista l'ultima volta Shay?",a="Roccia Dura ha visto Shay per l'ultima volta mentre camminavano tra le rovine appena a nord del punto in cui si trova.",al={"dove è andata shay","ultimo luogo di avvistamento","dove sono le rovine"}},{q="Perché Roccia Dura chiede a qualcun altro di cercare?",a="Roccia Dura è preoccupato e non sa cosa fare. Pensa che le tue gambe possano portarti molto più in fretta delle sue.",al={"perché roccia dura non può cercare","perché mandare un avventuriero"}}},fp="18,113,30.241.0,17.109.1,29.102.0,25.87.0,46.99.0"}
P.entries["quest:2845"] = {n="Wandering Shay",s="Shay Fogliasvelta si distrae con ciò che vede lungo il cammino mentre cerca di tornare dall’amico Roccia Dura.",h="Shay Fogliasvelta si distrae con ciò che vede lungo il cammino mentre cerca di tornare dall’amico Roccia Dura.",kw={"scorta","feralas","giant guardian","roccia dura","shay fogliasvelta","campana di shay"},sec={{t="Una ragazza facile alle distrazioni",b="Roccia Dura avrebbe dovuto tenere d’occhio Shay. Lei vuole tornare da lui, ma le tante cose intorno la attirano e la sviano."},{t="La campana nel forziere",b="Una campana nel forziere accanto a Shay attira sempre la sua attenzione, e lei ne custodisce gelosamente il suono. Se si allontana, suonala: promette che tornerà di corsa. Puoi portare la campana all’accampamento di Roccia Dura, dove Shay spera di essere condotta."}},faq={{q="Da chi sta cercando di tornare Shay Fogliasvelta?",a="Shay sta cercando di tornare dall’amico Roccia Dura, che avrebbe dovuto tenerla d’occhio. Puoi accompagnarla al suo accampamento.",al={"chi è roccia dura","amico di shay","dove va shay"}},{q="Perché Shay si allontana vagando?",a="Le tante cose da vedere distraggono Shay, così lei si allontana vagando.",al={"perché shay è persa","come si è persa shay","perché shay si è allontanata"}},{q="Come faccio a evitare che Shay si allontani?",a="La campana di Shay si trova in un forziere accanto a lei, e lei ne custodisce gelosamente il suono. Promette che, se si allontana, suonarla la farà tornare di corsa.",al={"come controllare shay","campana di shay","cosa fa la campana"}},{q="Cosa precede questa missione?",a="The Giant Guardian precede questa missione. Roccia Dura ti manda a cercare Shay lì.",al={"missione precedente","giant guardian","cosa porta a wandering shay"}}},fp="14,106,24.136.0,21.231.0,45.109.0,25.57.0,33.143.0,23.81.0"}
P.entries["quest:285"] = {n="Search More Hovels",s="Tra le capanne dei Murloc non hai trovato traccia della Statuetta di Menethil. Così ti spingi più a nord, in cerca del prossimo indizio.",h="Tra le capanne dei Murloc non hai trovato traccia della Statuetta di Menethil.",kw={"barile","statuetta di menethil","capanne dei murloc","capanne a nord","cercare altre capanne"},sec={{t="Ricerca verso nord",b="Credi che la Statuetta di Menethil si trovi in una delle capanne più a nord. Così continui a cercare tra le dimore dei Murloc."}},faq={{q="Che cosa sto cercando?",a="Stai cercando la Statuetta di Menethil nelle capanne dei Murloc.",al={"ricerca della statuetta","statuetta di menethil","cosa sto cercando"}},{q="La statuetta era in queste capanne?",a="Un’accurata ricerca in questo gruppo di capanne non rivela nulla.",al={"capanne vuote","trovato qualcosa qui","cosa hanno rivelato le capanne"}},{q="Dove potrebbe trovarsi la statuetta?",a="Credi che una delle capanne dei Murloc più a nord possa custodire la Statuetta di Menethil.",al={"dov'è la statuetta","capanne a nord","posizione della statuetta"}}},fp="18,125,16.130.0,24.63.0,36.58.0,29.83.0"}
P.entries["quest:286"] = {n="Return the Statuette",s="Karl Boran al Porto di Menethil ha bisogno che gli venga riportata la Statuetta di Menethil. È stata trovata in un barile tirato fuori dal fango, e il suo ritorno solleverà il capitano della Blind Princess.",h="Karl Boran al Porto di Menethil ha bisogno che gli venga riportata la Statuetta di Menethil.",kw={"barile","blind princess","karl boran","porto di menethil","statuetta di menethil","paladino","statuetta"},sec={{t="La statuetta",b="La statuetta era avvolta in paglia fine dentro il barile. Raffigura un giovane paladino dai capelli lunghi che solleva un martello. Karl Boran al Porto di Menethil la sta aspettando. Il capitano della Blind Princess sarà sollevato nel sapere che il carico è al sicuro."}},faq={{q="Cos'è la Statuetta di Menethil?",a="La Statuetta di Menethil è una statuetta argentata che raffigura un giovane paladino dai capelli lunghi con un martello sollevato.",al={"statuetta","statuetta di menethil","cosa c'è nel barile"}},{q="Dove è stata trovata la statuetta?",a="La statuetta era avvolta in paglia fine dentro un barile tirato fuori dal fango.",al={"statuetta nel barile","dove è stata trovata","barile di paglia"}},{q="Chi aspetta la statuetta?",a="Karl Boran al Porto di Menethil aspetta la Statuetta di Menethil.",al={"chi riceve la statuetta","restituire la statuetta","karl boran"}},{q="Chi sarà sollevato quando verrà restituita?",a="Il capitano della Blind Princess sarà sollevato che il prezioso carico sia stato recuperato.",al={"capitano sollevato","carico della blind princess","chi possiede il carico"}},{q="Cosa raffigura la statuetta?",a="La statuetta raffigura un giovane paladino dai capelli lunghi con un martello sollevato.",al={"chi è raffigurato sulla statuetta","statuetta del paladino","statuetta con martello"}}},fp="20,178,12.235.0,31.103.0,30.76.0,33.68.0,41.94.0,31.72.0"}
P.entries["quest:2862"] = {n="War on the Woodpaw",s="All'Accampamento Mojache, Hadoken Passo Lesto ti chiede di ridurre il numero crescente dei gnoll Woodpaw. I loro attacchi si fanno sempre più accaniti e dieci Crini di Gnoll Woodpaw basteranno per rispondere alla sua chiamata.",h="All'Accampamento Mojache, Hadoken Passo Lesto ti chiede di ridurre il numero crescente dei gnoll Woodpaw.",kw={"alpha strike","accampamento mojache","feralas","gnoll","hadoken passo lesto","crini","woodpaw"},sec={{t="Una minaccia per l'accampamento",b="Hadoken Passo Lesto dice che la sopravvivenza dell'accampamento conta più delle pretese dei gnoll su Feralas. Avverte che, se l'Accampamento Mojache non terrà duro, i gnoll potrebbero scacciarlo dall'intera regione. I loro attacchi si fanno sempre più accaniti, perciò vuole ridurne il numero. Offre una generosa ricompensa per dieci Crini di Gnoll Woodpaw."},{t="La risposta di Hadoken",b="Hadoken Passo Lesto considera i crini un buon inizio. Ha rivolto la stessa richiesta ad altri che hanno già combattuto i gnoll, e un tempo i loro sforzi li avevano tenuti a bada. Ultimamente, i gnoll si sono spinti molto più spesso verso nord, nell'area sotto il controllo dell'Accampamento Mojache. I loro attacchi sono diventati feroci, quasi disperati. Hadoken dice di avere un piano che potrebbe risolvere la questione."}},faq={{q="Chi offre questa ricompensa a Feralas?",a="Hadoken Passo Lesto offre la ricompensa all'Accampamento Mojache.",al={"chi assegna war on the woodpaw","dove consegnare war on the woodpaw","datore di missione war on the woodpaw"}},{q="Perché l'Accampamento Mojache prende di mira i gnoll Woodpaw?",a="Hadoken considera i gnoll Woodpaw un pericolo costante per l'Accampamento Mojache. I loro attacchi si fanno sempre più accaniti e teme che l'accampamento venga scacciato dall'intera regione, se non terrà duro.",al={"perché combattere i woodpaw","problema woodpaw","perché i gnoll attaccano"}},{q="Quale prova richiede Hadoken Passo Lesto?",a="Hadoken Passo Lesto richiede dieci Crini di Gnoll Woodpaw.",al={"oggetti necessari per war on the woodpaw","oggetti missione woodpaw","cosa portare a hadoken"}}},fp="18,182,20.314.0,18.368.1,34.55.0,49.193.0,45.54.0"}
P.entries["quest:2863"] = {n="Alpha Strike",s="La situazione di stallo tra l'Orda e The Woodpaw Gnolls potrebbe sbloccarsi colpendo i loro capi in rapida successione. Hadoken Passo Lesto ti chiede di abbattere cinque Alpha entro un'ora.",h="La situazione di stallo tra l'Orda e The Woodpaw Gnolls potrebbe sbloccarsi colpendo i loro capi in rapida...",kw={"alpha strike","feralas","gnoll","hadoken passo lesto","woodpaw","alpha woodpaw"},sec={{t="Cinque Alpha in un'ora",b="Hadoken Passo Lesto crede che i ranghi di The Woodpaw Gnolls sprofonderanno nel caos se i loro Alpha moriranno uno dopo l'altro. Quei colpi potrebbero anche mostrare ai gnoll che l'Orda può distruggerli. Ti chiede di attuare il piano. Cinque Alpha devono cadere entro un'ora, altrimenti lo stallo continuerà."},{t="In seguito",b="Hadoken Passo Lesto si aspetta che i capi uccisi e i ranghi assottigliati facciano esitare i gnoll prima che assaltino l'accampamento. Deve ancora scoprire cosa li abbia spinti a tanta frenesia. Spera di scoprirlo prima che si riorganizzino."}},faq={{q="Chi fornisce questa missione?",a="Hadoken Passo Lesto ti affida questo incarico mentre affronta lo stallo dell'Orda contro The Woodpaw Gnolls.",al={"chi fornisce alpha strike","hadoken passo lesto","fornitore missione"}},{q="Perché il limite di un'ora?",a="Il piano dipende dal far cadere gli Alpha in rapida successione, per gettare nel caos i ranghi dei gnoll. Cinque devono cadere entro un'ora.",al={"perché un'ora","perché rapida successione","timer alpha strike"}},{q="Cosa sono gli Alpha?",a="Gli Alpha sono capi di The Woodpaw Gnolls, che si definiscono Alpha.",al={"alpha woodpaw","alpha gnoll","chi sono gli obiettivi"}},{q="Quanti Alpha devo uccidere?",a="Devi uccidere cinque Alpha entro un'ora, poi tornare da Hadoken Passo Lesto.",al={"quanti alpha","conteggio alpha"}}},fp="12,179,22.277.0,10.225.1,21.102.0,23.127.0,20.76.0,28.79.0"}
P.entries["quest:2866"] = {n="The Ruins of Solarsal",s="A sud di Shandris Piumaluna, i naga Cresta d'Odio affollano le Rovine di Solarsal. Ti manda tra le antiche pietre a cercare qualcosa di insolito.",h="A sud di Shandris Piumaluna, i naga Cresta d'Odio affollano le Rovine di Solarsal.",kw={"roccaforte di piumaluna","feralas","gazebo","glifi","cresta d'odio","naga","shandris piumaluna","solarsal"},sec={{t="Naga tra le Antiche Pietre",b="Shandris Piumaluna dice che molto tempo fa degli esploratori perlustrarono le rovine, senza trovare nulla di rilevante. Così le pietre furono lasciate in pace. Ora i naga Cresta d'Odio le hanno occupate in numero allarmante. La loro presenza sembrò dapprima annunciare un attacco, e il pericolo non è svanito. Eppure Shandris sospetta che stia accadendo qualcos'altro. Ti chiede di attraversare le rovine e notare tutto ciò che sembra fuori dall'ordinario."},{t="Cosa Risalta",b="Un gazebo è diverso dalle pietre circostanti ed è chiaramente più recente. Piccoli glifi si ripetono lungo i lati, ma nessuno sa da dove provengano o cosa significhino. La pietra è calda al tatto."}},faq={{q="Dove si trovano le Rovine di Solarsal?",a="Le rovine si trovano a sud di Shandris Piumaluna.",al={"posizione rovine di solarsal","dove si trova solarsal","dove trovare solarsal"}},{q="Perché Shandris Piumaluna è preoccupata per le rovine?",a="I naga Cresta d'Odio hanno occupato le rovine in numero allarmante. La loro presenza sembrava dapprima preparare un attacco, e resta una possibilità. Shandris sospetta che stia accadendo qualcos'altro.",al={"perché mandato a solarsal","motivo shandris piumaluna solarsal","perché indagare su solarsal"}},{q="Cosa erano le Rovine di Solarsal prima dell'arrivo dei naga?",a="Le rovine risalgono a prima dei tempi moderni. Shandris dice che molto tempo fa furono esplorate, ma non fu trovato nulla di rilevante, così furono lasciate in pace.",al={"storia di solarsal","cosa è solarsal"}},{q="Quali naga si trovano nelle rovine?",a="I naga Cresta d'Odio si trovano nelle rovine.",al={"chi c'è a solarsal","nemici a solarsal","tribù naga a solarsal"}}},fp="21,151,22.386.0,15.198.1,32.44.0,54.197.0,56.131.0,28.32.0"}
P.entries["quest:2867"] = {n="Return to Feathermoon Stronghold",s="Torni alla Roccaforte di Piumaluna con notizie di uno strano gazebo nel cuore delle Rovine di Solarsal. Il generale Shandris Piumaluna attende il tuo rapporto.",h="Torni alla Roccaforte di Piumaluna con notizie di uno strano gazebo nel cuore delle Rovine di Solarsal.",kw={"roccaforte di piumaluna","feralas","hatecrest","naga","rovine di solarsal","shandris piumaluna","gazebo di solarsal"},sec={{t="Portare il rapporto a casa",b="Alla Roccaforte di Piumaluna, il generale Shandris Piumaluna attende notizie dello strano gazebo. Riporti le tue scoperte dal cuore delle rovine, così che possa sentire cos'hai visto."},{t="Al tuo ritorno",b="Shandris trova inquietante il tuo rapporto sul gazebo. I naga potrebbero non aver avuto intenzione di attaccare, eppure la loro presenza continua è di cattivo auspicio per l'avanzata in Feralas. La Roccaforte di Piumaluna ha bisogno di altro aiuto contro i naga Against the Hatecrest, e Shandris ti offre altro lavoro, se sei disposto."}},faq={{q="A chi devo fare rapporto dopo le rovine?",a="Riferisci al generale Shandris Piumaluna alla Roccaforte di Piumaluna.",al={"a chi devo consegnare questa","chi vuole il rapporto","dove consegnare return to feathermoon stronghold"}},{q="Cosa devo riferire?",a="Parla al generale Shandris Piumaluna dello strano gazebo al centro delle Rovine di Solarsal.",al={"cosa dico a shandris","cosa è stato trovato a solarsal"}},{q="Cosa precede questa missione?",a="Le Rovine di Solarsal sono una tappa precedente al tuo ritorno. Shandris ti ha mandato a esplorare le rovine e a indagare sui naga che vi si trovano.",al={"missione precedente","cosa porta qui"}}},fp="32,154,24.182.0,14.281.1,35.65.0,21.98.0,23.118.0"}
P.entries["quest:2869"] = {n="Against the Hatecrest",s="Alla Roccaforte di Piumaluna, Latronicus Lanciargentea vuole affrontare i naga Hatecrest prima che agiscano. Ti chiede dieci Squame di Hatecrest in buone condizioni.",h="Alla Roccaforte di Piumaluna, Latronicus Lanciargentea vuole affrontare i naga Hatecrest prima che agiscano.",kw={"against the hatecrest","roccaforte di piumaluna","feralas","hatecrest","squama di naga hatecrest","latronicus lanciargentea","naga","isola di sardor"},sec={{t="Agire prima che sia troppo tardi",b="Latronicus Lanciargentea si aspetta che un giorno i naga cerchino di reclamare l’isola. Vuole agire prima che possano farlo, così ti chiede dieci Squame di Hatecrest in buone condizioni. Dovrai scoprire da solo come ottenerle. Spera che raccoglierle indebolisca la presenza dei naga sull’Isola di Sardor e ti faccia assaggiare per la prima volta uno scontro con loro."},{t="Pace e dovere",b="Latronicus dice che gli elfi della notte hanno a cuore la pace e l’armonia, non la guerra. Tuttavia, non lascerà i loro interessi senza protezione. Difenderli è il suo dovere verso il Generale Piumaluna e la Roccaforte."},{t="Dopo",b="Latronicus trova le squame più che soddisfacenti. Ha intenzione di inviarle a Pratt, nel caso si possa ricavarne qualcosa di utile. Ha anche un altro incarico per te."}},faq={{q="Chi assegna questa missione e dove?",a="Latronicus Lanciargentea ti chiede le squame e le riceve alla Roccaforte di Piumaluna.",al={"chi inizia against the hatecrest","posizione latronicus lanciargentea","dove consegnare against the hatecrest"}},{q="Perché Latronicus Lanciargentea vuole le squame di Hatecrest?",a="Latronicus si aspetta che un giorno i naga cerchino di assicurarsi l’Isola di Sardor, quindi vuole agire per primo. Raccogliere squame potrebbe indebolire la loro presenza sull’isola.",al={"perché uccidere gli hatecrest","scopo squama di hatecrest","perché raccogliere squame di naga"}},{q="Quante squame sono necessarie?",a="Ti servono dieci Squame di Hatecrest in buone condizioni.",al={"quante squame","conteggio squame"}},{q="Dove si trovano i naga Hatecrest?",a="Latronicus parla di una presenza naga sull'Isola di Sardor.",al={"posizione hatecrest","dove trovare gli hatecrest","naga dell'isola di sardor"}}},fp="21,174,28.344.0,14.186.0,10.166.1,31.85.0,52.141.0,27.48.0,35.52.0"}
P.entries["quest:287"] = {n="Covo dei Mantogelido",s="Sopra il Lago di Ghiacciospesso, i troll Mantogelido sorvegliano una roccaforte cavernicola tra le vette occidentali. Senir Barbabianca, montanaro ed esploratore a Kharanos, ti manda a esplorarne le profondità e a riportargli informazioni per i suoi rapporti.",h="Sopra il Lago di Ghiacciospesso, i troll Mantogelido sorvegliano una roccaforte cavernicola tra le vette...",kw={"borgo luppolo","dun morogh","cacciatore di teste mantogelido","covo dei mantogelido","troll del ghiaccio","lago di ghiacciospesso","kharanos","senir barbabianca","i rapporti"},ang={["faction:Alliance"]="Come membro dell'Alleanza, contribuisci a mettere al sicuro Dun Morogh e a mantenere libere da imboscate tribali ostili le strade montane che collegano Forgiardente ai regni vicini.",["race:Dwarf"]="Da nano, sai che i troll Mantogelido contendono ai nani di Forgiardente il controllo delle vette innevate di Dun Morogh. Esplorare la loro roccaforte cavernicola principale aiuta a difendere il regno.",["race:Gnome"]="Da gnomo, sai che dopo la caduta di Gnomeregan gli gnomi si sono stabiliti in tutta Dun Morogh e a Kharanos. Contenere gli attacchi dei Mantogelido aiuta a tenere al sicuro le rotte di rifornimento dei rifugiati."},sec={{t="Uno scout in ritardo",b="Senir ha rintracciato le tribù aggressive fino alla loro caverna principale, a sud-ovest di Borgo Luppolo. Troll armati affollano l'ingresso. In ritardo con i suoi rapporti ufficiali, Senir non vuole entrare da solo, quindi ti incarica di esplorare al suo posto la caverna ghiacciata."},{t="Breccia nella caverna",b="Sopra il Lago di Ghiacciospesso, la roccaforte è scavata nelle vette occidentali ed è piena di ostili troll del ghiaccio. Ti fai strada nei tunnel sotterranei, uccidi i cacciatori di teste Mantogelido appostati lungo le sporgenze e mappi l'interno. Le tue scoperte forniscono a Senir le informazioni necessarie per completare il suo rapporto destinato ai comandanti militari di Forgiardente."}},faq={{q="Dove si trova il Covo dei Mantogelido?",a="Il Covo dei Mantogelido si trova a sud-ovest di Borgo Luppolo, in una caverna all'estremità occidentale di Dun Morogh. Da Kharanos, segui la strada verso nord fino al ponte, poi imbocca il fiume ghiacciato verso ovest, supera il Lago di Ghiacciospesso e raggiungi Borgo Luppolo. Da lì, sali verso sud-ovest tra le montagne.",al={"trovare covo dei mantogelido","dove si trova la caverna","posizione covo dei mantogelido"}},{q="Chi è Senir Barbabianca?",a="Senir Barbabianca è un esploratore nano di stanza fuori dalla Distilleria Birratuono, a Kharanos. Tiene d'occhio le minacce in tutta Dun Morogh e scrive rapporti sui troll Mantogelido aggressivi.",al={"senir barbabianca","chi assegna la missione","datore di missione kharanos"}},{q="Perché Senir non ha esplorato il covo da solo?",a="Senir ha esplorato l'ingresso e ha trovato la tribù radunata lì, ma la caverna era piena di troll armati e temeva di entrarvi da solo. Preoccupato per la propria incolumità e in ritardo con le scadenze delle sue ricognizioni, lascia l'esplorazione pericolosa ad avventurieri capaci.",al={"perché senir ha paura","perché senir non ci è andato"}},{q="Chi sono i troll Mantogelido?",a="I Mantogelido sono una tribù di troll del ghiaccio originaria delle creste innevate di Dun Morogh. Acerrimi nemici dei nani di Forgiardente e degli gnomi, spesso razziano rotte commerciali, accampamenti e insediamenti da accampamenti nascosti sparsi per la regione.",al={"mantogelido","troll dun morogh","troll del dun morogh"}},{q="Cosa succede dopo aver completato la ricognizione del covo?",a="Quando torni con notizie sulla disposizione della caverna e sui cacciatori di teste uccisi, Senir completa il suo rapporto. Ti chiede di consegnare i documenti urgenti ai suoi superiori a Dun Morogh.",al={"prossima missione","cosa dopo covo dei mantogelido","missione i rapporti"}},{q="Quanto in profondità nella caverna bisogna andare?",a="Esplora oltre l'ingresso, ricognisci le camere interne e uccidi cinque cacciatori di teste Mantogelido. Le loro morti confermano che le profondità della caverna sono state esplorate a fondo.",al={"esplorare completamente covo dei mantogelido","attivazione esplorazione caverna"}}},fx={["889a57f0"]={q="Perché Senir Barbabianca vuole che venga esplorato il Covo dei Mantogelido?",a="Senir Barbabianca è un agente incaricato di redigere rapporti d'intelligence sulle minacce sempre più pressanti di Dun Morogh. È rimasto indietro con i suoi compiti di ricognizione e ha bisogno di informazioni di prima mano sull'accampamento dei troll Mantogelido per completare la sua valutazione per il comando di Forgiardente prima che i superiori se ne accorgano.",al={"perché senir vuole che venga fatto","motivazioni di senir barbabianca","perché esplorare il covo dei mantogelido"}},["860fac70"]={q="Perché devi affrontare i Cacciatori di Teste Mantogelido?",a="I Cacciatori di Teste Mantogelido costituiscono la difesa militante del Covo dei Mantogelido, le profonde caverne a sudovest del Borgo Luppolo dove i troll sfollati si sono radunati in forze. Ucciderli riduce le loro pattuglie e apre la strada per esplorare a fondo le caverne.",al={"chi sono i cacciatori di teste mantogelido","perché uccidere i cacciatori di teste","scopo dei cacciatori di teste mantogelido"}}},fp="14,214,23.234.0,20.334.0,32.263.0,24.184.0,42.249.0,29.225.0,52.176.1,41.175.0"}
P.entries["quest:2870"] = {n="Against Lord Shalzaru",s="Alla Roccaforte di Piumaluna, Latronicus Lanciargentea ti chiede di fermare Sire Shalzaru e recuperare la reliquia che ha trovato.",h="Alla Roccaforte di Piumaluna, Latronicus Lanciargentea ti chiede di fermare Sire Shalzaru e recuperare la...",kw={"roccaforte di piumaluna","feralas","hatecrest","isola del terrore","latronicus lanciargentea","sire shalzaru","reliquia misteriosa","naga","shalzaru"},sec={{t="La catena di comando naga",b="Latronicus Lanciargentea ha nuovi rapporti sulla catena di comando dei naga. I reali impartiscono ordini tra le loro fila. Sire Shalzaru è uno dei reali più crudeli."},{t="Una strana reliquia",b="Gli esploratori dicono che Sire Shalzaru ha rinvenuto una strana reliquia mentre i naga scavavano in una grotta sull'Isola del Terrore. La grotta si trova oltre l'acqua, a sud delle rovine principali. Latronicus vuole che fermi Shalzaru e ponga fine allo Scavo. Poi porta la Reliquia Misteriosa alla Roccaforte di Piumaluna perché venga studiata."},{t="Quando sarà finita",b="Latronicus crede che la caduta di Sire Shalzaru possa lasciare i naga nel caos per un po', forse per sempre. Pensa che la minaccia sia ora più sotto controllo che mai. Ha un'altra cosa da chiederti."}},faq={{q="Chi è Sire Shalzaru?",a="Sire Shalzaru è uno dei reali naga più crudeli. I reali impartiscono ordini tra le fila dei naga.",al={"shalzaru","chi è shalzaru","storia di sire shalzaru"}},{q="Dove si trova Sire Shalzaru?",a="Gli esploratori hanno localizzato lo Scavo di Sire Shalzaru in una grotta sull'Isola del Terrore, oltre l'acqua e a sud delle rovine principali.",al={"dove si trova shalzaru","posizione grotta di shalzaru","trovare shalzaru"}},{q="Cos'è la reliquia?",a="La Reliquia Misteriosa è uno strano oggetto rinvenuto da Sire Shalzaru mentre i naga scavavano. Latronicus vuole che tu gliela porti perché possa studiarla.",al={"reliquia misteriosa feralas","cos'è la reliquia","reliquia di shalzaru"}},{q="Dove devo consegnare la reliquia?",a="Porta la reliquia a Latronicus Lanciargentea alla Roccaforte di Piumaluna.",al={"chi riceve la reliquia","consegna shalzaru"}}},fp="21,110,25.150.0,12.277.0,15.198.1,21.93.0,31.108.0,18.141.0,29.66.0"}
P.entries["quest:2871"] = {n="Delivering the Relic",s="Alla Roccaforte di Piumaluna, Latronicus Lanciargentea ti affida la Reliquia Misteriosa da portare a sua moglie Vestia. Non riesce a capirla e spera che lei possa dirgli di cosa si tratta.",h="Alla Roccaforte di Piumaluna, Latronicus Lanciargentea ti affida la Reliquia Misteriosa da portare a sua...",kw={"delivering the relic","roccaforte di piumaluna","feralas","latronicus lanciargentea","reliquia misteriosa","vestia lanciargentea"},sec={{t="L'occhio di uno studioso",b="Latronicus Lanciargentea non riesce a capire il congegno, scommessa o no. Dice che sua moglie Vestia è un'eccellente sacerdotessa per la loro comunità e una delle studiose più erudite che ci siano. Se qualcuno può scoprire cos'è la reliquia, è lei. Devono saperlo. Vestia è a pochi passi, anche se di certo sarà impegnata a studiare."},{t="Il primo esame di Vestia",b="Vestia Lanciargentea sa che hai aiutato il Generale Piumaluna e Latro contro i naga. A prima vista, la reliquia non sembra provenire dalle rovine in cui è stata trovata, né presenta motivi naga. È qualcosa di molto più alieno. Ci vorrà del tempo per studiarla. Quando avrà finito, potrebbe chiedere il tuo aiuto se sarai nei paraggi."}},faq={{q="Chi è Vestia Lanciargentea?",a="Vestia Lanciargentea è la moglie di Latronicus Lanciargentea. Lui la considera un'eccellente sacerdotessa per la loro comunità e una delle studiose più erudite che ci siano. Si trova alla Roccaforte di Piumaluna.",al={"vestia lanciargentea","chi è vestia","moglie di latro"}},{q="Da dove proviene la Reliquia Misteriosa?",a="La Reliquia Misteriosa è quella che Sire Shalzaru ha scoperto mentre i naga scavavano in una grotta sull'Isola del Terrore.",al={"da dove proviene la reliquia","origine reliquia","fonte reliquia misteriosa"}},{q="Cosa sa Latronicus Lanciargentea della reliquia?",a="Latronicus Lanciargentea sa poco della reliquia. Non riesce a venirne a capo, perciò vuole che sua moglie la esamini.",al={"cosa sa latronicus","congegno di latro"}},{q="Dove devo portare la reliquia?",a="Porta la Reliquia Misteriosa a Vestia Lanciargentea, alla Roccaforte di Piumaluna. Latronicus dice che si trova proprio dietro l'angolo.",al={"chi riceve la reliquia","destinazione di delivering the relic"}}},fp="20,166,15.322.0,19.325.1,24.178.0,42.116.0,52.131.0,26.117.0"}
P.entries["quest:2872"] = {n="Stoley's Debt",s="Al Porto degli Spargifumo, il «Lupo di Mare» MacKinley vuole il rum che Stoley ha scommesso con lui. Ti chiede di parlarne con l’oste.",h="Al Porto degli Spargifumo, il «Lupo di Mare» MacKinley vuole il rum che Stoley ha scommesso con lui.",kw={"rum di sentina","baia del bottino","mackinley","rum","porto degli spargifumo","stoley","tanaris","scommessa"},sec={{t="Questione di rum e monete",b="Il «Lupo di Mare» MacKinley dice che Stoley gli deve una bottiglia speciale di rum. Stoley si era vantato che il rum del Porto degli Spargifumo fosse più forte di qualsiasi rum a Baia del Bottino. Aveva promesso di raddoppiare il denaro che deve a MacKinley se questi l’avesse assaggiato e non fosse stato d’accordo.\n\nOra MacKinley pensa che Stoley abbia perso il coraggio di consegnargli la bottiglia. Ma MacKinley non si tira mai indietro davanti a una scommessa, perciò ti chiede di parlare con Stoley al bar del Porto degli Spargifumo."},{t="La risposta di Stoley",b="Stoley dice di non avere paura di consegnare il Rum di Sentina degli Spargifumo. Ma non è rimasto rum da dare."}},faq={{q="Chi è il \"Lupo di Mare\" MacKinley?",a="Il «Lupo di Mare» MacKinley è un vecchio amico di Stoley. Hanno scommesso su quale dei loro rum sia più forte.",al={"chi è mackinley","lupo di mare mackinley","chi dà il debito di stoley"}},{q="Dove si trova Stoley?",a="Stoley gestisce il bar del Porto degli Spargifumo, a Tanaris.",al={"dove si trova stoley","posizione di stoley","trova stoley"}},{q="Che scommessa ha fatto Stoley con MacKinley?",a="Che il rum del Porto degli Spargifumo batta qualsiasi rum a Baia del Bottino. Stoley giurò che fosse più forte e promise a MacKinley il doppio del denaro che gli doveva, se MacKinley l’avesse assaggiato e non fosse stato d’accordo.",al={"qual è la scommessa","che scommessa","scommessa di stoley"}}},fp="13,133,24.434.0,15.99.1,28.96.0,24.53.0,40.171.0"}
P.entries["quest:2873"] = {n="Spedizione di Stoley",s="Stoley ha finito il rum e ti chiede di recuperare la sua spedizione rubata. Il Capitano Cuergo la tiene a Cala del Sartiame, la città fortificata dei pirati a sud.",h="Stoley ha finito il rum e ti chiede di recuperare la sua spedizione rubata.",kw={"cuergo","cala del sartiame","mackinley","rum","spedizione","porto degli spargifumo","stoley","tanaris"},sec={{t="Una spedizione rubata",b="Stoley deve del rum a “Lupo di Mare” MacKinley di Baia del Bottino per la loro scommessa, ma ha esaurito le scorte. Il Capitano Cuergo ha preso l'ultima spedizione e la tiene a Cala del Sartiame, la città fortificata dei pirati a sud. Stoley vuole che tu riporti il rum, così potrà dimostrare che la bevanda di Kalimdor è migliore di qualsiasi cosa servano a Baia del Bottino."},{t="Dove è custodita",b="I pirati tengono il rum in casse al piano superiore della casa a nord-ovest."}},faq={{q="Chi è Stoley?",a="Stoley si trova al Porto degli Spargifumo, a Tanaris. Deve del rum a “Lupo di Mare” MacKinley di Baia del Bottino per saldare la loro scommessa.",al={"stoley","chi assegna stoleys shipment","stoley tanaris"}},{q="Perché Stoley vuole indietro la sua spedizione?",a="Il Capitano Cuergo ha rubato l'ultima spedizione di rum di Stoley. Stoley ne ha bisogno per saldare la scommessa con MacKinley e dimostrare che i liquori di Kalimdor battono quelli di Baia del Bottino.",al={"perché rum","motivazione di stoley","cos'è stoleys shipment"}},{q="Dove hanno nascosto il rum i pirati?",a="I pirati tengono il rum in casse al piano superiore della casa a nord-ovest a Cala del Sartiame, la città fortificata dei pirati a sud.",al={"posizione rum di stoley","dove si trova la spedizione","rum di cala del sartiame"}},{q="Chi è il Capitano Cuergo?",a="Il Capitano Cuergo ha rubato l'ultima spedizione di rum di Stoley e la tiene nella città fortificata dei pirati a sud.",al={"cuergo","capitano cuergo"}},{q="Dove si colloca questa fase nella catena?",a="È la continuazione di Stoley's Debt.",al={"catena di stoleys shipment","cosa segue stoley's debt"}},{q="Chi è il \"Lupo di Mare\" MacKinley?",a="“Lupo di Mare” MacKinley si trova a Baia del Bottino. Ha scommesso con Stoley su quale dei loro rum sia migliore.",al={"lupo di mare mackinley","mackinley baia del bottino"}}},fp="17,147,17.318.0,16.84.0,14.113.0,39.149.0,35.137.0,22.102.0,38.27.0,28.90.0"}
P.entries["quest:2874"] = {n="Deliver to MacKinley",s="Al Porto degli Spargifumo, Stoley ti dà del rum di sentina per MacKinley, a Baia del Bottino. Il Lupo di Mare può giudicare se la bevanda gli farà cambiare idea sugli alcolici di Baia del Bottino.",h="Al Porto degli Spargifumo, Stoley ti dà del rum di sentina per MacKinley, a Baia del Bottino.",kw={"baia del bottino","mackinley","lupo di mare mackinley","rum di sentina degli spargifumo","stoley","stoley's debt","spedizione di stoley","tanaris"},sec={{t="Una Bottiglia da Trasportare",b="Dopo che aiuti con la spedizione, Stoley ti dà una bottiglia di rum di sentina degli Spargifumo. La porti a MacKinley, a Baia del Bottino, dove finalmente potrà accantonare le sue convinzioni sugli alcolici del posto."},{t="Il Verdetto di MacKinley",b="MacKinley assaggia il rum e si delizia della sua orribile qualità. Stoley ha mantenuto la parola sul rum di sentina, quindi MacKinley non deve pagare il denaro che gli deve. Lo definisce denso come la ghiaia e bruciante come la lava."}},faq={{q="Chi ti consegna la bottiglia?",a="Stoley ti consegna la bottiglia al Porto degli Spargifumo.",al={"chi inizia deliver to mackinley","donatore missione deliver to mackinley"}},{q="Chi riceve la bottiglia di rum?",a="La bottiglia va al “Lupo di Mare” MacKinley, a Baia del Bottino.",al={"dove porto la bottiglia","chi riceve il rum","posizione di mackinley"}},{q="Che tipo di alcolico viene consegnato?",a="Una bottiglia di rum di sentina degli Spargifumo.",al={"che rum è","quale alcolico dà stoley"}},{q="Dove si colloca questo passaggio nella catena?",a="Questo fa seguito a Stoley's Debt e Stoley's Shipment.",al={"cosa precede deliver to mackinley","catena missioni deliver to mackinley"}}},fp="20,160,17.192.0,19.193.1,25.49.0,31.57.0,40.35.0,38.49.0"}
P.entries["quest:2875"] = {n="WANTED: Andre Firebeard",s="A Meccania e al Porto degli Spargifumo, un avviso di taglia nomina Andre Firebeard e lo accusa di crimini contro entrambi i luoghi. Consegna la sua testa al Capo della Sorveglianza Segachiodi al Porto degli Spargifumo: varrà come contratto vincolante.",h="A Meccania e al Porto degli Spargifumo, un avviso di taglia nomina Andre Firebeard e lo accusa di crimini...",kw={"andre firebeard","segachiodi","meccania","enclave dei pirati","porto degli spargifumo","tanaris","avviso di taglia"},sec={{t="Il decreto",b="Un avviso condanna Andre Firebeard come un vile pirata, accusato di crimini contro gli Steamwheedle e Meccania. Il consiglio direttivo autorizza chiunque legga l'avviso a usare la forza letale per catturare Andre e chiunque lo aiuti. Si trova nell'enclave dei pirati, lungo la costa a sud del Porto degli Spargifumo, accanto a un falò dentro le mura."},{t="La testa come procura",b="Un ulteriore decreto stabilisce che la testa di Andre può parlare per lui se è morto o comunque impossibilitato a presentarsi all'udienza. Consegnala al Capo della Sorveglianza Segachiodi al Porto degli Spargifumo: varrà come contratto vincolante."},{t="Termini di pagamento",b="Segachiodi è lieto che Andre si presenti comunque al processo. Il pagamento arriverà dopo la tua firma. Liquida le clausole scritte in piccolo come innocue e dice che sono troppo piccole perché si possano leggere con qualsiasi lente d'ingrandimento."}},faq={{q="Chi è Andre Firebeard?",a="Andre Firebeard è un pirata accusato di crimini contro gli Steamwheedle e Meccania.",al={"andre firebeard","chi è andre","firebeard tanaris"}},{q="Dove si può trovare l'avviso di taglia?",a="L'avviso di taglia è affisso a Meccania e al Porto degli Spargifumo.",al={"dove ottenere la missione","posizione avviso di taglia","avviso di taglia andre firebeard"}},{q="Dov'è localizzato Andre Firebeard?",a="Andre Firebeard si trova accanto a un falò, dentro le mura dell'enclave dei pirati lungo la costa a sud del Porto degli Spargifumo.",al={"posizione firebeard","dov'è firebeard","trovare andre firebeard"}},{q="Chi riceve la testa una volta che Andre è stato sistemato?",a="Il Capo della Sorveglianza Segachiodi riceve la testa al Porto degli Spargifumo.",al={"a chi consegnare firebeard","posizione segachiodi","dove consegnare la testa di firebeard"}},{q="Perché è richiesta la sua testa?",a="Un decreto permette alla testa di agire al posto di Andre se è morto o comunque impossibilitato a presentarsi all'udienza.",al={"perché la sua testa","testa come procura","procura per il processo"}}},fp="23,227,10.338.0,17.205.0,16.193.1,23.81.0,37.66.0,33.117.0,47.67.0,25.100.0"}
P.entries["quest:2876"] = {n="Ship Schedules",s="Al Porto degli Spargifumo, alcuni viaggi sono segnati sulla tabella di marcia delle navi. Dovrebbe essere nelle mani di qualcuno con autorità sul posto.",h="Al Porto degli Spargifumo, alcuni viaggi sono segnati sulla tabella di marcia delle navi.",kw={"segachiodi","baia del bottino","pirati","ship schedules","porto degli spargifumo","tanaris"},sec={{t="La pergamena",b="Le navi salpano tra il Porto degli Spargifumo e la Baia del Bottino, e la pergamena le elenca tutte. Registra i viaggi già compiuti e quelli ancora da fare. Alcuni sono segnati da grandi X. Le note accanto ad altri avvertono di saccheggi o di duri combattimenti. Qualcuno con autorità al Porto degli Spargifumo ha bisogno della tabella di marcia."},{t="La reazione del porto",b="Il Capo della Sorveglianza Segachiodi controlla la tabella di marcia e trova esatte le date e gli orari. Teme ciò che un capitano pirata potrebbe fare con queste informazioni. Quando gli dici che l'hai presa a un pirata, Segachiodi definisce la notizia inquietante e ti ringrazia. È contento che il pirata sia morto."}},faq={{q="Cosa c'è scritto sulla tabella di marcia?",a="La tabella di marcia elenca le navi e registra i viaggi passati e futuri tra il Porto degli Spargifumo e la Baia del Bottino. Alcuni sono segnati da grandi X, mentre altre note menzionano saccheggi o duri combattimenti.",al={"cosa dice la tabella di marcia delle navi","testo tabella di marcia navi","note sulle spedizioni"}},{q="Chi deve vedere questo documento?",a="Qualcuno con autorità al Porto degli Spargifumo ha bisogno della tabella di marcia. La prende il Capo della Sorveglianza Segachiodi.",al={"a chi devo dare la tabella di marcia","consegna tabella di marcia navi","dove va la tabella di marcia"}}},fp="14,111,10.289.0,19.279.1,32.185.0,31.99.0"}
P.entries["quest:2877"] = {n="Skulk Rock Clean-up",s="Fanghiglie e melme hanno invaso le vecchie posizioni dell’Orda intorno al Tumulo Strisciante. Fraggar Mantotonante, al Picco dell’Aquila, vuole che tu le elimini: i Martello Selvaggio hanno progetti per quel terreno.",h="Fanghiglie e melme hanno invaso le vecchie posizioni dell’Orda intorno al Tumulo Strisciante.",kw={"picco dell'aquila","fraggar mantotonante","fanghiglia verde","entroterre","melma di giada","tumulo strisciante","martello selvaggio"},sec={{t="Una questione di territorio",b="I Martello Selvaggio ricordano il passato più dei loro fratelli di Forgiardente. Fraggar Mantotonante dice che qui gli amici si fanno sporcandosi le mani. L’Orda ha lasciato le sue posizioni intorno al Tumulo Strisciante, nelle Entroterre, e fanghiglie e melme le hanno invase. I Martello Selvaggio hanno progetti per quel terreno, ma prima bisogna ridurre l’infestazione."},{t="Liberare il terreno",b="Uccidi dieci fanghiglie verdi e dieci melme di giada. Poi torna da Fraggar al Picco dell’Aquila e riferiscigli com’è andata."}},faq={{q="Chi è Fraggar Mantotonante?",a="Fraggar Mantotonante è un Martello Selvaggio che si trova al Picco dell’Aquila, nelle Entroterre. Vuole che il Tumulo Strisciante venga ripulito.",al={"chi assegna la pulizia del tumulo strisciante","fraggar mantotonante"}},{q="Perché i Martello Selvaggio vogliono che il Tumulo Strisciante venga ripulito?",a="L’Orda ha lasciato le sue posizioni intorno al Tumulo Strisciante, e fanghiglie e melme le hanno invase. I Martello Selvaggio hanno progetti per la zona, ma prima bisogna ridurre l’infestazione.",al={"perché uccidere le melme","piani dei martello selvaggio per il tumulo strisciante"}},{q="Quali creature abitano il Tumulo Strisciante?",a="Fanghiglie verdi e melme di giada hanno invaso le vecchie posizioni dell’Orda al Tumulo Strisciante.",al={"creature al tumulo strisciante","cosa c'è al tumulo strisciante"}},{q="Perché Fraggar menziona Forgiardente?",a="Fraggar dice che i Martello Selvaggio ricordano il passato più dei loro fratelli di Forgiardente. Dice che qui gli amici si fanno sporcandosi le mani.",al={"differenza tra martello selvaggio e forgiardente","fraggar forgiardente"}}},fp="19,173,21.348.0,19.97.0,29.100.0,47.172.0,35.80.0,36.147.0"}
P.entries["quest:2879"] = {n="The Stave of Equinex",s="Alle Rovine di Corvovento, Troyas Brezzaluna mette alla prova il suo bastone per vedere se può aprire il Monolite di Equinex. Raccogli le essenze di quattro fiamme che ardono ancora tra le rovine.",h="Alle Rovine di Corvovento, Troyas Brezzaluna mette alla prova il suo bastone per vedere se può aprire il...",kw={"byltan","albero dei sogni","monolite di equinex","feralas","imbel","lahassa","rovine di corvovento","samha","bastone di equinex","troyas brezzaluna"},sec={{t="Una chiave per il monolite",b="Troyas Brezzaluna pensa che il suo bastone possa essere il Bastone di Equinex, una chiave per il Monolite di Equinex nelle Rovine di Corvovento. Lì ardono ancora quattro fiamme: Samha, Imbel, Byltan e Lahassa. Ognuna cede un'essenza. Le usi tutte e quattro presso il monolite per energizzare il bastone. Se è davvero la chiave, il monolite si aprirà e rivelerà un artefatto sacro."},{t="Presso la pietra",b="Il bastone energizzato è quasi impossibile da tenere mentre il suo potere ti attraversa con un rombo. Allunghi la mano verso la fredda superficie del monolite e una piccola porta si apre. Raggi di luce si riversano attorno alla pietra mentre prendi ciò che si trova all'interno."}},faq={{q="Dove si trova il Monolite di Equinex?",a="Il Monolite di Equinex si trova nelle Rovine di Corvovento, a ovest dell'Albero dei Sogni, sulla terraferma.",al={"posizione monolite di equinex","dov'è il monolite","trovare il monolite di equinex"}},{q="Quali sono le quattro fiamme di cui ho bisogno?",a="Le quattro fiamme sono Samha, Imbel, Byltan e Lahassa. Ardono ancora nelle Rovine di Corvovento e raccogli l'essenza di ognuna.",al={"quattro fiamme","nomi fiamme feralas","fiamme di corvovento"}},{q="A cosa serve il Bastone di Equinex?",a="Troyas Brezzaluna dice che il Bastone di Equinex potrebbe essere la chiave per il Monolite di Equinex, che custodisce un artefatto sacro.",al={"cosa fa il bastone","scopo del bastone di equinex","perché energizzare il bastone"}},{q="Dove devo energizzare il bastone?",a="Energizzi il bastone accanto al Monolite di Equinex usando le essenze di tutte e quattro le fiamme.",al={"dove usare le essenze","posizione energizzazione bastone"}}},fp="20,169,22.341.0,12.217.1,38.95.0,32.132.0,33.112.0,30.90.0"}
P.entries["quest:288"] = {n="The Third Fleet",s="Fuori dalla Locanda Acquefonde, il Primo Ufficiale Fitzsimmons affoga i ricordi della Third Fleet nell’alcol. Fu l’unico a sopravvivere al suo incendio al largo delle Paludi Grigie durante la Seconda Guerra.",h="Fuori dalla Locanda Acquefonde, il Primo Ufficiale Fitzsimmons affoga i ricordi della Third Fleet nell’alcol.",kw={"locanda acquefonde","flotta dannata","fauce del drago","fitzsimmons","kul tiras","porto di menethil","draghi rossi","third fleet","wave mistress","paludi grigie"},ang={["faction:Alliance"]="Da difensore dell’Alleanza, nel racconto di Fitzsimmons sulla Wave Mistress senti le cicatrici lasciate dai cavalcadraghi dell’Orda in tutta Khaz Modan.",["race:Dwarf"]="Da nano, sai che Grim Batol proiettava la sua ombra su Khaz Modan. I draghi allevati nelle sue profondità devastarono le terre dei nani e quelle degli alleati umani.",["race:Human"]="Da umano, puoi ricordare la distruzione della Third Fleet come una ferita amara nelle battaglie navali combattute da Kul Tiras e dall’Alleanza contro Fauce del Drago."},sec={{t="Il dolore di un marinaio",b="Il Primo Ufficiale Fitzsimmons trascorre le sue giornate fuori dalla Locanda Acquefonde, a Porto di Menethil. Combatte i postumi di una sbornia e ricordi che non gli danno pace. Un tempo prestava servizio sulla Wave Mistress, una nave da guerra della flotta di Kul Tiras. Ora si consola con l’idromele nanico, e un altro boccale potrebbe spingerlo a raccontare un terribile massacro navale."},{t="Fuoco sulle onde",b="Durante la Seconda Guerra, la Third Fleet navigava lungo le coste di Khaz Modan quando il fuoco piovve dal cielo. Il clan Fauce del Drago aveva sottomesso lo stormo dei draghi rossi a Grim Batol e scatenò il fuoco draconico sulle navi da guerra ignare. Fitzsimmons ricorda gli scafi di legno avvolti da fiamme altissime e gli equipaggi trascinati negli abissi. Fu l’unico a sopravvivere e ad approdare a riva. I suoi fratelli caduti giacciono nel cimitero marino noto come Flotta Dannata."}},faq={{q="Chi è il Primo Ufficiale Fitzsimmons?",a="Il Primo Ufficiale Fitzsimmons è un vecchio marinaio che beve fuori dalla Locanda Acquefonde, a Porto di Menethil, per attenuare il trauma. Un tempo prestava servizio sulla nave da guerra di Kul Tiras Wave Mistress ed è l’unico superstite noto della distruzione della Third Fleet.",al={"fitzsimmons","chi è il marinaio ubriaco","fitzsimmons locanda"}},{q="Cosa è successo alla The Third Fleet?",a="Durante la Seconda Guerra, il clan Fauce del Drago tese un’imboscata alla Third Fleet di Kul Tiras al largo delle Paludi Grigie e la incendiò. Gli orchi in groppa ai draghi riversarono fuoco dal cielo, trascinando navi e marinai sul fondo del mare.",al={"destino third fleet","come è affondata la flotta","navi di kul tiras affondate"}},{q="Perché i draghi attaccavano le navi umane?",a="Durante la Seconda Guerra, il clan Fauce del Drago schiavizzò la draga rossa Alexstrasza con l’Anima del Demone, nella vicina Grim Batol. Vincolati da una magia oscura, i draghi rossi furono costretti a servire l’Orda come cavalcature e armi d’assedio.",al={"draghi fauce del drago","draghi rossi paludi","perché orchi sui draghi"}},{q="Dove sono affondate esattamente le navi?",a="I relitti carbonizzati giacciono sotto il mare, al largo della costa occidentale delle Paludi Grigie, a nord di Porto di Menethil. La zona è ricordata come la Flotta Dannata.",al={"dov'è la flotta dannata","posizione del naufragio nelle paludi grigie","relitti third fleet"}},{q="Che bevanda vuole Fitzsimmons?",a="Fitzsimmons vuole un boccale d’idromele nanico per calmare il mal di testa e sciogliersi la lingua. Lo vende l’oste dentro la Locanda Acquefonde.",al={"idromele per fitzsimmons","cosa vuole fitzsimmons","boccale di idromele"}},{q="Quale nazione serviva la The Third Fleet?",a="La Third Fleet serviva Kul Tiras, un regno insulare la cui formidabile marina costituiva la spina dorsale delle forze navali dell’Alleanza durante la Seconda Guerra.",al={"la third fleet è di roccavento","flotta di kul tiras","chi possedeva la wave mistress"}}},fx={["03818f34"]={q="Perché Primo Ufficiale Fitzsimmons vuole da bere?",a="Fitzsimmons è l'unico sopravvissuto a un terribile massacro, tormentato dall'incendio della sua flotta e alle prese con una terribile sbornia. Gli fa così male la testa che non riesce a raccontare la tragedia della Terza Flotta senza un liquore forte che gli attenui il dolore e gli sciolga la lingua. Solo una caraffa d'idromele riuscirà a farlo parlare.",al={"motivazioni di fitzsimmons","perché fitzsimmons vuole l'idromele","perché aiutare fitzsimmons"}},["53fbd504"]={q="Perché Fitzsimmons ha bisogno che tu gli prenda l'idromele?",a="Fitzsimmons è un sopravvissuto distrutto e indigente, immerso nell'autocommiserazione e nel dolore proprio fuori dalla taverna. Tormentato da una sbornia tremenda e avendo probabilmente speso fino all'ultimo rame, non ha né i mezzi né la forza per arrivare al bancone da solo, così è costretto a chiedere l'elemosina agli avventurieri di passaggio.",al={"perché fitzsimmons non può comprarsi da bere","perché chiedere a me l'idromele","perché fitzsimmons ha scelto me"}}},fp="15,166,16.342.0,19.450.0,30.241.0,33.197.0,39.218.0,34.141.0,33.148.0,38.147.0"}
P.entries["quest:2880"] = {n="Troll Necklace Bounty",s="A Picco dell'Aquila, Fraggar Mantotonante ti chiede di portargli cinque collane dei troll delle Entroterre.",h="A Picco dell'Aquila, Fraggar Mantotonante ti chiede di portargli cinque collane dei troll delle Entroterre.",kw={"picco dell'aquila","taglia","fraggar mantotonante","entroterre","collana tribale dei troll","troll","granmartello"},sec={{t="Guadagnarsi la stima dei Granmartello",b="Fraggar Mantotonante si fida dei fatti più che delle parole. I Granmartello non rispondono ad alcuna Alleanza e chi cerca la loro amicizia deve prima dimostrare il proprio valore. I troll che vagano per i pendii delle Entroterre talvolta indossano collane tribali. Portane cinque a Fraggar a Picco dell'Aquila e avrai fatto il primo passo."}},faq={{q="Perché Fraggar Mantotonante vuole le collane dei troll?",a="Fraggar giudica le persone dai fatti, non dalle parole. Cinque collane dei troll sono un buon inizio per chi cerca l'amicizia dei Granmartello.",al={"perché collane dei troll","scopo taglia collane dei troll","perché fraggar vuole le collane"}},{q="I Granmartello fanno parte dell'Alleanza?",a="Fraggar dice che i Granmartello sono indipendenti e non rispondono ad alcuna Alleanza. Giudicano le persone dai fatti.",al={"granmartello alleanza","picco dell'aquila alleanza","fedeltà granmartello"}},{q="Dove si possono trovare le collane tribali dei troll?",a="I troll che vagano per i pendii delle Entroterre talvolta portano collane tribali.",al={"dove trovare collana tribale dei troll","posizione collana dei troll","come ottenere le collane dei troll"}},{q="A chi devo consegnare le collane?",a="Porta le cinque collane a Fraggar Mantotonante a Picco dell'Aquila.",al={"chi riceve le collane dei troll","consegnare a fraggar mantotonante","dove si trova fraggar mantotonante"}}},fp="21,105,25.294.0,52.139.0,41.105.0,42.74.0,33.64.0"}
P.entries["quest:2881"] = {n="Troll Necklace Bounty",s="Per Fraggar Mantotonante, le collane tribali dei troll si consegnano ancora in lotti da cinque. Il Granmartello ne ha già accettato un lotto da te e l'offerta è ancora valida.",h="Per Fraggar Mantotonante, le collane tribali dei troll si consegnano ancora in lotti da cinque.",kw={"fraggar mantotonante","entroterre","collana tribale","troll necklace bounty","troll","granmartekko"},sec={{t="Un'offerta sempre valida",b="Fraggar Mantotonante accetta volentieri altre collane tribali dei troll quando le trovi e decidi di consegnargliele. Dice che i Granmartello combatteranno per chi combatte per loro. Ogni lotto deve contenere cinque collane."},{t="L'approvazione di Fraggar",b="Fraggar Mantotonante è lieto quando gli porti le collane. Per lui dimostrano che sei disposto a sporcarti le mani, una qualità che i Granmartello apprezzano."}},faq={{q="Chi vuole le collane tribali dei troll?",a="Fraggar Mantotonante parla a nome dei Granmartello.",al={"chi assegna questa taglia","ruolo di fraggar mantotonante","chi prende le collane"}},{q="Quante collane tribali dei troll sono necessarie?",a="Cinque alla volta. Fraggar conta un lotto solo quando contiene cinque collane.",al={"conteggio collane","quante collane","requisito taglia"}},{q="Perché Fraggar Mantotonante raccoglie queste collane?",a="Fraggar considera le collane una prova che sei disposto a combattere per i Granmartello. Dice che loro combatteranno per chi lo fa.",al={"perché le collane dei troll","motivazione granmartello","scopo della taglia"}},{q="Cosa è successo prima di questa taglia?",a="Hai già completato la prima Troll Necklace Bounty per Fraggar Mantotonante.",al={"missione prerequisito","passo precedente","taglia precedente"}}},fp="21,164,16.213.0,18.159.1,37.49.0,43.73.0,55.130.0,29.80.0"}
P.entries["quest:289"] = {n="The Cursed Crew",s="Al largo delle coste delle Paludi Grigie, la Cursed Crew infesta le navi dove naufragò la Third Fleet di Kul Tiras. Il Primo Ufficiale Fitzsimmons, unico sopravvissuto della flotta, chiede ai viaggiatori di liberare i suoi compagni perduti. Una reliquia oscura a bordo di un relitto tiene i marinai e i fanti annegati legati alle loro navi come non morti inquieti.",h="Al largo delle coste delle Paludi Grigie, la Cursed Crew infesta le navi dove naufragò la Third Fleet di Kul...",kw={"the cursed crew","fante maledetto","marinaio maledetto","fitzsimmons","kul tiras","menethil","snellig","scatola di tabacco","the third fleet","paludi grigie"},ang={["class:Paladin"]="Come paladino, puoi dare pace ai marinai innocenti e purificare la profanazione sacrilega che li ha colpiti. Porta la luce in queste acque oscure.",["faction:Alliance"]="Come viaggiatore dell'Alleanza, condividi il solenne dovere di dare pace a questi marinai Kul Tirani tormentati. Kul Tiras ha fornito a lungo i suoi migliori marinai alla Grande Alleanza.",["race:Human"]="Come viaggiatore umano, potresti sentirti legato a questi marinai caduti dalle tradizioni navali condivise con Kul Tiras."},sec={{t="Una Flotta Inquieta",b="La Third Fleet di Kul Tiras naufragò lungo le frastagliate coste a nord di Porto di Menethil. Il Primo Ufficiale Fitzsimmons fu l'unico a raggiungere la riva vivo. I suoi compagni marinai non trovarono pace sotto le onde. Mentre morivano, la stregoneria sprigionata da un tesoro misterioso nascosto nel profondo di uno scafo legò le loro anime ai legni battuti dal mare e negò loro il riposo."},{t="Pietà tramite la Lama",b="Il Primo Ufficiale Fitzsimmons sente ancora i suoi ex compagni di nave gemere e gridare di notte nelle taverne di Porto di Menethil. Crede che abbattere i loro cadaveri animati possa liberarli dal tormento. Perciò manda i viaggiatori nei marci relitti sommersi a uccidere i marinai maledetti, i veterani fanti e il suo ex pari, il Primo Ufficiale Snellig. Chiede loro di riportare la scatola di tabacco personale di Snellig come prova che il suo amico ha trovato riposo."}},faq={{q="Chi era il Primo Ufficiale Snellig?",a="Il Primo Ufficiale Snellig prestò servizio con il Primo Ufficiale Fitzsimmons a bordo della Third Fleet di Kul Tiras. Snellig annegò con l'equipaggio quando la flotta naufragò al largo della costa settentrionale delle Paludi Grigie. Una reliquia maligna a bordo delle navi lo trasformò in un orrore non morto, e ora infesta una stiva allagata in uno dei relitti.",al={"snellig","primo ufficiale snellig","chi è snellig"}},{q="Perché i marinai e i fanti sono maledetti?",a="Fitzsimmons dice che un tesoro occultato e maligno si trovava a bordo di una delle navi della flotta. Quando le navi naufragarono lungo la costa, le energie oscure dell'artefatto legarono gli spiriti dell'equipaggio annegato ai loro scafi marci. Non possono andarsene e soffrono come non morti.",al={"perché sono non morti","maledizione della third fleet","causa dei marinai maledetti"}},{q="Dove si trovano le navi affondate?",a="Le navi in rovina della Third Fleet giacciono sotto le acque al largo della costa settentrionale delle Paludi Grigie, a nord di Porto di Menethil. L'equipaggio maledetto si aggira sui ponti e nelle acque circostanti, mentre Snellig infesta lo scafo crepato della nave meridionale.",al={"dove sono le navi","posizione del relitto","dove si trova snellig"}},{q="Perché Fitzsimmons vuole la Scatola di Tabacco di Snellig?",a="In vita, il Primo Ufficiale Snellig custodiva la scatola di tabacco come ricordo personale. Restituirla a Fitzsimmons dimostra che il suo compagno maledetto è stato liberato dalla sua prigione marcia sotto le onde.",al={"scatola di tabacco di snellig","scatola di tabacco","perché la scatola di tabacco"}},{q="Chi è il Primo Ufficiale Fitzsimmons?",a="Il Primo Ufficiale Fitzsimmons è un marinaio Kul Tirano e l'unico sopravvissuto noto della Third Fleet. Il dolore e il senso di colpa lo trattengono a Porto di Menethil, dove gli incubi sui suoi fratelli annegati lo tormentano mentre cerca viaggiatori che mettano fine alle loro sofferenze.",al={"fitzsimmons","primo ufficiale fitzsimmons"}},{q="Uccidere l'equipaggio spezza davvero la maledizione?",a="Abbattere i marinai e i fanti concede ai loro spiriti inquieti un sollievo temporaneo, ma non spezza l'incantesimo. La Reliquia Misteriosa nascosta tra i relitti resta all'origine della maledizione.",al={"la maledizione è spezzata","questo pone fine alla maledizione"}}},fx={["8e82e35b"]={q="Perché Primo Ufficiale Fitzsimmons vuole che la ciurma maledetta venga uccisa?",a="Fitzsimmons è tormentato dal fatto di essere l'unico sopravvissuto della Terza Flotta. Nel sonno, è perseguitato dai lamenti disperati dei suoi compagni annegati, le cui anime sono ancora legate agli scafi marcescenti da un tesoro oscuro. Spera che mettere a riposo i loro cadaveri ambulanti plachi le loro grida e cominci a spezzare la terribile maledizione che li trattiene.",al={"perché uccidere la ciurma","motivazioni di fitzsimmons","perché fitzsimmons vuole questo"}},["7d36941a"]={q="Perché Fitzsimmons ha bisogno di te invece di andarci lui?",a="Fitzsimmons è un vecchio marinaio distrutto, segnato dal trauma di essere sopravvissuto al naufragio che ha inghiottito l'intera sua flotta. Annega i dispiaceri nella taverna e non ha né la forza né il coraggio di affrontare da solo i cadaveri rianimati dei suoi ex compagni. Si affida invece ad avventurieri capaci perché si rechino ai relitti.",al={"perché fitzsimmons ha bisogno di me","perché fitzsimmons non può andarci","perché non le guardie di menethil"}}},fp="15,293,16.325.0,18.439.1,27.291.0,39.259.0,35.231.0,45.180.0,30.236.0,47.205.1"}
P.entries["quest:29"] = {n="Trial of the Lake",s="A Radaluna, un iniziato affronta il Trial of the Lake, una prova a tempo di velocità e destrezza. Ti immergi nel Lago Elune'ara per recuperare una Bolla del Santuario instabile, poi corri al Santuario di Remulos prima che si deteriori. Se superi la prova, ottieni il riconoscimento di Tajarri e onori la dedizione del Circolo Cenariano all'equilibrio.",h="A Radaluna, un iniziato affronta il Trial of the Lake, una prova a tempo di velocità e destrezza.",kw={"circolo cenariano","lago elune'ara","radaluna","remulos","bolla del santuario","santuario di remulos","tajarri","trial of the lake"},ang={["class:Druid"]="In quanto druido, affronti una prova di rapidità e adattabilità a Radaluna. Il rito di passaggio onora il Custode Remulos."},sec={{t="Una prova di destrezza",b="I guardiani di Radaluna supervisionano questo rito per gli iniziati. Ti immergi nel Lago Elune'ara per trovare una delicata Bolla del Santuario adagiata sul fondale. Inizia a deteriorarsi non appena la tocchi, quindi ti servono mano ferma, sensi acuti e movimenti rapidi per trasportarla via terra prima che la sua magia svanisca."},{t="Omaggio al Custode",b="Una volta presa la bolla, devi correre al Santuario di Remulos, nel nord-ovest di Radaluna. Il monumento onora il Custode Remulos, che guida il Circolo Cenariano nella salvaguardia della natura e dell'equilibrio del mondo. Attivare la bolla lì ne sottolinea l'importanza per il Circolo. La custode Tajarri accoglie gli iniziati che battono il tempo limite e la concorrenza."}},faq={{q="Cos'è il Trial of the Lake?",a="Il Trial of the Lake mette alla prova l'agilità e la concentrazione di un iniziato a Radaluna. Ti immergi nelle gelide profondità del Lago Elune'ara per recuperare una Bolla del Santuario che si deteriora in fretta, poi attraversi di corsa il rifugio fino al Santuario di Remulos, prima che la sua energia svanisca.",al={"cos'è il trial of the lake","scopo del trial of the lake","cos'è questa missione"}},{q="Dove si trova il Santuario di Remulos?",a="Il Santuario di Remulos si trova nel nord-ovest di Radaluna. Onora il Custode Remulos, che guida il Circolo Cenariano, ed è custodito e mantenuto dalla custode Tajarri.",al={"dove si trova il santuario di remulos","posizione del santuario","santuario di remulos radaluna"}},{q="Chi è Tajarri?",a="Tajarri è una fidata custode di Radaluna che si prende cura del Santuario di Remulos. Supervisiona il Trial of the Lake e accoglie gli iniziati che portano la bolla per rendere omaggio al santuario.",al={"chi è tajarri","tajarri radaluna","custode del santuario tajarri"}},{q="Cos'è una Bolla del Santuario?",a="Una Bolla del Santuario è una reliquia che si trova sul fondale del Lago Elune'ara. Una volta estratta dall'acqua, si deteriora rapidamente, quindi chi la porta deve correre ad attivarla presso il Santuario di Remulos come offerta, prima che la sua energia svanisca.",al={"cos'è la bolla del santuario","perché la bolla si deteriora","scopo della bolla del santuario"}},{q="Perché il Custode Remulos viene onorato in questo santuario?",a="Il Custode Remulos è un venerato custode del boschetto che guida il Circolo Cenariano nella salvaguardia della natura e nel mantenimento dell'equilibrio. Il santuario nel nord-ovest di Radaluna onora la sua guida e i suoi principi.",al={"chi è il custode remulos","storia di remulos","perché onorare remulos"}},{q="Cosa significa offrire la bolla al santuario?",a="Attivare la bolla presso il Santuario di Remulos rende omaggio al sacro equilibrio che il Circolo Cenariano preserva e riconosce il duraturo valore spirituale del santuario a Radaluna.",al={"cosa succede usando la bolla","perché attivare la bolla al santuario"}}},fp="17,295,19.299.0,21.340.0,30.252.0,39.157.0,15.173.0,24.216.0,45.199.0,52.184.0"}
P.entries["quest:290"] = {n="Lifting the Curse",s="Il Primo Ufficiale Fitzsimmons ti chiede di liberare i suoi compagni caduti da una maledizione inquieta. Crede che un artefatto a bordo dell’Intrepida, la nave naufragata, li tenga legati e che il fantasma del Capitano Halyndor custodisca la Chiave del Forziere.",h="Il Primo Ufficiale Fitzsimmons ti chiede di liberare i suoi compagni caduti da una maledizione inquieta.",kw={"capitano halyndor","fitzsimmons","glorin frontesalda","intrepida","lifting the curse","porto di menethil","forziere","third fleet","paludi grigie"},ang={["class:Priest"]="Come sacerdote, hai l’autorità spirituale per contrastare le afflizioni e purificare le reliquie contaminate. Fitzsimmons affida il contenuto del forziere al sacerdozio perché venga purificato.",["faction:Alliance"]="Come campione dell’Alleanza, onori i marinai che servirono l’Alleanza in vita. Aiuta a dare pace alle loro anime tormentate mentre attraversi Porto di Menethil."},sec={{t="Il peso di un capitano",b="Il Primo Ufficiale Fitzsimmons è sopravvissuto al destino della Third Fleet, ma i ricordi dei suoi compagni lo tormentano giorno e notte. Crede che un oggetto malvagio chiuso nel forziere dell’Intrepida sia legato alla non-morte che affligge i suoi compagni di bordo. Il fantasma del Capitano Halyndor sorveglia il relitto e custodisce la Chiave del Forziere."},{t="Sbloccare gli abissi",b="Le navi distrutte della Third Fleet giacciono al largo della costa settentrionale delle Paludi Grigie. Lo scafo allagato dell’Intrepida contiene un forziere chiuso e la reliquia al centro delle sofferenze dell’equipaggio. Sul ponte, il fantasma di Halyndor custodisce la chiave arrugginita. Prendila, entra nello scafo allagato e recupera l’artefatto, così che mani consacrate possano purificarlo."}},faq={{q="Quale nave stai cercando durante questa missione?",a="Stai cercando l’Intrepida, una nave affondata della Third Fleet al largo della costa nordoccidentale delle Paludi Grigie.",al={"quale nave","naufragio dell'intrepida","dov'è il forziere"}},{q="Chi è il Capitano Halyndor?",a="Il Capitano Halyndor comandava l’Intrepida. Il suo fantasma inquieto infesta il ponte della nave in rovina e custodisce la chiave del suo forziere.",al={"chi è halyndor","storia del capitano halyndor"}},{q="Perché il Primo Ufficiale Fitzsimmons vuole che il forziere venga aperto?",a="Fitzsimmons crede che un oggetto maledetto nel forziere intrappoli gli spiriti dei suoi compagni marinai, condannandoli al tormento. Vuole che venga aperto, così da poter recuperare e purificare l’artefatto.",al={"obiettivo di fitzsimmons","perché aprire il forziere","scopo della missione"}},{q="Dov'è situato il forziere dell'Intrepida?",a="Il forziere dell’Intrepida si trova sommerso nella parte inferiore dello scafo. Puoi raggiungerlo passando da una falla nel fianco del relitto, sotto le onde.",al={"posizione del forziere","dov'è il forziere","come trovare il forziere"}},{q="Chi può purificare l'oggetto maledetto una volta recuperato?",a="Fitzsimmons ti chiede di portare l’oggetto recuperato a Glorin Frontesalda, un sacerdote nano a Porto di Menethil, perché lo purifichi.",al={"chi purifica la reliquia","chi è glorin frontesalda","dove portare l'oggetto maledetto"}},{q="Cosa ha causato il naufragio in primo luogo?",a="Durante la Seconda Guerra, draghi rossi controllati dagli orchi attaccarono la Third Fleet, incendiandone e affondandone le navi al largo delle Paludi Grigie. Un tesoro maledetto a bordo impedisce ora agli equipaggi annegati di trovare pace.",al={"come è affondata la third fleet","causa del relitto della third fleet"}}},fx={["336b08f7"]={q="A cosa serve la Chiave del Forziere dell'Intrepida?",a="La chiave apparteneva al Capitano Halyndor ed è necessaria per aprire il forziere dell'Intrepida nel relitto. Al suo interno si trova l'oggetto maledetto responsabile della piaga che ha colpito i marinai della Terza Flotta: va recuperato prima che possa essere purificato.",al={"chiave del forziere dell'intrepida","cosa apre la chiave","perché mi serve la chiave"}},["1f8e42a3"]={q="Perché Primo Ufficiale Fitzsimmons ti manda al posto di andarci lui?",a="Fitzsimmons è profondamente traumatizzato e tormentato dai sogni della sua ciurma morta e del suo ex comandante. Oppresso dal senso di colpa e dalla paura, non riesce ad affrontare il relitto maledetto dell'Intrepida né il vendicativo fantasma del Capitano Halyndor.",al={"perché io per fitzsimmons","perché fitzsimmons non può farlo","perché fitzsimmons ha bisogno di te"}}},fp="17,204,18.297.0,20.314.1,46.101.0,24.128.0,58.167.0,42.131.0,55.126.0,45.193.0"}
P.entries["quest:2902"] = {n="Woodpaw Investigation",s="All'Accampamento Mojache, Hadoken Passo Lesto sospetta che i gnoll Woodpaw seguano piani scritti. Ti manda a sud a cercare piani di battaglia nei loro accampamenti.",h="All'Accampamento Mojache, Hadoken Passo Lesto sospetta che i gnoll Woodpaw seguano piani scritti.",kw={"mappa di battaglia","piani di battaglia","accampamento mojache","feralas","gnoll","hadoken passo lesto","woodpaw"},sec={{t="Una ricerca di piani",b="Dopo Alpha Strike, Hadoken Passo Lesto ti rimanda dai gnoll Woodpaw. Dubita che siano intelligenti, eppure i loro recenti assalti sono stati troppo ben coordinati per essere frutto del caso. Sospetta che tengano traccia per iscritto della loro strategia. Se la trovi, potrebbe scoprire cosa li ha agitati, quindi ti chiede di perlustrare gli accampamenti e riportargli tutto ciò che somiglia a dei piani di battaglia."},{t="Cosa mostra la mappa",b="La mappa dà a Hadoken i piani che cercava. Le frecce la attraversano e potrebbero indicare i movimenti delle truppe, anche se la maggior parte punta a sud, lontano dall'Accampamento Mojache, a nord. Altrove, un disegno ricorda un grosso insetto. I segni sotto potrebbero contare le perdite dei gnoll causate da insetti sconosciuti."}},faq={{q="Chi ti invia a investigare sui gnoll The Woodpaw?",a="Hadoken Passo Lesto, all'Accampamento Mojache, ti manda a indagare sui gnoll Woodpaw.",al={"chi assegna woodpaw investigation","datore di missione woodpaw investigation"}},{q="Perché Hadoken crede che i gnoll abbiano dei piani di battaglia?",a="I recenti assalti dei gnoll Woodpaw sono stati troppo ben coordinati per essere improvvisati. Hadoken si aspetta di trovare una strategia scritta che potrebbe rivelare cosa li ha agitati.",al={"perché i gnoll hanno piani","strategia woodpaw"}},{q="Dove si trovano i piani di battaglia?",a="I piani di battaglia si trovano negli accampamenti dei gnoll Woodpaw, a sud dell'Accampamento Mojache.",al={"dove sono i piani woodpaw","dove trovare mappa di battaglia woodpaw"}},{q="Cosa viene prima di Woodpaw Investigation?",a="Alpha Strike precede questa ricerca.",al={"missione precedente woodpaw investigation","prerequisito catena woodpaw"}}},fp="21,153,18.373.0,18.259.1,48.81.0,54.151.0,35.64.0,39.44.0"}
P.entries["quest:2903"] = {n="The Battle Plans",s="Porti i piani di battaglia dei Woodpaw verso l'Accampamento Mojache, dove Hadoken Passo Lesto spera di scoprire cosa hanno in mente gli gnoll.",h="Porti i piani di battaglia dei Woodpaw verso l'Accampamento Mojache, dove Hadoken Passo Lesto spera di...",kw={"piani di battaglia","accampamento mojache","feralas","gnoll","hadoken passo lesto","woodpaw"},sec={{t="Ritorno all'Accampamento Mojache",b="Dopo Woodpaw Investigation, riporti i piani di battaglia dei Woodpaw da Hadoken Passo Lesto all'Accampamento Mojache. Gli servono prove concrete sulle intenzioni degli gnoll."},{t="La lettura di Hadoken",b="Hadoken Passo Lesto dice che i piani sono proprio ciò di cui avevano bisogno. Per lui la maggior parte degli scarabocchi è incomprensibile, ma ha letto abbastanza piani di battaglia da capire che gli gnoll combattono su due fronti. Uno è l'Accampamento Mojache. La maggior parte delle loro forze è rivolta contro un nemico a sud. Hadoken intuisce che dietro gli scontri c'è qualcosa di più grande e crede che debbano scoprire chi sia quel secondo nemico."}},faq={{q="Dove devono essere portati questi piani di battaglia?",a="Porta i piani a Hadoken Passo Lesto all'Accampamento Mojache.",al={"a chi consegnare i piani","dove consegnare i piani di battaglia","consegna piani di battaglia"}},{q="Cosa è venuto prima di questa fase?",a="Woodpaw Investigation si è svolta prima di questa missione, quando hai cercato i piani degli gnoll.",al={"missione precedente","cosa porta ai piani di battaglia","prerequisito piani di battaglia"}},{q="Da dove provengono i piani di battaglia?",a="I piani appartengono agli gnoll. Li hai trovati negli accampamenti degli gnoll a sud dell'Accampamento Mojache durante Woodpaw Investigation.",al={"chi ha creato la mappa","quali gnoll hanno creato i piani","origine piani woodpaw"}}},fp="16,121,20.159.0,17.372.1,39.55.0,27.80.0,37.113.0"}
P.entries["quest:2904"] = {n="A Fine Mess",s="A Gnomeregan, trovi Stracciolercio malconcio tra i trogg dopo un’imboscata dei Ferroscuro. Salvarlo porta notizie di una trivella sotterranea sotto Dun Morogh, diretta a Baia del Bottino.",h="A Gnomeregan, trovi Stracciolercio malconcio tra i trogg dopo un’imboscata dei Ferroscuro.",kw={"baia del bottino","clockwerk run","ferroscuro","gnomeregan","stracciolercio","scotty","super trivella","tinkerwiz","trogg"},ang={["faction:Alliance"]="Come membro dell’Alleanza, scopri che gli agenti dell’imperatore Thaurissan stanno sabotando gli sforzi dell’Alleanza per ristabilire la situazione a Gnomeregan.",["profession:Engineering"]="Come ingegnere, potresti preoccuparti nello scoprire che i macchinisti Ferroscuro stanno costruendo un’enorme super trivella sotterranea.",["race:Gnome"]="Come gnomo, hai il dovere d’onore di salvare un superstite dalle profondità contaminate di Gnomeregan. Gli infiltrati Ferroscuro e i trogg selvaggi lo minacciano."},sec={{t="Un sopravvissuto malconcio",b="Trovi Stracciolercio nel dormitorio di Gnomeregan, picchiato e intontito. I nani Ferroscuro hanno teso un’imboscata al goblin e l’hanno lasciato tra i trogg selvaggi. Lo guidi attraverso i corridoi contaminati verso la salvezza."},{t="Macchinazioni sotterranee",b="Stracciolercio porta notizie del lavoro del clan Ferroscuro a un’enorme super trivella sotto Dun Morogh. Fugge via mare fino a Porto Paranco per avvertire il tecnico goblin Tinkerwiz. Poi ti manda a sud, a Baia del Bottino, con notizie per il tecnico goblin Scotty."}},faq={{q="Chi è Stracciolercio?",a="Stracciolercio è un goblin che trovi in fin di vita a Gnomeregan. I nani Ferroscuro gli hanno teso un’imboscata e l’hanno lasciato tra i trogg prima che tu lo salvassi.",al={"stracciolercio","chi è stracciolercio"}},{q="Dove deve essere scortato Stracciolercio?",a="Guidi Stracciolercio attraverso le sale ostili di Gnomeregan, verso l’uscita di Clockwerk Run e i corridoi dell’ingresso superiore.",al={"dove porto stracciolercio","destinazione scorta","uscita clockwerk run"}},{q="Perché erano coinvolti i nani Ferroscuro?",a="I nani Ferroscuro aiutavano a progettare e costruire un’enorme super trivella sotterranea. Stracciolercio scoprì il loro piano prima che gli tendessero un’imboscata.",al={"perché i ferroscuro","super trivella ferroscuro","ferroscuro a gnomeregan"}},{q="Dove va Stracciolercio dopo essere scappato?",a="Dopo aver raggiunto un luogo sicuro, Stracciolercio attraversa il mare fino a Porto Paranco, nelle Savane, per avvertire Tinkerwiz del coinvolgimento dei Ferroscuro nella trivella sotterranea.",al={"dove è andato stracciolercio","stracciolercio porto paranco","avvertimento tinkerwiz"}},{q="Perché devi fare rapporto a Scotty a Baia del Bottino?",a="Scotty è un tecnico goblin di Baia del Bottino che collabora con Tinkerwiz su attrezzature sotterranee ad alta tecnologia e reti di trasponder.",al={"perché scotty","consegna baia del bottino","collegamento scotty"}},{q="In che modo questo è collegato al Mekgeniere Termospin?",a="Scotty conosce la minaccia rappresentata da Mekgeniere Termospin all’interno di Gnomeregan. Aiutare Stracciolercio fornisce supporto e rifornimenti agli avventurieri che si preparano a tornare e affrontare il traditore Mekgeniere.",al={"collegamento termospin","combattere termospin"}}},fx={["73352f2e"]={q="Perché Stracciolercio ha bisogno di essere scortato fuori?",a="Stracciolercio è stato colto di sorpresa, picchiato quasi a morte dai nani Ferroscuro e abbandonato in un dormitorio invaso da trogg ostili. Malconcio e intrappolato nel cuore delle sale in rovina di Gnomeregan, non può raggiungere l'uscita da solo. Inoltre, porta con sé informazioni urgenti: ha scoperto che il clan Ferroscuro è direttamente coinvolto nella costruzione di un'enorme trivella. Fuggire vivo è la sua unica possibilità di raggiungere Porto Paranco e avvertire il suo socio Tinkerwiz prima che quel macchinario provochi altri danni.",al={"perché aiutare stracciolercio","motivazioni di stracciolercio","perché stracciolercio ha bisogno di aiuto"}},["9976ada5"]={q="Perché Stracciolercio non può fuggire da Gnomeregan da solo?",a="Quando lo trovi, Stracciolercio è a malapena cosciente: i suoi carcerieri Ferroscuro lo hanno picchiato duramente prima di gettarlo in una fossa piena di trogg. Contuso, disarmato e indebolito fino allo stremo, non ha alcuna speranza di superare i mutanti irradiati, i costrutti impazziti e i trogg ferali che pattugliano Clockwerk Run senza un avventuriero capace che lo protegga.",al={"perché stracciolercio ha bisogno di te","perché stracciolercio non può combattere","perché io per stracciolercio"}}},fp="11,166,19.204.0,20.250.1,16.147.0,32.119.0,40.149.0,38.164.1,43.127.0,46.191.0"}
P.entries["quest:291"] = {n="I rapporti",s="Da Kharanos, Senir Barbabianca informa il Senatore Barin Pietrarossa a Forgiardente della minaccia dei Mantogelido a Dun Morogh. Ti chiede di non rivelare il nome del suo esploratore.",h="Da Kharanos, Senir Barbabianca informa il Senatore Barin Pietrarossa a Forgiardente della minaccia dei...",kw={"barin pietrarossa","senato dei nani","mantogelido","high seat","forgiardente","kharanos","magni barbabronzea","senir barbabianca","i rapporti"},ang={["faction:Alliance"]="In quanto membro dell'Alleanza, scopri la struttura civica di Forgiardente e la burocrazia che plasma la politica interna dell'Alleanza.",["race:Dwarf"]="In quanto nano, quando consegni il dispaccio nell'High Seat scopri l'equilibrio tra la corona di Re Magni e il potere parlamentare del Senato dei nani."},sec={{t="Un dispaccio per la capitale",b="Il rapporto porta notizie dall'interno del Covo dei Mantogelido, dove i troll minacciano Dun Morogh. Senir vuole che tu lo consegni direttamente a Barin Pietrarossa e non riveli il nome dell'esploratore delle rupi innevate."},{t="Attriti nell'High Seat",b="Il Senatore Barin Pietrarossa si infuria quando il rapporto di Senir raggiunge la corte reale di Forgiardente. Gli dà fastidio che Senir abbia invocato l'autorità di Re Magni Barbabronzea per approvare le sue operazioni. La sua rabbia rivela il risentimento del Senato per i decreti del Re e per il lavoro sul campo svolto in suo nome."}},faq={{q="Chi è Senir Barbabianca?",a="Senir Barbabianca è un montanaro nano di stanza vicino a Kharanos, a Dun Morogh. Supervisiona le ricognizioni e l'esplorazione militare contro i troll Mantogelido che avanzano verso gli insediamenti dei nani.",al={"senir barbabianca","chi consegna i rapporti","barbabianca kharanos"}},{q="Chi è il Senatore Barin Pietrarossa?",a="Barin Pietrarossa è un senatore nano scontroso e aristocratico, che vive nella sala del trono di Forgiardente, vicino a Re Magni Barbabronzea. I postulanti comuni lo irritano facilmente.",al={"barin pietrarossa","chi è il senatore","pietrarossa forgiaardente"}},{q="Perché il Senatore Pietrarossa è arrabbiato per il rapporto?",a="Senir ti avverte che il Senatore Pietrarossa è scontroso. Quando consegni il rapporto, scopri perché il senatore è arrabbiato.",al={"perché pietrarossa è arrabbiato","perché il senatore urla","senato contro magni"}},{q="Perché Senir Barbabianca chiede di mantenere segreto il tuo aiuto?",a="Senir Barbabianca ti chiede di mantenere segreto il tuo aiuto, così i suoi superiori crederanno che abbia compiuto da solo l'ardua ricognizione. Non vuole ammettere che il lavoro sia stato svolto da un avventuriero.",al={"perché senir si prende il merito","barbabianca ha rubato il merito","segreto di senir"}},{q="Dove viene consegnato il rapporto?",a="Consegni il rapporto al Senatore Barin Pietrarossa nell'High Seat di Forgiardente, la grande sala dove Re Magni Barbabronzea tiene udienza.",al={"dove consegnare i rapporti","posizione barin pietrarossa","consegna dei rapporti"}},{q="Cosa rivela questa missione sulla politica di Forgiardente?",a="Consegnare il rapporto ti fa conoscere il Senato di Forgiardente e i funzionari che ricevono le segnalazioni dalle frontiere. La risposta di Pietrarossa offre uno scorcio sulla politica di Forgiardente.",al={"lore del governo di forgiardente","lore del senato dei nani","magni contro senato"}}},fx={bde96c47={q="Perché Senir Barbabianca ha bisogno che tu consegni il rapporto al posto suo?",a="Senir Barbabianca è ancora di stanza a Dun Morogh per supervisionare le operazioni sul campo contro minacce locali come i troll Mantogelido. Soprattutto, vuole far credere al Senato e ai suoi superiori di lavorare instancabilmente in prima linea, lasciando i compiti da corriere e il fastidio di affrontare un senatore scontroso a un viaggiatore sacrificabile.",al={"perché dovrei consegnare il rapporto","perché senir non consegna il rapporto","perché proprio io per i rapporti"}}},fp="11,163,25.197.0,25.281.1,24.190.0,30.157.0,47.110.1,55.190.0,30.139.0,53.163.1"}
P.entries["quest:292"] = {n="The Eye of Paleth",s="Fitzsimmons ti chiede di recuperare l'Occhio di Paleth dall'Intrepida affondata. Poi porta la gemma maledetta da Glorin Frontesalda a Porto di Menethil, dove il sacerdote nanico cerca un modo per purificare la sua piaga.",h="Fitzsimmons ti chiede di recuperare l'Occhio di Paleth dall'Intrepida affondata.",kw={"occhio di paleth maledetto","occhio di paleth","fitzsimmons","glorin frontesalda","intrepida","porto di menethil","the third fleet","paludi grigie"},ang={["class:Priest"]="Da sacerdote, hai motivo di preoccuparti quando un artefatto sacro come l'Occhio di Paleth viene profanato. La sua piaga tocca la tua fede nella Sacra Luce.",["faction:Alliance"]="Come membro dell'Alleanza, sai che la distruzione della The Third Fleet ha lasciato Porto di Menethil vulnerabile. Recuperarne i resti può dare conforto per la perdita dei compagni.",["race:Dwarf"]="Da nano, condividi la dedizione a recuperare le reliquie perdute al largo delle coste di Khaz Modan. I membri del clero di Forgiardente, come Glorin Frontesalda, possono aiutarti."},sec={{t="Una Reliquia Corrotta",b="Sotto la Baia di Baradin, la cassetta di sicurezza chiusa dell'Intrepida custodisce un globo annerito. L'Occhio di Paleth pulsa sott'acqua, trasformato dalla luce sacra in una fonte di sofferenza. La sua corruzione lo lega agli spiriti inquieti e al destino che ha reclamato i marinai della The Third Fleet."},{t="In cerca del sacerdozio",b="Glorin Frontesalda esamina la reliquia a Porto di Menethil. Il sacerdote nanico della Sacra Luce è sbalordito che un simile artefatto sacro appartenesse alla The Third Fleet. Riconosce la sua macchia innaturale e si prepara a compiere riti per annullarne la nefasta influenza."}},faq={{q="Cos'è l'Occhio di Paleth?",a="L'Occhio di Paleth è una gemma sacra antica e potente, di solito legata a energie sacre. A bordo dell'Intrepida, un vascello affondato della The Third Fleet, è stato distorto e maledetto, e irradia magia oscura.",al={"lore occhio di paleth","cos'è paleth","occhio di paleth maledetto"}},{q="Dove è stato recuperato l'Occhio?",a="Recuperi l'Occhio da una cassetta di sicurezza chiusa nel relitto allagato dell'Intrepida, al largo della costa delle Paludi Grigie.",al={"dove trovo l'occhio","posizione occhio di paleth","cassaforte intrepida"}},{q="Perché a Glorin Frontesalda importa dell'artefatto?",a="Glorin Frontesalda è un sacerdote nanico di stanza a Porto di Menethil. La sua conoscenza della Sacra Luce gli permette di riconoscere le reliquie antiche e preparare riti per spezzare le maledizioni sinistre.",al={"chi è glorin frontesalda","perché frontesalda"}},{q="Come fa Fitzsimmons a conoscere l'Occhio?",a="Fitzsimmons è sopravvissuto alla tragedia della The Third Fleet, che ancora lo tormenta. Rifugiatosi nella taverna di Menethil, sapeva che una reliquia oscura giaceva nascosta tra i relitti e tormentava i suoi compagni caduti.",al={"legame con fitzsimmons","perché fitzsimmons mi ha mandato"}},{q="Perché l'Occhio è maledetto?",a="La corruzione dell'Occhio è legata alle morti soprannaturali e ai non morti inquieti che infestano i relitti della The Third Fleet. Ha assorbito energie oscure durante o dopo la catastrofe che ha trascinato la flotta sul fondo dell'oceano.",al={"perché è maledetto","origine maledizione occhio"}},{q="Cosa succede dopo aver consegnato l'Occhio a Glorin?",a="Glorin esamina la gemma maledetta e capisce che non può restare corrotta. Ti incarica di purificare la reliquia dalla sua influenza corruttrice.",al={"prossima missione","cosa fare con l'occhio"}}},fp="17,199,16.272.0,22.247.1,26.191.0,28.110.0,50.174.0,40.197.0,22.215.0,44.131.1"}
P.entries["quest:2922"] = {n="Save Techbot's Brain!",s="Tinkmaster Overspark ti manda a Gnomeregan per completare Save Techbot's Brain! e recuperare il Nucleo della Memoria di Techbot. La macchina un tempo aiutava i ricercatori, ma le radiazioni hanno invaso la città e una scarica elettrica durante la sua caduta ha polarizzato il suo cervello, rendendola violenta. Overspark spera che il nucleo lo aiuti a invertire il danno e a ripristinare la sua creazione.",h="Tinkmaster Overspark ti manda a Gnomeregan per completare Save Techbot's Brain!",kw={"gnomeregan","nucleo della memoria","negatronico","overspark","positronico","techbot","tinker town"},ang={["faction:Alliance"]="In quanto membro dell'Alleanza, aiuti i rifugiati gnomi che trovano riparo a Forgiardente recuperando tecnologie perdute dal perimetro contaminato di Gnomeregan.",["profession:Engineering"]="In quanto ingegnere, puoi vedere nel passaggio di Techbot da positronico a negatronico come una catastrofe possa deformare matrici computazionali complesse.",["race:Gnome"]="In quanto gnomo, sai che Gnomeregan era la tua città natale. Techbot mostra come la sua caduta abbia danneggiato persino le più grandi creazioni intellettuali della città."},sec={{t="Una Mente Invertita",b="Prima della caduta di Gnomeregan, Techbot aiutava i ricercatori con i suoi dispositivi e la sua profonda conoscenza tecnica. Tinkmaster Overspark progettò l'assistente meccanico, i cui congegni integrati lo rendevano una meraviglia dell'ingegno gnomico. Poi l'invasione dei trogg portò il caos e le radiazioni tossiche invasero la città. Una scarica elettrica vagante scosse i delicati meccanismi di Techbot e polarizzò il suo cervello positronico, trasformandolo in un instabile stato negatronico."},{t="Operazione di Recupero",b="Tinkmaster Overspark ha bisogno che tu recuperi il nucleo di Techbot, perché ora la macchina vaga furiosa per i corridoi contaminati di Gnomeregan e attacca chiunque incontri. Overspark si rifiuta di abbandonare il suo prezioso assistente come rottame. Ti chiede di trovare la macchina, estrarre il Nucleo della Memoria di Techbot dal telaio metallico e portarlo a Forgiardente. Con il nucleo spera di capire la polarizzazione e riparare la mente di Techbot."}},faq={{q="Chi è Techbot?",a="Techbot è un assistente meccanico progettato da Tinkmaster Overspark. Prima della caduta di Gnomeregan, aiutava il Tinkmaster e i suoi collaboratori grazie alle sue vaste conoscenze e ai congegni integrati.",al={"cosa è techbot","lore di techbot","overspark techbot"}},{q="Perché Techbot è diventato ostile?",a="Durante la caduta di Gnomeregan, una scarica elettrica vagante scosse il cervello positronico di Techbot. La scossa ne invertì l'allineamento neurale, trasformandolo in uno stato negatronico e rendendo violenta la sua indole servizievole.",al={"perché techbot è arrabbiato","cosa è successo a techbot","polarizzazione di techbot"}},{q="Dove si può trovare Techbot?",a="Techbot vaga per i corridoi esterni e le sale di raduno di Gnomeregan, oltre il perimetro in cui operano gli gnomi esiliati e le forze naniche di spedizione.",al={"dove si trova techbot","posizione di techbot","trovare techbot"}},{q="Chi assegna questa missione?",a="Tinkmaster Overspark ti fa la sua richiesta da Tinker Town, a Forgiardente. Qui supervisiona le operazioni di recupero e ricerca per il Gran Meccanista Gelbin Meccatork.",al={"chi inizia salva il cervello di techbot","luogo di overspark"}},{q="Techbot può essere davvero riparato?",a="Tinkmaster Overspark crede che il Nucleo della Memoria di Techbot lo aiuterà a scoprire la causa della sua polarizzazione negatronica e a rimettere in funzione la macchina.",al={"techbot è riparato","puoi riparare techbot","techbot sopravvive"}},{q="Cosa succede dopo aver restituito il Nucleo della Memoria?",a="Quando Overspark riceve il nucleo, si prepara a smontare e riconfigurare i circuiti invertiti. Trovare gli strumenti giusti nel suo caotico laboratorio è già una sfida.",al={"conclusione della missione di techbot","consegna nucleo di techbot"}}},fx={e9c625cc={q="Perché Tinkmaster Overspark vuole che il cervello di Techbot venga salvato?",a="Techbot è la creazione più preziosa di Tinkmaster Overspark e un tempo serviva lui e i suoi colleghi inventori con un immenso archivio di conoscenze e congegni pratici. Quando Gnomeregan cadde, una scarica elettrica imprevista polarizzò il cervello positronico dell'automa, trasformandolo in uno stato negatronico e facendolo impazzire. Overspark si rifiuta di abbandonare la sua creazione e spera che studiarne il nucleo gli permetta di annullare il danno e ripristinare il suo assistente.",al={"motivazioni di overspark","perché salvare techbot","perché overspark vuole techbot"}},["6f8a4042"]={q="A cosa serve il Nucleo della Memoria di Techbot?",a="Il nucleo della memoria contiene la mente digitalizzata di Techbot e le conoscenze che ha accumulato. Poiché il cervello positronico dell'automa si è invertito durante la caduta di Gnomeregan, estrarre questo componente è l'unico modo per esaminare il cambiamento di polarità e tentare di riprogrammare o ricostruire l'assistente meccanico.",al={"nucleo della memoria di techbot","a cosa serve il nucleo della memoria"}}},fp="21,341,15.420.0,17.407.0,15.180.0,31.187.0,27.146.0,21.136.0,30.153.0,45.182.1"}
P.entries["quest:2923"] = {n="Tinkmaster Overspark",s="A Roccavento, Fratello Sarno viene a sapere che Techbot si è guastato e che Tinkmaster Overspark è in lutto a Forgiardente. Invia gli avventurieri dell'Alleanza a Tinker Town, dove Overspark chiede aiuto per recuperare il nucleo di memoria di Techbot da Gnomeregan.",h="A Roccavento, Fratello Sarno viene a sapere che Techbot si è guastato e che Tinkmaster Overspark è in lutto a...",kw={"gnomeregan","forgiardente","overspark","sarno","techbot","tinker town","tinkmaster"},ang={["faction:Alliance"]="Come membro dell'Alleanza, aiutare gli gnomi sfollati a Tinker Town rafforza i legami tra Roccavento e i regni di nani e gnomi.",["profession:Engineering"]="Come ingegnere, puoi imparare dagli ultimi ritrovati dell'ingegno gnomesco esaminando le creazioni fuori controllo di Overspark.",["race:Gnome"]="Come gnomo, ogni creazione che recuperi e ogni nucleo di memoria che riporti preservano un frammento della tua patria caduta, sottraendolo alle radiazioni e ai trogg."},sec={{t="Una supplica dalla Cattedrale",b="Fratello Sarno si prende cura dei viaggiatori a Roccavento e parla dei problemi dei rifugiati gnomi. Tinkmaster Overspark, una delle menti dietro le meraviglie di Gnomeregan, è in lutto per la corruzione di Techbot. Il servitore meccanico un tempo aiutava fedelmente i tecnocrati. Poi la città cadde in rovina."},{t="Verso Tinker Town",b="Prendi il Tram degli Abissi da Roccavento a Tinker Town, a Forgiardente. Lì, Overspark cerca avventurieri disposti ad aiutarlo nelle sale irradiate di Gnomeregan. Chiede loro di recuperare ciò che resta delle facoltà di Techbot prima che il costrutto causi danni irreparabili."}},faq={{q="Chi è Tinkmaster Overspark?",a="Tinkmaster Overspark è un ingegnere gnomo che addestra all'ingegneria gnomica. Si trova a Tinker Town, a Forgiardente, e coordina gli sforzi per riconquistare Gnomeregan e recuperare la tecnologia gnomica dispersa nella capitale in rovina.",al={"overspark","chi è overspark","tinkmaster overspark"}},{q="Chi inizia questa missione?",a="Fratello Sarno, un chierico umano a Roccavento, ti manda ad aiutare gli gnomi a Forgiardente.",al={"datore di missione","dove trovare la missione di tinkmaster overspark"}},{q="Cos'è Techbot?",a="Techbot è una creazione meccanica progettata da Tinkmaster Overspark. Un tempo era un utile strumento per gli ingegneri gnomi, ma si è guastato dopo la caduta di Gnomeregan e ora è fuori controllo nella città irradiata.",al={"techbot","cosa è successo a techbot"}},{q="Dove si trova Tinkmaster Overspark?",a="Tinkmaster Overspark si trova a Tinker Town, il quartiere gnomesco nel distretto orientale di Forgiardente, tra altri tecnocrati rifugiati e macchinari sperimentali.",al={"posizione di overspark","dove si trova overspark"}},{q="Cosa succede dopo aver parlato con Overspark?",a="Dopo aver parlato con Overspark, ti chiede di entrare a Gnomeregan, disattivare Techbot e recuperare il suo nucleo di memoria, così da poterlo ripristinare.",al={"prossima missione","salva il cervello di techbot"}},{q="Perché l'Alleanza si interessa a una macchina rotta di un inventore?",a="L'Alleanza si prende cura degli gnomi esiliati, e gli automi fuori controllo a Gnomeregan minacciano le spedizioni che cercano di riconquistare la capitale sotterranea o di difendere i confini di Dun Morogh.",al={"perché preoccuparsi di techbot","importanza di techbot"}}},fx={["9c70ad2e"]={q="Perché Fratello Sarno ti manda da Tinkmaster Overspark?",a="Fratello Sarno ricorda Techbot come un automa gentile e disponibile, che serviva fedelmente gli gnomi prima che Gnomeregan sprofondasse nel caos. Sapere che Overspark è sconvolto per il malfunzionamento della sua creazione turba l'uomo santo. Sperando che la macchina possa ancora essere salvata, invece di essere lasciata arrugginire o distrutta, Sarno indirizza gli avventurieri più compassionevoli a Tinker Town, affinché il tinkmaster sconvolto riceva l'aiuto di cui ha disperatamente bisogno.",al={"perché interessa a fratello sarno","motivazioni di fratello sarno","perché mi manda da overspark"}}},fp="20,235,25.293.0,14.259.0,28.211.0,22.91.0,16.197.0,40.151.0,41.136.0,63.172.0"}
P.entries["quest:2924"] = {n="Essential Artificials",s="A Forgiardente, Klockmort Spannerspan non ha i componenti necessari ai suoi esperimenti. Gli gnomi esiliati fuggirono da Gnomeregan durante l'invasione dei trogg e il disastro delle radiazioni, lasciando gli Essential Artificials nei livelli inferiori della città.",h="A Forgiardente, Klockmort Spannerspan non ha i componenti necessari ai suoi esperimenti.",kw={"estrapolatore artificiale","essential artificials","gnomeregan","ingegneria gnomica","forgiardente","klockmort spannerspan","tinker town"},ang={["faction:Alliance"]="In quanto membro dell'Alleanza, aiutare gli gnomi esiliati a recuperare la tecnologia perduta rafforza la base ingegneristica dell'Alleanza a Forgiardente.",["profession:Engineering"]="In quanto ingegnere, sai quanto lavoro possa fermarsi per la mancanza di un solo pezzo. Questi componenti dimostrano l'abilità degli ingegneri di Gnomeregan prima della caduta della città.",["race:Gnome"]="In quanto gnomo, recuperare questi componenti aiuta a preservare l'arte e l'inventiva del tuo popolo durante l'esilio a Forgiardente."},sec={{t="Dimenticati nell'esodo",b="Quando i trogg invasero Gnomeregan e le radiazioni riempirono i suoi corridoi, gli gnomi fuggirono portando con sé solo ciò che riuscirono a raggiungere. Gli Essential Artificials rimasero indietro. Queste parti meccaniche specializzate funzionano in quasi ogni dispositivo e sono apprezzate da artefici e artigiani. Ora, a Tinker Town di Forgiardente, il mastro artefice Klockmort Spannerspan non può proseguire i suoi nuovi esperimenti senza averne una scorta."},{t="Esplorando gli estrapolatori",b="Nel profondo di Gnomeregan, i componenti si trovano in pesanti contenitori a vapore chiamati estrapolatori artificiali. Per raggiungerli, devi attraversare sale irradiate, dove si aggirano gnomi lebbrosi mutati, automi difensivi malfunzionanti e trogg feroci. Klockmort ha bisogno di dodici componenti per proseguire il suo lavoro e mantenere viva l'inventiva gnomica durante l'esilio."}},faq={{q="Cos'è un essenziale artificiale?",a="Un Essenziale Artificiale è un componente meccanico realizzato dagli ingegneri gnomi, che funziona in quasi ogni dispositivo. Artefici e fabbri apprezzano queste parti come elementi fondamentali per congegni complessi e macchinari sperimentali.",al={"cosa sono gli essential artificials","essenziale artificiale","cos'è"}},{q="Chi assegna la missione Essential Artificials?",a="Klockmort Spannerspan, un ingegnere gnomo di Tinker Town a Forgiardente, ti chiede i componenti.",al={"chi assegna la missione","chi inizia questa missione","dove trovo gli essential artificials"}},{q="Dove si trovano gli Essential Artificials a Gnomeregan?",a="Gli Essential Artificials si trovano nel profondo di Gnomeregan, dentro gli estrapolatori artificiali sparsi nei livelli inferiori. Sono alti armadi di stoccaggio alimentati a vapore.",al={"dove si trovano","posizione dell'estrapolatore","come trovare gli artificiali"}},{q="Perché sono stati lasciati a Gnomeregan?",a="I trogg invasero Gnomeregan e le radiazioni inondarono la città. Durante la precipitosa evacuazione, gli gnomi lasciarono scorte di Essential Artificials nelle officine inferiori.",al={"perché sono stati lasciati indietro","perché si trovano a gnomeregan","storia degli artificiali"}},{q="A cosa servono a Klockmort?",a="Klockmort Spannerspan ha bisogno dei componenti per i complessi esperimenti che sta preparando nella sua officina di Forgiardente.",al={"perché klockmort li vuole","piano di klockmort"}},{q="È necessario Klockmort's Essentials prima di accettare questa missione?",a="Klockmort's Essentials ti presenta Klockmort e ti indica la sua officina. Puoi accettare questo incarico senza portarlo a termine.",al={"prerequisito","klockmort's essentials necessario","componenti richiesti da klockmorts essentials"}}},fx={["41f0ee2b"]={q="Perché Klockmort ha bisogno di avventurieri esterni per entrare a Gnomeregan?",a="Gnomeregan non è più una città funzionante: è una zona di guerra letale e irradiata, invasa dai trogg e dagli gnomi lebbrosi impazziti. Gli inventori gnomeschi come Klockmort Spannerspan sono ricercatori, non soldati in prima linea, e gli gnomi sopravvissuti a Tinker Town sono profughi che vivono grazie all'ospitalità dei nani, non un esercito invasore. Per avventurarsi nei settori più profondi e pericolosi della città in rovina servono avventurieri esperti, capaci di farsi strada tra ondate di mutanti ostili fino ai contenitori di stoccaggio.",al={"perché mi manda","perché servono avventurieri","perché klockmort non può recuperarli"}}},fp="21,215,23.375.0,25.343.0,32.217.0,42.94.0,56.169.0,40.160.0,34.109.0,60.136.0"}
P.entries["quest:2925"] = {n="Klockmort's Essentials",s="A Darnassus, Mathiel porta oltre il mare l'appello urgente di Klockmort Spannerspan. Vincolato al suo incarico, chiede ai viaggiatori dell'Alleanza di trovare il suo amico gnomo a Forgiardente.",h="A Darnassus, Mathiel porta oltre il mare l'appello urgente di Klockmort Spannerspan.",kw={"essential artificials","gnomeregan","forgiardente","klockmort spannerspan","klockmort's essentials","gnomi lebbrosi","mathiel","tinkertown"},ang={["faction:Alliance"]="Come viaggiatore dell'Alleanza, porti l'appello di Mathiel da Darnassus a Klockmort, a Forgiardente. Le terre degli Elfi della Notte e le sale dei nani si uniscono per difendersi.",["race:Gnome"]="Da gnomo, sai che ogni chiamata a Tinkertown sostiene la lotta in corso per riconquistare la tua patria perduta, Gnomeregan."},sec={{t="Una chiamata attraverso i continenti",b="Dalla Terrazza dei Guerrieri a Darnassus, Mathiel manda notizie a Dun Morogh. Klockmort Spannerspan ha bisogno di alleati audaci per una spedizione a Gnomeregan, ma Mathiel non può lasciare il suo incarico per raggiungerlo. Perciò chiede ai viaggiatori dell'Alleanza più capaci che passano da Darnassus di compiere il viaggio al suo posto."},{t="La strada per Tinkertown",b="Klockmort Spannerspan lavora a Tinkertown, il quartiere di Forgiardente riservato agli gnomi cacciati dalla loro città sotterranea. Ha in programma di recuperare macchinari essenziali dai corridoi contaminati di Gnomeregan. Grazie alla presentazione di Mathiel, raggiungi l'officina di Klockmort, che ha bisogno di aiuto per riprendersi ciò che è rimasto indietro."}},faq={{q="Chi fornisce la missione Klockmort's Essentials?",a="Mathiel ti affida la missione. L'Elfo della Notte non può lasciare il suo incarico per recarsi a Forgiardente, perciò chiede ai fidati viaggiatori dell'Alleanza di rispondere all'appello del suo vecchio amico Klockmort Spannerspan.",al={"datore di missione","chi inizia klockmort's essentials","missione di mathiel"}},{q="Dove trovo Klockmort Spannerspan?",a="Trova Klockmort Spannerspan a Tinkertown, il quartiere degli gnomi di Forgiardente. Qui gli gnomi, costretti ad abbandonare la loro patria perduta, hanno allestito officine e attrezzature.",al={"dove si trova klockmort","posizione di klockmort","klockmort spannerspan forgiardente"}},{q="Perché Klockmort ha bisogno di aiuto a Gnomeregan?",a="Klockmort ha bisogno di aiuto per recuperare componenti meccanici essenziali da Gnomeregan. Le ricadute tossiche hanno invaso la città, le cui rovine sono abitate da trogg, gnomi lebbrosi impazziti e automi fuori controllo.",al={"cosa vuole klockmort","perché missione a gnomeregan","scopo di klockmort"}},{q="Questa missione è richiesta per entrare a Gnomeregan?",a="No. La missione di Mathiel ti conduce da Klockmort Spannerspan, ma puoi parlargli a Forgiardente e accettare i suoi incarichi anche senza presentazione.",al={"questa missione è obbligatoria","prerequisito per gnomeregan","posso saltare klockmort's essentials"}},{q="Quale missione segue Klockmort's Essentials?",a="Dopo aver parlato con Klockmort Spannerspan, ti manda da Essential Artificials. Ti porterà nel cuore di Gnomeregan.",al={"missione successiva","seguito missione","seguito di essential artificials"}},{q="Perché Mathiel è interessato ad aiutare uno gnomo a Forgiardente?",a="Mathiel e Klockmort sono amici di lunga data. Pur essendo di stanza lontano e impossibilitato a lasciare il suo incarico, Mathiel cerca qualcuno di fidato che aiuti il suo amico.",al={"connessione con mathiel","perché a mathiel importa","mathiel e klockmort"}}},fx={b4ad922f={q="Perché Mathiel ti chiede di andare al posto suo?",a="Il dovere vincola Mathiel al suo incarico a Darnassus, impedendogli di attraversare il mare fino a Dun Morogh. Anche se il suo cuore soffre perché vorrebbe aiutare di persona il suo amico Klockmort, deve affidarsi a un avventuriero capace diretto a Forgiardente, che risponda alla chiamata al posto suo.",al={"perché mathiel non può andare","perché mathiel mi manda","perché mathiel non aiuta klockmort"}}},fp="22,166,24.294.0,22.296.0,43.175.0,38.152.0,43.184.0,43.150.0,42.121.0,58.162.0"}
P.entries["quest:2926"] = {n="Gnogaine",s="A Kharanos, Ozzie Valvotron manda gli avventurieri verso Gnomeregan a raccogliere ricadute radioattive. Spera di preparare una cura per gli gnomi contaminati, anche se l'intruglio potrebbe diventare un liquore molto forte.",h="A Kharanos, Ozzie Valvotron manda gli avventurieri verso Gnomeregan a raccogliere ricadute radioattive.",kw={"gnoarn","gnogaine","gnomeregan","bagliore verde","trogg irradiato","kharanos","gnomo contaminato","ozzie valvotron","fiala","radiazione"},ang={["faction:Alliance"]="In quanto membro dell'Alleanza, sai che la contaminazione di Gnomeregan minaccia tutto Dun Morogh. Comprendere o contenere le ricadute è importante per la sicurezza della regione.",["profession:Engineering"]="In quanto ingegnere, osservi la scienza da campo degli gnomi al lavoro: scorie radioattive grezze raccolte in fiale schermate di piombo.",["race:Gnome"]="In quanto gnomo esiliato, sai quanto i tuoi simili siano disperati nel trovare un rimedio per i loro fratelli irradiati. Vale la pena provare persino gli esperimenti azzardati di Ozzie."},sec={{t="Una cura o un cocktail",b="Dalla caduta di Gnomeregan, i rifugiati come Gnoarn hanno cercato di uccidere gli invasori trogg e di invertire la malattia che ha trasformato i loro simili. Ozzie Valvotron e la sua socia Razzle Mollapazza hanno scelto un'altra strada dal loro laboratorio di Kharanos. Ozzie dice che stanno cercando di preparare una cura per gli gnomi contaminati. La loro formula potrebbe invece diventare un rum molto forte."},{t="Raccogliere il bagliore",b="Ozzie e Razzle hanno bisogno di residui tossici dal cuore del disastro. Ozzie consegna agli avventurieri una fiala di raccolta in piombo e li manda verso i tunnel squarciati di Gnomeregan. Gli Irradiated Invaders e gli Irradiated Pillagers si aggirano lì: sono trogg saturi di scorie fuoriuscite. La fiala ha bisogno del loro bagliore verde."},{t="Capelli e grandi speranze",b="Con una fiala piena di bagliore verde, Ozzie prepara una prova dal vivo. Spera che l'intruglio restituisca salute e sanità mentale a uno gnomo contaminato tenuto prigioniero. Spera anche che la miscela di ricadute possa curare la sua calvizie."}},faq={{q="Chi offre la missione Gnogaine?",a="Ozzie Valvotron, un inventore gnomo di Kharanos, propone questo incarico.",al={"chi dà gnogaine","datore di missione gnogaine","missione ozzie valvotron"}},{q="Cosa devo raccogliere per questa missione?",a="Usa una Fiala della Raccolta Vuota sugli Irradiated Invaders o sugli Irradiated Pillagers luminosi per raccogliere ricadute radioattive finché la fiala non è piena.",al={"obiettivo gnogaine","cosa raccogliere gnogaine","fiala della raccolta piena"}},{q="Dove posso trovare i trogg irradiati?",a="Trova i trogg irradiati nelle caverne esterne dell'ingresso e nei corridoi tortuosi che conducono al portale dell'istanza di Gnomeregan. Puoi raggiungerli senza entrare nel dungeon.",al={"dove sono i trogg irradiati","posizione trogg gnogaine","posizione invasore irradiato"}},{q="Devo completare 'The Day After' prima di accettare questa missione?",a="No. Ozzie propone questo incarico indipendentemente da The Day After, anche se quella storia è legata alla situazione di Kharanos e fa da preludio a questa.",al={"the day after è richiesto","prerequisito gnogaine"}},{q="Cosa sta cercando di ottenere Ozzie con il fallout radioattivo?",a="Ozzie e Razzle stanno cercando di preparare una cura per gli gnomi contaminati, anche se Ozzie ammette che l'intruglio potrebbe diventare un rum molto forte.",al={"perché ozzie vuole la radiazione","a cosa serve gnogaine"}},{q="Quale missione segue Gnogaine?",a="Una fiala piena dà inizio a The Only Cure is More Green Glow, che ti manda più in profondità a Gnomeregan.",al={"proseguimento gnogaine","cosa viene dopo gnogaine"}}},fx={["28ada800"]={q="A cosa serve la Fiala della Raccolta Piena?",a="La fiala è schermata con piombo per contenere e trasportare in sicurezza le pericolose scorie radioattive luminescenti estratte dai trogg nei dintorni di Gnomeregan. Ozzie Valvotron e Razzle Mollapazza hanno bisogno di questa materia radioattiva concentrata come ingrediente essenziale per la loro mistura sperimentale, che sperano possa curare il loro prigioniero gnomo lebbroso, produrre un rum straordinariamente potente o, magari, far ricrescere i capelli di Ozzie.",al={"a cosa serve la fiala della raccolta piena","perché la fiala di piombo","scopo della fiala della raccolta di piombo"}},dfd2dab8={q="Cosa sono i trogg irradiati di Gnomeregan?",a="I trogg sono sbucati dalle profondità sotto Gnomeregan, invadendo quella città, meraviglia della tecnologia. Nel disperato tentativo di annientare l'invasione, l'Alto Tinkmaster Mekkatorque e i suoi consiglieri hanno inondato i corridoi inferiori di radiazioni tossiche. Invece di morire, molti trogg sono sopravvissuti, trasformandosi in feroci invasori e razziatori irradiati, ora avvolti da un malsano bagliore verde radioattivo.",al={"invasori irradiati","razziatori irradiati","perché i trogg sono irradiati"}}},fp="8,183,20.360.0,19.298.0,19.200.1,30.65.0,41.146.0,39.164.0,63.128.0,64.118.0,28.95.0"}
P.entries["quest:2927"] = {n="The Day After",s="A Forgiardente e Kharanos, i sopravvissuti di Gnomeregan cercano una risposta alla rovina della loro città. Gnoarn manda i viaggiatori da Ozzie Valvotron, che studia la contaminazione e spera di trovare una soluzione.",h="A Forgiardente e Kharanos, i sopravvissuti di Gnomeregan cercano una risposta alla rovina della loro città.",kw={"gnoarn","gnomefro","gnomeregan","kharanos","ozzie valvotron","fuga di radiazioni","the day after","trogg"},ang={["faction:Alliance"]="Da eroe dell'Alleanza, aiuti i pensatori gnomi di Dun Morogh a contenere lo strano disastro biochimico che minaccia il regno montano.",["profession:Engineering"]="Da ingegnere, vedi Ozzie Valvotron mettere alla prova le sue idee mentre gli inventori gnomi affrontano un disastro tecnologico fuori controllo.",["race:Gnome"]="Da gnomo, conosci il lamento di Gnoarn. Racchiude la tragedia, l'eccentrico orgoglio e l'amara sete di vendetta dei profughi cacciati dalla loro capitale."},sec={{t="Una perdita tragica",b="A Tinker Town, a Forgiardente, Gnoarn piange Gnomeregan e la perdita del suo gnomefro. Gli invasori trogg hanno conquistato la città meccanica, e le ricadute tossiche gli hanno portato via la sua preziosa chioma. La furia contro i trogg e la speranza di riconquistare la città lo spingono a mandare viaggiatori comprensivi dai colleghi che possono salvare ciò che resta."},{t="La strada per Kharanos",b="A Kharanos, gli gnomi ingegnosi hanno iniziato ad affrontare le ricadute. Gnoarn manda i viaggiatori da Ozzie Valvotron, che lavora con la sua socia Razzle Mollapazza. Ozzie ricorda la catastrofe, quando i capelli di Gnoarn caddero a ciocche e presero il sopravvento la follia e la sete di vendetta. Ora Ozzie studia la contaminazione nella cittadina innevata e usa le sue abilità ingegneristiche per cercare un antidoto."}},faq={{q="Chi è Gnoarn?",a="Gnoarn è un profugo gnomo a Tinker Town, a Forgiardente. Gli invasori trogg e la catastrofe delle condotte radioattive lo hanno reso amareggiato, e la perdita improvvisa del suo un tempo fiero gnomefro lo ha scosso profondamente.",al={"gnoarn","gnomo calvo","chi dà the day after"}},{q="Perché Gnoarn ti manda da Ozzie Valvotron?",a="Gnoarn spera che Gnomeregan possa ancora essere salvata. Ozzie Valvotron e la sua socia Razzle Mollapazza sono a Kharanos, dove studiano la radiazione tossica che avvolge la città e cercano di creare una cura.",al={"perché andare da ozzie","missione di ozzie valvotron","ingegnere di kharanos"}},{q="Cosa è successo a Gnomeregan per causare tutto questo?",a="Durante una vasta invasione trogg sotto la città, il Gran Meccanista Gelbin Meccatork fu convinto a riversare rifiuti tossici radioattivi nelle sale inferiori per sterminarli. Il piano fallì. Innumerevoli gnomi morirono o furono mutati, Gnomeregan divenne inabitabile e i trogg sopravvissero.",al={"cosa è successo a gnomeregan","perché gnomeregan è irradiata","invasione trogg"}},{q="Dove conduce questa catena di missioni dopo aver raggiunto Ozzie?",a="Dopo aver parlato con Ozzie, ti chiede di raccogliere le ricadute radioattive dai trogg irradiati fuori da Gnomeregan. Proverà miscele sperimentali per neutralizzarle.",al={"seguiti di the day after","cosa viene dopo the day after","missione successiva"}}},fx={b3abdd6a={q="Perché Gnoarn vuole che si faccia questa cosa?",a="Gnoarn è animato da una rabbia personale e da una speranza ostinata. Le scorie radioattive che hanno rovinato Gnomeregan gli hanno portato via anche ciò che più gli era caro: l'unico gnomo-ciuffo di tutta Azeroth. Amareggiato per la sua calvizie e assetato di vendetta contro i trogg invasori, si rifiuta di abbandonare la sua casa. Crede che, indirizzando avventurieri capaci da Ozzie Valvotron, ci sia ancora una possibilità di porre rimedio al disastro e riconquistare la città.",al={"motivazioni di gnoarn","perché aiutare gnoarn","perché interessa a gnoarn"}}},fp="13,196,13.310.0,20.381.0,14.200.0,45.194.0,42.273.0,54.170.0"}
P.entries["quest:2928"] = {n="Gyrodrillmatic Excavationators",s="Nel Distretto dei Nani di Roccavento, Shoni la Shilente prepara le macchine da scavo per Dun Morogh. Le mancano dei pezzi, così ti manda a recuperarli dagli automi ribelli di Gnomeregan.",h="Nel Distretto dei Nani di Roccavento, Shoni la Shilente prepara le macchine da scavo per Dun Morogh.",kw={"dun morogh","distretto dei nani","excavationators","gnomeregan","ingegneria gnomica","gyrodrillmatic","interiora robomeccaniche","shoni la shilente"},ang={["faction:Alliance"]="Come membro dell'Alleanza, aiutare gli gnomi a preparare le macchine da scavo a Roccavento rafforza i legami tra i loro ospiti umani e i sopravvissuti esiliati che lavorano per riconquistare la propria eredità.",["profession:Engineering"]="Come ingegnere, estrarre con precisione gli ingranaggi dai servitori caduti di Gnomeregan offre una lezione pratica sul design gnomico e sulla riparazione di macchinari pesanti.",["race:Gnome"]="Come gnomo, ogni componente recuperato avvicina la flotta sotterranea di Shoni al pieno funzionamento. Da Roccavento, il sogno della riconquista e della ripresa industriale continua a vivere."},sec={{t="Una flotta che ha bisogno di interiora",b="Nel Distretto dei Nani aspettano di essere messe a punto centinaia di Gyrodrillmatic Excavationators. Gli ingegneri gnomi aiutano i loro simili sfollati. Le macchine trasporteranno persone e rifornimenti sottoterra, ma questi enormi macchinari non possono funzionare senza i pezzi meccanici che mancano a Shoni."},{t="Recupero nella città caduta",b="Un tempo Gnomeregan riforniva gli gnomi di tecnologia avanzata. Le sue sale in rovina e i tunnel vicini contengono ancora macchine da recuperare, anche se robot difensivi malfunzionanti, sentinelle meccaniche e operai a orologeria vagano senza controllo. Shoni ti manda nella città caduta a raccogliere due dozzine di fasci di Interiora Robomeccaniche, da riportare nelle terre degli umani."},{t="Un'impresa monumentale",b="Due dozzine di fasci di Interiora Robomeccaniche forniscono abbastanza rottami per riparare un Gyrodrillmatic Excavator. Shoni ha ancora quasi quattrocento macchine da preparare, perciò il trasporto sotterraneo su larga scala procede a rilento. Ogni macchina funzionante è un piccolo passo verso la riconquista del terreno perduto dopo la caduta di Gnomeregan."}},faq={{q="Cos'è un Gyrodrillmatic Excavationator?",a="Un Gyrodrillmatic Excavator è un pesante macchinario gnomico da scavo, detto anche macchina talpa, progettato per scavare e trasportare persone o rifornimenti sottoterra. Shoni la Shilente ne sta preparando una flotta per Dun Morogh.",al={"gyrodrillmatic excavationators","cos'è un excavationator","trivella gnomica"}},{q="Chi è Shoni la Shilente?",a="Shoni la Shilente è un'ingegnera gnomica nel Distretto dei Nani di Roccavento. Schietta e autoritaria, sta preparando centinaia di macchine da scavo.",al={"shoni la shilente","shoni","chi è shoni"}},{q="Perché Shoni ha bisogno proprio di parti provenienti da Gnomeregan?",a="Un tempo Gnomeregan riforniva gli gnomi di tecnologia avanzata, e le sue sale cadute ospitano automi impazziti, servitori a orologeria e mech difensivi. Le linee di rifornimento della città sono interrotte, perciò queste macchine ribelli offrono pezzi di ricambio gnomici compatibili.",al={"perché parti da gnomeregan","perché interiora robotiche","recupero a gnomeregan"}},{q="Dove si trovano le Interiora Robomeccaniche?",a="Puoi recuperare le Interiora Robomeccaniche dalle sentinelle meccaniche, dai costrutti a orologeria e da altre macchine ostili nella struttura in rovina di Gnomeregan e nei tunnel superiori circostanti.",al={"interiora robomeccaniche","dove trovare le interiora","interiora meccaniche gnomeregan"}},{q="Riparare una macchina completa la flotta di Shoni?",a="No. Due dozzine di fasci di Interiora Robomeccaniche riparano un macchinario. Shoni dice che gliene restano ancora trecentonovantotto da preparare.",al={"quanti excavationator","dimensione flotta shoni","quante trivelle"}},{q="Perché viene preparata una flotta di scavo per Dun Morogh?",a="Dun Morogh è la patria ancestrale degli gnomi e il luogo in cui sorgeva la loro capitale, ormai caduta. I pesanti macchinari da scavo possono aiutare a scavare, rimuovere le macerie e sostenere i lavori tra le montagne innevate.",al={"flotta per dun morogh","perché dun morogh","scopo degli escavatori"}}},fx={b2dc5b24={q="A cosa servono le Interiora Robomeccaniche?",a="Shoni la Shilente ne ha bisogno come componenti interni di recupero per riparare la sua flotta di Gyrodrillmatic Excavationators. La complessa ingegneria di questi veicoli per gli scavi sotterranei richiede ingranaggi di precisione, cablaggi e attuatori, difficili da forgiare da zero a Roccavento. Recuperando le interiora funzionanti degli automi a orologeria che vagano per Gnomeregan, può trovare i pezzi di ricambio essenziali per rimettere in funzione i suoi impianti di perforazione a terra.",al={"a cosa servono le interiora robomeccaniche","uso delle interiora robomeccaniche","uso delle interiora per shoni"}},["1cb24930"]={q="Per cosa combatti all'interno di Gnomeregan per conto di Shoni?",a="Ti viene chiesto di smantellare i robot e i mech impazziti che vagano per i corridoi irradiati e le periferie di Gnomeregan. Quando la capitale sotterranea degli gnomi cadde sotto l'invasione dei trogg e le scorie radioattive, innumerevoli sistemi di difesa automatizzati e congegni di servizio si guastarono, diventando ostili agli estranei. Per Shoni questi automi abbandonati e vaganti non sono solo pericoli, ma anche un mucchio di rottami da cui recuperare pezzi.",al={"chi devo combattere per shoni","bersagli a gnomeregan per le interiora","quali macchine hanno le interiora"}},["33a01105"]={q="Perché Shoni ha bisogno che tu raccolga i pezzi invece di andarci lei stessa?",a="Shoni è un'ingegnera di stanza nel Distretto dei Nani di Roccavento, impegnata a mantenere i macchinari e a supervisionare l'assemblaggio di una vasta flotta di scavatori. Avventurarsi in una rovina irradiata e infestata di trogg, invasa da letali sentinelle a orologeria, richiede un avventuriero armato disposto a farsi strada in corridoi pericolosi. Lei resta indietro per esaminare i rottami e riparare gli impianti man mano che arrivano i componenti.",al={"perché mi mandano a recuperare le interiora","perché shoni non va di persona","perché io per la missione di shoni"}}},fp="30,178,23.272.0,26.332.0,24.290.0,40.208.0,25.146.0,55.250.0,41.172.0,45.115.0,57.182.0"}
P.entries["quest:2929"] = {n="The Grand Betrayal",s="Gran Meccanista Mekkatorque ti chiede di colpire Mekgeniere Termospin, che ha tradito lui e il popolo degli gnomi. Il dominio di Termospin impedisce agli gnomi di riconquistare Gnomeregan.",h="Gran Meccanista Mekkatorque ti chiede di colpire Mekgeniere Termospin, che ha tradito lui e il popolo degli...",kw={"tradimento","gnomeregan","gnomi","gran meccanista mekkatorque","mekgeniere termospin","riconquistare gnomeregan","il grande tradimento"},ang={["race:Gnome"]="Da gnomo, la richiesta di Mekkatorque riguarda la patria perduta del tuo popolo e la sua lotta per riconquistare Gnomeregan."},sec={{t="L'appello di Mekkatorque",b="Gran Meccanista Mekkatorque cerca il tuo aiuto nella lotta per restituire Gnomeregan al popolo degli gnomi. Si fidava di Mekgeniere Termospin, ma Termospin ha tradito lui e gli gnomi. Ora gli gnomi sono stati allontanati dalla loro città, e Termospin ne è il padrone. Mekkatorque ti chiede di sconfiggere il traditore, così i loro piani per riconquistare la città potranno avanzare."},{t="La rivendicazione della città",b="Dopo la morte di Mekgeniere Termospin, Mekkatorque dice che gli gnomi sono più vicini a riprendersi Gnomeregan."}},faq={{q="Chi ha tradito gli gnomi?",a="Mekgeniere Termospin ha tradito Gran Meccanista Mekkatorque e il popolo degli gnomi.",al={"tradimento di termospin","chi ha tradito gli gnomi"}},{q="Perché gli gnomi sono stati allontanati?",a="Mekkatorque dice che il tradimento di Termospin ha costretto gli gnomi a lasciare Gnomeregan, che ora è sotto il suo controllo.",al={"gnomi allontanati","perché lasciare gnomeregan"}},{q="Chi chiede aiuto contro Termospin?",a="Gran Meccanista Mekkatorque ti chiede di uccidere Mekgeniere Termospin.",al={"richiesta di mekkatorque","chi vuole morto termospin"}},{q="Cosa vuole Mekkatorque per Gnomeregan?",a="Mekkatorque e gli gnomi vogliono riportare Gnomeregan sotto il loro controllo.",al={"riconquistare gnomeregan","piani per la città degli gnomi"}}},fp="18,173,20.349.0,18.102.1,24.78.0,29.110.0,38.63.0,42.69.0"}
P.entries["quest:293"] = {n="Cleansing the Eye",s="Nelle Paludi Grigie, Cleansing the Eye manda gli avventurieri a sud, a Roccavento, con un globo maledetto. Dopo aver recuperato l'Occhio di Paleth, cercano l'Arcivescovo Benedictus perché ne purifichi la corruzione persistente.",h="Nelle Paludi Grigie, Cleansing the Eye manda gli avventurieri a sud, a Roccavento, con un globo maledetto.",kw={"arcivescovo benedictus","cathedral of light","cleansing the eye","occhio di paleth maledetto","occhio di paleth","glorin frontesalda","roccavento","paludi grigie"},ang={["class:Paladin"]="I paladini considerano recuperare le reliquie sacre dalle paludi oscure un dovere solenne. La corruzione dell'Occhio è un affronto da purificare nelle sale consacrate di Roccavento.",["class:Priest"]="Per i sacerdoti della Sacra Luce, l'Occhio di Paleth Maledetto dimostra come la disperazione possa corrompere l'arte sacra. Serve la purificazione dell'Arcivescovo Benedictus per mondarlo.",["faction:Alliance"]="Gli avamposti nanici delle Paludi Grigie e le guide spirituali di Roccavento collaborano grazie alla fede condivisa, unendo i regni dell'Alleanza."},sec={{t="Una reliquia corrotta",b="L'Occhio di Paleth recuperato dalle paludi non brilla di Sacra Luce. L'ombra vi si aggrappa, insieme al dolore e al trauma della tragedia in cui andò perduto. Glorin Frontesalda, un nano, riconosce il potere del globo. Ma gli manca l'arte divina necessaria a spezzare una maledizione così grave."},{t="Viaggio alla Cattedrale",b="Furono i sacerdoti umani della Sacra Luce a creare gli Occhi di Paleth, perciò solo il loro ordine più elevato sa come annullarne la profanazione. Glorin manda gli avventurieri a sud, a Roccavento, con il globo oscurato, dall'Arcivescovo Benedictus, guida della Chiesa della Luce Sacra. Benedictus conosce il pericolo di lasciare una reliquia simile senza purificazione. Si assume il compito di restituirle la sua luce sacra."}},faq={{q="Cos'è l'Occhio di Paleth?",a="Gli Occhi di Paleth sono globi sacri creati dai sacerdoti umani perché risplendano di luce santa. Quando sono integri, il loro potere si accorda con la Sacra Luce. Se corrotti, i loro poteri diventano instabili e pericolosi.",al={"conoscenze sull'occhio di paleth","cos'è questo globo","cos'è l'occhio di paleth"}},{q="Perché Glorin Frontesalda non può purificare l'Occhio da solo?",a="Glorin Frontesalda non può purificare l'Occhio perché gli manca l'arte liturgica necessaria a scacciarne l'afflizione oscura. La reliquia fu creata dai sacerdoti umani della Sacra Luce, quindi per purificarne la corruzione serve l'autorità di quella tradizione.",al={"perché andare a roccavento","purificazione di glorin","perché benedictus"}},{q="Chi è l'Arcivescovo Benedictus?",a="L'Arcivescovo Benedictus è la venerabile guida della Chiesa della Luce Sacra. Risiede nella Cathedral of Light di Roccavento e guida l'Alleanza nelle questioni di fede.",al={"chi è benedictus","arcivescovo benedictus","arcivescovo di roccavento"}},{q="Perché l'Occhio viene descritto come sporco o addolorato?",a="L'Arcivescovo Benedictus dice che il globo fu testimone di una grande tragedia nelle Paludi Grigie. Col tempo assorbì quell'agonia, e il dolore che vi rimase si trasformò in una maledizione che ne distorse il potere.",al={"perché è maledetto","tragedia dell'occhio di paleth","occhio di paleth maledetto"}},{q="Cosa succede quando Benedictus riceve il globo?",a="Benedictus accetta di purificare il globo. Gli Occhi di Paleth dovrebbero brillare intensamente, e la loro corruzione comporta gravi pericoli spirituali e fisici per chi si trova nelle vicinanze.",al={"benedictus lo purifica","esito dell'occhio di paleth"}},{q="Dove si trova la Cathedral of Light?",a="La Cathedral of Light si trova in Piazza della Cattedrale, nel quartiere settentrionale di Roccavento. L'Arcivescovo Benedictus è presso l'altare maggiore, nel cuore del santuario.",al={"dove si trova la cathedral of light","posizione della cathedral of light","trovare benedictus"}}},fx={["6f168d84"]={q="Perché Glorin Frontesalda vuole che l'Occhio di Paleth venga purificato?",a="Glorin riconosce che l'Occhio di Paleth Maledetto è una reliquia sacra estremamente pericolosa. Creato dai sacerdoti umani della Luce Sacra perché risplendesse intensamente, la sua magia diventa pericolosa e corruttrice quando è contaminata dalla tragedia e dal potere oscuro. Poiché né l'arte dei nani né le sue abilità possono rimuovere una simile afflizione spirituale, insiste perché venga portato a Roccavento prima che la corruzione causi altri danni a te o alle terre circostanti.",al={"perché purificare l'occhio di paleth","motivazioni di glorin frontesalda","perché mandare l'occhio a roccavento"}}},fp="17,203,15.267.0,24.379.0,26.194.0,51.224.0,29.168.0,48.180.0,46.160.0,40.167.0"}
P.entries["quest:2930"] = {n="Data Rescue",s="Il Maestro Meccanico Tuboduro ti manda a Gnomeregan per recuperare i suoi archivi. Trogg e radiazioni hanno costretto gli gnomi a lasciare la città, ma i terminali perforacarte proteggono ancora gli archivi dietro diversi livelli di autorizzazione.",h="Il Maestro Meccanico Tuboduro ti manda a Gnomeregan per recuperare i suoi archivi.",kw={"tuboduro","data rescue","engineering labs","gnomeregan","matrix punchograph","scheda perforata prismatica","scheda perforata","tinker town","train depot"},ang={["faction:Alliance"]="Come membro dell'Alleanza, aiuti il governo gnomico in esilio a Forgiardente sostenendo Tuboduro. Il tuo aiuto rafforza l'unità e le capacità tecnologiche della Grande Alleanza.",["profession:Engineering"]="Come ingegnere, puoi studiare come la rete Matrix Punchograph archivia i dati e usa gli elaborati meccanismi di autorizzazione ideati dalla Tinkers' Court.",["race:Gnome"]="Come gnomo, contribuisci a recuperare il patrimonio del tuo popolo riportando alla luce i dati di Gnomeregan. Ogni scheda perforata recuperata preserva l'ingegno della tua città da trogg e radiazioni."},sec={{t="Archivi perduti del sottosuolo",b="Trogg e radiazioni hanno costretto gli abitanti di Gnomeregan a lasciare la città, abbandonando secoli di ricerche, schemi e registri civici. I terminali Matrix Punchograph sono ancora disposti lungo i corridoi tecnologici. Gestiscono le autorizzazioni di sicurezza e archiviano i file. Il Maestro Meccanico Tuboduro, a Tinker Town, Forgiardente, vuole che recuperi quegli archivi codificati con schede perforate dalle profondità della città."},{t="Una gerarchia di perforazioni",b="I mainframe gnomici richiedono autorizzazioni per gradi. Per prima cosa, trova una Scheda Perforata Bianca tra i rottami fuori dai cancelli interni. Inseriscila nel Matrix Punchograph 3005-A al Train Depot per ottenere una scheda gialla. Poi portala al terminale 3005-B nel Dormitorio per ottenere una scheda blu. Il modello 3005-C la trasforma in una scheda rossa. L'ultimo terminale, il 3005-D, si trova negli Engineering Labs, dove la Scheda Perforata Rossa diventa una Scheda Perforata Prismatica."},{t="Leggerezza gnomica in binario",b="Le schede perforate di Gnomeregan contengono documenti tecnici e molto altro. I loro schemi binari custodiscono anche battute umoristiche, lamentele sul lavoro e barzellette piccanti su Gelbin Meccatork, Gran Meccanico, che indossa biancheria intima degli elfi della notte. Neppure le gilde informatiche della città hanno resistito a uno scherzo."}},faq={{q="Cos'è la Scheda Perforata Prismatica?",a="La Scheda Perforata Prismatica è il livello di sicurezza più alto riconosciuto dai mainframe automatizzati di Gnomeregan. Il Matrix Punchograph 3005-D negli Engineering Labs la crea a partire da una Scheda Perforata Rossa.",al={"scheda prismatica","cos'è una scheda perforata","scheda perforata di gnomeregan"}},{q="Dove inizia la sequenza delle schede perforate?",a="La sequenza inizia con una Scheda Perforata Bianca recuperata da trogg e rottami meccanici fuori dall'ingresso principale, vicino al Train Depot.",al={"dove trovare la scheda perforata bianca","come iniziare con le schede perforate","prima scheda perforata"}},{q="Dove si trovano i terminali Matrix Punchograph?",a="Il Matrix Punchograph 3005-A si trova al Train Depot, fuori dall'ingresso. Il modello 3005-B è nel Dormitorio, oltre la Clean Zone, mentre il 3005-C è sulle passerelle sopraelevate più avanti. Il modello 3005-D è al livello inferiore degli Engineering Labs.",al={"posizioni dei terminali","dove sono i punchograph","macchine per schede perforate"}},{q="Chi è il Maestro Meccanico Tuboduro?",a="Il Maestro Meccanico Tuboduro è un ingegnere gnomico esperto tra i rifugiati di Tinker Town, a Forgiardente. Coordina gli sforzi per recuperare il patrimonio intellettuale di Gnomeregan dall'antica capitale caduta.",al={"tuboduro","chi assegna data rescue","storia di tuboduro"}},{q="Quali dati sono effettivamente sulle schede?",a="Le schede custodiscono dati computazionali fondamentali, battute tra ingegneri gnomici, scherzi bonari sui leader delle varie regioni come Thrall e Meccatork, e appunti stravaganti.",al={"testo della scheda","traduzione binaria","cosa dice il binario"}},{q="I personaggi dell'Orda possono accedere a questi terminali?",a="Il Maestro Meccanico Tuboduro affida questo incarico solo all'Alleanza, a Forgiardente. Chiunque abbia le schede richieste può usare i terminali perforacarte all'interno del dungeon.",al={"recupero dati orda","schede perforate orda","l'orda può usare i terminali"}}},fx={["0f0753b5"]={q="Perché il Maestro Meccanico Tuboduro vuole che venga recuperata la scheda perforata?",a="Quando gli gnomi evacuarono Gnomeregan durante la sua caduta, montagne di dati operativi e tecnici essenziali furono abbandonate nel caos. Il Maestro Meccanico Tuboduro considera le informazioni conservate nei terminali ad alta sicurezza del Matrice Punzonatrice fondamentali per la sopravvivenza degli gnomi e per la ricostruzione, e insiste che non possono permettersi di perderle per sempre.",al={"motivazioni di tuboduro","perché tuboduro ha bisogno della scheda perforata","perché data rescue"}}},fp="11,210,32.373.0,27.423.0,24.288.1,33.186.0,45.138.0,51.234.0,32.192.0,35.163.0,41.165.0"}
P.entries["quest:2931"] = {n="Castpipe's Task",s="A Forgiardente, il Maestro Meccanico Tuboduro invita i viaggiatori a recuperare gli archivi di Gnomeregan. Le sale in rovina custodiscono ancora conoscenze meccaniche e tecniche vitali.",h="A Forgiardente, il Maestro Meccanico Tuboduro invita i viaggiatori a recuperare gli archivi di Gnomeregan.",kw={"assemblea","tuboduro","data rescue","gaxim","gnomeregan","forgiardente","scoppiarame","tinkertown"},ang={["faction:Alliance"]="In quanto alleato dell'Alleanza, sostieni i gnomi sfollati mentre recuperano i loro archivi perduti. Questo lavoro rafforza Tinkertown e la posizione tecnologica dell'Alleanza.",["profession:Engineering"]="In quanto ingegnere, sai che i nuclei dati di Gnomeregan custodiscono meraviglie computazionali e schemi avanzati senza pari su Azeroth.",["race:Gnome"]="In quanto gnomo, a ogni impresa di recupero contribuisci a preservare dalle radiazioni e dalla distruzione un frammento della tua casa caduta. Il lavoro di Tuboduro tocca la sopravvivenza del tuo popolo."},sec={{t="Una chiamata a Tinkertown",b="Dopo la caduta di Gnomeregan e la sua chiusura in quarantena radioattiva, i gnomi sopravvissuti trovarono rifugio a Tinkertown, a Forgiardente. Trogg e costrutti irradiati invadono ancora la loro vecchia casa. Nel profondo della città, matrici informatiche custodiscono registri operativi e schemi meccanici. Tuboduro cerca forestieri disposti ad affrontare le sale tossiche e a recuperare file che potrebbero spiegare cosa andò storto o aiutare i gnomi a tornare."},{t="Approvazione dell'Assemblea",b="Gaxim Scoppiarame, dell'Assemblea di Arcanologia, Alchimia e Scienze Ingegneristiche degli Illuminati, diffonde notizie sull'impresa di Tuboduro. Tuboduro non appartiene ad alcun corpo accademico, ma i suoi compagni gnomi rispettano la sua abilità e sostengono il suo lavoro. Scoppiarame valuta all'ottantaquattro per cento il valore strategico dell'operazione. I viaggiatori possono recarsi a Tinkertown per ricevere ordini."}},faq={{q="Chi è il Maestro Meccanico Tuboduro?",a="Il Maestro Meccanico Tuboduro è un ingegnere gnomo stimato a Tinkertown, a Forgiardente. Organizza squadre di recupero per riportare alla luce dati dalle rovine sotterranee di Gnomeregan.",al={"tuboduro","chi è tuboduro","maestro meccanico tuboduro"}},{q="Perché Tuboduro vuole i dati da Gnomeregan?",a="Quando Gnomeregan fu contaminata ed evacuata, la memoria del suo computer centrale custodiva conoscenze tecniche fondamentali, progetti e registri interni di sistema. I gnomi sfollati hanno bisogno di queste informazioni mentre sperano di ricostruire la città.",al={"dati di gnomeregan","perché recuperare dati","registri di gnomeregan"}},{q="Chi è Gaxim Scoppiarame?",a="Gaxim Scoppiarame è uno studioso gnomo dell'Assemblea di Arcanologia, Alchimia e Scienze Ingegneristiche degli Illuminati. Sostiene l'impresa di recupero di Tuboduro e vi indirizza i viaggiatori capaci.",al={"gaxim","scoppiarame"}},{q="Dove si trova Tuboduro?",a="Il Maestro Meccanico Tuboduro si trova a Tinkertown, il quartiere abitato dagli gnomi nella zona orientale di Forgiardente.",al={"posizione di tuboduro","dove si trova tuboduro"}},{q="Cosa succede dopo essersi presentati a Tuboduro?",a="Presentarti al Maestro Meccanico Tuboduro ti conduce a Data Rescue, nella città caduta. I viaggiatori si addentrano nella parte contaminata di Gnomeregan per recuperare schede perforate e supporti di archiviazione.",al={"prossima missione","what comes next","dopo tuboduro"}},{q="Che cos'è l'Assemblea degli Illuminati di Arcanologia, Alchimia e Scienze Ingegneristiche?",a="L'Assemblea di Arcanologia, Alchimia e Scienze Ingegneristiche degli Illuminati è una stimata società gnomica dedita allo studio scientifico, magico e meccanico. Membri come Gaxim Scoppiarame usano la probabilità per valutare le imprese importanti.",al={"l'assemblea","assemblea degli illuminati"}}},fx={["0652d792"]={q="Perché Gaxim Scoppiarame ti manda dal Maestro Meccanico Tuboduro?",a="Gaxim Scoppiarame rispetta l'intelletto del Maestro Meccanico Tuboduro, anche se Tuboduro non fa parte dell'Assemblea Illuminata di Arcanologia, Alchimia e Scienze Ingegneristiche. Secondo i calcoli di Gaxim, c'è l'ottantaquattro per cento di probabilità che l'operazione di recupero dati che Tuboduro sta preparando a Gnomeregan sia davvero essenziale per gli gnomi. Considerate queste buone probabilità, Gaxim è ansioso di indirizzare avventurieri capaci verso Forgiardente per sostenere l'opera di riconquista.",al={"perché gaxim ti manda","motivazioni di gaxim scoppiarame","perché parlare con tuboduro"}}},fp="15,157,20.417.0,20.356.0,32.167.0,44.217.0,24.190.0,28.111.0,41.184.0,81.231.0"}
P.entries["quest:2932"] = {n="Grim Message",s="A Rovotorto, Nimboya ti manda a nord a punire i troll Scorzasecca per aver tradito Thrall. Ti dà una picca per infilzarvi i loro teschi e piantarla in uno dei loro villaggi nelle Entroterre.",h="A Rovotorto, Nimboya ti manda a nord a punire i troll Scorzasecca per aver tradito Thrall.",kw={"grim message","entroterre","hiri'watha","nimboya","mulino di tarren","thrall","scorzasecca","zun'watha"},sec={{t="Un Messaggio Cupo",b="Nimboya ti manda da Rovotorto alle Entroterre, molto a nord e a nord-est di Mulino di Tarren, un villaggio tenuto dai Reietti. Un tempo i troll Scorzasecca erano alleati dell'Orda, ma hanno tradito Thrall. Dai loro la caccia per raccoglierne i teschi, poi pianta la picca di Nimboya a Hiri'watha o Zun'watha, due dei loro villaggi più piccoli. L'avvertimento mostrerà loro quanto costano le loro azioni. Nimboya ti aspetta a Rovotorto."}},faq={{q="Perché Nimboya vuole punire i troll Scorzasecca?",a="Un tempo i troll Scorzasecca erano alleati dell'Orda, poi si sono rivoltati contro Thrall. Nimboya dice che il loro tradimento non può restare impunito.",al={"perché attaccare gli scorzasecca","tradimento degli scorzasecca","motivo di un messaggio cupo"}},{q="Dove ti manda Nimboya a piantare la picca?",a="Pianta la picca a Hiri'watha o Zun'watha, due villaggi minori dei troll Scorzasecca nelle Entroterre.",al={"dove piantare la picca","posizione della picca di nimboya","posizione di un messaggio cupo"}},{q="Dove si trovano le Entroterre rispetto a Mulino di Tarren?",a="Le Entroterre si trovano a nord-est di Mulino di Tarren, il villaggio tenuto dai Reietti. Sono molto a nord di Nimboya, a Rovotorto.",al={"posizione delle entroterre","dove sono le entroterre"}},{q="Chi dà Un Messaggio Cupo?",a="Nimboya ti dà la picca a Rovotorto e ti aspetta lì per avere tue notizie.",al={"consegnatario della missione un messaggio cupo","chi è nimboya"}}},fp="12,184,18.400.0,54.127.0,46.93.0,43.127.0,23.69.0"}
P.entries["quest:2933"] = {n="Venom Bottles",s="Nelle Entroterre, Venom Bottles riempiono un villaggio degli Scorzasecca. La loro grande quantità suggerisce che gli Scorzasecca apprezzino il vile veleno verde, e uno speziale nel vicino Mulino di Tarren potrebbe volerne un campione.",h="Nelle Entroterre, Venom Bottles riempiono un villaggio degli Scorzasecca.",kw={"speziale lydon","aracnoide","entroterre","mulino di tarren","veleno dei troll","bottiglia di veleno","scorzasecca"},sec={{t="Una scoperta tossica",b="Un vile veleno verde riempie le bottiglie sparse per il Villaggio degli Scorzasecca. Ce ne sono molte, segno che gli Scorzasecca considerano importante il veleno. Uno speziale del Mulino di Tarren potrebbe volerne un campione da esaminare."},{t="Il verdetto di Lydon",b="Lo Speziale Lydon non ha avuto fortuna con i suoi esperimenti quel giorno. Riconosce nel contenuto il veleno estratto da una creatura aracnoide, poi chiede da dove provenga."}},faq={{q="Dove si trovano le bottiglie di veleno?",a="Le bottiglie si trovano in gran numero in un villaggio degli Scorzasecca nelle Entroterre.",al={"posizione bottiglia di veleno","dove trovare bottiglie di veleno","veleno degli scorzasecca"}},{q="Chi è interessato alle bottiglie di veleno?",a="Uno speziale del Mulino di Tarren potrebbe volerne un campione. Lo Speziale Lydon è la persona da cercare.",al={"chi vuole il veleno","dove consegnare la bottiglia di veleno","speziale di mulino di tarren"}},{q="Cosa c'è nelle bottiglie?",a="Le bottiglie contengono un vile veleno verde. La loro grande quantità suggerisce che gli Scorzasecca lo apprezzino molto.",al={"cos'è il veleno","cosa c'è nelle bottiglie"}}},fp="13,191,17.205.0,15.175.1,34.82.0,39.83.0,23.95.0"}
P.entries["quest:2934"] = {n="Sacca di Veleno Intonsa",s="A Mulino di Tarren, lo Speziale Lydon cerca un campione fresco di veleno. Cerchi nelle Entroterre i ragni che lo producono, e il sacco deve arrivargli fresco.",h="A Mulino di Tarren, lo Speziale Lydon cerca un campione fresco di veleno.",kw={"speziale lydon","entroterre","shadra'alor","veleno di ragno","mulino di tarren","sacca del veleno"},sec={{t="Un campione fresco",b="Dopo Venom Bottles, lo Speziale Lydon ti chiede un campione più fresco. I ragni che producono il veleno vivono nelle Entroterre, molti nei pressi della città dei troll di Shadra'alor. Lydon vuole un Undamaged Venom Sac intatto, consegnato ancora fresco. Non vede l'ora di sperimentare e ha ordinato diversi piccoli animali terribilmente carini per i test."}},faq={{q="Chi richiede l'Undamaged Venom Sac?",a="Lo Speziale Lydon al Mulino di Tarren ti chiede il sacco e ne attende l'arrivo lì.",al={"chi consegna il sacco di veleno intatto","chi dà la missione del sacco di veleno intatto","committente del sacco di veleno intatto"}},{q="Dove si possono trovare i ragni?",a="Molti ragni vivono nelle Entroterre, vicino alla città dei troll di Shadra'alor.",al={"posizione ragni","dove si trovano i ragni","dove trovare il sacco di veleno intatto"}},{q="Perché lo Speziale Lydon dice di non perdere tempo?",a="Il sacco deve arrivare fresco, quindi Lydon vuole che tu glielo porti senza indugio.",al={"perché c'è un limite di tempo","perché il sacco si deteriora","tempo limite del sacco di veleno intatto"}},{q="Cosa c'era prima di questa fase?",a="Questa missione segue Venom Bottles, quando hai portato a Lydon un campione di veleno dal Villaggio degli Scorzasecca.",al={"missione precedente","quale missione precede il sacco di veleno intatto","prerequisito del sacco di veleno intatto"}}},fp="19,155,14.332.0,37.85.0,31.79.0,43.72.0,27.95.0"}
P.entries["quest:2935"] = {n="Consult Master Gadrin",s="Nel Villaggio di Sen'jin, lo Speziale Lydon cerca un campione di veleno più potente. Il veleno delle guardiacova che hai portato era più debole del tuo primo campione, quindi la fonte potrebbe essere un altro tipo di ragno.",h="Nel Villaggio di Sen'jin, lo Speziale Lydon cerca un campione di veleno più potente.",kw={"speziale lydon","consult master gadrin","durotar","entroterre","maestro gadrin","villaggio di sen'jin","veleno","witherbark"},sec={{t="Alla ricerca della potenza",b="Lo Speziale Lydon ha bisogno di un nuovo campione del veleno più potente. Il veleno delle guardiacova che hai portato era più debole del tuo primo campione, quindi deve provenire da un altro tipo di ragno.\n\nLydon ti manda dal Maestro Gadrin nel Villaggio di Sen'jin, a Durotar. Gadrin è un troll che conosce bene i Witherbark e potrebbe sapere da dove proviene il veleno."}},faq={{q="Perché lo Speziale Lydon ti manda dal Maestro Gadrin?",a="Il veleno delle guardiacova era più debole del tuo primo campione, il che indica un altro tipo di ragno. Il Maestro Gadrin conosce i Witherbark e potrebbe indicarti la fonte del veleno.",al={"perché consultare gadrin","perché andare a sen'jin","lydon gadrin"}},{q="Dove si trova il Maestro Gadrin?",a="Il Maestro Gadrin si trova nel Villaggio di Sen'jin, a Durotar.",al={"dove si trova gadrin","posizione maestro gadrin","trovare il maestro gadrin"}},{q="Cosa è successo prima di questo viaggio?",a="Prima di questo viaggio, hai portato allo Speziale Lydon una sacca di veleno intatta dalle Entroterre.",al={"prerequisiti","cosa c'era prima","missione precedente"}}},fp="21,180,20.335.0,52.163.0,31.48.0,30.94.0"}
P.entries["quest:2937"] = {n="Summoning Shadra",s="A Shadra'alor, leggi la pergamena del Maestro Gadrin e richiami Shadra dal regno Witherbark.",h="A Shadra'alor, leggi la pergamena del Maestro Gadrin e richiami Shadra dal regno Witherbark.",kw={"speziale lydon","entroterre","maestro gadrin","shadra","shadra'alor","dio ragno","mulino di tarren","witherbark"},sec={{t="Richiamo del Dio Ragno",b="Il Maestro Gadrin ti manda nel profondo del regno Witherbark delle Entroterre. A Shadra'alor, leggi la sua pergamena all'altare e Shadra, il dio ragno, risponde. Sconfiggila lì, poi porta il suo veleno allo Speziale Lydon al Mulino di Tarren."}},faq={{q="Chi fornisce la pergamena per evocare Shadra?",a="Il Maestro Gadrin ti dà la pergamena.",al={"chi fornisce summoning shadra","chi assegna summoning shadra"}},{q="Dove viene evocata Shadra?",a="Evoca Shadra all'altare di Shadra'alor, nel profondo del regno Witherbark delle Entroterre.",al={"dove evocare shadra","posizione altare di shadra'alor","posizione di shadra"}},{q="Chi riceve il veleno una volta sconfitta Shadra?",a="Dopo aver sconfitto Shadra, porti il suo veleno allo Speziale Lydon al Mulino di Tarren.",al={"a chi consegno il veleno","consegna summoning shadra","posizione speziale lydon"}}},fp="16,93,22.237.0,44.38.0,25.95.0,47.80.0"}
P.entries["quest:2938"] = {n="Venom to the Undercity",s="Lo Speziale Lydon invia a Sepulcra il veleno del dio ragno. La sua potenza lo entusiasma, e affida a te un pacco per il Maestro Speziale Faranell, suo superiore all'Apothecarium.",h="Lo Speziale Lydon invia a Sepulcra il veleno del dio ragno.",kw={"apothecarium","speziale lydon","pacco di faranell","maestro speziale faranell","shadra","venom to the undercity"},sec={{t="Un ritrovamento potente",b="Lo Speziale Lydon ha ucciso quasi due dozzine di conigli con una dose di veleno. Alcuni erano molto piccoli, quindi la loro resistenza era sicuramente bassa. Eppure il veleno è potente. Lydon è certo che il Maestro Speziale Faranell vorrà testarlo di persona e ti affida un pacco per l'Apothecarium a Sepulcra."}},faq={{q="Chi invia il pacco a Sepulcra?",a="Lo Speziale Lydon invia il pacco dopo aver testato il veleno prelevato dal dio ragno dei Witherbark.",al={"chi consegna il veleno a sepulcra","chi dà la missione venom to the undercity","chi avvia venom to the undercity"}},{q="Chi dovrebbe ricevere il veleno a Sepulcra?",a="Il Maestro Speziale Faranell, superiore di Lydon, deve ricevere il veleno all'Apothecarium di Sepulcra.",al={"chi riceve il pacco","dove va il veleno a sepulcra","chi è faranell"}},{q="Quanto è stato potente il veleno durante i test?",a="Una dose ha ucciso quasi due dozzine di conigli, anche se alcuni erano molto giovani e piccoli.",al={"quanto è forte il veleno di shadra","test di lydon sui conigli"}},{q="Cosa precede questa consegna?",a="La consegna avviene dopo Summoning Shadra, quando il veleno è stato prelevato dal dio ragno.",al={"missione precedente a venom to the undercity","prerequisito di venom to the undercity"}}},fp="22,163,13.286.0,43.93.0,54.107.0,40.79.0,32.84.0"}
P.entries["quest:2939"] = {n="In Search of Knowledge",s="Troyas Brezzaluna ti manda a cercare Daryn Ventolieve a Rut'theran. Ha trovato un bastone tra le macerie di Feralas e vuole scoprire di cosa si tratta.",h="Troyas Brezzaluna ti manda a cercare Daryn Ventolieve a Rut'theran.",kw={"angelas","darnassus","daryn ventolieve","feralas","rovine","rut'theran","bastone","troyas brezzaluna"},sec={{t="Un bastone comune",b="Troyas Brezzaluna dice che le rovine di Feralas sono pericolose, ma hanno molto da raccontare su ciò che è successo lì. Qualche giorno fa ha cercato tra le macerie a sud e ha trovato un bastone dall'aspetto comune. Eppure, sente che c'è dell'altro. Lui e Angelas hanno consultato i loro libri, ma non hanno trovato nulla sul bastone."},{t="Una collega a Darnassus",b="Troyas ha una collega a Darnassus che potrebbe sapere di cosa si tratta. Ti chiede di parlare con Daryn Ventolieve a Rut'theran."},{t="La risposta di Daryn",b="Daryn Ventolieve brontola perché Troyas continua a importunarla con le sue idee strampalate su qualcosa di importante che sarebbe stato trovato. Pensa che gli ogre o le arpie che ora vivono nelle rovine abbiano probabilmente portato via tutto ciò che aveva davvero valore molto tempo fa. Dice che puoi guardarti intorno, anche se dubita che i libri lì possano essere d'aiuto."}},faq={{q="Chi ti manda da Daryn Ventolieve?",a="Troyas Brezzaluna ti manda da Daryn perché vuole scoprire cosa sia davvero il bastone che ha trovato nelle rovine di Feralas.",al={"chi inizia in search of knowledge","datore di missione"}},{q="Cosa ha trovato Troyas?",a="Troyas ha trovato un bastone tra le macerie, a sud del luogo in cui lavora. Sembra comune, ma sente che c'è dell'altro.",al={"cosa ha trovato troyas","bastone di feralas"}},{q="Dov'è Daryn Ventolieve?",a="Daryn Ventolieve si trova a Rut'theran. Troyas la descrive come una collega di Darnassus.",al={"posizione di daryn ventolieve","dove si trova daryn"}},{q="Perché Troyas ti manda da Daryn?",a="Troyas e Angelas non hanno trovato nulla sul bastone nei loro libri. Daryn potrebbe riuscire a dirgli di cosa si tratta.",al={"perché visitare daryn ventolieve","perché darnassus"}}},fp="22,147,17.307.0,24.132.0,13.307.1,33.118.0,21.119.0,25.91.0,34.107.0"}
P.entries["quest:294"] = {n="Ormer's Revenge",s="Agli Scavi di Whelgar, Ormer Trecciaferro e i suoi due compagni si aggrappano a una scarpata sopra lo scavo invaso dai rapaci. Sotto il fango delle Paludi Grigie, i nani hanno scoperto enormi ossa preistoriche. I rapaci screziati sono arrivati in branchi e hanno ucciso gran parte della squadra.",h="Agli Scavi di Whelgar, Ormer Trecciaferro e i suoi due compagni si aggrappano a una scarpata sopra lo scavo...",kw={"rapace screziato","strillatore screziato","ormer trecciaferro","ormer's revenge","prospettore whelgar","paludi grigie","scavi di whelgar"},ang={["class:Hunter"]="Da cacciatore, puoi studiare come i pericolosi rapaci screziati si muovono seguendo tracce nel terreno paludoso sui pendii fuori dal sito.",["race:Dwarf"]="Da nano, vedere i tuoi simili uccisi durante uno scavo della Lega degli Esploratori può rendere ripulire la cava infestata dai rapaci un atto d'onore ancestrale e di giusta vendetta."},sec={{t="Orrori dissotterrati",b="I nani sono giunti agli Scavi di Whelgar per riportare alla luce enormi resti preistorici sotto il fango delle Paludi Grigie. La loro scoperta ha attirato i rapaci nativi della palude verso lo scavo. Branchi di predatori screziati hanno invaso il sito, colto di sorpresa gli scavatori e falciato i loro ranghi."},{t="Una resistenza amara",b="Solo pochi nani sono sopravvissuti. Ormer Trecciaferro, Merrin Plasmarocce e il Prospettore Whelgar si sono arrampicati in fretta su una scarpata sopra la fossa, ma i branchi aggressivi li tengono ancora bloccati lì. Ormer piange i compagni caduti ed è consumato dalla rabbia, ma resta a proteggere Merrin e il Prospettore. Chiede ai viaggiatori di decimare i rapaci screziati e gli strillatori screziati sottostanti. Questo è il primo colpo della sua vendetta."}},faq={{q="Cosa è successo agli scavatori qui?",a="I rapaci hanno sopraffatto lo scavo dopo che gli archeologi nani hanno scoperto ossa gigantesche nel bacino. Il disturbo ha attirato i branchi locali dalla palude. Hanno ucciso gran parte della squadra e intrappolato tre superstiti sulla scarpata più alta.",al={"perché i rapaci sono qui","massacro agli scavi di whelgar","cosa ha ucciso i nani"}},{q="Chi è Ormer Trecciaferro?",a="Ormer Trecciaferro è uno scavatore nano bloccato agli Scavi di Whelgar. Resta per proteggere il Prospettore Whelgar, ancora scosso, e Merrin Plasmarocce, mentre cerca una sanguinosa vendetta contro i rapaci che hanno ucciso i suoi compagni.",al={"chi è ormer","storia di ormer trecciaferro"}},{q="Da dove vengono questi rapaci?",a="I rapaci screziati e gli strillatori screziati sono predatori nativi delle Paludi Grigie. Si aggirano sui pendii fangosi e nelle paludi a ovest della scarpata dello scavo, e lungo i sentieri che conducono alle grotte del sito.",al={"dove si trovano i rapaci screziati","posizioni dei rapaci nelle paludi"}},{q="Perché Ormer non caccia i rapaci da solo?",a="Ormer vorrebbe uccidere i rapaci con le sue mani, ma deve proteggere il Prospettore Whelgar e Merrin Plasmarocce. Fa la guardia perché il rifugio dei nani terrorizzati sulla scarpata non venga invaso.",al={"perché ormer non combatte","perché ormer è bloccato"}},{q="Eliminare questi rapaci pone fine al rancore di Ormer?",a="No. Uccidere i comuni rapaci screziati e gli strillatori è solo il primo passo del piano di Ormer per vendicare gli amici caduti. Seguiranno colpi più duri contro la covata dei rapaci.",al={"questa è la fine della vendetta di ormer","cosa succederà a ormer"}},{q="Perché dissotterrare le ossa ha attirato i rapaci?",a="I rapaci delle Paludi Grigie sono spazzini ferocemente territoriali e aggressivi. Scavare gli antichi resti dei giganti ha sconvolto il bacino, attirando predatori curiosi e affamati nel cuore del campo di scavo.",al={"perché le ossa hanno attirato i rapaci","ossa di dinosauro rapaci"}}},fx={["87324e21"]={q="Perché Ormer Trecciaferro vuole che i raptor vengano uccisi?",a="Quando la squadra dei nani portò alla luce ossa antiche nel sito di scavo, raptor famelici invasero la zona e massacrarono i colleghi di Ormer. Ormer, Merrin Plasmarocce e Prospettore Whelgar sopravvissero a malapena all'assalto e sono ancora intrappolati in cima alle scogliere. Consumanto dal dolore e dalla furia, Ormer vuole vendicare i compagni caduti e iniziare a liberare lo scavo dalle feroci bestie.",al={"motivazioni di ormer trecciaferro","perché uccidere i raptor maculati","perché ormer vuole vendetta"}},["79eca2c5"]={q="Cosa sono i Raptor Maculati e gli Strillatori contro cui ti mandano?",a="Ti mandano contro i Raptor Maculati e gli Strillatori Maculati che si aggirano appena a ovest della scogliera dello scavo. Questi rettili aggressivi, originari delle Paludi, hanno invaso il sito non appena gli scavatori hanno portato alla luce enormi ossa antiche, massacrando gli addetti agli scavi e reclamando il terreno circostante come territorio di caccia.",al={"contro chi stai combattendo","bersaglio degli strillatori maculati","raptor maculati delle paludi"}}},fp="15,243,17.279.0,14.398.0,37.221.0,23.229.0,33.196.0,43.176.0,46.176.0,49.197.0"}
P.entries["quest:2940"] = {n="Feralas: Una Storia",s="A Feralas trovi Feralas: A History, un libro che potrebbe servire a Troyas. Sembra che nessuno lo apra da secoli. Il libro appartiene a Daryn Ventolieve, quindi devi chiederle se puoi prenderlo in prestito.",h="A Feralas trovi Feralas: A History, un libro che potrebbe servire a Troyas.",kw={"libro","daryn ventolieve","feralas","storia","in search of knowledge","lore","troyas"},sec={{t="Un libro trascurato",b="Le copertine del libro sono molto consumate e le pagine sono ingiallite. Dopo averlo esaminato, sospetti che possa essere ciò che Troyas sta cercando. Lo prendi, poi ci ripensi: è meglio non prenderlo in prestito senza chiedere. Appartiene a Daryn Ventolieve, quindi chiedile prima."},{t="La risposta di Daryn",b="Daryn Ventolieve si prende un momento per riflettere sulla tua richiesta. Ti lascerà prendere in prestito Feralas: A History, ma solo dopo che le avrai fatto un favore."}},faq={{q="Che cos'è Feralas: A History?",a="Feralas: A History ha le copertine consumate e le pagine ingiallite. Sembra che nessuno lo apra da secoli e potrebbe essere proprio ciò che Troyas sta cercando.",al={"cos'è il libro","libro feralas a history","libro di troyas"}},{q="Chi possiede il libro?",a="Il libro appartiene a Daryn Ventolieve. Chiedile prima di prenderlo in prestito.",al={"chi possiede feralas a history","chi ha il libro","chi è daryn ventolieve"}},{q="Cosa viene prima di questo?",a="Viene dopo In Search of Knowledge, quando Troyas Brezzaluna ti ha mandato a parlare con Daryn Ventolieve del suo bastone.",al={"missione precedente","qual era l'ultima missione","catena prima di questa"}}},fp="18,192,16.252.0,14.142.1,36.148.0,18.59.0,23.117.0"}
P.entries["quest:2941"] = {n="The Borrower",s="Sulla spiaggia nelle Entroterre, Daryn Ventolieve desidera vedere Gammerita, una mandibola scattante gigante. Le sue ricerche la tengono lontana, così ti manda a Tanaris con una lettera per Curgle Criccaleva.",h="Sulla spiaggia nelle Entroterre, Daryn Ventolieve desidera vedere Gammerita, una mandibola scattante gigante.",kw={"curgle criccaleva","daryn ventolieve","gammerita","mandibola scattante","istantanea","fotomatic fx","tanaris","the borrower"},sec={{t="Una foto di Gammerita",b="Daryn Ventolieve ha studiato molti soggetti. Ora le mandibole scattanti lungo la spiaggia nelle Entroterre attirano la sua attenzione, soprattutto Gammerita, una mandibola scattante gigante. Le sue ricerche la trattengono dov'è, così ti chiede di riportarle una foto di Gammerita."},{t="La lettera per Tanaris",b="Daryn ti consegna una lettera per Curgle Criccaleva a Tanaris. Curgle ha realizzato un'invenzione in grado di catturare un'immagine. Daryn crede che Curgle la chiami istantanea."},{t="La reazione di Curgle",b="Curgle ti scambia per uno degli stagisti di Daryn e la elogia come storica esperta. Poi va a prendere il Fotomatic FX. È certo che ti piacerà."}},faq={{q="Chi ti manda a Tanaris?",a="Daryn Ventolieve ti manda a Tanaris con una lettera. Le sue ricerche le impediscono di andarci di persona.",al={"datore di missione","chi dà the borrower","daryn ventolieve"}},{q="Chi è Curgle Criccaleva?",a="Curgle Criccaleva si trova a Tanaris e ha realizzato per Daryn un'invenzione in grado di catturare un'immagine. Daryn crede che Curgle la chiami istantanea.",al={"chi è curgle","posizione curgle criccaleva","curgle tanaris"}},{q="Perché Daryn vuole una foto di Gammerita?",a="Daryn è affascinata dalle mandibole scattanti lungo la spiaggia nelle Entroterre e desidera soprattutto vedere Gammerita. Le sue ricerche la tengono lontana, quindi una foto è la cosa migliore dopo poterla vedere di persona.",al={"mandibola scattante gammerita","perché gammerita","mandibola scattante gigante"}},{q="Cos'è Gammerita?",a="Gammerita è una mandibola scattante gigante che vive sulla spiaggia nelle Entroterre.",al={"chi è gammerita","gammerita"}}},fp="12,176,22.237.0,21.154.0,17.178.1,25.94.0,25.134.0,43.168.0,18.61.0"}
P.entries["quest:2942"] = {n="The Morrow Stone",s="Al Monolito di Equinex, prelevare l’artefatto inizia a prosciugare il Bastone di Equinex. Riporti la Pietra Luccicante e il bastone a Troyas Brezzaluna alla Roccaforte di Piumaluna.",h="Al Monolito di Equinex, prelevare l’artefatto inizia a prosciugare il Bastone di Equinex.",kw={"monolito di equinex","roccaforte di piumaluna","feralas","the morrow stone","pietra luccicante","bastone di equinex","troyas brezzaluna"},sec={{t="Ritorno alla Roccaforte di Piumaluna",b="Il Bastone di Equinex inizia a perdere energia quando prelevi l’artefatto dal monolito. Troyas Brezzaluna alla Roccaforte di Piumaluna attende tue notizie su ciò che hai trovato. Portagli la Pietra Luccicante e il bastone."},{t="Le scoperte di Troyas",b="Dopo la tua partenza, Troyas studia la pietra e la chiama Morrow Stone. Non ne conosce ancora lo scopo, ma crede che tutto ciò che era nascosto dentro il monolito debba avere grande importanza. Continuerà i suoi studi e spera che tu gli resterai accanto."}},faq={{q="Dove inizia tutto questo?",a="Tutto comincia al Monolito di Equinex, quando prelevi l’artefatto.",al={"dove prendo questa missione","dove iniziare the morrow stone","inizio monolito di equinex"}},{q="A chi devo portare la pietra?",a="Porta la pietra a Troyas Brezzaluna alla Roccaforte di Piumaluna, insieme al Bastone di Equinex.",al={"a chi consegnare the morrow stone","dove si trova troyas brezzaluna","chi riceve la pietra luccicante"}},{q="Cosa succede al Bastone di Equinex?",a="L’energia del bastone inizia a svanire appena prelevi l’artefatto dal monolito.",al={"energia del bastone di equinex","cosa succede al bastone","perché il bastone ha perso potere"}},{q="Cosa c'è prima di questo?",a="Segue Il Bastone di Equinex, dove hai caricato il bastone accanto al monolito.",al={"missione precedente","quale missione viene prima di the morrow stone","missione prerequisito"}}},fp="16,179,30.208.0,17.259.1,22.70.0,28.96.0,37.85.0,23.83.0"}
P.entries["quest:2943"] = {n="Return to Troyas",s="Daryn Ventolieve ti manda alla Roccaforte di Piumaluna con il suo libro, Feralas: A History. Troyas Brezzaluna attende con impazienza il tuo ritorno.",h="Daryn Ventolieve ti manda alla Roccaforte di Piumaluna con il suo libro, Feralas: A History.",kw={"darnassus","daryn ventolieve","roccaforte di piumaluna","feralas","feralas: a history","troyas brezzaluna"},sec={{t="Un libro in prestito",b="Dopo il Fotomatic FX, Daryn Ventolieve ti affida il suo libro, Feralas: A History. Ti esorta a sbrigarti, perché Troyas Brezzaluna attende con impazienza il tuo ritorno. Il libro è destinato a Troyas alla Roccaforte di Piumaluna."},{t="Troyas legge",b="Troyas Brezzaluna è contento che tu abbia portato il libro. Lo esamina e ne sfoglia le pagine. Poi esclama che crede di averlo trovato."}},faq={{q="Cosa sto consegnando?",a="Stai consegnando il libro di Daryn Ventolieve, Feralas: A History.",al={"che libro è","cosa devo portare a troyas","libro feralas a history"}},{q="Dov'è Troyas Brezzaluna?",a="Troyas Brezzaluna si trova alla Roccaforte di Piumaluna.",al={"posizione di troyas","dov'è troyas brezzaluna","dove devo andare"}},{q="Chi ti dà il libro?",a="Daryn Ventolieve ti consegna il libro e ti chiede di prendertene cura.",al={"chi assegna la missione","datore di missione","daryn ventolieve"}},{q="Cosa è successo prima?",a="Il Fotomatic FX viene prima.",al={"missione precedente","cosa ho appena fatto","catena prima di questa"}}},fp="16,130,15.222.0,12.134.1,21.62.0,27.47.0,23.65.0,22.39.0"}
P.entries["quest:2944"] = {n="The Super Snapper FX",s="Curgle Criccaleva ha un nuovo dispositivo da farti provare: il Fotomatic FX. Puntalo verso Gammerita, una creatura delle Entroterre, poi porta la foto e il dispositivo a Daryn Ventolieve a Rut'theran. Questa missione segue The Borrower.",h="Curgle Criccaleva ha un nuovo dispositivo da farti provare: il Fotomatic FX.",kw={"curgle criccaleva","daryn ventolieve","gammerita","rut'theran","istantanea","fotomatic fx","entroterre"},sec={{t="Un dispositivo da provare",b="Dopo The Borrower, Curgle Criccaleva ti mette in mano una nuova invenzione: il Fotomatic FX. Puntalo verso ciò che vuoi fotografare, poi premi il pulsante. Curgle te lo dà da provare."},{t="Il soggetto",b="Gammerita, una creatura delle Entroterre, è il soggetto di cui hai parlato a Curgle. Ti augura buona fortuna nel trovarla e si aspetta che Daryn Ventolieve apprezzi l'istantanea. Una volta scattata la foto, portala insieme al dispositivo a Daryn a Rut'theran."}},faq={{q="Chi consegna il Fotomatic FX?",a="Curgle Criccaleva ti dà il Fotomatic FX da provare.",al={"chi consegna il fotomatic","curgle chi assegna la missione","dove ottenere il fotomatic fx"}},{q="Cosa devo fotografare con il Fotomatic FX?",a="Fotografa Gammerita, una creatura delle Entroterre. Curgle ti augura buona fortuna nel trovarla.",al={"posizione di gammerita","dove si trova gammerita","istantanea di gammerita"}},{q="Chi riceve l'istantanea?",a="Daryn Ventolieve a Rut'theran riceve sia l'istantanea sia il dispositivo.",al={"consegna fotomatic fx","dove va la foto","chi è daryn ventolieve"}},{q="Cosa segue nella serie?",a="La catena prosegue con Return to Troyas.",al={"prossima missione dopo il fotomatic","cosa segue il fotomatic fx"}}},fp="20,229,16.183.0,11.261.0,31.56.0,47.90.0,26.80.0,29.42.0"}
P.entries["quest:2945"] = {n="L'anello Sudicio",s="Un nano Ferroscuro a Gnomeregan porta un anello coperto di sudiciume tossico e fango indurito. Lo Sparklematic 5200 nel dormitorio della Clean Zone può ripulirlo e rivelarne le incisioni.",h="Un nano Ferroscuro a Gnomeregan porta un anello coperto di sudiciume tossico e fango indurito.",kw={"clean zone","ferroscuro","dormitorio","gnomeregan","anello incrostato di sporcizia","il ritorno dell'anello","sparklematic 5200"},ang={["profession:Engineering"]="Lo Sparklematic 5200 mostra l'ingegneria gnomica al lavoro, combinando la pulizia con solventi industriali e una confezionatrice automatica per regali.",["race:Dwarf"]="Da nano, puoi immaginare che un nano Ferroscuro infiltrato possa aver sottratto l'anello a Forgiardente o alle vittime gnomiche durante la caduta di Gnomeregan.",["race:Gnome"]="Da gnomo, sai che persino mentre la tua città cadeva, i suoi inventori costruivano macchine per l'igiene che concludono i cicli di lavaggio pericolosi con un allegro campanello e un fiocco."},sec={{t="Una reliquia sotto il fango",b="Gli scontri ricoprono i corridoi di Gnomeregan di melma tossica, olio e ricadute radioattive. I nani Ferroscuro che si infiltrano in città portano ninnoli insozzati da quella sporcizia. Un anello è coperto da una crosta che un normale lavaggio non può rimuovere. Sotto, il metallo potrebbe essere rame, oro o robaccia."},{t="Lo Sparklematic 5200",b="Lo Sparklematic 5200 nel dormitorio della Clean Zone accetta monete, ripulisce gli oggetti sporchi e li restituisce lucidati e avvolti con un fiocco. La pulizia dell'anello rivela un sigillo cittadino e delle iniziali incise all'interno della fascia. Questi segni danno inizio a Return of the Ring, un viaggio verso la restituzione."}},faq={{q="Dove si trova l'Anello Incrostato di Sporcizia?",a="I nani Ferroscuro all'interno di Gnomeregan portano l'anello.",al={"drop anello","dove si trova l'anello sporco","chi lascia cadere l'anello incrostato di sporcizia"}},{q="Come si pulisce l'anello?",a="Porta l'anello allo Sparklematic 5200 nel dormitorio della Clean Zone di Gnomeregan. Paga il costo richiesto in monete e la macchina rimuoverà il fango indurito.",al={"pulire anello","come pulire l'anello incrostato di sporcizia","dove lavare l'anello"}},{q="Cosa succede dopo che l'anello è stato pulito?",a="Lo Sparklematic restituisce l'anello restaurato in una scatola ben confezionata, con le incisioni personali finalmente visibili. Questo dà inizio a Return of the Ring, che ti porterà a cercare il proprietario originale dell'anello.",al={"prossima missione anello sporco","cosa faccio con l'anello pulito","risultato anello sparklematic"}},{q="I personaggi dell'Orda possono completare questa missione?",a="Sì. Gli avventurieri dell'Orda possono pulire l'anello con lo Sparklematic 5200. Le fasi successive mandano i personaggi dell'Orda da un ingegnere a Orgrimmar invece che a Forgiardente.",al={"l'anello sudicio è solo per l'alleanza","anello incrostato dell'orda","l'orda può pulire l'anello"}},{q="Perché l'anello è avvolto in una confezione regalo dopo la pulizia?",a="Lo Sparklematic 5200 rimuove melma e sporcizia, poi confeziona ogni oggetto pulito e ci lega un fiocco decorativo, il tutto con un tocco di estro gnomico.",al={"anello confezionato","perché la scatola regalo dello sparklematic"}},{q="Ci sono più macchine Sparklematic?",a="Diverse unità Sparklematic sono allineate lungo la parete del dormitorio della Clean Zone. Solo quella a sinistra entrando dalle scale, vicino agli gnomi amichevoli, funziona per l'anello.",al={"quale sparklematic","posizioni dello sparklematic 5200"}}},fx={["5abd59ba"]={q="Perché devi pulire l'Anello Incrostato di Sudiciume?",a="Quando strappi l'anello al nano Ferroscuro caduto, è ricoperto da una spessa crosta indurita di melma radioattiva e fango cavernicolo. Riesci a intravedere il debole luccichio di un metallo prezioso e di una gemma sotto lo sporco, ma i residui incrostati lo rendono impossibile da indossare e da esaminare. Pulirlo è l'unico modo per rivelare la sua vera fattura e scoprire se abbia un valore o uno scopo concreto.",al={"perché pulire l'anello","scopo dell'anello incrostato di sudiciume","perché pulire l'anello incrostato di sudiciume"}},c5a1096d={q="Cos'è l'Anello Incrostato di Sudiciume?",a="Sembra un gioiello prezioso portato a Gnomeregan da uno dei nani Ferroscuro invasori. Completamente ricoperto da sporcizia industriale irradiata, il suo pregiato lavoro in metallo e la pietra incastonata sono del tutto nascosti finché non lo fai passare nell'apparato di pulizia automatizzato di Gnomeregan, lo Sparklematic 5200.",al={"cos'è l'anello incrostato di sudiciume","storia dell'anello incrostato di sudiciume","che tipo di anello è"}}},fp="20,180,24.283.0,21.283.1,43.51.0,26.150.0,39.190.0,38.158.0,53.138.0,41.168.0"}
P.entries["quest:2947"] = {n="Il corriere degli anelli",s="A Gnomeregan, un anello d'oro reca un marchio che ti conduce a Forgiardente.",h="A Gnomeregan, un anello d'oro reca un marchio che ti conduce a Forgiardente.",kw={"anello d'oro scintillante","ferroscuro","sigillo forgiardente","guardia mistica","sparklematic","talvash kissel","tdk"},ang={["faction:Alliance"]="Come membro dell'Alleanza, puoi vedere la crescente minaccia che gli agenti di Emperor Thaurissan rappresentano per la dimora montana dell'Alleanza a Forgiardente, attraverso i manufatti recanti il marchio di Forgiardente in possesso dei nani Ferroscuro.",["race:Gnome"]="Da gnomo, ritrovare un'opera perduta a Gnomeregan ti offre un raro scorcio degli artigianati pacifici che il tuo popolo praticava prima del disastro di Thermaplugg."},sec={{t="Un tesoro ricoperto di melma",b="Inserisci un gingillo incrostato di sporcizia nello Sparklematic 5200 di Gnomeregan. La macchina rimuove anni di sporcizia irradiata, rivelando un Anello d'Oro Scintillante lucidato che vibra ancora di potere arcano. All'interno della fascia, tre iniziali, «TdK», sono accanto al sigillo di Forgiardente."},{t="L'artigiano della Guardia Mistica",b="Talvash Kissel, un gioielliere gnomo della Guardia Mistica di Forgiardente, riconosce l'anello come uno dei suoi modelli standard, realizzati prima della caduta di Gnomeregan. Spesso respinge immaginari esattori mentre lavora. Sapere che gli infiltrati Ferroscuro portavano l'anello lo turba e lascia domande su cosa si sia mosso sotto la città perduta."}},faq={{q="Chi ha realizzato l'anello trovato a Gnomeregan?",a="Le iniziali «TdK» appartengono a Talvash Kissel, un gioielliere gnomo della Guardia Mistica di Forgiardente. Prima della caduta di Gnomeregan, aveva una gioielleria lì e creò diversi semplici anelli magici di questo modello.",al={"chi ha realizzato l'anello","iniziali anello tdk","chi è tdk"}},{q="Da dove proviene originariamente l'anello?",a="L'anello proviene dalle profondità di Gnomeregan, dove fu trovato come un gingillo incrostato di sporcizia, portato da invasori ostili come i nani Ferroscuro. Lo Sparklematic 5200 ne ha ripristinato la lucentezza dorata e i marchi del creatore.",al={"dove è stato trovato l'anello","da dove viene l'anello"}},{q="Perché i nani Ferroscuro portavano l'anello di Talvash?",a="Talvash non sa perché gli infiltrati Ferroscuro portassero un suo vecchio lavoro. L'anello potrebbe provenire dalla sua bottega abbandonata o essere stato sottratto a qualcuno che non riuscì a fuggire dall'invasione di Gnomeregan.",al={"perché i ferroscuro ce l'hanno","storia dell'anello dei ferroscuro"}},{q="Perché Talvash Kissel pensa che tu sia il suo padrone di casa?",a="Talvash è nervoso ed eccentrico, e spesso è in ritardo con l'affitto a Forgiardente. Quando degli estranei si avvicinano alla sua bottega con fare aggressivo, pensa che siano ufficiali giudiziari o proprietari venuti a riscuotere i suoi debiti arretrati.",al={"perché talvash è paranoico","affitto talvash"}},{q="Talvash crea gioielli maledetti?",a="Talvash assicura ai potenziali clienti di non creare oggetti maledetti. Le sue nervose smentite tendono a sollevare più domande di quante ne risolvano.",al={"talvash è maledetto","gioielli maledetti forgiardente"}},{q="Posso tenermi l'anello invece di restituirlo?",a="L'anello ha proprietà magiche, ma il suo creatore può esaminarlo e offrirsi di affinarne l'incantamento con ulteriori lavori.",al={"tenere l'anello","dovrei restituire l'anello"}}},fx={["8e194cce"]={q="Perché lo Sparklematic 5200 vuole che l'anello venga restituito?",a="Non lo vuole. Lo Sparklematic 5200 è un dispositivo di pulizia automatizzato, progettato per trattare i rottami incrostati di sudiciume recuperati dalle profondità di Gnomeregan. Pulisce qualunque cosa vi inserisci e sputa fuori l'oggetto ripristinato. Una volta che la macchina eroga l'Anello d'Oro Scintillante lucidato, restituirlo è una tua scelta, presa dopo aver notato il marchio del fabbricante e il sigillo di Forgiardente impressi all'interno della fascia.",al={"perché restituire l'anello","motivazioni dello sparklematic 5200","perché la macchina vuole che l'anello venga restituito"}}},fp="18,80,24.278.0,30.338.1,38.204.0,40.217.0,51.190.0,55.197.0,33.143.0,49.121.0"}
P.entries["quest:2948"] = {n="Miglioramento gnomesco",s="A Forgiardente, Talvash Kissel si offre di migliorare un anello che ha creato a Gnomeregan. Gli servono argento e Agata Muschiata per un delicato reticolo sopra la vecchia fascia.",h="A Forgiardente, Talvash Kissel si offre di migliorare un anello che ha creato a Gnomeregan.",kw={"anello d'oro scintillante","gnome improvement","gnomeregan","forgiardente","agata muschiata","lingotto d'argento","talvash"},ang={["faction:Alliance"]="Come avventuriero dell'Alleanza, puoi aiutare i rifugiati di Gnomeregan grazie ai legami tra la capitale caduta e Forgiardente.",["profession:Mining"]="Come minatore, puoi fornire l'argento e l'Agata Muschiata che servono a Talvash per il suo lavoro di gioielleria.",["race:Gnome"]="Come gnomo, puoi vedere l'orgoglio che Talvash prova per il suo mestiere, anche dopo l'esilio dalla sua terra natale e la perdita dei suoi materiali."},sec={{t="Un artigiano gnomo in esilio",b="Talvash Kissel fuggì da Gnomeregan dopo che l'invasione dei trogg e le radiazioni avevano messo in ginocchio la città. Ora il rifugiato gnomo vive nella Guardia Mistica di Forgiardente. Il gioielliere e inventore ha pochi soldi e scorte esaurite, ma è deciso a dimostrare che il suo talento è ancora intatto, anche in esilio."},{t="Migliorare il vecchio anello",b="Talvash è felice di rivedere il suo semplice modello di anello, ripulito dallo Sparklematic 5200. Eppure considera la vecchia fascia superata. Si offre di migliorarla con un reticolo di argento e Agata Muschiata, mostrando la sua abilità con metalli e gemme."}},faq={{q="Chi è Talvash Kissel?",a="Talvash Kissel è un gioielliere e artigiano gnomo che vive in esilio a Forgiardente. Prima della caduta di Gnomeregan, gestiva lì una piccola gioielleria. Uno dei suoi anelli può essere recuperato e portato da lui nella Guardia Mistica.",al={"talvash","talvash kissel","gioielliere gnomo forgiardente"}},{q="Qual è la storia dell'anello che viene migliorato?",a="Talvash creò l'anello come una delle tante semplici fasce nella sua gioielleria di Gnomeregan. Un nano Ferroscuro ne portò uno tra le rovine, dove gli avventurieri possono recuperarlo e pulirlo nello Sparklematic 5200. Talvash si offre di aggiungere un reticolo di argento e Agata Muschiata per migliorarlo.",al={"da dove viene l'anello","origine anello incrostato di sporcizia"}},{q="Perché Talvash chiede al giocatore di fornire i reagenti?",a="Talvash ha finito i materiali e ha pochi soldi dopo essere fuggito da Gnomeregan. Chiede argento e Agata Muschiata per realizzare il reticolo.",al={"perché servono argento e agata muschiata","perché talvash non ha materiali"}},{q="Dove inizia questa serie di missioni?",a="La pista inizia a Gnomeregan, dove si può trovare un anello coperto di sporcizia sui nemici. Puliscilo nello Sparklematic 5200, poi segui le iniziali «TdK» fino a Talvash a Forgiardente.",al={"come iniziare gnome improvement","inizio serie missioni anello"}},{q="Talvash è amareggiato per la sua situazione a Forgiardente?",a="Talvash si lamenta delle ingiuste difficoltà economiche, ma conserva il buonumore e l'orgoglio professionale. Crede che, una volta risollevate le sue sorti, sarà rinomato in tutta Azeroth per la creazione dei migliori gingilli.",al={"storia di talvash","personalità di talvash"}},{q="L'Orda può accedere a questa missione?",a="No. Gli avventurieri dell'Orda che puliscono oggetti coperti di sporcizia a Gnomeregan vengono mandati da Nogg a Orgrimmar invece che da Talvash a Forgiardente.",al={"l'orda può fare il miglioramento gnomesco","potenziamento dell'anello per l'orda"}}},fx={["2e3e2066"]={q="A cosa serve il Lingotto d'Argento?",a="Talvash ha bisogno del metallo raffinato per trasformare il tuo anello originale in un gioiello più elaborato. Usa il lingotto d'argento per forgiare un intricato intreccio direttamente sulla fascia, donando al semplice design molta più eleganza e robustezza rispetto ai suoi primi lavori artigianali.",al={"perché il lingotto d'argento","lingotto d'argento per talvash","per cosa gli serve l'argento"}},a02fa77a={q="A cosa serve l'Agata Muschiata?",a="L'agata muschiata è il fulcro decorativo dell'anello migliorato. Incastonando la gemma verde lucidata nel nuovo intreccio d'argento, Talvash intende aggiungere un tocco di stile e dimostrare la sua vera abilità artigianale, trasformando un gingillo rudimentale in un'opera molto più impressionante.",al={"perché l'agata muschiata","agata muschiata per talvash","per cosa gli serve l'agata"}}},fp="17,153,26.270.0,22.232.0,26.213.0,51.266.0,56.136.0,34.176.0,51.197.0,41.132.0"}
P.entries["quest:2949"] = {n="Il corriere degli anelli",s="Un anello di Gnomeregan reca il sigillo di Orgrimmar e le lettere NOG. La sua pista conduce a Nogg, un ingegnere goblin con una teoria sulle rovine.",h="Un anello di Gnomeregan reca il sigillo di Orgrimmar e le lettere NOG.",kw={"anello d'oro scintillante","ferroscuro","gnomeregan","nogg","orgrimmar","il ritorno dell'anello","sparklematic 5200","valle dell'onore"},ang={["faction:Horde"]="Da membro dell'Orda, raramente trovi i suoi simboli nel cuore del principale centro tecnologico dei Regni Orientali. L'anello ti conduce da Khaz Modan alla Valle dell'Onore.",["profession:Engineering"]="Da ingegnere, sai che gli inventori goblin di Orgrimmar si misurano con le invenzioni gnomiche. Nogg non vede l'ora di esaminare qualsiasi cosa recuperata dalla loro meraviglia tecnologica in rovina."},sec={{t="Una scoperta curiosa",b="Ripulisci un anello di Gnomeregan nello Sparklematic 5200. La macchina rimuove la sporcizia e rivela il sigillo ufficiale di Orgrimmar, un'ondata di potere magico e le lettere NOG, parzialmente leggibili. Gnomeregan si trova nelle profondità di Khaz Modan, una città dell'Alleanza lontana dalla capitale dell'Orda. L'anello potrebbe essere stato fabbricato a Kalimdor o portato lì durante una spedizione sfortunata, ma il sigillo indica Orgrimmar."},{t="Rivalità gnomiche e trame Ferroscuro",b="Porti l'anello da Nogg, nella Valle dell'Onore di Orgrimmar. L'ingegnere goblin dice che non è suo, anche se la sua origine solleva delle domande. Da tempo i goblin considerano gli inventori gnomi rivali eccentrici. Nogg sospetta che gli gnomi abbiano rubato e modificato i progetti dei golem Ferroscuro. Poiché i nani Ferroscuro tenevano l'anello a Gnomeregan, pensa che possano cercare vendetta. È una pista che vale la pena seguire."}},faq={{q="Perché un anello trovato a Gnomeregan reca il sigillo di Orgrimmar?",a="Nessuno sa esattamente come l'anello sia arrivato a Gnomeregan. I nani Ferroscuro lo portarono nel profondo delle rovine, dove fu recuperato. Il sigillo di Orgrimmar lo collega ai metalmeccanici e agli artigiani dell'Orda a Durotar.",al={"perché sigillo orgrimmar","anello dell'orda a gnomeregan","come è arrivato lì l'anello"}},{q="Chi è Nogg?",a="Nogg è un ingegnere goblin nella Valle dell'Onore di Orgrimmar. Si occupa di forniture e macchinari d'ingegneria, e il suo nome corrisponde alle lettere consumate sull'anello ripulito.",al={"chi è nogg","nogg orgrimmar","lettere nog anello"}},{q="Cos'è lo Sparklematic 5200?",a="Lo Sparklematic 5200 è un sistema di lavaggio industriale automatico nella Clean Zone di Gnomeregan. Rimuove spessi strati di fanghiglia tossica e contaminazione radioattiva dagli oggetti recuperati dai corridoi in rovina.",al={"cos'è lo sparklematic","sparklematic 5200","cleanomatic"}},{q="Nogg è il proprietario dell'anello?",a="No. Nogg esamina l'anello ripulito e dice che non è suo. Ne riconosce la fattura e usa la sua abilità d'ingegnere per modificarlo ulteriormente per te.",al={"è l'anello di nogg","nogg ha perso il suo anello","di chi è l'anello"}},{q="Cosa pensa Nogg che sia successo a Gnomeregan?",a="Nogg sospetta che gli gnomi abbiano rubato progetti avanzati di golem al clan Ferroscuro. Pensa che i Ferroscuro vogliano vendicarsi e considera questa pista degna d'indagine.",al={"teoria nogg gnomeregan","cosa è successo a gnomeregan","perché i nani ferroscuro"}},{q="Posso tenere l'anello invece di restituirlo a Nogg?",a="Puoi indossare subito l'anello o portarlo a Orgrimmar. Consegnarlo a Nogg permette all'ingegnere goblin di esaminarne la fattura e offrirti ulteriori miglioramenti.",al={"tenere anello d'oro scintillante","devo restituire l'anello","devo darlo a nogg"}}},fx={["9392e9ce"]={q="Perché lo Sparklematic 5200 vuole che l'anello venga restituito?",a="Lo Sparklematic 5200 non ha volontà né motivazioni proprie: è semplicemente un apparato di pulizia automatizzato all'interno di Gnomeregan, progettato per strofinare via lo sporco dagli oggetti recuperati e sputare fuori quel che ne esce. Una volta pulito il tuo anello incrostato di sudiciume e averlo erogato in una scatola avvolta, la sua funzione è terminata. La decisione di rintracciare le iniziali incise all'interno della fascia nasce solo dalla tua curiosità, dopo aver scoperto il sigillo di Orgrimmar e le lettere parziali incise al suo interno.",al={"motivazioni dello sparklematic","perché restituire l'anello allo sparklematic","scopo dello sparklematic 5200"}}},fp="18,140,19.394.0,37.391.1,63.203.0,12.163.0,30.193.0,23.151.1,44.169.0,52.157.0"}
P.entries["quest:295"] = {n="Ormer's Revenge",s="Tra le rovine dello Scavo di Whelgar, Ormer Trecciaferro ti manda a caccia dei raptor che hanno scacciato la sua spedizione. Hai già decimato i più giovani, e ora vuole che uccidi gli Artigliofalce Maculati e i Masticatori.",h="Tra le rovine dello Scavo di Whelgar, Ormer Trecciaferro ti manda a caccia dei raptor che hanno scacciato la...",kw={"nano","scavo","lega degli esploratori","masticatore maculato","artigliofalce maculato","ormer trecciaferro","raptor","paludi grigie","scavo whelgar"},ang={["class:Hunter"]="Da cacciatore, affronti i raptor maculati delle Paludi Grigie, predatori territoriali che cacciano in branco e rendono letale seguire le tracce nelle trincee strette e fangose.",["faction:Alliance"]="Come membro dell'Alleanza, contribuisci a riprendere lo Scavo di Whelgar e a garantire operazioni sicure lungo la strada orientale tra le Paludi Grigie e gli Altopiani d'Arathi.",["race:Dwarf"]="Da nano, condividi l'orgoglio feroce della Lega degli Esploratori e il suo rifiuto di lasciare che le bestie selvatiche fermino la ricerca del tuo passato ancestrale."},sec={{t="Intensificare la Caccia",b="Ormer Trecciaferro ti manda a caccia dei raptor adulti nella zona inferiore dello scavo. Hai già decimato i giovani che avevano invaso l'accampamento superiore, ma gli Artigliofalce Maculati e i Masticatori minacciano ancora ogni speranza di riprendere gli scavi. Si avventano sui prospettori nani e lasciano le trincee disseminate di casse sfondate e picconi abbandonati."},{t="Sangue nelle Trincee",b="I raptor hanno fatto il nido nelle fosse di scavo. Dal crinale sopra lo scavo, Ormer ti guida nel fango per colpire le bestie adulte. Il Prospettore Whelgar e la sua squadra sperano di recuperare antiche reliquie, ma Ormer è consumato dalla vendetta. Esige un pesante tributo di Artigliofalce Maculati e Masticatori morti prima di occuparsi del terrore supremo del sito."}},faq={{q="Perché Ormer è così arrabbiato con questi raptor?",a="I raptor maculati sciamarono sullo Scavo di Whelgar, scacciarono la squadra nanica e massacrarono chi non riuscì a fuggire. Ormer Trecciaferro fu costretto ad andarsene e ne serba rancore. Non permetterà alle bestie di controllare lo scavo senza far loro pagare un prezzo in sangue.",al={"perché ormer è arrabbiato","motivo vendetta ormer","perché uccidere i raptor nelle paludi grigie"}},{q="Dove si trovano gli Artigliofalce Maculati e i Masticatori?",a="Gli Artigliofalce Maculati e i Masticatori si aggirano per le trincee inferiori e le opere di terra circostanti dello Scavo di Whelgar, a est del Porto di Menethil e a sud-ovest di Dun Modr, nelle Paludi Grigie.",al={"posizione artigliofalce maculato","posizione masticatore maculato","dove trovare raptor ormer"}},{q="Chi è Ormer Trecciaferro?",a="Ormer Trecciaferro è un nano della Lega degli Esploratori di stanza allo Scavo di Whelgar. Dopo che i raptor si sono impadroniti dello scavo, ha fatto dello sterminio del branco che infesta il sito la sua missione personale.",al={"chi è ormer","storia ormer trecciaferro"}},{q="Cosa succede dopo aver abbattuto questi raptor?",a="Dopo che avrai eliminato gli Artigliofalce Maculati e i Masticatori, Ormer rivolgerà la sua attenzione a Sarltooth, il grande raptor che ritiene sia a capo del branco locale. Ti ordinerà di porre fine all'infestazione di raptor.",al={"cosa succede dopo ormer's revenge","sequel ormer's revenge","prossima missione dopo artigliofalce"}},{q="Questa missione è collegata ad altri compiti nel sito di scavo?",a="Sì. Mentre dai la caccia ai raptor nella zona inferiore dello scavo per conto di Ormer, puoi anche aiutare il Prospettore Whelgar e la sua squadra con \"Uncovering the Past\", raccogliendo i frammenti di artefatti di terra sparsi nelle stesse trincee.",al={"missioni scavo whelgar","collegamento uncovering the past"}},{q="Perché i nani scavavano qui in origine?",a="La Lega degli Esploratori di Forgiardente fondò lo Scavo di Whelgar per cercare reliquie dei titani e scoprire la storia antica della razza nanica. La fauna aggressiva fermò i lavori quando invase lo scavo.",al={"perché scavare nelle paludi grigie","scopo scavo whelgar"}}},fx={["2ccf3294"]={q="Cosa sono gli Artigli Falcianti Maculati e i Morsilame Maculati?",a="Queste feroci razze di raptor si aggirano nei livelli inferiori del sito di scavo di Whelgar. Note per la sete di sangue e gli artigli affilati come rasoi, hanno sopraffatto gli scavatori nani, costringendoli ad abbandonare le fosse di lavoro. Ormer ora ti incarica di dare la caccia agli esemplari più letali, per spezzare il loro dominio sulle rovine.",al={"cosa sono gli artigli falcianti e i morsilame","artigli falcianti maculati","morsilame maculati","raptor delle paludi"}},f1520877={q="Perché Ormer ti chiede di dare la caccia ai raptor invece di occuparsene personalmente?",a="Ormer e i prospettori sopravvissuti sono stati costretti a rifugiarsi sulla cresta sopra il sito di scavo. Con la squadra di scavo dispersa o uccisa, non hanno abbastanza uomini per lanciare da soli un contrattacco deciso e hanno bisogno di avventurieri capaci, disposti a calarsi nelle fosse infestate al posto loro.",al={"perché ormer ha bisogno di aiuto","perché ormer non uccide i raptor","perché proprio io per ormer"}}},fp="15,217,19.338.0,21.341.0,39.256.0,54.188.0,23.214.0,41.196.1,62.208.0,53.217.0"}
P.entries["quest:2950"] = {n="Il nuovo anello di Nogg",s="A Orgrimmar, Nogg vuole migliorare un anello recuperato a Gnomeregan. Gli servono materiali rari e notizie sui nani Ferroscuro, per dimostrare che l'artigianato goblin supera il design gnomico.",h="A Orgrimmar, Nogg vuole migliorare un anello recuperato a Gnomeregan.",kw={"anello d'oro scintillante","ferroscuro","gnomeregan","goblin engineering","agata muschiata","nogg","orgrimmar","lingotto d'argento"},ang={["faction:Horde"]="Come membro dell'Orda, puoi portare la tecnologia da luoghi legati all'Alleanza, come Gnomeregan, agli inventori di Orgrimmar. Così l'Orda può conoscere le capacità dei suoi nemici.",["profession:Engineering"]="Come ingegnere, assisti alla rivalità tra l'ingegno goblin e i congegni gnomici. I goblin modificano con audacia i dispositivi esistenti per sfruttarli al massimo.",["profession:Mining"]="Come minatore, puoi aiutare Nogg a procurarsi un Lingotto d'Argento raffinato e un'Agata Muschiata, ottenuti con l'attività mineraria e il taglio delle gemme."},sec={{t="Superiorità Goblin",b="Porti a Nogg, nella sua officina della Valle dell'Onore, un anello d'oro ripulito recuperato a Gnomeregan. L'ingegnere goblin ne studia la semplice fattura gnomica e ti propone un accordo. Se gli porti materie prime e una piccola somma, incornicerà la fascia con argento e Agata Muschiata. Il reticolo dovrebbe rafforzare la magia al suo interno."},{t="Un Angolo Ferroscuro",b="L'offerta di Nogg va oltre il commercio. Ha saputo che dei nani Ferroscuro si trovano nella città degli gnomi assediata. La loro presenza potrebbe spiegare gli improvvisi progressi degli gnomi nella meccanica, un'arte che i goblin rivendicano come propria. Le informazioni che gli fornisci ti fanno ottenere un anello migliorato e il riluttante rispetto di Nogg."}},faq={{q="Chi è Nogg?",a="Nogg è un ingegnere goblin che vive nella Valle dell'Onore, a Orgrimmar. Lavora con altri inventori nel Varcolargo e nella Valle dell'Onore, esaminando curiosi artefatti meccanici e progetti riportati da spedizioni pericolose.",al={"chi è nogg","nogg orgrimmar","npc nogg"}},{q="Quali materiali sono necessari per riforgiare l'anello?",a="Nogg ti chiede l'Anello d'Oro Scintillante originale, un Lingotto d'Argento, un'Agata Muschiata e trenta monete d'argento per coprire il lavoro e le spese dell'officina.",al={"materiali anello","materiali nogg","cosa serve a nogg"}},{q="Perché Nogg è interessato a Gnomeregan?",a="Gnomeregan ha un grande valore tecnologico. I goblin competono accanitamente con gli gnomi nei campi tecnici, e Nogg si chiede se i nani Ferroscuro siano coinvolti nelle anomalie tecnologiche all'interno della città tecnologica caduta.",al={"perché nogg si interessa a gnomeregan","interesse goblin per gnomeregan"}},{q="Cosa fa effettivamente Nogg all'anello?",a="Nogg costruisce un reticolo d'argento e Agata Muschiata attorno alla fascia d'oro. La struttura convoglia e stabilizza gli incanti dell'anello, rendendolo più potente del progetto gnomico originale.",al={"lore potenziamento anello","cosa cambia sull'anello"}},{q="Dove inizia questa catena di missioni?",a="La catena di eventi comincia nel cuore di Gnomeregan. Trovi un Grime-Encrusted Ring addosso a un nano Ferroscuro, poi lo pulisci con la macchina Sparklematic 5200.",al={"inizio catena","come iniziare la missione di nogg","inizio catena missioni anello"}},{q="Perché Nogg sospetta dei nani Ferroscuro?",a="Gli ingegneri goblin diffidano delle innovazioni gnomiche. Nogg sospetta che dietro ogni improvviso progresso nella meccanica degli gnomi ci sia una manomissione esterna, soprattutto da parte dell'astuto clan Ferroscuro.",al={"perché i ferroscuro","legame con i nani ferroscuro"}}},fx={e11b7fb8={q="Perché Nogg vuole riforgiare l'anello?",a="Nogg non rivendica la proprietà dell'anello, ma è sinceramente grato per le informazioni che gli hai riportato sui nani Ferroscuro a Gnomeregan. Da ingegnere goblin, inoltre, non riesce a resistere alla tentazione di sfoggiare la propria abilità: vuole dimostrare di poter superare il rozzo lavoro degli inventori gnomi, potenziandone il progetto con un reticolo magico molto più potente.",al={"perché nogg si offre di rifare l'anello","perché rifare l'anello","motivo di nogg per rifare l'anello"}},["63dec8fa"]={q="A cosa serve il Lingotto d'Argento in Rifare l'anello di Nogg?",a="Nogg usa il Lingotto d'Argento per forgiare attorno all'anello un reticolo strutturale raffinato. Questa delicata struttura metallica funge da supporto fisico, necessario per fissare ulteriori incantamenti magici senza alterare il nucleo esistente dell'anello.",al={"a cosa serve il lingotto d'argento","lingotto d'argento nogg","perché il lingotto d'argento per rifare l'anello"}},c138af81={q="A cosa serve l'Agata Muschiata in Rifare l'anello di Nogg?",a="L'Agata Muschiata viene incorporata nel nuovo reticolo d'argento che Nogg crea per il tuo anello. Le sue proprietà minerali intrinseche aiutano a incanalare e amplificare l'energia magica latente contenuta nell'oggetto, trasformando un semplice gingillo gnomesco in un artefatto molto più potente.",al={"a cosa serve l'agata muschiata","agata muschiata nogg","perché l'agata muschiata per rifare l'anello"}}},fp="16,182,18.310.0,15.290.1,12.216.0,46.144.0,37.215.0,39.182.0,34.140.0,40.171.0"}
P.entries["quest:2951"] = {n="Lavatutto 5200!",s="A Gnomeregan, lo Sparklematic 5200! continua a pulire preziosi recuperati per tre monete d'argento. L'ingegno gnomico lo mantiene in funzione nel caos della città in rovina.",h="A Gnomeregan, lo Sparklematic 5200!",kw={"pulitrice","gnomo","gnomeregan","sudicio","macchina","recupero","sparklematic","sparklematic 5200","trogg"},ang={["faction:Alliance"]="Come membro dell'Alleanza, puoi usare lo Sparklematic per pulire reliquie recuperate a Gnomeregan prima di riportarle a Forgiardente.",["profession:Engineering"]="Come ingegnere, puoi apprezzare il motore e il meccanismo di selezione che puliscono e smistano detriti sconosciuti senza incepparsi o esplodere.",["race:Gnome"]="Come gnomo, puoi vedere la resilienza del tuo popolo in una macchina per la pulizia che continua a funzionare nonostante la devastazione della sua patria."},sec={{t="Un faro nello sporco",b="Un gruppo di gnomi sopravvissuti mantiene un perimetro sicuro vicino allo Sparklematic 5200! a Gnomeregan. La macchina rimuove dai preziosi recuperati lo sporco più ostinato del sottosuolo. I trogg e altre creature sotterranee martellano le paratie, ma resta pronta per ciò che porti."},{t="Operazione frenetica",b="Metti una reliquia incrostata di sporcizia e tre monete d'argento nello Sparklematic, e la pulizia ha inizio. La macchina di ferro geme e vibra, sussultando mentre rimuove fanghiglia tossica, grasso irradiato e polvere di roccia. Pochi istanti dopo, espelle ciò che si nascondeva sotto la melma, dai minerali preziosi ai componenti meccanici."}},faq={{q="Che cos'è lo Sparklematic 5200?",a="Lo Sparklematic 5200! è una macchina gnomica automatizzata per la pulizia, situata in un'area protetta di Gnomeregan. Rimuove grasso radioattivo, fanghiglia e sporco dagli oggetti incrostati recuperati nella città caduta.",al={"a cosa serve lo sparklematic 5200","macchina sparklematic","macchina pulitrice gnomeregan"}},{q="Cosa richiede la macchina per funzionare?",a="Lo Sparklematic ha bisogno di un Oggetto Sudicio, che si trova tra i mostri e i detriti di Gnomeregan, e di tre monete d'argento da inserire nella fessura.",al={"come usare lo sparklematic","costo dello sparklematic","cosa inserire nello sparklematic"}},{q="Perché c'è una macchina operativa nel bel mezzo di una zona di guerra?",a="Dopo che l'invasione dei trogg e le esalazioni tossiche devastarono Gnomeregan, gli gnomi sopravvissuti si ritirarono in officine fortificate. Lì, macchine come lo Sparklematic rimasero intatte e alimentate, preservando la comodità degli strumenti automatizzati gnomici.",al={"perché lo sparklematic è qui","chi ha messo lo sparklematic a gnomeregan"}},{q="Cosa esce dopo aver pulito un oggetto sudicio?",a="Lo Sparklematic restituisce pulito l'oggetto recuperato, rivelando ciò che si nascondeva sotto la melma. Potrebbe trattarsi di materiali commerciali, pietre da lavorazione, gemme o pezzi di ricambio per l'ingegneria.",al={"cosa si ottiene dallo sparklematic","bottino dello sparklematic","ricompense oggetto sudicio"}},{q="Posso usare lo Sparklematic 5200 più di una volta?",a="Sì. Puoi usare lo Sparklematic più volte, portando altri oggetti incrostati di sporcizia e tre monete d'argento per ogni pulizia.",al={"si può usare ancora lo sparklematic","posso pulire più oggetti sudici","altro sullo sparklematic"}},{q="Perché la macchina trema così violentemente durante la pulizia?",a="Lo sporco incrostato di Gnomeregan è denso, tossico e indurito. L'agitazione e le spazzole interne dello Sparklematic lo staccano, facendo sussultare e gemere il telaio.",al={"sparklematic che trema","lo sparklematic è rotto"}}},fx={["3b5f4e4c"]={q="Perché lo Sparklematic 5200 vuole che venga fatto questo?",a="Lo Sparklematic 5200 non è un essere senziente, ma un elettrodomestico gnomesco automatizzato, costruito per un unico scopo commerciale: pulire oggetti di valore sporchi e incrostati per i clienti paganti. Come recita la targhetta d'ottone, è progettato per ripulire, in cambio di tre monete d'argento, reliquie rovinate e coperte di melma recuperate dalle sale contaminate di Gnomeregan. Non ha altri obiettivi personali oltre a eseguire il proprio programma, quando riceve il carburante e le monete giuste.",al={"perché lo sparklematic vuole gli oggetti","scopo dello sparklematic 5200","perché inserire oggetti nello sparklematic"}},["757f94ef"]={q="A cosa serve un Oggetto Sudicio?",a="Un Oggetto Sudicio è un pezzo irriconoscibile di tecnologia gnomesca recuperata, minerale o gingillo personale, ricoperto dai fanghi tossici e dalle radiazioni che invadono Gnomeregan. In questo stato contaminato, l'oggetto è del tutto inutile e la sua vera natura resta nascosta. Inserirlo nello Sparklematic 5200 elimina la melma radioattiva e le incrostazioni corrosive, rivelando eventuali equipaggiamenti preziosi, gemme o rottami metallici nascosti al suo interno.",al={"cos'è un oggetto sudicio","a cosa serve l'oggetto sudicio","perché tenere l'oggetto sudicio"}}},fp="22,160,21.270.0,18.308.0,30.198.0,41.141.0,64.236.0,53.167.0,47.125.0,56.162.0"}
P.entries["quest:2952"] = {n="Lavatutto 5200!",s="A Gnomeregan, il Lavatutto 5200! riceve oggetti recuperati sporchi e li pulisce. I suoi cicli rimuovono le incrostazioni tossiche, poi avvolgono ciò che resta in una confezione regalo.",h="A Gnomeregan, il Lavatutto 5200!",kw={"pulizia","macchinario","decontaminazione","gnomeregan","sporcizia","macchina","lavatutto"},ang={["profession:Engineering"]="Se sei un ingegnere, puoi studiare come il Lavatutto pulisce automaticamente le particelle e confeziona gli oggetti in fretta, anche in presenza di forti radiazioni.",["race:Gnome"]="Se sei uno gnomo, il Lavatutto ti ricorda casa, prima della caduta. Persino un'unità di pulizia industriale suonava allegra e confezionava il proprio lavoro come un regalo di compleanno."},sec={{t="Pulizia Automatizzata",b="Inserisci rifiuti tossici e contaminati nel Lavatutto 5200!: i suoi cicli rimuovono incrostazioni e residui caustici. Dopo averlo caricato e pagato, la macchina sferraglia durante la sua routine. Segue un allegro ding, poi un regalo con fiocco contiene ciò che resta."},{t="Tesori nel Fango",b="Quando i trogg conquistarono Gnomeregan, le radiazioni e il fango industriale seppellirono effetti personali e rottami tecnologici. Inserisci Oggetti Sudici nella macchina: potresti recuperare gemme, minerali grezzi e altri oggetti preziosi inghiottiti quando la città fu ventilata."}},faq={{q="A cosa serve il Lavatutto 5200?",a="Il Lavatutto 5200! pulisce gli oggetti all'interno di Gnomeregan. Inserisci un Oggetto Sudicio e paga una moneta: la macchina rimuoverà melma, sporcizia e liquami radioattivi. Ciò che resta ti verrà restituito in una piccola confezione regalo.",al={"cos'è il lavatutto 5200","come funziona il lavatutto","funzione del lavatutto"}},{q="Dove si trova il Lavatutto 5200?",a="Il Lavatutto 5200! si trova nei corridoi della caduta Gnomeregan, vicino alla Clean Zone dove un tempo operavano i superstiti e i sistemi automatici di decontaminazione.",al={"posizione del lavatutto","dov'è il macchinario di pulizia","trova il lavatutto"}},{q="Perché il macchinario impacchetta gli oggetti con un fiocco?",a="L'estro gnomico ha dato al Lavatutto 5200! la sua finitura con fiocco. Dopo aver ripulito un oggetto dalle scorie e dalle incrostazioni tossiche, lo confeziona come un regalo ben impacchettato.",al={"perché il pacchetto regalo","regalo impacchettato del lavatutto","impacchettato con un fiocco"}},{q="Gli avventurieri dell'Orda possono usare il Lavatutto 5200?",a="Sì. Il Lavatutto 5200! è automatico e non bada all'appartenenza a una fazione. Inserisci monete e oggetti sporchi: la macchina avvierà il suo ciclo.",al={"orda lavatutto","l'orda può pulire la sporcizia","il lavatutto è neutrale"}},{q="Posso usare il Lavatutto più volte?",a="Sì. Dopo il primo utilizzo, il Lavatutto 5200! può pulire di nuovo gli oggetti. Porta gli Oggetti Sudici trovati per tutto il dungeon e sottoponili a un altro ciclo.",al={"il lavatutto è ripetibile","more sparklematic action","farmare oggetti sudici"}},{q="Cosa succede dopo questa missione?",a="Dopo la prima pulizia, puoi usare il ciclo ripetibile More Sparklematic Action per ripulire altri Oggetti Sudici che hai con te.",al={"missione successiva al lavatutto","cosa viene dopo il lavatutto 5200"}}},fx={["1a7da75f"]={q="Perché lo Sparklematic 5200 vuole gli oggetti incrostati di sporcizia?",a="Lo Sparklematic 5200 non ha ambizioni personali: è una meraviglia dell'ingegneria gnomesca, progettata per pulire e ripristinare i beni recuperati. Costruito prima della caduta di Gnomeregan, ha la funzione programmata di rimuovere spessi strati di melma radioattiva e detriti, confezionando ciò che resta in un pacchetto ordinato per chi lo usa.",al={"perché lo sparklematic vuole questo","scopo dello sparklematic 5200","perché pulire gli oggetti sudici"}}},fp="22,164,19.252.0,22.257.0,35.204.0,39.157.0,41.174.0,48.134.0,42.171.0,30.140.0"}
P.entries["quest:2953"] = {n="Altri pacchi incartati",s="A Gnomeregan, lo Sparklematic 5200 pulisce ancora ciò che si può salvare. Lasciato indietro durante l'evacuazione della città, rimuove fango e liquame radioattivo dalle curiosità in cambio di una piccola somma d'argento.",h="A Gnomeregan, lo Sparklematic 5200 pulisce ancora ciò che si può salvare.",kw={"automazione","macchina pulitrice","pulizia","gnomeregan","incrostato di sporcizia","sparklematic"},ang={["profession:Engineering"]="Come ingegnere, puoi studiare da vicino i robusti cicli di pulizia con solventi gnomici e i meccanismi attivati dalle monete.",["race:Gnome"]="Come gnomo, puoi ammirare la resistenza meccanica del tuo popolo nello Sparklematic, ancora funzionante tra le rovine tossiche della tua patria."},sec={{t="Ripristino Automatizzato",b="Prima dell'invasione dei trogg e delle radiazioni che ne seguirono, gli ingegneri di Gnomeregan installarono dispositivi automatizzati in tutta la città. Rifiuti tossici e automi ostili riempiono ora i suoi corridoi. Eppure lo Sparklematic 5200 segue alla lettera la sua programmazione: per avviarlo servono tre monete d'argento e un artefatto incrostato di sporcizia."},{t="Meraviglie dal Fango",b="Lo Sparklematic sussulta mentre spruzza sul cimelio inserito potenti solventi gnomici e lo strofina fino a pulirlo. Un allegro rintocco segnala la fine del ciclo e la macchina dispensa una scatola ben confezionata. Dentro c'è tutto ciò che è rimasto recuperabile sotto il viscido corrosivo dei trogg e la lordura tossica."}},faq={{q="Che cos'è lo Sparklematic 5200?",a="Lo Sparklematic 5200 è un dispositivo di pulizia automatizzato degli gnomi, situato a Gnomeregan. Rimuove liquame caustico, sporcizia e residui radioattivi dagli oggetti recuperati, lasciando materiali che si possono identificare.",al={"sparklematic 5200","cosa fa la macchina","pulitore di gnomeregan"}},{q="Perché la macchina richiede delle monete?",a="Per avviare un ciclo di pulizia, lo Sparklematic richiede tre monete d'argento. Non viene spiegato il motivo del costo.",al={"perché pagare argento","costo sparklematic"}},{q="Che tipo di oggetti si possono inserire?",a="La macchina pulisce gli oggetti incrostati di sporcizia, compresi i cimeli recuperati dai trogg caduti, dalle sentinelle corrotte e dagli orrori irradiati nei tunnel di Gnomeregan.",al={"oggetto sudicio","quali oggetti posso pulire"}},{q="Lo Sparklematic è al sicuro dalle radiazioni?",a="I tunnel esterni di Gnomeregan sono pieni di rifiuti radioattivi, ma lo Sparklematic 5200 funziona ancora. I suoi speciali detergenti gnomici rimuovono i residui pericolosi dagli oggetti inseriti.",al={"sparklematic irradiato","contaminazione sparklematic"}},{q="Entrambe le fazioni possono usare lo Sparklematic 5200?",a="Sì. Lo Sparklematic 5200 è un impianto meccanico automatizzato che accetta pagamenti e oggetti incrostati di sporcizia dai visitatori di entrambe le fazioni.",al={"sparklematic orda","chi può usarlo"}},{q="Chi ha progettato lo Sparklematic?",a="Il creatore dello Sparklematic non è stato nominato. La macchina per la pulizia degli gnomi funziona ancora a Gnomeregan.",al={"creatore sparklematic","chi ha costruito sparklematic"}}},fx={["9d072b2b"]={q="Perché bisogna mettere in funzione lo Sparklematic 5200?",a="Lo Sparklematic 5200 è un elettrodomestico gnomesco automatizzato, progettato per un unico scopo: rimuovere il fango sotterraneo più tenace e le incrostazioni industriali dagli equipaggiamenti contaminati. Essendo una macchina, non nutre grandi ambizioni né nasconde secondi fini; resta semplicemente in attesa della tariffa giusta e degli oggetti sudici da inserire, per attivare i cicli di pulizia e distribuire gli oggetti ripristinati.",al={"perché mettere in funzione lo sparklematic","motivo dello sparklematic","perché usare lo sparklematic 5200"}}},fp="24,191,21.313.0,21.282.0,30.201.0,34.103.0,40.158.0,40.180.0,44.149.0,30.100.0"}
P.entries["quest:2954"] = {n="The Stone Watcher",s="Al Piedistallo di Uldum, lo Stone Watcher custodisce l'ingresso al complesso. Hai trasportato i dischi di platino attraverso Tanaris e ora ti chiede di apprendere la sua storia prima di proseguire.",h="Al Piedistallo di Uldum, lo Stone Watcher custodisce l'ingresso al complesso.",kw={"creatori","piastre di uldum","dischi di platino","the stone watcher di norgannon","tanaris","uldaman","uldum","piedistallo di uldum"},sec={{t="Un Guardiano presso il Piedistallo",b="Al Piedistallo di Uldum, lo Stone Watcher sbarra l'ingresso al complesso di Uldum. Hai portato i dischi di platino attraverso Tanaris. Il guardiano dice che puoi entrare solo se il tuo set include le Piastre di Uldum. Apprendi la storia del Watcher, poi usa il piedistallo."},{t="Cosa spiega il Watcher",b="Lo Stone Watcher controlla l'accesso al complesso di Uldum per conto dei Creators. Ammette solo chi possiede i dischi di sequenziamento corretti. Le Piastre di Uldum sono state create dai Creators e registrano il loro lavoro a Uldum. Sono quasi grandi quanto i tuoi dischi, ma i loro simboli riguardano Uldum anziché Uldaman.\n\nUldum è una struttura di ricerca dove i Creators lavorano per migliorare la biosfera di Azeroth. Solo chi possiede le Piastre può conoscere i dettagli di quel lavoro. Il Watcher promette di restituirti i dischi quando avrai avuto accesso al piedistallo. Ti permetterà di entrare nel complesso quando le Piastre faranno parte del tuo set."},{t="Altro dal Watcher",b="Lo Stone Watcher dice che i Creators controllano la distribuzione dei dischi per ogni complesso di questo mondo. Azeroth è stata riprogrammata per una visita. I Creators usano le visite per ristabilire il controllo sui mondi seminati quando forze esterne o interne alterano l'equilibrio delle dinamiche della loro matrice. Il Watcher avverte che non bisogna prendere alla leggera una visita."}},faq={{q="Chi è il The Stone Watcher di Norgannon?",a="Al Piedistallo di Uldum, a Tanaris, lo Stone Watcher custodisce l'ingresso al complesso di Uldum e decide chi può entrare.",al={"cos'è il the stone watcher","chi è il watcher a uldum","identità del the stone watcher"}},{q="Perché il The Stone Watcher nega l'accesso?",a="Lo Stone Watcher ammette solo chi ha le Piastre di Uldum nel proprio set di dischi. Il tuo set non le include ancora.",al={"perché non posso entrare a uldum","piastre di uldum mancanti","accesso a uldum negato"}}},fp="17,183,26.264.0,25.593.1,21.356.2,38.113.0,38.116.0"}
P.entries["quest:296"] = {n="Ormer's Revenge",s="Ormer Trecciaferro cerca vendetta al Sito di Scavo di Whelgar. Crede che Sarltooth abbia guidato l'attacco dei raptor che ha massacrato gli scavatori nani e ti chiede di riportare uno dei suoi artigli come prova.",h="Ormer Trecciaferro cerca vendetta al Sito di Scavo di Whelgar.",kw={"lega degli esploratori","ormer trecciaferro","raptor","sarltooth","artiglio","paludi grigie","sito di scavo di whelgar"},ang={["class:Hunter"]="Come cacciatore, affronti uno dei predatori dominanti delle Paludi Grigie. Le tue abilità di tracciamento ti guidano sul crinale fino al capo branco.",["faction:Alliance"]="Come membro dell'Alleanza, aiuti a proteggere le spedizioni naniche negli Acquitrini Selvaggi e a mantenere intatti gli avamposti dell'Alleanza tra Forgiardente e le terre del nord.",["race:Dwarf"]="Come nano, onori i sudditi caduti di Re Magni vendicando la squadra della Lega degli Esploratori massacrata al Sito di Scavo di Whelgar."},sec={{t="Un colpo al capo branco",b="Dopo il massacro degli scavatori della Lega degli Esploratori al Sito di Scavo di Whelgar, Ormer Trecciaferro osservò i raptor dal suo crinale. Una bestia era più grande delle altre. Sarltooth si appollaiava sopra gli scavi, dove Ormer lo vide guidare il branco che scacciò i nani. Per Ormer, Sarltooth era più di una bestia selvatica. Credeva che avesse guidato l'attacco ai sudditi di Re Magni Barbabronzea."},{t="Giustizia nelle Paludi Grigie",b="Ormer esige la morte dei responsabili del massacro. Ti manda lungo gli alti sentieri sulle pareti dello scavo per uccidere Sarltooth. Riporta uno dei formidabili artigli del raptor e i lavoratori caduti saranno vendicati. Ormer vuole che gli Acquitrini Selvaggi sappiano che gli attacchi alle spedizioni naniche non resteranno impuniti."}},faq={{q="Chi è Sarltooth?",a="Sarltooth è un grosso raptor che guida il branco al Sito di Scavo di Whelgar, nelle Paludi Grigie. Ormer Trecciaferro crede che Sarltooth abbia diretto l'assalto che ha massacrato gli scavatori nani.",al={"cos'è sarltooth","chi è il boss raptor","lore di sarltooth"}},{q="Dove si trova Sarltooth?",a="Sarltooth si aggira su un sentiero sopraelevato lungo la parete occidentale, nell'angolo nord-occidentale del Sito di Scavo di Whelgar.",al={"trovare sarltooth","dove appare sarltooth","percorso di sarltooth"}},{q="Perché Ormer vuole Sarltooth morto invece di limitarsi a scacciarlo?",a="Ormer considera l'attacco dei raptor un crimine contro i sudditi di Re Magni. I lavoratori nani sono morti mentre svolgevano il loro lavoro e Ormer crede che solo la morte di Sarltooth possa rendere giustizia alla memoria dei caduti.",al={"motivo vendetta di ormer","perché uccidere sarltooth"}},{q="Quale prova richiede Ormer?",a="Ormer pretende uno degli artigli di Sarltooth come prova che il massiccio predatore è stato ucciso.",al={"prova di sarltooth","artiglio di sarltooth"}},{q="Chi sono state le vittime al sito di scavo?",a="Le vittime erano archeologi e lavoratori nani inviati dalla Lega degli Esploratori a riportare alla luce artefatti dei titani. I branchi di raptor li colsero di sorpresa e li massacrarono quando invasero lo scavo.",al={"chi è morto a whelgar","vittime sito di scavo"}},{q="Uccidere Sarltooth mette in sicurezza il sito di scavo?",a="Uccidere Sarltooth elimina la minaccia più letale del branco e dà una punizione per i caduti. I raptor continuano a strisciare tra le trincee, lasciando il sito pericoloso e in gran parte abbandonato.",al={"whelgar è al sicuro ora","ormer ha vinto"}}},fp="15,195,27.390.0,23.296.0,17.180.0,27.109.0,68.194.0,30.90.0,44.193.0,50.181.0"}
P.entries["quest:2962"] = {n="The Only Cure is More Green Glow",s="A Kharanos, Ozzie Valvotron cerca una cura per gli gnomi lebbrosi. Gli serve un campione puro di ricaduta proveniente dalle profondità di Gnomeregan.",h="A Kharanos, Ozzie Valvotron cerca una cura per gli gnomi lebbrosi.",kw={"gnogaine","gnomeregan","hall of gears","kharanos","gnomo lebbroso","ozzie valvotron","radiazione","ricaduta radioattiva"},ang={["faction:Alliance"]="Come membro dell'Alleanza, puoi aiutare a stabilizzare Dun Morogh e a riconquistare Gnomeregan imparando ad affrontare i pericoli letali che minacciano le porte di Forgiardente.",["profession:Engineering"]="Da ingegnere, sai che le radiazioni richiedono robuste schermature di piombo e strumenti precisi. Gnomeregan mostra il prezzo di un fallimento ingegneristico.",["race:Gnome"]="Da gnomo, porti con te il dolore per la tua patria perduta. Aiutare Ozzie a scoprire se le mutazioni possono essere annullate dà speranza di redimere i tuoi consanguinei caduti."},sec={{t="Un Campione Puro",b="I primi test di Ozzie Valvotron fuori da Gnomeregan non hanno dato risposte. I trogg di Dun Morogh trasportavano residui insufficienti e impuri. Ora, dal suo laboratorio a Kharanos, Ozzie cerca un campione fresco e concentrato dalle profondità della città. Spera che lo aiuti a trovare un rimedio per gli gnomi lebbrosi."},{t="Direttamente dal Rubinetto",b="Devi raccogliere Ricaduta Radioattiva ad Alta Potenza all'interno di Gnomeregan. Orrori irradiati, lurker e melme popolano le profondità inferiori intorno alla Hall of Gears e alla Clean Zone. Il loro liquame instabile va trasportato in una pesante fiala di piombo, e il lavoro è pericoloso. La ricaduta perde rapidamente potenza, quindi devi portarla al laboratorio di Ozzie a Kharanos in tempo."}},faq={{q="Perché Ozzie ha bisogno della ricaduta radioattiva?",a="Ozzie Valvotron cerca una cura per gli gnomi lebbrosi, il cui corpo e la cui mente furono rovinati dalla ricaduta liberata durante la caduta di Gnomeregan. Crede che un campione puro del veleno possa aiutare a invertirne gli effetti.",al={"ozzie valvotron cura","perché prendere la luminescenza verde","cura per i gnomi lebbrosi"}},{q="Dove trova il giocatore la ricaduta?",a="Puoi raccogliere ricaduta dagli orrori irradiati, dai lurker e dalle melme ancora vivi nelle profondità di Gnomeregan, soprattutto intorno alla Hall of Gears e oltre la Clean Zone.",al={"dove si trova la ricaduta radioattiva ad alta potenza","posizione ricaduta gnomeregan"}},{q="Perché i campioni dei trogg di superficie sono stati rifiutati?",a="I trogg fuori da Gnomeregan trasportavano una quantità insufficiente di contaminazione, e i loro campioni erano impuri. Non potevano fornire a Ozzie materiale affidabile per la sua ricerca di una cura.",al={"perché non i trogg","cosa c'era di sbagliato nella gnogaine"}},{q="Perché la ricaduta ha un limite di tempo?",a="La ricaduta è instabile e perde rapidamente potenza, anche in una fiala di piombo. Deve raggiungere il laboratorio di Ozzie a Kharanos prima che si deteriori.",al={"perché la ricaduta scade","durata della ricaduta"}},{q="Chi sono i gnomi lebbrosi che Ozzie spera di aiutare?",a="Gli gnomi lebbrosi erano cittadini di Gnomeregan, intrappolati all'interno quando le valvole di radiazione furono aperte per combattere i trogg. Sopravvissero, ma si ammalarono e persero la ragione, diventando ostili ai loro ex compagni.",al={"lore gnomi lebbrosi","cosa sono i gnomi lebbrosi"}},{q="Chi assegna questo compito?",a="Ozzie Valvotron è un ricercatore gnomo che vive a Kharanos, a Dun Morogh. Ti chiede di raccogliere ricaduta mentre cerca un rimedio ai danni causati dalla catastrofe di Gnomeregan.",al={"chi assegna la missione","posizione ozzie valvotron"}}},fx={a4e93100={q="A cosa serve la Ricaduta Radioattiva ad Alta Potenza?",a="Ozzie Valvotron ha bisogno della ricaduta concentrata per studiare le intense radiazioni che hanno avvolto Gnomeregan. Il suo obiettivo finale è trovare una cura per gli gnomi lebbrosi, i suoi fratelli trasformati, il cui corpo e la cui mente sono stati deformati dal disastro. Poiché i precedenti campioni di superficie prelevati dai trogg erranti si sono rivelati troppo deboli e contaminati per fornire risultati scientifici utili, gli occorrono radiazioni potenti e non diluite, prelevate direttamente dalle creature all'interno della città in rovina.",al={"a cosa serve la ricaduta radioattiva","uso della ricaduta ad alta potenza","scopo della ricaduta per ozzie"}},["089f8395"]={q="Quali creature devi cacciare a Gnomeregan?",a="Ti viene chiesto di raccogliere campioni dalle melme irradiate, dai predatori furtivi e dagli orrori che infestano Gnomeregan. Questi miserabili esseri melmosi e mutati si sono formati direttamente dopo la ricaduta tossica sprigionata durante la caduta della città, assorbendo enormi concentrazioni di scorie radioattive grezze. Poiché incarnano la ricaduta nel suo stato più puro e attivo, estrarne residui fornisce a Ozzie la potenza non diluita necessaria per le sue ricerche.",al={"cosa sono le melme irradiate","chi devo uccidere per la ricaduta","creature della ricaduta di gnomeregan"}}},fp="32,127,13.315.0,21.345.0,40.206.0,39.159.0,44.164.0,35.135.0,45.188.0,22.168.0"}
P.entries["quest:2969"] = {n="Freedom for All Creatures",s="Al campo dei Totem Truce, Kindal Treccialuna ti chiede di liberare i draghi fatati catturati. Né Kindal né Jer'kai sanno cosa abbia in mente il clan. Kindal verrà con te, mentre Jer'kai resterà indietro.",h="Al campo dei Totem Truce, Kindal Treccialuna ti chiede di liberare i draghi fatati catturati.",kw={"gabbia di bambù","elune","drago fatato","feralas","insediamento dei totem truce","jer'kai","kindal treccialuna"},sec={{t="Draghi nel recinto",b="Kindal Treccialuna definisce spregevole il clan dei Totem Truce per aver catturato i draghi fatati. Né Kindal né Jer'kai sanno cosa voglia il clan, solo che non ha buone intenzioni. Non sono abbastanza forti per farsi strada combattendo nel campo, così Kindal ti chiede di aiutarla a liberare i draghetti fatati. La Chiave della Gabbia apre il loro recinto e Kindal vuole che fuggano vivi. Porta con te amici forti."},{t="Postazione di vedetta di Kindal",b="Kindal ti aspetta su una sporgenza dietro l'Insediamento dei Totem Truce, sopra l'acqua. Un sentiero sale lungo la parete della scogliera e porta da lui. Kindal combatte al tuo fianco nel campo. Jer'kai resta indietro."},{t="In seguito",b="Una volta liberi i draghetti, Kindal ringrazia Elune. I draghi liberati potrebbero non restare tali, quindi Kindal e Jer'kai intendono portare la lotta ai Totem Truce. Kindal ti manda a parlare con Jer'kai."}},faq={{q="Chi sta catturando i draghi fatati?",a="Kindal Treccialuna dice che il clan dei Totem Truce sta catturando i draghi fatati. Kindal e Jer'kai non sanno cosa voglia il clan da loro.",al={"chi ha catturato i draghi fatati","chi ha i draghetti fatati","gabbie totem truce"}},{q="Dov'è Kindal Treccialuna?",a="Kindal Treccialuna ti aspetta su una sporgenza dietro l'Insediamento dei Totem Truce, sopra l'acqua. Vai a sinistra dell'insediamento per trovare, dietro un albero, un sentiero che sale lungo la parete della scogliera.",al={"dov'è kindal","posizione di kindal treccialuna","come raggiungere kindal treccialuna"}},{q="Jer'kai viene insieme?",a="No. Jer'kai resta indietro, mentre Kindal viene con te.",al={"jerkai aiuta","coinvolgimento di jerkai"}},{q="Cosa mi serve per liberare i draghetti fatati?",a="La Chiave della Gabbia, che Kindal ti consegna, apre il recinto nel campo dei Totem Truce. Kindal ti chiede di portare amici forti.",al={"chiave della gabbia","come liberare i draghetti fatati"}},{q="Cosa segue questa missione?",a="La missione successiva nella catena è Doling Justice.",al={"missione successiva a freedom for all creatures","cosa fare dopo aver salvato i draghetti fatati"}}},fp="25,205,18.379.0,16.179.0,9.200.1,36.136.0,27.163.0,24.53.0,42.122.0,24.39.0"}
P.entries["quest:297"] = {n="Gathering Idols",s="In un sito di scavi, i trogg stringono gli idoli scolpiti che cerca Magmar Viltaglio. Le reliquie li hanno spinti in una frenesia violenta.",h="In un sito di scavi, i trogg stringono gli idoli scolpiti che cerca Magmar Viltaglio.",kw={"forsennato","idoli di pietra scolpita","scavi","gathering idols","magmar viltaglio","rovine","trogg"},ang={["faction:Alliance"]="Come avventuriero dell'Alleanza, aiuti le spedizioni dei nani a mettere al sicuro reliquie pericolose prima che i feroci trogg causino altri danni.",["race:Dwarf"]="Come nano, ti unisci agli scavatori in cerca di antichi artefatti tra le rovine infestate dai trogg e dei segreti che custodiscono."},sec={{t="Le Reliquie Riportate alla Luce",b="Poco prima che feroci trogg emergessero e invadessero il sito di scavi, i ricercatori avevano scoperto un grande deposito di strani idoli di pietra scolpita. L'attacco costrinse la spedizione ad abbandonare le rovine prima che potesse iniziare qualsiasi studio formale. Ora i trogg stringono le reliquie e si aggirano per il sito, impedendo un ritorno pacifico."},{t="Una Frenesia Selvaggia",b="I trogg sembrano profondamente influenzati dagli idoli, ben oltre il semplice desiderio di impossessarsene. Le loro strane incisioni esercitano un potere inquietante che spinge le creature a una rabbia incontrollabile. Magmar Viltaglio vuole studiare gli idoli in sicurezza e placare la frenesia che attanaglia la zona, perciò cerca di sottrarli ai trogg."}},faq={{q="Chi è Magmar Viltaglio?",a="Magmar Viltaglio è uno scavatore che cerca di recuperare idoli di pietra scolpita da un sito di scavi invaso dai trogg.",al={"chi è magmar viltaglio","datore di missione","magmar"}},{q="Cosa sono gli idoli di pietra scolpita?",a="Gli idoli sono misteriose reliquie di pietra scolpita, riportate alla luce in un sito di scavi. Il loro potere inquietante spinge i trogg vicini a una frenesia furiosa.",al={"cosa sono gli idoli di pietra scolpita","idoli strani","idoli scavati"}},{q="Perché gli idoli fanno impazzire i trogg?",a="Gli idoli esercitano sui trogg un'influenza strana e inspiegabile. Quando le creature ne entrano in possesso, una furia selvaggia le manda fuori controllo.",al={"perché i trogg sono forsennati","gli idoli fanno impazzire i trogg","rabbia dei trogg"}},{q="Perché Magmar Viltaglio vuole che gli idoli vengano raccolti?",a="Magmar Viltaglio vuole recuperare gli idoli in sicurezza per studiarne le origini e le proprietà, e sottrarre le reliquie instabili ai trogg.",al={"perché prendere gli idoli","scopo di gathering idols","studio di magmar"}},{q="Cosa è successo al sito di scavi?",a="I trogg emersero all'improvviso dal sito di scavi poco dopo la scoperta degli idoli. Scacciarono gli scavatori dalle rovine.",al={"chi è emerso nel sito","invasione dei trogg","scavi invasi"}},{q="Dove si trovano gli idoli?",a="I trogg trasportano gli idoli di pietra scolpita nel sito di scavi dove le reliquie furono riportate alla luce.",al={"dove trovare gli idoli","chi ha gli idoli","posizione degli idoli di pietra scolpita"}}},fp="15,126,20.301.0,15.306.0,22.108.0,32.144.0,44.124.0,49.142.0,37.132.0,26.97.0"}
P.entries["quest:2970"] = {n="Doling Justice",s="A Feralas, Jer'kai Treccialuna e Kindal sono pronti a reagire dopo il salvataggio dei draghi fatati. Jer'kai ti chiede di assottigliare le file dei Totem Truce, poi di tornare da lui.",h="A Feralas, Jer'kai Treccialuna e Kindal sono pronti a reagire dopo il salvataggio dei draghi fatati.",kw={"doling justice","feralas","totem truce","jer'kai treccialuna","kindal treccialuna","naturalista","incursore","sciamano"},sec={{t="Portare la battaglia ai Totem Truce",b="Dopo il salvataggio dei draghi fatati, Jer'kai Treccialuna e Kindal sono pronti ad attaccare i Totem Truce. Insieme possono assottigliare le file dei tauren senza correre molti rischi, e accolgono volentieri il tuo aiuto.\n\nHai visto l'accampamento sottostante, e altri si trovano più a est. Scegli le tue tattiche contro Naturalisti, Incursori e Sciamani Totem Truce, poi torna da Jer'kai."}},faq={{q="Chi assegna Doling Justice?",a="A Feralas, Jer'kai Treccialuna chiede il tuo aiuto dopo che Kindal ha spiegato i loro piani in seguito al salvataggio dei draghi fatati.",al={"chi assegna doling justice","datore di missione doling justice","jer'kai treccialuna"}},{q="Quali Totem Truce sono presi di mira?",a="I bersagli sono i Naturalisti, gli Incursori e gli Sciamani Totem Truce del clan Totem Truce.",al={"quali nemici devo uccidere","bersagli di doling justice","uccisioni totem truce"}},{q="Dove si trovano gli accampamenti dei Totem Truce?",a="Un accampamento Totem Truce è proprio sotto Jer'kai, in vista, e lei dice che altri si trovano a est.",al={"dove si trovano i totem truce","posizione accampamento totem truce","dove devo andare"}},{q="Cosa viene prima di Doling Justice?",a="Freedom for All Creatures viene prima. Lì hai liberato i draghi fatati dall'accampamento dei Totem Truce.",al={"missione precedente","prerequisito doling justice","passaggio precedente"}}},fp="14,166,33.338.0,25.127.0,29.104.0,30.89.0,33.99.0"}
P.entries["quest:2972"] = {n="Doling Justice",s="A Feralas, Jer'kai Treccialuna ti affida un anello da portare a Darnassus alla Somma Sacerdotessa Tyrande Soffiabrezza. Le mostrerà che Jer'kai e Kindal stanno bene e darà credito al tuo racconto.",h="A Feralas, Jer'kai Treccialuna ti affida un anello da portare a Darnassus alla Somma Sacerdotessa Tyrande...",kw={"darnassus","feralas","jer'kai treccialuna","kindal treccialuna","anello con sigillo","teldrassil","temple of the moon","tyrande soffiabrezza"},sec={{t="Un anello per la Somma Sacerdotessa",b="Jer'kai Treccialuna e Kindal hanno ben poco da offrire a Feralas, ma vogliono che tu sappia quanto ti sono grati. Jer'kai ti affida un anello con sigillo per la Somma Sacerdotessa Tyrande Soffiabrezza, al Temple of the Moon di Darnassus. L'anello mostrerà a Tyrande che i due stanno bene e darà credito al tuo racconto."},{t="La risposta di Tyrande",b="La Somma Sacerdotessa Tyrande Soffiabrezza è lieta che tu abbia aiutato la stirpe dei draghi e una delle sue sacerdotesse. Dice che Jer'kai ha fatto bene a inviarti e promette che l'anello sarà restituito a Jer'kai. Presto degli esploratori si dirigeranno verso Feralas e tra le questioni di cui si occuperanno ci sarà anche l'anello."}},faq={{q="Chi ti consegna l'anello con sigillo?",a="A Feralas, Jer'kai Treccialuna ti affida l'anello con sigillo, insieme ai ringraziamenti di Kindal.",al={"chi inizia questa missione","datore di missione"}},{q="Dove va portato l'anello con sigillo?",a="L'anello va consegnato alla Somma Sacerdotessa Tyrande Soffiabrezza, al Temple of the Moon di Darnassus.",al={"dove devo portare l'anello","luogo di consegna","chi riceve l'anello con sigillo di jerkai"}},{q="Perché Jer'kai ti consegna l'anello?",a="Jer'kai e Kindal hanno ben poco da offrire nella natura selvaggia. L'anello mostrerà a Tyrande che stanno bene e darà credito al tuo racconto.",al={"scopo dell'anello con sigillo","perché l'anello con sigillo di jerkai"}},{q="Cosa segue in questa serie di missioni?",a="La catena prosegue con An Orphan Looking For a Home.",al={"prossima missione","dove andare dopo"}}},fp="14,177,29.298.0,16.283.1,26.89.0,30.91.0,35.121.0,29.54.0"}
P.entries["quest:2973"] = {n="A New Cloak's Sheen",s="All'Accampamento Mojache, Krueg Fendicranio ti chiede di raccogliere ali per il mantello di Korrin. È giunto a Feralas con compagni mandati dai loro padroni a Orgrimmar.",h="All'Accampamento Mojache, Krueg Fendicranio ti chiede di raccogliere ali per il mantello di Korrin.",kw={"accampamento mojache","mantello","drago fatato","feralas","ali iridescenti","korrin","krueg fendicranio"},sec={{t="Un mantello per Korrin",b="Krueg Fendicranio è giunto a Feralas con compagni mandati dai loro padroni a Orgrimmar. Korrin, la sua compagna di vita, ama i vestiti nuovi, così progetta un mantello adornato con delicate ali di drago fatato. I draghi fatati che cerca vivono a ovest dell'Accampamento Mojache. Porta a Krueg dieci Ali di Drago Fatato Iridescenti."},{t="L'avvertimento di Krueg",b="Krueg avverte che i draghi fatati diventano pericolosi se provocati. I vicini elfi della notte tendono a rintanarsi nelle foreste, quindi fai ancora più attenzione nei loro paraggi."}},faq={{q="Chi è Krueg Fendicranio?",a="Krueg Fendicranio si trova all'Accampamento Mojache. È giunto a Feralas con compagni mandati dai loro padroni a Orgrimmar.",al={"chi è krueg","storia di krueg fendicranio","krueg a feralas"}},{q="Perché Krueg vuole le ali di drago fatato?",a="Krueg progetta un mantello adornato con ali di drago fatato per Korrin, la sua compagna di vita, che ama i vestiti nuovi.",al={"perché servono le ali di drago fatato","scopo delle ali di drago fatato","cosa sta creando krueg"}},{q="Dove si trovano i draghi fatati?",a="I draghi fatati vivono a ovest dell'Accampamento Mojache.",al={"dove trovare i draghi fatati","posizione dei draghi fatati","dove sono i draghi fatati a feralas"}},{q="Di quali pericoli avverte Krueg?",a="I draghi fatati, che diventano pericolosi se provocati, e i vicini elfi della notte, che tendono a rintanarsi nelle foreste e richiedono ancora più cautela.",al={"avvertimenti di krueg","minacce nella foresta di feralas"}}},fp="19,154,18.293.0,15.145.0,27.110.0,40.101.0,37.45.0,35.146.0"}
P.entries["quest:2974"] = {n="A Grim Discovery",s="All'Accampamento Mojache, Krueg Fendicranio scopre che hai incontrato dei tauren a Feralas e li chiama Totem Truce. Belgrom ha messo una taglia su di loro e Krueg ti chiede venti corna.",h="All'Accampamento Mojache, Krueg Fendicranio scopre che hai incontrato dei tauren a Feralas e li chiama Totem...",kw={"belgrom","accampamento mojache","feralas","totem truce","corna","krueg fendicranio"},sec={{t="Notizie sui Totem Truce",b="Racconti a Krueg Fendicranio dei tauren che hai incontrato a Feralas. Li chiama clan Totem Truce. Belgrom, uno dei padroni di Krueg, ha messo una taglia su di loro e si interessa molto alla loro gente. Krueg ti avverte che i Totem Truce sono malvagi e non vanno sottovalutati. Vuole che gli porti venti corna prima che possano radere al suolo villaggi o sottrarre terre."},{t="Corna consegnate",b="Krueg giudica buone le corna e dice che lo hai aiutato due volte. Belgrom ne verrà a conoscenza non appena Krueg sarà tornato a Orgrimmar."}},faq={{q="Chi assegna A Grim Discovery?",a="Krueg Fendicranio ti affida l'incarico all'Accampamento Mojache, dopo che gli racconti di aver incontrato dei tauren a Feralas.",al={"chi assegna grim discovery","missione krueg fendicranio","datore missione grim discovery"}},{q="Perché Krueg vuole le corna dei Totem Truce?",a="Krueg dice che i Totem Truce sono malvagi e vuole colpirli prima che possano radere al suolo villaggi o sottrarre terre. Anche Belgrom, uno dei padroni di Krueg a Orgrimmar, ha messo una taglia su di loro.",al={"perché uccidere i totem truce","minaccia totem truce feralas","perché corna totem truce"}},{q="Chi è Belgrom?",a="Krueg dice che Belgrom è uno dei suoi padroni. Belgrom è interessato ai Totem Truce e ha messo una taglia su di loro.",al={"belgrom orgrimmar","chi è belgrom"}},{q="Quante corna vuole Krueg?",a="Krueg vuole che gli porti venti corna dei Totem Truce all'Accampamento Mojache. Se riesci, ne vuole mucchi.",al={"conteggio corna totem truce","quante corna totem truce"}},{q="Cosa segue A Grim Discovery?",a="La catena prosegue con A Grim Discovery, parte due.",al={"prossima missione grim discovery","catena grim discovery"}}},fp="16,170,21.358.0,19.126.1,27.97.0,36.175.0,15.108.0,31.113.0,30.52.0"}
P.entries["quest:2975"] = {n="The Ogres of Feralas",s="All'Accampamento Mojache, Rok Orhan chiede di respingere i Gordunni. Il loro avamposto è a nord, risalendo il fiume.",h="All'Accampamento Mojache, Rok Orhan chiede di respingere i Gordunni.",kw={"bruto","accampamento mojache","feralas","gordunni","ogre","mago ogre","rok orhan"},sec={{t="Il Marchio dei Gordunni",b="Rok Orhan dice che gli ogre Gordunni deturpano la terra attorno all'Accampamento Mojache. Respingi la tribù prima che si addentri ulteriormente a Feralas. Segui il fiume verso nord per trovare il loro avamposto. Lì, uccidi dieci Ogre Gordunni, dieci Magi Ogre Gordunni e cinque Bruti Gordunni per mostrare alla tribù che non è la benvenuta."}},faq={{q="Chi vuole che gli ogre Gordunni vengano respinti?",a="Rok Orhan, all'Accampamento Mojache, vuole che gli ogre Gordunni vengano respinti.",al={"chi assegna la missione","datore di missione","rok orhan"}},{q="Perché Rok Orhan vuole che i Gordunni vengano respinti?",a="Rok Orhan dice che i Gordunni deturpano la terra e vanno fermati prima che si diffondano ulteriormente a Feralas.",al={"perché uccidere gli ogre","motivo dei gordunni","perché combattere i gordunni"}},{q="Dov'è l'avamposto dei Gordunni?",a="Segui il fiume verso nord per trovare l'avamposto dei Gordunni.",al={"posizione avamposto ogre","dove sono gli ogre","posizione gordunni feralas"}},{q="Quali Gordunni devono essere uccisi?",a="Uccidi dieci Ogre Gordunni, dieci Magi Ogre Gordunni e cinque Bruti Gordunni.",al={"quanti ogre","conteggio uccisioni gordunni"}},{q="Cosa segue questa missione?",a="La catena prosegue con The Ogres of Feralas due.",al={"prossima missione the ogres of feralas","catena the ogres of feralas"}}},fp="20,114,24.292.0,41.63.0,49.102.0,30.52.0,29.73.0,24.50.0"}
